--
-- Name: _sales_pump_order_owned_by_session(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sales_pump_order_owned_by_session(p_admin_user text, p_session_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  me RECORD;
  jwt_email TEXT;
  auth_email TEXT;
  a text;
BEGIN
  IF p_session_user_id IS NULL OR p_admin_user IS NULL OR btrim(p_admin_user) = '' THEN
    RETURN false;
  END IF;
  SELECT username, email INTO me FROM us_users WHERE id = p_session_user_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT u.email INTO auth_email FROM auth.users u WHERE u.id = p_session_user_id;
  jwt_email := auth.jwt() ->> 'email';
  a := lower(btrim(p_admin_user));
  RETURN length(a) > 0 AND (
    (length(btrim(coalesce(me.username, ''))) > 0 AND a = lower(btrim(me.username)))
    OR (length(btrim(coalesce(me.email, ''))) > 0 AND a = lower(btrim(me.email)))
    OR (length(btrim(coalesce(jwt_email, ''))) > 0 AND a = lower(btrim(jwt_email)))
    OR (length(btrim(coalesce(auth_email, ''))) > 0 AND a = lower(btrim(auth_email)))
  );
END;
$$;


--
-- Name: ac_ecommerce_existing_order_nos(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_existing_order_nos(p_channel_id uuid, p_order_nos text[]) RETURNS TABLE(order_no text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT trim(both FROM sl.order_no)::text AS order_no
  FROM public.ac_ecommerce_sale_lines sl
  INNER JOIN public.ac_ecommerce_import_batches b ON b.id = sl.batch_id
  WHERE b.channel_id = p_channel_id
    AND sl.order_no IS NOT NULL
    AND trim(both FROM sl.order_no) <> ''
    AND trim(both FROM sl.order_no) IN (
      SELECT trim(both FROM x)
      FROM unnest(p_order_nos) AS u(x)
      WHERE trim(both FROM x) <> ''
    );
$$;


--
-- Name: FUNCTION ac_ecommerce_existing_order_nos(p_channel_id uuid, p_order_nos text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ac_ecommerce_existing_order_nos(p_channel_id uuid, p_order_nos text[]) IS 'คืนเลขคำสั่งซื้อที่มีใน ac_ecommerce_sale_lines แล้วสำหรับ channel_id ที่ระบุ และอยู่ในรายการ p_order_nos (เปรียบเทียบแบบ trim)';


--
-- Name: ac_ecommerce_marketplace_bill_page(uuid, text, timestamp with time zone, timestamp with time zone, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_marketplace_bill_page(p_channel_id uuid, p_date_basis text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search text DEFAULT NULL::text, p_status_filter text DEFAULT 'all'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 51) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH filtered AS MATERIALIZED (
    SELECT
      r.*,
      CASE p_date_basis
        WHEN 'completed_at' THEN COALESCE(r.completed_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'settled_at' THEN COALESCE(r.settled_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'wallet_received_at' THEN COALESCE(r.wallet_received_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'billed_at' THEN COALESCE(r.marketplace_billed_at, r.ordered_at)
        ELSE COALESCE(r.ordered_at, r.marketplace_billed_at)
      END AS sort_date
    FROM public.ac_v_ecommerce_marketplace_bill_reconciliation r
    WHERE auth.uid() IS NOT NULL
      AND r.channel_id = p_channel_id
      AND CASE p_date_basis
        WHEN 'completed_at' THEN COALESCE(r.completed_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'settled_at' THEN COALESCE(r.settled_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'wallet_received_at' THEN COALESCE(r.wallet_received_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'billed_at' THEN COALESCE(r.marketplace_billed_at, r.ordered_at)
        ELSE COALESCE(r.ordered_at, r.marketplace_billed_at)
      END BETWEEN p_date_from AND p_date_to
      AND (
        nullif(btrim(p_search), '') IS NULL
        OR r.order_no ILIKE '%' || btrim(p_search) || '%'
        OR r.erp_bill_no ILIKE '%' || btrim(p_search) || '%'
      )
      AND (
        p_status_filter = 'all'
        OR (p_status_filter = 'issues' AND r.reconciliation_status IN ('not_found_order', 'waiting_delivery', 'waiting_wallet', 'waiting_settlement', 'amount_mismatch'))
        OR (p_status_filter = 'paid' AND r.reconciliation_status IN ('paid', 'paid_zero'))
        OR (p_status_filter NOT IN ('all', 'issues', 'paid') AND r.reconciliation_status = p_status_filter)
      )
    ORDER BY sort_date DESC NULLS LAST, r.order_no DESC
    LIMIT least(greatest(p_limit, 1), 101)
    OFFSET greatest(p_offset, 0)
  )
  SELECT COALESCE(
    jsonb_agg(to_jsonb(filtered) - 'sort_date' ORDER BY sort_date DESC NULLS LAST, order_no DESC),
    '[]'::jsonb
  )
  FROM filtered;
$$;


--
-- Name: ac_ecommerce_marketplace_bill_page_v2(uuid, text, timestamp with time zone, timestamp with time zone, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_marketplace_bill_page_v2(p_channel_id uuid, p_date_basis text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search text DEFAULT NULL::text, p_status_filter text DEFAULT 'all'::text, p_aging text DEFAULT 'all'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 51) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH prepared AS MATERIALIZED (
    SELECT
      r.*,
      CASE p_date_basis
        WHEN 'completed_at' THEN COALESCE(r.completed_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'settled_at' THEN COALESCE(r.settled_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'wallet_received_at' THEN COALESCE(r.wallet_received_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'billed_at' THEN COALESCE(r.marketplace_billed_at, r.ordered_at)
        ELSE COALESCE(r.ordered_at, r.marketplace_billed_at)
      END AS sort_date,
      GREATEST(
        CURRENT_DATE - COALESCE(r.marketplace_billed_at, r.ordered_at)::date,
        0
      ) AS pending_age_days
    FROM public.ac_v_ecommerce_marketplace_bill_reconciliation r
    WHERE auth.uid() IS NOT NULL
      AND r.channel_id = p_channel_id
      AND CASE p_date_basis
        WHEN 'completed_at' THEN COALESCE(r.completed_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'settled_at' THEN COALESCE(r.settled_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'wallet_received_at' THEN COALESCE(r.wallet_received_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'billed_at' THEN COALESCE(r.marketplace_billed_at, r.ordered_at)
        ELSE COALESCE(r.ordered_at, r.marketplace_billed_at)
      END BETWEEN p_date_from AND p_date_to
      AND (
        nullif(btrim(p_search), '') IS NULL
        OR r.order_no ILIKE '%' || btrim(p_search) || '%'
        OR r.erp_bill_no ILIKE '%' || btrim(p_search) || '%'
      )
      AND (
        p_status_filter = 'all'
        OR (p_status_filter = 'issues' AND r.reconciliation_status IN ('not_found_order', 'waiting_delivery', 'waiting_wallet', 'waiting_settlement', 'amount_mismatch'))
        OR (p_status_filter = 'paid' AND r.reconciliation_status IN ('paid', 'paid_zero'))
        OR (p_status_filter = 'delivered' AND r.delivery_status = 'delivered')
        OR (p_status_filter = 'income_found' AND r.income_matched)
        OR (p_status_filter = 'balance_found' AND r.balance_matched)
        OR (p_status_filter = 'cancelled_returned' AND r.reconciliation_status IN ('cancelled', 'returned', 'parcel_returned'))
        OR (p_status_filter NOT IN ('all', 'issues', 'paid', 'delivered', 'income_found', 'balance_found', 'cancelled_returned') AND r.reconciliation_status = p_status_filter)
      )
  ), filtered AS (
    SELECT *
    FROM prepared
    WHERE p_aging = 'all'
       OR (p_aging = 'within_7' AND NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days <= 7)
       OR (p_aging = 'days_8_14' AND NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days BETWEEN 8 AND 14)
       OR (p_aging = 'over_14' AND NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days > 14)
    ORDER BY sort_date DESC NULLS LAST, order_no DESC
    LIMIT least(greatest(p_limit, 1), 101)
    OFFSET greatest(p_offset, 0)
  )
  SELECT COALESCE(
    jsonb_agg(to_jsonb(filtered) - 'sort_date' ORDER BY sort_date DESC NULLS LAST, order_no DESC),
    '[]'::jsonb
  )
  FROM filtered;
$$;


--
-- Name: ac_ecommerce_marketplace_bill_summary(uuid, text, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_marketplace_bill_summary(p_channel_id uuid, p_date_basis text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search text DEFAULT NULL::text, p_status_filter text DEFAULT 'all'::text) RETURNS TABLE(order_count bigint, order_match_count bigint, income_match_count bigint, balance_match_count bigint, delivered_count bigint, cancelled_count bigint, shipping_count bigint, paid_count bigint, paid_zero_count bigint, waiting_settlement_count bigint, waiting_wallet_count bigint, mismatch_count bigint, missing_order_count bigint, issue_count bigint, sales_total numeric, fee_total numeric, payout_total numeric, wallet_total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT r.*
    FROM public.ac_v_ecommerce_marketplace_bill_reconciliation r
    WHERE auth.uid() IS NOT NULL
      AND r.channel_id = p_channel_id
      AND CASE p_date_basis
        WHEN 'completed_at' THEN COALESCE(r.completed_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'settled_at' THEN COALESCE(r.settled_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'wallet_received_at' THEN COALESCE(r.wallet_received_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'billed_at' THEN COALESCE(r.marketplace_billed_at, r.ordered_at)
        ELSE COALESCE(r.ordered_at, r.marketplace_billed_at)
      END BETWEEN p_date_from AND p_date_to
      AND (
        nullif(btrim(p_search), '') IS NULL
        OR r.order_no ILIKE '%' || btrim(p_search) || '%'
        OR r.erp_bill_no ILIKE '%' || btrim(p_search) || '%'
      )
      AND (
        p_status_filter = 'all'
        OR (p_status_filter = 'issues' AND r.reconciliation_status IN ('not_found_order', 'waiting_delivery', 'waiting_wallet', 'waiting_settlement', 'amount_mismatch'))
        OR (p_status_filter = 'paid' AND r.reconciliation_status IN ('paid', 'paid_zero'))
        OR (p_status_filter NOT IN ('all', 'issues', 'paid') AND r.reconciliation_status = p_status_filter)
      )
  )
  SELECT
    count(*) AS order_count,
    count(*) FILTER (WHERE order_matched) AS order_match_count,
    count(*) FILTER (WHERE income_matched) AS income_match_count,
    count(*) FILTER (WHERE balance_matched) AS balance_match_count,
    count(*) FILTER (WHERE delivery_status = 'delivered') AS delivered_count,
    count(*) FILTER (WHERE delivery_status = 'cancelled') AS cancelled_count,
    count(*) FILTER (WHERE delivery_status = 'shipping') AS shipping_count,
    count(*) FILTER (WHERE reconciliation_status = 'paid') AS paid_count,
    count(*) FILTER (WHERE reconciliation_status = 'paid_zero') AS paid_zero_count,
    count(*) FILTER (WHERE reconciliation_status = 'waiting_settlement') AS waiting_settlement_count,
    count(*) FILTER (WHERE reconciliation_status = 'waiting_wallet') AS waiting_wallet_count,
    count(*) FILTER (WHERE reconciliation_status = 'amount_mismatch') AS mismatch_count,
    count(*) FILTER (WHERE NOT order_matched) AS missing_order_count,
    count(*) FILTER (WHERE reconciliation_status IN ('not_found_order', 'waiting_delivery', 'waiting_wallet', 'waiting_settlement', 'amount_mismatch')) AS issue_count,
    COALESCE(sum(COALESCE(gross_sales, marketplace_order_total, erp_order_total)), 0) AS sales_total,
    COALESCE(sum(platform_fee_total), 0) AS fee_total,
    COALESCE(sum(payout_amount), 0) AS payout_total,
    COALESCE(sum(wallet_amount), 0) AS wallet_total
  FROM filtered;
$$;


--
-- Name: ac_ecommerce_marketplace_bill_summary_v2(uuid, text, timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_marketplace_bill_summary_v2(p_channel_id uuid, p_date_basis text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search text DEFAULT NULL::text, p_status_filter text DEFAULT 'all'::text, p_aging text DEFAULT 'all'::text) RETURNS TABLE(order_count bigint, order_match_count bigint, income_match_count bigint, balance_match_count bigint, delivered_count bigint, cancelled_count bigint, returned_count bigint, shipping_count bigint, paid_count bigint, paid_zero_count bigint, waiting_settlement_count bigint, waiting_wallet_count bigint, mismatch_count bigint, missing_order_count bigint, issue_count bigint, within_cycle_count bigint, overdue_cycle_count bigint, overdue_two_cycles_count bigint, sales_total numeric, delivered_total numeric, fee_total numeric, payout_total numeric, wallet_total numeric, within_cycle_total numeric, overdue_cycle_total numeric, overdue_two_cycles_total numeric, paid_total numeric, mismatch_total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH prepared AS (
    SELECT
      r.*,
      GREATEST(
        CURRENT_DATE - COALESCE(r.marketplace_billed_at, r.ordered_at)::date,
        0
      ) AS pending_age_days,
      COALESCE(r.payout_amount, r.gross_sales, r.order_total, 0) AS expected_amount
    FROM public.ac_v_ecommerce_marketplace_bill_reconciliation r
    WHERE auth.uid() IS NOT NULL
      AND r.channel_id = p_channel_id
      AND CASE p_date_basis
        WHEN 'completed_at' THEN COALESCE(r.completed_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'settled_at' THEN COALESCE(r.settled_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'wallet_received_at' THEN COALESCE(r.wallet_received_at, r.marketplace_billed_at, r.ordered_at)
        WHEN 'billed_at' THEN COALESCE(r.marketplace_billed_at, r.ordered_at)
        ELSE COALESCE(r.ordered_at, r.marketplace_billed_at)
      END BETWEEN p_date_from AND p_date_to
      AND (
        nullif(btrim(p_search), '') IS NULL
        OR r.order_no ILIKE '%' || btrim(p_search) || '%'
        OR r.erp_bill_no ILIKE '%' || btrim(p_search) || '%'
      )
      AND (
        p_status_filter = 'all'
        OR (p_status_filter = 'issues' AND r.reconciliation_status IN ('not_found_order', 'waiting_delivery', 'waiting_wallet', 'waiting_settlement', 'amount_mismatch'))
        OR (p_status_filter = 'paid' AND r.reconciliation_status IN ('paid', 'paid_zero'))
        OR (p_status_filter = 'delivered' AND r.delivery_status = 'delivered')
        OR (p_status_filter = 'income_found' AND r.income_matched)
        OR (p_status_filter = 'balance_found' AND r.balance_matched)
        OR (p_status_filter = 'cancelled_returned' AND r.reconciliation_status IN ('cancelled', 'returned', 'parcel_returned'))
        OR (p_status_filter NOT IN ('all', 'issues', 'paid', 'delivered', 'income_found', 'balance_found', 'cancelled_returned') AND r.reconciliation_status = p_status_filter)
      )
  ), filtered AS (
    SELECT *
    FROM prepared
    WHERE p_aging = 'all'
       OR (p_aging = 'within_7' AND NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days <= 7)
       OR (p_aging = 'days_8_14' AND NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days BETWEEN 8 AND 14)
       OR (p_aging = 'over_14' AND NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days > 14)
  )
  SELECT
    count(*) AS order_count,
    count(*) FILTER (WHERE order_matched) AS order_match_count,
    count(*) FILTER (WHERE income_matched) AS income_match_count,
    count(*) FILTER (WHERE balance_matched) AS balance_match_count,
    count(*) FILTER (WHERE delivery_status = 'delivered') AS delivered_count,
    count(*) FILTER (WHERE reconciliation_status = 'cancelled') AS cancelled_count,
    count(*) FILTER (WHERE reconciliation_status IN ('returned', 'parcel_returned')) AS returned_count,
    count(*) FILTER (WHERE delivery_status = 'shipping') AS shipping_count,
    count(*) FILTER (WHERE reconciliation_status = 'paid') AS paid_count,
    count(*) FILTER (WHERE reconciliation_status = 'paid_zero') AS paid_zero_count,
    count(*) FILTER (WHERE reconciliation_status = 'waiting_settlement') AS waiting_settlement_count,
    count(*) FILTER (WHERE reconciliation_status = 'waiting_wallet') AS waiting_wallet_count,
    count(*) FILTER (WHERE reconciliation_status = 'amount_mismatch') AS mismatch_count,
    count(*) FILTER (WHERE NOT order_matched) AS missing_order_count,
    count(*) FILTER (WHERE reconciliation_status IN ('not_found_order', 'waiting_delivery', 'waiting_wallet', 'waiting_settlement', 'amount_mismatch')) AS issue_count,
    count(*) FILTER (WHERE NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days <= 7) AS within_cycle_count,
    count(*) FILTER (WHERE NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days BETWEEN 8 AND 14) AS overdue_cycle_count,
    count(*) FILTER (WHERE NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days > 14) AS overdue_two_cycles_count,
    COALESCE(sum(COALESCE(gross_sales, marketplace_order_total, erp_order_total)), 0) AS sales_total,
    COALESCE(sum(COALESCE(gross_sales, order_total)) FILTER (WHERE delivery_status = 'delivered'), 0) AS delivered_total,
    COALESCE(sum(platform_fee_total), 0) AS fee_total,
    COALESCE(sum(payout_amount), 0) AS payout_total,
    COALESCE(sum(wallet_amount), 0) AS wallet_total,
    COALESCE(sum(expected_amount) FILTER (WHERE NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days <= 7), 0) AS within_cycle_total,
    COALESCE(sum(expected_amount) FILTER (WHERE NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days BETWEEN 8 AND 14), 0) AS overdue_cycle_total,
    COALESCE(sum(expected_amount) FILTER (WHERE NOT balance_matched AND reconciliation_status NOT IN ('cancelled', 'returned', 'parcel_returned', 'paid_zero') AND pending_age_days > 14), 0) AS overdue_two_cycles_total,
    COALESCE(sum(wallet_amount) FILTER (WHERE reconciliation_status IN ('paid', 'paid_zero')), 0) AS paid_total,
    COALESCE(sum(ABS(payout_variance)) FILTER (WHERE reconciliation_status = 'amount_mismatch'), 0) AS mismatch_total
  FROM filtered;
$$;


--
-- Name: ac_ecommerce_reconciliation_page(uuid, text, timestamp with time zone, timestamp with time zone, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_reconciliation_page(p_channel_id uuid, p_date_basis text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search text DEFAULT NULL::text, p_status_filter text DEFAULT 'all'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 51) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH page_rows AS MATERIALIZED (
    SELECT r.*
    FROM public.ac_v_ecommerce_order_reconciliation_core r
    WHERE r.channel_id = p_channel_id
      AND CASE p_date_basis
        WHEN 'settled_at' THEN r.settled_at
        WHEN 'wallet_received_at' THEN r.wallet_received_at
        ELSE r.ordered_at
      END >= p_date_from
      AND CASE p_date_basis
        WHEN 'settled_at' THEN r.settled_at
        WHEN 'wallet_received_at' THEN r.wallet_received_at
        ELSE r.ordered_at
      END <= p_date_to
      AND (nullif(btrim(p_search), '') IS NULL OR r.order_no ILIKE '%' || btrim(p_search) || '%')
      AND (
        p_status_filter = 'all'
        OR (p_status_filter = 'issues' AND r.reconciliation_status IN ('waiting_wallet', 'waiting_settlement', 'amount_mismatch', 'needs_review'))
        OR (p_status_filter NOT IN ('all', 'issues') AND r.reconciliation_status = p_status_filter)
      )
    ORDER BY
      CASE p_date_basis
        WHEN 'settled_at' THEN r.settled_at
        WHEN 'wallet_received_at' THEN r.wallet_received_at
        ELSE r.ordered_at
      END DESC NULLS LAST,
      r.order_no DESC
    LIMIT least(greatest(p_limit, 1), 101)
    OFFSET greatest(p_offset, 0)
  ), enriched AS (
    SELECT
      to_jsonb(p) || jsonb_build_object(
        'erp_order_id', erp.id,
        'erp_bill_no', erp.bill_no,
        'erp_order_total', erp.total_amount
      ) AS row_data,
      CASE p_date_basis
        WHEN 'settled_at' THEN p.settled_at
        WHEN 'wallet_received_at' THEN p.wallet_received_at
        ELSE p.ordered_at
      END AS sort_date,
      p.order_no AS sort_order_no
    FROM page_rows p
    LEFT JOIN LATERAL (
      SELECT oo.id, oo.bill_no, oo.total_amount
      FROM public.or_orders oo
      WHERE oo.channel_order_no IS NOT NULL
        AND lower(btrim(oo.channel_order_no)) = lower(btrim(p.order_no))
      ORDER BY oo.created_at DESC
      LIMIT 1
    ) erp ON true
  )
  SELECT COALESCE(jsonb_agg(row_data ORDER BY sort_date DESC NULLS LAST, sort_order_no DESC), '[]'::jsonb) FROM enriched;
$$;


--
-- Name: ac_ecommerce_reconciliation_summary(uuid, text, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_reconciliation_summary(p_channel_id uuid, p_date_basis text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_search text DEFAULT NULL::text, p_status_filter text DEFAULT 'all'::text) RETURNS TABLE(order_count bigint, delivered_count bigint, cancelled_count bigint, shipping_count bigint, paid_count bigint, issue_count bigint, sales_total numeric, fee_total numeric, payout_total numeric, wallet_total numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT r.*
    FROM public.ac_v_ecommerce_order_reconciliation_core r
    WHERE r.channel_id = p_channel_id
      AND CASE p_date_basis
        WHEN 'settled_at' THEN r.settled_at
        WHEN 'wallet_received_at' THEN r.wallet_received_at
        ELSE r.ordered_at
      END >= p_date_from
      AND CASE p_date_basis
        WHEN 'settled_at' THEN r.settled_at
        WHEN 'wallet_received_at' THEN r.wallet_received_at
        ELSE r.ordered_at
      END <= p_date_to
      AND (nullif(btrim(p_search), '') IS NULL OR r.order_no ILIKE '%' || btrim(p_search) || '%')
      AND (
        p_status_filter = 'all'
        OR (p_status_filter = 'issues' AND r.reconciliation_status IN ('waiting_wallet', 'waiting_settlement', 'amount_mismatch', 'needs_review'))
        OR (p_status_filter NOT IN ('all', 'issues') AND r.reconciliation_status = p_status_filter)
      )
  )
  SELECT
    count(*) AS order_count,
    count(*) FILTER (WHERE delivery_status = 'delivered') AS delivered_count,
    count(*) FILTER (WHERE delivery_status = 'cancelled') AS cancelled_count,
    count(*) FILTER (WHERE delivery_status = 'shipping') AS shipping_count,
    count(*) FILTER (WHERE reconciliation_status IN ('paid', 'paid_zero')) AS paid_count,
    count(*) FILTER (WHERE reconciliation_status IN ('waiting_wallet', 'waiting_settlement', 'amount_mismatch', 'needs_review')) AS issue_count,
    CASE WHEN coalesce(sum(gross_sales), 0) <> 0 THEN coalesce(sum(gross_sales), 0) ELSE coalesce(sum(order_total), 0) END AS sales_total,
    coalesce(sum(platform_fee_total), 0) AS fee_total,
    coalesce(sum(payout_amount), 0) AS payout_total,
    coalesce(sum(wallet_amount), 0) AS wallet_total
  FROM filtered;
$$;


--
-- Name: ac_ecommerce_set_manual_status(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_ecommerce_set_manual_status(p_channel_id uuid, p_order_no text, p_status text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_status NOT IN ('cancelled', 'returned') THEN
    RAISE EXCEPTION 'Unsupported manual reconciliation status';
  END IF;

  IF nullif(btrim(p_order_no), '') IS NULL THEN
    RAISE EXCEPTION 'Order number is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.ac_v_ecommerce_marketplace_bill_reconciliation row_check
    WHERE row_check.channel_id = p_channel_id
      AND lower(btrim(row_check.order_no)) = lower(btrim(p_order_no))
  ) THEN
    RAISE EXCEPTION 'Marketplace bill not found';
  END IF;

  INSERT INTO public.ac_ecommerce_reconciliation_overrides (
    channel_id,
    order_no,
    manual_status,
    note,
    updated_by,
    updated_at
  ) VALUES (
    p_channel_id,
    btrim(p_order_no),
    p_status,
    nullif(btrim(p_note), ''),
    auth.uid(),
    now()
  )
  ON CONFLICT (channel_id, order_no) DO UPDATE
  SET manual_status = EXCLUDED.manual_status,
      note = EXCLUDED.note,
      updated_by = EXCLUDED.updated_by,
      updated_at = now();
END;
$$;


--
-- Name: ac_guard_shipping_payment_duplicate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_guard_shipping_payment_duplicate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.or_shipping_conversion_payments WHERE trans_ref=OLD.easyslip_trans_ref) THEN
 IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.verified_amount IS DISTINCT FROM OLD.verified_amount OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted OR NEW.validation_status IS DISTINCT FROM OLD.validation_status OR NEW.easyslip_trans_ref IS DISTINCT FROM OLD.easyslip_trans_ref THEN RAISE EXCEPTION 'หลักฐานชำระค่าส่งที่ตรวจแล้วไม่สามารถแก้ไขยอดหรือย้ายบิลได้'; END IF;
 RETURN NEW;
 END IF;
 IF NEW.validation_status='passed' AND NEW.easyslip_trans_ref IS NOT NULL THEN
 PERFORM pg_advisory_xact_lock(hashtextextended('SLIP:'||NEW.easyslip_trans_ref,0));
 IF coalesce(current_setting('app.shipping_payment_write',true),'')<>'yes' AND EXISTS(SELECT 1 FROM public.or_shipping_conversion_payments WHERE trans_ref=NEW.easyslip_trans_ref) THEN RAISE EXCEPTION 'สลิปนี้ใช้ชำระการเปลี่ยนเป็นจัดส่งแล้ว'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: acknowledge_my_certificate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_my_certificate(p_certificate_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.hr_certificates
  SET acknowledged_at = COALESCE(acknowledged_at, now())
  WHERE id = p_certificate_id
    AND employee_id = public.hr_my_employee_id()
    AND status = 'issued';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Certificate not found or cannot be acknowledged';
  END IF;
END;
$$;


