--
-- Name: approve_borrow_requisition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_borrow_requisition(p_borrow_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role   TEXT;
  v_status TEXT;
  v_item   RECORD;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติรายการยืม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_status;
  END IF;

  FOR v_item IN
    SELECT product_id, qty
    FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id
  LOOP
    INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    VALUES (v_item.product_id, 0, v_item.qty, 0)
    ON CONFLICT (product_id) DO UPDATE
      SET reserved = COALESCE(public.inv_stock_balances.reserved, 0) + v_item.qty;
  END LOOP;

  UPDATE public.wms_borrow_requisitions
  SET status = 'approved', approved_by = auth.uid(), approved_at = NOW()
  WHERE id = p_borrow_id;
END;
$$;


--
-- Name: approve_return_requisition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_return_requisition(p_return_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role     TEXT;
  v_status   TEXT;
  v_item     RECORD;
  v_avg_cost NUMERIC;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติรายการคืน (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_return_requisitions
  WHERE id = p_return_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการคืน'; END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_status;
  END IF;

  FOR v_item IN
    SELECT product_id, qty
    FROM public.wms_return_requisition_items
    WHERE return_requisition_id = p_return_id
  LOOP
    v_avg_cost := public.fn_get_current_avg_cost(v_item.product_id);

    INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    VALUES (v_item.product_id, v_item.qty, 0, 0)
    ON CONFLICT (product_id) DO UPDATE
      SET on_hand = inv_stock_balances.on_hand + v_item.qty;

    INSERT INTO public.inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, unit_cost, total_cost
    )
    VALUES (
      v_item.product_id, 'return_requisition', v_item.qty,
      'wms_return_requisitions', p_return_id,
      'อนุมัติใบคืน (RPC)', v_avg_cost, v_item.qty * v_avg_cost
    );

    INSERT INTO public.inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id
    )
    VALUES (
      v_item.product_id, v_item.qty, v_item.qty, v_avg_cost,
      'wms_return_requisitions', p_return_id
    );

    PERFORM public.fn_recalc_product_landed_cost(v_item.product_id);
  END LOOP;

  UPDATE public.wms_return_requisitions
  SET status = 'approved', approved_by = auth.uid(), approved_at = NOW()
  WHERE id = p_return_id;
END;
$$;


--
-- Name: approve_wms_requisition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_wms_requisition(p_requisition_id uuid, p_picker_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role TEXT;
  v_picker_role TEXT;
  v_requisition public.wms_requisitions%ROWTYPE;
  v_item_count INTEGER;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store') THEN RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติใบเบิก'; END IF;
  SELECT role INTO v_picker_role FROM public.us_users WHERE id = p_picker_id;
  IF v_picker_role IS DISTINCT FROM 'picker' THEN RAISE EXCEPTION 'ผู้รับงานที่เลือกไม่ใช่ Picker'; END IF;

  SELECT * INTO v_requisition FROM public.wms_requisitions WHERE id = p_requisition_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบใบเบิก'; END IF;
  IF v_requisition.status <> 'pending' THEN RAISE EXCEPTION 'ใบเบิกนี้ไม่ได้อยู่ในสถานะรออนุมัติ (สถานะ: %)', v_requisition.status; END IF;
  SELECT COUNT(*) INTO v_item_count FROM public.wms_requisition_items WHERE requisition_id = v_requisition.requisition_id;
  IF v_item_count = 0 THEN RAISE EXCEPTION 'ใบเบิกนี้ไม่มีรายการสินค้า'; END IF;

  UPDATE public.wms_requisitions SET status = 'approved', approved_by = v_uid, approved_at = NOW() WHERE id = p_requisition_id;
  INSERT INTO public.wms_orders
    (order_id, product_code, product_name, location, qty, unit_name, assigned_to, status)
  SELECT v_requisition.requisition_id, item.product_code, item.product_name, item.location, item.qty,
         COALESCE(NULLIF(TRIM(item.unit_name), ''), NULLIF(TRIM(p.unit_name), ''), 'ชิ้น'), p_picker_id, 'pending'
  FROM public.wms_requisition_items item
  LEFT JOIN public.pr_products p ON p.product_code = item.product_code
  WHERE item.requisition_id = v_requisition.requisition_id
  ORDER BY item.created_at, item.id;
END;
$$;


--
-- Name: bank_auto_match_order_has_capacity(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_auto_match_order_has_capacity(p_order_id uuid, p_amount numeric) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM or_orders o WHERE o.id=p_order_id
  AND coalesce(o.status,'') NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ','ยกเลิก')
  AND coalesce((SELECT sum(allocated_amount) FROM ac_bank_reconciliation_allocations WHERE order_id=o.id),0)
    +coalesce((SELECT sum(amount) FROM ac_order_receipt_certifications WHERE order_id=o.id AND revoked_at IS NULL),0)
    <o.receivable_amount+public.or_approved_overpayment_amount(o.id)-0.01
  AND coalesce((SELECT sum(allocated_amount) FROM ac_bank_reconciliation_allocations WHERE order_id=o.id),0)
    +coalesce((SELECT sum(amount) FROM ac_order_receipt_certifications WHERE order_id=o.id AND revoked_at IS NULL),0)
    +p_amount<=o.receivable_amount+public.or_approved_overpayment_amount(o.id)+0.01)
$$;


--
-- Name: bank_auto_match_overpayment_refunds(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_auto_match_overpayment_refunds(p_order_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_info jsonb; v_waivers jsonb;
BEGIN
 v_info:=public.bank_auto_match_overpayment_refunds_before_waiver(p_order_ids);
 SELECT coalesce(jsonb_object_agg(id::text,public.or_approved_waiver_amount(id)),'{}'::jsonb)
   INTO v_waivers FROM or_orders WHERE id=ANY(p_order_ids);
 RETURN v_info||jsonb_build_object('waived_amounts',v_waivers);
END $$;


--
-- Name: bank_auto_match_overpayment_refunds_before_waiver(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_auto_match_overpayment_refunds_before_waiver(p_order_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_order public.or_orders; v_info JSONB; v_refund_id UUID; v_candidates BIGINT;
  v_count INTEGER := 0; v_amounts JSONB := '{}'::JSONB;
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  IF COALESCE(cardinality(p_order_ids),0)>50 THEN RAISE EXCEPTION 'จับคู่อัตโนมัติได้ครั้งละไม่เกิน 50 บิล'; END IF;
  -- Use the same order as manual matching to serialize simultaneous requests.
  FOR v_order IN SELECT * FROM public.or_orders WHERE id=ANY(p_order_ids)
    ORDER BY id FOR UPDATE
  LOOP
    IF COALESCE(v_order.status,'') IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') THEN CONTINUE; END IF;
    -- Lock same-bill refunds before testing uniqueness, including pending requests.
    -- Two approved refunds for the exact amount are ambiguous: leave both for manual selection.
    PERFORM id FROM public.ac_refunds WHERE order_id=v_order.id ORDER BY id FOR UPDATE;
    v_info := public.bank_overpayment_refunds(v_order.id);
    SELECT count(*),(array_agg(r.id ORDER BY r.id))[1] INTO v_candidates,v_refund_id
    FROM public.ac_refunds r
    WHERE r.order_id=v_order.id AND r.status='approved'
      AND r.amount=(v_info->>'remaining')::NUMERIC AND r.amount>0.01
      AND NOT EXISTS(SELECT 1 FROM public.ac_bank_overpayment_refund_matches m WHERE m.refund_id=r.id)
      AND NOT EXISTS(SELECT 1 FROM public.ac_bank_refund_auto_match_exclusions e WHERE e.refund_id=r.id);
    IF v_candidates=1 THEN
      PERFORM public.bank_match_overpayment_refund(v_order.id,v_refund_id);
      v_count := v_count+1;
    END IF;
    SELECT v_amounts || jsonb_build_object(v_order.id::TEXT,COALESCE(sum(r.amount),0)) INTO v_amounts
    FROM public.ac_bank_overpayment_refund_matches m JOIN public.ac_refunds r ON r.id=m.refund_id
    WHERE m.order_id=v_order.id;
  END LOOP;
  RETURN jsonb_build_object('matched_count',v_count,'amounts',v_amounts);
END $$;


--
-- Name: bank_certify_receipt(uuid, numeric, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_certify_receipt(p_order_id uuid, p_amount numeric, p_method text, p_received_on date, p_reason text, p_evidence text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id UUID; v_order public.or_orders; v_received NUMERIC;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND role = 'superadmin') THEN
    RAISE EXCEPTION 'เฉพาะ superadmin สามารถรับรองเงินรับ';
  END IF;
  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_order.status,'') IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') THEN
    RAISE EXCEPTION 'บิลนี้ไม่สามารถรับรองเงินรับได้';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount,2)
     OR p_received_on IS NULL OR p_received_on > (now() AT TIME ZONE 'Asia/Bangkok')::DATE
     OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุยอดเงิน วันที่รับ และเหตุผลให้ถูกต้อง'; END IF;
  SELECT COALESCE((SELECT sum(allocated_amount) FROM public.ac_bank_reconciliation_allocations WHERE order_id=p_order_id),0)
    + COALESCE((SELECT sum(amount) FROM public.ac_order_receipt_certifications WHERE order_id=p_order_id AND revoked_at IS NULL),0)
    INTO v_received;
  IF v_received + p_amount > v_order.receivable_amount + 0.01 THEN RAISE EXCEPTION 'ยอดรับรองเกินยอดค้างของบิล กรุณาตรวจเงินที่จับคู่แล้ว'; END IF;
  INSERT INTO public.ac_order_receipt_certifications(order_id,amount,receipt_method,received_on,reason,evidence_reference,certified_by)
  VALUES(p_order_id,p_amount,p_method,p_received_on,btrim(p_reason),NULLIF(btrim(p_evidence),''),auth.uid()) RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: bank_manual_slip_retry_easyslip(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_manual_slip_retry_easyslip(p_manual_slip_id uuid, p_verified_slip_id uuid, p_bank_setting_id uuid, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
  v_requested public.ac_manual_slip_checks;
  v_matched public.ac_manual_slip_checks;
  v_slip public.ac_verified_slips;
  v_bank public.bank_settings;
  v_response JSONB;
  v_api_success BOOLEAN := FALSE;
  v_pass BOOLEAN := FALSE;
  v_duplicate BOOLEAN := FALSE;
  v_amount NUMERIC;
  v_amount_text TEXT;
  v_trans_ref TEXT;
  v_date_text TEXT;
  v_payment_at TIMESTAMPTZ;
  v_receiver_bank TEXT;
  v_receiver_account TEXT;
  v_bank_match BOOLEAN := FALSE;
  v_account_match BOOLEAN := FALSE;
  v_error TEXT;
  v_errors TEXT[] := ARRAY[]::TEXT[];
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจ EasySlip ซ้ำ';
  END IF;

  SELECT * INTO v_requested
  FROM public.ac_manual_slip_checks
  WHERE id = p_manual_slip_id
  FOR UPDATE;
  IF NOT FOUND OR v_requested.status NOT IN ('approved', 'verified_by_easyslip') THEN
    RAISE EXCEPTION 'รายการนี้ไม่ใช่สลิปตรวจมือที่อนุมัติแล้ว';
  END IF;

  SELECT * INTO v_slip
  FROM public.ac_verified_slips
  WHERE id = p_verified_slip_id
    AND order_id = v_requested.order_id
    AND COALESCE(is_deleted, FALSE) = FALSE
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'รูปสลิปไม่ตรงกับบิลของรายการตรวจมือ';
  END IF;

  SELECT * INTO v_bank
  FROM public.bank_settings
  WHERE id = p_bank_setting_id AND is_active = TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบบัญชีธนาคารที่เปิดใช้งาน';
  END IF;

  v_response := p_result->'easyslip_response';
  v_api_success := COALESCE((p_result->>'success')::BOOLEAN, FALSE);
  v_error := NULLIF(trim(COALESCE(p_result->>'error', p_result->>'message', '')), '');
  v_amount_text := COALESCE(p_result->>'amount', v_response #>> '{data,amount,amount}');
  IF COALESCE(v_amount_text, '') ~ '^[0-9]+([.][0-9]+)?$' THEN
    v_amount := v_amount_text::NUMERIC;
  END IF;
  v_trans_ref := NULLIF(trim(COALESCE(v_response #>> '{data,transRef}', '')), '');
  v_date_text := NULLIF(trim(COALESCE(v_response #>> '{data,date}', '')), '');
  IF v_date_text IS NOT NULL THEN
    BEGIN
      v_payment_at := v_date_text::TIMESTAMPTZ;
    EXCEPTION WHEN OTHERS THEN
      v_payment_at := NULL;
    END;
  END IF;
  v_receiver_bank := NULLIF(trim(COALESCE(v_response #>> '{data,receiver,bank,id}', '')), '');
  v_receiver_account := NULLIF(trim(COALESCE(v_response #>> '{data,receiver,account,bank,account}', '')), '');

  v_bank_match := v_receiver_bank IS NOT NULL AND v_receiver_bank = v_bank.bank_code;
  v_account_match := v_receiver_account IS NOT NULL
    AND right(regexp_replace(v_receiver_account, '\D', '', 'g'), 4)
      = right(regexp_replace(v_bank.account_number, '\D', '', 'g'), 4);

  IF v_trans_ref IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ac_verified_slips used
      WHERE used.id <> p_verified_slip_id
        AND COALESCE(used.is_deleted, FALSE) = FALSE
        AND NULLIF(trim(used.easyslip_trans_ref), '') = v_trans_ref
    ) INTO v_duplicate;
  END IF;

  -- Match the verified image to one unused manual transfer of the same bill and amount.
  -- When duplicate amounts exist, the closest manually entered transfer time wins.
  IF v_api_success AND v_amount IS NOT NULL THEN
    SELECT m.* INTO v_matched
    FROM public.ac_manual_slip_checks m
    WHERE m.order_id = v_requested.order_id
      AND m.status = 'approved'
      AND ABS(m.transfer_amount - v_amount) <= 0.01
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_manual_slip_easyslip_retries r
        WHERE r.matched_manual_slip_id = m.id AND r.status = 'passed'
      )
    ORDER BY
      CASE WHEN v_payment_at IS NULL THEN 0 ELSE
        ABS(EXTRACT(EPOCH FROM (
          ((m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok') - v_payment_at
        )))
      END,
      m.submitted_at,
      m.id
    LIMIT 1
    FOR UPDATE OF m;
  END IF;

  IF NOT v_api_success THEN v_errors := array_append(v_errors, COALESCE(v_error, 'EasySlip ตรวจไม่สำเร็จ')); END IF;
  IF v_response IS NULL THEN v_errors := array_append(v_errors, 'ไม่พบข้อมูลตอบกลับจาก EasySlip'); END IF;
  IF v_payment_at IS NULL THEN v_errors := array_append(v_errors, 'ไม่พบวันเวลาโอนจาก EasySlip'); END IF;
  IF v_amount IS NULL THEN v_errors := array_append(v_errors, 'ไม่พบยอดเงินจาก EasySlip'); END IF;
  IF v_amount IS NOT NULL AND v_matched.id IS NULL THEN v_errors := array_append(v_errors, 'ไม่พบรายการตรวจมือยอดเดียวกันที่ยังไม่ได้จับกับรูปอื่น'); END IF;
  IF NOT v_bank_match THEN v_errors := array_append(v_errors, 'ธนาคารผู้รับไม่ตรงกับบัญชี Statement'); END IF;
  IF NOT v_account_match THEN v_errors := array_append(v_errors, 'เลขบัญชีผู้รับไม่ตรงกับบัญชี Statement'); END IF;
  IF v_duplicate THEN v_errors := array_append(v_errors, 'เลขอ้างอิง EasySlip ถูกใช้กับสลิปอื่นแล้ว'); END IF;

  v_pass := v_api_success
    AND v_response IS NOT NULL
    AND v_payment_at IS NOT NULL
    AND v_amount IS NOT NULL
    AND v_matched.id IS NOT NULL
    AND v_bank_match
    AND v_account_match
    AND NOT v_duplicate;

  UPDATE public.ac_verified_slips
  SET verified_amount = COALESCE(v_amount, verified_amount),
      easyslip_response = COALESCE(v_response, easyslip_response),
      easyslip_trans_ref = CASE WHEN v_pass THEN v_trans_ref ELSE NULL END,
      easyslip_date = CASE WHEN v_pass THEN v_payment_at ELSE NULL END,
      easyslip_receiver_bank_id = COALESCE(v_receiver_bank, easyslip_receiver_bank_id),
      easyslip_receiver_account = COALESCE(v_receiver_account, easyslip_receiver_account),
      is_validated = TRUE,
      validation_status = CASE WHEN v_pass THEN 'passed' ELSE 'failed' END,
      validation_errors = CASE WHEN v_pass THEN NULL ELSE v_errors END,
      expected_amount = CASE WHEN v_pass THEN v_matched.transfer_amount ELSE NULL END,
      expected_bank_account = v_bank.account_number,
      expected_bank_code = v_bank.bank_code,
      bank_code_match = v_bank_match,
      amount_match = v_pass
  WHERE id = p_verified_slip_id;

  INSERT INTO public.ac_manual_slip_easyslip_retries (
    order_id, requested_manual_slip_id, matched_manual_slip_id,
    verified_slip_id, status, checked_at, checked_by, error_message
  ) VALUES (
    v_requested.order_id, p_manual_slip_id,
    CASE WHEN v_pass THEN v_matched.id ELSE NULL END,
    p_verified_slip_id, CASE WHEN v_pass THEN 'passed' ELSE 'failed' END,
    now(), auth.uid(), CASE WHEN v_pass THEN NULL ELSE array_to_string(v_errors, ' | ') END
  )
  ON CONFLICT (verified_slip_id) DO UPDATE
  SET requested_manual_slip_id = EXCLUDED.requested_manual_slip_id,
      matched_manual_slip_id = EXCLUDED.matched_manual_slip_id,
      status = EXCLUDED.status,
      checked_at = EXCLUDED.checked_at,
      checked_by = EXCLUDED.checked_by,
      error_message = EXCLUDED.error_message;

  IF v_pass THEN
    UPDATE public.ac_manual_slip_checks
    SET easyslip_retry_status = 'passed',
        easyslip_retry_checked_at = now(),
        easyslip_retry_checked_by = auth.uid(),
        easyslip_retry_error = NULL,
        status = 'verified_by_easyslip'
    WHERE id = v_matched.id;
  ELSE
    UPDATE public.ac_manual_slip_checks
    SET easyslip_retry_status = 'failed',
        easyslip_retry_checked_at = now(),
        easyslip_retry_checked_by = auth.uid(),
        easyslip_retry_error = array_to_string(v_errors, ' | ')
    WHERE id = p_manual_slip_id AND status = 'approved';
  END IF;

  RETURN jsonb_build_object(
    'success', v_pass,
    'requested_manual_slip_id', p_manual_slip_id,
    'matched_manual_slip_id', CASE WHEN v_pass THEN v_matched.id ELSE NULL END,
    'verified_slip_id', p_verified_slip_id,
    'amount', v_amount,
    'payment_at', v_payment_at,
    'trans_ref', v_trans_ref,
    'errors', to_jsonb(v_errors)
  );
END;
$_$;


--
-- Name: bank_match_overpayment_refund(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_match_overpayment_refund(p_order_id uuid, p_refund_id uuid, p_remove boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_match_overpayment_refund_manual_impl(p_order_id,p_refund_id,p_remove);
  IF p_remove THEN
    INSERT INTO public.ac_bank_refund_auto_match_exclusions(refund_id,excluded_by)
    VALUES(p_refund_id,auth.uid()) ON CONFLICT(refund_id) DO UPDATE
      SET excluded_by=EXCLUDED.excluded_by,excluded_at=now();
  ELSE
    DELETE FROM public.ac_bank_refund_auto_match_exclusions WHERE refund_id=p_refund_id;
  END IF;
END $$;


--
-- Name: bank_match_overpayment_refund_manual_impl(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_match_overpayment_refund_manual_impl(p_order_id uuid, p_refund_id uuid, p_remove boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_refund public.ac_refunds; v_order public.or_orders; v_info JSONB;
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  -- Serialize matches for a bill and lock the refund against concurrent approval changes.
  SELECT * INTO v_order FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
  SELECT * INTO v_refund FROM public.ac_refunds WHERE id=p_refund_id FOR UPDATE;
  IF NOT FOUND OR v_refund.order_id<>p_order_id THEN RAISE EXCEPTION 'รายการโอนคืนต้องเป็นของบิลเดียวกัน'; END IF;
  IF p_remove THEN
    DELETE FROM public.ac_bank_overpayment_refund_matches WHERE order_id=p_order_id AND refund_id=p_refund_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบรายการที่จับคู่'; END IF;
    RETURN;
  END IF;
  IF v_refund.status<>'approved' OR v_refund.amount IS NULL OR v_refund.amount<=0 THEN
    RAISE EXCEPTION 'กรุณาเลือกรายการโอนคืนที่อนุมัติแล้วและมียอดมากกว่าศูนย์';
  END IF;
  IF COALESCE(v_order.status,'') IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') THEN
    RAISE EXCEPTION 'สถานะบิลนี้ไม่สามารถจับคู่ได้';
  END IF;
  IF EXISTS (SELECT 1 FROM public.ac_bank_overpayment_refund_matches WHERE refund_id=p_refund_id) THEN
    RAISE EXCEPTION 'รายการโอนคืนนี้ถูกจับคู่แล้ว กรุณารีเฟรช';
  END IF;
  v_info := public.bank_overpayment_refunds(p_order_id);
  IF (v_info->>'excess')::NUMERIC<=0.01 OR v_refund.amount>(v_info->>'remaining')::NUMERIC THEN
    RAISE EXCEPTION 'ยอดโอนคืนเกินยอดรับเกินที่ยังไม่ได้จับคู่ กรุณารีเฟรชและตรวจสอบยอด';
  END IF;
  INSERT INTO public.ac_bank_overpayment_refund_matches(refund_id,order_id,matched_by)
    VALUES(p_refund_id,p_order_id,auth.uid());
END $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: ac_bank_transaction_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ac_bank_transaction_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_name text NOT NULL,
    match_keyword text NOT NULL,
    classification_name text NOT NULL,
    bank_setting_id uuid,
    direction text DEFAULT 'credit'::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ac_bank_transaction_rules_direction_check CHECK ((direction = ANY (ARRAY['credit'::text, 'debit'::text, 'both'::text]))),
    CONSTRAINT ac_bank_transaction_rules_keyword_length CHECK ((length(btrim(match_keyword)) >= 3))
);


--
-- Name: bank_matching_rule(uuid, text, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_matching_rule(p_bank_setting_id uuid, p_transaction_type text, p_channel text, p_description text, p_debit_amount numeric, p_credit_amount numeric) RETURNS public.ac_bank_transaction_rules
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT rule.*
  FROM public.ac_bank_transaction_rules rule
  WHERE rule.is_active = TRUE
    AND (rule.bank_setting_id IS NULL OR rule.bank_setting_id = p_bank_setting_id)
    AND (
      rule.direction = 'both'
      OR (rule.direction = 'credit' AND COALESCE(p_credit_amount, 0) > 0)
      OR (rule.direction = 'debit' AND COALESCE(p_debit_amount, 0) > 0)
    )
    AND strpos(lower(concat_ws(' ', p_transaction_type, p_channel, p_description)), lower(btrim(rule.match_keyword))) > 0
  ORDER BY
    CASE WHEN rule.bank_setting_id IS NOT NULL THEN 0 ELSE 1 END,
    rule.priority,
    length(rule.match_keyword) DESC,
    rule.created_at,
    rule.id
  LIMIT 1;
$$;


--
-- Name: bank_overpayment_refunds(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_overpayment_refunds(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_info jsonb; v_waived numeric;
BEGIN
 v_info:=public.bank_overpayment_refunds_before_waiver(p_order_id);
 v_waived:=public.or_approved_waiver_amount(p_order_id);
 RETURN v_info||jsonb_build_object('waived_amount',v_waived,
   'remaining',greatest(0,(v_info->>'remaining')::numeric-v_waived));
END $$;


--
-- Name: bank_overpayment_refunds_before_waiver(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_overpayment_refunds_before_waiver(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_excess NUMERIC; v_matched NUMERIC; v_result JSONB;
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  SELECT greatest(0,
    COALESCE((SELECT sum(allocated_amount) FROM public.ac_bank_reconciliation_allocations WHERE order_id=o.id),0)
    + COALESCE((SELECT sum(amount) FROM public.ac_order_receipt_certifications WHERE order_id=o.id AND revoked_at IS NULL),0)
    - o.receivable_amount) INTO v_excess FROM public.or_orders o WHERE o.id=p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
  SELECT COALESCE(sum(r.amount),0) INTO v_matched FROM public.ac_bank_overpayment_refund_matches m
    JOIN public.ac_refunds r ON r.id=m.refund_id WHERE m.order_id=p_order_id;
  SELECT jsonb_build_object('excess',v_excess,'matched_amount',v_matched,
    'remaining',greatest(0,v_excess-v_matched),
    'refunds',COALESCE(jsonb_agg(jsonb_build_object(
      'id',r.id,'amount',r.amount,'created_at',r.created_at,
      'recipient',r.refund_recipient_account_name,'bank',r.refund_recipient_bank,
      'account_number',r.refund_recipient_account_number,'reason',r.refund_recipient_reason,
      'has_slip',COALESCE(cardinality(r.refund_slip_paths),0)>0,
      'sent',r.refund_slip_sent_at IS NOT NULL,'matched_at',m.matched_at
    ) ORDER BY r.created_at DESC,r.id),'[]'::JSONB)) INTO v_result
  FROM public.ac_refunds r LEFT JOIN public.ac_bank_overpayment_refund_matches m ON m.refund_id=r.id
  WHERE r.order_id=p_order_id AND (r.status='approved' OR m.refund_id IS NOT NULL);
  RETURN v_result;
END $$;


--
-- Name: bank_receipt_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_receipt_history(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 SELECT COALESCE(jsonb_agg(to_jsonb(h)),'[]'::JSONB) INTO v_result FROM (
  SELECT c.*,COALESCE(u.username,c.certified_by::TEXT) actor,COALESCE(r.username,c.revoked_by::TEXT) revoker
  FROM public.ac_order_receipt_certifications c LEFT JOIN public.us_users u ON u.id=c.certified_by
  LEFT JOIN public.us_users r ON r.id=c.revoked_by WHERE c.order_id=p_order_id ORDER BY c.certified_at DESC,c.id
 ) h; RETURN v_result;
END $$;


--
-- Name: bank_reconciliation_bill_match_availability(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_bill_match_availability(p_bill_no text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_order public.or_orders; v_allocated numeric; v_limit numeric;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 SELECT * INTO v_order FROM or_orders WHERE upper(trim(bill_no))=upper(trim(p_bill_no)) AND status<>'ยกเลิก' LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล หรือบิลถูกยกเลิก'; END IF;
 SELECT coalesce(sum(allocated_amount),0) INTO v_allocated FROM ac_bank_reconciliation_allocations WHERE order_id=v_order.id;
 v_allocated:=v_allocated+coalesce((SELECT sum(amount) FROM ac_order_receipt_certifications WHERE order_id=v_order.id AND revoked_at IS NULL),0);
 v_limit:=coalesce(v_order.receivable_amount,0)+public.or_approved_overpayment_amount(v_order.id);
 RETURN jsonb_build_object('available',v_allocated<v_limit-0.01,'bill_no',v_order.bill_no,'order_id',v_order.id,
   'bill_amount',v_order.receivable_amount,'allowed_amount',v_limit,'allocated_amount',v_allocated,
   'remaining_amount',greatest(v_limit-v_allocated,0));
END $$;


--
-- Name: bank_reconciliation_clear_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_clear_match(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  PERFORM public.bank_reconciliation_clear_match_authorized_impl(p_transaction_id);
END;
$$;


--
-- Name: bank_reconciliation_clear_match_authorized_impl(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_clear_match_authorized_impl(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ผลกระทบยอด';
  END IF;
  DELETE FROM public.ac_bank_reconciliation_allocations WHERE transaction_id = p_transaction_id;
  UPDATE public.ac_bank_statement_transactions SET reconciliation_status = 'unmatched'
  WHERE id = p_transaction_id;
END;
$$;


--
-- Name: bank_reconciliation_global_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_global_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_unmatched_count BIGINT;
  v_ambiguous_count BIGINT;
  v_missing_payment_count BIGINT;
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();

  SELECT
    COUNT(*) FILTER (WHERE tx.credit_amount > 0 AND tx.reconciliation_status = 'unmatched'),
    COUNT(*) FILTER (WHERE tx.credit_amount > 0 AND tx.reconciliation_status = 'ambiguous')
  INTO v_unmatched_count, v_ambiguous_count
  FROM public.ac_bank_statement_transactions tx;

  SELECT COUNT(*)
  INTO v_missing_payment_count
  FROM (
    SELECT 'verified_slip'::TEXT AS source_type, slip.id AS source_id
    FROM public.ac_verified_slips slip
    JOIN public.or_orders customer_order ON customer_order.id = slip.order_id
    WHERE COALESCE(slip.is_deleted, false) = false
      AND slip.easyslip_date IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=customer_order.id AND c.revoked_at IS NULL
       HAVING sum(c.amount)+COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=customer_order.id),0)>=customer_order.receivable_amount-0.01)
      AND COALESCE(customer_order.status, '') NOT IN ('รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก')
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations allocation
        WHERE allocation.verified_slip_id = slip.id
      )
      AND EXISTS (
        SELECT 1
        FROM public.ac_bank_statement_imports statement_import
        JOIN public.bank_settings bank ON bank.id = statement_import.bank_setting_id
        WHERE slip.easyslip_date >= statement_import.period_start::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
          AND slip.easyslip_date < (statement_import.period_end + 1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
          AND (NULLIF(trim(slip.easyslip_receiver_bank_id), '') IS NULL OR trim(slip.easyslip_receiver_bank_id) = bank.bank_code)
          AND (
            NULLIF(regexp_replace(COALESCE(slip.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
            OR right(regexp_replace(slip.easyslip_receiver_account, '\D', '', 'g'), 4)
               = right(regexp_replace(bank.account_number, '\D', '', 'g'), 4)
          )
      )
    UNION ALL
    SELECT 'manual_slip'::TEXT AS source_type, manual_slip.id AS source_id
    FROM public.ac_manual_slip_checks manual_slip
    JOIN public.or_orders customer_order ON customer_order.id = manual_slip.order_id
    WHERE manual_slip.status = 'approved'
      AND manual_slip.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      AND manual_slip.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      AND NOT EXISTS(SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=customer_order.id AND c.revoked_at IS NULL
       HAVING sum(c.amount)+COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=customer_order.id),0)>=customer_order.receivable_amount-0.01)
      AND COALESCE(customer_order.status, '') <> 'ยกเลิก'
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations allocation
        WHERE allocation.manual_slip_check_id = manual_slip.id
      )
      AND EXISTS (
        SELECT 1
        FROM public.ac_bank_statement_imports statement_import
        JOIN public.bank_settings_channels channel
          ON channel.bank_setting_id = statement_import.bank_setting_id
         AND channel.channel_code = customer_order.channel_code
        WHERE CASE
          WHEN manual_slip.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN manual_slip.transfer_date::DATE
          ELSE NULL
        END BETWEEN statement_import.period_start AND statement_import.period_end
      )
  ) missing;

  RETURN jsonb_build_object(
    'unmatched_count', COALESCE(v_unmatched_count, 0),
    'ambiguous_count', COALESCE(v_ambiguous_count, 0),
    'missing_payment_count', COALESCE(v_missing_payment_count, 0)
  );
END;
$_$;


--
-- Name: bank_reconciliation_import_issue_summary(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_import_issue_summary(p_import_ids uuid[]) RETURNS TABLE(import_id uuid, unmatched_count bigint, ambiguous_count bigint, missing_payment_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();

  RETURN QUERY
  WITH transaction_counts AS (
    SELECT
      tx.import_id,
      COUNT(*) FILTER (
        WHERE tx.credit_amount > 0 AND tx.reconciliation_status = 'unmatched'
      ) AS unmatched_count,
      COUNT(*) FILTER (
        WHERE tx.credit_amount > 0 AND tx.reconciliation_status = 'ambiguous'
      ) AS ambiguous_count
    FROM public.ac_bank_statement_transactions tx
    WHERE tx.import_id = ANY(p_import_ids)
    GROUP BY tx.import_id
  )
  SELECT
    statement_import.id,
    COALESCE(transaction_counts.unmatched_count, 0),
    COALESCE(transaction_counts.ambiguous_count, 0),
    COALESCE(missing.missing_payment_count, 0)
  FROM public.ac_bank_statement_imports statement_import
  LEFT JOIN transaction_counts ON transaction_counts.import_id = statement_import.id
  LEFT JOIN LATERAL (
    SELECT COUNT(DISTINCT (payment.source_type, payment.source_id)) AS missing_payment_count
    FROM public.bank_reconciliation_missing_payments(statement_import.id) payment
  ) missing ON TRUE
  WHERE statement_import.id = ANY(p_import_ids)
  ORDER BY statement_import.uploaded_at DESC;
END;
$$;


--
-- Name: bank_reconciliation_manual_source_candidates(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_manual_source_candidates(p_transaction_id uuid, p_order_id uuid) RETURNS TABLE(source_type text, source_id uuid, payment_at timestamp with time zone, paid_amount numeric, time_diff_minutes numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH tx AS (
    SELECT t.*, b.bank_code, b.account_number
    FROM public.ac_bank_statement_transactions t
    JOIN public.bank_settings b ON b.id = t.bank_setting_id
    WHERE t.id = p_transaction_id AND t.credit_amount > 0
  ), candidates AS (
    SELECT
      'verified_slip'::TEXT AS source_type,
      slip.id AS source_id,
      slip.easyslip_date AS payment_at,
      slip.verified_amount AS paid_amount,
      ABS(EXTRACT(EPOCH FROM (slip.easyslip_date - tx.transaction_at))) / 60.0 AS time_diff_minutes
    FROM tx
    JOIN public.ac_verified_slips slip
      ON slip.order_id = p_order_id
     AND COALESCE(slip.is_deleted, FALSE) = FALSE
     AND slip.easyslip_date IS NOT NULL
     AND slip.validation_status = 'passed'
     AND ABS(slip.verified_amount - tx.credit_amount) <= 0.01
     AND (
       (
         (NULLIF(trim(slip.easyslip_receiver_bank_id), '') IS NULL OR trim(slip.easyslip_receiver_bank_id) = tx.bank_code)
         AND (
           NULLIF(regexp_replace(COALESCE(slip.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
           OR right(regexp_replace(slip.easyslip_receiver_account, '\D', '', 'g'), 4)
              = right(regexp_replace(tx.account_number, '\D', '', 'g'), 4)
         )
       )
       OR (
         trim(COALESCE(slip.expected_bank_code, '')) = tx.bank_code
         AND right(regexp_replace(COALESCE(slip.expected_bank_account, ''), '\D', '', 'g'), 4)
             = right(regexp_replace(tx.account_number, '\D', '', 'g'), 4)
       )
     )
    WHERE NOT EXISTS (
      SELECT 1 FROM public.ac_bank_reconciliation_allocations used
      WHERE used.verified_slip_id = slip.id
    )

    UNION ALL

    SELECT
      'manual_slip'::TEXT,
      manual.id,
      (manual.transfer_date || ' ' || manual.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok',
      manual.transfer_amount,
      ABS(EXTRACT(EPOCH FROM (
        ((manual.transfer_date || ' ' || manual.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok') - tx.transaction_at
      ))) / 60.0
    FROM tx
    JOIN public.ac_manual_slip_checks manual
      ON manual.order_id = p_order_id
     AND manual.status = 'approved'
     AND manual.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     AND manual.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     AND ABS(manual.transfer_amount - tx.credit_amount) <= 0.01
    JOIN public.or_orders o ON o.id = manual.order_id
    WHERE EXISTS (
      SELECT 1 FROM public.bank_settings_channels channel
      WHERE channel.bank_setting_id = tx.bank_setting_id
        AND channel.channel_code = o.channel_code
    )
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations used
        WHERE used.manual_slip_check_id = manual.id
      )
  )
  SELECT
    candidate.source_type,
    candidate.source_id,
    candidate.payment_at,
    candidate.paid_amount,
    round(candidate.time_diff_minutes::NUMERIC, 1)
  FROM candidates candidate
  ORDER BY candidate.time_diff_minutes, candidate.source_type, candidate.source_id;
$_$;


--
-- Name: bank_reconciliation_missing_payments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_missing_payments(p_import_id uuid) RETURNS TABLE(source_type text, source_id uuid, order_id uuid, bill_no text, payment_at timestamp with time zone, paid_amount numeric, bill_amount numeric, difference numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  RETURN QUERY SELECT missing.* FROM public.bank_reconciliation_missing_payments_authorized_impl(p_import_id) missing
 WHERE NOT EXISTS(SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=missing.order_id AND c.revoked_at IS NULL
 HAVING sum(c.amount)+COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=missing.order_id),0)>=missing.bill_amount-0.01);
END;
$$;


--
-- Name: bank_reconciliation_missing_payments_authorized_impl(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_missing_payments_authorized_impl(p_import_id uuid) RETURNS TABLE(source_type text, source_id uuid, order_id uuid, bill_no text, payment_at timestamp with time zone, paid_amount numeric, bill_amount numeric, difference numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูกระทบยอดธนาคาร';
  END IF;

  RETURN QUERY
  WITH selected_import AS (
    SELECT i.*, b.bank_code, b.account_number
    FROM public.ac_bank_statement_imports i
    JOIN public.bank_settings b ON b.id = i.bank_setting_id
    WHERE i.id = p_import_id
  ), missing AS (
    SELECT
      'verified_slip'::TEXT AS source_type,
      s.id AS source_id,
      s.order_id,
      o.bill_no,
      s.easyslip_date AS payment_at,
      s.verified_amount AS paid_amount,
      o.total_amount AS bill_amount,
      s.verified_amount - o.total_amount AS difference
    FROM selected_import i
    JOIN public.ac_verified_slips s
      ON s.easyslip_date >= i.period_start::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
     AND s.easyslip_date < (i.period_end + 1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
    JOIN public.or_orders o ON o.id = s.order_id
    WHERE COALESCE(s.is_deleted, false) = false
      AND COALESCE(o.status, '') NOT IN ('รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก')
      AND (NULLIF(trim(s.easyslip_receiver_bank_id), '') IS NULL OR trim(s.easyslip_receiver_bank_id) = i.bank_code)
      AND (
        NULLIF(regexp_replace(COALESCE(s.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
        OR right(regexp_replace(s.easyslip_receiver_account, '\D', '', 'g'), 4)
           = right(regexp_replace(i.account_number, '\D', '', 'g'), 4)
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.verified_slip_id = s.id
      )
    UNION ALL
    SELECT
      'manual_slip'::TEXT AS source_type,
      m.id AS source_id,
      m.order_id,
      o.bill_no,
      (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' AS payment_at,
      m.transfer_amount AS paid_amount,
      o.total_amount AS bill_amount,
      m.transfer_amount - o.total_amount AS difference
    FROM selected_import i
    JOIN public.ac_manual_slip_checks m
      ON CASE
           WHEN m.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN m.transfer_date::DATE
           ELSE NULL
         END BETWEEN i.period_start AND i.period_end
    JOIN public.or_orders o ON o.id = m.order_id
    WHERE m.status = 'approved'
      AND m.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      AND COALESCE(o.status, '') <> 'ยกเลิก'
      AND EXISTS (
        SELECT 1 FROM public.bank_settings_channels bsc
        WHERE bsc.bank_setting_id = i.bank_setting_id AND bsc.channel_code = o.channel_code
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.manual_slip_check_id = m.id
      )
  )
  SELECT
    missing.source_type,
    missing.source_id,
    missing.order_id,
    missing.bill_no,
    missing.payment_at,
    missing.paid_amount,
    missing.bill_amount,
    missing.difference
  FROM missing
  ORDER BY missing.payment_at, missing.bill_no;
END;
$_$;


--
-- Name: bank_reconciliation_require_authorized_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_require_authorized_role() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ใช้งานกระทบยอดธนาคาร';
  END IF;
END;
$$;


--
-- Name: bank_reconciliation_save_rule(uuid, text, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_save_rule(p_rule_id uuid, p_rule_name text, p_match_keyword text, p_classification_name text, p_bank_setting_id uuid, p_apply_existing boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_rule_id UUID;
  v_applied INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตั้งค่าการจำแนกรายการธนาคาร';
  END IF;
  IF length(btrim(COALESCE(p_match_keyword, ''))) < 3 THEN
    RAISE EXCEPTION 'คำที่ใช้จับคู่ต้องมีอย่างน้อย 3 ตัวอักษร';
  END IF;
  IF btrim(COALESCE(p_classification_name, '')) = '' THEN
    RAISE EXCEPTION 'กรุณาระบุชื่อประเภทเงินรับ';
  END IF;
  IF p_bank_setting_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.bank_settings WHERE id = p_bank_setting_id AND is_active = TRUE)
  THEN
    RAISE EXCEPTION 'ไม่พบบัญชีธนาคารที่เปิดใช้งาน';
  END IF;

  IF p_rule_id IS NULL THEN
    INSERT INTO public.ac_bank_transaction_rules (
      rule_name, match_keyword, classification_name, bank_setting_id,
      direction, created_by, updated_at
    ) VALUES (
      COALESCE(NULLIF(btrim(p_rule_name), ''), btrim(p_classification_name)),
      btrim(p_match_keyword),
      btrim(p_classification_name),
      p_bank_setting_id,
      'credit',
      auth.uid(),
      now()
    )
    RETURNING id INTO v_rule_id;
  ELSE
    UPDATE public.ac_bank_transaction_rules
    SET rule_name = COALESCE(NULLIF(btrim(p_rule_name), ''), btrim(p_classification_name)),
        match_keyword = btrim(p_match_keyword),
        classification_name = btrim(p_classification_name),
        bank_setting_id = p_bank_setting_id,
        updated_at = now()
    WHERE id = p_rule_id
    RETURNING id INTO v_rule_id;
    IF v_rule_id IS NULL THEN RAISE EXCEPTION 'ไม่พบกฎที่ต้องการแก้ไข'; END IF;
  END IF;

  IF COALESCE(p_apply_existing, TRUE) AND EXISTS (SELECT 1 FROM public.ac_bank_transaction_rules WHERE id=v_rule_id AND is_active) THEN
    UPDATE public.ac_bank_statement_transactions transaction
    SET reconciliation_status = 'ignored',
        classification_rule_id = v_rule_id,
        classification_name = btrim(p_classification_name),
        classified_at = now(),
        classified_by = auth.uid()
    WHERE transaction.credit_amount > 0
      AND transaction.reconciliation_status IN ('unmatched', 'ambiguous')
      AND (p_bank_setting_id IS NULL OR transaction.bank_setting_id = p_bank_setting_id)
      AND strpos(lower(concat_ws(' ', transaction.transaction_type, transaction.channel, transaction.description)), lower(btrim(p_match_keyword))) > 0
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations allocation
        WHERE allocation.transaction_id = transaction.id
      );
    GET DIAGNOSTICS v_applied = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object('rule_id', v_rule_id, 'applied_count', v_applied);
END;
$$;


--
-- Name: bank_reconciliation_set_manual_match(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_set_manual_match(p_transaction_id uuid, p_bill_no text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  RETURN public.bank_reconciliation_set_manual_match_authorized_impl(p_transaction_id, p_bill_no);
END;
$$;


--
-- Name: bank_reconciliation_set_manual_match_authorized_impl(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_set_manual_match_authorized_impl(p_transaction_id uuid, p_bill_no text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_tx public.ac_bank_statement_transactions;
  v_order public.or_orders;
  v_candidate_count INTEGER := 0;
  v_source_type TEXT;
  v_source_id UUID;
  v_candidates JSONB := '[]'::JSONB;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ผลกระทบยอด';
  END IF;

  SELECT * INTO v_tx
  FROM public.ac_bank_statement_transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND OR v_tx.credit_amount <= 0 THEN RAISE EXCEPTION 'ไม่พบรายการเงินเข้า'; END IF;

  SELECT * INTO v_order
  FROM public.or_orders
  WHERE upper(trim(bill_no)) = upper(trim(p_bill_no)) AND status <> 'ยกเลิก'
  LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล หรือบิลถูกยกเลิก'; END IF;

  SELECT
    COUNT(*)::INTEGER,
    COALESCE(jsonb_agg(to_jsonb(candidate) ORDER BY candidate.time_diff_minutes), '[]'::JSONB)
  INTO v_candidate_count, v_candidates
  FROM public.bank_reconciliation_manual_source_candidates(v_tx.id, v_order.id) candidate;

  IF v_candidate_count > 1 THEN
    RETURN jsonb_build_object(
      'matched', FALSE,
      'requires_source_selection', TRUE,
      'transaction_id', v_tx.id,
      'order_id', v_order.id,
      'bill_no', v_order.bill_no,
      'source_candidate_count', v_candidate_count,
      'candidates', v_candidates
    );
  END IF;

  IF v_candidate_count = 1 THEN
    SELECT candidate.source_type, candidate.source_id
    INTO v_source_type, v_source_id
    FROM public.bank_reconciliation_manual_source_candidates(v_tx.id, v_order.id)
      candidate
    LIMIT 1;
  END IF;

  DELETE FROM public.ac_bank_reconciliation_allocations WHERE transaction_id = v_tx.id;
  INSERT INTO public.ac_bank_reconciliation_allocations (
    transaction_id, order_id, verified_slip_id, manual_slip_check_id,
    allocated_amount, match_method, matched_by
  ) VALUES (
    v_tx.id,
    v_order.id,
    CASE WHEN v_source_type = 'verified_slip' THEN v_source_id ELSE NULL END,
    CASE WHEN v_source_type = 'manual_slip' THEN v_source_id ELSE NULL END,
    v_tx.credit_amount,
    CASE
      WHEN v_source_type = 'verified_slip' THEN 'manual_bill'
      WHEN v_source_type = 'manual_slip' THEN 'manual_bill'
      ELSE 'manual_bill'
    END,
    auth.uid()
  );
  UPDATE public.ac_bank_statement_transactions SET reconciliation_status = 'matched' WHERE id = v_tx.id;

  RETURN jsonb_build_object(
    'matched', TRUE,
    'requires_source_selection', FALSE,
    'transaction_id', v_tx.id,
    'order_id', v_order.id,
    'bill_no', v_order.bill_no,
    'source_candidate_count', v_candidate_count,
    'source_linked', v_candidate_count = 1,
    'source_type', v_source_type,
    'source_id', v_source_id
  );
END;
$$;


--
-- Name: bank_reconciliation_set_manual_match_source(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_set_manual_match_source(p_transaction_id uuid, p_bill_no text, p_source_type text, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tx public.ac_bank_statement_transactions;
  v_order public.or_orders;
  v_candidate RECORD;
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  IF p_source_type NOT IN ('verified_slip', 'manual_slip') THEN
    RAISE EXCEPTION 'ประเภทแหล่งข้อมูลไม่ถูกต้อง';
  END IF;

  SELECT * INTO v_tx
  FROM public.ac_bank_statement_transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND OR v_tx.credit_amount <= 0 THEN RAISE EXCEPTION 'ไม่พบรายการเงินเข้า'; END IF;

  SELECT * INTO v_order
  FROM public.or_orders
  WHERE upper(trim(bill_no)) = upper(trim(p_bill_no)) AND status <> 'ยกเลิก'
  LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล หรือบิลถูกยกเลิก'; END IF;

  SELECT * INTO v_candidate
  FROM public.bank_reconciliation_manual_source_candidates(v_tx.id, v_order.id) candidate
  WHERE candidate.source_type = p_source_type AND candidate.source_id = p_source_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'สลิปที่เลือกไม่พร้อมใช้งาน หรือถูกจับคู่ไปแล้ว';
  END IF;

  DELETE FROM public.ac_bank_reconciliation_allocations WHERE transaction_id = v_tx.id;
  INSERT INTO public.ac_bank_reconciliation_allocations (
    transaction_id, order_id, verified_slip_id, manual_slip_check_id,
    allocated_amount, match_method, matched_by
  ) VALUES (
    v_tx.id,
    v_order.id,
    CASE WHEN p_source_type = 'verified_slip' THEN p_source_id ELSE NULL END,
    CASE WHEN p_source_type = 'manual_slip' THEN p_source_id ELSE NULL END,
    v_tx.credit_amount,
    'manual_bill',
    auth.uid()
  );
  UPDATE public.ac_bank_statement_transactions SET reconciliation_status = 'matched' WHERE id = v_tx.id;

  RETURN jsonb_build_object(
    'matched', TRUE,
    'transaction_id', v_tx.id,
    'order_id', v_order.id,
    'bill_no', v_order.bill_no,
    'source_linked', TRUE,
    'source_type', p_source_type,
    'source_id', p_source_id
  );
END;
$$;


--
-- Name: bank_reconciliation_unclassify_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_reconciliation_unclassify_transaction(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  UPDATE public.ac_bank_statement_transactions
  SET reconciliation_status = 'unmatched',
      classification_rule_id = NULL,
      classification_name = NULL,
      classified_at = NULL,
      classified_by = NULL
  WHERE id = p_transaction_id
    AND reconciliation_status = 'ignored'
    AND NOT EXISTS (
      SELECT 1 FROM public.ac_bank_reconciliation_allocations allocation
      WHERE allocation.transaction_id = p_transaction_id
    );
END;
$$;


--
-- Name: bank_relink_allocations_to_verified_slips(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_relink_allocations_to_verified_slips(p_order_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pair RECORD;
  v_updated INTEGER := 0;
  v_rows INTEGER := 0;
BEGIN
  FOR v_pair IN
    WITH candidates AS (
      SELECT
        allocation.id AS allocation_id,
        allocation.order_id,
        slip.id AS verified_slip_id,
        tx.transaction_at,
        slip.easyslip_date,
        ABS(EXTRACT(EPOCH FROM (slip.easyslip_date - tx.transaction_at))) AS diff_seconds
      FROM public.ac_bank_reconciliation_allocations allocation
      JOIN public.ac_bank_statement_transactions tx
        ON tx.id = allocation.transaction_id
      JOIN public.ac_verified_slips slip
        ON slip.order_id = allocation.order_id
       AND COALESCE(slip.is_deleted, FALSE) = FALSE
       AND slip.easyslip_date IS NOT NULL
       AND ABS(slip.verified_amount - allocation.allocated_amount) <= 0.01
       AND slip.easyslip_date >= tx.transaction_at - INTERVAL '10 minutes'
       AND slip.easyslip_date <= tx.transaction_at + INTERVAL '10 minutes'
       AND (
         slip.validation_status = 'passed'
         OR EXISTS (
           SELECT 1
           FROM public.ac_manual_slip_easyslip_retries retry
           WHERE retry.verified_slip_id = slip.id
             AND retry.status = 'passed'
         )
       )
      WHERE allocation.verified_slip_id IS NULL
        AND (p_order_id IS NULL OR allocation.order_id = p_order_id)
        AND NOT EXISTS (
          SELECT 1
          FROM public.ac_bank_reconciliation_allocations used
          WHERE used.verified_slip_id = slip.id
            AND used.id <> allocation.id
        )
    ), ranked AS (
      SELECT
        candidate.*,
        ROW_NUMBER() OVER (
          PARTITION BY candidate.allocation_id
          ORDER BY candidate.diff_seconds, candidate.verified_slip_id
        ) AS allocation_rank,
        ROW_NUMBER() OVER (
          PARTITION BY candidate.verified_slip_id
          ORDER BY candidate.diff_seconds, candidate.allocation_id
        ) AS slip_rank
      FROM candidates candidate
    )
    SELECT *
    FROM ranked
    WHERE allocation_rank = 1 AND slip_rank = 1
    ORDER BY diff_seconds, allocation_id
  LOOP
    BEGIN
      UPDATE public.ac_bank_reconciliation_allocations
      SET verified_slip_id = v_pair.verified_slip_id,
          manual_slip_check_id = NULL,
          match_method = CASE
            WHEN date_trunc('minute', v_pair.easyslip_date) = date_trunc('minute', v_pair.transaction_at)
              THEN 'exact_verified_slip'
            ELSE 'time_tolerant_verified_slip'
          END,
          note = concat_ws(
            ' | ',
            NULLIF(note, ''),
            'เชื่อม EasySlip อัตโนมัติจากรายการจับคู่เดิม'
          )
      WHERE id = v_pair.allocation_id
        AND verified_slip_id IS NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.ac_bank_reconciliation_allocations used
          WHERE used.verified_slip_id = v_pair.verified_slip_id
            AND used.id <> v_pair.allocation_id
        );
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_updated := v_updated + v_rows;
    EXCEPTION WHEN unique_violation THEN
      -- A concurrent reconciliation already claimed this verified slip.
      NULL;
    END;
  END LOOP;

  RETURN v_updated;
END;
$$;


--
-- Name: bank_repair_unique_manual_bill_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_repair_unique_manual_bill_sources() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_allocation RECORD;
  v_candidate RECORD;
  v_count INTEGER;
  v_updated INTEGER := 0;
BEGIN
  FOR v_allocation IN
    SELECT allocation.id, allocation.transaction_id, allocation.order_id
    FROM public.ac_bank_reconciliation_allocations allocation
    WHERE allocation.verified_slip_id IS NULL
      AND allocation.manual_slip_check_id IS NULL
      AND allocation.match_method = 'manual_bill'
    ORDER BY allocation.matched_at, allocation.id
  LOOP
    SELECT COUNT(*)::INTEGER INTO v_count
    FROM public.bank_reconciliation_manual_source_candidates(
      v_allocation.transaction_id,
      v_allocation.order_id
    );

    IF v_count = 1 THEN
      SELECT * INTO v_candidate
      FROM public.bank_reconciliation_manual_source_candidates(
        v_allocation.transaction_id,
        v_allocation.order_id
      )
      LIMIT 1;

      UPDATE public.ac_bank_reconciliation_allocations
      SET verified_slip_id = CASE WHEN v_candidate.source_type = 'verified_slip' THEN v_candidate.source_id ELSE NULL END,
          manual_slip_check_id = CASE WHEN v_candidate.source_type = 'manual_slip' THEN v_candidate.source_id ELSE NULL END,
          note = concat_ws(' | ', NULLIF(note, ''), 'เชื่อมแหล่งชำระอัตโนมัติจากการจับคู่เลขบิลเดิม')
      WHERE id = v_allocation.id
        AND verified_slip_id IS NULL
        AND manual_slip_check_id IS NULL;
      IF FOUND THEN v_updated := v_updated + 1; END IF;
    END IF;
  END LOOP;

  RETURN v_updated;
END;
$$;


--
-- Name: bank_revoke_receipt(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_revoke_receipt(p_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role='superadmin') THEN RAISE EXCEPTION 'เฉพาะ superadmin สามารถยกเลิกการรับรอง'; END IF;
  IF NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผล'; END IF;
  PERFORM 1 FROM public.or_orders WHERE id=(SELECT order_id FROM public.ac_order_receipt_certifications WHERE id=p_id) FOR UPDATE;
  UPDATE public.ac_order_receipt_certifications SET revoked_by=auth.uid(),revoked_at=now(),revoke_reason=btrim(p_reason)
  WHERE id=p_id AND revoked_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบการรับรองที่ยังใช้งาน'; END IF;
END $$;


--
-- Name: bank_sales_workspace(date, date, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_sales_workspace(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_status text DEFAULT 'pending'::text, p_search text DEFAULT ''::text, p_channel text DEFAULT ''::text, p_method text DEFAULT ''::text, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_result JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 WITH base AS (
  SELECT o.id,o.bill_no,o.created_at,o.channel_code,o.payment_method,o.total_amount,o.receivable_amount,
   COALESCE(a.amount,0) bank_received,COALESCE(c.amount,0) certified_received,
   COALESCE(s.amount,0)+COALESCE(m.amount,0) evidence_amount,COALESCE(c.cash,0) certified_cash,COALESCE(c.other,0) certified_other,
   s.payment_at,
   CASE WHEN COALESCE(a.amount,0)+COALESCE(c.amount,0)>o.receivable_amount+0.01 THEN 'overpaid'
    WHEN ((upper(COALESCE(o.bill_no,'')) LIKE 'REQ%' AND o.receivable_amount<=0.01) OR (o.payment_not_required AND o.receivable_amount=0))
      AND COALESCE(a.amount,0)+COALESCE(c.amount,0)<=0.01 THEN 'no_payment'
    WHEN COALESCE(a.amount,0)+COALESCE(c.amount,0)>=o.receivable_amount-0.01 THEN CASE WHEN COALESCE(c.amount,0)>0 THEN 'certified' ELSE 'matched' END
    WHEN COALESCE(a.amount,0)+COALESCE(c.amount,0)>0 THEN 'partial'
    WHEN COALESCE(s.amount,0)+COALESCE(m.amount,0)>0 THEN 'waiting_bank' ELSE 'no_evidence' END reconciliation_state,
   CASE WHEN coverage.payment_count=0 OR coverage.has_unknown THEN 'unknown'
    WHEN coverage.uncovered THEN 'not_uploaded' ELSE 'covered' END statement_coverage
  FROM public.or_orders o
  LEFT JOIN LATERAL (SELECT sum(allocated_amount) amount FROM public.ac_bank_reconciliation_allocations WHERE order_id=o.id) a ON TRUE
  LEFT JOIN LATERAL (SELECT sum(amount) amount,sum(amount) FILTER(WHERE receipt_method='cash') cash,sum(amount) FILTER(WHERE receipt_method<>'cash') other FROM public.ac_order_receipt_certifications WHERE order_id=o.id AND revoked_at IS NULL) c ON TRUE
  LEFT JOIN LATERAL (SELECT sum(verified_amount) amount,max(easyslip_date) payment_at,max(NULLIF(easyslip_receiver_account,'')) receiver_account
    FROM public.ac_verified_slips WHERE order_id=o.id AND COALESCE(is_deleted,false)=false AND verified_amount>0 AND easyslip_date IS NOT NULL) s ON TRUE
  LEFT JOIN LATERAL (SELECT sum(transfer_amount) amount,max(CASE WHEN transfer_date ~ '^\d{4}-\d{2}-\d{2}$' THEN transfer_date::DATE END) payment_on
    FROM public.ac_manual_slip_checks WHERE order_id=o.id AND status='approved'
    AND NOT EXISTS (SELECT 1 FROM public.ac_verified_slips vs WHERE vs.order_id=o.id AND COALESCE(vs.is_deleted,false)=false AND vs.easyslip_date IS NOT NULL AND vs.verified_amount>0)) m ON TRUE
  LEFT JOIN LATERAL (
   SELECT count(*) payment_count,bool_or(p.payment_on IS NULL OR NOT EXISTS(
     SELECT 1 FROM public.bank_settings b WHERE
      (p.receiver_account IS NOT NULL AND right(regexp_replace(p.receiver_account,'\D','','g'),4)=right(regexp_replace(b.account_number,'\D','','g'),4)
       AND (p.bank_code IS NULL OR b.bank_code=p.bank_code))
      OR (p.receiver_account IS NULL AND EXISTS(SELECT 1 FROM public.bank_settings_channels bc WHERE bc.bank_setting_id=b.id AND bc.channel_code=o.channel_code))
    )) has_unknown,
    bool_or(EXISTS(SELECT 1 FROM public.bank_settings b WHERE
      ((p.receiver_account IS NOT NULL AND right(regexp_replace(p.receiver_account,'\D','','g'),4)=right(regexp_replace(b.account_number,'\D','','g'),4)
        AND (p.bank_code IS NULL OR b.bank_code=p.bank_code))
       OR (p.receiver_account IS NULL AND EXISTS(SELECT 1 FROM public.bank_settings_channels bc WHERE bc.bank_setting_id=b.id AND bc.channel_code=o.channel_code)))
      AND NOT EXISTS(SELECT 1 FROM public.ac_bank_statement_imports i WHERE i.bank_setting_id=b.id AND p.payment_on BETWEEN i.period_start AND i.period_end)
    )) uncovered
   FROM (
    SELECT (vs.easyslip_date AT TIME ZONE 'Asia/Bangkok')::DATE payment_on,
      NULLIF(regexp_replace(CASE
        WHEN COALESCE(vs.easyslip_receiver_account,'') ~ '[xX*•]' AND NULLIF(btrim(vs.expected_bank_account),'') IS NOT NULL THEN vs.expected_bank_account
        ELSE COALESCE(NULLIF(btrim(vs.easyslip_receiver_account),''),vs.expected_bank_account,'') END,'\D','','g'),'') receiver_account,
      CASE WHEN (COALESCE(vs.easyslip_receiver_account,'') ~ '[xX*•]' OR NULLIF(btrim(vs.easyslip_receiver_account),'') IS NULL)
        AND NULLIF(btrim(vs.expected_bank_account),'') IS NOT NULL
        THEN COALESCE(NULLIF(btrim(vs.expected_bank_code),''),NULLIF(btrim(vs.easyslip_receiver_bank_id),''))
        ELSE NULLIF(btrim(vs.easyslip_receiver_bank_id),'') END bank_code
    FROM public.ac_verified_slips vs WHERE vs.order_id=o.id AND COALESCE(vs.is_deleted,false)=false AND vs.verified_amount>0 AND vs.easyslip_date IS NOT NULL
    UNION ALL
    SELECT CASE WHEN ms.transfer_date ~ '^\d{4}-\d{2}-\d{2}$' THEN ms.transfer_date::DATE END,NULL::TEXT,NULL::TEXT
    FROM public.ac_manual_slip_checks ms WHERE ms.order_id=o.id AND ms.status='approved'
   ) p
  ) coverage ON TRUE
  WHERE COALESCE(o.status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ')
   AND COALESCE(o.channel_code,'') NOT IN ('SPTR','FSPTR','TTTR','LZTR','PGTR','WY')
   AND o.created_at >= TIMESTAMPTZ '2026-10-01 00:00:00+07'
   AND (p_from IS NULL OR o.created_at >= p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_to IS NULL OR o.created_at < (p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_channel='' OR o.channel_code=p_channel) AND (p_method='' OR COALESCE(o.payment_method,'')=p_method)
   AND (p_search='' OR strpos(lower(o.bill_no),lower(p_search))>0)
 ), filtered AS (SELECT * FROM base WHERE p_status='all' OR reconciliation_state=p_status
   OR p_status='pending' AND reconciliation_state IN ('partial','waiting_bank','no_evidence','overpaid')),
 page AS (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT 50 OFFSET greatest(p_offset,0))
 SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'::JSONB),
  'count',(SELECT count(*) FROM filtered),'summary',(SELECT jsonb_build_object('bills',count(*),'sales',COALESCE(sum(total_amount),0),
   'bank',COALESCE(sum(bank_received),0),'certified',COALESCE(sum(certified_received),0),'cash',COALESCE(sum(certified_cash),0),'other_certified',COALESCE(sum(certified_other),0),'outstanding',COALESCE(sum(greatest(receivable_amount-bank_received-certified_received,0)),0)) FROM base),
  'channels',(SELECT COALESCE(jsonb_agg(channel_code),'[]'::JSONB) FROM (SELECT DISTINCT channel_code FROM public.or_orders WHERE COALESCE(channel_code,'') NOT IN ('SPTR','FSPTR','TTTR','LZTR','PGTR','WY') AND created_at >= TIMESTAMPTZ '2026-10-01 00:00:00+07' AND COALESCE(status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') ORDER BY channel_code) channels),
  'states',COALESCE((SELECT jsonb_object_agg(reconciliation_state,n) FROM (SELECT reconciliation_state,count(*) n FROM base GROUP BY reconciliation_state) counts),'{}'::JSONB)) INTO v_result;
 RETURN v_result;
END $_$;


--
-- Name: bank_statement_auto_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_auto_match(p_import_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  RETURN public.bank_statement_auto_match_authorized_impl(p_import_id);
END;
$$;


--
-- Name: bank_statement_auto_match_authorized_impl(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_auto_match_authorized_impl(p_import_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
  v_tx RECORD;
  v_candidate_count INTEGER;
  v_exact_count INTEGER;
  v_sender_count INTEGER;
  v_source_kind TEXT;
  v_source_id UUID;
  v_order_id UUID;
  v_is_exact BOOLEAN;
  v_sender_match BOOLEAN;
  v_matched INTEGER := 0;
  v_ambiguous INTEGER := 0;
  v_skipped INTEGER := 0;
  v_inserted INTEGER;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์กระทบยอดธนาคาร';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ac_bank_statement_imports WHERE id = p_import_id) THEN
    RAISE EXCEPTION 'ไม่พบรอบ Statement';
  END IF;

  FOR v_tx IN
    SELECT
      t.*,
      b.bank_code,
      b.account_number,
      substring(COALESCE(t.description, '') FROM 'X([0-9]{3,})') AS statement_sender_suffix
    FROM public.ac_bank_statement_transactions t
    JOIN public.bank_settings b ON b.id = t.bank_setting_id
    WHERE t.import_id = p_import_id
      AND t.credit_amount > 0
      AND t.reconciliation_status <> 'ignored'
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.transaction_id = t.id
      )
    ORDER BY t.transaction_at, t.id
    FOR UPDATE OF t SKIP LOCKED
  LOOP
    WITH candidates AS (
      SELECT
        'verified'::TEXT AS source_kind,
        s.id AS source_id,
        s.order_id,
        ABS(EXTRACT(EPOCH FROM (s.easyslip_date - v_tx.transaction_at))) AS time_diff_seconds,
        date_trunc('minute', s.easyslip_date) = date_trunc('minute', v_tx.transaction_at) AS is_exact,
        CASE
          WHEN NULLIF(v_tx.statement_sender_suffix, '') IS NULL THEN FALSE
          ELSE right(
            regexp_replace(
              COALESCE(
                s.easyslip_response #>> '{data,sender,account,bank,account}',
                s.easyslip_response #>> '{data,from,account,bank,account}',
                s.easyslip_response #>> '{data,from,account,account}',
                ''
              ),
              '\D', '', 'g'
            ),
            length(v_tx.statement_sender_suffix)
          ) = v_tx.statement_sender_suffix
        END AS sender_match
      FROM public.ac_verified_slips s
      JOIN public.or_orders o ON o.id = s.order_id
      WHERE COALESCE(s.is_deleted, false) = false
        AND NOT EXISTS (SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=o.id AND c.revoked_at IS NULL
          HAVING sum(c.amount) + COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=o.id),0) + v_tx.credit_amount > o.receivable_amount + 0.01)
        AND COALESCE(o.status, '') NOT IN ('รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก')
        AND public.bank_auto_match_order_has_capacity(o.id,v_tx.credit_amount)
        AND s.easyslip_date >= v_tx.transaction_at - INTERVAL '10 minutes'
        AND s.easyslip_date <= v_tx.transaction_at + INTERVAL '10 minutes'
        AND ABS(s.verified_amount - v_tx.credit_amount) <= 0.01
        AND (
          (
            (NULLIF(trim(s.easyslip_receiver_bank_id), '') IS NULL OR trim(s.easyslip_receiver_bank_id) = v_tx.bank_code)
            AND (
              NULLIF(regexp_replace(COALESCE(s.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
              OR right(regexp_replace(s.easyslip_receiver_account, '\D', '', 'g'), 4)
                 = right(regexp_replace(v_tx.account_number, '\D', '', 'g'), 4)
            )
          )
          OR (
            trim(COALESCE(s.expected_bank_code, '')) = v_tx.bank_code
            AND right(regexp_replace(COALESCE(s.expected_bank_account, ''), '\D', '', 'g'), 4)
                = right(regexp_replace(v_tx.account_number, '\D', '', 'g'), 4)
          )
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.ac_bank_reconciliation_allocations used
          WHERE used.verified_slip_id = s.id
        )
      UNION ALL
      SELECT
        'manual'::TEXT AS source_kind,
        m.id AS source_id,
        m.order_id,
        ABS(EXTRACT(EPOCH FROM (
          ((m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok') - v_tx.transaction_at
        ))) AS time_diff_seconds,
        date_trunc('minute', (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
          = date_trunc('minute', v_tx.transaction_at) AS is_exact,
        FALSE AS sender_match
      FROM public.ac_manual_slip_checks m
      JOIN public.or_orders o ON o.id = m.order_id
      WHERE m.status = 'approved'
        AND m.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        AND m.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        AND NOT EXISTS (SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=o.id AND c.revoked_at IS NULL
          HAVING sum(c.amount) + COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=o.id),0) + v_tx.credit_amount > o.receivable_amount + 0.01)
        AND COALESCE(o.status, '') <> 'ยกเลิก'
        AND public.bank_auto_match_order_has_capacity(o.id,v_tx.credit_amount)
        AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
              >= v_tx.transaction_at - INTERVAL '10 minutes'
        AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
              <= v_tx.transaction_at + INTERVAL '10 minutes'
        AND ABS(m.transfer_amount - v_tx.credit_amount) <= 0.01
        AND EXISTS (
          SELECT 1 FROM public.bank_settings_channels bsc
          WHERE bsc.bank_setting_id = v_tx.bank_setting_id
            AND bsc.channel_code = o.channel_code
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.ac_bank_reconciliation_allocations used
          WHERE used.manual_slip_check_id = m.id
        )
    ), stats AS (
      SELECT
        COUNT(*)::INTEGER AS candidate_count,
        COUNT(*) FILTER (WHERE is_exact)::INTEGER AS exact_count,
        COUNT(*) FILTER (WHERE sender_match)::INTEGER AS sender_count
      FROM candidates
    ), selected AS (
      SELECT c.*
      FROM candidates c
      CROSS JOIN stats s
      WHERE (s.exact_count = 1 AND c.is_exact)
         OR (s.exact_count <> 1 AND s.sender_count = 1 AND c.sender_match)
         OR (s.exact_count = 0 AND s.sender_count <> 1 AND s.candidate_count = 1)
      ORDER BY
        CASE WHEN c.is_exact THEN 0 WHEN c.sender_match THEN 1 ELSE 2 END,
        c.time_diff_seconds,
        c.source_kind,
        c.source_id
      LIMIT 1
    )
    SELECT
      stats.candidate_count,
      stats.exact_count,
      stats.sender_count,
      selected.source_kind,
      selected.source_id,
      selected.order_id,
      selected.is_exact,
      selected.sender_match
    INTO
      v_candidate_count,
      v_exact_count,
      v_sender_count,
      v_source_kind,
      v_source_id,
      v_order_id,
      v_is_exact,
      v_sender_match
    FROM stats
    LEFT JOIN selected ON TRUE;

    IF v_source_id IS NOT NULL THEN
      BEGIN
      PERFORM 1 FROM public.or_orders WHERE id=v_order_id FOR UPDATE;
      -- Recheck capacity after acquiring the same order lock as the allocation guards.
      IF NOT public.bank_auto_match_order_has_capacity(v_order_id,v_tx.credit_amount) THEN
        UPDATE public.ac_bank_statement_transactions SET reconciliation_status='unmatched' WHERE id=v_tx.id;
        v_skipped:=v_skipped+1;
        CONTINUE;
      END IF;
      INSERT INTO public.ac_bank_reconciliation_allocations (
        transaction_id, order_id, verified_slip_id, manual_slip_check_id,
        allocated_amount, match_method, matched_by
      ) VALUES (
        v_tx.id,
        v_order_id,
        CASE WHEN v_source_kind = 'verified' THEN v_source_id ELSE NULL END,
        CASE WHEN v_source_kind = 'manual' THEN v_source_id ELSE NULL END,
        v_tx.credit_amount,
        CASE
          WHEN v_source_kind = 'verified' AND v_is_exact THEN 'exact_verified_slip'
          WHEN v_source_kind = 'manual' AND v_is_exact THEN 'exact_manual_slip'
          WHEN v_source_kind = 'verified' AND v_sender_match THEN 'sender_confirmed_verified_slip'
          WHEN v_source_kind = 'verified' THEN 'time_tolerant_verified_slip'
          ELSE 'time_tolerant_manual_slip'
        END,
        auth.uid()
      ) ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_inserted=ROW_COUNT;
      IF v_inserted>0 THEN
        UPDATE public.ac_bank_statement_transactions SET reconciliation_status='matched' WHERE id=v_tx.id;
        v_matched:=v_matched+1;
      END IF;
      EXCEPTION WHEN SQLSTATE 'P0001' OR unique_violation OR check_violation THEN
        UPDATE public.ac_bank_statement_transactions SET reconciliation_status='unmatched' WHERE id=v_tx.id;
        v_skipped:=v_skipped+1;
        UPDATE public.ac_bank_statement_imports SET warnings=COALESCE(warnings,'[]'::jsonb)||jsonb_build_array(
          jsonb_build_object('code','auto_match_skipped','transaction_id',v_tx.id,'message',SQLERRM)) WHERE id=v_tx.import_id;
      END;
    ELSIF v_candidate_count > 1 THEN
      UPDATE public.ac_bank_statement_transactions
      SET reconciliation_status = 'ambiguous'
      WHERE id = v_tx.id;
      v_ambiguous := v_ambiguous + 1;
    ELSE
      UPDATE public.ac_bank_statement_transactions
      SET reconciliation_status = 'unmatched'
      WHERE id = v_tx.id;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'matched', v_matched,
    'skipped', v_skipped,
    'ambiguous', v_ambiguous,
    'time_tolerance_minutes', 10,
    'supports_split_payment', true
  );
END;
$_$;


--
-- Name: bank_statement_import(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_import(p_bank_setting_id uuid, p_file_name text, p_file_hash text, p_metadata jsonb, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  RETURN public.bank_statement_import_authorized_impl(
    p_bank_setting_id, p_file_name, p_file_hash, p_metadata, p_transactions
  );
END;
$$;


--
-- Name: bank_statement_import_authorized_impl(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_import_authorized_impl(p_bank_setting_id uuid, p_file_name text, p_file_hash text, p_metadata jsonb, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_bank public.bank_settings;
  v_import_id UUID;
  v_source_count INTEGER;
  v_inserted_count INTEGER;
  v_match_result JSONB;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์นำเข้า Statement';
  END IF;
  SELECT * INTO v_bank FROM public.bank_settings WHERE id = p_bank_setting_id AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบัญชีธนาคารที่เปิดใช้งาน'; END IF;
  IF regexp_replace(v_bank.account_number, '\D', '', 'g')
     <> regexp_replace(COALESCE(p_metadata->>'account_number', ''), '\D', '', 'g') THEN
    RAISE EXCEPTION 'เลขบัญชีในไฟล์ไม่ตรงกับบัญชีที่เลือก';
  END IF;
  IF p_transactions IS NULL OR jsonb_typeof(p_transactions) <> 'array'
     OR jsonb_array_length(p_transactions) < 1 OR jsonb_array_length(p_transactions) > 5000 THEN
    RAISE EXCEPTION 'Statement ต้องมี 1 ถึง 5,000 รายการ';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ac_bank_statement_imports
    WHERE bank_setting_id = p_bank_setting_id AND file_hash = p_file_hash
  ) THEN
    RAISE EXCEPTION 'ไฟล์ Statement นี้ถูกนำเข้าแล้ว';
  END IF;

  v_source_count := jsonb_array_length(p_transactions);
  INSERT INTO public.ac_bank_statement_imports (
    bank_setting_id, file_name, file_hash, parser_code, statement_reference,
    account_number_snapshot, account_name_snapshot, period_start, period_end,
    opening_balance, closing_balance, declared_credit_total, declared_debit_total,
    source_row_count, warnings, uploaded_by
  ) VALUES (
    p_bank_setting_id,
    NULLIF(trim(p_file_name), ''),
    p_file_hash,
    COALESCE(NULLIF(p_metadata->>'parser_code', ''), 'unknown'),
    NULLIF(p_metadata->>'statement_reference', ''),
    p_metadata->>'account_number',
    NULLIF(p_metadata->>'account_name', ''),
    (p_metadata->>'period_start')::DATE,
    (p_metadata->>'period_end')::DATE,
    NULLIF(p_metadata->>'opening_balance', '')::NUMERIC,
    NULLIF(p_metadata->>'closing_balance', '')::NUMERIC,
    NULLIF(p_metadata->>'declared_credit_total', '')::NUMERIC,
    NULLIF(p_metadata->>'declared_debit_total', '')::NUMERIC,
    v_source_count,
    COALESCE(p_metadata->'warnings', '[]'::JSONB),
    auth.uid()
  ) RETURNING id INTO v_import_id;

  INSERT INTO public.ac_bank_statement_transactions (
    import_id, bank_setting_id, source_row_number, transaction_at, effective_date,
    transaction_type, debit_amount, credit_amount, balance, channel, description,
    source_fingerprint, raw_data
  )
  SELECT
    v_import_id,
    p_bank_setting_id,
    x.source_row_number,
    x.transaction_at::TIMESTAMPTZ,
    x.effective_date::DATE,
    x.transaction_type,
    COALESCE(x.debit_amount, 0),
    COALESCE(x.credit_amount, 0),
    x.balance,
    NULLIF(x.channel, ''),
    NULLIF(x.description, ''),
    x.source_fingerprint,
    x.raw_data
  FROM jsonb_to_recordset(p_transactions) AS x(
    source_row_number INTEGER,
    transaction_at TEXT,
    effective_date TEXT,
    transaction_type TEXT,
    debit_amount NUMERIC,
    credit_amount NUMERIC,
    balance NUMERIC,
    channel TEXT,
    description TEXT,
    source_fingerprint TEXT,
    raw_data JSONB
  )
  WHERE x.source_row_number IS NOT NULL
    AND NULLIF(x.transaction_at, '') IS NOT NULL
    AND NULLIF(x.effective_date, '') IS NOT NULL
    AND NULLIF(x.transaction_type, '') IS NOT NULL
    AND NULLIF(x.source_fingerprint, '') IS NOT NULL
    AND (COALESCE(x.debit_amount, 0) > 0 OR COALESCE(x.credit_amount, 0) > 0)
  ON CONFLICT (bank_setting_id, source_fingerprint) DO NOTHING;
  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

  UPDATE public.ac_bank_statement_imports
  SET imported_row_count = v_inserted_count,
      duplicate_row_count = v_source_count - v_inserted_count
  WHERE id = v_import_id;

  -- Keep input validation atomic; isolate only the optional automatic matching stage.
  BEGIN
    v_match_result := public.bank_statement_auto_match(v_import_id);
  EXCEPTION WHEN OTHERS THEN
    v_match_result:=jsonb_build_object('matched',0,'ambiguous',0,'requires_review',true,'warning',SQLERRM);
    UPDATE public.ac_bank_statement_imports SET warnings=COALESCE(warnings,'[]'::jsonb)||jsonb_build_array(
      jsonb_build_object('code','auto_match_failed','message',SQLERRM,'action','rerun_auto_match')) WHERE id=v_import_id;
  END;
  RETURN jsonb_build_object(
    'import_id', v_import_id,
    'source_count', v_source_count,
    'inserted_count', v_inserted_count,
    'duplicate_count', v_source_count - v_inserted_count,
    'match_result', v_match_result
  );
END;
$$;


--
-- Name: bank_statement_match_candidate_lists(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_match_candidate_lists(p_import_id uuid) RETURNS TABLE(transaction_id uuid, available_candidate_count integer, allocated_candidate_count integer, available_candidates jsonb, allocated_candidates jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจสอบการกระทบยอดธนาคาร';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.ac_bank_statement_imports WHERE id = p_import_id) THEN
    RAISE EXCEPTION 'ไม่พบรอบ Statement';
  END IF;

  RETURN QUERY
  WITH tx AS (
    SELECT
      t.id,
      t.transaction_at,
      t.credit_amount,
      t.bank_setting_id,
      b.bank_code,
      b.account_number,
      substring(COALESCE(t.description, '') FROM 'X([0-9]{3,})') AS sender_suffix
    FROM public.ac_bank_statement_transactions t
    JOIN public.bank_settings b ON b.id = t.bank_setting_id
    WHERE t.import_id = p_import_id
      AND t.credit_amount > 0
      AND t.reconciliation_status IN ('unmatched', 'ambiguous')
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations a
        WHERE a.transaction_id = t.id
      )
  ), candidate_base AS (
    SELECT
      t.id AS transaction_id,
      'verified_slip'::TEXT AS source_type,
      s.id AS source_id,
      s.order_id,
      o.bill_no,
      o.created_at AS bill_created_at,
      s.easyslip_date AS payment_at,
      s.verified_amount AS paid_amount,
      'approved'::TEXT AS source_status,
      (
        (
          (NULLIF(trim(s.easyslip_receiver_bank_id), '') IS NULL OR trim(s.easyslip_receiver_bank_id) = t.bank_code)
          AND (
            NULLIF(regexp_replace(COALESCE(s.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
            OR right(regexp_replace(s.easyslip_receiver_account, '\D', '', 'g'), 4)
               = right(regexp_replace(t.account_number, '\D', '', 'g'), 4)
          )
        )
        OR (
          trim(COALESCE(s.expected_bank_code, '')) = t.bank_code
          AND right(regexp_replace(COALESCE(s.expected_bank_account, ''), '\D', '', 'g'), 4)
              = right(regexp_replace(t.account_number, '\D', '', 'g'), 4)
        )
      ) AS account_match,
      CASE
        WHEN NULLIF(t.sender_suffix, '') IS NULL THEN FALSE
        ELSE right(
          regexp_replace(
            COALESCE(
              s.easyslip_response #>> '{data,sender,account,bank,account}',
              s.easyslip_response #>> '{data,from,account,bank,account}',
              s.easyslip_response #>> '{data,from,account,account}',
              ''
            ),
            '\D', '', 'g'
          ),
          length(t.sender_suffix)
        ) = t.sender_suffix
      END AS sender_match,
      (used.id IS NOT NULL) AS already_allocated,
      ABS(EXTRACT(EPOCH FROM (s.easyslip_date - t.transaction_at))) / 60.0 AS time_diff_minutes,
      ABS(EXTRACT(EPOCH FROM (s.easyslip_date - t.transaction_at))) <= 600 AS within_auto_window,
      (COALESCE(s.is_deleted, FALSE) = FALSE AND COALESCE(o.status, '') <> 'ยกเลิก') AS usable
    FROM tx t
    JOIN public.ac_verified_slips s
      ON s.easyslip_date >= t.transaction_at - INTERVAL '7 days'
     AND s.easyslip_date <= t.transaction_at + INTERVAL '7 days'
     AND ABS(s.verified_amount - t.credit_amount) <= 0.01
    JOIN public.or_orders o ON o.id = s.order_id
    LEFT JOIN public.ac_bank_reconciliation_allocations used ON used.verified_slip_id = s.id

    UNION ALL

    SELECT
      t.id AS transaction_id,
      'manual_slip'::TEXT AS source_type,
      m.id AS source_id,
      m.order_id,
      o.bill_no,
      o.created_at AS bill_created_at,
      (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' AS payment_at,
      m.transfer_amount AS paid_amount,
      m.status AS source_status,
      EXISTS (
        SELECT 1 FROM public.bank_settings_channels bsc
        WHERE bsc.bank_setting_id = t.bank_setting_id
          AND bsc.channel_code = o.channel_code
      ) AS account_match,
      FALSE AS sender_match,
      (used.id IS NOT NULL) AS already_allocated,
      ABS(EXTRACT(EPOCH FROM (
        (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' - t.transaction_at
      ))) / 60.0 AS time_diff_minutes,
      ABS(EXTRACT(EPOCH FROM (
        (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' - t.transaction_at
      ))) <= 600 AS within_auto_window,
      (m.status = 'approved' AND COALESCE(o.status, '') <> 'ยกเลิก') AS usable
    FROM tx t
    JOIN public.ac_manual_slip_checks m
      ON m.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     AND m.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
          >= t.transaction_at - INTERVAL '7 days'
     AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
          <= t.transaction_at + INTERVAL '7 days'
     AND ABS(m.transfer_amount - t.credit_amount) <= 0.01
    JOIN public.or_orders o ON o.id = m.order_id
    LEFT JOIN public.ac_bank_reconciliation_allocations used ON used.manual_slip_check_id = m.id
  ), eligible AS (
    SELECT *
    FROM candidate_base
    WHERE account_match AND usable
  ), ranked AS (
    SELECT
      candidate.*,
      ROW_NUMBER() OVER (
        PARTITION BY candidate.transaction_id, candidate.already_allocated
        ORDER BY
          CASE WHEN candidate.within_auto_window THEN 0 ELSE 1 END,
          CASE WHEN candidate.sender_match THEN 0 ELSE 1 END,
          candidate.time_diff_minutes,
          candidate.source_id
      ) AS list_rank
    FROM eligible candidate
  ), stats AS (
    SELECT
      t.id AS transaction_id,
      COUNT(r.source_id) FILTER (WHERE NOT r.already_allocated)::INTEGER AS available_count,
      COUNT(r.source_id) FILTER (WHERE r.already_allocated)::INTEGER AS allocated_count
    FROM tx t
    LEFT JOIN ranked r ON r.transaction_id = t.id
    GROUP BY t.id
  ), candidate_json AS (
    SELECT
      r.transaction_id,
      jsonb_agg(
        jsonb_build_object(
          'source_type', r.source_type,
          'source_id', r.source_id,
          'order_id', r.order_id,
          'bill_no', r.bill_no,
          'bill_created_at', r.bill_created_at,
          'payment_at', r.payment_at,
          'paid_amount', r.paid_amount,
          'source_status', r.source_status,
          'account_match', r.account_match,
          'sender_match', r.sender_match,
          'already_allocated', r.already_allocated,
          'within_auto_window', r.within_auto_window,
          'time_diff_minutes', round(r.time_diff_minutes::NUMERIC, 1),
          'payment_before_bill_hours', round((EXTRACT(EPOCH FROM (r.bill_created_at - r.payment_at)) / 3600.0)::NUMERIC, 1)
        ) ORDER BY r.list_rank
      ) FILTER (WHERE NOT r.already_allocated AND r.list_rank <= 5) AS available_candidates,
      jsonb_agg(
        jsonb_build_object(
          'source_type', r.source_type,
          'source_id', r.source_id,
          'order_id', r.order_id,
          'bill_no', r.bill_no,
          'bill_created_at', r.bill_created_at,
          'payment_at', r.payment_at,
          'paid_amount', r.paid_amount,
          'source_status', r.source_status,
          'account_match', r.account_match,
          'sender_match', r.sender_match,
          'already_allocated', r.already_allocated,
          'within_auto_window', r.within_auto_window,
          'time_diff_minutes', round(r.time_diff_minutes::NUMERIC, 1),
          'payment_before_bill_hours', round((EXTRACT(EPOCH FROM (r.bill_created_at - r.payment_at)) / 3600.0)::NUMERIC, 1)
        ) ORDER BY r.list_rank
      ) FILTER (WHERE r.already_allocated AND r.list_rank <= 5) AS allocated_candidates
    FROM ranked r
    GROUP BY r.transaction_id
  )
  SELECT
    stats.transaction_id,
    stats.available_count,
    stats.allocated_count,
    COALESCE(candidate_json.available_candidates, '[]'::JSONB),
    COALESCE(candidate_json.allocated_candidates, '[]'::JSONB)
  FROM stats
  LEFT JOIN candidate_json ON candidate_json.transaction_id = stats.transaction_id
  ORDER BY stats.transaction_id;
END;
$_$;


--
-- Name: FUNCTION bank_statement_match_candidate_lists(p_import_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bank_statement_match_candidate_lists(p_import_id uuid) IS 'Separates selectable nearby payment candidates from already allocated audit-only candidates.';


--
-- Name: bank_statement_match_diagnostics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_match_diagnostics(p_import_id uuid) RETURNS TABLE(transaction_id uuid, reason_code text, candidate_count integer, candidates jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.bank_reconciliation_require_authorized_role();
  RETURN QUERY SELECT * FROM public.bank_statement_match_diagnostics_authorized_impl(p_import_id);
END;
$$;


--
-- Name: bank_statement_match_diagnostics_authorized_impl(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_match_diagnostics_authorized_impl(p_import_id uuid) RETURNS TABLE(transaction_id uuid, reason_code text, candidate_count integer, candidates jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจสอบการกระทบยอดธนาคาร';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.ac_bank_statement_imports WHERE id = p_import_id) THEN
    RAISE EXCEPTION 'ไม่พบรอบ Statement';
  END IF;

  RETURN QUERY
  WITH tx AS (
    SELECT
      t.id,
      t.transaction_at,
      t.credit_amount,
      t.bank_setting_id,
      b.bank_code,
      b.account_number,
      substring(COALESCE(t.description, '') FROM 'X([0-9]{3,})') AS sender_suffix
    FROM public.ac_bank_statement_transactions t
    JOIN public.bank_settings b ON b.id = t.bank_setting_id
    WHERE t.import_id = p_import_id
      AND t.credit_amount > 0
      AND t.reconciliation_status IN ('unmatched', 'ambiguous')
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations a
        WHERE a.transaction_id = t.id
      )
  ), candidate_base AS (
    SELECT
      t.id AS transaction_id,
      'verified_slip'::TEXT AS source_type,
      s.id AS source_id,
      s.order_id,
      o.bill_no,
      o.created_at AS bill_created_at,
      s.easyslip_date AS payment_at,
      s.verified_amount AS paid_amount,
      'approved'::TEXT AS source_status,
      (
        (
          (NULLIF(trim(s.easyslip_receiver_bank_id), '') IS NULL OR trim(s.easyslip_receiver_bank_id) = t.bank_code)
          AND (
            NULLIF(regexp_replace(COALESCE(s.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
            OR right(regexp_replace(s.easyslip_receiver_account, '\D', '', 'g'), 4)
               = right(regexp_replace(t.account_number, '\D', '', 'g'), 4)
          )
        )
        OR (
          trim(COALESCE(s.expected_bank_code, '')) = t.bank_code
          AND right(regexp_replace(COALESCE(s.expected_bank_account, ''), '\D', '', 'g'), 4)
              = right(regexp_replace(t.account_number, '\D', '', 'g'), 4)
        )
      ) AS account_match,
      CASE
        WHEN NULLIF(t.sender_suffix, '') IS NULL THEN FALSE
        ELSE right(
          regexp_replace(
            COALESCE(
              s.easyslip_response #>> '{data,sender,account,bank,account}',
              s.easyslip_response #>> '{data,from,account,bank,account}',
              s.easyslip_response #>> '{data,from,account,account}',
              ''
            ),
            '\D', '', 'g'
          ),
          length(t.sender_suffix)
        ) = t.sender_suffix
      END AS sender_match,
      (used.id IS NOT NULL) AS already_allocated,
      ABS(EXTRACT(EPOCH FROM (s.easyslip_date - t.transaction_at))) / 60.0 AS time_diff_minutes,
      ABS(EXTRACT(EPOCH FROM (s.easyslip_date - t.transaction_at))) <= 600 AS within_auto_window,
      (COALESCE(s.is_deleted, FALSE) = FALSE AND COALESCE(o.status, '') <> 'ยกเลิก') AS usable
    FROM tx t
    JOIN public.ac_verified_slips s
      ON s.easyslip_date >= t.transaction_at - INTERVAL '7 days'
     AND s.easyslip_date <= t.transaction_at + INTERVAL '7 days'
     AND ABS(s.verified_amount - t.credit_amount) <= 0.01
    JOIN public.or_orders o ON o.id = s.order_id
    LEFT JOIN public.ac_bank_reconciliation_allocations used ON used.verified_slip_id = s.id

    UNION ALL

    SELECT
      t.id AS transaction_id,
      'manual_slip'::TEXT AS source_type,
      m.id AS source_id,
      m.order_id,
      o.bill_no,
      o.created_at AS bill_created_at,
      (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' AS payment_at,
      m.transfer_amount AS paid_amount,
      m.status AS source_status,
      EXISTS (
        SELECT 1 FROM public.bank_settings_channels bsc
        WHERE bsc.bank_setting_id = t.bank_setting_id
          AND bsc.channel_code = o.channel_code
      ) AS account_match,
      FALSE AS sender_match,
      (used.id IS NOT NULL) AS already_allocated,
      ABS(EXTRACT(EPOCH FROM (
        (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' - t.transaction_at
      ))) / 60.0 AS time_diff_minutes,
      ABS(EXTRACT(EPOCH FROM (
        (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok' - t.transaction_at
      ))) <= 600 AS within_auto_window,
      (m.status = 'approved' AND COALESCE(o.status, '') <> 'ยกเลิก') AS usable
    FROM tx t
    JOIN public.ac_manual_slip_checks m
      ON m.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     AND m.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
          >= t.transaction_at - INTERVAL '7 days'
     AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
          <= t.transaction_at + INTERVAL '7 days'
     AND ABS(m.transfer_amount - t.credit_amount) <= 0.01
    JOIN public.or_orders o ON o.id = m.order_id
    LEFT JOIN public.ac_bank_reconciliation_allocations used ON used.manual_slip_check_id = m.id
  ), ranked AS (
    SELECT
      c.*,
      row_number() OVER (
        PARTITION BY c.transaction_id
        ORDER BY
          CASE WHEN c.within_auto_window THEN 0 ELSE 1 END,
          CASE WHEN c.account_match THEN 0 ELSE 1 END,
          CASE WHEN c.sender_match THEN 0 ELSE 1 END,
          c.time_diff_minutes,
          c.source_id
      ) AS candidate_rank
    FROM candidate_base c
  ), stats AS (
    SELECT
      t.id AS transaction_id,
      COUNT(r.source_id)::INTEGER AS candidate_count,
      COUNT(r.source_id) FILTER (WHERE r.account_match)::INTEGER AS account_match_count,
      COUNT(r.source_id) FILTER (WHERE r.account_match AND r.usable)::INTEGER AS usable_count,
      COUNT(r.source_id) FILTER (WHERE r.account_match AND r.usable AND r.already_allocated)::INTEGER AS allocated_count,
      COUNT(r.source_id) FILTER (
        WHERE r.account_match AND r.usable AND NOT r.already_allocated AND r.within_auto_window
      )::INTEGER AS auto_candidate_count
    FROM tx t
    LEFT JOIN ranked r ON r.transaction_id = t.id
    GROUP BY t.id
  ), candidate_json AS (
    SELECT
      r.transaction_id,
      jsonb_agg(
        jsonb_build_object(
          'source_type', r.source_type,
          'source_id', r.source_id,
          'order_id', r.order_id,
          'bill_no', r.bill_no,
          'bill_created_at', r.bill_created_at,
          'payment_at', r.payment_at,
          'paid_amount', r.paid_amount,
          'source_status', r.source_status,
          'account_match', r.account_match,
          'sender_match', r.sender_match,
          'already_allocated', r.already_allocated,
          'within_auto_window', r.within_auto_window,
          'time_diff_minutes', round(r.time_diff_minutes::NUMERIC, 1),
          'payment_before_bill_hours', round((EXTRACT(EPOCH FROM (r.bill_created_at - r.payment_at)) / 3600.0)::NUMERIC, 1)
        ) ORDER BY r.candidate_rank
      ) FILTER (WHERE r.candidate_rank <= 5) AS candidates
    FROM ranked r
    GROUP BY r.transaction_id
  )
  SELECT
    s.transaction_id,
    CASE
      WHEN s.candidate_count = 0 THEN 'no_same_amount_slip'
      WHEN s.account_match_count = 0 THEN 'receiver_account_mismatch'
      WHEN s.usable_count = 0 THEN 'slip_not_ready'
      WHEN s.allocated_count = s.usable_count THEN 'slip_already_allocated'
      WHEN s.auto_candidate_count = 0 THEN 'outside_time_window'
      WHEN s.auto_candidate_count > 1 THEN 'multiple_candidates'
      ELSE 'rerun_auto_match'
    END AS reason_code,
    s.candidate_count,
    COALESCE(j.candidates, '[]'::JSONB) AS candidates
  FROM stats s
  LEFT JOIN candidate_json j ON j.transaction_id = s.transaction_id
  ORDER BY s.transaction_id;
END;
$_$;


--
-- Name: FUNCTION bank_statement_match_diagnostics_authorized_impl(p_import_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bank_statement_match_diagnostics_authorized_impl(p_import_id uuid) IS 'Explains unmatched bank credits using slip transfer time, not order creation time.';


--
-- Name: bank_statement_workspace(date, date, uuid, text, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_workspace(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_bank uuid DEFAULT NULL::uuid, p_status text DEFAULT 'all'::text, p_search text DEFAULT ''::text, p_offset integer DEFAULT 0, p_include_debits boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 WITH base AS (SELECT t.*,b.bank_name,b.account_number,r.rule_name,r.match_keyword,
  COALESCE(r.is_active AND (r.bank_setting_id IS NULL OR r.bank_setting_id=t.bank_setting_id)
   AND strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(btrim(r.match_keyword)))>0,false) rule_valid
  FROM public.ac_bank_statement_transactions t JOIN public.bank_settings b ON b.id=t.bank_setting_id
  LEFT JOIN public.ac_bank_transaction_rules r ON r.id=t.classification_rule_id
  WHERE (p_include_debits OR t.credit_amount>0) AND (p_from IS NULL OR t.transaction_at>=p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_to IS NULL OR t.transaction_at<(p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_bank IS NULL OR t.bank_setting_id=p_bank)
   AND (p_search='' OR strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(p_search))>0)),
 filtered AS (SELECT * FROM base WHERE p_status='all' OR reconciliation_status=p_status),
 page AS (SELECT * FROM filtered ORDER BY transaction_at DESC,id LIMIT 100 OFFSET greatest(p_offset,0))
 SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'::JSONB),
  'count',(SELECT count(*) FROM filtered),'summary',(SELECT jsonb_build_object('credit',COALESCE(sum(credit_amount),0),
   'matched',COALESCE(sum(credit_amount) FILTER(WHERE reconciliation_status='matched'),0),
   'other',COALESCE(sum(credit_amount) FILTER(WHERE reconciliation_status='ignored'),0),
   'unmatchedCount',count(*) FILTER(WHERE credit_amount>0 AND reconciliation_status='unmatched'),
   'ambiguousCount',count(*) FILTER(WHERE credit_amount>0 AND reconciliation_status='ambiguous')) FROM base)) INTO v_result;
 RETURN v_result;
END $$;


--
-- Name: bank_sync_manual_verified_twins(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_sync_manual_verified_twins(p_order_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_pair RECORD;
  v_updated INTEGER := 0;
  v_rows INTEGER := 0;
BEGIN
  FOR v_pair IN
    WITH candidates AS (
      SELECT
        m.id AS manual_id,
        m.order_id,
        s.id AS verified_id,
        ABS(EXTRACT(EPOCH FROM (
          ((m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
          - s.easyslip_date
        ))) AS diff_seconds
      FROM public.ac_manual_slip_checks m
      JOIN public.ac_verified_slips s
        ON s.order_id = m.order_id
       AND COALESCE(s.is_deleted, FALSE) = FALSE
       AND s.easyslip_date IS NOT NULL
       AND ABS(s.verified_amount - m.transfer_amount) <= 0.01
       AND s.easyslip_date >= ((m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok') - INTERVAL '10 minutes'
       AND s.easyslip_date <= ((m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok') + INTERVAL '10 minutes'
       AND (
         s.validation_status = 'passed'
         OR EXISTS (
           SELECT 1 FROM public.ac_bank_reconciliation_allocations allocation
           WHERE allocation.verified_slip_id = s.id
         )
       )
      WHERE m.status = 'approved'
        AND (p_order_id IS NULL OR m.order_id = p_order_id)
        AND m.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        AND m.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        AND NOT EXISTS (
          SELECT 1 FROM public.ac_manual_slip_easyslip_retries retry
          WHERE retry.status = 'passed'
            AND (retry.matched_manual_slip_id = m.id OR retry.verified_slip_id = s.id)
        )
    ), ranked AS (
      SELECT
        candidate.*,
        ROW_NUMBER() OVER (
          PARTITION BY candidate.manual_id
          ORDER BY candidate.diff_seconds, candidate.verified_id
        ) AS manual_rank,
        ROW_NUMBER() OVER (
          PARTITION BY candidate.verified_id
          ORDER BY candidate.diff_seconds, candidate.manual_id
        ) AS verified_rank
      FROM candidates candidate
    )
    SELECT * FROM ranked
    WHERE manual_rank = 1 AND verified_rank = 1
    ORDER BY diff_seconds, manual_id
  LOOP
    BEGIN
      INSERT INTO public.ac_manual_slip_easyslip_retries (
        order_id,
        requested_manual_slip_id,
        matched_manual_slip_id,
        verified_slip_id,
        status,
        checked_at,
        checked_by,
        error_message
      ) VALUES (
        v_pair.order_id,
        v_pair.manual_id,
        v_pair.manual_id,
        v_pair.verified_id,
        'passed',
        now(),
        auth.uid(),
        NULL
      )
      ON CONFLICT (verified_slip_id) DO UPDATE
      SET matched_manual_slip_id = EXCLUDED.matched_manual_slip_id,
          status = 'passed',
          checked_at = now(),
          checked_by = auth.uid(),
          error_message = NULL
      WHERE public.ac_manual_slip_easyslip_retries.status = 'failed';

      UPDATE public.ac_manual_slip_checks
      SET status = 'verified_by_easyslip',
          easyslip_retry_status = 'passed',
          easyslip_retry_checked_at = now(),
          easyslip_retry_checked_by = auth.uid(),
          easyslip_retry_error = NULL
      WHERE id = v_pair.manual_id
        AND status = 'approved'
        AND EXISTS (
          SELECT 1 FROM public.ac_manual_slip_easyslip_retries retry
          WHERE retry.matched_manual_slip_id = v_pair.manual_id
            AND retry.verified_slip_id = v_pair.verified_id
            AND retry.status = 'passed'
        );
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_updated := v_updated + v_rows;
    EXCEPTION WHEN unique_violation THEN
      -- A concurrent sync already claimed one side of this pair.
      NULL;
    END;
  END LOOP;

  RETURN v_updated;
END;
$_$;


--
-- Name: bank_workspace_auto_match(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_workspace_auto_match(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_bank uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
  v_tx RECORD;
  v_candidate_count INTEGER;
  v_exact_count INTEGER;
  v_sender_count INTEGER;
  v_source_kind TEXT;
  v_source_id UUID;
  v_order_id UUID;
  v_is_exact BOOLEAN;
  v_sender_match BOOLEAN;
  v_matched INTEGER := 0;
  v_ambiguous INTEGER := 0;
  v_skipped INTEGER := 0;
  v_inserted INTEGER;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์กระทบยอดธนาคาร';
  END IF;
  PERFORM public.bank_reconciliation_require_authorized_role();

  FOR v_tx IN
    SELECT
      t.*,
      b.bank_code,
      b.account_number,
      substring(COALESCE(t.description, '') FROM 'X([0-9]{3,})') AS statement_sender_suffix
    FROM public.ac_bank_statement_transactions t
    JOIN public.bank_settings b ON b.id = t.bank_setting_id
    WHERE (p_from IS NULL OR t.transaction_at >= p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
      AND (p_to IS NULL OR t.transaction_at < (p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
      AND (p_bank IS NULL OR t.bank_setting_id=p_bank)
      AND t.credit_amount > 0
      AND t.reconciliation_status <> 'ignored'
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.transaction_id = t.id
      )
    ORDER BY t.transaction_at, t.id
    FOR UPDATE OF t SKIP LOCKED
  LOOP
    WITH candidates AS (
      SELECT
        'verified'::TEXT AS source_kind,
        s.id AS source_id,
        s.order_id,
        ABS(EXTRACT(EPOCH FROM (s.easyslip_date - v_tx.transaction_at))) AS time_diff_seconds,
        date_trunc('minute', s.easyslip_date) = date_trunc('minute', v_tx.transaction_at) AS is_exact,
        CASE
          WHEN NULLIF(v_tx.statement_sender_suffix, '') IS NULL THEN FALSE
          ELSE right(
            regexp_replace(
              COALESCE(
                s.easyslip_response #>> '{data,sender,account,bank,account}',
                s.easyslip_response #>> '{data,from,account,bank,account}',
                s.easyslip_response #>> '{data,from,account,account}',
                ''
              ),
              '\D', '', 'g'
            ),
            length(v_tx.statement_sender_suffix)
          ) = v_tx.statement_sender_suffix
        END AS sender_match
      FROM public.ac_verified_slips s
      JOIN public.or_orders o ON o.id = s.order_id
      WHERE COALESCE(s.is_deleted, false) = false
        AND NOT EXISTS (SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=o.id AND c.revoked_at IS NULL
          HAVING sum(c.amount) + COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=o.id),0) + v_tx.credit_amount > o.receivable_amount + 0.01)
        AND COALESCE(o.status, '') NOT IN ('รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก')
        AND public.bank_auto_match_order_has_capacity(o.id,v_tx.credit_amount)
        AND s.easyslip_date >= v_tx.transaction_at - INTERVAL '10 minutes'
        AND s.easyslip_date <= v_tx.transaction_at + INTERVAL '10 minutes'
        AND ABS(s.verified_amount - v_tx.credit_amount) <= 0.01
        AND (
          (
            (NULLIF(trim(s.easyslip_receiver_bank_id), '') IS NULL OR trim(s.easyslip_receiver_bank_id) = v_tx.bank_code)
            AND (
              NULLIF(regexp_replace(COALESCE(s.easyslip_receiver_account, ''), '\D', '', 'g'), '') IS NULL
              OR right(regexp_replace(s.easyslip_receiver_account, '\D', '', 'g'), 4)
                 = right(regexp_replace(v_tx.account_number, '\D', '', 'g'), 4)
            )
          )
          OR (
            trim(COALESCE(s.expected_bank_code, '')) = v_tx.bank_code
            AND right(regexp_replace(COALESCE(s.expected_bank_account, ''), '\D', '', 'g'), 4)
                = right(regexp_replace(v_tx.account_number, '\D', '', 'g'), 4)
          )
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.ac_bank_reconciliation_allocations used
          WHERE used.verified_slip_id = s.id
        )
      UNION ALL
      SELECT
        'manual'::TEXT AS source_kind,
        m.id AS source_id,
        m.order_id,
        ABS(EXTRACT(EPOCH FROM (
          ((m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok') - v_tx.transaction_at
        ))) AS time_diff_seconds,
        date_trunc('minute', (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
          = date_trunc('minute', v_tx.transaction_at) AS is_exact,
        FALSE AS sender_match
      FROM public.ac_manual_slip_checks m
      JOIN public.or_orders o ON o.id = m.order_id
      WHERE m.status = 'approved'
        AND m.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        AND m.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        AND NOT EXISTS (SELECT 1 FROM public.ac_order_receipt_certifications c WHERE c.order_id=o.id AND c.revoked_at IS NULL
          HAVING sum(c.amount) + COALESCE((SELECT sum(a.allocated_amount) FROM public.ac_bank_reconciliation_allocations a WHERE a.order_id=o.id),0) + v_tx.credit_amount > o.receivable_amount + 0.01)
        AND COALESCE(o.status, '') <> 'ยกเลิก'
        AND public.bank_auto_match_order_has_capacity(o.id,v_tx.credit_amount)
        AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
              >= v_tx.transaction_at - INTERVAL '10 minutes'
        AND (m.transfer_date || ' ' || m.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
              <= v_tx.transaction_at + INTERVAL '10 minutes'
        AND ABS(m.transfer_amount - v_tx.credit_amount) <= 0.01
        AND EXISTS (
          SELECT 1 FROM public.bank_settings_channels bsc
          WHERE bsc.bank_setting_id = v_tx.bank_setting_id
            AND bsc.channel_code = o.channel_code
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.ac_bank_reconciliation_allocations used
          WHERE used.manual_slip_check_id = m.id
        )
    ), stats AS (
      SELECT
        COUNT(*)::INTEGER AS candidate_count,
        COUNT(*) FILTER (WHERE is_exact)::INTEGER AS exact_count,
        COUNT(*) FILTER (WHERE sender_match)::INTEGER AS sender_count
      FROM candidates
    ), selected AS (
      SELECT c.*
      FROM candidates c
      CROSS JOIN stats s
      WHERE (s.exact_count = 1 AND c.is_exact)
         OR (s.exact_count <> 1 AND s.sender_count = 1 AND c.sender_match)
         OR (s.exact_count = 0 AND s.sender_count <> 1 AND s.candidate_count = 1)
      ORDER BY
        CASE WHEN c.is_exact THEN 0 WHEN c.sender_match THEN 1 ELSE 2 END,
        c.time_diff_seconds,
        c.source_kind,
        c.source_id
      LIMIT 1
    )
    SELECT
      stats.candidate_count,
      stats.exact_count,
      stats.sender_count,
      selected.source_kind,
      selected.source_id,
      selected.order_id,
      selected.is_exact,
      selected.sender_match
    INTO
      v_candidate_count,
      v_exact_count,
      v_sender_count,
      v_source_kind,
      v_source_id,
      v_order_id,
      v_is_exact,
      v_sender_match
    FROM stats
    LEFT JOIN selected ON TRUE;

    IF v_source_id IS NOT NULL THEN
      BEGIN
      PERFORM 1 FROM public.or_orders WHERE id=v_order_id FOR UPDATE;
      -- Recheck capacity after acquiring the same order lock as the allocation guards.
      IF NOT public.bank_auto_match_order_has_capacity(v_order_id,v_tx.credit_amount) THEN
        UPDATE public.ac_bank_statement_transactions SET reconciliation_status='unmatched' WHERE id=v_tx.id;
        v_skipped:=v_skipped+1;
        CONTINUE;
      END IF;
      INSERT INTO public.ac_bank_reconciliation_allocations (
        transaction_id, order_id, verified_slip_id, manual_slip_check_id,
        allocated_amount, match_method, matched_by
      ) VALUES (
        v_tx.id,
        v_order_id,
        CASE WHEN v_source_kind = 'verified' THEN v_source_id ELSE NULL END,
        CASE WHEN v_source_kind = 'manual' THEN v_source_id ELSE NULL END,
        v_tx.credit_amount,
        CASE
          WHEN v_source_kind = 'verified' AND v_is_exact THEN 'exact_verified_slip'
          WHEN v_source_kind = 'manual' AND v_is_exact THEN 'exact_manual_slip'
          WHEN v_source_kind = 'verified' AND v_sender_match THEN 'sender_confirmed_verified_slip'
          WHEN v_source_kind = 'verified' THEN 'time_tolerant_verified_slip'
          ELSE 'time_tolerant_manual_slip'
        END,
        auth.uid()
      ) ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_inserted=ROW_COUNT;
      IF v_inserted>0 THEN
        UPDATE public.ac_bank_statement_transactions SET reconciliation_status='matched' WHERE id=v_tx.id;
        v_matched:=v_matched+1;
      END IF;
      EXCEPTION WHEN SQLSTATE 'P0001' OR unique_violation OR check_violation THEN
        UPDATE public.ac_bank_statement_transactions SET reconciliation_status='unmatched' WHERE id=v_tx.id;
        v_skipped:=v_skipped+1;
        UPDATE public.ac_bank_statement_imports SET warnings=COALESCE(warnings,'[]'::jsonb)||jsonb_build_array(
          jsonb_build_object('code','auto_match_skipped','transaction_id',v_tx.id,'message',SQLERRM)) WHERE id=v_tx.import_id;
      END;
    ELSIF v_candidate_count > 1 THEN
      UPDATE public.ac_bank_statement_transactions
      SET reconciliation_status = 'ambiguous'
      WHERE id = v_tx.id;
      v_ambiguous := v_ambiguous + 1;
    ELSE
      UPDATE public.ac_bank_statement_transactions
      SET reconciliation_status = 'unmatched'
      WHERE id = v_tx.id;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'matched', v_matched,
    'skipped', v_skipped,
    'ambiguous', v_ambiguous,
    'time_tolerance_minutes', 10,
    'supports_split_payment', true
  );
END;
$_$;


--
-- Name: bank_workspace_diagnostics(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_workspace_diagnostics(p_transaction_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_diagnostics JSONB; v_candidates JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::JSONB) INTO v_diagnostics
 FROM (SELECT DISTINCT import_id FROM public.ac_bank_statement_transactions WHERE id=ANY(p_transaction_ids)) i
 CROSS JOIN LATERAL public.bank_statement_match_diagnostics(i.import_id) d WHERE d.transaction_id=ANY(p_transaction_ids);
 SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::JSONB) INTO v_candidates
 FROM (SELECT DISTINCT import_id FROM public.ac_bank_statement_transactions WHERE id=ANY(p_transaction_ids)) i
 CROSS JOIN LATERAL public.bank_statement_match_candidate_lists(i.import_id) d WHERE d.transaction_id=ANY(p_transaction_ids);
 RETURN jsonb_build_object('diagnostics',v_diagnostics,'candidates',v_candidates);
END $$;


--
-- Name: bulk_adjust_stock(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_adjust_stock(items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role          TEXT;
  item            JSONB;
  v_product_id    UUID;
  v_qty_delta     NUMERIC(12,2);
  v_movement_type TEXT;
  v_ref_type      TEXT;
  v_ref_id        UUID;
  v_note          TEXT;
  v_movement_id   UUID;
  v_avg_cost      NUMERIC;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR (
    v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'manager', 'store')
    AND NOT (
      v_role = 'account'
      AND current_setting('app.inventory_adjustment_approval', true) = 'on'
    )
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปรับสต๊อค (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(items)
  LOOP
    v_product_id    := (item->>'product_id')::UUID;
    v_qty_delta     := (item->>'qty_delta')::NUMERIC;
    v_movement_type := item->>'movement_type';
    v_ref_type      := item->>'ref_type';
    v_ref_id        := CASE WHEN item->>'ref_id' IS NOT NULL THEN (item->>'ref_id')::UUID ELSE NULL END;
    v_note          := item->>'note';

    INSERT INTO inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    VALUES (v_product_id, v_qty_delta, 0, 0)
    ON CONFLICT (product_id) DO UPDATE
      SET on_hand = inv_stock_balances.on_hand + v_qty_delta;

    v_avg_cost := fn_get_current_avg_cost(v_product_id);

    IF v_qty_delta > 0 THEN
      INSERT INTO inv_stock_movements (
        product_id, movement_type, qty, ref_type, ref_id, note, unit_cost, total_cost
      )
      VALUES (
        v_product_id, v_movement_type, v_qty_delta, v_ref_type, v_ref_id, v_note,
        v_avg_cost, v_qty_delta * v_avg_cost
      );

      INSERT INTO inv_stock_lots (
        product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id
      )
      VALUES (
        v_product_id, v_qty_delta, v_qty_delta, v_avg_cost, COALESCE(v_ref_type, 'inv_adjustments'), v_ref_id
      );
    ELSIF v_qty_delta < 0 THEN
      INSERT INTO inv_stock_movements (product_id, movement_type, qty, ref_type, ref_id, note)
      VALUES (v_product_id, v_movement_type, v_qty_delta, v_ref_type, v_ref_id, v_note)
      RETURNING id INTO v_movement_id;

      PERFORM fn_consume_stock_fifo(v_product_id, ABS(v_qty_delta), v_movement_id);
    ELSE
      INSERT INTO inv_stock_movements (
        product_id, movement_type, qty, ref_type, ref_id, note, unit_cost, total_cost
      )
      VALUES (v_product_id, v_movement_type, 0, v_ref_type, v_ref_id, v_note, 0, 0);
    END IF;

    PERFORM fn_recalc_product_landed_cost(v_product_id);
  END LOOP;
END;
$$;


--
-- Name: bulk_update_order_point(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_update_order_point(items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  item JSONB;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin-tr', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ order point (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(items)
  LOOP
    UPDATE pr_products
    SET order_point = item->>'order_point'
    WHERE id = (item->>'product_id')::UUID;
  END LOOP;
END;
$$;


--
-- Name: bulk_update_safety_stock(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_update_safety_stock(items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role        TEXT;
  item          JSONB;
  v_product_id  UUID;
  v_new_safety  NUMERIC;
  v_current     NUMERIC;
  v_delta       NUMERIC;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR (
    v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'manager', 'store')
    AND NOT (
      v_role = 'account'
      AND current_setting('app.inventory_adjustment_approval', true) = 'on'
    )
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ safety stock (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(items)
  LOOP
    v_product_id := (item->>'product_id')::UUID;
    v_new_safety := (item->>'safety_stock')::NUMERIC;

    SELECT COALESCE(safety_stock, 0)
    INTO v_current
    FROM inv_stock_balances
    WHERE product_id = v_product_id;

    IF NOT FOUND THEN
      v_current := 0;
    END IF;

    v_delta := v_new_safety - v_current;

    IF v_delta > 0 THEN
      PERFORM fn_transfer_to_safety_stock(v_product_id, v_delta);
    ELSIF v_delta < 0 THEN
      PERFORM fn_release_safety_stock(v_product_id, ABS(v_delta));
    END IF;

    PERFORM fn_recalc_product_landed_cost(v_product_id);
  END LOOP;
END;
$$;


--
-- Name: calc_avg_daily_sales(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_avg_daily_sales(p_from_date date) RETURNS TABLE(product_id uuid, total_sold numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT
    oi.product_id,
    SUM(oi.quantity)::NUMERIC AS total_sold
  FROM or_order_items oi
  JOIN or_orders o ON o.id = oi.order_id
  WHERE o.entry_date >= p_from_date
    AND o.status NOT IN ('ยกเลิก')
    AND oi.product_id IS NOT NULL
  GROUP BY oi.product_id;
$$;


