--
-- Name: capture_inv_stock_balance_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_inv_stock_balance_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT'
     OR OLD.on_hand IS DISTINCT FROM NEW.on_hand
     OR OLD.reserved IS DISTINCT FROM NEW.reserved
     OR OLD.safety_stock IS DISTINCT FROM NEW.safety_stock THEN
    INSERT INTO public.inv_stock_balance_history (product_id, on_hand, reserved, safety_stock, recorded_at)
    VALUES (NEW.product_id, COALESCE(NEW.on_hand, 0), COALESCE(NEW.reserved, 0), COALESCE(NEW.safety_stock, 0), NOW());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: capture_order_cancellation_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_order_cancellation_actor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_name TEXT;
BEGIN
  IF NEW.status = 'ยกเลิก' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF v_actor_id IS NOT NULL THEN
      SELECT COALESCE(NULLIF(BTRIM(username), ''), NULLIF(BTRIM(email), ''), v_actor_id::TEXT)
      INTO v_actor_name
      FROM public.us_users
      WHERE id = v_actor_id;

      NEW.cancelled_by := v_actor_id;
    END IF;

    NEW.cancelled_by_name := COALESCE(
      v_actor_name,
      NULLIF(BTRIM(NEW.cancelled_by_name), ''),
      NULLIF(BTRIM(OLD.cancelled_by_name), ''),
      CASE WHEN NEW.cancelled_by IS NOT NULL THEN NEW.cancelled_by::TEXT END
    );
    NEW.cancelled_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;


