--
-- Name: erp_data_assert_superadmin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_data_assert_superadmin() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role TEXT;
  v_claims JSONB := COALESCE(NULLIF(current_setting('request.jwt.claims', TRUE), '')::JSONB, '{}'::JSONB);
  v_jwt_role TEXT := COALESCE(v_claims->>'role', '');
BEGIN
  IF v_jwt_role = 'service_role' THEN
    RETURN NULL;
  END IF;

  SELECT u.role
  INTO v_role
  FROM us_users u
  WHERE u.id = v_uid
  LIMIT 1;

  IF v_uid IS NULL OR v_role IS DISTINCT FROM 'superadmin' THEN
    RAISE EXCEPTION 'ต้องใช้สิทธิ์ superadmin เท่านั้น';
  END IF;

  RETURN v_uid;
END;
$$;


