--
-- Name: or_tax_receivable(numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_receivable(p_total numeric, p_details jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT round(p_total,2)-CASE WHEN p_details @> '{"withholding_requested":true}'::jsonb
 THEN round(round(p_total/(1+coalesce((p_details->>'vat_rate')::numeric,7)/100),2)*0.03,2) ELSE 0 END
$$;


--
-- Name: or_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.or_orders (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    channel_code text NOT NULL,
    bill_no text NOT NULL,
    status text DEFAULT 'รอลงข้อมูล'::text NOT NULL,
    price numeric(10,2) DEFAULT 0,
    shipping_cost numeric(10,2) DEFAULT 0,
    discount numeric(10,2) DEFAULT 0,
    total_amount numeric(10,2) DEFAULT 0,
    payment_method text,
    promotion text,
    customer_name text NOT NULL,
    customer_address text NOT NULL,
    admin_user text NOT NULL,
    entry_date date DEFAULT CURRENT_DATE,
    work_order_name text,
    shipped_by text,
    shipped_time timestamp with time zone,
    tracking_number text,
    claim_type text,
    claim_details text,
    billing_details jsonb,
    packing_meta jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    scheduled_pickup_at timestamp with time zone,
    channel_order_no text,
    recipient_name text,
    payment_date date,
    payment_time time without time zone,
    transport_meta jsonb,
    confirm_note text,
    revision_no integer DEFAULT 0,
    is_locked boolean DEFAULT false,
    plan_released_from_work_order text,
    plan_released_at timestamp with time zone,
    work_order_id uuid,
    plan_released_from_work_order_id uuid,
    requires_confirm_design boolean DEFAULT true NOT NULL,
    claim_shipping_confirmed_at timestamp with time zone,
    last_edited_by text,
    ship_due_at timestamp with time zone,
    overdue_at timestamp with time zone,
    shipping_option text,
    urgency_label text,
    urgency_color text,
    failed_queue_archived_at timestamp with time zone,
    failed_queue_archived_by uuid,
    failed_queue_archived_by_name text,
    failed_queue_archive_reason text,
    express_receipt_number text,
    requires_express_receipt_number boolean DEFAULT false NOT NULL,
    fulfillment_method text NOT NULL,
    converted_from_self_pickup_at timestamp with time zone,
    converted_from_self_pickup_by text,
    source_prebill_document_id uuid,
    prebill_price_locked boolean DEFAULT false NOT NULL,
    source_prebill_document_type text,
    source_prebill_owner_name text,
    cancelled_by uuid,
    cancelled_by_name text,
    cancelled_at timestamp with time zone,
    stock_reservation_enabled boolean DEFAULT true NOT NULL,
    shipping_conversion_pending boolean DEFAULT false NOT NULL,
    item_uid_sequence bigint DEFAULT 0 NOT NULL,
    has_parcel_return boolean DEFAULT false NOT NULL,
    source_marketplace_order_id uuid,
    discount_approval_enabled boolean DEFAULT false NOT NULL,
    payment_not_required boolean DEFAULT false NOT NULL,
    automatic_discount_snapshot jsonb,
    receivable_amount numeric GENERATED ALWAYS AS (public.or_tax_receivable(total_amount, billing_details)) STORED,
    CONSTRAINT or_orders_fulfillment_method_check CHECK ((fulfillment_method = ANY (ARRAY['self_pickup'::text, 'shipping'::text]))),
    CONSTRAINT or_orders_source_prebill_document_type_check CHECK (((source_prebill_document_type IS NULL) OR (source_prebill_document_type = ANY (ARRAY['quotation'::text, 'production_confirmation'::text]))))
);

ALTER TABLE ONLY public.or_orders REPLICA IDENTITY FULL;


