--
-- Name: find_shipped_order_for_parcel_return(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_shipped_order_for_parcel_return(p_tracking text) RETURNS SETOF public.or_orders
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT o.*
  FROM public.or_orders o
  WHERE o.status = 'จัดส่งแล้ว'
    AND upper(regexp_replace(coalesce(p_tracking, ''), '[[:space:]]+', '', 'g')) <> ''
    AND upper(regexp_replace(coalesce(o.tracking_number, ''), '[[:space:]]+', '', 'g'))
      = upper(regexp_replace(coalesce(p_tracking, ''), '[[:space:]]+', '', 'g'))
  ORDER BY o.id
  LIMIT 1;
$$;


--
-- Name: fn_apply_location_stock_delta(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_apply_location_stock_delta(p_product_id uuid, p_qty_delta numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_remaining NUMERIC := ABS(COALESCE(p_qty_delta, 0));
  v_location_id UUID;
  v_take NUMERIC;
  v_row RECORD;
BEGIN
  IF COALESCE(p_qty_delta, 0) = 0 THEN RETURN; END IF;

  SELECT id INTO v_location_id
  FROM public.wh_storage_locations
  WHERE is_active
  ORDER BY CASE location_type WHEN 'picking' THEN 0 WHEN 'unallocated' THEN 1 ELSE 2 END,
           sort_order, code
  LIMIT 1;

  IF v_location_id IS NULL THEN
    INSERT INTO public.wh_storage_locations(code, name, location_type, sort_order)
    VALUES ('MOVE', 'จุดจัดเก็บหลัก', 'picking', 0)
    ON CONFLICT ((LOWER(BTRIM(code)))) DO UPDATE SET is_active = true
    RETURNING id INTO v_location_id;
  END IF;

  IF p_qty_delta > 0 THEN
    INSERT INTO public.wh_location_stock(product_id, location_id, qty)
    VALUES (p_product_id, v_location_id, p_qty_delta)
    ON CONFLICT (product_id, location_id) DO UPDATE
      SET qty = public.wh_location_stock.qty + EXCLUDED.qty, updated_at = NOW();
    RETURN;
  END IF;

  FOR v_row IN
    SELECT stock.location_id, stock.qty
    FROM public.wh_location_stock stock
    JOIN public.wh_storage_locations location ON location.id = stock.location_id
    WHERE stock.product_id = p_product_id AND stock.qty > 0
    ORDER BY CASE location.location_type WHEN 'picking' THEN 0 WHEN 'unallocated' THEN 1 ELSE 2 END,
             location.sort_order, location.code
    FOR UPDATE OF stock
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_remaining, v_row.qty);
    UPDATE public.wh_location_stock
    SET qty = qty - v_take, updated_at = NOW()
    WHERE product_id = p_product_id AND location_id = v_row.location_id;
    v_remaining := v_remaining - v_take;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION fn_apply_location_stock_delta(p_product_id uuid, p_qty_delta numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_apply_location_stock_delta(p_product_id uuid, p_qty_delta numeric) IS 'Applies Movement deltas to physical locations; creates MOVE as the primary location when none exists.';


--
-- Name: fn_assert_available_stock(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_assert_available_stock(p_product_id uuid, p_qty numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_on_hand   NUMERIC := 0;
  v_reserved  NUMERIC := 0;
  v_available NUMERIC := 0;
BEGIN
  IF p_qty <= 0 THEN RETURN; END IF;

  SELECT COALESCE(on_hand, 0), COALESCE(reserved, 0)
  INTO v_on_hand, v_reserved
  FROM inv_stock_balances
  WHERE product_id = p_product_id;

  v_available := v_on_hand - v_reserved;

  IF v_available < p_qty THEN
    RAISE EXCEPTION 'stock not enough (available %, requested %)', v_available, p_qty;
  END IF;
END;
$$;


--
-- Name: fn_audit_sub_warehouse_snapshot(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_sub_warehouse_snapshot(p_product_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH ledger AS (
    SELECT m.sub_warehouse_id,sum(m.qty_delta) qty
    FROM public.wh_sub_warehouse_stock_moves m
    WHERE m.product_id=p_product_id AND m.created_at<=p_at
    GROUP BY m.sub_warehouse_id
  ), warehouse_ids AS (
    SELECT a.sub_warehouse_id FROM public.wh_sub_warehouse_products a
    WHERE a.product_id=p_product_id AND a.created_at<=p_at
    UNION SELECT b.sub_warehouse_id FROM ledger b WHERE b.qty<>0
  ), mappings AS (
    SELECT ids.sub_warehouse_id,g.id group_id
    FROM warehouse_ids ids
    JOIN public.wh_sub_wms_map_groups g
      ON (g.sub_warehouse_id IS NULL OR g.sub_warehouse_id=ids.sub_warehouse_id)
      AND g.created_at<=p_at
    JOIN public.wh_sub_wms_map_spares s ON s.group_id=g.id AND s.product_id=p_product_id
  ), usage_codes AS (
    SELECT p.product_code FROM public.pr_products p WHERE p.id=p_product_id
    UNION
    SELECT p.product_code FROM mappings g
    JOIN public.wh_sub_wms_map_sources s ON s.group_id=g.group_id
    JOIN public.pr_products p ON p.id=s.product_id
  ), relevant_orders AS MATERIALIZED (
    SELECT wms.* FROM public.wms_orders wms
    JOIN usage_codes codes ON codes.product_code::text=wms.product_code::text
    WHERE wms.status='correct'
  ), summary_times AS (
    SELECT btrim(s.order_id) order_id,min(s.checked_at) checked_at
    FROM public.wms_order_summaries s
    WHERE btrim(s.order_id) IN (SELECT btrim(r.order_id) FROM relevant_orders r)
    GROUP BY btrim(s.order_id)
  ), work_names AS MATERIALIZED (
    SELECT DISTINCT btrim(COALESCE(o.work_order_name,'')) name FROM public.or_orders o
  ), usage_rows AS (
    SELECT wms.product_code,wms.qty,
      COALESCE(summary.checked_at,direct_completion.wms_review_completed_at,completion.completed_at,
        CASE WHEN wms.fulfillment_mode IN ('system_complete','sub_warehouse_skip') THEN wms.end_time END) used_at
    FROM relevant_orders wms
    LEFT JOIN summary_times summary ON summary.order_id=btrim(wms.order_id)
    LEFT JOIN public.or_work_orders direct_completion ON direct_completion.id=wms.work_order_id
    LEFT JOIN LATERAL (
      SELECT w.wms_review_completed_at completed_at FROM public.or_work_orders w
      WHERE wms.work_order_id IS NULL AND summary.checked_at IS NULL
        AND btrim(w.work_order_name)=btrim(wms.order_id)
      ORDER BY w.created_at DESC LIMIT 1
    ) completion ON true
    WHERE wms.status='correct'
      AND NOT EXISTS (SELECT 1 FROM public.wms_requisitions r WHERE r.requisition_id=wms.order_id)
      AND upper(btrim(COALESCE(wms.order_id,''))) NOT LIKE 'REQ-%'
      AND (wms.work_order_id IS NOT NULL OR EXISTS (
        SELECT 1 FROM work_names o
        WHERE o.name=btrim(COALESCE(wms.order_id,''))
      ))
  ), usage_totals AS (
    SELECT product_code,sum(qty) qty FROM usage_rows
    WHERE used_at<=p_at GROUP BY product_code
  ), mapped_totals AS (
    SELECT g.sub_warehouse_id,COALESCE(sum(u.qty),0) qty
    FROM mappings g
    LEFT JOIN public.wh_sub_wms_map_sources s ON s.group_id=g.group_id
    LEFT JOIN public.pr_products p ON p.id=s.product_id
    LEFT JOIN usage_totals u ON u.product_code::text=p.product_code::text
    GROUP BY g.sub_warehouse_id
  ), balances AS (
    SELECT ids.sub_warehouse_id,COALESCE(l.qty,0)-
      CASE WHEN mapped.sub_warehouse_id IS NOT NULL THEN mapped.qty ELSE COALESCE(direct.qty,0) END qty
    FROM warehouse_ids ids
    LEFT JOIN ledger l ON l.sub_warehouse_id=ids.sub_warehouse_id
    LEFT JOIN mapped_totals mapped ON mapped.sub_warehouse_id=ids.sub_warehouse_id
    LEFT JOIN public.pr_products p ON p.id=p_product_id
    LEFT JOIN usage_totals direct ON direct.product_code::text=p.product_code::text
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'sub_warehouse_id',w.id,'name',w.name,'qty',b.qty
  ) ORDER BY w.name,w.id),'[]'::jsonb)
  FROM balances b JOIN public.wh_sub_warehouses w ON w.id=b.sub_warehouse_id
  WHERE w.created_at<=p_at AND (w.is_active OR b.qty<>0 OR EXISTS (
    SELECT 1 FROM ledger l WHERE l.sub_warehouse_id=w.id AND l.qty<>0
  ));
$$;


--
-- Name: fn_auto_convert_rm_to_fg_on_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_auto_convert_rm_to_fg_on_movement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg RECORD;
  v_fg_qty NUMERIC(12,2);
  v_unit_cost NUMERIC(14,4);
  v_movement_id UUID;
  v_note TEXT;
BEGIN
  IF NEW.movement_type NOT IN ('gr', 'adjust') THEN
    RETURN NEW;
  END IF;

  SELECT
    c.fg_product_id,
    c.sheets_per_roll,
    c.cost_per_sheet
  INTO v_cfg
  FROM roll_material_config_rms m
  JOIN roll_material_configs c ON c.id = m.config_id
  JOIN pr_products rm ON rm.id = m.rm_product_id
  JOIN pr_products fg ON fg.id = c.fg_product_id
  WHERE m.rm_product_id = NEW.product_id
    AND rm.product_type = 'RM'
    AND fg.product_type = 'FG'
    AND COALESCE(c.sheets_per_roll, 0) > 0
  ORDER BY c.updated_at DESC, c.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_fg_qty := ROUND(COALESCE(NEW.qty, 0) * v_cfg.sheets_per_roll, 2);
  IF COALESCE(v_fg_qty, 0) = 0 THEN
    RETURN NEW;
  END IF;

  v_note := format(
    'Auto FG from RM (%s): RM qty %s x sheets_per_roll %s',
    COALESCE(NEW.product_id::TEXT, '-'),
    COALESCE(NEW.qty::TEXT, '0'),
    COALESCE(v_cfg.sheets_per_roll::TEXT, '0')
  );

  INSERT INTO inv_stock_balances (product_id, on_hand, reserved, safety_stock)
  VALUES (v_cfg.fg_product_id, v_fg_qty, 0, 0)
  ON CONFLICT (product_id) DO UPDATE
    SET on_hand = inv_stock_balances.on_hand + v_fg_qty,
        updated_at = NOW();

  IF v_fg_qty > 0 THEN
    v_unit_cost := COALESCE(v_cfg.cost_per_sheet, fn_get_current_avg_cost(v_cfg.fg_product_id), 0);

    INSERT INTO inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, created_by, unit_cost, total_cost
    )
    VALUES (
      v_cfg.fg_product_id,
      'roll_auto_fg',
      v_fg_qty,
      COALESCE(NEW.ref_type, 'roll_auto_fg'),
      NEW.ref_id,
      v_note,
      NEW.created_by,
      v_unit_cost,
      v_fg_qty * v_unit_cost
    );

    INSERT INTO inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id
    )
    VALUES (
      v_cfg.fg_product_id,
      v_fg_qty,
      v_fg_qty,
      v_unit_cost,
      COALESCE(NEW.ref_type, 'roll_auto_fg'),
      NEW.ref_id
    );
  ELSE
    INSERT INTO inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, created_by
    )
    VALUES (
      v_cfg.fg_product_id,
      'roll_auto_fg',
      v_fg_qty,
      COALESCE(NEW.ref_type, 'roll_auto_fg'),
      NEW.ref_id,
      v_note,
      NEW.created_by
    )
    RETURNING id INTO v_movement_id;

    PERFORM fn_consume_stock_fifo(v_cfg.fg_product_id, ABS(v_fg_qty), v_movement_id);
  END IF;

  PERFORM fn_recalc_product_landed_cost(v_cfg.fg_product_id);

  RETURN NEW;
END;
$$;


--
-- Name: fn_calc_pp_producible_qty(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_calc_pp_producible_qty(p_product_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_recipe_id UUID;
  v_min_qty   NUMERIC := NULL;
  v_inc       RECORD;
  v_on_hand   NUMERIC;
  v_possible  NUMERIC;
BEGIN
  SELECT id INTO v_recipe_id FROM pp_recipes WHERE product_id = p_product_id;
  IF v_recipe_id IS NULL THEN RETURN 0; END IF;

  FOR v_inc IN
    SELECT ri.product_id, ri.qty
    FROM pp_recipe_includes ri
    WHERE ri.recipe_id = v_recipe_id AND ri.qty > 0
  LOOP
    SELECT COALESCE(sb.on_hand, 0) INTO v_on_hand
    FROM inv_stock_balances sb
    WHERE sb.product_id = v_inc.product_id;

    v_on_hand := COALESCE(v_on_hand, 0);
    v_possible := FLOOR(v_on_hand / v_inc.qty);

    IF v_min_qty IS NULL OR v_possible < v_min_qty THEN
      v_min_qty := v_possible;
    END IF;
  END LOOP;

  RETURN COALESCE(v_min_qty, 0);
END;
$$;


--
-- Name: fn_calc_pp_producible_qty_batch(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_calc_pp_producible_qty_batch(p_product_ids uuid[]) RETURNS TABLE(product_id uuid, producible_qty numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_pid       UUID;
  v_recipe_id UUID;
  v_min_qty   NUMERIC;
  v_inc       RECORD;
  v_on_hand   NUMERIC;
  v_possible  NUMERIC;
BEGIN
  FOREACH v_pid IN ARRAY p_product_ids
  LOOP
    v_min_qty := NULL;
    SELECT r.id INTO v_recipe_id FROM pp_recipes r WHERE r.product_id = v_pid;

    IF v_recipe_id IS NOT NULL THEN
      FOR v_inc IN
        SELECT ri.product_id AS inc_product_id, ri.qty
        FROM pp_recipe_includes ri
        WHERE ri.recipe_id = v_recipe_id AND ri.qty > 0
      LOOP
        SELECT COALESCE(sb.on_hand, 0) INTO v_on_hand
        FROM inv_stock_balances sb
        WHERE sb.product_id = v_inc.inc_product_id;

        v_on_hand := COALESCE(v_on_hand, 0);
        v_possible := FLOOR(v_on_hand / v_inc.qty);

        IF v_min_qty IS NULL OR v_possible < v_min_qty THEN
          v_min_qty := v_possible;
        END IF;
      END LOOP;
    END IF;

    product_id := v_pid;
    producible_qty := COALESCE(v_min_qty, 0);
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: fn_check_requisition_stock(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_check_requisition_stock(p_code text, p_qty numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_product public.pr_products%ROWTYPE; v_available numeric := 0;
BEGIN
  IF p_qty IS NULL OR p_qty <= 0 OR p_qty::text IN ('NaN', 'Infinity', '-Infinity') THEN
    RAISE EXCEPTION 'จำนวนเบิกสินค้า % ต้องมากกว่า 0', p_code;
  END IF;
  SELECT * INTO v_product FROM public.pr_products WHERE product_code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบสินค้า %', p_code; END IF;
  SELECT COALESCE(on_hand, 0) - COALESCE(reserved, 0) INTO v_available
  FROM public.inv_stock_balances WHERE product_id = v_product.id FOR UPDATE;
  v_available := GREATEST(COALESCE(v_available, 0), 0);
  IF p_qty > v_available THEN
    RAISE EXCEPTION 'สินค้า % - % เบิกได้ไม่เกิน % % (ยอดพร้อมเบิกหลังหักจอง)',
      p_code, v_product.product_name, v_available, COALESCE(NULLIF(BTRIM(v_product.unit_name), ''), 'ชิ้น');
  END IF;
END $$;


--
-- Name: fn_close_terminal_mixed_work_order_tracks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_close_terminal_mixed_work_order_tracks(p_work_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_wo public.or_work_orders%ROWTYPE;
  v_open_orders INTEGER := 0;
  v_shipped_orders INTEGER := 0;
  v_plan_job_id TEXT;
  v_tracks JSONB := '{}'::JSONB;
  v_qc_start TIMESTAMPTZ;
  v_qc_end TIMESTAMPTZ;
  v_pack_start TIMESTAMPTZ;
  v_pack_end TIMESTAMPTZ;
  v_qc_patch JSONB;
  v_pack_patch JSONB;
BEGIN
  IF p_work_order_id IS NULL THEN
    RETURN jsonb_build_object('success', FALSE, 'reason', 'missing_work_order_id');
  END IF;

  SELECT * INTO v_wo
  FROM public.or_work_orders
  WHERE id = p_work_order_id;
  IF v_wo.id IS NULL THEN
    RETURN jsonb_build_object('success', FALSE, 'reason', 'work_order_not_found');
  END IF;

  SELECT
    COUNT(*) FILTER (
      WHERE COALESCE(o.status, '') NOT IN ('ยกเลิก', 'จัดส่งแล้ว')
        AND EXISTS (
          SELECT 1 FROM public.or_order_items oi
          WHERE oi.order_id = o.id
            AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
        )
    )::INTEGER,
    COUNT(*) FILTER (WHERE COALESCE(o.status, '') = 'จัดส่งแล้ว')::INTEGER,
    MAX(COALESCE(o.shipped_time, o.updated_at)) FILTER (WHERE COALESCE(o.status, '') = 'จัดส่งแล้ว')
  INTO v_open_orders, v_shipped_orders, v_pack_end
  FROM public.or_orders o
  WHERE o.work_order_id = v_wo.id
     OR (o.work_order_id IS NULL AND BTRIM(COALESCE(o.work_order_name, '')) = BTRIM(v_wo.work_order_name));

  IF v_open_orders > 0 THEN
    RETURN jsonb_build_object('success', TRUE, 'closed', FALSE, 'reason', 'active_orders_remain');
  END IF;
  IF v_shipped_orders = 0 THEN
    RETURN jsonb_build_object('success', TRUE, 'closed', FALSE, 'reason', 'fully_cancelled_or_no_shipped_order');
  END IF;

  SELECT pj.id, COALESCE(pj.tracks, '{}'::JSONB)
  INTO v_plan_job_id, v_tracks
  FROM public.plan_jobs pj
  WHERE pj.work_order_id = v_wo.id
     OR (pj.work_order_id IS NULL AND pj.name = v_wo.work_order_name)
  ORDER BY pj.date DESC, pj.order_index DESC
  LIMIT 1;
  IF v_plan_job_id IS NULL THEN
    RETURN jsonb_build_object('success', FALSE, 'reason', 'plan_job_not_found');
  END IF;

  v_qc_start := NULLIF(v_tracks -> 'QC' -> 'เริ่มQC' ->> 'start', '')::TIMESTAMPTZ;
  v_pack_start := NULLIF(v_tracks -> 'PACK' -> 'เริ่มแพ็ค' ->> 'start', '')::TIMESTAMPTZ;

  SELECT MAX(q.end_time)
  INTO v_qc_end
  FROM public.qc_sessions q
  WHERE q.filename = 'WO-' || v_wo.work_order_name
    AND q.end_time IS NOT NULL;

  -- Starting PACK proves the active QC work was handed off. Prefer a real
  -- closed QC session, then PACK start, then the latest shipment timestamp.
  v_qc_end := COALESCE(v_qc_end, v_pack_start, v_pack_end);
  IF v_qc_start IS NOT NULL AND v_qc_end IS NOT NULL THEN
    v_qc_end := GREATEST(v_qc_start, v_qc_end);
  END IF;
  IF v_pack_start IS NOT NULL AND v_pack_end IS NOT NULL THEN
    v_pack_end := GREATEST(v_pack_start, v_pack_end);
  END IF;

  IF v_qc_start IS NOT NULL
     AND NULLIF(v_tracks -> 'QC' -> 'เสร็จแล้ว' ->> 'end', '') IS NULL
     AND v_qc_end IS NOT NULL THEN
    v_qc_patch := jsonb_build_object(
      'เริ่มQC', jsonb_build_object('start_if_null', to_jsonb(v_qc_start), 'end', to_jsonb(v_qc_end)),
      'เสร็จแล้ว', jsonb_build_object('start_if_null', to_jsonb(v_qc_start), 'end', to_jsonb(v_qc_end))
    );
    PERFORM public.merge_plan_tracks(v_plan_job_id, 'QC', v_qc_patch);
  END IF;

  -- Reload after the QC merge so the PACK merge cannot overwrite it.
  SELECT COALESCE(tracks, '{}'::JSONB) INTO v_tracks
  FROM public.plan_jobs WHERE id = v_plan_job_id;

  IF v_pack_start IS NOT NULL
     AND NULLIF(v_tracks -> 'PACK' -> 'เสร็จแล้ว' ->> 'end', '') IS NULL
     AND v_pack_end IS NOT NULL THEN
    v_pack_patch := jsonb_build_object(
      'เริ่มแพ็ค', jsonb_build_object('start_if_null', to_jsonb(v_pack_start), 'end', to_jsonb(v_pack_end)),
      'เสร็จแล้ว', jsonb_build_object('start_if_null', to_jsonb(v_pack_start), 'end', to_jsonb(v_pack_end))
    );
    PERFORM public.merge_plan_tracks(v_plan_job_id, 'PACK', v_pack_patch);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'closed', TRUE,
    'plan_job_id', v_plan_job_id,
    'qc_end', v_qc_end,
    'pack_end', v_pack_end,
    'shipped_orders', v_shipped_orders
  );
END;
$$;


--
-- Name: FUNCTION fn_close_terminal_mixed_work_order_tracks(p_work_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_close_terminal_mixed_work_order_tracks(p_work_order_id uuid) IS 'Closes missing QC/PACK Plan end tracks only when no active fulfillment order remains and at least one bill was shipped.';


--
-- Name: fn_consume_stock_fifo(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_consume_stock_fifo(p_product_id uuid, p_qty numeric, p_movement_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_remaining NUMERIC := p_qty;
  v_total_cost NUMERIC := 0;
  v_lot RECORD;
  v_consume NUMERIC;
  v_unit_cost NUMERIC;
BEGIN
  IF p_qty <= 0 THEN RETURN 0; END IF;

  FOR v_lot IN
    SELECT l.id, l.qty_remaining, l.unit_cost
    FROM public.inv_stock_lots l
    WHERE l.product_id = p_product_id
      AND l.qty_remaining > 0
      AND COALESCE(l.is_safety_stock, FALSE) IS FALSE
    ORDER BY l.created_at, l.id
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_consume := LEAST(v_lot.qty_remaining, v_remaining);
    UPDATE public.inv_stock_lots
    SET qty_remaining = qty_remaining - v_consume
    WHERE id = v_lot.id;
    INSERT INTO public.inv_lot_consumptions (lot_id, movement_id, qty, unit_cost)
    VALUES (v_lot.id, p_movement_id, v_consume, v_lot.unit_cost);
    v_total_cost := v_total_cost + (v_consume * v_lot.unit_cost);
    v_remaining := v_remaining - v_consume;
  END LOOP;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'insufficient sellable lots for product %, short by %', p_product_id, v_remaining;
  END IF;

  v_unit_cost := CASE WHEN p_qty > 0 THEN v_total_cost / p_qty ELSE 0 END;
  UPDATE public.inv_stock_movements
  SET unit_cost = v_unit_cost,
      total_cost = qty * v_unit_cost
  WHERE id = p_movement_id;
  RETURN v_total_cost;
END;
$$;


--
-- Name: fn_document_reservation_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_document_reservation_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_type text; v_old uuid; v_new uuid; v_fields text[];
BEGIN
  -- Item-save RPCs deliberately touch the header's updated_at to reconcile
  -- once after suppressing per-line reservations. Never skip that final touch.
  -- Limit the header optimization to actual packing-meta-only changes, allowing
  -- updated_at stamped by other triggers. Keep prebill expiry behavior intact.
  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME = 'or_orders'
      AND (to_jsonb(OLD)->'packing_meta') IS DISTINCT FROM (to_jsonb(NEW)->'packing_meta')
      AND (to_jsonb(OLD) - ARRAY['packing_meta','updated_at'])
        IS NOT DISTINCT FROM (to_jsonb(NEW) - ARRAY['packing_meta','updated_at'])
    THEN RETURN NULL; END IF;
    v_fields := CASE TG_TABLE_NAME
      WHEN 'or_order_items' THEN ARRAY['id','order_id','product_id','quantity','is_detail_row','cancellation_stock_action']
      ELSE NULL END;
    IF v_fields IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM unnest(v_fields) AS f(key)
      WHERE (to_jsonb(OLD)->f.key) IS DISTINCT FROM (to_jsonb(NEW)->f.key)
    ) THEN RETURN NULL; END IF;
  END IF;
  v_type:=CASE WHEN TG_TABLE_NAME LIKE 'or_prebill%' THEN 'prebill' ELSE 'order' END;
  IF TG_OP <> 'INSERT' THEN
    v_old:=CASE WHEN TG_TABLE_NAME IN ('or_orders','or_prebill_documents') THEN OLD.id
      WHEN v_type='prebill' THEN (to_jsonb(OLD)->>'document_id')::uuid ELSE (to_jsonb(OLD)->>'order_id')::uuid END;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_new:=CASE WHEN TG_TABLE_NAME IN ('or_orders','or_prebill_documents') THEN NEW.id
      WHEN v_type='prebill' THEN (to_jsonb(NEW)->>'document_id')::uuid ELSE (to_jsonb(NEW)->>'order_id')::uuid END;
  END IF;
  IF v_old IS NOT NULL AND v_old IS DISTINCT FROM v_new THEN PERFORM public.fn_sync_document_reservations(v_type,v_old); END IF;
  IF v_new IS NOT NULL THEN PERFORM public.fn_sync_document_reservations(v_type,v_new); END IF;
  RETURN NULL;
END $$;


--
-- Name: fn_enable_sales_reservation_on_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enable_sales_reservation_on_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.status='รอลงข้อมูล' AND NEW.status NOT IN ('รอลงข้อมูล','ยกเลิก','จัดส่งแล้ว') THEN
    NEW.stock_reservation_enabled:=true;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_expire_document_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expire_document_reservations() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN SELECT DISTINCT source_id FROM public.inv_document_reservations
    WHERE source_type='prebill' AND qty>0 AND expires_on < timezone('Asia/Bangkok',now())::date ORDER BY source_id
  LOOP PERFORM public.fn_sync_document_reservations('prebill',r.source_id); END LOOP;
END $$;


--
-- Name: fn_get_current_avg_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_current_avg_cost(p_product_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_avg NUMERIC;
BEGIN
  SELECT SUM(qty_remaining * unit_cost) / NULLIF(SUM(qty_remaining), 0)
  INTO v_avg
  FROM inv_stock_lots
  WHERE product_id = p_product_id
    AND qty_remaining > 0
    AND is_safety_stock = FALSE;

  RETURN COALESCE(v_avg, 0);
END;
$$;


--
-- Name: fn_get_latest_gr_lot_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_latest_gr_lot_cost(p_product_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_cost NUMERIC;
BEGIN
  SELECT l.unit_cost
  INTO v_cost
  FROM inv_stock_lots l
  WHERE l.product_id = p_product_id
    AND l.ref_type IN ('inv_gr', 'initial_import')
  ORDER BY l.created_at DESC, l.id DESC
  LIMIT 1;

  IF v_cost IS NULL THEN
    SELECT COALESCE(p.landed_cost, p.unit_cost, 0)
    INTO v_cost
    FROM pr_products p
    WHERE p.id = p_product_id;
  END IF;

  RETURN COALESCE(v_cost, 0);
END;
$$;


--
-- Name: fn_get_roll_calc_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_roll_calc_dashboard() RETURNS TABLE(config_id uuid, fg_product_id uuid, fg_product_code text, fg_product_name text, fg_product_category text, rm_product_id uuid, rm_product_code text, rm_product_name text, rm_count integer, rm_on_hand numeric, category_id uuid, category_name text, sheets_per_roll numeric, cost_per_sheet numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT
      c.id AS cfg_id,
      fg.id AS fg_id,
      fg.product_code AS fg_code,
      fg.product_name AS fg_name,
      fg.product_category AS fg_cat,
      (ARRAY_AGG(m.rm_product_id ORDER BY rm.product_code))[1] AS first_rm_id,
      COALESCE(STRING_AGG(rm.product_code, E'\n' ORDER BY rm.product_code), '-') AS rm_codes,
      COALESCE(STRING_AGG(rm.product_name, E'\n' ORDER BY rm.product_code), '-') AS rm_names,
      COUNT(m.rm_product_id)::INT AS rm_count_val,
      COALESCE(SUM(sb.on_hand), 0) AS rm_oh,
      c.category_id AS cat_id,
      cat.name AS cat_name,
      c.sheets_per_roll AS spr,
      c.cost_per_sheet AS cps,
      COALESCE(cat.sort_order, 999) AS cat_sort
    FROM roll_material_configs c
    JOIN pr_products fg ON fg.id = c.fg_product_id
    LEFT JOIN roll_material_config_rms m ON m.config_id = c.id
    LEFT JOIN pr_products rm ON rm.id = m.rm_product_id
    LEFT JOIN inv_stock_balances sb ON sb.product_id = m.rm_product_id
    LEFT JOIN roll_material_categories cat ON cat.id = c.category_id
    GROUP BY
      c.id, fg.id, fg.product_code, fg.product_name, fg.product_category,
      c.category_id, cat.name, c.sheets_per_roll, c.cost_per_sheet, cat.sort_order
    ORDER BY cat_sort, fg.product_code
  LOOP
    config_id           := r.cfg_id;
    fg_product_id       := r.fg_id;
    fg_product_code     := r.fg_code;
    fg_product_name     := r.fg_name;
    fg_product_category := r.fg_cat;
    rm_product_id       := r.first_rm_id;
    rm_product_code     := r.rm_codes;
    rm_product_name     := r.rm_names;
    rm_count            := r.rm_count_val;
    rm_on_hand          := r.rm_oh;
    category_id         := r.cat_id;
    category_name       := r.cat_name;
    sheets_per_roll     := r.spr;
    cost_per_sheet      := r.cps;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: fn_guard_or_order_items_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_or_order_items_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_available numeric; v_own numeric; v_other numeric; v_enabled boolean; v_source uuid;
BEGIN
  IF NEW.product_id IS NULL OR coalesce(NEW.is_detail_row,false) THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.product_id IS NOT DISTINCT FROM OLD.product_id AND NEW.quantity=OLD.quantity THEN RETURN NEW; END IF;
  PERFORM public.fn_expire_document_reservations();
  SELECT stock_reservation_enabled,source_prebill_document_id INTO v_enabled,v_source FROM public.or_orders WHERE id=NEW.order_id FOR UPDATE;
  IF v_enabled THEN RETURN NEW; END IF;
  -- Legacy documents retain the previous validation.
  INSERT INTO public.inv_stock_balances(product_id,on_hand,reserved,safety_stock) VALUES(NEW.product_id,0,0,0) ON CONFLICT(product_id) DO NOTHING;
  SELECT coalesce(on_hand,0)-coalesce(reserved,0) INTO v_available FROM public.inv_stock_balances WHERE product_id=NEW.product_id FOR UPDATE;
  SELECT coalesce(sum(qty),0) INTO v_own FROM public.inv_document_reservations WHERE source_type='order' AND source_id=NEW.order_id AND product_id=NEW.product_id;
  SELECT coalesce(sum(quantity),0) INTO v_other FROM public.or_order_items
  WHERE order_id=NEW.order_id AND product_id=NEW.product_id AND NOT coalesce(is_detail_row,false)
    AND cancellation_stock_action IS NULL AND (TG_OP='INSERT' OR id<>OLD.id);
  IF v_other+NEW.quantity > v_available THEN
    RAISE EXCEPTION 'สต๊อกพร้อมขายไม่เพียงพอ: ต้องการ % แต่พร้อมขาย %',v_other+NEW.quantity,v_available;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_guard_requisition_approval_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_requisition_approval_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
  IF NEW.status = 'approved' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
    IF NOT EXISTS (SELECT 1 FROM public.wms_requisition_items WHERE requisition_id = NEW.requisition_id) THEN
      RAISE EXCEPTION 'ใบเบิกนี้ไม่มีรายการสินค้า';
    END IF;
    IF EXISTS (SELECT 1 FROM public.wms_requisition_items WHERE requisition_id = NEW.requisition_id
      AND (qty IS NULL OR qty <= 0 OR qty::text IN ('NaN', 'Infinity', '-Infinity'))) THEN
      RAISE EXCEPTION 'จำนวนเบิกสินค้าต้องมากกว่า 0';
    END IF;
    FOR r IN SELECT product_code, SUM(qty) AS qty FROM public.wms_requisition_items
      WHERE requisition_id = NEW.requisition_id GROUP BY product_code ORDER BY product_code
    LOOP PERFORM public.fn_check_requisition_stock(r.product_code, r.qty); END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_guard_requisition_item_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_requisition_item_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text; v_total numeric;
BEGIN
  -- Serialize changes to a document, including duplicate product lines.
  SELECT status INTO v_status FROM public.wms_requisitions
  WHERE requisition_id = NEW.requisition_id FOR UPDATE;
  IF NOT FOUND OR v_status <> 'pending' THEN
    RAISE EXCEPTION 'เพิ่มหรือแก้ไขสินค้าได้เฉพาะใบเบิกรออนุมัติ';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.requisition_id IS DISTINCT FROM OLD.requisition_id THEN
    RAISE EXCEPTION 'ไม่สามารถย้ายรายการไปใบเบิกอื่น';
  END IF;
  -- Validate the line separately so a negative line cannot offset another line.
  PERFORM public.fn_check_requisition_stock(NEW.product_code, NEW.qty);
  SELECT COALESCE(SUM(qty), 0) + NEW.qty INTO v_total
  FROM public.wms_requisition_items
  WHERE requisition_id = NEW.requisition_id AND product_code = NEW.product_code
    AND id IS DISTINCT FROM NEW.id;
  PERFORM public.fn_check_requisition_stock(NEW.product_code, v_total);
  RETURN NEW;
END $$;


--
-- Name: fn_guard_requisition_pick_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_requisition_pick_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'picked' AND OLD.status IS DISTINCT FROM 'picked'
     AND OLD.status IS DISTINCT FROM 'correct'
     AND EXISTS (SELECT 1 FROM public.wms_requisitions WHERE requisition_id = NEW.order_id) THEN
    PERFORM public.fn_check_requisition_stock(NEW.product_code, NEW.qty);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_guard_reservation_cutover(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_reservation_cutover() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN NEW.stock_reservation_enabled:=true;
  ELSIF NEW.stock_reservation_enabled IS DISTINCT FROM OLD.stock_reservation_enabled THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนโหมดจองของเอกสาร';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_guard_reserved_order_item_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_reserved_order_item_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM public.or_orders WHERE id=OLD.order_id AND stock_reservation_enabled)
     AND EXISTS(SELECT 1 FROM public.wms_orders WHERE source_order_item_id=OLD.id
       AND (status NOT IN ('returned','cancelled') OR (status='cancelled' AND stock_action IS NULL)))
     AND (TG_OP='DELETE' OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.quantity IS DISTINCT FROM OLD.quantity) THEN
    RAISE EXCEPTION 'รายการนี้เชื่อมงานหยิบแล้ว กรุณาใช้ขั้นตอนแก้ไข/ยกเลิกบิลและจัดการสต๊อกก่อน';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


