         LPAD(NEXTVAL('public.wh_stock_transfer_no_seq')::TEXT, 5, '0');
$$;


--
-- Name: fn_normalize_seller_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_normalize_seller_type(p_raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v TEXT := lower(trim(COALESCE(p_raw, '')));
BEGIN
  IF v = '' THEN
    RETURN NULL;
  END IF;

  IF v IN ('thailand', 'th', 'ไทย', 'ประเทศไทย') THEN
    RETURN 'thailand';
  END IF;

  IF v IN ('foreign', 'intl', 'international', 'cn', 'ต่างประเทศ', 'ตปท') THEN
    RETURN 'foreign';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: fn_order_work_order_has_started(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_order_work_order_has_started(p_order_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_work_order_id UUID;
  v_work_order_name TEXT;
  v_tracks JSONB;
  v_has_pickable BOOLEAN := false;
  v_dept RECORD;
  v_step RECORD;
BEGIN
  SELECT o.work_order_id, nullif(trim(o.work_order_name), '')
  INTO v_work_order_id, v_work_order_name
  FROM public.or_orders o
  WHERE o.id = p_order_id;

  IF v_work_order_id IS NULL AND v_work_order_name IS NULL THEN
    RETURN false;
  END IF;

  SELECT pj.tracks
  INTO v_tracks
  FROM public.plan_jobs pj
  WHERE (v_work_order_id IS NOT NULL AND pj.work_order_id = v_work_order_id)
     OR (v_work_order_id IS NULL AND trim(pj.name) = v_work_order_name)
  ORDER BY CASE WHEN pj.work_order_id = v_work_order_id THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_tracks IS NULL OR jsonb_typeof(v_tracks) <> 'object' THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id = o.id
    JOIN public.pr_products p ON p.id = oi.product_id
    WHERE NOT coalesce(oi.is_detail_row, false)
      AND public.fn_wms_is_pickable_category(p.product_category::text)
      AND (
        (v_work_order_id IS NOT NULL AND o.work_order_id = v_work_order_id)
        OR (
          v_work_order_id IS NULL
          AND trim(coalesce(o.work_order_name, '')) = v_work_order_name
        )
      )
  ) INTO v_has_pickable;

  FOR v_dept IN SELECT * FROM jsonb_each(v_tracks)
  LOOP
    CONTINUE WHEN v_dept.value IS NULL OR jsonb_typeof(v_dept.value) <> 'object';
    CONTINUE WHEN v_dept.key = 'เบิก' AND NOT v_has_pickable;

    FOR v_step IN SELECT * FROM jsonb_each(v_dept.value)
    LOOP
      CONTINUE WHEN v_step.key = 'เตรียมไฟล์';
      CONTINUE WHEN v_step.value IS NULL OR jsonb_typeof(v_step.value) <> 'object';
      IF nullif(trim(v_step.value->>'start'), '') IS NOT NULL THEN
        RETURN true;
      END IF;
    END LOOP;
  END LOOP;

  RETURN false;
END;
$$;


--
-- Name: fn_plan_job_has_any_track_start(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_plan_job_has_any_track_start(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tracks JSONB;
  d          RECORD;
  s          RECORD;
BEGIN
  SELECT pj.tracks INTO v_tracks
  FROM plan_jobs pj
  WHERE trim(both FROM pj.name) = trim(both FROM coalesce(p_name, ''))
  LIMIT 1;

  IF v_tracks IS NULL OR v_tracks = '{}'::jsonb THEN
    RETURN false;
  END IF;

  FOR d IN SELECT * FROM jsonb_each(v_tracks)
  LOOP
    CONTINUE WHEN d.value IS NULL OR jsonb_typeof(d.value) <> 'object';
    FOR s IN SELECT * FROM jsonb_each(d.value)
    LOOP
      CONTINUE WHEN s.value IS NULL OR jsonb_typeof(s.value) <> 'object';
      IF (s.value ? 'start') AND nullif(trim(s.value->>'start'), '') IS NOT NULL THEN
        RETURN true;
      END IF;
    END LOOP;
  END LOOP;

  RETURN false;
END;
$$;


--
-- Name: fn_plan_qty_json_for_work_order(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_plan_qty_json_for_work_order(p_work_order_name text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_pack INT := 0;
  v_qty JSONB := '{"STAMP":0,"STK":0,"CTT":0,"LASER":0,"TUBE":0,"ETC":0,"PACK":0}'::jsonb;
  v_cat TEXT;
  v_bill_ids UUID[];
BEGIN
  SELECT array_agg(o.id) INTO v_bill_ids
  FROM or_orders o
  WHERE trim(both FROM coalesce(o.work_order_name, '')) = trim(both FROM coalesce(p_work_order_name, ''));

  v_pack := COALESCE(array_length(v_bill_ids, 1), 0);
  v_qty := jsonb_set(v_qty, '{PACK}', to_jsonb(v_pack));

  IF v_bill_ids IS NULL OR v_pack = 0 THEN
    RETURN v_qty;
  END IF;

  FOR r IN
    SELECT oi.product_id
    FROM or_order_items oi
    WHERE oi.order_id = ANY (v_bill_ids)
      AND oi.product_id IS NOT NULL
  LOOP
    SELECT upper(trim(coalesce(product_category, ''))) INTO v_cat
    FROM pr_products WHERE id = r.product_id;

    IF v_cat IS NULL THEN CONTINUE; END IF;

    IF v_cat LIKE '%STAMP%' THEN
      v_qty := jsonb_set(v_qty, '{STAMP}', to_jsonb((v_qty->>'STAMP')::int + 1));
    END IF;
    IF v_cat LIKE '%STK%' THEN
      v_qty := jsonb_set(v_qty, '{STK}', to_jsonb((v_qty->>'STK')::int + 1));
    END IF;
    IF v_cat LIKE '%UV%' OR v_cat LIKE '%SUBLIMATION%' THEN
      v_qty := jsonb_set(v_qty, '{CTT}', to_jsonb((v_qty->>'CTT')::int + 1));
    END IF;
    IF v_cat LIKE '%LASER%' THEN
      v_qty := jsonb_set(v_qty, '{LASER}', to_jsonb((v_qty->>'LASER')::int + 1));
    END IF;
    IF v_cat LIKE '%TUBE%' THEN
      v_qty := jsonb_set(v_qty, '{TUBE}', to_jsonb((v_qty->>'TUBE')::int + 1));
    END IF;
    IF v_cat IN ('CALENDAR', 'ETC', 'INK') THEN
      v_qty := jsonb_set(v_qty, '{ETC}', to_jsonb((v_qty->>'ETC')::int + 1));
    END IF;
  END LOOP;

  RETURN v_qty;
END;
$$;


--
-- Name: fn_pr_products_ensure_seller_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_pr_products_ensure_seller_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM fn_upsert_pr_seller_from_product(
    NEW.seller_name,
    NEW.seller_name_cn,
    NEW.seller_purchase_channel,
    NEW.seller_type
  );
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_pr_products_ensure_seller_row(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_pr_products_ensure_seller_row() IS 'เมื่อมี seller_name ในสินค้า ให้ upsert pr_sellers พร้อม metadata จากสินค้า';


--
-- Name: fn_recalc_product_landed_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_recalc_product_landed_cost(p_product_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_avg NUMERIC;
BEGIN
  SELECT SUM(qty_remaining * unit_cost) / NULLIF(SUM(qty_remaining), 0)
  INTO v_avg
  FROM inv_stock_lots
  WHERE product_id = p_product_id AND qty_remaining > 0;

  UPDATE pr_products
  SET landed_cost = COALESCE(v_avg, 0)
  WHERE id = p_product_id;
END;
$$;


--
-- Name: fn_recompute_work_order_order_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_recompute_work_order_order_count(p_work_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cnt int;
BEGIN
  IF p_work_order_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COUNT(*)::int INTO v_cnt
  FROM or_orders o
  WHERE o.work_order_id = p_work_order_id
    AND COALESCE(o.status, '') NOT IN ('ยกเลิก', 'จัดส่งแล้ว');

  UPDATE or_work_orders
  SET
    order_count = v_cnt,
    plan_wo_modified = true
  WHERE id = p_work_order_id;
END;
$$;


--
-- Name: FUNCTION fn_recompute_work_order_order_count(p_work_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_recompute_work_order_order_count(p_work_order_id uuid) IS 'ตั้ง order_count = จำนวนบิลที่ยังอยู่ในใบงานและไม่ใช่สถานะ ยกเลิก / จัดส่งแล้ว (สอดคล้องกับ Plan จัดการใบงาน โหมด active)';


--
-- Name: fn_reconcile_sellable_lots_to_on_hand(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reconcile_sellable_lots_to_on_hand(p_product_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_on_hand NUMERIC := 0;
  v_lot_qty NUMERIC := 0;
  v_missing NUMERIC := 0;
  v_unit_cost NUMERIC := 0;
BEGIN
  SELECT COALESCE(b.on_hand, 0)
  INTO v_on_hand
  FROM public.inv_stock_balances b
  WHERE b.product_id = p_product_id
  FOR UPDATE;

  -- Serialize repairs and FIFO consumption for this product.
  PERFORM 1
  FROM public.inv_stock_lots l
  WHERE l.product_id = p_product_id
    AND l.qty_remaining > 0
    AND COALESCE(l.is_safety_stock, FALSE) IS FALSE
  ORDER BY l.created_at, l.id
  FOR UPDATE;

  SELECT COALESCE(SUM(l.qty_remaining), 0)
  INTO v_lot_qty
  FROM public.inv_stock_lots l
  WHERE l.product_id = p_product_id
    AND l.qty_remaining > 0
    AND COALESCE(l.is_safety_stock, FALSE) IS FALSE;

  v_missing := GREATEST(v_on_hand - v_lot_qty, 0);
  IF v_missing <= 0 THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(
    NULLIF((
      SELECT SUM(l.qty_remaining * l.unit_cost) / NULLIF(SUM(l.qty_remaining), 0)
      FROM public.inv_stock_lots l
      WHERE l.product_id = p_product_id
        AND l.qty_remaining > 0
        AND COALESCE(l.is_safety_stock, FALSE) IS FALSE
    ), 0),
    NULLIF(p.landed_cost, 0), NULLIF(p.unit_cost, 0), 0
  )
  INTO v_unit_cost
  FROM public.pr_products p
  WHERE p.id = p_product_id;

  INSERT INTO public.inv_stock_lots (
    product_id, qty_initial, qty_remaining, unit_cost,
    ref_type, ref_id, is_safety_stock
  )
  VALUES (
    p_product_id, v_missing, v_missing, COALESCE(v_unit_cost, 0),
    'balance_lot_repair', p_product_id, FALSE
  );

  RETURN v_missing;
END;
$$;


--
-- Name: FUNCTION fn_reconcile_sellable_lots_to_on_hand(p_product_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_reconcile_sellable_lots_to_on_hand(p_product_id uuid) IS 'Creates only the missing normal FIFO layer up to the locked main on_hand balance; never increases stock balance.';


--
-- Name: fn_reconcile_stocktake_product(uuid, numeric, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reconcile_stocktake_product(p_product_id uuid, p_target_on_hand numeric, p_target_safety numeric, p_adjustment_id uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_current_on_hand numeric := 0;
  v_current_safety numeric := 0;
  v_total_delta numeric;
  v_normal_lot_qty numeric := 0;
  v_safety_lot_qty numeric := 0;
  v_lot_delta numeric;
  v_remaining numeric;
  v_consume numeric;
  v_unit_cost numeric := 0;
  v_movement_id uuid;
  v_lot record;
BEGIN
  IF p_target_on_hand IS NULL OR p_target_safety IS NULL
     OR p_target_on_hand < 0 OR p_target_safety < 0 THEN
    RAISE EXCEPTION 'Invalid stocktake target for product %', p_product_id;
  END IF;

  INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
  VALUES (p_product_id, 0, 0, 0)
  ON CONFLICT (product_id) DO NOTHING;

  SELECT COALESCE(on_hand, 0), COALESCE(safety_stock, 0)
  INTO v_current_on_hand, v_current_safety
  FROM public.inv_stock_balances
  WHERE product_id = p_product_id
  FOR UPDATE;

  SELECT COALESCE(
    NULLIF(public.fn_get_current_avg_cost(p_product_id), 0),
    NULLIF(p.landed_cost, 0),
    NULLIF(p.unit_cost, 0),
    0
  )
  INTO v_unit_cost
  FROM public.pr_products p
  WHERE p.id = p_product_id;

  v_total_delta := (p_target_on_hand + p_target_safety)
    - (v_current_on_hand + v_current_safety);

  INSERT INTO public.inv_stock_movements (
    product_id, movement_type, qty, ref_type, ref_id, note,
    created_by, unit_cost, total_cost
  )
  VALUES (
    p_product_id, 'stocktake_reconcile', v_total_delta,
    'inv_adjustments', p_adjustment_id, p_note,
    auth.uid(), v_unit_cost, v_total_delta * v_unit_cost
  )
  RETURNING id INTO v_movement_id;

  -- Reconcile normal FIFO lots independently from the possibly stale balance.
  SELECT COALESCE(SUM(qty_remaining), 0)
  INTO v_normal_lot_qty
  FROM public.inv_stock_lots
  WHERE product_id = p_product_id
    AND qty_remaining > 0
    AND COALESCE(is_safety_stock, false) IS false;

  v_lot_delta := p_target_on_hand - v_normal_lot_qty;
  IF v_lot_delta > 0 THEN
    INSERT INTO public.inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost,
      ref_type, ref_id, is_safety_stock
    )
    VALUES (
      p_product_id, v_lot_delta, v_lot_delta, v_unit_cost,
      'stocktake_reconcile', p_adjustment_id, false
    );
  ELSIF v_lot_delta < 0 THEN
    v_remaining := ABS(v_lot_delta);
    FOR v_lot IN
      SELECT id, qty_remaining, unit_cost
      FROM public.inv_stock_lots
      WHERE product_id = p_product_id
        AND qty_remaining > 0
        AND COALESCE(is_safety_stock, false) IS false
      ORDER BY created_at, id
      FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_consume := LEAST(v_lot.qty_remaining, v_remaining);
      UPDATE public.inv_stock_lots
      SET qty_remaining = qty_remaining - v_consume
      WHERE id = v_lot.id;
      INSERT INTO public.inv_lot_consumptions (lot_id, movement_id, qty, unit_cost)
      VALUES (v_lot.id, v_movement_id, v_consume, v_lot.unit_cost);
      v_remaining := v_remaining - v_consume;
    END LOOP;
  END IF;

  -- Reconcile the safety-stock FIFO pool in the same transaction.
  SELECT COALESCE(SUM(qty_remaining), 0)
  INTO v_safety_lot_qty
  FROM public.inv_stock_lots
  WHERE product_id = p_product_id
    AND qty_remaining > 0
    AND COALESCE(is_safety_stock, false) IS true;

  v_lot_delta := p_target_safety - v_safety_lot_qty;
  IF v_lot_delta > 0 THEN
    INSERT INTO public.inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost,
      ref_type, ref_id, is_safety_stock
    )
    VALUES (
      p_product_id, v_lot_delta, v_lot_delta, v_unit_cost,
      'stocktake_reconcile', p_adjustment_id, true
    );
  ELSIF v_lot_delta < 0 THEN
    v_remaining := ABS(v_lot_delta);
    FOR v_lot IN
      SELECT id, qty_remaining, unit_cost
      FROM public.inv_stock_lots
      WHERE product_id = p_product_id
        AND qty_remaining > 0
        AND COALESCE(is_safety_stock, false) IS true
      ORDER BY created_at, id
      FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_consume := LEAST(v_lot.qty_remaining, v_remaining);
      UPDATE public.inv_stock_lots
      SET qty_remaining = qty_remaining - v_consume
      WHERE id = v_lot.id;
      INSERT INTO public.inv_lot_consumptions (lot_id, movement_id, qty, unit_cost)
      VALUES (v_lot.id, v_movement_id, v_consume, v_lot.unit_cost);
      v_remaining := v_remaining - v_consume;
    END LOOP;
  END IF;

  UPDATE public.inv_stock_balances
  SET on_hand = p_target_on_hand,
      safety_stock = p_target_safety,
      updated_at = now()
  WHERE product_id = p_product_id;

  PERFORM public.fn_recalc_product_landed_cost(p_product_id);

  RETURN jsonb_build_object(
    'before_on_hand', v_current_on_hand,
    'before_safety', v_current_safety,
    'after_on_hand', p_target_on_hand,
    'after_safety', p_target_safety,
    'qty_delta', v_total_delta,
    'unit_cost', v_unit_cost
  );
END;
$$;


--
-- Name: fn_release_safety_stock(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_release_safety_stock(p_product_id uuid, p_qty numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_remaining    NUMERIC := p_qty;
  v_lot          RECORD;
  v_consume      NUMERIC;
  v_current_ss   NUMERIC;
BEGIN
  IF p_qty <= 0 THEN RETURN; END IF;

  SELECT COALESCE(safety_stock, 0) INTO v_current_ss
  FROM inv_stock_balances WHERE product_id = p_product_id;

  IF NOT FOUND OR v_current_ss < p_qty THEN
    RAISE EXCEPTION 'safety stock ไม่เพียงพอสำหรับย้ายออก (ต้องการ %, มี %)',
      p_qty, COALESCE(v_current_ss, 0);
  END IF;

  FOR v_lot IN
    SELECT id, qty_remaining, unit_cost
    FROM inv_stock_lots
    WHERE product_id = p_product_id
      AND qty_remaining > 0
      AND is_safety_stock = TRUE
    ORDER BY created_at ASC
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_consume := LEAST(v_lot.qty_remaining, v_remaining);

    UPDATE inv_stock_lots
    SET qty_remaining = qty_remaining - v_consume
    WHERE id = v_lot.id;

    INSERT INTO inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost,
      ref_type, ref_id, is_safety_stock
    )
    VALUES (
      p_product_id, v_consume, v_consume, v_lot.unit_cost,
      'safety_release', v_lot.id, FALSE
    );

    v_remaining := v_remaining - v_consume;
  END LOOP;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'safety lot ไม่เพียงพอสำหรับย้ายออก (ขาด %)', v_remaining;
  END IF;

  UPDATE inv_stock_balances
  SET on_hand      = on_hand + p_qty,
      safety_stock = safety_stock - p_qty,
      updated_at   = NOW()
  WHERE product_id = p_product_id;
END;
$$;


--
-- Name: fn_reservation_audit(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservation_audit(p_product_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(product_id uuid, product_code text, product_name text, unit_name text, on_hand numeric, reserved numeric, document_reserved numeric, wms_reserved numeric, borrow_reserved numeric, linked_reserved numeric, difference numeric, completed_wms_count bigint, uncertain_count bigint, classification text, evidence jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
WITH products AS (
 SELECT p.id,p.product_code,p.product_name,p.unit_name,
   count(*) OVER(PARTITION BY upper(btrim(p.product_code))) AS code_count
 FROM public.pr_products p
), wms AS (
 SELECT p.id AS product_id,w.id,w.order_id,w.qty,w.status,w.status_before_cancel,w.stock_action,
   coalesce(m.net_deducted,0) AS net_deducted,
   CASE WHEN w.status='picked' OR (w.status='cancelled' AND w.status_before_cancel='picked' AND w.stock_action IS NULL)
     THEN coalesce(w.qty,0) ELSE 0 END AS held,
   CASE WHEN p.code_count>1 OR w.qty IS NULL OR w.qty<0 OR w.status IS NULL
     OR w.status NOT IN ('pending','picked','correct','out_of_stock','cancelled','returned')
     OR (w.status='correct' AND coalesce(m.net_deducted,0)<coalesce(w.qty,0))
     OR (w.status='cancelled' AND w.stock_action IS NULL AND w.status_before_cancel IS NULL)
     OR (w.status='returned' AND coalesce(m.net_deducted,0)>0)
     THEN 1 ELSE 0 END AS uncertain
 FROM public.wms_orders w JOIN products p ON upper(btrim(p.product_code))=upper(btrim(w.product_code))
 LEFT JOIN LATERAL (
   SELECT coalesce(sum(-sm.qty),0) AS net_deducted FROM public.inv_stock_movements sm
   WHERE sm.ref_type='wms_orders' AND sm.ref_id=w.id AND sm.product_id=p.id
     AND sm.movement_type IN ('pick','pick_reversal','return_pick')
 ) m ON true
), wms_totals AS (
 SELECT w.product_id,sum(w.held) AS held,sum(w.uncertain)::bigint AS uncertain,
   count(*) FILTER(WHERE w.status='correct' AND w.qty>0 AND w.net_deducted>=w.qty) AS completed,
   coalesce(jsonb_agg(jsonb_build_object('wms_id',w.id,'work_order',w.order_id,'qty',w.qty,
     'status',w.status,'net_deducted',w.net_deducted,'uncertain',w.uncertain)), '[]'::jsonb) AS evidence
 FROM wms w GROUP BY w.product_id
), documents AS (
 SELECT r.product_id,sum(r.qty) AS held,
   count(*) FILTER(WHERE (r.source_type='order' AND o.id IS NULL) OR (r.source_type='prebill' AND d.id IS NULL)
     OR (r.source_type='prebill' AND (d.status IN ('draft','cancelled','converted','expired') OR d.valid_until<timezone('Asia/Bangkok',now())::date))
     OR (r.source_type='order' AND o.status IN ('ยกเลิก','จัดส่งแล้ว'))) AS uncertain
 FROM public.inv_document_reservations r
 LEFT JOIN public.or_orders o ON r.source_type='order' AND o.id=r.source_id
 LEFT JOIN public.or_prebill_documents d ON r.source_type='prebill' AND d.id=r.source_id
 WHERE r.qty>0 GROUP BY r.product_id
), borrows AS (
 SELECT i.product_id,
   sum(CASE WHEN b.status IN ('approved','partial_returned','overdue')
     THEN greatest(i.qty-coalesce(i.returned_qty,0)-coalesce(i.written_off_qty,0),0) ELSE 0 END) AS held,
   count(*) FILTER(WHERE b.status IS NULL OR b.status NOT IN ('pending','approved','partial_returned','overdue','returned','written_off','cancelled','rejected')
     OR i.qty<0 OR coalesce(i.returned_qty,0)+coalesce(i.written_off_qty,0)>i.qty) AS uncertain
 FROM public.wms_borrow_requisition_items i JOIN public.wms_borrow_requisitions b ON b.id=i.borrow_requisition_id
 GROUP BY i.product_id
), amounts AS (
 SELECT p.id AS product_id,p.product_code,p.product_name,p.unit_name,coalesce(b.on_hand,0) AS on_hand,
   coalesce(b.reserved,0) AS reserved,coalesce(d.held,0) AS document_reserved,
   coalesce(w.held,0) AS wms_reserved,coalesce(br.held,0) AS borrow_reserved,
   coalesce(d.held,0)+coalesce(w.held,0)+coalesce(br.held,0) AS linked_reserved,
   coalesce(w.completed,0) AS completed_wms_count,
   coalesce(w.uncertain,0)+coalesce(d.uncertain,0)+coalesce(br.uncertain,0)+CASE WHEN p.code_count>1 THEN 1 ELSE 0 END AS uncertain_count,
   coalesce(w.evidence,'[]'::jsonb) AS wms_evidence
 FROM products p JOIN public.inv_stock_balances b ON b.product_id=p.id
 LEFT JOIN documents d ON d.product_id=p.id LEFT JOIN wms_totals w ON w.product_id=p.id
 LEFT JOIN borrows br ON br.product_id=p.id
 WHERE p_product_ids IS NULL OR p.id=ANY(p_product_ids)
)
SELECT a.product_id,a.product_code,a.product_name,a.unit_name,a.on_hand,a.reserved,
 a.document_reserved,a.wms_reserved,a.borrow_reserved,a.linked_reserved,a.reserved-a.linked_reserved,
 a.completed_wms_count,a.uncertain_count,
 CASE WHEN a.reserved=a.linked_reserved THEN 'matched'
   WHEN a.uncertain_count>0 THEN 'requires_review'
   WHEN a.reserved<a.linked_reserved THEN 'under_reserved'
   WHEN a.completed_wms_count>0 AND a.linked_reserved<=a.on_hand THEN 'excess_with_completed_evidence'
   ELSE 'unexplained_excess' END,
 jsonb_build_object('wms',a.wms_evidence,'document_reserved',a.document_reserved,'wms_reserved',a.wms_reserved,'borrow_reserved',a.borrow_reserved)
FROM amounts a ORDER BY a.product_code,a.product_id;
$$;


--
-- Name: fn_reverse_wms_stock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reverse_wms_stock(p_wms_order_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_movement RECORD;
  v_consumption RECORD;
  v_product_id UUID;
  v_total_returned NUMERIC := 0;
  v_wms RECORD;
  v_reserved_qty NUMERIC := 0;
BEGIN
  SELECT id, status, product_code, qty, stock_action, source_order_item_id, order_id
  INTO v_wms FROM public.wms_orders WHERE id = p_wms_order_id;
  IF v_wms.id IS NULL OR v_wms.stock_action IS NOT NULL THEN RETURN 0; END IF;

  SELECT sm.id, sm.product_id, sm.qty, sm.unit_cost
  INTO v_movement
  FROM public.inv_stock_movements sm
  WHERE sm.ref_type = 'wms_orders' AND sm.ref_id = p_wms_order_id AND sm.movement_type = 'pick'
  ORDER BY sm.created_at DESC LIMIT 1;

  IF v_movement.id IS NULL THEN
    SELECT id INTO v_product_id FROM public.pr_products WHERE product_code = v_wms.product_code LIMIT 1;
    IF v_wms.status = 'picked' AND v_product_id IS NOT NULL THEN
      v_reserved_qty := COALESCE(v_wms.qty, 0);
      UPDATE public.inv_stock_balances
      SET reserved = GREATEST(COALESCE(reserved, 0) - v_reserved_qty, 0), updated_at = NOW()
      WHERE product_id = v_product_id;
    END IF;
    UPDATE public.wms_orders SET stock_action = 'recalled' WHERE id = p_wms_order_id;
    IF v_wms.source_order_item_id IS NOT NULL THEN
      UPDATE public.or_order_items SET cancellation_stock_action = 'recalled' WHERE id = v_wms.source_order_item_id;
    END IF;
    RETURN v_reserved_qty;
  END IF;

  v_product_id := v_movement.product_id;
  FOR v_consumption IN
    SELECT lc.lot_id, lc.qty FROM public.inv_lot_consumptions lc WHERE lc.movement_id = v_movement.id
  LOOP
    UPDATE public.inv_stock_lots SET qty_remaining = qty_remaining + v_consumption.qty WHERE id = v_consumption.lot_id;
    v_total_returned := v_total_returned + v_consumption.qty;
  END LOOP;

  INSERT INTO public.inv_stock_movements
    (product_id, movement_type, qty, ref_type, ref_id, note, unit_cost, total_cost)
  VALUES
    (v_product_id, 'pick_reversal', v_total_returned, 'wms_orders', p_wms_order_id,
     'Stock recall after cancelled bill', COALESCE(v_movement.unit_cost, 0),
     v_total_returned * COALESCE(v_movement.unit_cost, 0));

  UPDATE public.inv_stock_balances
  SET on_hand = COALESCE(on_hand, 0) + v_total_returned, updated_at = NOW()
  WHERE product_id = v_product_id;
  PERFORM public.fn_recalc_product_landed_cost(v_product_id);
  UPDATE public.wms_orders SET stock_action = 'recalled' WHERE id = p_wms_order_id;

  IF v_wms.source_order_item_id IS NOT NULL THEN
    UPDATE public.or_order_items SET cancellation_stock_action = 'recalled' WHERE id = v_wms.source_order_item_id;
  ELSE
    UPDATE public.or_order_items oi
    SET cancellation_stock_action = 'recalled'
    FROM public.or_orders o, public.pr_products p
    WHERE oi.order_id = o.id AND p.id = oi.product_id
      AND oi.cancellation_stock_action = 'pending'
      AND TRIM(COALESCE(o.work_order_name, '')) = TRIM(COALESCE(v_wms.order_id, ''))
      AND UPPER(TRIM(COALESCE(p.product_code::TEXT, ''))) = UPPER(TRIM(COALESCE(v_wms.product_code, '')));
  END IF;
  RETURN v_total_returned;
END;
$$;


--
-- Name: fn_set_document_reservation(text, uuid, uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_set_document_reservation(p_type text, p_source uuid, p_product uuid, p_qty numeric, p_expires date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_old numeric; v_available numeric; v_id uuid;
BEGIN
  INSERT INTO public.inv_stock_balances(product_id,on_hand,reserved,safety_stock)
  VALUES(p_product,0,0,0) ON CONFLICT(product_id) DO NOTHING;
  SELECT coalesce(on_hand,0)-coalesce(reserved,0) INTO v_available
  FROM public.inv_stock_balances WHERE product_id=p_product FOR UPDATE;
  SELECT qty,id INTO v_old,v_id FROM public.inv_document_reservations
  WHERE source_type=p_type AND source_id=p_source AND product_id=p_product FOR UPDATE;
  v_old:=coalesce(v_old,0);
  IF p_qty > v_old AND p_qty-v_old > v_available THEN
    RAISE EXCEPTION 'สต๊อกพร้อมขายไม่พอสำหรับจองสินค้า %: เพิ่มจอง % แต่พร้อมขาย %',p_product,p_qty-v_old,v_available;
  END IF;
  INSERT INTO public.inv_document_reservations(source_type,source_id,product_id,qty,expires_on)
  VALUES(p_type,p_source,p_product,p_qty,p_expires)
  ON CONFLICT(source_type,source_id,product_id) DO UPDATE
  SET qty=excluded.qty,expires_on=excluded.expires_on,updated_at=now()
  RETURNING id INTO v_id;
  IF p_qty <> v_old THEN
    UPDATE public.inv_stock_balances SET reserved=coalesce(reserved,0)+p_qty-v_old,updated_at=now() WHERE product_id=p_product;
    INSERT INTO public.inv_document_reservation_history(reservation_id,source_type,source_id,product_id,old_qty,new_qty)
    VALUES(v_id,p_type,p_source,p_product,v_old,p_qty);
  END IF;
END $$;


--
-- Name: fn_snapshot_wms_notification_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_snapshot_wms_notification_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_item public.wms_orders%ROWTYPE;
BEGIN
  IF NEW.wms_order_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_item FROM public.wms_orders WHERE id=NEW.wms_order_id;
  IF NOT FOUND OR v_item.order_id IS DISTINCT FROM NEW.order_id THEN
    RAISE EXCEPTION 'รายการสินค้าแจ้งเตือนไม่ตรงกับใบงาน';
  END IF;
  NEW.product_code:=v_item.product_code;
  NEW.product_name:=v_item.product_name;
  NEW.location:=v_item.location;
  RETURN NEW;
END $$;


--
-- Name: fn_stamp_wms_review_completed_at(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_stamp_wms_review_completed_at(p_work_order_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total INTEGER := 0;
  v_incomplete INTEGER := 0;
  v_completed_at TIMESTAMPTZ;
BEGIN
  IF p_work_order_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (
      WHERE w.status NOT IN ('correct', 'wrong', 'not_find', 'out_of_stock', 'returned')
    ),
    MAX(COALESCE(w.end_time, w.created_at))
  INTO v_total, v_incomplete, v_completed_at
  FROM public.wms_orders w
  WHERE w.work_order_id = p_work_order_id
    AND (w.fulfillment_mode = 'warehouse_pick' OR w.fulfillment_mode IS NULL)
    AND (
      w.status <> 'cancelled'
      OR (w.status = 'cancelled' AND w.stock_action = 'recalled')
    );

  IF v_total = 0 OR v_incomplete > 0 THEN
    RETURN NULL;
  END IF;

  v_completed_at := COALESCE(v_completed_at, NOW());

  UPDATE public.or_work_orders wo
  SET wms_review_completed_at = COALESCE(wo.wms_review_completed_at, v_completed_at)
  WHERE wo.id = p_work_order_id
  RETURNING wo.wms_review_completed_at INTO v_completed_at;

  RETURN v_completed_at;
END;
$$;


--
-- Name: fn_sync_document_reservations(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_document_reservations(p_type text, p_source uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record; v_enabled boolean; v_status text; v_exp date; v_qty numeric; v_claim_ready boolean:=true;
BEGIN
  IF current_setting('app.reservation_save',true)=p_type||':'||p_source::text THEN RETURN; END IF;
  IF p_type='prebill' THEN
    SELECT stock_reservation_enabled,status,valid_until INTO v_enabled,v_status,v_exp
    FROM public.or_prebill_documents WHERE id=p_source FOR UPDATE;
  ELSE
    SELECT stock_reservation_enabled,status,(bill_no NOT LIKE 'REQ%' OR claim_shipping_confirmed_at IS NOT NULL) INTO v_enabled,v_status,v_claim_ready FROM public.or_orders WHERE id=p_source FOR UPDATE;
  END IF;
  IF NOT coalesce(v_enabled,false) AND NOT EXISTS(SELECT 1 FROM public.inv_document_reservations WHERE source_type=p_type AND source_id=p_source AND qty>0) THEN RETURN; END IF;
  FOR r IN
    SELECT product_id FROM public.inv_document_reservations WHERE source_type=p_type AND source_id=p_source
    UNION SELECT product_id FROM public.or_prebill_items WHERE p_type='prebill' AND document_id=p_source AND product_id IS NOT NULL
    UNION SELECT product_id FROM public.or_order_items WHERE p_type='order' AND order_id=p_source AND product_id IS NOT NULL
    ORDER BY product_id
  LOOP
    v_qty:=0;
    IF v_enabled AND p_type='prebill' AND v_status IN ('active','pending_discount','approved','rejected')
       AND v_exp >= timezone('Asia/Bangkok',now())::date THEN
      SELECT coalesce(sum(quantity),0) INTO v_qty FROM public.or_prebill_items
      WHERE document_id=p_source AND product_id=r.product_id AND NOT coalesce(is_detail_row,false);
    ELSIF v_enabled AND v_claim_ready AND p_type='order' AND v_status NOT IN ('รอลงข้อมูล','ยกเลิก','จัดส่งแล้ว') THEN
      SELECT coalesce(sum(greatest(i.quantity-coalesce(w.covered,0),0)),0) INTO v_qty
      FROM public.or_order_items i
      LEFT JOIN LATERAL (
        SELECT sum(greatest(coalesce(m.net_deducted,0),CASE WHEN x.status IN ('picked','cancelled') THEN x.qty ELSE 0 END)) AS covered
        FROM public.wms_orders x
        LEFT JOIN LATERAL (SELECT greatest(coalesce(sum(-sm.qty),0),0) AS net_deducted FROM public.inv_stock_movements sm
          WHERE sm.ref_type='wms_orders' AND sm.ref_id=x.id AND sm.movement_type IN ('pick','pick_reversal')) m ON true
        WHERE x.source_order_item_id=i.id
      ) w ON true
      WHERE i.order_id=p_source AND i.product_id=r.product_id
        AND NOT coalesce(i.is_detail_row,false) AND i.cancellation_stock_action IS NULL;
    END IF;
    PERFORM public.fn_set_document_reservation(p_type,p_source,r.product_id,v_qty,v_exp);
  END LOOP;
END $$;


--
-- Name: fn_sync_plan_pick_end_from_wms(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_plan_pick_end_from_wms(p_work_order_id uuid, p_completed_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total INT;
  v_incomplete INT;
  v_job_id TEXT;
  v_job_name TEXT;
  v_tracks JSONB;
  v_dept JSONB;
  v_patch JSONB := '{}'::jsonb;
  v_ts TIMESTAMPTZ;
BEGIN
  IF p_work_order_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_work_order_id');
  END IF;

  -- Only rows visible in the WMS review flow participate. Cancelled/recalled
  -- rows remain incomplete until warehouse staff physically return them.
  SELECT
    COUNT(*),
    COUNT(*) FILTER (
      WHERE w.status NOT IN ('correct', 'wrong', 'not_find', 'out_of_stock', 'returned')
    )
  INTO v_total, v_incomplete
  FROM public.wms_orders w
  WHERE w.work_order_id = p_work_order_id
    AND (
      (w.fulfillment_mode = 'warehouse_pick' AND w.status <> 'cancelled')
      OR (w.fulfillment_mode = 'warehouse_pick' AND w.status = 'cancelled' AND w.stock_action = 'recalled')
      OR (w.fulfillment_mode IS NULL AND w.status <> 'cancelled')
      OR (w.fulfillment_mode IS NULL AND w.status = 'cancelled' AND w.stock_action = 'recalled')
    );

  IF v_total = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_wms_review_rows');
  END IF;

  IF v_incomplete > 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'inspect_not_complete',
      'incomplete_count', v_incomplete
    );
  END IF;

  -- Prefer the UUID relation. The name fallback repairs legacy rows created
  -- before work_order_id was added to plan_jobs.
  SELECT pj.id, pj.name, COALESCE(pj.tracks, '{}'::jsonb)
  INTO v_job_id, v_job_name, v_tracks
  FROM public.plan_jobs pj
  WHERE pj.work_order_id = p_work_order_id
  ORDER BY pj.date DESC, pj.order_index DESC
  LIMIT 1;

  IF v_job_id IS NULL THEN
    SELECT wo.work_order_name INTO v_job_name
    FROM public.or_work_orders wo
    WHERE wo.id = p_work_order_id;

    SELECT pj.id, COALESCE(pj.tracks, '{}'::jsonb)
    INTO v_job_id, v_tracks
    FROM public.plan_jobs pj
    WHERE pj.name = v_job_name
    ORDER BY pj.date DESC, pj.order_index DESC
    LIMIT 1;
  END IF;

  IF v_job_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'plan_job_not_found');
  END IF;

  v_dept := COALESCE(v_tracks -> 'เบิก', '{}'::jsonb);

  -- Preserve an existing actual end. Fill only the missing process(es).
  IF (v_dept -> 'หยิบของ' ->> 'end') IS NULL THEN
    v_patch := v_patch || jsonb_build_object(
      'หยิบของ', jsonb_build_object(
        'start_if_null', to_jsonb(COALESCE(p_completed_at, NOW())),
        'end', to_jsonb(COALESCE(p_completed_at, NOW()))
      )
    );
  END IF;

  IF (v_dept -> 'ส่งมอบ' ->> 'end') IS NULL THEN
    v_patch := v_patch || jsonb_build_object(
      'ส่งมอบ', jsonb_build_object(
        'start_if_null', to_jsonb(COALESCE(p_completed_at, NOW())),
        'end', to_jsonb(COALESCE(p_completed_at, NOW()))
      )
    );
  END IF;

  IF v_patch = '{}'::jsonb THEN
    RETURN jsonb_build_object(
      'success', true,
      'synced', false,
      'reason', 'already_stamped',
      'plan_job_id', v_job_id
    );
  END IF;

  -- For historical repair, use the WMS completion time when available.
  IF p_completed_at IS NULL THEN
    SELECT MAX(w.end_time) INTO v_ts
    FROM public.wms_orders w
    WHERE w.work_order_id = p_work_order_id
      AND (w.fulfillment_mode = 'warehouse_pick' OR w.fulfillment_mode IS NULL);

    v_ts := COALESCE(v_ts, NOW());
    v_patch := (
      SELECT jsonb_object_agg(
        entry.key,
        jsonb_set(
          jsonb_set(entry.value, '{start_if_null}', to_jsonb(v_ts), true),
          '{end}', to_jsonb(v_ts), true
        )
      )
      FROM jsonb_each(v_patch) AS entry
    );
  END IF;

  PERFORM public.merge_plan_tracks(v_job_id, 'เบิก', v_patch);

  RETURN jsonb_build_object(
    'success', true,
    'synced', true,
    'plan_job_id', v_job_id,
    'completed_at', COALESCE(p_completed_at, v_ts)
  );
END;
$$;


--
-- Name: FUNCTION fn_sync_plan_pick_end_from_wms(p_work_order_id uuid, p_completed_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_sync_plan_pick_end_from_wms(p_work_order_id uuid, p_completed_at timestamp with time zone) IS 'ปิดเวลา Plan แผนกเบิกเมื่อรายการ WMS ของใบงานตรวจครบ และใช้ซ่อมข้อมูลเดิมได้';


--
-- Name: fn_sync_wms_document_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_wms_document_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_source uuid;
BEGIN
  v_source:=coalesce(NEW.source_order_id,OLD.source_order_id);
  IF v_source IS NULL THEN
    SELECT order_id INTO v_source FROM public.or_order_items WHERE id=coalesce(NEW.source_order_item_id,OLD.source_order_item_id);
  END IF;
  IF v_source IS NOT NULL THEN PERFORM public.fn_sync_document_reservations('order',v_source); END IF;
  RETURN NULL;
END $$;


--
-- Name: fn_transfer_document_reservation_to_wms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_transfer_document_reservation_to_wms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_order uuid; v_product uuid; v_qty numeric;
BEGIN
  IF NEW.status NOT IN ('picked','correct') OR NEW.status IS NOT DISTINCT FROM OLD.status
     OR OLD.status IN ('picked','correct') OR NEW.source_order_item_id IS NULL THEN RETURN NEW; END IF;
  SELECT i.order_id,i.product_id INTO v_order,v_product FROM public.or_order_items i
  JOIN public.or_orders o ON o.id=i.order_id AND o.stock_reservation_enabled
  WHERE i.id=NEW.source_order_item_id AND NOT coalesce(i.is_detail_row,false);
  IF v_product IS NULL THEN RETURN NEW; END IF;
  PERFORM 1 FROM public.or_orders WHERE id=v_order FOR UPDATE;
  PERFORM 1 FROM public.inv_stock_balances WHERE product_id=v_product FOR UPDATE;
  SELECT qty INTO v_qty FROM public.inv_document_reservations WHERE source_type='order' AND source_id=v_order AND product_id=v_product;
  PERFORM public.fn_set_document_reservation('order',v_order,v_product,greatest(coalesce(v_qty,0)-NEW.qty,0));
  RETURN NEW;
END $$;


--
-- Name: fn_transfer_prebill_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_transfer_prebill_reservations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
  IF NEW.source_prebill_document_id IS NOT NULL AND NEW.stock_reservation_enabled THEN
    PERFORM 1 FROM public.or_prebill_documents WHERE id=NEW.source_prebill_document_id
      AND status IN ('active','approved') AND valid_until>=timezone('Asia/Bangkok',now())::date
      AND public.can_manage_prebill_document(owner_id) FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'เอกสารต้นทางไม่พร้อมเปิดบิลหรือไม่มีสิทธิ์'; END IF;
    FOR r IN SELECT product_id FROM public.inv_document_reservations
      WHERE source_type='prebill' AND source_id=NEW.source_prebill_document_id AND qty>0 ORDER BY product_id
    LOOP PERFORM public.fn_set_document_reservation('prebill',NEW.source_prebill_document_id,r.product_id,0); END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_transfer_to_safety_stock(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_transfer_to_safety_stock(p_product_id uuid, p_qty numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_remaining    NUMERIC := p_qty;
  v_lot          RECORD;
  v_consume      NUMERIC;
  v_current_oh   NUMERIC;
BEGIN
  IF p_qty <= 0 THEN RETURN; END IF;

  SELECT COALESCE(on_hand, 0) INTO v_current_oh
  FROM inv_stock_balances WHERE product_id = p_product_id;

  IF NOT FOUND OR v_current_oh < p_qty THEN
    RAISE EXCEPTION 'on_hand ไม่เพียงพอสำหรับย้ายเข้า safety stock (ต้องการ %, มี %)',
      p_qty, COALESCE(v_current_oh, 0);
  END IF;

  FOR v_lot IN
    SELECT id, qty_remaining, unit_cost
    FROM inv_stock_lots
    WHERE product_id = p_product_id
      AND qty_remaining > 0
      AND is_safety_stock = FALSE
    ORDER BY created_at ASC
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_consume := LEAST(v_lot.qty_remaining, v_remaining);

    UPDATE inv_stock_lots
    SET qty_remaining = qty_remaining - v_consume
    WHERE id = v_lot.id;

    INSERT INTO inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost,
      ref_type, ref_id, is_safety_stock
    )
    VALUES (
      p_product_id, v_consume, v_consume, v_lot.unit_cost,
      'safety_transfer', v_lot.id, TRUE
    );

    v_remaining := v_remaining - v_consume;
  END LOOP;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'lot ปกติไม่เพียงพอสำหรับย้ายเข้า safety stock (ขาด %)', v_remaining;
  END IF;

  UPDATE inv_stock_balances
  SET on_hand      = on_hand - p_qty,
      safety_stock = safety_stock + p_qty,
      updated_at   = NOW()
  WHERE product_id = p_product_id;
END;
$$;


--
-- Name: fn_update_product_landed_costs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_update_product_landed_costs(p_po_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_total_received_qty NUMERIC;
  v_intl_thb      NUMERIC;
  v_intl_cpp      NUMERIC;
  v_gr_rec        RECORD;
  v_dom_cpp       NUMERIC;
  v_gr_total_recv NUMERIC;
  v_lot_rec       RECORD;
  v_unit_price    NUMERIC;
BEGIN
  SELECT COALESCE(SUM(gi.qty_received), 0)
  INTO v_total_received_qty
  FROM inv_gr_items gi
  JOIN inv_gr g ON g.id = gi.gr_id
  WHERE g.po_id = p_po_id;

  IF v_total_received_qty = 0 THEN RETURN; END IF;

  SELECT COALESCE(intl_shipping_cost_thb, 0) INTO v_intl_thb FROM inv_po WHERE id = p_po_id;
  v_intl_cpp := v_intl_thb / v_total_received_qty;

  FOR v_gr_rec IN
    SELECT gr.id AS gr_id, COALESCE(gr.dom_shipping_cost, 0) AS dom_cost
    FROM inv_gr gr WHERE gr.po_id = p_po_id
  LOOP
    SELECT COALESCE(SUM(qty_received), 0) INTO v_gr_total_recv
    FROM inv_gr_items WHERE gr_id = v_gr_rec.gr_id;

    v_dom_cpp := CASE WHEN v_gr_total_recv > 0 THEN v_gr_rec.dom_cost / v_gr_total_recv ELSE 0 END;

    FOR v_lot_rec IN
      SELECT sl.id AS lot_id, sl.product_id
      FROM inv_stock_lots sl
      WHERE sl.ref_type = 'inv_gr' AND sl.ref_id = v_gr_rec.gr_id
    LOOP
      SELECT COALESCE(unit_price, 0) INTO v_unit_price
      FROM inv_po_items
      WHERE po_id = p_po_id AND product_id = v_lot_rec.product_id
      LIMIT 1;

      UPDATE inv_stock_lots
      SET unit_cost = v_unit_price + v_intl_cpp + v_dom_cpp
      WHERE id = v_lot_rec.lot_id;
    END LOOP;
  END LOOP;

  FOR v_lot_rec IN
    SELECT DISTINCT product_id FROM inv_po_items WHERE po_id = p_po_id
  LOOP
    PERFORM fn_recalc_product_landed_cost(v_lot_rec.product_id);
  END LOOP;
END;
$$;


--
-- Name: fn_upsert_pr_seller_from_product(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_upsert_pr_seller_from_product(p_name text, p_name_cn text DEFAULT NULL::text, p_purchase_channel text DEFAULT NULL::text, p_seller_type text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name TEXT := trim(COALESCE(p_name, ''));
  v_name_cn TEXT := NULLIF(trim(COALESCE(p_name_cn, '')), '');
  v_channel TEXT := NULLIF(trim(COALESCE(p_purchase_channel, '')), '');
  v_type TEXT := fn_normalize_seller_type(p_seller_type);
BEGIN
  IF v_name = '' THEN
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pr_sellers WHERE name = v_name) THEN
    INSERT INTO pr_sellers (name, name_cn, purchase_channel, seller_type, is_active)
    VALUES (
      v_name,
      COALESCE(v_name_cn, ''),
      COALESCE(v_channel, ''),
      COALESCE(v_type, 'foreign'),
      TRUE
    );
    RETURN;
  END IF;

  UPDATE pr_sellers SET
    name_cn = CASE
      WHEN v_name_cn IS NOT NULL AND v_name_cn <> '' THEN v_name_cn
      ELSE name_cn
    END,
    purchase_channel = CASE
      WHEN v_channel IS NOT NULL AND v_channel <> '' THEN v_channel
      ELSE purchase_channel
    END,
    seller_type = CASE
      WHEN v_type IS NOT NULL THEN v_type
      ELSE seller_type
    END,
    is_active = TRUE,
    updated_at = NOW()
  WHERE name = v_name;
END;
$$;


--
-- Name: FUNCTION fn_upsert_pr_seller_from_product(p_name text, p_name_cn text, p_purchase_channel text, p_seller_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_upsert_pr_seller_from_product(p_name text, p_name_cn text, p_purchase_channel text, p_seller_type text) IS 'สร้าง/อัปเดต pr_sellers จากฟิลด์ผู้ขายบนสินค้า — อัปเดตเฉพาะฟิลด์ที่ส่งมาและไม่ว่าง';


--
-- Name: fn_upsert_roll_config(uuid, uuid, uuid, numeric, numeric, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_upsert_roll_config(p_fg_product_id uuid, p_rm_product_id uuid, p_category_id uuid DEFAULT NULL::uuid, p_sheets numeric DEFAULT NULL::numeric, p_cost numeric DEFAULT NULL::numeric, p_rm_product_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id UUID;
  v_primary_rm UUID;
  v_rm_ids UUID[];
BEGIN
  IF p_rm_product_ids IS NOT NULL AND COALESCE(array_length(p_rm_product_ids, 1), 0) > 0 THEN
    v_rm_ids := p_rm_product_ids;
  ELSIF p_rm_product_id IS NOT NULL THEN
    v_rm_ids := ARRAY[p_rm_product_id];
  ELSE
    v_rm_ids := ARRAY[]::UUID[];
  END IF;

  IF COALESCE(array_length(v_rm_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'ต้องเลือกรายการ RM อย่างน้อย 1 รายการ';
  END IF;

  v_primary_rm := v_rm_ids[1];

  INSERT INTO roll_material_configs (fg_product_id, rm_product_id, category_id, sheets_per_roll, cost_per_sheet)
  VALUES (p_fg_product_id, v_primary_rm, p_category_id, p_sheets, p_cost)
  ON CONFLICT (fg_product_id) DO UPDATE SET
    rm_product_id   = EXCLUDED.rm_product_id,
    category_id     = EXCLUDED.category_id,
    sheets_per_roll = EXCLUDED.sheets_per_roll,
    cost_per_sheet  = EXCLUDED.cost_per_sheet,
    updated_at      = now()
  RETURNING id INTO v_id;

  DELETE FROM roll_material_config_rms WHERE config_id = v_id;
  INSERT INTO roll_material_config_rms (config_id, rm_product_id)
  SELECT v_id, x
  FROM unnest(v_rm_ids) AS x
  ON CONFLICT (config_id, rm_product_id) DO NOTHING;

  RETURN v_id;
END;
$$;


--
-- Name: fn_validate_production_items_batch(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_production_items_batch(p_items jsonb) RETURNS TABLE(pp_product_id uuid, include_product_code text, needed numeric, on_hand numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_item      JSONB;
  v_recipe_id UUID;
  v_inc       RECORD;
  v_oh        NUMERIC;
  v_need      NUMERIC;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT r.id INTO v_recipe_id
    FROM pp_recipes r
    WHERE r.product_id = (v_item->>'product_id')::UUID;

    IF v_recipe_id IS NULL THEN CONTINUE; END IF;

    FOR v_inc IN
      SELECT ri.product_id AS inc_pid, ri.qty,
             p.product_code AS inc_code
      FROM pp_recipe_includes ri
      JOIN pr_products p ON p.id = ri.product_id
      WHERE ri.recipe_id = v_recipe_id AND ri.qty > 0
    LOOP
      v_need := v_inc.qty * (v_item->>'qty')::NUMERIC;

      SELECT COALESCE(sb.on_hand, 0) INTO v_oh
      FROM inv_stock_balances sb
      WHERE sb.product_id = v_inc.inc_pid;

      v_oh := COALESCE(v_oh, 0);

      IF v_oh < v_need THEN
        pp_product_id := (v_item->>'product_id')::UUID;
        include_product_code := v_inc.inc_code;
        needed := v_need;
        on_hand := v_oh;
        RETURN NEXT;
      END IF;
    END LOOP;
  END LOOP;
END;
$$;


--
-- Name: fn_wms_is_pickable_category(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_is_pickable_category(p_cat text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN NULLIF(BTRIM(COALESCE(p_cat,'')),'') IS NULL THEN false
    WHEN EXISTS (
      SELECT 1 FROM public.wms_non_picker_categories c
      WHERE UPPER(BTRIM(c.category_name))=UPPER(BTRIM(p_cat))
    ) THEN false
    ELSE true
  END;
$$;


--
-- Name: FUNCTION fn_wms_is_pickable_category(p_cat text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_wms_is_pickable_category(p_cat text) IS 'false=system_complete จากเมนูหมวดสินค้าไม่ต้อง Picker; หมวดใหม่ที่ยังไม่ตั้งค่า default เป็นต้อง Picker';


--
-- Name: fn_wms_is_sub_warehouse_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_is_sub_warehouse_product(p_product_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p_product_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.wh_sub_warehouse_products swp
    JOIN public.wh_sub_warehouses sw ON sw.id=swp.sub_warehouse_id
    WHERE swp.product_id=p_product_id AND sw.is_active
  );
$$;


--
-- Name: fn_wms_item_fulfillment_mode(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_item_fulfillment_mode(p_product_id uuid, p_category text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN public.fn_wms_is_sub_warehouse_product(p_product_id) THEN 'sub_warehouse_skip'
    WHEN public.fn_wms_is_pickable_category(p_category) THEN 'warehouse_pick'
    ELSE 'system_complete'
  END;
$$;


--
-- Name: FUNCTION fn_wms_item_fulfillment_mode(p_product_id uuid, p_category text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_wms_item_fulfillment_mode(p_product_id uuid, p_category text) IS 'warehouse_pick=Picker คลังหลัก, system_complete=ตัดคลังหลักอัตโนมัติ, sub_warehouse_skip=สินค้าคลังย่อยที่ข้าม Picker แต่ยังตัดสต๊อคหลักอัตโนมัติ';


--
-- Name: fn_wms_item_has_legacy_stock_conflict(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_item_has_legacy_stock_conflict(p_order_item_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item RECORD;
  v_linked_correct NUMERIC := 0;
  v_linked_movement NUMERIC := 0;
BEGIN
  SELECT oi.id,oi.order_id source_order_id,o.work_order_id,o.work_order_name,p.product_code::TEXT product_code
  INTO v_item
  FROM public.or_order_items oi
  JOIN public.or_orders o ON o.id=oi.order_id
  JOIN public.pr_products p ON p.id=oi.product_id
  WHERE oi.id=p_order_item_id;
  IF v_item.id IS NULL THEN RETURN true; END IF;

  -- A legacy WMS row cannot be allocated safely to a particular bill line.
  IF EXISTS (
    SELECT 1
    FROM public.wms_orders w
    WHERE w.source_order_item_id IS NULL
      AND UPPER(BTRIM(COALESCE(w.product_code,'')))=UPPER(BTRIM(COALESCE(v_item.product_code,'')))
      AND (w.work_order_id=v_item.work_order_id OR w.source_order_id=v_item.source_order_id OR
        (w.work_order_id IS NULL AND BTRIM(COALESCE(w.order_id,''))=BTRIM(COALESCE(v_item.work_order_name,''))))
      AND (
        w.status<>'cancelled'
        OR EXISTS (
          SELECT 1 FROM public.inv_stock_movements m
          WHERE m.ref_type='wms_orders' AND m.ref_id=w.id
          GROUP BY m.ref_id HAVING COALESCE(SUM(-m.qty) FILTER
            (WHERE m.movement_type IN ('pick','pick_reversal')),0)<>0
        )
      )
  ) THEN RETURN true; END IF;

  SELECT COALESCE(SUM(w.qty) FILTER (WHERE w.status='correct'),0)
  INTO v_linked_correct
  FROM public.wms_orders w WHERE w.source_order_item_id=p_order_item_id;

  SELECT COALESCE(SUM(-m.qty) FILTER (WHERE m.movement_type IN ('pick','pick_reversal')),0)
  INTO v_linked_movement
  FROM public.wms_orders w
  JOIN public.inv_stock_movements m ON m.ref_type='wms_orders' AND m.ref_id=w.id
  WHERE w.source_order_item_id=p_order_item_id;

  RETURN v_linked_correct<>v_linked_movement;
END;
$$;


--
-- Name: fn_wms_item_has_unlinked_legacy_conflict(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_item_has_unlinked_legacy_conflict(p_order_item_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.or_order_items oi
    JOIN public.or_orders o ON o.id=oi.order_id
    JOIN public.pr_products p ON p.id=oi.product_id
    JOIN public.wms_orders w ON w.source_order_item_id IS NULL
      AND UPPER(BTRIM(COALESCE(w.product_code,'')))=UPPER(BTRIM(COALESCE(p.product_code::TEXT,'')))
      AND (w.work_order_id=o.work_order_id OR w.source_order_id=o.id OR
        (w.work_order_id IS NULL AND BTRIM(COALESCE(w.order_id,''))=BTRIM(COALESCE(o.work_order_name,''))))
    WHERE oi.id=p_order_item_id
      AND (
        w.status<>'cancelled'
        OR EXISTS (
          SELECT 1 FROM public.inv_stock_movements m
          WHERE m.ref_type='wms_orders' AND m.ref_id=w.id
          GROUP BY m.ref_id HAVING COALESCE(SUM(-m.qty) FILTER
            (WHERE m.movement_type IN ('pick','pick_reversal')),0)<>0
        )
      )
  );
$$;


--
-- Name: fn_wms_order_ready_for_packing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_order_ready_for_packing(p_order_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH target_order AS (
    SELECT o.id, o.work_order_id
    FROM public.or_orders o
    WHERE o.id = p_order_id
  ), active_items AS (
    SELECT
      o.id AS order_id,
      o.work_order_id,
      COALESCE(oi.quantity, 1)::NUMERIC AS expected_qty,
      UPPER(BTRIM(COALESCE(p.product_code::TEXT, ''))) AS product_code_key,
      public.fn_wms_item_fulfillment_mode(p.id, p.product_category::TEXT) AS current_mode
    FROM target_order target
    JOIN public.or_orders o
      ON (target.work_order_id IS NOT NULL AND o.work_order_id = target.work_order_id)
      OR (target.work_order_id IS NULL AND o.id = target.id)
    JOIN public.or_order_items oi ON oi.order_id = o.id
    JOIN public.pr_products p ON p.id = oi.product_id
    WHERE o.status <> 'ยกเลิก'
      AND NOT COALESCE(oi.is_detail_row, FALSE)
      AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
  ), item_groups AS (
    SELECT
      item.work_order_id,
      item.product_code_key,
      SUM(item.expected_qty)::NUMERIC AS expected_qty,
      BOOL_OR(item.current_mode = 'warehouse_pick') AS current_picker_required
    FROM active_items item
    GROUP BY item.work_order_id, item.product_code_key
  ), wms_groups AS (
    SELECT
      w.work_order_id,
      UPPER(BTRIM(COALESCE(w.product_code, ''))) AS product_code_key,
      COALESCE(SUM(w.qty) FILTER (WHERE w.status <> 'cancelled'), 0)::NUMERIC AS active_qty,
      COALESCE(SUM(w.qty) FILTER (WHERE w.status = 'correct'), 0)::NUMERIC AS correct_qty
    FROM target_order target
    JOIN public.wms_orders w
      ON (target.work_order_id IS NOT NULL AND w.work_order_id = target.work_order_id)
      OR (target.work_order_id IS NULL AND w.source_order_id = target.id)
    GROUP BY w.work_order_id, UPPER(BTRIM(COALESCE(w.product_code, '')))
  ), group_readiness AS (
    SELECT
      item.work_order_id,
      item.product_code_key,
      CASE
        WHEN NOT item.current_picker_required THEN TRUE
        WHEN COALESCE(wms.active_qty, 0) > 0
          THEN COALESCE(wms.correct_qty, 0) >= item.expected_qty
        ELSE FALSE
      END AS ready
    FROM item_groups item
    LEFT JOIN wms_groups wms
      ON wms.work_order_id IS NOT DISTINCT FROM item.work_order_id
     AND wms.product_code_key = item.product_code_key
  )
  SELECT COALESCE(BOOL_AND(readiness.ready), TRUE)
  FROM active_items item
  JOIN group_readiness readiness
    ON readiness.work_order_id IS NOT DISTINCT FROM item.work_order_id
   AND readiness.product_code_key = item.product_code_key
  WHERE item.order_id = p_order_id;
$$;


--
-- Name: FUNCTION fn_wms_order_ready_for_packing(p_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_wms_order_ready_for_packing(p_order_id uuid) IS 'Packing readiness uses current non-picker configuration as an override, while retaining WMS quantity checks for products that currently require Picker.';


--
-- Name: fn_wms_try_auto_consume_non_pick(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_wms_try_auto_consume_non_pick(p_work_order_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_nm TEXT := BTRIM(COALESCE(p_work_order_name,''));
  v_work_order_id UUID;
  v_expected INT;
  v_linked INT;
BEGIN
  IF v_nm='' THEN RETURN; END IF;

  SELECT wo.id,COALESCE(wo.order_count,0) INTO v_work_order_id,v_expected
  FROM public.or_work_orders wo
  WHERE BTRIM(COALESCE(wo.work_order_name,''))=v_nm AND wo.status='กำลังผลิต'
  ORDER BY wo.created_at DESC,wo.id DESC LIMIT 1;
  IF COALESCE(v_expected,0)<=0 THEN RETURN; END IF;

  SELECT COUNT(*) INTO v_linked
  FROM public.or_orders o
  WHERE o.work_order_id=v_work_order_id;
  IF v_linked<v_expected THEN RETURN; END IF;

  INSERT INTO public.wms_orders(
    work_order_id,order_id,source_order_id,source_order_item_id,
    product_code,product_name,location,qty,unit_name,status,assigned_to,fulfillment_mode
  )
  SELECT o.work_order_id,v_nm,o.id,oi.id,
    COALESCE(NULLIF(BTRIM(p.product_code::TEXT),''),oi.product_name,'N/A'),
    oi.product_name,COALESCE(p.storage_location::TEXT,''),COALESCE(oi.quantity,1)::NUMERIC,
    COALESCE(NULLIF(BTRIM(p.unit_name::TEXT),''),'ชิ้น'),'pending',NULL,
    public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT)
  FROM public.or_orders o
  JOIN public.or_order_items oi ON oi.order_id=o.id
  JOIN public.pr_products p ON p.id=oi.product_id
  WHERE o.work_order_id=v_work_order_id
    AND NOT COALESCE(oi.is_detail_row,false)
    AND public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT)<>'warehouse_pick'
    AND NOT EXISTS (
      SELECT 1 FROM public.wms_orders w
      WHERE w.source_order_item_id=oi.id AND w.status<>'cancelled'
    );

  UPDATE public.wms_orders
  SET status='correct',end_time=COALESCE(end_time,NOW())
  WHERE work_order_id=v_work_order_id
    AND fulfillment_mode IN ('system_complete','sub_warehouse_skip')
    AND status='pending';
END;
$$;


--
-- Name: FUNCTION fn_wms_try_auto_consume_non_pick(p_work_order_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_wms_try_auto_consume_non_pick(p_work_order_name text) IS 'ใบกำลังผลิต, ยังไม่มี WMS, ไม่มีหมวดหยิบ — สร้าง system_complete แล้ว correct ให้ trigger ตัดสต๊อก';


--
-- Name: fn_work_order_wms_fully_returned_or_cleared(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_work_order_wms_fully_returned_or_cleared(p_work_order_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name TEXT;
BEGIN
  IF p_work_order_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT trim(both FROM coalesce(work_order_name, '')) INTO v_name
  FROM or_work_orders
  WHERE id = p_work_order_id;

  IF v_name = '' THEN
    RETURN false;
  END IF;

  RETURN NOT EXISTS (
    SELECT 1
    FROM wms_orders w
    WHERE (
      w.work_order_id = p_work_order_id
      OR (
        w.work_order_id IS NULL
        AND trim(both FROM coalesce(w.order_id, '')) = v_name
      )
    )
    AND w.status NOT IN ('returned', 'cancelled')
  );
END;
$$;


--
-- Name: FUNCTION fn_work_order_wms_fully_returned_or_cleared(p_work_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_work_order_wms_fully_returned_or_cleared(p_work_order_id uuid) IS 'true เมื่อไม่มีแถว wms_orders ที่ status ไม่ใช่ returned/cancelled - ใช้ตัดสิน reuse เลข R';


--
-- Name: get_announcement_ack_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_announcement_ack_status(p_announcement_id uuid) RETURNS TABLE(employee_id uuid, employee_name text, department_name text, position_name text, acknowledged boolean, acknowledged_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT hr_can_manage_announcements() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูสถานะการรับทราบ';
  END IF;

  RETURN QUERY
  SELECT
    e.id,
    (trim(concat_ws(' ', e.first_name, e.last_name))
      || CASE WHEN coalesce(e.nickname, '') <> '' THEN ' (' || e.nickname || ')' ELSE '' END)::TEXT,
    d.name::TEXT,
    p.name::TEXT,
    (r.id IS NOT NULL),
    r.acknowledged_at
  FROM hr_announcements a
  JOIN hr_employees e ON e.employment_status IN ('active','probation')
    AND (
      a.target_all_departments
      OR EXISTS (
        SELECT 1 FROM hr_announcement_departments ad
        WHERE ad.announcement_id = a.id AND ad.department_id = e.department_id
      )
    )
  LEFT JOIN hr_departments d ON d.id = e.department_id
  LEFT JOIN hr_positions p ON p.id = e.position_id
  LEFT JOIN hr_announcement_reads r ON r.announcement_id = a.id AND r.employee_id = e.id
  WHERE a.id = p_announcement_id
  ORDER BY (r.id IS NOT NULL), e.first_name;
END;
$$;


--
-- Name: get_announcement_ack_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_announcement_ack_summary() RETURNS TABLE(announcement_id uuid, target_count integer, acked_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    a.id,
    count(e.id)::INT,
    count(r.id)::INT
  FROM hr_announcements a
  LEFT JOIN hr_employees e
    ON e.employment_status IN ('active','probation')
   AND (
     a.target_all_departments
     OR EXISTS (
       SELECT 1 FROM hr_announcement_departments ad
       WHERE ad.announcement_id = a.id AND ad.department_id = e.department_id
     )
   )
  LEFT JOIN hr_announcement_reads r
    ON r.announcement_id = a.id AND r.employee_id = e.id
  WHERE hr_can_manage_announcements()
  GROUP BY a.id;
$$;


--
-- Name: get_announcement_attention_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_announcement_attention_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN NOT hr_can_manage_announcements() THEN 0 ELSE (
    SELECT count(*)::INT
    FROM hr_announcements a
    WHERE a.status = 'pending'
       OR (
         a.status = 'published'
         AND EXISTS (
           SELECT 1 FROM hr_employees e
           WHERE e.employment_status IN ('active','probation')
             AND (
               a.target_all_departments
               OR EXISTS (
                 SELECT 1 FROM hr_announcement_departments ad
                 WHERE ad.announcement_id = a.id AND ad.department_id = e.department_id
               )
             )
             AND NOT EXISTS (
               SELECT 1 FROM hr_announcement_reads r
               WHERE r.announcement_id = a.id AND r.employee_id = e.id
             )
         )
       )
  ) END;
$$;


--
-- Name: get_career_path(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_career_path(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'career', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'track_id', t.id,
        'track_name', t.name,
        'description', t.description,
        'current_level_id', ec.current_level_id,
        'current_salary', ec.current_salary,
        'effective_date', ec.effective_date,
        'levels', (
          SELECT jsonb_agg(jsonb_build_object(
            'id', cl.id,
            'level_order', cl.level_order,
            'title', cl.title,
            'salary_min', cl.salary_min,
            'salary_max', cl.salary_max,
            'salary_step', cl.salary_step,
            'requirements', cl.requirements
          ) ORDER BY cl.level_order)
          FROM hr_career_levels cl WHERE cl.track_id = t.id
        )
      ))
      FROM hr_employee_career ec
      JOIN hr_career_tracks t ON t.id = ec.track_id
      WHERE ec.employee_id = p_employee_id
    ), '[]'::jsonb),
    'history', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'from_title', fl.title,
        'to_title', tl.title,
        'from_salary', ch.from_salary,
        'to_salary', ch.to_salary,
        'effective_date', ch.effective_date,
        'reason', ch.reason
      ) ORDER BY ch.effective_date DESC)
      FROM hr_career_history ch
      LEFT JOIN hr_career_levels fl ON fl.id = ch.from_level_id
      JOIN hr_career_levels tl ON tl.id = ch.to_level_id
      WHERE ch.employee_id = p_employee_id
    ), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_distinct_product_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_distinct_product_categories() RETURNS TABLE(product_category text)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT DISTINCT p.product_category
  FROM pr_products p
  WHERE p.is_active = true
    AND p.product_category IS NOT NULL
    AND p.product_category <> ''
  ORDER BY p.product_category;
$$;


--
-- Name: get_employee_leave_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_leave_summary(p_employee_id uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'balances', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'leave_type_id', t.id,
        'leave_type_name', t.name,
        'entitled_days', CASE WHEN o.id IS NOT NULL THEN o.opening_remaining_days ELSE COALESCE(t.max_days_per_year, 0) END,
        'used_days', COALESCE(u.used, 0),
        'carried_days', 0,
        'remaining', GREATEST(0, CASE WHEN o.id IS NOT NULL THEN o.opening_remaining_days ELSE COALESCE(t.max_days_per_year, 0) END - COALESCE(u.used, 0)),
        'opening_effective_date', o.effective_date
      ) ORDER BY t.name)
      FROM public.hr_leave_types t
      LEFT JOIN public.hr_employee_opening_leave_balances o
        ON o.leave_type_id = t.id AND o.employee_id = p_employee_id AND o.year = p_year
        AND o.effective_date <= CASE WHEN p_year=EXTRACT(YEAR FROM now() AT TIME ZONE 'Asia/Bangkok')::int THEN (now() AT TIME ZONE 'Asia/Bangkok')::date ELSE make_date(p_year,12,31) END
      LEFT JOIN LATERAL (
        SELECT SUM(r.total_days) AS used
        FROM public.hr_leave_requests r
        WHERE r.employee_id = p_employee_id
          AND r.leave_type_id = t.id
          AND r.status = 'approved'
          AND EXTRACT(YEAR FROM r.start_date) = p_year
          AND (o.id IS NULL OR r.start_date >= o.effective_date)
      ) u ON TRUE
    ), '[]'::jsonb),
    'recent_requests', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'leave_type_name', t.name, 'start_date', r.start_date,
        'end_date', r.end_date, 'total_days', r.total_days, 'leave_mode', r.leave_mode,
        'start_time', r.start_time, 'end_time', r.end_time, 'total_hours', r.total_hours,
        'status', r.status, 'reason', r.reason, 'medical_cert_url', r.medical_cert_url,
        'created_at', r.created_at
      ) ORDER BY r.created_at DESC)
      FROM public.hr_leave_requests r
      JOIN public.hr_leave_types t ON t.id = r.leave_type_id
      WHERE r.employee_id = p_employee_id AND EXTRACT(YEAR FROM r.start_date) = p_year
    ), '[]'::jsonb),
    'pending_count', (SELECT count(*) FROM public.hr_leave_requests WHERE employee_id = p_employee_id AND status = 'pending')
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_hr_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hr_dashboard(p_employee_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_employees', (SELECT count(*) FROM hr_employees WHERE employment_status IN ('active','probation')),
    'pending_leaves', (SELECT count(*) FROM hr_leave_requests WHERE status = 'pending'),
    'today_on_leave', (SELECT count(*) FROM hr_leave_requests WHERE status = 'approved' AND CURRENT_DATE BETWEEN start_date AND end_date),
    'upcoming_interviews', (SELECT count(*) FROM hr_interviews WHERE status = 'scheduled' AND interview_date > now()),
    'active_onboarding', (SELECT count(*) FROM hr_onboarding_plans WHERE status = 'in_progress'),
    'unread_notifications', CASE WHEN p_employee_id IS NOT NULL
      THEN (SELECT count(*) FROM hr_notifications WHERE employee_id = p_employee_id AND NOT is_read)
      ELSE 0 END
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_inactive_products(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inactive_products(p_days integer DEFAULT 30) RETURNS TABLE(id uuid, product_code text, product_name text, product_type text, product_category text, seller_name text, storage_location text, order_point text, rubber_code text, last_sold_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    p.product_code,
    p.product_name,
    p.product_type::TEXT,
    p.product_category,
    p.seller_name,
    p.storage_location,
    p.order_point,
    p.rubber_code,
    (
      SELECT MAX(o.created_at)
      FROM or_order_items oi
      JOIN or_orders o ON o.id = oi.order_id
      WHERE oi.product_id = p.id
    ) AS last_sold_at
  FROM pr_products p
  WHERE p.is_active = true
    AND NOT EXISTS (
      SELECT 1
      FROM or_order_items oi
      JOIN or_orders o ON o.id = oi.order_id
      WHERE oi.product_id = p.id
        AND o.created_at >= (NOW() - (p_days || ' days')::INTERVAL)
    )
  ORDER BY p.product_code;
END;
$$;


--
-- Name: get_issue_creator_profiles(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_issue_creator_profiles(p_user_ids uuid[]) RETURNS TABLE(id uuid, username text, role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT u.id, u.username::text, u.role::text
  FROM public.us_users u
  WHERE u.id = ANY(coalesce(p_user_ids, ARRAY[]::UUID[]))
    AND public.is_current_user_active()
    AND EXISTS (
      SELECT 1 FROM public.us_users viewer
      WHERE viewer.id = auth.uid()
        AND viewer.role IN (
          'superadmin', 'admin', 'sales-tr', 'sales-pump',
          'production', 'qc_staff', 'packing_staff'
        )
    );
$$;


--
-- Name: get_leave_calendar(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_leave_calendar(p_start date, p_end date) RETURNS TABLE(id uuid, employee_id uuid, employee_name text, position_name text, department_name text, start_date date, end_date date, leave_mode text, start_time time without time zone, end_time time without time zone, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT hr_can_view_leave_calendar() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูปฏิทินลา';
  END IF;

  RETURN QUERY
  SELECT
    r.id,
    r.employee_id,
    (trim(concat_ws(' ', e.first_name, e.last_name))
      || CASE WHEN coalesce(e.nickname, '') <> '' THEN ' (' || e.nickname || ')' ELSE '' END)::TEXT,
    p.name::TEXT,
    d.name::TEXT,
    r.start_date,
    r.end_date,
    r.leave_mode::TEXT,
    r.start_time,
    r.end_time,
    r.status::TEXT
  FROM hr_leave_requests r
  JOIN hr_employees e ON e.id = r.employee_id
  LEFT JOIN hr_positions p ON p.id = e.position_id
  LEFT JOIN hr_departments d ON d.id = e.department_id
  WHERE r.status IN ('approved','pending')
    AND r.start_date <= p_end
    AND r.end_date >= p_start
  ORDER BY r.start_date, e.first_name;
END;
$$;


--
-- Name: get_machinery_inspection_access_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_machinery_inspection_access_candidates() RETURNS TABLE(id uuid, username text, email text, role text, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    candidate.id,
    candidate.username,
    candidate.email,
    candidate.role,
    candidate.is_active
  FROM public.us_users AS candidate
  WHERE public.check_user_role(
      auth.uid(),
      ARRAY['superadmin', 'admin', 'technician']
    )
    AND candidate.role IN ('production', 'production_mb', 'manager', 'packing_staff')
    AND candidate.is_active = true
  ORDER BY candidate.username NULLS LAST, candidate.email NULLS LAST;
$$;


--
-- Name: get_machinery_purchase_products(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_machinery_purchase_products(p_include_disabled boolean DEFAULT false) RETURNS TABLE(product_id uuid, product_code text, product_name text, product_category text, unit_name text, storage_location text, on_hand numeric, enabled boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.product_code, p.product_name, p.product_category, p.unit_name,
         p.storage_location, COALESCE(b.on_hand, 0), COALESCE(mp.enabled, false)
  FROM pr_products p
  LEFT JOIN pr_machinery_purchase_products mp ON mp.product_id = p.id
  LEFT JOIN inv_stock_balances b ON b.product_id = p.id
  WHERE p.is_active = true
    AND (p_include_disabled OR COALESCE(mp.enabled, false))
  ORDER BY p.product_code;
$$;


--
-- Name: get_my_unread_announcement_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_unread_announcement_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::INT
  FROM hr_announcements a
  JOIN hr_employees e ON e.id = hr_my_employee_id()
  WHERE a.status = 'published'
    AND (
      a.target_all_departments
      OR EXISTS (
        SELECT 1 FROM hr_announcement_departments d
        WHERE d.announcement_id = a.id AND d.department_id = e.department_id
      )
    )
    AND NOT EXISTS (
      SELECT 1 FROM hr_announcement_reads r
      WHERE r.announcement_id = a.id AND r.employee_id = e.id
    );
$$;


--
-- Name: get_onboarding_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_onboarding_detail(p_plan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  result JSONB;
  v_plan RECORD;
BEGIN
  SELECT * INTO v_plan FROM hr_onboarding_plans WHERE id = p_plan_id;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;

  SELECT jsonb_build_object(
    'plan', row_to_json(v_plan)::jsonb,
    'employee', (SELECT row_to_json(e)::jsonb FROM hr_employees e WHERE e.id = v_plan.employee_id),
    'mentor', (SELECT row_to_json(e)::jsonb FROM hr_employees e WHERE e.id = v_plan.mentor_id),
    'supervisor', (SELECT row_to_json(e)::jsonb FROM hr_employees e WHERE e.id = v_plan.supervisor_id),
    'manager', (SELECT row_to_json(e)::jsonb FROM hr_employees e WHERE e.id = v_plan.manager_id),
    'template', (SELECT row_to_json(t)::jsonb FROM hr_onboarding_templates t WHERE t.id = v_plan.template_id),
    'progress', COALESCE((
      SELECT jsonb_agg(row_to_json(p)::jsonb ORDER BY p.phase_index, p.task_index)
      FROM hr_onboarding_progress p WHERE p.plan_id = p_plan_id
    ), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_orders_sidebar_actionable_count(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orders_sidebar_actionable_count(p_username text DEFAULT ''::text, p_role text DEFAULT ''::text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::BIGINT
  FROM public.or_orders o
  WHERE
    (
      (
        o.status = 'รอลงข้อมูล'
        -- บิลเคลมสถานะรอลงข้อมูลจัดการในแท็บบิลเคลม ไม่ใช่คิวรอลงข้อมูลปกติ
        AND o.claim_type IS NULL
      )
      OR o.status = 'ลงข้อมูลผิด'
      OR (
        o.status = ANY(ARRAY['ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ']::TEXT[])
        -- รายการที่ผู้ใช้เก็บเข้าประวัติแล้วจะไม่อยู่ในแท็บตรวจสอบไม่ผ่านอีกต่อไป
        AND o.failed_queue_archived_at IS NULL
      )
      OR
      (
        o.claim_shipping_confirmed_at IS NULL
        AND o.status IS DISTINCT FROM 'ยกเลิก'
        -- ใช้ความสัมพันธ์กับคำขอเคลมเป็นแหล่งจริง ไม่ใช้เพียงเลขบิลขึ้นต้น REQ
        AND EXISTS (
          SELECT 1
          FROM public.or_claim_requests cr
          WHERE cr.created_claim_order_id = o.id
            AND cr.status = 'approved'
        )
      )
    )
    AND
    (
      (p_role = 'sales-pump' AND p_username <> '' AND o.admin_user = p_username)
      OR
      (
        p_role = 'sales-tr'
        AND o.admin_user IN (
          SELECT DISTINCT TRIM(u.username)
          FROM public.us_users u
          WHERE u.role = 'sales-tr'
            AND u.username IS NOT NULL
            AND TRIM(u.username) <> ''
          UNION
          SELECT DISTINCT TRIM(u.email)
          FROM public.us_users u
          WHERE u.role = 'sales-tr'
            AND u.email IS NOT NULL
            AND TRIM(u.email) <> ''
        )
      )
      OR p_role NOT IN ('sales-pump', 'sales-tr')
      OR p_role IS NULL
    );
$$;


--
-- Name: get_purchase_badge_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_purchase_badge_counts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_pr_pending INT;
  v_pr_approved_no_po INT;
  v_po_waiting_gr INT;
BEGIN
  -- PR pending count
  SELECT COUNT(*) INTO v_pr_pending
  FROM inv_pr WHERE status = 'pending';

  -- Approved PRs that don't have a PO yet
  SELECT COUNT(*) INTO v_pr_approved_no_po
  FROM inv_pr pr
  WHERE pr.status = 'approved'
    AND NOT EXISTS (SELECT 1 FROM inv_po po WHERE po.pr_id = pr.id);

  -- POs waiting for GR (ordered or partial)
  SELECT COUNT(*) INTO v_po_waiting_gr
  FROM inv_po WHERE status IN ('ordered', 'partial');

  RETURN jsonb_build_object(
    'pr_pending', v_pr_pending,
    'pr_approved_no_po', v_pr_approved_no_po,
    'po_waiting_gr', v_po_waiting_gr
  );
END;
$$;


--
-- Name: get_sidebar_counts(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sidebar_counts(p_username text DEFAULT ''::text, p_role text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_orders_pending bigint;
  v_orders_req_claim_shipping bigint;
  v_admin_qc bigint;
  v_qc_reject bigint;
  v_packing bigint;
  v_warehouse bigint;
  v_refund_pending bigint;
  v_tax_pending bigint;
  v_cash_pending bigint;
  v_manual_slip_pending bigint;
  v_amendment_pending bigint;
  v_claim_pending bigint;
  v_excluded text[] := ARRAY['รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน'];
  v_is_sales_pump_owner boolean;
  v_is_sales_tr_team boolean;
  v_sales_from date;
  v_sales_days numeric;
BEGIN
  v_is_sales_pump_owner := (p_role = 'sales-pump' AND p_username <> '');
  v_is_sales_tr_team := (p_role = 'sales-tr');

  -- Warehouse.tsx default: salesFromDate = today - 14 days
  v_sales_from := (CURRENT_DATE - 14);
  v_sales_days := GREATEST((CURRENT_DATE - v_sales_from), 1);

  -- orders: ไม่รวมบิลเคลม (claim_type IS NOT NULL) ที่ยังอยู่สถานะ 'รอลงข้อมูล'
  IF v_is_sales_pump_owner THEN
    SELECT count(*) INTO v_orders_pending
    FROM or_orders
    WHERE status = ANY(v_excluded)
      AND (claim_type IS NULL OR status <> 'รอลงข้อมูล')
      AND admin_user = p_username;
  ELSIF v_is_sales_tr_team THEN
    SELECT count(*) INTO v_orders_pending
    FROM or_orders
    WHERE status = ANY(v_excluded)
      AND (claim_type IS NULL OR status <> 'รอลงข้อมูล')
      AND admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      );
  ELSE
    SELECT count(*) INTO v_orders_pending
    FROM or_orders
    WHERE status = ANY(v_excluded)
      AND (claim_type IS NULL OR status <> 'รอลงข้อมูล');
  END IF;

  IF v_is_sales_pump_owner THEN
    SELECT count(*) INTO v_orders_req_claim_shipping
    FROM or_orders o
    WHERE o.bill_no LIKE 'REQ%'
      AND o.claim_shipping_confirmed_at IS NULL
      AND o.status IS DISTINCT FROM 'ยกเลิก'
      AND o.admin_user = p_username;
  ELSIF v_is_sales_tr_team THEN
    SELECT count(*) INTO v_orders_req_claim_shipping
    FROM or_orders o
    WHERE o.bill_no LIKE 'REQ%'
      AND o.claim_shipping_confirmed_at IS NULL
      AND o.status IS DISTINCT FROM 'ยกเลิก'
      AND o.admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      );
  ELSE
    SELECT count(*) INTO v_orders_req_claim_shipping
    FROM or_orders o
    WHERE o.bill_no LIKE 'REQ%'
      AND o.claim_shipping_confirmed_at IS NULL
      AND o.status IS DISTINCT FROM 'ยกเลิก';
  END IF;

  IF v_is_sales_pump_owner THEN
    SELECT count(*) INTO v_admin_qc
    FROM or_orders
    WHERE status = 'รอตรวจคำสั่งซื้อ'
      AND channel_code IS DISTINCT FROM 'PUMP'
      AND admin_user = p_username;
  ELSIF v_is_sales_tr_team THEN
    SELECT count(*) INTO v_admin_qc
    FROM or_orders
    WHERE status = 'รอตรวจคำสั่งซื้อ'
      AND channel_code IS DISTINCT FROM 'PUMP'
      AND admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      );
  ELSIF p_role IN ('superadmin', 'admin') THEN
    SELECT count(*) INTO v_admin_qc
    FROM or_orders
    WHERE status = 'รอตรวจคำสั่งซื้อ'
      AND channel_code IS DISTINCT FROM 'PUMP';
  ELSE
    SELECT count(*) INTO v_admin_qc
    FROM or_orders
    WHERE status = 'รอตรวจคำสั่งซื้อ'
      AND channel_code IS DISTINCT FROM 'PUMP'
      AND channel_code IS DISTINCT FROM 'OFFICE';
  END IF;

  SELECT count(*) INTO v_qc_reject
  FROM qc_records r
  WHERE r.is_rejected = true
    AND (
      NOT EXISTS (
        SELECT 1 FROM or_order_items oi WHERE oi.item_uid = r.item_uid
      )
      OR EXISTS (
        SELECT 1
        FROM or_order_items oi
        INNER JOIN or_orders o ON o.id = oi.order_id
        WHERE oi.item_uid = r.item_uid
          AND o.status IS DISTINCT FROM 'ยกเลิก'
      )
    );

  SELECT count(*) INTO v_packing
  FROM or_work_orders WHERE status = 'กำลังผลิต';

  WITH pending_po AS (
    SELECT
      poi.product_id,
      SUM(
        GREATEST(
          COALESCE(poi.qty, 0)
          - COALESCE(poi.qty_received_total, 0)
          - COALESCE(poi.resolution_qty, 0),
          0
        )
      )::numeric AS pending_qty
    FROM inv_po_items poi
    JOIN inv_po po ON po.id = poi.po_id
    WHERE po.status IN ('ordered', 'partial')
    GROUP BY poi.product_id
  ),
  sales AS (
    SELECT
      oi.product_id,
      SUM(oi.quantity)::numeric AS total_sold
    FROM or_order_items oi
    JOIN or_orders o ON o.id = oi.order_id
    WHERE o.entry_date >= v_sales_from
      AND o.status IS DISTINCT FROM 'ยกเลิก'
      AND oi.product_id IS NOT NULL
    GROUP BY oi.product_id
  )
  SELECT count(*) INTO v_warehouse
  FROM pr_products p
  LEFT JOIN inv_stock_balances b ON b.product_id = p.id
  LEFT JOIN pending_po pp ON pp.product_id = p.id
  LEFT JOIN sales s ON s.product_id = p.id
  WHERE p.is_active = true
    AND COALESCE(p.is_hold, false) = false
    AND p.order_point IS NOT NULL
    AND NULLIF(TRIM(REPLACE(p.order_point::text, ',', '')), '') IS NOT NULL
    AND NULLIF(TRIM(REPLACE(p.order_point::text, ',', '')), '')::numeric > 0
    AND (
      (COALESCE(b.on_hand, 0)::numeric + COALESCE(pp.pending_qty, 0)) < NULLIF(TRIM(REPLACE(p.order_point::text, ',', '')), '')::numeric
      OR
      (
        p.order_point_days IS NOT NULL
        AND COALESCE(p.order_point_days, 0)::numeric > 0
        AND COALESCE(s.total_sold, 0) > 0
        AND (
          ROUND(
            COALESCE(b.on_hand, 0)::numeric
            /
            NULLIF((COALESCE(s.total_sold, 0) / v_sales_days), 0)
          )
        ) < COALESCE(p.order_point_days, 0)::numeric
      )
    );

  IF v_is_sales_pump_owner THEN
    SELECT count(*) INTO v_refund_pending
    FROM ac_refunds r
    JOIN or_orders o ON o.id = r.order_id
    WHERE r.status = 'pending'
      AND r.reason LIKE '%โอนเกิน%'
      AND o.status IS DISTINCT FROM 'ยกเลิก'
      AND o.admin_user = p_username;
  ELSIF v_is_sales_tr_team THEN
    SELECT count(*) INTO v_refund_pending
    FROM ac_refunds r
    JOIN or_orders o ON o.id = r.order_id
    WHERE r.status = 'pending'
      AND r.reason LIKE '%โอนเกิน%'
      AND o.status IS DISTINCT FROM 'ยกเลิก'
      AND o.admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      );
  ELSE
    SELECT count(*) INTO v_refund_pending
    FROM ac_refunds r
    JOIN or_orders o ON o.id = r.order_id
    WHERE r.status = 'pending'
      AND r.reason LIKE '%โอนเกิน%'
      AND o.status IS DISTINCT FROM 'ยกเลิก';
  END IF;

  IF v_is_sales_pump_owner THEN
    SELECT count(*) INTO v_tax_pending
    FROM or_orders
    WHERE billing_details @> '{"request_tax_invoice": true}'::jsonb
      AND NOT COALESCE(billing_details @> '{"account_confirmed_tax": true}'::jsonb, false)
      AND status != ALL(v_excluded)
      AND admin_user = p_username;
  ELSIF v_is_sales_tr_team THEN
    SELECT count(*) INTO v_tax_pending
    FROM or_orders
    WHERE billing_details @> '{"request_tax_invoice": true}'::jsonb
      AND NOT COALESCE(billing_details @> '{"account_confirmed_tax": true}'::jsonb, false)
      AND status != ALL(v_excluded)
      AND admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      );
  ELSE
    SELECT count(*) INTO v_tax_pending
    FROM or_orders
    WHERE billing_details @> '{"request_tax_invoice": true}'::jsonb
      AND NOT COALESCE(billing_details @> '{"account_confirmed_tax": true}'::jsonb, false)
      AND status != ALL(v_excluded);
  END IF;

  IF v_is_sales_pump_owner THEN
    SELECT count(*) INTO v_cash_pending
    FROM or_orders
    WHERE billing_details @> '{"request_cash_bill": true}'::jsonb
      AND NOT COALESCE(billing_details @> '{"account_confirmed_cash": true}'::jsonb, false)
      AND status != ALL(v_excluded)
      AND admin_user = p_username;
  ELSIF v_is_sales_tr_team THEN
    SELECT count(*) INTO v_cash_pending
    FROM or_orders
    WHERE billing_details @> '{"request_cash_bill": true}'::jsonb
      AND NOT COALESCE(billing_details @> '{"account_confirmed_cash": true}'::jsonb, false)
      AND status != ALL(v_excluded)
      AND admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      );
  ELSE
    SELECT count(*) INTO v_cash_pending
    FROM or_orders
    WHERE billing_details @> '{"request_cash_bill": true}'::jsonb
      AND NOT COALESCE(billing_details @> '{"account_confirmed_cash": true}'::jsonb, false)
      AND status != ALL(v_excluded);
  END IF;

  SELECT count(DISTINCT m.order_id) INTO v_manual_slip_pending
  FROM ac_manual_slip_checks m
  WHERE m.status = 'pending';

  SELECT count(*) INTO v_amendment_pending
  FROM or_order_amendments a
  WHERE a.status = 'pending';

  SELECT count(*) INTO v_claim_pending
  FROM or_claim_requests c
  WHERE c.status = 'pending';

  RETURN jsonb_build_object(
    'orders', v_orders_pending,
    'orders_req_claim_shipping', v_orders_req_claim_shipping,
    'admin_qc', v_admin_qc,
    'qc_reject', v_qc_reject,
    'packing', v_packing,
    'warehouse', v_warehouse,
    'refund_pending', v_refund_pending,
    'tax_pending', v_tax_pending,
    'cash_pending', v_cash_pending,
    'manual_slip_pending', v_manual_slip_pending,
    'amendment_pending', v_amendment_pending,
    'claim_pending', v_claim_pending
  );
END;
$$;


--
-- Name: get_unread_chat_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_chat_count(p_user_id uuid) RETURNS TABLE(order_chat_unread bigint, issue_chat_unread bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role       TEXT;
  v_username   TEXT;
  v_is_admin   BOOLEAN;
  v_is_owner   BOOLEAN;
  v_is_production BOOLEAN;
  v_order_unread BIGINT := 0;
  v_issue_unread BIGINT := 0;
BEGIN
  SELECT role, username INTO v_role, v_username
  FROM us_users WHERE id = p_user_id;

  v_is_admin := v_role IN ('superadmin', 'admin');
  v_is_owner := v_role IN ('admin-tr', 'order_staff');
  v_is_production := v_role IN ('admin_qc', 'production_staff', 'picker', 'auditor');

  -- ═══ Order Chat Unread ═══
  IF v_is_admin THEN
    SELECT count(*) INTO v_order_unread
    FROM or_order_chat_logs m
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE m.is_hidden = false
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz);

  ELSIF v_is_owner THEN
    SELECT count(*) INTO v_order_unread
    FROM or_order_chat_logs m
    JOIN or_orders o ON o.id = m.order_id
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE m.is_hidden = false
      AND o.admin_user = v_username
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz);

  ELSIF v_is_production THEN
    SELECT count(*) INTO v_order_unread
    FROM or_order_chat_logs m
    JOIN or_orders o ON o.id = m.order_id
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE m.is_hidden = false
      AND o.admin_user = v_username
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz);
  END IF;

  -- ═══ Issue Chat Unread ═══
  IF v_is_admin THEN
    SELECT count(*) INTO v_issue_unread
    FROM or_issue_messages m
    LEFT JOIN or_issue_reads r ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz);

  ELSIF v_is_owner THEN
    SELECT count(*) INTO v_issue_unread
    FROM or_issue_messages m
    JOIN or_issues i ON i.id = m.issue_id
    JOIN or_orders o ON o.id = i.order_id
    LEFT JOIN or_issue_reads r ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND o.admin_user = v_username
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz);

  ELSIF v_is_production THEN
    SELECT count(*) INTO v_issue_unread
    FROM or_issue_messages m
    JOIN or_issues i ON i.id = m.issue_id
    LEFT JOIN or_orders o ON o.id = i.order_id
    LEFT JOIN or_issue_reads r ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND (i.created_by = p_user_id OR o.admin_user = v_username)
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz);
  END IF;

  RETURN QUERY SELECT v_order_unread, v_issue_unread;
END;
$$;


--
-- Name: get_unread_chat_count(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_chat_count(p_user_id uuid, p_role text, p_username text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_issue_on_count bigint := 0;
  v_issue_unread bigint := 0;
  v_order_unread bigint := 0;
  v_is_admin boolean;
  v_is_sales_tr boolean;
  v_is_sales_pump boolean;
  v_is_production boolean;
  v_is_operational_issue boolean;
  v_role text := lower(btrim(coalesce(p_role, '')));
  v_confirm_statuses text[] := ARRAY[
    'ตรวจสอบแล้ว',
    'ไม่ต้องออกแบบ',
    'รอออกแบบ',
    'ออกแบบแล้ว',
    'รอคอนเฟิร์ม',
    'คอนเฟิร์มแล้ว'
  ]::text[];
BEGIN
  v_is_admin := v_role IN ('superadmin', 'admin');
  v_is_sales_tr := v_role = 'sales-tr';
  v_is_sales_pump := v_role = 'sales-pump';
  v_is_production := v_role = 'production';
  v_is_operational_issue := v_role IN ('production', 'qc_staff', 'packing_staff');

  IF v_is_admin THEN
    SELECT count(*) INTO v_issue_on_count
    FROM public.or_issues
    WHERE status = 'On';
  ELSIF v_is_sales_tr THEN
    SELECT count(*) INTO v_issue_on_count
    FROM public.or_issues i
    JOIN public.or_orders o ON o.id = i.order_id
    WHERE i.status = 'On'
      AND o.admin_user IN (
        SELECT DISTINCT trim(u.username) FROM public.us_users u
        WHERE u.role = 'sales-tr' AND nullif(trim(u.username), '') IS NOT NULL
        UNION
        SELECT DISTINCT trim(u.email) FROM public.us_users u
        WHERE u.role = 'sales-tr' AND nullif(trim(u.email), '') IS NOT NULL
      );
  ELSIF v_is_sales_pump THEN
    SELECT count(*) INTO v_issue_on_count
    FROM public.or_issues i
    JOIN public.or_orders o ON o.id = i.order_id
    WHERE i.status = 'On'
      AND public._sales_pump_order_owned_by_session(o.admin_user, p_user_id);
  ELSIF v_is_operational_issue THEN
    SELECT count(*) INTO v_issue_on_count
    FROM public.or_issues i
    WHERE i.status = 'On'
      AND (
        i.created_by = p_user_id
        OR EXISTS (
          SELECT 1 FROM public.us_users creator
          WHERE creator.id = i.created_by
            AND creator.role IN ('sales-tr', 'sales-pump')
        )
      );
  END IF;

  IF v_is_admin THEN
    SELECT count(*) INTO v_issue_unread
    FROM public.or_issue_messages m
    LEFT JOIN public.or_issue_reads r
      ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz);
  ELSIF v_is_sales_tr THEN
    SELECT count(*) INTO v_issue_unread
    FROM public.or_issue_messages m
    JOIN public.or_issues i ON i.id = m.issue_id
    JOIN public.or_orders o ON o.id = i.order_id
    LEFT JOIN public.or_issue_reads r
      ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND o.admin_user IN (
        SELECT DISTINCT trim(u.username) FROM public.us_users u
        WHERE u.role = 'sales-tr' AND nullif(trim(u.username), '') IS NOT NULL
        UNION
        SELECT DISTINCT trim(u.email) FROM public.us_users u
        WHERE u.role = 'sales-tr' AND nullif(trim(u.email), '') IS NOT NULL
      )
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz);
  ELSIF v_is_sales_pump THEN
    SELECT count(*) INTO v_issue_unread
    FROM public.or_issue_messages m
    JOIN public.or_issues i ON i.id = m.issue_id
    JOIN public.or_orders o ON o.id = i.order_id
    LEFT JOIN public.or_issue_reads r
      ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND public._sales_pump_order_owned_by_session(o.admin_user, p_user_id)
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz);
  ELSIF v_is_operational_issue THEN
    SELECT count(*) INTO v_issue_unread
    FROM public.or_issue_messages m
    JOIN public.or_issues i ON i.id = m.issue_id
    LEFT JOIN public.or_issue_reads r
      ON r.issue_id = m.issue_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND (
        i.created_by = p_user_id
        OR EXISTS (
          SELECT 1 FROM public.us_users creator
          WHERE creator.id = i.created_by
            AND creator.role IN ('sales-tr', 'sales-pump')
        )
      )
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz);
  END IF;

  -- Keep the existing Confirm/order-chat visibility for production. The two
  -- additional operational roles receive Issue chat only.
  IF v_is_admin THEN
    SELECT count(*) INTO v_order_unread
    FROM public.or_order_chat_logs m
    LEFT JOIN public.or_order_chat_reads r
      ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz);
  ELSIF v_is_sales_tr THEN
    SELECT count(*) INTO v_order_unread
    FROM public.or_order_chat_logs m
    JOIN public.or_orders o ON o.id = m.order_id
    LEFT JOIN public.or_order_chat_reads r
      ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND o.status IS NOT NULL
      AND o.status = ANY(v_confirm_statuses)
      AND (
        o.channel_code = 'PUMP'
        OR (coalesce(o.requires_confirm_design, false) = true AND o.channel_code IS DISTINCT FROM 'PUMP')
      )
      AND o.admin_user IN (
        SELECT DISTINCT trim(u.username) FROM public.us_users u
        WHERE u.role = 'sales-tr' AND nullif(trim(u.username), '') IS NOT NULL
        UNION
        SELECT DISTINCT trim(u.email) FROM public.us_users u
        WHERE u.role = 'sales-tr' AND nullif(trim(u.email), '') IS NOT NULL
      )
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz);
  ELSIF v_is_sales_pump THEN
    SELECT count(*) INTO v_order_unread
    FROM public.or_order_chat_logs m
    JOIN public.or_orders o ON o.id = m.order_id
    LEFT JOIN public.or_order_chat_reads r
      ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz)
      AND (
        public._sales_pump_order_owned_by_session(o.admin_user, p_user_id)
        OR EXISTS (
          SELECT 1 FROM public.or_order_chat_logs mp
          WHERE mp.order_id = o.id
            AND mp.sender_id = p_user_id
            AND coalesce(mp.is_hidden, false) = false
        )
      );
  ELSIF v_is_production THEN
    SELECT count(*) INTO v_order_unread
    FROM public.or_order_chat_logs m
    JOIN public.or_orders o ON o.id = m.order_id
    LEFT JOIN public.or_order_chat_reads r
      ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE coalesce(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > coalesce(r.last_read_at, '1970-01-01'::timestamptz)
      AND o.status IS NOT NULL
      AND o.status = ANY(v_confirm_statuses)
      AND (
        o.channel_code = 'PUMP'
        OR (coalesce(o.requires_confirm_design, false) = true AND o.channel_code IS DISTINCT FROM 'PUMP')
      );
  END IF;

  RETURN jsonb_build_object(
    'issue_on_count', v_issue_on_count,
    'issue_unread', v_issue_unread,
    'order_unread', v_order_unread
  );
END;
$$;


--
-- Name: guard_audit_review_completeness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_audit_review_completeness() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  scope_count integer;
  counted_count integer;
BEGIN
  -- Decide at creation; a caller cannot disable the rule while submitting.
  IF NEW.require_full_count IS DISTINCT FROM OLD.require_full_count THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนเงื่อนไขนับครบหลังสร้างใบ Audit';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('review','completed','closed') THEN
    IF OLD.status = 'in_progress' AND NEW.status <> 'review' THEN
      RAISE EXCEPTION 'กรุณาส่งรีวิวก่อนปิดการตรวจนับ';
    END IF;
    IF NEW.status = 'review' THEN
      IF OLD.status <> 'in_progress' THEN
        RAISE EXCEPTION 'ใบ Audit ไม่อยู่ในสถานะกำลังนับ';
      END IF;
      SELECT count(*)::integer, count(*) FILTER (WHERE is_counted)::integer
      INTO scope_count, counted_count FROM public.inv_audit_items WHERE audit_id = NEW.id;
      IF counted_count = 0 THEN RAISE EXCEPTION 'ยังไม่มีรายการที่ถูกนับ'; END IF;
      IF NEW.require_full_count AND counted_count < scope_count THEN
        RAISE EXCEPTION 'ต้องตรวจนับครบ 100%% ก่อนส่งรีวิว (เหลือ % รายการ)', scope_count - counted_count;
      END IF;
      IF counted_count < scope_count AND NULLIF(btrim(NEW.partial_count_reason), '') IS NULL THEN
        RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ส่งรีวิวทั้งที่ยังนับไม่ครบ';
      END IF;
      NEW.total_items := scope_count;
      NEW.counted_items := counted_count;
      NEW.partial_count_reason := CASE WHEN counted_count < scope_count THEN btrim(NEW.partial_count_reason) ELSE NULL END;
    END IF;
  END IF;
  IF OLD.status IN ('review','completed','closed') AND (
    NEW.partial_count_reason IS DISTINCT FROM OLD.partial_count_reason
    OR NEW.total_items IS DISTINCT FROM OLD.total_items
    OR NEW.counted_items IS DISTINCT FROM OLD.counted_items
  ) THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนขอบเขตหรือเหตุผลหลังส่งรีวิว';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_audit_sub_warehouse_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_audit_sub_warehouse_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_at timestamptz;
BEGIN
  IF TG_OP='INSERT' THEN
    SELECT COALESCE(frozen_at,created_at) INTO v_at FROM inv_audits WHERE id=NEW.audit_id;
    NEW.sub_warehouse_snapshot:=fn_audit_sub_warehouse_snapshot(NEW.product_id,v_at);
  ELSIF NEW.sub_warehouse_snapshot IS DISTINCT FROM OLD.sub_warehouse_snapshot THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนยอดคลังย่อยตั้งต้นของใบ Audit';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_historical_po_unit_price(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_historical_po_unit_price() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF NEW.unit_price IS DISTINCT FROM OLD.unit_price THEN
    SELECT status INTO v_status FROM public.inv_po WHERE id = NEW.po_id;
    IF v_status <> 'open'
       AND COALESCE(current_setting('app.allow_historical_po_cost_correction', true), '') <> 'on' THEN
      RAISE EXCEPTION 'Historical PO unit prices must be corrected through the audited correction workflow';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_manual_payment_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_manual_payment_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_total numeric; v_duplicate uuid;
BEGIN
 SELECT receivable_amount INTO v_total FROM public.or_orders WHERE id=NEW.order_id FOR UPDATE;
 IF NEW.status IN ('pending','approved') THEN
  IF NEW.duplicate_of IS NOT NULL THEN RAISE EXCEPTION 'รายการซ้ำไม่สามารถนับยอดหรืออนุมัติได้'; END IF;
  SELECT id INTO v_duplicate FROM public.ac_manual_slip_checks
   WHERE order_id=NEW.order_id AND id<>NEW.id AND status IN ('pending','approved')
    AND duplicate_of IS NULL AND trim(transfer_date)=trim(NEW.transfer_date)
    AND trim(transfer_time)=trim(NEW.transfer_time) AND transfer_amount=NEW.transfer_amount
   LIMIT 1;
  IF FOUND THEN RAISE EXCEPTION 'บิลนี้มีรายการยอดและวันเวลาเดียวกันแล้ว (%) ห้ามส่งหรืออนุมัติซ้ำ',v_duplicate; END IF;
 END IF;
 IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
  NEW.approved_order_total:=v_total;
 ELSIF TG_OP='UPDATE' THEN
  IF NOT (OLD.approved_order_total IS NULL AND NEW.approved_order_total=v_total) THEN
   NEW.approved_order_total:=OLD.approved_order_total;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_manual_slip_approval_revocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_manual_slip_approval_revocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (OLD.status='approved' AND NEW.status IN ('rejected','pending'))
    OR NEW.approval_revoked_at IS DISTINCT FROM OLD.approval_revoked_at
    OR NEW.approval_revoked_by IS DISTINCT FROM OLD.approval_revoked_by
    OR NEW.approval_revoked_by_name IS DISTINCT FROM OLD.approval_revoked_by_name
    OR NEW.approval_revoked_reason IS DISTINCT FROM OLD.approval_revoked_reason THEN
    IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role='superadmin') THEN
      RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้นที่ยกเลิกการอนุมัติสลิปมือได้';
    END IF;
    IF OLD.approval_revoked_at IS NOT NULL THEN
      RAISE EXCEPTION 'ไม่สามารถแก้ไขประวัติการยกเลิกการอนุมัติเดิมได้';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_bill_product_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_bill_product_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_marketplace boolean; v_system_gift boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM public.or_orders
    WHERE id IN (OLD.order_id,NEW.order_id) AND source_marketplace_order_id IS NOT NULL)
    INTO v_marketplace;
  IF NOT v_marketplace THEN RETURN NEW; END IF;
  IF NEW.order_id IS DISTINCT FROM OLD.order_id OR
     NEW.source_mp_order_item_id IS DISTINCT FROM OLD.source_mp_order_item_id THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนต้นทางรายการสินค้า Marketplace ได้';
  END IF;
  IF NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.product_name IS DISTINCT FROM OLD.product_name THEN
    -- Automatic free ink gifts may change when ink changes. Imported free items remain locked.
    SELECT EXISTS(SELECT 1 FROM public.mp_order_items d
      WHERE d.id=OLD.source_mp_order_item_id AND d.raw_snapshot IS NULL AND d.is_free
        AND OLD.is_free AND NEW.is_free) INTO v_system_gift;
    IF NOT v_system_gift THEN
      RAISE EXCEPTION 'ไม่สามารถเปลี่ยนสินค้า Marketplace ได้ กรุณาแจ้งแก้ไข SKU ต้นทาง';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_draft_product_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_draft_product_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.raw_snapshot IS NOT NULL AND (
    NEW.product_id IS DISTINCT FROM OLD.product_id OR
    NEW.product_name_raw IS DISTINCT FROM OLD.product_name_raw OR
    NEW.sku_ref IS DISTINCT FROM OLD.sku_ref OR
    NEW.raw_snapshot IS DISTINCT FROM OLD.raw_snapshot OR
    NEW.mp_order_id IS DISTINCT FROM OLD.mp_order_id
  ) THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนสินค้า Marketplace ได้ กรุณาแจ้งแก้ไข SKU ต้นทาง';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_flagged_header(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_flagged_header() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_errors jsonb; v_key text;
BEGIN
  IF OLD.source_marketplace_order_id IS NULL OR OLD.status<>'ลงข้อมูลผิด' THEN RETURN NEW; END IF;
  v_errors:=public.marketplace_correction_errors(OLD.id);
  FOR v_key IN SELECT key FROM jsonb_each(to_jsonb(NEW)) LOOP
    IF v_key=ANY(ARRAY['status','updated_at','last_edited_by','entry_date','item_uid_sequence']) THEN CONTINUE; END IF;
    IF to_jsonb(NEW)->v_key IS NOT DISTINCT FROM to_jsonb(OLD)->v_key THEN CONTINUE; END IF;
    IF v_key=ANY(ARRAY['tracking_number','express_receipt_number']) AND v_errors->>v_key='true' THEN CONTINUE; END IF;
    RAISE EXCEPTION 'แก้ไขได้เฉพาะฟิลด์ที่ผู้ตรวจระบุผิด: %',v_key;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_flagged_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_flagged_items() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_order public.or_orders; v_errors jsonb; v_key text; v_rule text; v_order_id uuid;
BEGIN
  v_order_id:=CASE WHEN TG_OP='INSERT' THEN NEW.order_id ELSE OLD.order_id END;
  SELECT * INTO v_order FROM public.or_orders WHERE id=v_order_id FOR UPDATE;
  IF v_order.source_marketplace_order_id IS NULL OR v_order.status<>'ลงข้อมูลผิด' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'ไม่สามารถเพิ่มหรือลบรายการสินค้า Marketplace ที่ลงข้อมูลผิดได้'; END IF;
  v_errors:=public.marketplace_correction_errors(OLD.order_id,OLD.id);
  FOR v_key IN SELECT key FROM jsonb_each(to_jsonb(NEW)) LOOP
    IF v_key=ANY(ARRAY['updated_at','sort_order']) THEN CONTINUE; END IF;
    IF to_jsonb(NEW)->v_key IS NOT DISTINCT FROM to_jsonb(OLD)->v_key THEN CONTINUE; END IF;
    v_rule:=CASE v_key WHEN 'product_type' THEN 'layer' WHEN 'line_pattern' THEN 'line_art'
      WHEN 'file_attachment' THEN 'attachment' WHEN 'attachment_name' THEN 'attachment' ELSE v_key END;
    IF v_key=ANY(ARRAY['ink_color','product_type','cartoon_pattern','line_pattern','font',
      'line_1','line_2','line_3','notes','file_attachment','attachment_name']) AND v_errors->>v_rule='true' THEN CONTINUE; END IF;
    RAISE EXCEPTION 'แก้ไขได้เฉพาะฟิลด์รายการสินค้าที่ผู้ตรวจระบุผิด: %',v_key;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_order_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_order_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_order public.or_orders; v_id uuid;
BEGIN
  -- Check both parents when an item is moved, and serialize against review transitions.
  FOR v_id IN SELECT DISTINCT id FROM unnest(ARRAY[
    CASE WHEN TG_OP<>'INSERT' THEN OLD.order_id END,
    CASE WHEN TG_OP<>'DELETE' THEN NEW.order_id END]) AS parents(id)
    WHERE id IS NOT NULL ORDER BY id
  LOOP
    SELECT * INTO v_order FROM public.or_orders WHERE id=v_id FOR UPDATE;
    IF v_order.source_marketplace_order_id IS NOT NULL
       AND v_order.status='รอตรวจคำสั่งซื้อ'
       AND EXISTS(SELECT 1 FROM public.mp_orders WHERE id=v_order.source_marketplace_order_id AND billed_order_id=v_id) THEN
      RAISE EXCEPTION 'บิล Marketplace อยู่ระหว่างรอตรวจคำสั่งซื้อ กรุณาตีกลับก่อนแก้ไขรายการ';
    END IF;
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  SELECT * INTO v_order FROM public.or_orders WHERE id=NEW.order_id;
  IF v_order.source_marketplace_order_id IS NULL THEN RETURN NEW; END IF;
  IF NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'ink_color'),true) THEN NEW.ink_color:=NULL; END IF;
  IF NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'layer'),true) THEN NEW.product_type:=NULL; END IF;
  IF NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'cartoon_pattern'),true) THEN NEW.cartoon_pattern:=NULL; END IF;
  IF NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_pattern'),true) THEN NEW.line_pattern:=NULL; END IF;
  IF NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'font'),true) THEN NEW.font:=NULL; END IF;
  IF NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_1'),true)
     AND NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_2'),true)
     AND NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_3'),true) THEN NEW.no_name_line:=false; END IF;
  IF NEW.no_name_line OR NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_1'),true) THEN NEW.line_1:=NULL; END IF;
  IF NEW.no_name_line OR NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_2'),true) THEN NEW.line_2:=NULL; END IF;
  IF NEW.no_name_line OR NOT coalesce(public.marketplace_product_field_enabled(NEW.product_id,'line_3'),true) THEN NEW.line_3:=NULL; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_returned_quantity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_returned_quantity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.quantity IS DISTINCT FROM OLD.quantity AND EXISTS(
    SELECT 1 FROM public.or_orders WHERE id=OLD.order_id
      AND source_marketplace_order_id IS NOT NULL AND status='ลงข้อมูลผิด'
  ) THEN
    RAISE EXCEPTION 'บิล Marketplace ที่ลงข้อมูลผิด ไม่สามารถแก้ไขจำนวนสินค้าได้';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_returned_references(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_returned_references() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.source_marketplace_order_id IS NOT NULL AND OLD.status='ลงข้อมูลผิด' AND
     nullif(btrim(NEW.channel_order_no),'') IS DISTINCT FROM nullif(btrim(OLD.channel_order_no),'') THEN
    RAISE EXCEPTION 'บิล Marketplace ที่ลงข้อมูลผิด ไม่สามารถแก้ไขเลขคำสั่งซื้อได้';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_marketplace_review_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_marketplace_review_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.source_marketplace_order_id IS NOT NULL AND OLD.status='รอตรวจคำสั่งซื้อ'
       AND EXISTS(SELECT 1 FROM public.mp_orders WHERE billed_order_id=OLD.id) THEN
      RAISE EXCEPTION 'บิล Marketplace อยู่ระหว่างรอตรวจคำสั่งซื้อ ไม่สามารถลบบิลได้';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.source_marketplace_order_id IS NOT NULL THEN
    IF NEW.source_marketplace_order_id IS DISTINCT FROM OLD.source_marketplace_order_id THEN
      RAISE EXCEPTION 'ไม่สามารถเปลี่ยนที่มาของบิล Marketplace';
    END IF;
    IF OLD.status='รอตรวจคำสั่งซื้อ' AND
       (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN
      RAISE EXCEPTION 'บิล Marketplace อยู่ระหว่างรอตรวจคำสั่งซื้อ กรุณาตีกลับก่อนแก้ไขข้อมูล';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_order_failed_queue_archive(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_failed_queue_archive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.failed_queue_archived_at IS NOT NULL
     AND OLD.failed_queue_archived_at IS DISTINCT FROM NEW.failed_queue_archived_at
     AND NOT EXISTS (
       SELECT 1 FROM public.us_users
       WHERE id = auth.uid()
         AND role IN ('superadmin', 'admin', 'account')
     ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เก็บรายการตรวจสอบไม่ผ่านเข้าประวัติ';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_pp_actual_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pp_actual_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_order uuid;
BEGIN
  IF TG_TABLE_NAME = 'pp_production_order_items' THEN
    v_order := CASE WHEN TG_OP='DELETE' THEN OLD.order_id ELSE NEW.order_id END;
    -- Lock the parent first so direct edits cannot race completion.
    PERFORM 1 FROM pp_production_orders WHERE id=v_order FOR UPDATE;
    IF EXISTS(SELECT 1 FROM pp_production_orders WHERE id=v_order AND status='completed')
       OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM pp_production_orders WHERE id=OLD.order_id AND status='completed')) THEN
      RAISE EXCEPTION 'ไม่สามารถแก้ไขรายการของใบแปรรูปที่ปิดงานแล้ว';
    END IF;
    IF current_user IN ('authenticated','anon') AND TG_OP<>'DELETE' THEN
      IF NEW.actual_qty IS NOT NULL OR NEW.completion_report IS NOT NULL THEN RAISE EXCEPTION 'กรุณาปิดงานผ่านขั้นตอนบันทึกผลผลิตจริง'; END IF;
    END IF;
  ELSE
    IF TG_OP='DELETE' THEN
      IF OLD.status='completed' THEN RAISE EXCEPTION 'ใบแปรรูปปิดงานแล้ว'; END IF;
      RETURN OLD;
    END IF;
    IF OLD.status='completed' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.completion_short IS DISTINCT FROM OLD.completion_short OR NEW.completed_at IS DISTINCT FROM OLD.completed_at OR NEW.completed_by IS DISTINCT FROM OLD.completed_by) THEN RAISE EXCEPTION 'ใบแปรรูปปิดงานแล้ว'; END IF;
    IF current_user IN ('authenticated','anon') AND (NEW.status='completed' OR NEW.completion_short IS DISTINCT FROM OLD.completion_short) THEN RAISE EXCEPTION 'กรุณาปิดงานผ่านขั้นตอนบันทึกผลผลิตจริง'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_pp_production_create_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pp_production_create_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_role text;
BEGIN
  SELECT role INTO v_role FROM public.us_users
  WHERE id = auth.uid() AND is_active IS TRUE;
  IF v_role IS NULL OR v_role NOT IN ('production', 'packing_staff', 'store', 'admin', 'superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างใบแปรรูป';
  END IF;
  NEW.created_by := auth.uid();
  RETURN NEW;
END;
$$;


--
-- Name: guard_pp_production_max_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pp_production_max_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_over record;
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'completed' THEN
    SELECT p.product_code, COALESCE(b.on_hand, 0) AS on_hand, r.max_stock INTO v_over
    FROM public.pp_production_order_items oi
    JOIN public.pp_recipes r ON r.product_id = oi.product_id
    JOIN public.pr_products p ON p.id = oi.product_id
    LEFT JOIN public.inv_stock_balances b ON b.product_id = oi.product_id
    WHERE oi.order_id = NEW.id AND r.max_stock IS NOT NULL AND COALESCE(b.on_hand, 0) > r.max_stock LIMIT 1;
    IF FOUND THEN RAISE EXCEPTION 'สินค้า % คงเหลือ % เกิน Max %', v_over.product_code, v_over.on_hand, v_over.max_stock; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_pp_production_status_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pp_production_status_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_role text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  SELECT role INTO v_role FROM public.us_users
  WHERE id = auth.uid() AND is_active IS TRUE;

  IF NEW.status = 'pending' AND (v_role IS NULL OR v_role NOT IN ('production', 'packing_staff', 'store', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ส่งใบแปรรูปเพื่ออนุมัติ';
  ELSIF NEW.status IN ('approved', 'rejected') AND (v_role IS NULL OR v_role NOT IN ('store', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติหรือปฏิเสธใบแปรรูป';
  ELSIF NEW.status = 'processing' AND (v_role IS NULL OR v_role NOT IN ('production', 'packing_staff', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เริ่มแปรรูป';
  ELSIF NEW.status = 'completed' AND (v_role IS NULL OR v_role NOT IN ('store', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันรับเข้าผลผลิต';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_prebill_document_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_prebill_document_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();

  IF TG_OP = 'INSERT' THEN
    IF v_role <> 'superadmin' AND (
      NEW.status NOT IN ('draft', 'active') OR NEW.approved_by IS NOT NULL
      OR NEW.approved_at IS NOT NULL OR NEW.approved_special_discount IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'ไม่มีสิทธิ์กำหนดสถานะอนุมัติ';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- The opener is immutable. Editing a teammate's document must never transfer
  -- ownership or replace the opener's display name.
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id
     OR NEW.owner_name IS DISTINCT FROM OLD.owner_name THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนผู้เปิดเอกสาร QT/PC ได้';
  END IF;

  IF OLD.status IN ('converted', 'cancelled') THEN
    IF (to_jsonb(NEW) - ARRAY['converted_order_id', 'source_document_id', 'updated_at'])
       IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['converted_order_id', 'source_document_id', 'updated_at']) THEN
      RAISE EXCEPTION 'เอกสารที่เปิดบิลหรือยกเลิกแล้วแก้ไขไม่ได้';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF v_role <> 'superadmin' THEN
    IF NEW.status = 'approved'
       OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
       OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
       OR NEW.approved_special_discount IS DISTINCT FROM OLD.approved_special_discount THEN
      RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้นที่อนุมัติส่วนลดได้';
    END IF;
    IF NEW.special_discount IS DISTINCT FROM OLD.special_discount
       AND NEW.status <> 'pending_discount' THEN
      RAISE EXCEPTION 'ส่วนลดพิเศษต้องส่งคำขออนุมัติ';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
      (OLD.status IN ('draft', 'active', 'rejected') AND NEW.status IN ('draft', 'active'))
      OR (OLD.status IN ('draft', 'active', 'rejected') AND NEW.status = 'pending_discount'
          AND NEW.discount_requested_by = auth.uid()
          AND btrim(COALESCE(NEW.discount_request_note, '')) <> '')
      OR (OLD.status IN ('active', 'approved') AND NEW.status = 'converted'
          AND NEW.converted_order_id IS NOT NULL)
      OR NEW.status = 'cancelled'
    ) THEN
      RAISE EXCEPTION 'ไม่มีสิทธิ์เปลี่ยนสถานะเอกสาร';
    END IF;
  END IF;

  IF v_role <> 'superadmin' AND OLD.status IN ('pending_discount', 'approved')
     AND NEW.status <> 'cancelled'
     AND NOT (OLD.status = 'approved' AND NEW.status = 'converted'
              AND NEW.converted_order_id IS NOT NULL) THEN
    RAISE EXCEPTION 'เอกสารถูกล็อก แก้ไขได้โดย superadmin เท่านั้น';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: guard_prebill_item_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_prebill_item_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_locked BOOLEAN;
BEGIN
  -- Only the superadmin-only hard-delete RPC sets this transaction-local flag.
  IF TG_OP = 'DELETE'
     AND current_setting('app.prebill_hard_delete', true) = 'on'
     AND public.check_user_role(auth.uid(), ARRAY['superadmin']) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.or_prebill_documents d
      WHERE d.id = NEW.document_id AND d.status IN ('converted', 'cancelled')
    ) INTO v_locked;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.or_prebill_documents d
      WHERE d.id = OLD.document_id AND d.status IN ('converted', 'cancelled')
    ) INTO v_locked;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.or_prebill_documents d
      WHERE d.id IN (OLD.document_id, NEW.document_id)
        AND d.status IN ('converted', 'cancelled')
    ) INTO v_locked;
  END IF;

  IF v_locked THEN
    RAISE EXCEPTION 'รายการของเอกสารที่เปิดบิลหรือยกเลิกแล้วแก้ไขไม่ได้';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_receiving_closure_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_receiving_closure_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_user IN ('authenticated','anon') THEN
    IF TG_TABLE_NAME='inv_po_items' THEN
      IF TG_OP='INSERT' THEN
        IF coalesce(NEW.resolution_qty,0)<>0 OR NEW.resolution_type IS NOT NULL OR NEW.resolved_by IS NOT NULL
          OR NEW.resolved_at IS NOT NULL OR NEW.resolution_note IS NOT NULL THEN RAISE EXCEPTION 'ต้องปิดยอดผ่านการอนุมัติ'; END IF;
      ELSIF NEW.resolution_qty IS DISTINCT FROM OLD.resolution_qty OR NEW.resolution_type IS DISTINCT FROM OLD.resolution_type
        OR NEW.resolved_by IS DISTINCT FROM OLD.resolved_by OR NEW.resolved_at IS DISTINCT FROM OLD.resolved_at
        OR NEW.resolution_note IS DISTINCT FROM OLD.resolution_note THEN RAISE EXCEPTION 'ต้องปิดยอดผ่านการอนุมัติ'; END IF;
    ELSIF NEW.status='closed' AND OLD.status IS DISTINCT FROM 'closed' THEN RAISE EXCEPTION 'ต้องปิดยอดผ่านการอนุมัติ';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_refund_against_waiver(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_refund_against_waiver() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM id FROM or_orders WHERE id=NEW.order_id FOR UPDATE;
  PERFORM public.or_supersede_stale_waivers(NEW.order_id);
  IF NEW.status IN ('pending','approved') AND NEW.reason ILIKE '%โอนเกิน%'
    AND EXISTS(SELECT 1 FROM ac_overpayment_waivers WHERE order_id=NEW.order_id AND status IN ('pending','approved')) THEN
    RAISE EXCEPTION 'บิลนี้มีคำขอไม่รับเงินคืนแล้ว ไม่สามารถสร้างหรืออนุมัติโอนคืนซ้ำได้';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_separate_audit_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_separate_audit_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.count_mode='separate' THEN
    IF TG_OP='INSERT' AND EXISTS (SELECT 1 FROM roll_material_configs WHERE fg_product_id=NEW.product_id) THEN
      RAISE EXCEPTION 'FG ที่คำนวณจาก RM ไม่ต้องตรวจนับ';
    END IF;
    IF TG_OP='UPDATE' AND (NEW.count_mode IS DISTINCT FROM OLD.count_mode OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.audit_id IS DISTINCT FROM OLD.audit_id OR NEW.system_qty IS DISTINCT FROM OLD.system_qty OR NEW.system_safety_stock IS DISTINCT FROM OLD.system_safety_stock OR NEW.location_snapshot IS DISTINCT FROM OLD.location_snapshot OR NEW.system_reserved IS DISTINCT FROM OLD.system_reserved) THEN
      RAISE EXCEPTION 'ไม่สามารถเปลี่ยน snapshot ของใบ Audit';
    END IF;
    IF NEW.is_counted THEN
      IF NOT EXISTS (SELECT 1 FROM inv_audits WHERE id=NEW.audit_id AND status='in_progress') THEN RAISE EXCEPTION 'ใบ Audit ไม่อยู่ในสถานะนับ'; END IF;
      IF NEW.counted_qty IS NULL OR NEW.counted_qty < 0 OR NEW.counted_qty::text IN ('NaN','Infinity','-Infinity') OR NEW.counted_safety_stock < 0 OR NEW.counted_safety_stock::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'จำนวนตรวจนับไม่ถูกต้อง'; END IF;
      IF NEW.system_safety_stock > 0 AND NEW.counted_safety_stock IS NULL THEN RAISE EXCEPTION 'ต้องกรอก Safety ที่นับได้'; END IF;
      IF NEW.system_safety_stock IS NULL AND NEW.counted_safety_stock IS NOT NULL THEN RAISE EXCEPTION 'ST ใช้ยอดนับรวม ไม่แยก Safety'; END IF;
      NEW.variance := NEW.counted_qty - NEW.system_qty;
      NEW.safety_stock_match := CASE WHEN NEW.counted_safety_stock IS NULL THEN NULL ELSE NEW.counted_safety_stock=COALESCE(NEW.system_safety_stock,0) END;
    END IF;
  ELSIF TG_OP='UPDATE' AND OLD.count_mode='separate' THEN
    RAISE EXCEPTION 'ไม่สามารถเปลี่ยนรูปแบบการนับ';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_special_tracked_adjustment_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_special_tracked_adjustment_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'approved'
     AND OLD.status IS DISTINCT FROM 'approved'
     AND EXISTS (
       SELECT 1
       FROM public.inv_adjustment_items AS item
       JOIN public.wh_sub_wms_map_spares AS spare ON spare.product_id = item.product_id
       WHERE item.adjustment_id = NEW.id
     ) THEN
    RAISE EXCEPTION 'ใบปรับนี้มีสินค้า ST จึงไม่สามารถอนุมัติได้ กรุณาสร้างใบใหม่โดยปรับ SKU สินค้าผลิตที่ผูกไว้แทน';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_special_tracked_adjustment_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_special_tracked_adjustment_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.wh_sub_wms_map_spares AS spare
    WHERE spare.product_id = NEW.product_id
  ) THEN
    RAISE EXCEPTION 'สินค้า ST ไม่สามารถสร้างใบปรับสต๊อคได้ กรุณาปรับ SKU สินค้าผลิตที่ผูกไว้แทน';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_store_adjustment_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_store_adjustment_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM us_users WHERE id=auth.uid() AND role='store') AND auth.role() <> 'service_role' THEN
    IF TG_OP <> 'INSERT' AND (OLD.status='approved' OR OLD.approved_by IS NOT NULL OR OLD.approved_at IS NOT NULL) THEN
      RAISE EXCEPTION 'Store ไม่มีสิทธิ์แก้ไขใบปรับสต๊อคที่อนุมัติแล้ว';
    END IF;
    IF TG_OP <> 'DELETE' AND (NEW.status='approved' OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL) THEN
      RAISE EXCEPTION 'Store ไม่มีสิทธิ์อนุมัติใบปรับสต๊อค';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_store_audit_header(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_store_audit_header() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM us_users WHERE id=auth.uid() AND role='store') AND auth.role() <> 'service_role' THEN
    IF NEW.status NOT IN ('in_progress','review') OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.adjustment_id IS NOT NULL THEN
      RAISE EXCEPTION 'Store ไม่มีสิทธิ์อนุมัติหรือปิด Audit';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['status','total_items','show_system_qty','counted_items','partial_count_reason','accuracy_percent','total_variance','location_accuracy_percent','safety_stock_accuracy_percent','total_location_mismatches','total_safety_stock_mismatches']) IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['status','total_items','show_system_qty','counted_items','partial_count_reason','accuracy_percent','total_variance','location_accuracy_percent','safety_stock_accuracy_percent','total_location_mismatches','total_safety_stock_mismatches']) THEN
      RAISE EXCEPTION 'Store ไม่มีสิทธิ์เปลี่ยนข้อมูลหัวใบ Audit';
    END IF;
    IF NEW.status='review' AND NOT (current_user_can_audit() AND auth.uid()=ANY(COALESCE(OLD.assigned_to,ARRAY[]::uuid[]))) THEN
      RAISE EXCEPTION 'ส่งรีวิวได้เฉพาะผู้ตรวจที่ได้รับมอบหมาย';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_unique_order_tracking_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_unique_order_tracking_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tracking TEXT;
  v_tracking_key TEXT;
BEGIN
  v_tracking := NULLIF(btrim(NEW.tracking_number), '');
  NEW.tracking_number := v_tracking;
  v_tracking_key := upper(regexp_replace(COALESCE(v_tracking, ''), '[[:space:]]+', '', 'g'));

  IF TG_OP = 'UPDATE'
     AND upper(regexp_replace(COALESCE(NULLIF(btrim(OLD.tracking_number), ''), ''), '[[:space:]]+', '', 'g')) = v_tracking_key THEN
    RETURN NEW;
  END IF;

  IF v_tracking IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.or_orders other
    WHERE other.id IS DISTINCT FROM NEW.id
      AND COALESCE(other.status, '') <> 'ยกเลิก'
      AND upper(regexp_replace(COALESCE(other.tracking_number, ''), '[[:space:]]+', '', 'g')) = v_tracking_key
  ) THEN
    RAISE EXCEPTION 'เลขพัสดุ % ซ้ำกับบิลอื่นที่ยังใช้งานในระบบ', v_tracking;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_wms_requisition_approval_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_wms_requisition_approval_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status
     AND NEW.status IN ('approved', 'rejected') THEN
    SELECT u.role
      INTO v_role
    FROM public.us_users AS u
    WHERE u.id = auth.uid()
      AND u.is_active IS TRUE;

    IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store') THEN
      RAISE EXCEPTION 'Not authorized to approve or reject requisitions';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_account_can_read_all(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_account_can_read_all() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.us_users
    WHERE id = auth.uid()
      AND role = 'account'
  );
$$;


--
-- Name: FUNCTION hr_account_can_read_all(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hr_account_can_read_all() IS 'True only for authenticated users whose us_users.role is account; used by read-only HR RLS policies.';


--
-- Name: hr_announcement_after_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_announcement_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO hr_announcement_approvals (announcement_id, employee_id)
  SELECT NEW.id, a.employee_id FROM hr_announcement_approvers a WHERE a.is_active
  ON CONFLICT (announcement_id, employee_id) DO NOTHING;

  PERFORM hr_announcement_sync_status(NEW.id);
  RETURN NEW;
END;
$$;


--
-- Name: hr_announcement_after_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_announcement_after_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.title IS DISTINCT FROM OLD.title
     OR NEW.content IS DISTINCT FROM OLD.content
     OR NEW.attachment_urls IS DISTINCT FROM OLD.attachment_urls
     OR NEW.category_id IS DISTINCT FROM OLD.category_id
     OR NEW.target_all_departments IS DISTINCT FROM OLD.target_all_departments THEN
    UPDATE hr_announcement_approvals
      SET status = 'pending', acted_at = NULL, note = NULL
      WHERE announcement_id = NEW.id AND status <> 'pending';
    UPDATE hr_announcements SET reject_reason = NULL WHERE id = NEW.id AND reject_reason IS NOT NULL;
    PERFORM hr_announcement_sync_status(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_announcement_approval_after_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_announcement_approval_after_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'rejected' AND coalesce(NEW.note, '') <> '' THEN
      UPDATE hr_announcements SET reject_reason = NEW.note WHERE id = NEW.announcement_id;
    END IF;
    PERFORM hr_announcement_sync_status(NEW.announcement_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_announcement_sync_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_announcement_sync_status(p_announcement_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total INT;
  v_approved INT;
  v_rejected INT;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE status = 'approved'), count(*) FILTER (WHERE status = 'rejected')
    INTO v_total, v_approved, v_rejected
  FROM hr_announcement_approvals WHERE announcement_id = p_announcement_id;

  IF v_rejected > 0 THEN
    UPDATE hr_announcements SET status = 'rejected', published_at = NULL
    WHERE id = p_announcement_id AND status <> 'rejected';
  ELSIF v_total > 0 AND v_approved = v_total THEN
    UPDATE hr_announcements SET status = 'published', published_at = coalesce(published_at, now())
    WHERE id = p_announcement_id AND status <> 'published';
  ELSE
    UPDATE hr_announcements SET status = 'pending', published_at = NULL
    WHERE id = p_announcement_id AND status <> 'pending';
  END IF;
END;
$$;


--
-- Name: hr_announcement_targets_me(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_announcement_targets_me(p_announcement_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM hr_announcements a
    JOIN hr_employees e ON e.id = hr_my_employee_id()
    WHERE a.id = p_announcement_id
      AND (
        a.target_all_departments
        OR EXISTS (
          SELECT 1 FROM hr_announcement_departments d
          WHERE d.announcement_id = a.id AND d.department_id = e.department_id
        )
      )
  );
$$;


--
-- Name: hr_asset_dept_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_asset_dept_name(p uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN p IS NULL THEN '— ไม่ระบุ —'
    ELSE COALESCE((SELECT name FROM hr_departments WHERE id = p), '(ไม่พบแผนก)')
  END;
$$;


--
-- Name: hr_asset_emp_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_asset_emp_name(p uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN p IS NULL THEN '— ไม่ระบุ —'
    ELSE COALESCE(
      (SELECT NULLIF(TRIM(CONCAT_WS(' ', first_name, last_name)), '') FROM hr_employees WHERE id = p),
      (SELECT employee_code FROM hr_employees WHERE id = p),
      '(ไม่พบพนักงาน)'
    )
  END;
$$;


--
-- Name: hr_asset_peek_next_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_asset_peek_next_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_year TEXT;
  v_next INT;
BEGIN
  v_year := to_char(now() AT TIME ZONE 'Asia/Bangkok', 'YYYY');
  SELECT COALESCE(MAX((regexp_match(asset_code, '^AST-' || v_year || '-([0-9]+)$'))[1]::INT), 0) + 1
    INTO v_next
    FROM hr_assets
   WHERE asset_code ~ ('^AST-' || v_year || '-[0-9]+$');
  RETURN 'AST-' || v_year || '-' || lpad(v_next::TEXT, 4, '0');
END;
$_$;


--
-- Name: hr_asset_status_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_asset_status_label(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p
    WHEN 'active' THEN 'ใช้งาน'
    WHEN 'borrowed' THEN 'ยืมใช้งาน'
    WHEN 'maintenance' THEN 'ซ่อมบำรุง'
    WHEN 'retired' THEN 'ปลดระวาง'
    WHEN 'disposed' THEN 'จำหน่ายแล้ว'
    WHEN 'lost' THEN 'สูญหาย'
    ELSE p
  END;
$$;


--
-- Name: hr_assets_log_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assets_log_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_by TEXT;
BEGIN
  SELECT username INTO v_by FROM us_users WHERE id = v_uid;
  v_by := COALESCE(v_by, 'ระบบ');

  IF TG_OP = 'INSERT' THEN
    INSERT INTO hr_asset_logs(asset_id, asset_code, asset_name, action, changed_by, changed_by_name)
    VALUES (NEW.id, NEW.asset_code, NEW.name, 'created', v_uid, v_by);
    RETURN NEW;
  END IF;

  -- UPDATE: บันทึกทีละฟิลด์ที่เปลี่ยนจริง
  IF NEW.name IS DISTINCT FROM OLD.name THEN
    INSERT INTO hr_asset_logs(asset_id, asset_code, asset_name, action, field, field_label, old_value, new_value, changed_by, changed_by_name)
    VALUES (NEW.id, NEW.asset_code, NEW.name, 'updated', 'name', 'ชื่อทรัพย์สิน', OLD.name, NEW.name, v_uid, v_by);
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO hr_asset_logs(asset_id, asset_code, asset_name, action, field, field_label, old_value, new_value, changed_by, changed_by_name)
    VALUES (NEW.id, NEW.asset_code, NEW.name, 'updated', 'status', 'สถานะ',
            hr_asset_status_label(OLD.status), hr_asset_status_label(NEW.status), v_uid, v_by);
  END IF;

  IF NEW.assigned_employee_id IS DISTINCT FROM OLD.assigned_employee_id THEN
    INSERT INTO hr_asset_logs(asset_id, asset_code, asset_name, action, field, field_label, old_value, new_value, changed_by, changed_by_name)
    VALUES (NEW.id, NEW.asset_code, NEW.name, 'updated', 'assigned_employee_id', 'ผู้รับผิดชอบ',
            hr_asset_emp_name(OLD.assigned_employee_id), hr_asset_emp_name(NEW.assigned_employee_id), v_uid, v_by);
  END IF;

  IF NEW.department_id IS DISTINCT FROM OLD.department_id THEN
    INSERT INTO hr_asset_logs(asset_id, asset_code, asset_name, action, field, field_label, old_value, new_value, changed_by, changed_by_name)
    VALUES (NEW.id, NEW.asset_code, NEW.name, 'updated', 'department_id', 'แผนก',
            hr_asset_dept_name(OLD.department_id), hr_asset_dept_name(NEW.department_id), v_uid, v_by);
  END IF;

  IF NEW.location IS DISTINCT FROM OLD.location THEN
    INSERT INTO hr_asset_logs(asset_id, asset_code, asset_name, action, field, field_label, old_value, new_value, changed_by, changed_by_name)
    VALUES (NEW.id, NEW.asset_code, NEW.name, 'updated', 'location', 'สถานที่ใช้งาน',
            OLD.location, NEW.location, v_uid, v_by);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_assets_set_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assets_set_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_year TEXT;
  v_next INT;
BEGIN
  IF NEW.asset_code IS NULL OR btrim(NEW.asset_code) = '' THEN
    v_year := to_char(now() AT TIME ZONE 'Asia/Bangkok', 'YYYY');
    -- กันสองคนกดบันทึกพร้อมกันแล้วได้เลขซ้ำ
    PERFORM pg_advisory_xact_lock(hashtext('hr_asset_code:' || v_year));
    SELECT COALESCE(MAX((regexp_match(asset_code, '^AST-' || v_year || '-([0-9]+)$'))[1]::INT), 0) + 1
      INTO v_next
      FROM hr_assets
     WHERE asset_code ~ ('^AST-' || v_year || '-[0-9]+$');
    NEW.asset_code := 'AST-' || v_year || '-' || lpad(v_next::TEXT, 4, '0');
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: hr_assign_employee_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assign_employee_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND (NEW.employee_code IS NULL OR btrim(NEW.employee_code) = '') THEN
    NEW.employee_code := 'EMP' || lpad(nextval('hr_employee_code_seq')::text, 5, '0');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_assign_interview_template(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assign_interview_template(p_template_id uuid, p_position_id uuid, p_department_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (p_position_id IS NOT NULL)::INT + (p_department_id IS NOT NULL)::INT <> 1 THEN RAISE EXCEPTION 'เลือกแผนกหรือตำแหน่ง'; END IF;
  IF p_position_id IS NOT NULL THEN
    INSERT INTO public.hr_interview_template_assignments(template_id, position_id) VALUES(p_template_id, p_position_id)
    ON CONFLICT(position_id) DO UPDATE SET template_id = excluded.template_id;
  ELSE
    INSERT INTO public.hr_interview_template_assignments(template_id, department_id) VALUES(p_template_id, p_department_id)
    ON CONFLICT(department_id) DO UPDATE SET template_id = excluded.template_id;
  END IF;
END;
$$;


--
-- Name: hr_attendance_facts(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_attendance_facts(p_from date, p_to date, p_employee uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, employee_code text, employee_name text, department_id uuid, work_date date, day_type text, work_mode text, is_remote_day boolean, expected_start_min integer, expected_end_min integer, grace_min integer, actual_in_min integer, actual_in_source text, actual_in_ref uuid, actual_out_min integer, actual_out_source text, actual_out_ref uuid, ot_in_min integer, ot_in_ref uuid, ot_request_id uuid, ot_request_status text, ot_request_created_date date, ot_request_created_min integer, leave_id uuid, leave_status text, leave_mode text, leave_type_name text, leave_start_date date, leave_filed_date date, leave_filed_min integer, leave_start_min integer, leave_end_min integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- SECURITY DEFINER ข้าม RLS — พนักงานทั่วไปดูได้เฉพาะของตัวเอง
  IF NOT hr_is_admin() AND (p_employee IS NULL OR p_employee IS DISTINCT FROM hr_my_employee_id()) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูข้อมูลเวลาทำงานของพนักงานคนอื่น';
  END IF;

  IF p_to < p_from THEN
    RAISE EXCEPTION 'ช่วงวันที่ไม่ถูกต้อง';
  END IF;

  RETURN QUERY
  WITH default_schedule AS (
    SELECT s.work_start, s.work_end, s.late_grace_min, s.work_days
    FROM hr_work_schedules s
    WHERE s.is_active
    ORDER BY s.is_default DESC, s.created_at
    LIMIT 1
  ),
  emp AS (
    SELECT
      e.id,
      e.employee_code,
      TRIM(e.first_name || ' ' || e.last_name) AS full_name,
      e.department_id,
      e.hire_date,
      e.work_mode,
      COALESCE(es.work_start, ds.work_start, TIME '08:00') AS work_start,
      COALESCE(es.work_end, ds.work_end, TIME '17:00') AS work_end,
      COALESCE(es.late_grace_min, ds.late_grace_min, 0) AS late_grace_min,
      COALESCE(es.work_days, ds.work_days, '1,2,3,4,5,6') AS work_days
    FROM hr_employees e
    LEFT JOIN hr_work_schedules es ON es.id = e.work_schedule_id AND es.is_active
    LEFT JOIN default_schedule ds ON true
    WHERE e.employment_status IN ('active', 'probation')
      AND (p_employee IS NULL OR e.id = p_employee)
  ),
  days AS (
    SELECT gs::DATE AS d FROM generate_series(p_from, p_to, INTERVAL '1 day') gs
  ),
  base AS (
    SELECT emp.*, days.d
    FROM emp
    CROSS JOIN days
    WHERE emp.hire_date IS NULL OR days.d >= emp.hire_date
  )
  SELECT
    b.id,
    b.employee_code,
    b.full_name,
    b.department_id,
    b.d,
    CASE
      WHEN cal.id IS NOT NULL THEN cal.day_type
      WHEN hol.id IS NOT NULL THEN 'company_holiday'
      WHEN EXTRACT(ISODOW FROM b.d)::TEXT = ANY (string_to_array(b.work_days, ',')) THEN 'work'
      ELSE 'weekly_off'
    END AS day_type,
    b.work_mode,
    (b.work_mode = 'wfh' OR wfh.id IS NOT NULL) AS is_remote_day,
    (EXTRACT(HOUR FROM eff_start) * 60 + EXTRACT(MINUTE FROM eff_start))::INT AS expected_start_min,
    (EXTRACT(HOUR FROM eff_end) * 60 + EXTRACT(MINUTE FROM eff_end))::INT AS expected_end_min,
    COALESCE(cal_sched.late_grace_min, b.late_grace_min)::INT AS grace_min,

    COALESCE(tin.min_of_day, cin.min_of_day)::INT AS actual_in_min,
    CASE WHEN tin.id IS NOT NULL THEN 'entry' WHEN cin.id IS NOT NULL THEN 'certified' END AS actual_in_source,
    COALESCE(tin.id, cin.id) AS actual_in_ref,

    COALESCE(tout.min_of_day, cout.min_of_day)::INT AS actual_out_min,
    CASE WHEN tout.id IS NOT NULL THEN 'entry' WHEN cout.id IS NOT NULL THEN 'certified' END AS actual_out_source,
    COALESCE(tout.id, cout.id) AS actual_out_ref,

    otin.min_of_day::INT AS ot_in_min,
    otin.id AS ot_in_ref,
    otr.id AS ot_request_id,
    otr.status AS ot_request_status,
    (otr.created_at AT TIME ZONE 'Asia/Bangkok')::DATE AS ot_request_created_date,
    (EXTRACT(HOUR FROM otr.created_at AT TIME ZONE 'Asia/Bangkok') * 60
      + EXTRACT(MINUTE FROM otr.created_at AT TIME ZONE 'Asia/Bangkok'))::INT AS ot_request_created_min,

    lv.id AS leave_id,
    lv.status AS leave_status,
    lv.leave_mode,
    lv.type_name AS leave_type_name,
    lv.start_date AS leave_start_date,
    (lv.created_at AT TIME ZONE 'Asia/Bangkok')::DATE AS leave_filed_date,
    (EXTRACT(HOUR FROM lv.created_at AT TIME ZONE 'Asia/Bangkok') * 60
      + EXTRACT(MINUTE FROM lv.created_at AT TIME ZONE 'Asia/Bangkok'))::INT AS leave_filed_min,
    (EXTRACT(HOUR FROM lv.start_time) * 60 + EXTRACT(MINUTE FROM lv.start_time))::INT AS leave_start_min,
    (EXTRACT(HOUR FROM lv.end_time) * 60 + EXTRACT(MINUTE FROM lv.end_time))::INT AS leave_end_min
  FROM base b
  LEFT JOIN hr_employee_work_calendar cal ON cal.employee_id = b.id AND cal.work_date = b.d
  LEFT JOIN hr_work_schedules cal_sched ON cal_sched.id = cal.work_schedule_id
  LEFT JOIN hr_company_holidays hol ON hol.holiday_date = b.d
  -- ต้องอยู่ก่อน eff เพราะ eff อ้างช่วงเวลาของคำขอ WFH
  LEFT JOIN LATERAL (
    SELECT w.id, w.start_time, w.end_time
    FROM hr_wfh_requests w
    WHERE w.employee_id = b.id AND w.status = 'approved'
      AND w.start_date <= b.d AND w.end_date >= b.d
    ORDER BY w.approved_at DESC NULLS LAST
    LIMIT 1
  ) wfh ON true
  CROSS JOIN LATERAL (
    SELECT
      COALESCE(wfh.start_time, cal.work_start, cal_sched.work_start, b.work_start) AS eff_start,
      COALESCE(wfh.end_time, cal.work_end, cal_sched.work_end, b.work_end) AS eff_end
  ) eff
  LEFT JOIN LATERAL (
    SELECT te.id, EXTRACT(EPOCH FROM ((te.entry_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_entries te
    WHERE te.employee_id = b.id AND te.work_date = b.d AND te.entry_type = 'clock_in'
    ORDER BY te.entry_time
    LIMIT 1
  ) tin ON true
  LEFT JOIN LATERAL (
    SELECT te.id, EXTRACT(EPOCH FROM ((te.entry_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_entries te
    WHERE te.employee_id = b.id AND te.work_date = b.d AND te.entry_type = 'clock_out'
    ORDER BY te.entry_time DESC
    LIMIT 1
  ) tout ON true
  LEFT JOIN LATERAL (
    SELECT te.id, EXTRACT(EPOCH FROM ((te.entry_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_entries te
    WHERE te.employee_id = b.id AND te.work_date = b.d AND te.entry_type = 'ot_in'
    ORDER BY te.entry_time
    LIMIT 1
  ) otin ON true
  LEFT JOIN LATERAL (
    SELECT tc.id, EXTRACT(EPOCH FROM ((tc.certified_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_certifications tc
    WHERE tc.employee_id = b.id AND tc.work_date = b.d AND tc.entry_type = 'clock_in'
  ) cin ON true
  LEFT JOIN LATERAL (
    SELECT tc.id, EXTRACT(EPOCH FROM ((tc.certified_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_certifications tc
    WHERE tc.employee_id = b.id AND tc.work_date = b.d AND tc.entry_type = 'clock_out'
  ) cout ON true
  LEFT JOIN LATERAL (
    SELECT lr.id, lr.status, lr.leave_mode, lr.start_date, lr.created_at,
           lr.start_time, lr.end_time, lt.name AS type_name
    FROM hr_leave_requests lr
    LEFT JOIN hr_leave_types lt ON lt.id = lr.leave_type_id
    WHERE lr.employee_id = b.id
      AND lr.start_date <= b.d AND lr.end_date >= b.d
      AND lr.status IN ('approved', 'pending')
    ORDER BY CASE lr.status WHEN 'approved' THEN 0 ELSE 1 END, lr.created_at
    LIMIT 1
  ) lv ON true
  LEFT JOIN LATERAL (
    SELECT r.id, r.status, r.created_at
    FROM hr_ot_requests r
    WHERE r.employee_id = b.id AND r.request_date = b.d
      AND r.status IN ('approved', 'pending', 'rejected')
    ORDER BY CASE r.status WHEN 'approved' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END, r.created_at
    LIMIT 1
  ) otr ON true
  WHERE cal.day_type = 'work'
     OR (cal.id IS NULL AND hol.id IS NULL
         AND EXTRACT(ISODOW FROM b.d)::TEXT = ANY (string_to_array(b.work_days, ',')))
     OR tin.id IS NOT NULL OR tout.id IS NOT NULL OR otin.id IS NOT NULL
     OR cin.id IS NOT NULL OR cout.id IS NOT NULL
  ORDER BY b.full_name, b.d;
END;
$$;


--
-- Name: hr_can_approve_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_can_approve_leave() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.us_users
    WHERE id = auth.uid()
      AND is_active IS TRUE
      AND role IN ('superadmin', 'admin', 'hr', 'account')
  );
$$;


