-- Name: hr_can_certify_time(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_can_certify_time(p_employee_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT hr_is_admin() OR EXISTS (
    SELECT 1
    FROM hr_employees e
    JOIN hr_departments d ON d.id = e.department_id
    WHERE e.id = p_employee_id
      AND d.manager_id = hr_my_employee_id()
      AND e.id <> hr_my_employee_id()
  );
$$;


