--
-- Name: hr_cancel_payroll(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_cancel_payroll(p_run uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.hr_payroll_runs; company UUID;
BEGIN
  IF NOT public.hr_payroll_role_allowed() OR NULLIF(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ไม่มีสิทธิ์หรือยังไม่ระบุเหตุผล'; END IF;
  SELECT company_id INTO company FROM public.hr_payroll_runs WHERE id=p_run;
  PERFORM pg_advisory_xact_lock(hashtextextended(company::text || ':payroll',0));
  SELECT * INTO r FROM public.hr_payroll_runs WHERE id=p_run FOR UPDATE;
  IF NOT FOUND OR r.status='cancelled' THEN RAISE EXCEPTION 'ไม่พบงวดที่ยกเลิกได้'; END IF;
  IF r.status='confirmed' THEN PERFORM public.hr_reopen_payroll(p_run,p_reason); END IF;
  INSERT INTO public.hr_payroll_revisions(payroll_run_id,reason,run_before,items_before,created_by)
    SELECT r.id,'ยกเลิกงวด: '||trim(p_reason),to_jsonb(r),COALESCE(jsonb_agg(to_jsonb(i)),'[]'),auth.uid() FROM public.hr_payroll_items i WHERE payroll_run_id=r.id;
  UPDATE public.hr_payroll_runs SET status='cancelled',updated_at=now() WHERE id=r.id;
END $$;


--
-- Name: hr_cancel_payroll_adjustment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_cancel_payroll_adjustment(p_adjustment uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE company UUID;
BEGIN
  IF NOT public.hr_payroll_role_allowed() OR NULLIF(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลและใช้สิทธิ์ฝ่ายบัญชี'; END IF;
  SELECT company_id INTO company FROM public.hr_payroll_adjustments WHERE id=p_adjustment;
  PERFORM pg_advisory_xact_lock(hashtextextended(company::text || ':payroll',0));
  IF EXISTS(SELECT 1 FROM public.hr_payroll_payments WHERE adjustment_id=p_adjustment) THEN RAISE EXCEPTION 'รายการนี้จ่ายหรือรับคืนแล้ว ต้องปรับด้วยรายการใหม่'; END IF;
  UPDATE public.hr_payroll_adjustments SET status='cancelled',cancelled_reason=trim(p_reason),cancelled_by=auth.uid(),cancelled_at=now() WHERE id=p_adjustment AND status='approved';
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบรายการที่ยกเลิกได้'; END IF;
END $$;


--
-- Name: hr_company_manage_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_company_manage_allowed() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid() AND is_active IS TRUE AND role IN ('superadmin', 'admin', 'hr')
  );
$$;


--
-- Name: hr_payroll_adjustments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_payroll_adjustments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_key uuid NOT NULL,
    source_item_id uuid NOT NULL,
    company_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    earning_month date NOT NULL,
    reason text NOT NULL,
    previous_amounts jsonb NOT NULL,
    corrected_amounts jsonb NOT NULL,
    deltas jsonb NOT NULL,
    deduction_allocations jsonb DEFAULT '{}'::jsonb NOT NULL,
    income_delta numeric(12,2) NOT NULL,
    deduction_delta numeric(12,2) NOT NULL,
    net_delta numeric(12,2) NOT NULL,
    status text DEFAULT 'approved'::text NOT NULL,
    cancelled_reason text,
    cancelled_by uuid,
    cancelled_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_payroll_adjustments_reason_check CHECK ((length(TRIM(BOTH FROM reason)) > 0)),
    CONSTRAINT hr_payroll_adjustments_status_check CHECK ((status = ANY (ARRAY['approved'::text, 'cancelled'::text])))
);


--
-- Name: hr_create_payroll_adjustment(uuid, uuid, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_create_payroll_adjustment(p_request uuid, p_source uuid, p_corrected jsonb, p_reason text, p_expected_previous jsonb DEFAULT NULL::jsonb) RETURNS public.hr_payroll_adjustments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE source RECORD; existing public.hr_payroll_adjustments; previous JSONB; deltas JSONB:='{}'; field TEXT; current_amount NUMERIC; target NUMERIC; income NUMERIC:=0; deduction NUMERIC:=0; company UUID;
  allocations JSONB:='{}'; source_allocations JSONB; m RECORD; weights NUMERIC[]; months TEXT[]; denominator NUMERIC; cumulative NUMERIC; allocated NUMERIC; next_amount NUMERIC; idx INT;
  income_keys TEXT[]:=ARRAY['base_salary','position_allowance','overtime_pay','other_income'];
  keys TEXT[]:=ARRAY['base_salary','position_allowance','overtime_pay','other_income','personal_tax','social_security','ewf','savings','student_loan','company_loan','leave_deduction','other_deduction'];
BEGIN
  IF NOT public.hr_payroll_role_allowed() OR NULLIF(trim(p_reason),'') IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'ไม่มีสิทธิ์หรือยังไม่ระบุเหตุผลปรับปรุง'; END IF;
  IF jsonb_typeof(p_corrected) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ข้อมูลยอดที่ถูกต้องไม่ครบ'; END IF;
  SELECT r.company_id INTO company FROM public.hr_payroll_items i JOIN public.hr_payroll_runs r ON r.id=i.payroll_run_id WHERE i.id=p_source;
  PERFORM pg_advisory_xact_lock(hashtextextended(company::text || ':payroll',0));
  SELECT * INTO existing FROM public.hr_payroll_adjustments WHERE request_key=p_request;
  IF FOUND THEN
    IF existing.source_item_id<>p_source OR existing.corrected_amounts<>p_corrected OR existing.reason<>trim(p_reason) THEN RAISE EXCEPTION 'รหัสคำขอถูกใช้กับข้อมูลอื่น'; END IF;
    RETURN existing;
  END IF;
  SELECT i.*,r.company_id,r.payroll_month INTO source FROM public.hr_payroll_items i JOIN public.hr_payroll_runs r ON r.id=i.payroll_run_id WHERE i.id=p_source FOR UPDATE OF i;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.hr_payroll_payments WHERE payroll_item_id=p_source) THEN RAISE EXCEPTION 'ปรับส่วนต่างได้เฉพาะรายการที่บันทึกจ่ายจริงแล้ว'; END IF;
  IF EXISTS(SELECT 1 FROM public.hr_payroll_adjustments a WHERE a.source_item_id=p_source AND a.status='approved' AND NOT EXISTS(SELECT 1 FROM public.hr_payroll_payments p WHERE p.adjustment_id=a.id)) THEN RAISE EXCEPTION 'มีรายการปรับปรุงรอจ่ายอยู่ กรุณาจ่ายหรือยกเลิกรายการนั้นก่อน'; END IF;
  previous:=to_jsonb(source);
  FOREACH field IN ARRAY keys LOOP
    IF p_corrected->>field IS NULL OR p_corrected->>field IN ('NaN','Infinity','-Infinity') OR (p_corrected->>field)::numeric<0 THEN RAISE EXCEPTION 'ยอดที่ถูกต้องของ % ไม่ครบหรือเป็นค่าติดลบ',field; END IF;
    SELECT COALESCE(sum((a.deltas->>field)::numeric),0) INTO current_amount FROM public.hr_payroll_adjustments a WHERE a.source_item_id=p_source AND a.status='approved';
    current_amount:=COALESCE((to_jsonb(source)->>field)::numeric,0)+current_amount;
    IF p_expected_previous IS NOT NULL AND current_amount IS DISTINCT FROM (p_expected_previous->>field)::numeric THEN RAISE EXCEPTION 'มีผู้ใช้อื่นปรับยอดแล้ว กรุณาโหลดข้อมูลล่าสุด'; END IF;
    target:=round((p_corrected->>field)::numeric,2);
    previous:=previous||jsonb_build_object(field,current_amount);
    deltas:=deltas||jsonb_build_object(field,round(target-current_amount,2));
    IF field=ANY(income_keys) THEN income:=income+target-current_amount; ELSE deduction:=deduction+target-current_amount; END IF;
  END LOOP;
  IF NOT EXISTS(SELECT 1 FROM jsonb_each_text(deltas) WHERE value::numeric<>0) THEN RAISE EXCEPTION 'ยอดนี้ได้รับการปรับปรุงแล้ว ไม่มีส่วนต่างใหม่'; END IF;
  SELECT jsonb_object_agg(to_char(earning_month,'YYYY-MM'),amounts) INTO source_allocations FROM public.hr_payroll_monthly_allocations WHERE payroll_item_id=p_source;
  source_allocations:=COALESCE(source_allocations,jsonb_build_object(to_char(source.payroll_month,'YYYY-MM'),to_jsonb(source)));
  SELECT array_agg(key ORDER BY key) INTO months FROM jsonb_each(source_allocations);
  FOREACH field IN ARRAY keys LOOP
    SELECT array_agg(abs(COALESCE((value->>field)::numeric,0)) ORDER BY key),sum(abs(COALESCE((value->>field)::numeric,0))) INTO weights,denominator FROM jsonb_each(source_allocations);
    IF denominator=0 THEN
      SELECT array_agg(GREATEST(1,(SELECT count(*) FROM public.hr_payroll_wage_reservations w WHERE w.payroll_item_id=p_source AND to_char(w.work_date,'YYYY-MM')=key))::numeric ORDER BY key) INTO weights FROM jsonb_each(source_allocations);
      SELECT sum(weight) INTO denominator FROM unnest(weights) weight;
    END IF;
    cumulative:=0; allocated:=0;
    FOR idx IN 1..cardinality(months) LOOP
      cumulative:=cumulative+weights[idx]; next_amount:=round((deltas->>field)::numeric*cumulative/denominator,2);
      allocations:=jsonb_set(allocations,ARRAY[months[idx]],COALESCE(allocations->months[idx],'{}')||jsonb_build_object(field,next_amount-allocated),true);
      allocated:=next_amount;
    END LOOP;
  END LOOP;
  INSERT INTO public.hr_payroll_adjustments(request_key,source_item_id,company_id,employee_id,earning_month,reason,previous_amounts,corrected_amounts,deltas,deduction_allocations,income_delta,deduction_delta,net_delta,created_by)
    VALUES(p_request,p_source,company,source.employee_id,source.payroll_month,trim(p_reason),previous,p_corrected,deltas,allocations,round(income,2),round(deduction,2),round(income-deduction,2),auth.uid()) RETURNING * INTO existing;
  RETURN existing;
END $$;


--
-- Name: hr_generate_task_due_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_generate_task_due_notifications() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count INT;
BEGIN
  INSERT INTO hr_notifications(employee_id, type, title, message, link, related_id)
  SELECT p.employee_id,
    CASE WHEN t.due_at < now() THEN 'task_overdue' ELSE 'task_due_soon' END,
    CASE WHEN t.due_at < now() THEN 'งานเลยกำหนด' ELSE 'งานใกล้ถึงกำหนด' END,
    t.title, '/employee?tab=tasks', t.id
  FROM hr_tasks t JOIN hr_task_participants p ON p.task_id = t.id AND p.role = 'assignee'
  WHERE t.status IN ('new','acknowledged','in_progress','revision')
    AND t.due_at <= now() + interval '1 day'
    AND NOT EXISTS (
      SELECT 1 FROM hr_notifications n WHERE n.employee_id = p.employee_id AND n.related_id = t.id
        AND n.type = CASE WHEN t.due_at < now() THEN 'task_overdue' ELSE 'task_due_soon' END
        AND n.created_at::date = CURRENT_DATE
    );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: hr_guard_paid_payroll(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_guard_paid_payroll() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND OLD.status='confirmed' AND NEW.status='draft' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(OLD.company_id::text || ':payroll',0));
    IF EXISTS(SELECT 1 FROM public.hr_payroll_payments p JOIN public.hr_payroll_items i ON i.id=p.payroll_item_id WHERE i.payroll_run_id=OLD.id) THEN
      RAISE EXCEPTION 'มีรายการจ่ายเงินจริงแล้ว ให้สร้างรายการปรับเพิ่ม/ลดโดยอ้างอิงรายการเดิม';
    END IF;
    DELETE FROM public.hr_payroll_wage_reservations WHERE payroll_run_id=OLD.id;
    DELETE FROM public.hr_payroll_monthly_allocations WHERE payroll_run_id=OLD.id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: hr_guard_pay_schedule_definition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_guard_pay_schedule_definition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (NEW.company_id,NEW.frequency,NEW.weekday,NEW.first_day,NEW.second_day,NEW.payment_day,NEW.holiday_rule,NEW.deduction_policy,NEW.cutoff_time)
    IS DISTINCT FROM (OLD.company_id,OLD.frequency,OLD.weekday,OLD.first_day,OLD.second_day,OLD.payment_day,OLD.holiday_rule,OLD.deduction_policy,OLD.cutoff_time)
    AND EXISTS(SELECT 1 FROM public.hr_employee_pay_schedule_history WHERE schedule_id=OLD.id) THEN
    RAISE EXCEPTION 'รอบนี้มีประวัติใช้งานแล้ว ให้สร้างรอบใหม่และกำหนดวันที่เริ่มมีผลแทน';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_guard_task_checklist_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_guard_task_checklist_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status TEXT;
BEGIN
  IF OLD.is_completed IS NOT DISTINCT FROM NEW.is_completed THEN
    RETURN NEW;
  END IF;

  SELECT status::TEXT INTO v_status
  FROM hr_tasks
  WHERE id = NEW.task_id;

  IF v_status NOT IN ('in_progress', 'revision') THEN
    RAISE EXCEPTION 'ต้องเริ่มทำงานก่อนจึงจะเช็กรายการงานได้'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_guard_vacation_entitlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_guard_vacation_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_name text; v_entitled numeric; v_effective date; v_used numeric; v_year int;
BEGIN
  IF NEW.status NOT IN ('pending','approved') THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.employee_id IS NOT DISTINCT FROM OLD.employee_id
     AND NEW.leave_type_id IS NOT DISTINCT FROM OLD.leave_type_id
     AND NEW.start_date IS NOT DISTINCT FROM OLD.start_date
     AND NEW.end_date IS NOT DISTINCT FROM OLD.end_date
     AND NEW.total_days IS NOT DISTINCT FROM OLD.total_days
     AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  SELECT name,max_days_per_year INTO v_name,v_entitled FROM hr_leave_types WHERE id=NEW.leave_type_id;
  IF btrim(v_name) IS DISTINCT FROM 'ลาพักร้อน' THEN RETURN NEW; END IF;
  IF EXTRACT(YEAR FROM NEW.start_date)<>EXTRACT(YEAR FROM NEW.end_date) THEN
    RAISE EXCEPTION 'กรุณาแยกใบลาพักร้อนตามปีที่ลา';
  END IF;
  v_year:=EXTRACT(YEAR FROM NEW.start_date)::int;
  PERFORM pg_advisory_xact_lock(hashtextextended('vacation:'||NEW.employee_id::text,0));
  v_effective:=make_date(v_year,1,1);
  SELECT opening_remaining_days,effective_date INTO v_entitled,v_effective
  FROM hr_employee_opening_leave_balances
  WHERE employee_id=NEW.employee_id AND leave_type_id=NEW.leave_type_id
    AND year=v_year AND effective_date<=NEW.start_date;
  IF NOT FOUND THEN
    SELECT COALESCE(max_days_per_year,0) INTO v_entitled FROM hr_leave_types WHERE id=NEW.leave_type_id;
    v_effective:=make_date(v_year,1,1);
  END IF;
  SELECT COALESCE(sum(total_days),0) INTO v_used FROM hr_leave_requests
  WHERE employee_id=NEW.employee_id AND leave_type_id=NEW.leave_type_id
    AND status IN ('pending','approved') AND id IS DISTINCT FROM NEW.id
    AND start_date>=v_effective AND start_date<make_date(v_year+1,1,1);
  IF NEW.total_days>GREATEST(0,v_entitled-v_used) THEN
    RAISE EXCEPTION 'สิทธิ์ลาพักร้อนไม่เพียงพอ: ขอ % วัน คงเหลือที่ขอได้ % วัน (หักคำขอรออนุมัติแล้ว)',NEW.total_days,GREATEST(0,v_entitled-v_used);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_guard_wfh_decision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_guard_wfh_decision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_employee uuid;
  v_name text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'pending' OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL
       OR NEW.approved_by_user_id IS NOT NULL OR NEW.approved_by_name IS NOT NULL
       OR NEW.cancelled_by_user_id IS NOT NULL OR NEW.cancelled_by_name IS NOT NULL
       OR NEW.cancelled_at IS NOT NULL OR NEW.cancel_reason IS NOT NULL THEN
      RAISE EXCEPTION 'คำขอใหม่ต้องอยู่ในสถานะรออนุมัติ';
    END IF;
    RETURN NEW;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM us_users WHERE id = v_actor AND role IN ('superadmin', 'admin')) THEN
    RAISE EXCEPTION 'เฉพาะ superadmin และ admin เท่านั้นที่อนุมัติหรือยกเลิก WFH ได้';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['status','approved_by','approved_at','approved_by_user_id','approved_by_name',
      'reject_reason','cancelled_by_user_id','cancelled_by_name','cancelled_at','cancel_reason','updated_at'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['status','approved_by','approved_at','approved_by_user_id','approved_by_name',
      'reject_reason','cancelled_by_user_id','cancelled_by_name','cancelled_at','cancel_reason','updated_at']) THEN
    RAISE EXCEPTION 'ไม่สามารถแก้ไขรายละเอียดคำขอเดิม กรุณายกเลิกและส่งคำขอใหม่';
  END IF;
  SELECT e.id, COALESCE(NULLIF(trim(concat_ws(' ', e.first_name, e.last_name)), ''), u.username, v_actor::text)
    INTO v_employee, v_name FROM us_users u
    LEFT JOIN hr_employees e ON e.user_id = u.id
    WHERE u.id = v_actor LIMIT 1;

  IF OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected') THEN
    IF NEW.status = 'rejected' AND NULLIF(trim(NEW.reject_reason), '') IS NULL THEN
      RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ไม่อนุมัติ';
    END IF;
    NEW.approved_by := v_employee;
    NEW.approved_at := now();
    NEW.approved_by_user_id := v_actor;
    NEW.approved_by_name := v_name;
    NEW.reject_reason := CASE WHEN NEW.status = 'rejected' THEN trim(NEW.reject_reason) ELSE NULL END;
    NEW.cancelled_by_user_id := NULL;
    NEW.cancelled_by_name := NULL;
    NEW.cancelled_at := NULL;
    NEW.cancel_reason := NULL;
  ELSIF OLD.status = 'approved' AND NEW.status = 'cancelled' THEN
    IF OLD.start_date <= (now() AT TIME ZONE 'Asia/Bangkok')::date THEN
      RAISE EXCEPTION 'ยกเลิกได้เฉพาะคำขอที่ยังไม่ถึงวันเริ่มต้น';
    END IF;
    IF EXISTS (SELECT 1 FROM hr_time_entries WHERE employee_id = OLD.employee_id
      AND (wfh_request_id = OLD.id OR work_date BETWEEN OLD.start_date AND OLD.end_date)) THEN
      RAISE EXCEPTION 'ไม่สามารถยกเลิกได้ เนื่องจากมีการบันทึกเวลาทำงานแล้ว';
    END IF;
    IF NULLIF(trim(NEW.cancel_reason), '') IS NULL THEN
      RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ยกเลิก';
    END IF;
    NEW.approved_by := OLD.approved_by;
    NEW.approved_at := OLD.approved_at;
    NEW.approved_by_user_id := OLD.approved_by_user_id;
    NEW.approved_by_name := OLD.approved_by_name;
    NEW.reject_reason := OLD.reject_reason;
    NEW.cancelled_by_user_id := v_actor;
    NEW.cancelled_by_name := v_name;
    NEW.cancelled_at := now();
    NEW.cancel_reason := trim(NEW.cancel_reason);
  ELSE
    RAISE EXCEPTION 'สถานะคำขอเปลี่ยนแล้ว หรือไม่สามารถดำเนินการจากสถานะนี้ได้';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_interview_preserve_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_interview_preserve_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.interview_date IS DISTINCT FROM NEW.interview_date OR OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.appointment_history := OLD.appointment_history || jsonb_build_array(jsonb_build_object(
      'date', OLD.interview_date, 'status', OLD.status,
      'reason', coalesce(NEW.notes, ''), 'changed_at', now()
    ));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.us_users
    WHERE id = auth.uid()
      AND role IN ('superadmin', 'admin', 'hr', 'account')
  );
$$;


--
-- Name: hr_is_superadmin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_is_superadmin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM us_users WHERE id = auth.uid() AND role = 'superadmin'
  );
$$;


--
-- Name: hr_late_accumulation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_accumulation() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ดูยอดมาสาย'; END IF;
  RETURN hr_late_summary_internal();
END; $$;


--
-- Name: hr_late_attendance_facts(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_attendance_facts(p_from date, p_to date, p_employee uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, employee_code text, employee_name text, department_id uuid, work_date date, day_type text, work_mode text, is_remote_day boolean, expected_start_min integer, expected_end_min integer, grace_min integer, actual_in_min integer, actual_in_source text, actual_in_ref uuid, actual_out_min integer, actual_out_source text, actual_out_ref uuid, ot_in_min integer, ot_in_ref uuid, ot_request_id uuid, ot_request_status text, ot_request_created_date date, ot_request_created_min integer, leave_id uuid, leave_status text, leave_mode text, leave_type_name text, leave_start_date date, leave_filed_date date, leave_filed_min integer, leave_start_min integer, leave_end_min integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Private helper: revoked from PUBLIC/authenticated. Public RPCs and the
  -- warning trigger authorize the actor, including employee acknowledgement.

  IF p_to < p_from THEN
    RAISE EXCEPTION 'ช่วงวันที่ไม่ถูกต้อง';
  END IF;

  RETURN QUERY
  WITH default_schedule AS (
    SELECT s.work_start, s.work_end, s.late_grace_min, s.work_days
    FROM hr_work_schedules s
    WHERE s.is_active
    ORDER BY s.is_default DESC, s.created_at
    LIMIT 1
  ),
  emp AS (
    SELECT
      e.id,
      e.employee_code,
      TRIM(e.first_name || ' ' || e.last_name) AS full_name,
      e.department_id,
      e.hire_date,
      e.work_mode,
      COALESCE(es.work_start, ds.work_start, TIME '08:00') AS work_start,
      COALESCE(es.work_end, ds.work_end, TIME '17:00') AS work_end,
      COALESCE(es.late_grace_min, ds.late_grace_min, 0) AS late_grace_min,
      COALESCE(es.work_days, ds.work_days, '1,2,3,4,5,6') AS work_days
    FROM hr_employees e
    LEFT JOIN hr_work_schedules es ON es.id = e.work_schedule_id AND es.is_active
    LEFT JOIN default_schedule ds ON true
    WHERE e.employment_status IN ('active', 'probation')
      AND (p_employee IS NULL OR e.id = p_employee)
  ),
  days AS (
    SELECT gs::DATE AS d FROM generate_series(p_from, p_to, INTERVAL '1 day') gs
  ),
  base AS (
    SELECT emp.*, days.d
    FROM emp
    CROSS JOIN days
    WHERE emp.hire_date IS NULL OR days.d >= emp.hire_date
  )
  SELECT
    b.id,
    b.employee_code,
    b.full_name,
    b.department_id,
    b.d,
    CASE
      WHEN cal.id IS NOT NULL THEN cal.day_type
      WHEN hol.id IS NOT NULL THEN 'company_holiday'
      WHEN EXTRACT(ISODOW FROM b.d)::TEXT = ANY (string_to_array(b.work_days, ',')) THEN 'work'
      ELSE 'weekly_off'
    END AS day_type,
    b.work_mode,
    (b.work_mode = 'wfh' OR wfh.id IS NOT NULL) AS is_remote_day,
    (EXTRACT(HOUR FROM eff_start) * 60 + EXTRACT(MINUTE FROM eff_start))::INT AS expected_start_min,
    (EXTRACT(HOUR FROM eff_end) * 60 + EXTRACT(MINUTE FROM eff_end))::INT AS expected_end_min,
    COALESCE(cal_sched.late_grace_min, b.late_grace_min)::INT AS grace_min,

    COALESCE(tin.min_of_day, cin.min_of_day)::INT AS actual_in_min,
    CASE WHEN tin.id IS NOT NULL THEN 'entry' WHEN cin.id IS NOT NULL THEN 'certified' END AS actual_in_source,
    COALESCE(tin.id, cin.id) AS actual_in_ref,

    COALESCE(tout.min_of_day, cout.min_of_day)::INT AS actual_out_min,
    CASE WHEN tout.id IS NOT NULL THEN 'entry' WHEN cout.id IS NOT NULL THEN 'certified' END AS actual_out_source,
    COALESCE(tout.id, cout.id) AS actual_out_ref,

    otin.min_of_day::INT AS ot_in_min,
    otin.id AS ot_in_ref,
    otr.id AS ot_request_id,
    otr.status AS ot_request_status,
    (otr.created_at AT TIME ZONE 'Asia/Bangkok')::DATE AS ot_request_created_date,
    (EXTRACT(HOUR FROM otr.created_at AT TIME ZONE 'Asia/Bangkok') * 60
      + EXTRACT(MINUTE FROM otr.created_at AT TIME ZONE 'Asia/Bangkok'))::INT AS ot_request_created_min,

    lv.id AS leave_id,
    lv.status AS leave_status,
    lv.leave_mode,
    lv.type_name AS leave_type_name,
    lv.start_date AS leave_start_date,
    (lv.created_at AT TIME ZONE 'Asia/Bangkok')::DATE AS leave_filed_date,
    (EXTRACT(HOUR FROM lv.created_at AT TIME ZONE 'Asia/Bangkok') * 60
      + EXTRACT(MINUTE FROM lv.created_at AT TIME ZONE 'Asia/Bangkok'))::INT AS leave_filed_min,
    (EXTRACT(HOUR FROM lv.start_time) * 60 + EXTRACT(MINUTE FROM lv.start_time))::INT AS leave_start_min,
    (EXTRACT(HOUR FROM lv.end_time) * 60 + EXTRACT(MINUTE FROM lv.end_time))::INT AS leave_end_min
  FROM base b
  LEFT JOIN hr_employee_work_calendar cal ON cal.employee_id = b.id AND cal.work_date = b.d
  LEFT JOIN hr_work_schedules cal_sched ON cal_sched.id = cal.work_schedule_id
  LEFT JOIN hr_company_holidays hol ON hol.holiday_date = b.d
  -- ต้องอยู่ก่อน eff เพราะ eff อ้างช่วงเวลาของคำขอ WFH
  LEFT JOIN LATERAL (
    SELECT w.id, w.start_time, w.end_time
    FROM hr_wfh_requests w
    WHERE w.employee_id = b.id AND w.status = 'approved'
      AND w.start_date <= b.d AND w.end_date >= b.d
    ORDER BY w.approved_at DESC NULLS LAST
    LIMIT 1
  ) wfh ON true
  CROSS JOIN LATERAL (
    SELECT
      COALESCE(wfh.start_time, cal.work_start, cal_sched.work_start, b.work_start) AS eff_start,
      COALESCE(wfh.end_time, cal.work_end, cal_sched.work_end, b.work_end) AS eff_end
  ) eff
  LEFT JOIN LATERAL (
    SELECT te.id, EXTRACT(EPOCH FROM ((te.entry_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_entries te
    WHERE te.employee_id = b.id AND te.work_date = b.d AND te.entry_type = 'clock_in'
    ORDER BY te.entry_time
    LIMIT 1
  ) tin ON true
  LEFT JOIN LATERAL (
    SELECT te.id, EXTRACT(EPOCH FROM ((te.entry_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_entries te
    WHERE te.employee_id = b.id AND te.work_date = b.d AND te.entry_type = 'clock_out'
    ORDER BY te.entry_time DESC
    LIMIT 1
  ) tout ON true
  LEFT JOIN LATERAL (
    SELECT te.id, EXTRACT(EPOCH FROM ((te.entry_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_entries te
    WHERE te.employee_id = b.id AND te.work_date = b.d AND te.entry_type = 'ot_in'
    ORDER BY te.entry_time
    LIMIT 1
  ) otin ON true
  LEFT JOIN LATERAL (
    SELECT tc.id, EXTRACT(EPOCH FROM ((tc.certified_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_certifications tc
    WHERE tc.employee_id = b.id AND tc.work_date = b.d AND tc.entry_type = 'clock_in'
  ) cin ON true
  LEFT JOIN LATERAL (
    SELECT tc.id, EXTRACT(EPOCH FROM ((tc.certified_time AT TIME ZONE 'Asia/Bangkok') - b.d::TIMESTAMP)) / 60 AS min_of_day
    FROM hr_time_certifications tc
    WHERE tc.employee_id = b.id AND tc.work_date = b.d AND tc.entry_type = 'clock_out'
  ) cout ON true
  LEFT JOIN LATERAL (
    SELECT lr.id, lr.status, lr.leave_mode, lr.start_date, lr.created_at,
           lr.start_time, lr.end_time, lt.name AS type_name
    FROM hr_leave_requests lr
    LEFT JOIN hr_leave_types lt ON lt.id = lr.leave_type_id
    WHERE lr.employee_id = b.id
      AND lr.start_date <= b.d AND lr.end_date >= b.d
      AND lr.status IN ('approved', 'pending')
    ORDER BY CASE lr.status WHEN 'approved' THEN 0 ELSE 1 END, lr.created_at
    LIMIT 1
  ) lv ON true
  LEFT JOIN LATERAL (
    SELECT r.id, r.status, r.created_at
    FROM hr_ot_requests r
    WHERE r.employee_id = b.id AND r.request_date = b.d
      AND r.status IN ('approved', 'pending', 'rejected')
    ORDER BY CASE r.status WHEN 'approved' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END, r.created_at
    LIMIT 1
  ) otr ON true
  WHERE cal.day_type = 'work'
     OR (cal.id IS NULL AND hol.id IS NULL
         AND EXTRACT(ISODOW FROM b.d)::TEXT = ANY (string_to_array(b.work_days, ',')))
     OR tin.id IS NOT NULL OR tout.id IS NOT NULL OR otin.id IS NOT NULL
     OR cin.id IS NOT NULL OR cout.id IS NOT NULL
  ORDER BY b.full_name, b.d;
END;
$$;


--
-- Name: hr_late_create_warning(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_create_warning(p_employee uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE summary JSONB; row_data JSONB; incident_day DATE; offense UUID; warning_id UUID; description TEXT;
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างใบเตือน'; END IF;
  -- Same lock as settings changes and exception decisions; concurrent clicks cannot create duplicate drafts.
  PERFORM singleton FROM hr_late_settings WHERE singleton FOR UPDATE;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_employee::TEXT,653));
  summary := hr_late_summary_internal();
  SELECT x INTO row_data FROM jsonb_array_elements(summary->'rows') x WHERE x->>'employee_id'=p_employee::TEXT;
  IF row_data IS NULL OR NOT (row_data->>'eligible')::BOOLEAN THEN RAISE EXCEPTION 'ยังไม่ถึงเกณฑ์ หรือมีเคส/ลาฉุกเฉินรอดำเนินการ กรุณารีเฟรช'; END IF;
  -- Conservative validity: no event in this warning is older than its one-year validity base.
  SELECT min((x->>'work_date')::DATE),string_agg((x->>'work_date')||' เริ่ม '||
      to_char(make_interval(mins=>(x->>'expected_min')::INT),'HH24:MI')||' เข้า '||
      to_char(make_interval(mins=>(x->>'actual_min')::INT),'HH24:MI')||' สาย '||(x->>'late_min')||' นาที',E'\n' ORDER BY x->>'work_date')
    INTO incident_day,description FROM jsonb_array_elements(row_data->'incidents') x;
  SELECT id INTO offense FROM hr_warning_offense_types WHERE code='late';
  IF offense IS NULL THEN RAISE EXCEPTION 'ไม่พบประเภทความผิดมาสาย'; END IF;
  INSERT INTO hr_warnings(employee_id,offense_type_id,warning_level,recommended_level,subject,description,corrective_action,
    incident_date,effective_until,status,created_by_user,issued_by,late_generated,late_start_date,late_incidents_snapshot)
  VALUES(p_employee,offense,row_data->>'next_level',row_data->>'next_level','การมาสายสะสม',
    'สะสม '||(row_data->>'late_count')||' ครั้ง รวม '||(row_data->>'late_minutes')||E' นาที\n'||description,
    'ให้มาปฏิบัติงานตรงตามเวลาเริ่มงานและปฏิบัติตามหลักเกณฑ์การมาทำงานสายของบริษัท',
    incident_day,(incident_day+INTERVAL '1 year')::DATE,'draft',auth.uid(),hr_my_employee_id(),true,
    (summary->>'start_date')::DATE,row_data->'incidents') RETURNING id INTO warning_id;
  RETURN warning_id;
END; $$;


--
-- Name: hr_late_events_internal(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_events_internal(p_start date, p_today date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE f RECORD; lv RECORD; ex RECORD; expected INT; actual INT; delay INT;
  approved_full BOOLEAN; approved_at_arrival BOOLEAN; waiting BOOLEAN; occurred TIMESTAMPTZ;
  event_status TEXT; event_reason TEXT; result JSONB := '[]';
BEGIN
  IF p_start>p_today THEN RETURN result; END IF;
  FOR f IN SELECT * FROM hr_late_attendance_facts(p_start,p_today,NULL) LOOP
    IF f.day_type<>'work' OR f.actual_in_min IS NULL THEN CONTINUE; END IF;
    -- Floor seconds, do not round 08:35:31 up to 08:36.
    SELECT CASE WHEN f.actual_in_source='entry' THEN
      (SELECT entry_time FROM hr_time_entries WHERE id=f.actual_in_ref)
      ELSE (SELECT certified_time FROM hr_time_certifications WHERE id=f.actual_in_ref) END INTO occurred;
    actual := floor(extract(epoch FROM ((occurred AT TIME ZONE 'Asia/Bangkok')-f.work_date::TIMESTAMP))/60)::INT;
    expected := f.expected_start_min;
    IF actual-expected<=5 THEN CONTINUE; END IF;
    approved_full := false; approved_at_arrival := false; waiting := false;
    FOR lv IN SELECT r.* FROM hr_leave_requests r
      WHERE r.employee_id=f.employee_id AND r.start_date<=f.work_date AND r.end_date>=f.work_date
        AND r.status='approved' ORDER BY r.start_time NULLS FIRST LOOP
      IF lv.leave_mode IS DISTINCT FROM 'hourly' THEN approved_full := true;
      ELSIF lv.start_time IS NOT NULL AND lv.end_time IS NOT NULL THEN
        IF actual >= extract(epoch FROM lv.start_time)/60 AND actual <= extract(epoch FROM lv.end_time)/60 THEN
          approved_at_arrival := true;
        END IF;
        IF extract(epoch FROM lv.start_time)/60<=expected AND extract(epoch FROM lv.end_time)/60>expected THEN
          expected := (extract(epoch FROM lv.end_time)/60)::INT;
        END IF;
      END IF;
    END LOOP;
    SELECT EXISTS(SELECT 1 FROM hr_leave_requests r WHERE r.employee_id=f.employee_id
      AND r.start_date<=f.work_date AND r.end_date>=f.work_date AND r.status='pending' AND r.is_emergency
      AND (r.leave_mode IS DISTINCT FROM 'hourly' OR
        (extract(epoch FROM r.start_time)/60<=actual AND extract(epoch FROM r.end_time)/60>=f.expected_start_min))) INTO waiting;
    SELECT * INTO ex FROM hr_late_exceptions WHERE employee_id=f.employee_id AND work_date=f.work_date;
    delay := greatest(actual-expected,0);
    IF approved_full OR approved_at_arrival OR delay<=5 OR COALESCE(ex.exempt,false) THEN
      event_status := 'exempt';
      event_reason := CASE WHEN COALESCE(ex.exempt,false) THEN ex.reason ELSE 'ช่วงลาที่อนุมัติ / เข้างานภายในเวลาหลังลา' END;
    ELSIF waiting THEN event_status := 'pending'; event_reason := 'รอพิจารณาลากิจฉุกเฉิน';
    ELSE event_status := 'included'; event_reason := ex.reason; END IF;
    result := result || jsonb_build_array(jsonb_build_object('employee_id',f.employee_id,'work_date',f.work_date,
      'occurred_at',occurred,'expected_min',expected,'actual_min',actual,'late_min',delay,'status',event_status,'reason',event_reason));
  END LOOP;
  RETURN result;
END; $$;


--
-- Name: hr_late_ready_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_ready_count() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ดูยอดมาสาย'; END IF;
  RETURN (hr_late_summary_internal()->>'ready_count')::INT;
END; $$;


--
-- Name: hr_late_review_warning(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_review_warning(p_warning uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE w hr_warnings; summary JSONB; row_data JSONB;
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ทบทวนเคส'; END IF;
  SELECT * INTO w FROM hr_warnings WHERE id=p_warning FOR UPDATE;
  IF NOT FOUND OR NOT w.late_generated OR w.status NOT IN ('draft','changes_requested','pending_review','pending_approval') THEN
    RAISE EXCEPTION 'ทบทวนได้เฉพาะเคสก่อนอนุมัติ หากอนุมัติแล้วให้ยกเลิกหรือเพิกถอน';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(w.employee_id::TEXT,653));
  summary := hr_late_summary_internal();
  SELECT x INTO row_data FROM jsonb_array_elements(summary->'rows') x WHERE x->>'employee_id'=w.employee_id::TEXT;
  IF row_data IS NULL OR (row_data->>'pending_emergency_count')::INT>0
    OR ((row_data->>'late_count')::INT<3 AND (row_data->>'late_minutes')::INT<120)
    OR w.warning_level IS DISTINCT FROM row_data->>'next_level' THEN
    RAISE EXCEPTION 'ยอดหรือขั้นไม่ตรงเกณฑ์ กรุณายกเลิกเคสและพิจารณาใหม่';
  END IF;
  UPDATE hr_warnings SET status='changes_requested',late_incidents_snapshot=row_data->'incidents',reviewed_at=NULL,reviewer_id=NULL
    WHERE id=p_warning;
  INSERT INTO hr_late_audit(action,actor,old_data,new_data) VALUES('review_case',auth.uid(),to_jsonb(w),
    jsonb_build_object('warning_id',p_warning,'incidents',row_data->'incidents'));
END; $$;


--
-- Name: hr_late_set_exception(uuid, date, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_set_exception(p_employee uuid, p_date date, p_exempt boolean, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE old_row hr_late_exceptions;
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์พิจารณาข้อยกเว้น'; END IF;
  IF NULLIF(btrim(p_reason),'') IS NULL OR p_exempt IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผล'; END IF;
  IF p_date IS NULL OR p_date<(SELECT start_date FROM hr_late_settings WHERE singleton)
    OR p_date>(now() AT TIME ZONE 'Asia/Bangkok')::DATE THEN RAISE EXCEPTION 'วันที่เหตุไม่ถูกต้อง'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_employee::TEXT,653));
  SELECT * INTO old_row FROM hr_late_exceptions WHERE employee_id=p_employee AND work_date=p_date;
  INSERT INTO hr_late_exceptions(employee_id,work_date,exempt,reason,decided_by)
    VALUES(p_employee,p_date,p_exempt,btrim(p_reason),auth.uid()) ON CONFLICT(employee_id,work_date)
    DO UPDATE SET exempt=excluded.exempt,reason=excluded.reason,decided_by=excluded.decided_by,decided_at=now();
  INSERT INTO hr_late_audit(action,actor,old_data,new_data) VALUES('exception',auth.uid(),to_jsonb(old_row),
    jsonb_build_object('employee_id',p_employee,'work_date',p_date,'exempt',p_exempt,'reason',btrim(p_reason)));
END; $$;


--
-- Name: hr_late_set_start_date(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_set_start_date(p_start date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE old_row hr_late_settings;
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ตั้งค่า'; END IF;
  IF p_start IS NULL OR p_start<DATE '2000-01-01' OR p_start>DATE '2100-12-31' THEN RAISE EXCEPTION 'วันที่ไม่ถูกต้อง'; END IF;
  SELECT * INTO old_row FROM hr_late_settings WHERE singleton FOR UPDATE;
  IF EXISTS(SELECT 1 FROM hr_warnings WHERE late_generated) THEN RAISE EXCEPTION 'ไม่สามารถเปลี่ยนวันเริ่มหลังสร้างเคสได้'; END IF;
  UPDATE hr_late_settings SET start_date=p_start,updated_at=now(),updated_by=auth.uid() WHERE singleton;
  INSERT INTO hr_late_audit(action,actor,old_data,new_data) VALUES('set_start_date',auth.uid(),to_jsonb(old_row),jsonb_build_object('start_date',p_start));
END; $$;


--
-- Name: hr_late_summary_internal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_summary_internal() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE start_day DATE; today DATE := (now() AT TIME ZONE 'Asia/Bangkok')::DATE; result JSONB;
BEGIN
  SELECT start_date INTO start_day FROM hr_late_settings WHERE singleton;
  WITH events AS MATERIALIZED (
    SELECT x.* FROM jsonb_to_recordset(hr_late_events_internal(start_day,today)) AS x(
      employee_id UUID, work_date DATE, occurred_at TIMESTAMPTZ, expected_min INT,
      actual_min INT, late_min INT, status TEXT, reason TEXT)
  ), employees AS (
    SELECT e.id, e.employee_code, trim(e.first_name||' '||e.last_name) employee_name, d.name department_name
    FROM hr_employees e LEFT JOIN hr_departments d ON d.id=e.department_id
    WHERE e.employment_status IN ('active','probation') AND
      (EXISTS(SELECT 1 FROM events WHERE employee_id=e.id) OR EXISTS(SELECT 1 FROM hr_warnings WHERE employee_id=e.id AND late_generated))
  ), base AS (
    SELECT e.*, w.warning_level,
      (w.incident_date+INTERVAL '1 year')::DATE expires_on,
      CASE WHEN (w.incident_date+INTERVAL '1 year')::DATE<=today
        THEN (w.incident_date+INTERVAL '1 year')::TIMESTAMP AT TIME ZONE 'Asia/Bangkok'
        ELSE COALESCE(w.acknowledged_at,w.approved_at) END cutoff,
      p.id pending_warning_id, p.case_number pending_case_number, p.status pending_status,
      COALESCE(p.late_incidents_snapshot,CASE WHEN (w.incident_date+INTERVAL '1 year')::DATE>today THEN w.late_incidents_snapshot END) snapshot,
      (SELECT max(work_date) FROM events WHERE employee_id=e.id AND status<>'exempt' AND late_min>5) last_late_date
    FROM employees e
    LEFT JOIN LATERAL (
      SELECT * FROM hr_warnings WHERE employee_id=e.id AND late_generated AND status<>'cancelled'
        AND (acknowledged_at IS NOT NULL OR (warning_level='termination_review' AND approved_at IS NOT NULL))
      ORDER BY COALESCE(approved_at,acknowledged_at,created_at) DESC,id DESC LIMIT 1
    ) w ON true
    LEFT JOIN LATERAL (
      SELECT * FROM hr_warnings WHERE employee_id=e.id AND late_generated
        AND status IN ('draft','pending_review','changes_requested','pending_approval','approved','pending_acknowledgement','termination_review')
      ORDER BY created_at DESC,id DESC LIMIT 1
    ) p ON true
  ), ordered AS (
    SELECT x.*,lag(x.work_date) OVER(PARTITION BY x.employee_id ORDER BY x.work_date) previous_date
    FROM events x JOIN base b ON b.id=x.employee_id
    WHERE x.status<>'exempt' AND x.late_min>5 AND (b.cutoff IS NULL OR x.occurred_at>b.cutoff)
  ), rounds AS (
    SELECT x.*,sum(CASE WHEN previous_date IS NULL OR work_date-previous_date>=120 THEN 1 ELSE 0 END)
      OVER(PARTITION BY employee_id ORDER BY work_date) round_number FROM ordered x
  ), current_events AS (
    SELECT x.* FROM rounds x WHERE round_number=(SELECT max(y.round_number) FROM rounds y WHERE y.employee_id=x.employee_id)
      AND today-(SELECT max(y.work_date) FROM rounds y WHERE y.employee_id=x.employee_id)<120
  ), totals AS (
    SELECT b.*,
      CASE WHEN expires_on>today THEN warning_level END current_level,
      greatest(COALESCE(today-last_late_date,0),0) clean_days,
      (SELECT count(*) FROM current_events WHERE employee_id=b.id AND status='included')::INT late_count,
      COALESCE((SELECT sum(late_min) FROM current_events WHERE employee_id=b.id AND status='included'),0)::INT late_minutes,
      (SELECT count(*) FROM current_events WHERE employee_id=b.id AND status='pending')::INT pending_emergency_count,
      COALESCE((SELECT jsonb_agg(to_jsonb(x)-'previous_date'-'round_number' ORDER BY work_date) FROM current_events x WHERE employee_id=b.id AND status='included'),'[]') incidents,
      COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY work_date DESC) FROM events x WHERE employee_id=b.id),'[]') history,
      EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(b.snapshot,'[]')) s
        WHERE NOT EXISTS(SELECT 1 FROM events x WHERE x.employee_id=b.id AND x.work_date=(s->>'work_date')::DATE
          AND x.status='included' AND x.expected_min=(s->>'expected_min')::INT
          AND x.actual_min=(s->>'actual_min')::INT AND x.late_min=(s->>'late_min')::INT)) review_required
    FROM base b
  ), rows AS (
    SELECT employee_id,employee_code,employee_name,department_name,late_count,late_minutes,last_late_date,clean_days,
      current_level,CASE WHEN current_level IS NOT NULL THEN expires_on END effective_until,
      CASE current_level WHEN 'verbal' THEN 'written_1' WHEN 'written_1' THEN 'final'
        WHEN 'final' THEN 'termination_review' WHEN 'termination_review' THEN 'termination_review' ELSE 'verbal' END next_level,
      pending_warning_id,pending_case_number,pending_status,pending_emergency_count,review_required,incidents,history,
      ((late_count>=3 OR late_minutes>=120) AND pending_warning_id IS NULL AND pending_emergency_count=0
        AND COALESCE(current_level,'')<>'termination_review') eligible
    FROM (SELECT id employee_id,totals.* FROM totals) t
  ) SELECT jsonb_build_object('start_date',start_day,
      'settings_locked',EXISTS(SELECT 1 FROM hr_warnings WHERE late_generated),
      'ready_count',(SELECT count(*) FROM rows WHERE eligible),
      'rows',COALESCE((SELECT jsonb_agg(to_jsonb(rows) ORDER BY eligible DESC,employee_code) FROM rows),'[]')) INTO result;
  RETURN result;
END; $$;


--
-- Name: hr_late_warning_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_late_warning_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE summary JSONB; row_data JSONB; base_day DATE; evidence JSONB; evidence_count INT; evidence_minutes INT;
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.late_generated THEN RAISE EXCEPTION 'กรุณายกเลิกเคสแทนการลบ เพื่อรักษาประวัติ'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND OLD.late_generated AND NOT NEW.late_generated THEN RAISE EXCEPTION 'ไม่สามารถยกเลิกการเชื่อมยอดมาสายได้'; END IF;
  IF TG_OP='UPDATE' AND NOT OLD.late_generated AND NEW.late_generated THEN RAISE EXCEPTION 'กรุณาสร้างเคสผ่านหน้าสะสมการมาสาย'; END IF;
  IF NOT NEW.late_generated THEN RETURN NEW; END IF;
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN
    IF TG_OP<>'UPDATE' OR OLD.employee_id IS DISTINCT FROM hr_my_employee_id()
      OR OLD.status<>'pending_acknowledgement' OR NEW.status NOT IN ('acknowledged','acknowledgement_refused') THEN
      RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขเคสสะสมการมาสาย';
    END IF;
    IF (to_jsonb(NEW)-ARRAY['status','acknowledged_at','employee_response','updated_at']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['status','acknowledged_at','employee_response','updated_at']) THEN
      RAISE EXCEPTION 'พนักงานบันทึกได้เฉพาะการรับทราบและคำชี้แจง';
    END IF;
    NEW.acknowledged_at := now();
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.employee_id::TEXT,653));
  IF TG_OP='UPDATE' THEN
    IF NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.offense_type_id IS DISTINCT FROM OLD.offense_type_id
      OR NEW.warning_level IS DISTINCT FROM OLD.warning_level OR NEW.incident_date IS DISTINCT FROM OLD.incident_date
      OR NEW.late_start_date IS DISTINCT FROM OLD.late_start_date THEN
      RAISE EXCEPTION 'เคสสะสมมาสายไม่สามารถเปลี่ยนพนักงาน ขั้น หรือวันที่เหตุได้ กรุณายกเลิกและสร้างใหม่';
    END IF;
    IF NEW.status='cancelled' AND OLD.status<>'cancelled' AND NULLIF(btrim(NEW.resolution_note),'') IS NULL THEN
      RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ยกเลิกหรือเพิกถอน';
    END IF;
    IF NEW.status='cancelled' OR NEW.status='closed' OR NEW.status='changes_requested' THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN
    ('pending_review','pending_approval','pending_acknowledgement','termination_review','acknowledged','acknowledgement_refused')) THEN
    summary := hr_late_summary_internal();
    SELECT x INTO row_data FROM jsonb_array_elements(summary->'rows') x WHERE x->>'employee_id'=NEW.employee_id::TEXT;
    IF row_data IS NULL OR (row_data->>'pending_emergency_count')::INT>0 THEN
      RAISE EXCEPTION 'ยอดไม่ถึงเกณฑ์ หรือมีลาฉุกเฉินรอพิจารณา กรุณาทบทวนเคส';
    END IF;
    IF TG_OP='INSERT' AND NOT (row_data->>'eligible')::BOOLEAN THEN RAISE EXCEPTION 'มีเคสรอดำเนินการแล้ว'; END IF;
    IF (row_data->>'review_required')::BOOLEAN THEN RAISE EXCEPTION 'เวลา/ข้อยกเว้นเปลี่ยนแปลง กรุณาทบทวนยอดและส่งตรวจใหม่'; END IF;
    -- A warning expiring while this draft waits must not silently escalate the new cycle.
    IF NEW.warning_level IS DISTINCT FROM row_data->>'next_level' THEN RAISE EXCEPTION 'ขั้นเตือนเปลี่ยนแปลง กรุณายกเลิกเคสและสร้างร่างใหม่'; END IF;
    -- A 120-day counter reset does not erase the evidence of an already-created case.
    evidence := CASE WHEN TG_OP='INSERT' THEN '[]'::JSONB ELSE OLD.late_incidents_snapshot END || (row_data->'incidents');
    SELECT COALESCE(jsonb_agg(x ORDER BY x->>'work_date'),'[]') INTO evidence FROM (
      SELECT DISTINCT ON (x->>'work_date') x FROM jsonb_array_elements(evidence) WITH ORDINALITY a(x,n)
      ORDER BY x->>'work_date',n DESC
    ) unique_events;
    SELECT count(*)::INT,COALESCE(sum((x->>'late_min')::INT),0)::INT INTO evidence_count,evidence_minutes FROM jsonb_array_elements(evidence) x;
    IF evidence_count<3 AND evidence_minutes<120 THEN RAISE EXCEPTION 'ยอดไม่ถึงเกณฑ์ กรุณาทบทวนเคส'; END IF;
    IF NEW.status IN ('acknowledged','acknowledgement_refused') AND NEW.acknowledged_at IS NULL THEN
      RAISE EXCEPTION 'กรุณาบันทึกวันและเวลาที่แจ้งรับทราบ';
    END IF;
    NEW.late_incidents_snapshot := evidence;
    SELECT min((x->>'work_date')::DATE) INTO base_day FROM jsonb_array_elements(NEW.late_incidents_snapshot) x;
    IF (base_day+INTERVAL '1 year')::DATE<=(now() AT TIME ZONE 'Asia/Bangkok')::DATE THEN
      RAISE EXCEPTION 'เหตุที่ใช้เตือนเกินอายุหนึ่งปีแล้ว กรุณายกเลิกและพิจารณาใหม่';
    END IF;
    NEW.incident_date := base_day;
    NEW.effective_until := (base_day+INTERVAL '1 year')::DATE;
    NEW.description := 'สะสม '||evidence_count||' ครั้ง รวม '||evidence_minutes||E' นาที\n'||
      (SELECT string_agg((x->>'work_date')||' เริ่ม '||to_char(make_interval(mins=>(x->>'expected_min')::INT),'HH24:MI')||
        ' เข้า '||to_char(make_interval(mins=>(x->>'actual_min')::INT),'HH24:MI')||' สาย '||(x->>'late_min')||' นาที',E'\n' ORDER BY x->>'work_date')
        FROM jsonb_array_elements(NEW.late_incidents_snapshot) x);
  ELSE
    IF NEW.late_incidents_snapshot IS DISTINCT FROM OLD.late_incidents_snapshot THEN
      RAISE EXCEPTION 'ไม่สามารถแก้ไขหลักฐานสะสมโดยตรงได้ กรุณาทบทวนยอด';
    END IF;
    NEW.effective_until := (NEW.incident_date+INTERVAL '1 year')::DATE;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: hr_leave_guard_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_leave_guard_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF public.hr_can_approve_leave() THEN
      RETURN NEW;
    END IF;

    IF NEW.status = 'cancelled'
       AND OLD.status = 'pending'
       AND OLD.employee_id = public.hr_my_employee_id() THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'ไม่มีสิทธิ์เปลี่ยนสถานะใบลา (เฉพาะ superadmin/admin/hr/account เท่านั้น)';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_leave_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_leave_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    SELECT e.id, 'leave_approval_pending', 'มีใบลารออนุมัติ',
      NEW.reason, '/hr/leave', NEW.id
    FROM hr_employees e
    JOIN us_users u ON u.id = e.user_id
    WHERE u.role IN ('superadmin','admin','hr')
    LIMIT 5;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status IN ('approved','rejected') THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    VALUES (
      NEW.employee_id,
      'leave_result',
      CASE WHEN NEW.status = 'approved' THEN 'ใบลาได้รับการอนุมัติ' ELSE 'ใบลาถูกปฏิเสธ' END,
      COALESCE(NEW.reject_reason, ''),
      '/employee/leave',
      NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_medical_cert_reminder(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_medical_cert_reminder() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.status = 'approved'
     AND NEW.total_days > 1
     AND NEW.medical_cert_url IS NULL
     AND EXISTS (SELECT 1 FROM hr_leave_types WHERE id = NEW.leave_type_id AND name ILIKE '%ป่วย%')
  THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    VALUES (
      NEW.employee_id,
      'medical_cert_required',
      'กรุณาอัปโหลดใบรับรองแพทย์',
      'คุณลาป่วยเกิน 1 วัน กรุณาอัปโหลดใบรับรองแพทย์',
      '/employee/leave',
      NEW.id
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_my_employee_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_my_employee_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id FROM hr_employees WHERE user_id = auth.uid() LIMIT 1;
$$;


--
-- Name: hr_ot_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_ot_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    SELECT e.id, 'ot_approval_pending', 'มีคำขอ OT รออนุมัติ',
      NEW.reason, '/hr/leave', NEW.id
    FROM hr_employees e
    JOIN us_users u ON u.id = e.user_id
    WHERE u.role IN ('superadmin','admin')
    LIMIT 5;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status IN ('approved','rejected') THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    VALUES (
      NEW.employee_id,
      'ot_result',
      CASE WHEN NEW.status = 'approved' THEN 'คำขอ OT ได้รับการอนุมัติ' ELSE 'คำขอ OT ถูกปฏิเสธ' END,
      COALESCE(NEW.reject_reason, ''),
      '/employee',
      NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_pay_schedule_at(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_pay_schedule_at(p_employee uuid, p_date date) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((SELECT schedule_id FROM public.hr_employee_pay_schedule_history WHERE employee_id=p_employee AND effective_date<=p_date ORDER BY effective_date DESC,created_at DESC,id DESC LIMIT 1),'00000000-0000-4000-8000-000000000001'::uuid)
$$;


--
-- Name: hr_payroll_claim_dates(jsonb, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_claim_dates(p_item jsonb, p_start date, p_end date) RETURNS date[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE result DATE[];
BEGIN
  IF jsonb_typeof(p_item->'earning_dates')='array' THEN
    SELECT array_agg(DISTINCT value::date) INTO result FROM jsonb_array_elements_text(p_item->'earning_dates');
  ELSIF p_item->>'pay_type'='daily' AND jsonb_typeof(p_item->'daily_wage_details')='array' AND jsonb_array_length(p_item->'daily_wage_details')>0 THEN
    SELECT array_agg(DISTINCT (d->>'workDate')::date) INTO result FROM jsonb_array_elements(p_item->'daily_wage_details') d;
  ELSIF jsonb_typeof(p_item->'monthly_wage_details')='array' AND jsonb_array_length(p_item->'monthly_wage_details')>0 THEN
    SELECT array_agg(DISTINCT day::date) INTO result FROM jsonb_array_elements(p_item->'monthly_wage_details') d
      CROSS JOIN LATERAL generate_series((d->>'startDate')::date,(d->>'endDate')::date,interval '1 day') day;
  ELSE SELECT array_agg(day::date) INTO result FROM generate_series(p_start,p_end,interval '1 day') day;
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(result) day WHERE day<p_start OR day>p_end) THEN RAISE EXCEPTION 'วันที่ค่าจ้างอยู่นอกช่วงงวด'; END IF;
  RETURN COALESCE(result,ARRAY[]::date[]);
END;
$$;


--
-- Name: hr_payroll_confirm_no_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_confirm_no_overlap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE i RECORD; d DATE; dates DATE[]; allocation JSONB; month DATE; field TEXT; total NUMERIC; previous NUMERIC; limit_amount NUMERIC; wage NUMERIC; emp public.hr_employees; schedule public.hr_pay_schedules;
  start_date DATE:=COALESCE(NEW.period_start,NEW.payroll_month); end_date DATE:=COALESCE(NEW.period_end,(NEW.payroll_month+interval '1 month - 1 day')::date);
  money_keys TEXT[]:=ARRAY['base_salary','position_allowance','overtime_pay','other_income','personal_tax','social_security','ewf','savings','student_loan','company_loan','leave_deduction','other_deduction'];
BEGIN
  IF NEW.status<>'confirmed' OR OLD.status='confirmed' THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.company_id::text || ':payroll',0));
  SELECT * INTO schedule FROM public.hr_pay_schedules WHERE id=COALESCE(NEW.schedule_id,'00000000-0000-4000-8000-000000000001');
  IF (NEW.schedule_id IS NOT NULL OR NEW.payment_tracking_state='managed') AND (now() AT TIME ZONE 'Asia/Bangkok')<(end_date+schedule.cutoff_time) THEN RAISE EXCEPTION 'ยังไม่ถึงเวลาปิดงวดค่าจ้าง'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_payroll_items WHERE payroll_run_id=NEW.id) THEN RAISE EXCEPTION 'ไม่สามารถยืนยันงวดที่ไม่มีพนักงาน'; END IF;
  FOR i IN SELECT * FROM public.hr_payroll_items WHERE payroll_run_id=NEW.id LOOP
    IF i.reviewed_at IS NULL OR COALESCE(i.unresolved_attendance_days,0)>0 THEN RAISE EXCEPTION 'กรุณาตรวจสลิปและเวลาเข้าออกให้ครบก่อนยืนยัน'; END IF;
    dates:=public.hr_payroll_claim_dates(to_jsonb(i),start_date,end_date);
    IF cardinality(dates)=0 THEN RAISE EXCEPTION 'ไม่พบวันที่สิทธิ์ค่าจ้างของพนักงาน %',i.employee_code; END IF;
    FOREACH d IN ARRAY dates LOOP
      IF public.hr_pay_schedule_at(i.employee_id,d)<>COALESCE(NEW.schedule_id,'00000000-0000-4000-8000-000000000001') THEN RAISE EXCEPTION 'รอบจ่ายของพนักงาน % เปลี่ยนแล้ว ให้จัดทำจากเมนูรอบจ่ายและโหลดใหม่',i.employee_code; END IF;
      IF EXISTS(SELECT 1 FROM public.hr_payroll_wage_reservations WHERE company_id=NEW.company_id AND employee_id=i.employee_id AND work_date=d AND payroll_item_id<>i.id) THEN RAISE EXCEPTION 'พนักงาน % มีค่าจ้างยืนยันแล้ววันที่ % กรุณาปรับปรุงรายการเดิมเพื่อไม่ให้จ่ายซ้ำ',i.employee_code,d; END IF;
      INSERT INTO public.hr_payroll_wage_reservations VALUES(NEW.company_id,i.employee_id,d,NEW.id,i.id) ON CONFLICT DO NOTHING;
    END LOOP;
    allocation:=i.deduction_allocations;
    IF allocation IS NULL THEN allocation:=jsonb_build_object(to_char(NEW.payroll_month,'YYYY-MM'),to_jsonb(i)); END IF;
    IF jsonb_typeof(allocation)<>'object' OR NOT EXISTS(SELECT 1 FROM jsonb_each(allocation)) THEN RAISE EXCEPTION 'ไม่พบการจัดสรรยอดตามเดือน'; END IF;
    FOREACH field IN ARRAY money_keys LOOP
      SELECT COALESCE(sum(COALESCE((value->>field)::numeric,0)),0) INTO total FROM jsonb_each(allocation);
      IF round(total,2)<>round(COALESCE((to_jsonb(i)->>field)::numeric,0),2) THEN RAISE EXCEPTION 'ยอดจัดสรร % ไม่ตรงกับสลิป',field; END IF;
    END LOOP;
    FOR month,allocation IN SELECT (key||'-01')::date,value FROM jsonb_each(allocation) LOOP
      IF month<date_trunc('month',start_date)::date OR month>date_trunc('month',end_date)::date THEN RAISE EXCEPTION 'เดือนจัดสรรอยู่นอกงวด'; END IF;
      SELECT * INTO emp FROM public.hr_employees WHERE id=i.employee_id;
      IF NEW.schedule_id IS NOT NULL THEN
        IF i.social_security_enabled=false AND COALESCE((allocation->>'social_security')::numeric,0)<>0 THEN RAISE EXCEPTION 'พนักงานไม่เข้า สปส. ต้องไม่หักประกันสังคม'; END IF;
        FOREACH field IN ARRAY ARRAY['personal_tax','savings','student_loan','company_loan'] LOOP
          SELECT COALESCE(sum(COALESCE((amounts->>field)::numeric,0)),0) INTO previous FROM public.hr_payroll_effective_monthly_allocations WHERE company_id=NEW.company_id AND employee_id=i.employee_id AND earning_month=month AND payroll_item_id<>i.id;
          limit_amount:=CASE field WHEN 'personal_tax' THEN COALESCE(emp.monthly_personal_tax,0) WHEN 'savings' THEN COALESCE(emp.monthly_savings,0) WHEN 'student_loan' THEN COALESCE(emp.monthly_student_loan,0) ELSE COALESCE(emp.monthly_company_loan,0) END;
          IF COALESCE((allocation->>field)::numeric,0)>0 AND previous+(allocation->>field)::numeric>GREATEST(previous,limit_amount)+0.001 THEN RAISE EXCEPTION 'ยอดหัก % เกินกำหนดรายเดือน กรุณาโหลดข้อมูลล่าสุด',field; END IF;
        END LOOP;
        FOREACH field IN ARRAY ARRAY['savings','company_loan'] LOOP
          SELECT COALESCE(sum(COALESCE((amounts->>field)::numeric,0)),0) INTO previous FROM public.hr_payroll_effective_monthly_allocations WHERE company_id=NEW.company_id AND employee_id=i.employee_id AND payroll_item_id<>i.id;
          IF field='savings' THEN limit_amount:=CASE WHEN emp.savings_maximum IS NULL THEN NULL ELSE GREATEST(0,emp.savings_maximum-COALESCE(emp.savings_opening_balance,0)) END;
          ELSE limit_amount:=GREATEST(0,COALESCE(emp.company_loan_opening_balance,0)); END IF;
          IF limit_amount IS NOT NULL AND COALESCE((allocation->>field)::numeric,0)>0 AND previous+(allocation->>field)::numeric>GREATEST(previous,limit_amount)+0.001 THEN RAISE EXCEPTION 'ยอดหัก % เกินยอดคงเหลือ',field; END IF;
        END LOOP;
        SELECT COALESCE(sum(COALESCE((amounts->>'social_security')::numeric,0)),0),COALESCE(sum(COALESCE((amounts->>'base_salary')::numeric,0)),0)
          INTO previous,wage FROM public.hr_payroll_effective_monthly_allocations WHERE company_id=NEW.company_id AND employee_id=i.employee_id AND earning_month=month AND payroll_item_id<>i.id;
        SELECT round(LEAST(wage+COALESCE((allocation->>'base_salary')::numeric,0),maximum_wage_base)*contribution_rate/100,2) INTO limit_amount FROM public.hr_social_security_settings WHERE id=true;
        IF COALESCE((allocation->>'social_security')::numeric,0)>0 AND previous+(allocation->>'social_security')::numeric>GREATEST(previous,COALESCE(limit_amount,round(LEAST(wage+COALESCE((allocation->>'base_salary')::numeric,0),17500)*0.05,2)))+0.001 THEN RAISE EXCEPTION 'ยอด สปส. เกินยอดสะสมรายเดือน กรุณาโหลดข้อมูลใหม่'; END IF;
        SELECT COALESCE(sum(COALESCE((amounts->>'ewf')::numeric,0)),0),COALESCE(sum(COALESCE((amounts->>'base_salary')::numeric,0)+COALESCE((amounts->>'position_allowance')::numeric,0)),0)
          INTO previous,wage FROM public.hr_payroll_effective_monthly_allocations WHERE company_id=NEW.company_id AND employee_id=i.employee_id AND earning_month=month AND payroll_item_id<>i.id;
        limit_amount:=CASE WHEN upper(trim(i.employee_code))='EMP00001' OR EXISTS(SELECT 1 FROM public.hr_companies WHERE id=NEW.company_id AND ewf_enabled=false) THEN 0
          ELSE round((wage+COALESCE((allocation->>'base_salary')::numeric,0)+COALESCE((allocation->>'position_allowance')::numeric,0))*0.0025,2) END;
        IF COALESCE((allocation->>'ewf')::numeric,0)>0 AND previous+(allocation->>'ewf')::numeric>GREATEST(previous,limit_amount)+0.001 THEN RAISE EXCEPTION 'ยอด EWF เกินยอดสะสมรายเดือน กรุณาโหลดข้อมูลใหม่'; END IF;
      END IF;
      INSERT INTO public.hr_payroll_monthly_allocations VALUES(i.id,NEW.id,NEW.company_id,i.employee_id,month,allocation)
        ON CONFLICT(payroll_item_id,earning_month) DO UPDATE SET amounts=EXCLUDED.amounts;
    END LOOP;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: hr_payroll_guard_confirmed_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_guard_confirmed_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_status TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT status INTO v_status FROM public.hr_payroll_runs WHERE id=OLD.payroll_run_id FOR UPDATE;
    IF v_status='confirmed' THEN RAISE EXCEPTION 'ยอดยืนยันแล้ว กรุณาเปิดปรับปรุงงวดก่อน'; END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT status INTO v_status FROM public.hr_payroll_runs WHERE id=NEW.payroll_run_id FOR UPDATE;
    IF v_status='confirmed' THEN RAISE EXCEPTION 'ยอดยืนยันแล้ว กรุณาเปิดปรับปรุงงวดก่อน'; END IF;
    RETURN NEW;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: hr_payroll_guard_confirmed_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_guard_confirmed_run() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status='confirmed' THEN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'งวดที่ยืนยันแล้วต้องเก็บไว้ตรวจย้อนหลัง'; END IF;
    IF NEW.status <> 'draft'
      OR (to_jsonb(NEW)-ARRAY['status','confirmed_at','confirmed_by','updated_at'])
         IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','confirmed_at','confirmed_by','updated_at'])
      OR NOT EXISTS(SELECT 1 FROM public.hr_payroll_revisions r WHERE r.payroll_run_id=OLD.id
        AND r.transaction_id=txid_current() AND r.created_by IS NOT DISTINCT FROM auth.uid()) THEN
      RAISE EXCEPTION 'งวดนี้ยืนยันแล้ว กรุณาเปิดปรับปรุงยอดพร้อมระบุเหตุผลก่อน';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_payroll_monthly_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_monthly_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.hr_payroll_runs; other RECORD; dates DATE[];
BEGIN
  SELECT * INTO r FROM public.hr_payroll_runs WHERE id=NEW.payroll_run_id;
  PERFORM pg_advisory_xact_lock(hashtextextended(r.company_id::text || ':payroll',0));
  IF r.payroll_type NOT IN ('permanent','monthly_uninsured') THEN RETURN NEW; END IF;
  IF NEW.pay_type='daily' OR (NEW.social_security_enabled IS NOT NULL AND NEW.social_security_enabled<>(r.payroll_type='permanent')) THEN RAISE EXCEPTION 'สถานะ สปส. ไม่ตรงกับกลุ่มเงินเดือน'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=NEW.employee_id AND company_id=r.company_id) THEN RAISE EXCEPTION 'พนักงานไม่ได้อยู่ในบริษัทของงวด'; END IF;
  dates:=public.hr_payroll_claim_dates(to_jsonb(NEW),COALESCE(r.period_start,r.payroll_month),COALESCE(r.period_end,(r.payroll_month+interval '1 month - 1 day')::date));
  FOR other IN SELECT i.id,x.id run_id,x.status,x.schedule_id,x.payroll_type,x.payroll_month,
      COALESCE(x.period_start,x.payroll_month) start_date,COALESCE(x.period_end,(x.payroll_month+interval '1 month - 1 day')::date) end_date,to_jsonb(i) item
    FROM public.hr_payroll_items i JOIN public.hr_payroll_runs x ON x.id=i.payroll_run_id
    WHERE i.employee_id=NEW.employee_id AND x.company_id=r.company_id AND x.id<>r.id AND x.status<>'cancelled'
      AND x.payroll_type IN ('permanent','monthly_uninsured')
      AND COALESCE(x.period_start,x.payroll_month)<=COALESCE(r.period_end,(r.payroll_month+interval '1 month - 1 day')::date)
      AND COALESCE(x.period_end,(x.payroll_month+interval '1 month - 1 day')::date)>=COALESCE(r.period_start,r.payroll_month) LOOP
    IF public.hr_payroll_claim_dates(other.item,other.start_date,other.end_date) && dates THEN
      IF other.status='confirmed' THEN RAISE EXCEPTION 'พนักงานคนนี้ยืนยันค่าจ้างช่วงวันเดียวกันแล้ว'; END IF;
      IF TG_OP='UPDATE' AND other.id=OLD.id THEN CONTINUE; END IF;
      IF other.schedule_id IS NULL AND r.schedule_id IS NULL AND other.payroll_month=r.payroll_month AND other.payroll_type<>r.payroll_type THEN
        DELETE FROM public.hr_payroll_items WHERE id=other.id;
      ELSE RAISE EXCEPTION 'มีงวดร่างซ้อนช่วงวัน กรุณาทบทวนหรือยกเลิกร่างเดิมก่อน'; END IF;
    END IF;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: hr_payroll_paid_dates(jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_paid_dates(item jsonb, month_start date) RETURNS date[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE result DATE[]; month_end DATE := (date_trunc('month',month_start)+interval '1 month - 1 day')::date;
BEGIN
  IF COALESCE((item->>'base_salary')::numeric,0)=0 AND COALESCE((item->>'overtime_pay')::numeric,0)=0 THEN RETURN ARRAY[]::date[]; END IF;
  IF item->>'pay_type'='daily' AND jsonb_typeof(item->'daily_wage_details')='array' AND jsonb_array_length(item->'daily_wage_details')>0 THEN
    SELECT array_agg(DISTINCT (d->>'workDate')::date) INTO result FROM jsonb_array_elements(item->'daily_wage_details') d
      WHERE (COALESCE((d->>'amount')::numeric,0)>0 OR COALESCE((d->>'payableDay')::numeric,0)>0)
        AND (d->>'workDate')::date BETWEEN month_start AND month_end;
  ELSIF item->>'pay_type' IS DISTINCT FROM 'daily' AND jsonb_typeof(item->'monthly_wage_details')='array' AND jsonb_array_length(item->'monthly_wage_details')>0 THEN
    SELECT array_agg(DISTINCT day::date) INTO result FROM jsonb_array_elements(item->'monthly_wage_details') d
      CROSS JOIN LATERAL generate_series(GREATEST((d->>'startDate')::date,month_start),LEAST((d->>'endDate')::date,month_end),interval '1 day') day;
  ELSE
    -- A legacy paid item without a date breakdown occupies the whole month.
    SELECT array_agg(day::date) INTO result FROM generate_series(month_start,month_end,interval '1 day') day;
  END IF;
  IF COALESCE(array_length(result,1),0)=0 THEN
    SELECT array_agg(day::date) INTO result FROM generate_series(month_start,month_end,interval '1 day') day;
  END IF;
  RETURN result;
END;
$$;


--
-- Name: hr_payroll_role_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_role_allowed() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid() AND is_active IS TRUE AND role IN ('superadmin', 'account')
  );
$$;


--
-- Name: hr_payroll_run_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_run_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN NEW.version:=OLD.version+1; RETURN NEW; END $$;


--
-- Name: hr_payroll_snapshot_social_security(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_snapshot_social_security() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE kind TEXT;
BEGIN
  SELECT payroll_type INTO kind FROM public.hr_payroll_runs WHERE id=NEW.payroll_run_id;
  IF kind IN ('permanent','monthly_uninsured') THEN
    NEW.social_security_enabled := kind='permanent';
  ELSIF NEW.social_security_enabled IS NULL THEN
    SELECT e.social_security_enabled INTO NEW.social_security_enabled FROM public.hr_employees e WHERE e.id=NEW.employee_id;
  END IF;
  IF NEW.social_security_enabled IS FALSE THEN NEW.social_security := 0; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_portal_visible_time_entries(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_portal_visible_time_entries(p_work_date date DEFAULT ((now() AT TIME ZONE 'Asia/Bangkok'::text))::date) RETURNS TABLE(id uuid, employee_id uuid, employee_code text, employee_name text, nickname text, department_id uuid, department_name text, entry_type text, work_date date, entry_time timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_department_id UUID;
BEGIN
  SELECT u.role INTO v_role FROM us_users u WHERE u.id = auth.uid();
  SELECT e.department_id INTO v_department_id FROM hr_employees e WHERE e.user_id = auth.uid() LIMIT 1;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User not found';
  END IF;
  IF v_role NOT IN ('superadmin', 'admin', 'account') AND v_department_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    te.id,
    e.id,
    e.employee_code,
    TRIM(CONCAT_WS(' ', e.first_name, e.last_name)),
    e.nickname,
    e.department_id,
    d.name,
    te.entry_type,
    te.work_date,
    te.entry_time
  FROM hr_time_entries te
  JOIN hr_employees e ON e.id = te.employee_id
  LEFT JOIN hr_departments d ON d.id = e.department_id
  WHERE te.work_date = p_work_date
    AND e.employment_status IN ('active', 'probation')
    AND (
      v_role IN ('superadmin', 'admin', 'account')
      OR e.department_id = v_department_id
    )
  ORDER BY e.first_name, e.last_name, te.entry_time;
END;
$$;


--
-- Name: hr_preview_next_employee_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_preview_next_employee_code() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  SELECT 'EMP' || lpad((
    GREATEST(
      COALESCE((
        SELECT MAX(substring(e.employee_code FROM 4)::bigint)
        FROM hr_employees e
        WHERE e.employee_code ~ '^EMP[0-9]+$'
      ), 0),
      COALESCE((
        SELECT s.last_value
        FROM pg_sequences s
        WHERE s.schemaname = 'public'
          AND s.sequencename = 'hr_employee_code_seq'
      ), 0)
    ) + 1
  )::text, 5, '0');
$_$;


--
-- Name: hr_record_employee_compensation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_record_employee_compensation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE effective DATE;
BEGIN
  IF NEW.salary IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND (NEW.salary,NEW.contract_type,NEW.position_allowance,NEW.compensation_effective_date)
    IS NOT DISTINCT FROM (OLD.salary,OLD.contract_type,OLD.position_allowance,OLD.compensation_effective_date) THEN RETURN NEW; END IF;
  effective := COALESCE(NEW.compensation_effective_date,NEW.hire_date,(now() AT TIME ZONE 'Asia/Bangkok')::date);
  IF TG_OP='UPDATE' AND effective>(now() AT TIME ZONE 'Asia/Bangkok')::date THEN
    RAISE EXCEPTION 'ค่าจ้างล่วงหน้าให้เพิ่มผ่านประวัติเงินเดือน เพื่อคงค่าจ้างปัจจุบันไว้';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_salary_history h WHERE h.employee_id=NEW.id
    AND h.effective_date=effective AND h.salary=NEW.salary
    AND h.pay_type=COALESCE(NEW.contract_type,'permanent')
    AND COALESCE(h.position_allowance,0)=COALESCE(NEW.position_allowance,0)
    AND NOT EXISTS(SELECT 1 FROM public.hr_salary_history later WHERE later.employee_id=NEW.id
      AND later.effective_date=effective AND (later.created_at,later.id)>(h.created_at,h.id))) THEN
    INSERT INTO public.hr_salary_history(employee_id,salary,position_allowance,pay_type,effective_date,note,created_at)
      VALUES(NEW.id,NEW.salary,CASE WHEN NEW.contract_type='daily' THEN 0 ELSE COALESCE(NEW.position_allowance,0) END,
        COALESCE(NEW.contract_type,'permanent'),effective,'ทะเบียนพนักงาน: บันทึกประเภทสัญญา/ค่าจ้างพร้อมวันที่มีผล',clock_timestamp());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_record_pay_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_record_pay_schedule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE selected UUID := COALESCE(NEW.pay_schedule_id,'00000000-0000-4000-8000-000000000001'::uuid); effective DATE;
BEGIN
  IF TG_OP='UPDATE' AND (NEW.pay_schedule_id,NEW.pay_schedule_effective_date,NEW.company_id) IS NOT DISTINCT FROM (OLD.pay_schedule_id,OLD.pay_schedule_effective_date,OLD.company_id) THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_pay_schedules WHERE id=selected AND is_active AND (company_id IS NULL OR company_id=NEW.company_id)) THEN
    RAISE EXCEPTION 'รอบจ่ายไม่ได้อยู่ในบริษัทนี้หรือปิดใช้งานแล้ว';
  END IF;
  effective:=COALESCE(NEW.pay_schedule_effective_date,NEW.hire_date,(now() AT TIME ZONE 'Asia/Bangkok')::date);
  INSERT INTO public.hr_employee_pay_schedule_history(employee_id,schedule_id,effective_date) VALUES(NEW.id,selected,effective);
  RETURN NEW;
END;
$$;


--
-- Name: hr_record_payroll_payment(uuid, uuid, jsonb, uuid[], date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_record_payroll_payment(p_request uuid, p_run uuid, p_items jsonb, p_adjustments uuid[], p_paid_date date, p_channel text, p_reference text, p_evidence_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE company UUID; batch public.hr_payroll_payment_batches; payload JSONB; item RECORD; adjustment public.hr_payroll_adjustments;
  input JSONB; ids UUID[]; adjustment_ids UUID[]:=COALESCE(p_adjustments,ARRAY[]::uuid[]); signs INT[]; result JSONB;
BEGIN
  IF NOT public.hr_payroll_role_allowed() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกการจ่าย'; END IF;
  IF p_request IS NULL OR p_paid_date IS NULL OR p_paid_date>(now() AT TIME ZONE 'Asia/Bangkok')::date OR p_channel NOT IN ('bank','cash','other','offset') OR NULLIF(trim(p_reference),'') IS NULL THEN RAISE EXCEPTION 'กรุณาตรวจวันจ่าย ช่องทาง และเลขอ้างอิง'; END IF;
  IF p_evidence_url IS NOT NULL AND p_evidence_url !~ '^https://' THEN RAISE EXCEPTION 'ลิงก์หลักฐานต้องเป็น HTTPS'; END IF;
  IF jsonb_typeof(p_items)<>'array' THEN RAISE EXCEPTION 'ข้อมูลผู้รับเงินไม่ถูกต้อง'; END IF;
  SELECT array_agg(DISTINCT (entry->>'id')::uuid ORDER BY (entry->>'id')::uuid) INTO ids FROM jsonb_array_elements(p_items) entry;
  IF COALESCE(cardinality(ids),0)<>jsonb_array_length(p_items) OR COALESCE(cardinality(ids),0)+cardinality(adjustment_ids)=0 THEN RAISE EXCEPTION 'กรุณาเลือกผู้รับเงินโดยไม่ซ้ำกัน'; END IF;
  IF cardinality(adjustment_ids)<>(SELECT count(DISTINCT id) FROM unnest(adjustment_ids) id) THEN RAISE EXCEPTION 'รายการปรับปรุงซ้ำ'; END IF;
  IF cardinality(ids)>0 THEN SELECT company_id INTO company FROM public.hr_payroll_runs WHERE id=p_run;
  ELSE SELECT company_id INTO company FROM public.hr_payroll_adjustments WHERE id=adjustment_ids[1]; END IF;
  IF company IS NULL THEN RAISE EXCEPTION 'ไม่พบข้อมูลบริษัทของรายการ'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(company::text || ':payroll',0));
  payload:=jsonb_build_object('run',p_run,'items',p_items,'adjustments',adjustment_ids,'date',p_paid_date,'channel',p_channel,'reference',trim(p_reference),'evidence',p_evidence_url);
  SELECT * INTO batch FROM public.hr_payroll_payment_batches WHERE request_key=p_request;
  IF FOUND THEN
    IF batch.payload<>payload OR batch.company_id<>company THEN RAISE EXCEPTION 'รหัสคำขอนี้ถูกใช้กับข้อมูลอื่นแล้ว'; END IF;
    RETURN jsonb_build_object('batch',to_jsonb(batch),'payments',(SELECT jsonb_agg(to_jsonb(p)) FROM public.hr_payroll_payments p WHERE batch_id=batch.id));
  END IF;
  IF cardinality(ids)>0 THEN
    IF NOT EXISTS(SELECT 1 FROM public.hr_payroll_runs WHERE id=p_run AND company_id=company AND status='confirmed') THEN RAISE EXCEPTION 'ต้องยืนยันยอดก่อนบันทึกการจ่าย'; END IF;
    IF (SELECT count(*) FROM public.hr_payroll_items WHERE payroll_run_id=p_run AND id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'ผู้รับเงินไม่ได้อยู่ในงวดนี้'; END IF;
  END IF;
  signs:=ARRAY[]::int[];
  FOR input IN SELECT entry FROM jsonb_array_elements(p_items) entry LOOP
    SELECT * INTO item FROM public.hr_payroll_items WHERE id=(input->>'id')::uuid FOR UPDATE;
    IF EXISTS(SELECT 1 FROM public.hr_payroll_payments WHERE payroll_item_id=item.id) THEN RAISE EXCEPTION 'พนักงาน % บันทึกจ่ายแล้ว กรุณาโหลดสถานะล่าสุด',item.employee_code; END IF;
    IF item.net_pay<0 OR item.net_pay IS DISTINCT FROM (input->>'net_pay')::numeric THEN RAISE EXCEPTION 'ยอดสุทธิเปลี่ยนหรือเป็นยอดติดลบ กรุณาทบทวนก่อนจ่าย'; END IF;
    signs:=array_append(signs,sign(item.net_pay)::int);
  END LOOP;
  FOR adjustment IN SELECT * FROM public.hr_payroll_adjustments WHERE id=ANY(adjustment_ids) ORDER BY id FOR UPDATE LOOP
    IF adjustment.company_id<>company OR adjustment.status<>'approved' OR EXISTS(SELECT 1 FROM public.hr_payroll_payments WHERE adjustment_id=adjustment.id) THEN RAISE EXCEPTION 'รายการปรับปรุงถูกยกเลิกหรือบันทึกจ่ายแล้ว'; END IF;
    signs:=array_append(signs,sign(adjustment.net_delta)::int);
  END LOOP;
  IF (SELECT count(*) FROM public.hr_payroll_adjustments WHERE id=ANY(adjustment_ids))<>cardinality(adjustment_ids) THEN RAISE EXCEPTION 'ไม่พบรายการปรับปรุงครบ'; END IF;
  IF 1=ANY(signs) AND -1=ANY(signs) THEN RAISE EXCEPTION 'กรุณาแยกการจ่ายเพิ่มออกจากการรับเงินคืน'; END IF;
  IF p_channel='offset' AND EXISTS(SELECT 1 FROM unnest(signs) sign WHERE sign<>0) THEN RAISE EXCEPTION 'ช่องทางยอดศูนย์ใช้ได้เฉพาะรายการสุทธิศูนย์'; END IF;
  INSERT INTO public.hr_payroll_payment_batches(request_key,company_id,payload,paid_date,channel,reference,evidence_url,created_by)
    VALUES(p_request,company,payload,p_paid_date,p_channel,trim(p_reference),p_evidence_url,auth.uid()) RETURNING * INTO batch;
  INSERT INTO public.hr_payroll_payments(batch_id,company_id,employee_id,payroll_item_id,amount,snapshot)
    SELECT batch.id,company,employee_id,id,net_pay,to_jsonb(i) FROM public.hr_payroll_items i WHERE id=ANY(ids);
  INSERT INTO public.hr_payroll_payments(batch_id,company_id,employee_id,adjustment_id,amount,snapshot)
    SELECT batch.id,company,employee_id,id,net_delta,to_jsonb(a) FROM public.hr_payroll_adjustments a WHERE id=ANY(adjustment_ids);
  SELECT jsonb_build_object('batch',to_jsonb(batch),'payments',jsonb_agg(to_jsonb(p))) INTO result FROM public.hr_payroll_payments p WHERE batch_id=batch.id;
  RETURN result;
END $$;


