--
-- Name: hr_interviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_interviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    interview_date timestamp with time zone NOT NULL,
    location text,
    interviewer_ids uuid[] DEFAULT '{}'::uuid[],
    status text DEFAULT 'scheduled'::text,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    followup_status text DEFAULT 'pending'::text NOT NULL,
    start_date date,
    contact_note text,
    application_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    appointment_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT hr_interviews_followup_status_check CHECK ((followup_status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'started'::text, 'declined'::text])))
);


--
-- Name: hr_save_interview_followup(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_save_interview_followup(p_interview_id uuid, p_status text, p_start_date date, p_note text) RETURNS public.hr_interviews
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_interview public.hr_interviews;
  v_recommendation TEXT;
BEGIN
  IF p_status IS NULL OR p_status NOT IN ('pending', 'confirmed', 'started', 'declined') THEN
    RAISE EXCEPTION 'ผลการติดต่อไม่ถูกต้อง';
  END IF;
  SELECT * INTO v_interview FROM public.hr_interviews WHERE id = p_interview_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบนัดสัมภาษณ์'; END IF;
  SELECT recommendation INTO v_recommendation FROM public.hr_interview_scores
  WHERE interview_id = p_interview_id ORDER BY created_at DESC, id DESC LIMIT 1;
  IF v_interview.status NOT IN ('attended', 'completed') OR v_recommendation IS DISTINCT FROM 'hire' THEN
    RAISE EXCEPTION 'ติดตามเริ่มงานได้เฉพาะผู้ผ่านสัมภาษณ์';
  END IF;
  IF p_status IN ('confirmed', 'started') AND p_start_date IS NULL THEN
    RAISE EXCEPTION 'กรุณาระบุวันเริ่มงาน';
  END IF;
  UPDATE public.hr_interviews SET followup_status = p_status, start_date = p_start_date,
    contact_note = nullif(btrim(p_note), '') WHERE id = p_interview_id RETURNING * INTO v_interview;
  IF p_interview_id = (SELECT id FROM public.hr_interviews WHERE candidate_id = v_interview.candidate_id
    ORDER BY created_at DESC, id DESC LIMIT 1) THEN
    UPDATE public.hr_candidates SET status = CASE p_status
      WHEN 'started' THEN 'hired' WHEN 'declined' THEN 'withdrawn' ELSE 'passed' END
    WHERE id = v_interview.candidate_id;
  END IF;
  RETURN v_interview;
END;
$$;


--
-- Name: hr_save_payroll_period(jsonb, jsonb, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_save_payroll_period(p_run jsonb, p_items jsonb, p_confirm boolean DEFAULT false, p_expected_version integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE r public.hr_payroll_runs; company UUID:=(p_run->>'company_id')::uuid; selected_schedule UUID:=NULLIF(p_run->>'schedule_id','')::uuid;
  start_date DATE:=(p_run->>'period_start')::date; end_date DATE:=(p_run->>'period_end')::date;
  kind TEXT:=p_run->>'payroll_type'; item JSONB; payload JSONB; columns TEXT; assignments TEXT; result JSONB; finance_key TEXT; definition public.hr_pay_schedules; first_date DATE; last_date DATE; previous_last DATE; cutoff DATE; second_cutoff DATE;
  safe_keys TEXT[]:=ARRAY['payroll_run_id','employee_id','employee_code','employee_name','employee_nickname','department_position','base_salary','position_allowance','ot_normal_hours','ot_holiday_hours','overtime_pay','pay_type','daily_rate','full_days','half_days','paid_holiday_days','unpaid_leave_days','payable_days','unresolved_attendance_days','daily_wage_details','personal_tax','social_security','ewf','savings','student_loan','company_loan','leave_deduction','other_income','other_deduction','income_opening_balance','personal_tax_opening_balance','social_security_opening_balance','ewf_opening_balance','student_loan_opening_balance','savings_opening_balance','company_loan_opening_balance','company_loan_opening_installments','reviewed_at','reviewed_by','company_snapshot','social_security_enabled','monthly_rate','monthly_payable_days','monthly_wage_details','earning_dates','deduction_allocations'];
BEGIN
  IF NOT public.hr_payroll_role_allowed() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดทำเงินเดือน'; END IF;
  IF company IS NULL OR kind IS NULL OR kind NOT IN ('permanent','monthly_uninsured','daily') OR jsonb_typeof(p_items) IS DISTINCT FROM 'array'
    OR p_expected_version IS NULL OR p_expected_version<0 THEN RAISE EXCEPTION 'ข้อมูลงวดไม่ถูกต้อง'; END IF;
  IF start_date IS NULL OR end_date IS NULL OR end_date<start_date OR end_date-start_date>=366 THEN RAISE EXCEPTION 'ช่วงวันที่งวดไม่ถูกต้อง'; END IF;
  IF selected_schedule IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_pay_schedules WHERE id=selected_schedule AND is_active AND (company_id IS NULL OR company_id=company)) THEN RAISE EXCEPTION 'รอบจ่ายปิดใช้งานหรืออยู่คนละบริษัท'; END IF;
  IF selected_schedule IS NOT NULL THEN
    SELECT * INTO definition FROM public.hr_pay_schedules WHERE id=selected_schedule;
    first_date:=date_trunc('month',end_date)::date; last_date:=(first_date+interval '1 month - 1 day')::date;
    previous_last:=first_date-1;
    cutoff:=first_date+LEAST(definition.first_day,extract(day FROM last_date)::int)-1;
    second_cutoff:=CASE WHEN definition.second_day IS NULL THEN last_date ELSE first_date+LEAST(definition.second_day,extract(day FROM last_date)::int)-1 END;
    IF (definition.frequency='daily' AND start_date<>end_date)
      OR (definition.frequency='weekly' AND (end_date-start_date<>6 OR extract(isodow FROM end_date+1)::int<>definition.weekday))
      OR (definition.frequency='monthly' AND (start_date<>first_date OR end_date<>last_date))
      OR (definition.frequency='semimonthly' AND NOT (
        (end_date=cutoff AND start_date=CASE WHEN definition.second_day IS NULL THEN first_date ELSE date_trunc('month',previous_last)::date+LEAST(definition.second_day,extract(day FROM previous_last)::int) END)
        OR (start_date=cutoff+1 AND end_date=second_cutoff))) THEN
      RAISE EXCEPTION 'ช่วงวันที่ไม่ตรงกับรอบจ่ายที่กำหนด';
    END IF;
  END IF;
  IF selected_schedule IS NULL AND (start_date<>date_trunc('month',start_date)::date OR end_date<>(start_date+interval '1 month - 1 day')::date) THEN RAISE EXCEPTION 'งวดเดิมต้องเป็นช่วงเดือนเต็ม'; END IF;
  IF jsonb_array_length(p_items)<>(SELECT count(DISTINCT value->>'employee_id') FROM jsonb_array_elements(p_items)) THEN RAISE EXCEPTION 'รายชื่อพนักงานซ้ำ'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(company::text || ':payroll',0));
  SELECT * INTO r FROM public.hr_payroll_runs WHERE company_id=company AND payroll_type=kind
    AND schedule_id IS NOT DISTINCT FROM selected_schedule
    AND COALESCE(period_start,payroll_month)=start_date AND COALESCE(period_end,(payroll_month+interval '1 month - 1 day')::date)=end_date FOR UPDATE;
  IF FOUND THEN
    IF r.status='confirmed' THEN RAISE EXCEPTION 'งวดยืนยันแล้ว กรุณาเปิดปรับปรุงก่อน'; END IF;
    IF r.version<>p_expected_version THEN RAISE EXCEPTION 'ข้อมูลถูกแก้ไขโดยผู้ใช้อื่น กรุณาโหลดใหม่ก่อนบันทึก'; END IF;
    IF r.status='cancelled' THEN
      INSERT INTO public.hr_payroll_revisions(payroll_run_id,reason,run_before,items_before,created_by)
        SELECT r.id,'จัดทำใหม่หลังยกเลิกร่าง',to_jsonb(r),COALESCE(jsonb_agg(to_jsonb(i)),'[]'),auth.uid() FROM public.hr_payroll_items i WHERE i.payroll_run_id=r.id;
    END IF;
    UPDATE public.hr_payroll_runs SET status='draft',payment_date=NULLIF(p_run->>'payment_date','')::date,confirmed_at=NULL,confirmed_by=NULL,updated_at=now() WHERE id=r.id RETURNING * INTO r;
  ELSE
    IF p_expected_version<>0 THEN RAISE EXCEPTION 'ไม่พบงวดเดิม กรุณาโหลดใหม่'; END IF;
    INSERT INTO public.hr_payroll_runs(company_id,payroll_month,payroll_type,schedule_id,period_start,period_end,schedule_snapshot,payment_date,status)
      VALUES(company,date_trunc('month',start_date)::date,kind,selected_schedule,CASE WHEN selected_schedule IS NULL THEN NULL ELSE start_date END,
        CASE WHEN selected_schedule IS NULL THEN NULL ELSE end_date END,(SELECT to_jsonb(s) FROM public.hr_pay_schedules s WHERE id=COALESCE(selected_schedule,'00000000-0000-4000-8000-000000000001')),
        NULLIF(p_run->>'payment_date','')::date,'draft') RETURNING * INTO r;
  END IF;
  SELECT string_agg(quote_ident(attname),',' ORDER BY attnum),string_agg(format('%I=EXCLUDED.%I',attname,attname),',' ORDER BY attnum)
    INTO columns,assignments FROM pg_attribute WHERE attrelid='public.hr_payroll_items'::regclass AND attnum>0 AND NOT attisdropped AND attgenerated='' AND attname=ANY(safe_keys);
  FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    IF NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=(item->>'employee_id')::uuid AND company_id=company) THEN RAISE EXCEPTION 'พนักงานไม่ได้อยู่ในบริษัทนี้'; END IF;
    payload:='{}';
    FOREACH finance_key IN ARRAY ARRAY['base_salary','position_allowance','ot_normal_hours','ot_holiday_hours','overtime_pay','daily_rate','full_days','half_days','paid_holiday_days','unpaid_leave_days','payable_days','unresolved_attendance_days','personal_tax','social_security','ewf','savings','student_loan','company_loan','leave_deduction','other_income','other_deduction','income_opening_balance','personal_tax_opening_balance','social_security_opening_balance','ewf_opening_balance','student_loan_opening_balance','savings_opening_balance','company_loan_opening_balance','company_loan_opening_installments'] LOOP
      IF COALESCE(item->>finance_key,'0') IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'จำนวนเงินไม่ถูกต้อง'; END IF;
      payload:=payload||jsonb_build_object(finance_key,COALESCE((item->>finance_key)::numeric,0));
      IF (payload->>finance_key)::numeric<0 THEN RAISE EXCEPTION 'ยอดเงินและจำนวนวันต้องไม่ติดลบ'; END IF;
    END LOOP;
    payload:=item||payload||jsonb_build_object('payroll_run_id',r.id,'company_snapshot',(SELECT to_jsonb(c) FROM public.hr_companies c WHERE c.id=company),'pay_type',CASE WHEN kind='daily' THEN 'daily' ELSE 'permanent' END,'daily_wage_details',COALESCE(item->'daily_wage_details','[]'::jsonb));
    EXECUTE format('INSERT INTO public.hr_payroll_items(%s) SELECT %s FROM jsonb_populate_record(NULL::public.hr_payroll_items,$1) ON CONFLICT(payroll_run_id,employee_id) DO UPDATE SET %s',columns,columns,assignments) USING payload;
  END LOOP;
  DELETE FROM public.hr_payroll_items WHERE payroll_run_id=r.id AND employee_id NOT IN(SELECT (value->>'employee_id')::uuid FROM jsonb_array_elements(p_items));
  IF p_confirm THEN
    UPDATE public.hr_payroll_runs SET status='confirmed',confirmed_at=now(),confirmed_by=auth.uid(),updated_at=now() WHERE id=r.id RETURNING * INTO r;
  END IF;
  SELECT to_jsonb(r)||jsonb_build_object('company',(SELECT to_jsonb(c) FROM public.hr_companies c WHERE c.id=company),
    'items',COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.employee_code) FROM public.hr_payroll_items i WHERE i.payroll_run_id=r.id),'[]')) INTO result;
  RETURN result;
END $_$;


--
-- Name: hr_score_accept_appeal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_accept_appeal(p_appeal uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_appeal hr_score_appeals;
BEGIN
  IF NOT hr_is_admin() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตัดสินคำทักท้วง';
  END IF;

  SELECT * INTO v_appeal FROM hr_score_appeals WHERE id = p_appeal;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบคำทักท้วง'; END IF;
  IF v_appeal.status <> 'pending' THEN RAISE EXCEPTION 'คำทักท้วงนี้ตัดสินไปแล้ว'; END IF;

  -- เหตุการณ์ชดเชย: คะแนนตรงข้ามกับที่ถูกหัก · ไม่ลบของเดิม ประวัติต้องอยู่ครบ
  -- source='manual' จึงไม่ถูกลบตอนคำนวณคะแนนใหม่
  INSERT INTO hr_score_events
    (employee_id, event_date, category_id, event_code, points, source, ref_table, ref_id, detail, note, created_by)
  VALUES (
    v_appeal.employee_id,
    v_appeal.event_date,
    v_appeal.category_id,
    v_appeal.event_code || '_reversed',
    -v_appeal.points,
    'manual',
    'hr_score_appeals',
    p_appeal,
    jsonb_build_object('reversed_code', v_appeal.event_code, 'appeal_id', p_appeal),
    COALESCE(p_note, 'ยอมรับคำทักท้วง'),
    hr_my_employee_id()
  );

  UPDATE hr_score_appeals
  SET status = 'accepted', reviewed_by = hr_my_employee_id(), reviewed_at = now(), decision_note = p_note
  WHERE id = p_appeal;
END;
$$;


--
-- Name: hr_score_appeal_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_appeal_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    SELECT e.id, 'score_appeal_pending', 'มีคำทักท้วงคะแนนรอตรวจสอบ', NEW.reason, '/hr/work-score', NEW.id
    FROM hr_employees e
    JOIN us_users u ON u.id = e.user_id
    WHERE u.role IN ('superadmin', 'admin', 'hr')
    LIMIT 5;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status IN ('accepted', 'rejected') THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    VALUES (
      NEW.employee_id,
      'score_appeal_result',
      CASE WHEN NEW.status = 'accepted' THEN 'คำทักท้วงคะแนนได้รับการยอมรับ' ELSE 'คำทักท้วงคะแนนถูกปฏิเสธ' END,
      COALESCE(NEW.decision_note, ''),
      '/employee?tab=work-score',
      NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hr_score_can_appeal_date(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_can_appeal_date(p_date date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT hr_today_th() <= p_date + COALESCE((SELECT s.appeal_days FROM hr_score_settings s LIMIT 1), 7);
$$;


--
-- Name: hr_score_can_certify_date(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_can_certify_date(p_date date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT p_date <= hr_today_th()
     AND p_date >= hr_today_th() - COALESCE((SELECT s.certify_back_days FROM hr_score_settings s LIMIT 1), 7);
$$;


--
-- Name: hr_score_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_score_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    period date NOT NULL,
    category_id uuid NOT NULL,
    base_points numeric(6,2) NOT NULL,
    raw_deduction numeric(8,2) DEFAULT 0 NOT NULL,
    total_points numeric(6,2) NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    locked_at timestamp with time zone,
    locked_by uuid,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_score_periods_status_check CHECK ((status = ANY (ARRAY['open'::text, 'locked'::text])))
);


--
-- Name: hr_score_commit_period(uuid, date, uuid, jsonb, numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_commit_period(p_employee uuid, p_period date, p_category uuid, p_events jsonb, p_base numeric, p_raw_deduction numeric, p_total numeric, p_lock boolean DEFAULT false) RETURNS public.hr_score_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_period DATE := date_trunc('month', p_period)::DATE;
  v_next DATE := (date_trunc('month', p_period) + INTERVAL '1 month')::DATE;
  v_me UUID := hr_my_employee_id();
  v_row hr_score_periods;
BEGIN
  IF NOT hr_is_admin() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกคะแนน';
  END IF;

  IF hr_score_period_locked(p_employee, v_period) THEN
    RAISE EXCEPTION 'รอบเดือน % ปิดแล้ว บันทึกคะแนนซ้ำไม่ได้', to_char(v_period, 'YYYY-MM');
  END IF;

  DELETE FROM hr_score_events e
  WHERE e.employee_id = p_employee
    AND e.category_id = p_category
    AND e.source = 'auto'
    AND e.event_date >= v_period AND e.event_date < v_next;

  INSERT INTO hr_score_events
    (employee_id, event_date, category_id, rule_id, event_code, points, source, ref_table, ref_id, detail, created_by)
  SELECT
    p_employee,
    (ev ->> 'event_date')::DATE,
    p_category,
    NULLIF(ev ->> 'rule_id', '')::UUID,
    ev ->> 'event_code',
    (ev ->> 'points')::NUMERIC,
    'auto',
    NULLIF(ev ->> 'ref_table', ''),
    NULLIF(ev ->> 'ref_id', '')::UUID,
    COALESCE(ev -> 'detail', '{}'::JSONB),
    v_me
  FROM jsonb_array_elements(COALESCE(p_events, '[]'::JSONB)) AS ev;

  INSERT INTO hr_score_periods
    (employee_id, period, category_id, base_points, raw_deduction, total_points, status, locked_at, locked_by)
  VALUES (
    p_employee, v_period, p_category, p_base, p_raw_deduction, p_total,
    CASE WHEN p_lock THEN 'locked' ELSE 'open' END,
    CASE WHEN p_lock THEN now() END,
    CASE WHEN p_lock THEN v_me END
  )
  ON CONFLICT (employee_id, period, category_id) DO UPDATE SET
    base_points = EXCLUDED.base_points,
    raw_deduction = EXCLUDED.raw_deduction,
    total_points = EXCLUDED.total_points,
    status = EXCLUDED.status,
    locked_at = EXCLUDED.locked_at,
    locked_by = EXCLUDED.locked_by,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: hr_score_events_guard_locked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_events_guard_locked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_employee UUID;
  v_date DATE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_employee := OLD.employee_id;
    v_date := OLD.event_date;
  ELSE
    v_employee := NEW.employee_id;
    v_date := NEW.event_date;
  END IF;

  IF hr_score_period_locked(v_employee, v_date) THEN
    RAISE EXCEPTION 'รอบเดือน % ของพนักงานคนนี้ปิดแล้ว แก้ไขคะแนนไม่ได้', to_char(v_date, 'YYYY-MM');
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_score_period_ceiling(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_period_ceiling() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.total_points := LEAST(NEW.base_points,NEW.total_points);
  RETURN NEW;
END;
$$;


--
-- Name: hr_score_period_due_for_lock(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_period_due_for_lock(p_period date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT hr_today_th() >= (
    date_trunc('month', p_period)::DATE
    + INTERVAL '1 month'
    + ((COALESCE((SELECT s.lock_day_of_month FROM hr_score_settings s LIMIT 1), 5) - 1) || ' days')::INTERVAL
  )::DATE;
$$;


--
-- Name: hr_score_period_locked(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_period_locked(p_employee_id uuid, p_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM hr_score_periods
    WHERE employee_id = p_employee_id
      AND period = date_trunc('month', p_date)::DATE
      AND status = 'locked'
  );
$$;


--
-- Name: hr_score_periods_guard_unlock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_periods_guard_unlock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status = 'locked' AND NEW.status = 'open' AND NOT hr_is_superadmin() THEN
    RAISE EXCEPTION 'เปิดรอบที่ปิดไปแล้วได้เฉพาะ superadmin';
  END IF;
  IF OLD.status = 'locked' AND NEW.status = 'locked'
     AND (NEW.total_points, NEW.raw_deduction) IS DISTINCT FROM (OLD.total_points, OLD.raw_deduction) THEN
    RAISE EXCEPTION 'รอบนี้ปิดแล้ว แก้คะแนนไม่ได้';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_score_review_appeal_payroll(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_score_review_appeal_payroll(p_appeal uuid, p_payable_day numeric DEFAULT 0, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_appeal public.hr_score_appeals;
  v_existing public.hr_daily_wage_approvals;
BEGIN
  IF NOT public.hr_is_admin() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ตัดสินคำทักท้วง'; END IF;
  IF p_payable_day IS NULL OR p_payable_day NOT IN (0, 0.5, 1) THEN
    RAISE EXCEPTION 'กรุณาเลือกคืนคะแนนอย่างเดียว เต็มวัน หรือครึ่งวัน';
  END IF;
  SELECT * INTO v_appeal FROM public.hr_score_appeals WHERE id=p_appeal FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบคำทักท้วง'; END IF;
  IF v_appeal.status NOT IN ('pending','accepted') THEN RAISE EXCEPTION 'คำทักท้วงนี้ถูกปฏิเสธแล้ว'; END IF;
  IF p_payable_day > 0 THEN
    -- Only base absence events may establish attendance, never a repeat penalty.
    IF v_appeal.event_code NOT IN ('absent','absent_pending_leave') THEN
      RAISE EXCEPTION 'รับรองค่าจ้างได้เฉพาะคำทักท้วงขาดงานต้นทาง';
    END IF;
    IF NULLIF(trim(p_note),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุหลักฐานหรือเหตุผลรับรองค่าจ้าง'; END IF;
    -- Serialize different appeals for the same employee/date as well.
    PERFORM pg_advisory_xact_lock(hashtextextended(v_appeal.employee_id::text || ':' || v_appeal.event_date::text, 0));
    SELECT * INTO v_existing FROM public.hr_daily_wage_approvals
      WHERE employee_id=v_appeal.employee_id AND work_date=v_appeal.event_date;
    IF FOUND THEN RAISE EXCEPTION 'วันที่นี้ได้รับรองค่าจ้างแล้ว กรุณาตรวจประวัติเดิม'; END IF;
  END IF;
  IF v_appeal.status='pending' THEN
    PERFORM public.hr_score_accept_appeal(p_appeal, p_note);
  ELSIF p_payable_day=0 THEN
    RAISE EXCEPTION 'คำทักท้วงนี้คืนคะแนนแล้ว';
  END IF;
  IF p_payable_day > 0 THEN
    INSERT INTO public.hr_daily_wage_approvals(employee_id,work_date,appeal_id,payable_day,note,approved_by)
    VALUES(v_appeal.employee_id,v_appeal.event_date,p_appeal,p_payable_day,trim(p_note),auth.uid());
  END IF;
END;
$$;


--
-- Name: hr_set_leave_working_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_set_leave_working_days() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_work_days TEXT;
  v_working_days INTEGER;
BEGIN
  IF NEW.end_date < NEW.start_date THEN
    RAISE EXCEPTION 'วันสิ้นสุดการลาต้องไม่น้อยกว่าวันเริ่มต้น';
  END IF;

  SELECT COALESCE(employee_schedule.work_days, default_schedule.work_days, '1,2,3,4,5,6')
  INTO v_work_days
  FROM hr_employees employee
  LEFT JOIN hr_work_schedules employee_schedule
    ON employee_schedule.id = employee.work_schedule_id
  LEFT JOIN LATERAL (
    SELECT schedule.work_days
    FROM hr_work_schedules schedule
    WHERE schedule.is_default = true
    ORDER BY schedule.created_at
    LIMIT 1
  ) default_schedule ON true
  WHERE employee.id = NEW.employee_id;

  SELECT COUNT(*)::INTEGER
  INTO v_working_days
  FROM generate_series(NEW.start_date, NEW.end_date, INTERVAL '1 day') series(work_date)
  LEFT JOIN hr_employee_work_calendar override_day
    ON override_day.employee_id = NEW.employee_id
   AND override_day.work_date = series.work_date::DATE
  LEFT JOIN hr_company_holidays holiday
    ON holiday.holiday_date = series.work_date::DATE
  WHERE CASE
    -- รายการกำหนดพิเศษของพนักงานมีลำดับสูงสุด
    WHEN override_day.id IS NOT NULL THEN override_day.day_type = 'work'
    WHEN holiday.id IS NOT NULL THEN false
    ELSE EXTRACT(ISODOW FROM series.work_date)::INTEGER = ANY (
      string_to_array(v_work_days, ',')::INTEGER[]
    )
  END;

  IF v_working_days = 0 THEN
    RAISE EXCEPTION 'ช่วงวันที่เลือกไม่มีวันทำงาน ไม่สามารถบันทึกใบลาได้';
  END IF;

  IF COALESCE(NEW.leave_mode, 'full_day') = 'full_day' THEN
    NEW.total_days := v_working_days;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION hr_set_leave_working_days(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hr_set_leave_working_days() IS 'นับเฉพาะวันทำงานตาม override รายบุคคล วันหยุดบริษัท และตารางทำงาน ก่อนบันทึกใบลา';


--
-- Name: hr_set_task_assigners(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_set_task_assigners(p_employee_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_granted_by UUID := public.hr_my_employee_id();
BEGIN
  IF NOT public.hr_task_permission_admin() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขรายชื่อผู้มอบหมายงาน';
  END IF;

  DELETE FROM public.hr_task_assigner_permissions
  WHERE NOT (employee_id = ANY(COALESCE(p_employee_ids, ARRAY[]::UUID[])));

  INSERT INTO public.hr_task_assigner_permissions (employee_id, granted_by)
  SELECT DISTINCT selected.employee_id, v_granted_by
  FROM unnest(COALESCE(p_employee_ids, ARRAY[]::UUID[])) AS selected(employee_id)
  JOIN public.hr_employees employee ON employee.id = selected.employee_id
  WHERE employee.employment_status = 'active'
  ON CONFLICT (employee_id) DO UPDATE
  SET granted_by = EXCLUDED.granted_by,
      updated_at = now();
END;
$$;


--
-- Name: hr_set_task_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_set_task_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.task_no IS NULL THEN
    NEW.task_no := 'TASK-' || to_char(CURRENT_DATE, 'YYYYMM') || '-' || lpad(nextval('hr_task_no_seq')::text, 5, '0');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_acknowledge_my_part(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_acknowledge_my_part(p_task_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_employee UUID := public.hr_my_employee_id();
  v_now TIMESTAMPTZ := now();
BEGIN
  UPDATE public.hr_task_participants participant
  SET work_status = 'in_progress',
      acknowledged_at = COALESCE(participant.acknowledged_at, v_now),
      started_at = COALESCE(participant.started_at, v_now)
  FROM public.hr_tasks task
  WHERE participant.task_id = p_task_id
    AND participant.employee_id = v_employee
    AND participant.role = 'assignee'
    AND participant.work_status = 'pending'
    AND task.id = participant.task_id
    AND task.status NOT IN ('completed', 'cancelled');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบงานที่รอรับทราบ หรือคุณรับทราบงานนี้แล้ว';
  END IF;

  UPDATE public.hr_tasks
  SET status = CASE WHEN status IN ('new', 'acknowledged') THEN 'in_progress' ELSE status END,
      acknowledged_at = COALESCE(acknowledged_at, v_now),
      started_at = COALESCE(started_at, v_now),
      updated_at = v_now
  WHERE id = p_task_id
    AND status NOT IN ('completed', 'cancelled');
END;
$$;


--
-- Name: hr_task_can_assign(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_can_assign() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.hr_task_permission_admin()
    OR EXISTS (
      SELECT 1
      FROM public.hr_task_assigner_permissions permission
      WHERE permission.employee_id = public.hr_my_employee_id()
    );
$$;


--
-- Name: hr_task_can_manage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_can_manage(p_task_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT hr_is_admin() OR EXISTS (
    SELECT 1 FROM hr_tasks t WHERE t.id = p_task_id AND t.created_by = hr_my_employee_id()
  ) OR EXISTS (
    SELECT 1 FROM hr_task_participants p
    WHERE p.task_id = p_task_id AND p.employee_id = hr_my_employee_id() AND p.role = 'supervisor'
  );
$$;


--
-- Name: hr_task_complete_my_part(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_complete_my_part(p_task_id uuid, p_note text DEFAULT NULL::text, p_link text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_employee UUID := public.hr_my_employee_id();
  v_now TIMESTAMPTZ := now();
BEGIN
  IF NULLIF(btrim(COALESCE(p_note, '')), '') IS NULL
     AND NULLIF(btrim(COALESCE(p_link, '')), '') IS NULL THEN
    RAISE EXCEPTION 'กรุณาแนบลิงก์ผลงาน หรือกรอกข้อความสรุปงานอย่างน้อย 1 รายการ';
  END IF;

  UPDATE public.hr_task_participants participant
  SET work_status = 'completed',
      acknowledged_at = COALESCE(participant.acknowledged_at, v_now),
      started_at = COALESCE(participant.started_at, v_now),
      completed_at = v_now,
      submission_note = NULLIF(btrim(COALESCE(p_note, '')), ''),
      submission_link = NULLIF(btrim(COALESCE(p_link, '')), '')
  FROM public.hr_tasks task
  WHERE participant.task_id = p_task_id
    AND participant.employee_id = v_employee
    AND participant.role = 'assignee'
    AND task.id = participant.task_id
    AND task.status IN ('in_progress', 'revision');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบงานที่กำลังทำ หรือไม่มีสิทธิ์บันทึกส่วนงานนี้';
  END IF;
END;
$$;


--
-- Name: hr_task_is_related(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_is_related(p_task_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM hr_tasks t WHERE t.id = p_task_id AND t.created_by = hr_my_employee_id()
  ) OR EXISTS (
    SELECT 1 FROM hr_task_participants p WHERE p.task_id = p_task_id AND p.employee_id = hr_my_employee_id()
  );
$$;


--
-- Name: hr_task_is_team_manager(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_is_team_manager(p_team_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM hr_task_team_members WHERE team_id = p_team_id AND employee_id = hr_my_employee_id() AND role = 'manager');
$$;


--
-- Name: hr_task_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.role IN ('assignee','coordinator','advisor') THEN
    INSERT INTO hr_notifications(employee_id, type, title, message, link, related_id)
    SELECT NEW.employee_id, 'task_new',
      CASE NEW.role WHEN 'assignee' THEN 'ได้รับมอบหมายงานใหม่' WHEN 'coordinator' THEN 'ถูกเพิ่มเป็นผู้ประสานงาน' ELSE 'ถูกเพิ่มเป็นที่ปรึกษางาน' END,
      t.title, '/employee?tab=tasks', NEW.task_id FROM hr_tasks t WHERE t.id = NEW.task_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_permission_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_permission_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.us_users
    WHERE id = auth.uid()
      AND role IN ('superadmin', 'admin', 'hr', 'account')
  );
$$;


--
-- Name: hr_task_preserve_first_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_preserve_first_submission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'review' AND OLD.status IS DISTINCT FROM 'review' THEN
    NEW.first_submitted_at := COALESCE(OLD.first_submitted_at, NEW.submitted_at, now());
  ELSE
    NEW.first_submitted_at := OLD.first_submitted_at;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_recalculate_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_recalculate_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_task UUID; v_total INT; v_done INT;
BEGIN
  v_task := COALESCE(NEW.task_id, OLD.task_id);
  SELECT count(*), count(*) FILTER (WHERE is_completed) INTO v_total, v_done FROM hr_task_checklist_items WHERE task_id = v_task;
  UPDATE hr_tasks SET progress = CASE WHEN v_total = 0 THEN progress ELSE round(v_done * 100.0 / v_total)::INT END, updated_at = now() WHERE id = v_task;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: hr_task_record_combined_acknowledgement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_record_combined_acknowledgement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.acknowledged_at IS NULL
    AND NEW.acknowledged_at IS NOT NULL
    AND NEW.status <> 'acknowledged' THEN
    INSERT INTO hr_task_events(task_id, event_type, from_status, to_status, actor_id, event_at, details)
    VALUES (
      NEW.id,
      'acknowledged',
      OLD.status,
      NEW.status,
      hr_my_employee_id(),
      NEW.acknowledged_at,
      jsonb_build_object(
        'response_minutes', GREATEST(0, floor(extract(epoch FROM (NEW.acknowledged_at - NEW.created_at)) / 60)),
        'sla_minutes', 30,
        'met_sla', NEW.acknowledged_at <= NEW.created_at + interval '30 minutes'
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_record_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_record_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_type TEXT;
  v_details JSONB := '{}'::jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO hr_task_events(task_id, event_type, to_status, actor_id, event_at, details)
    VALUES (NEW.id, 'assigned', NEW.status, NEW.created_by, NEW.created_at, jsonb_build_object('due_at', NEW.due_at));
    RETURN NEW;
  END IF;

  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  v_event_type := CASE NEW.status
    WHEN 'acknowledged' THEN 'acknowledged'
    WHEN 'in_progress' THEN 'started'
    WHEN 'review' THEN 'submitted'
    WHEN 'revision' THEN 'revision_requested'
    WHEN 'completed' THEN 'completed'
    WHEN 'paused' THEN 'paused'
    WHEN 'cancelled' THEN 'cancelled'
    ELSE 'status_changed'
  END;

  IF NEW.status = 'acknowledged' THEN
    v_details := jsonb_build_object(
      'response_minutes', GREATEST(0, floor(extract(epoch FROM (COALESCE(NEW.acknowledged_at, now()) - NEW.created_at)) / 60)),
      'sla_minutes', 30,
      'met_sla', COALESCE(NEW.acknowledged_at, now()) <= NEW.created_at + interval '30 minutes'
    );
  ELSIF NEW.status = 'review' THEN
    v_details := jsonb_build_object(
      'due_at', NEW.due_at,
      'deadline_variance_minutes', CASE WHEN NEW.due_at IS NULL THEN NULL ELSE floor(extract(epoch FROM (COALESCE(NEW.submitted_at, now()) - NEW.due_at)) / 60) END,
      'work_minutes', CASE WHEN NEW.started_at IS NULL THEN NULL ELSE GREATEST(0, floor(extract(epoch FROM (COALESCE(NEW.submitted_at, now()) - NEW.started_at)) / 60)) END
    );
  END IF;

  INSERT INTO hr_task_events(task_id, event_type, from_status, to_status, actor_id, event_at, details)
  VALUES (NEW.id, v_event_type, OLD.status, NEW.status, hr_my_employee_id(), now(), v_details);
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_reset_assignees_on_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_reset_assignees_on_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'revision' THEN
    UPDATE public.hr_task_participants
    SET work_status = 'in_progress', completed_at = NULL
    WHERE task_id = NEW.id AND role = 'assignee';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_status_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_status_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('review','revision','completed') THEN
    INSERT INTO hr_notifications(employee_id, type, title, message, link, related_id)
    SELECT p.employee_id, 'task_' || NEW.status,
      CASE NEW.status WHEN 'review' THEN 'มีงานรอตรวจ' WHEN 'revision' THEN 'งานถูกขอให้แก้ไข' ELSE 'งานเสร็จสมบูรณ์' END,
      NEW.title,
      CASE WHEN p.role = 'assignee' THEN '/employee?tab=tasks' ELSE '/hr/tasks' END,
      NEW.id
    FROM hr_task_participants p
    WHERE p.task_id = NEW.id AND p.role IN (CASE WHEN NEW.status = 'review' THEN 'supervisor' ELSE 'assignee' END);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_task_submit_team(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_task_submit_team(p_task_id uuid, p_note text DEFAULT NULL::text, p_link text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_employee UUID := public.hr_my_employee_id();
  v_now TIMESTAMPTZ := now();
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.hr_task_participants
    WHERE task_id = p_task_id AND employee_id = v_employee
      AND role = 'assignee' AND is_primary
  ) THEN
    RAISE EXCEPTION 'เฉพาะผู้รับผิดชอบหลักเท่านั้นที่ส่งงานรวมเพื่อตรวจได้';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.hr_task_participants
    WHERE task_id = p_task_id AND role = 'assignee' AND work_status <> 'completed'
  ) THEN
    RAISE EXCEPTION 'สมาชิกผู้รับผิดชอบยังทำส่วนงานไม่ครบ';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.hr_task_checklist_items
    WHERE task_id = p_task_id AND NOT is_completed
  ) THEN
    RAISE EXCEPTION 'กรุณาเช็กรายการงานให้ครบก่อนส่งตรวจ';
  END IF;

  IF NULLIF(btrim(COALESCE(p_note, '')), '') IS NULL
     AND NULLIF(btrim(COALESCE(p_link, '')), '') IS NULL THEN
    RAISE EXCEPTION 'กรุณาแนบลิงก์ผลงาน หรือกรอกข้อความส่งงานอย่างน้อย 1 รายการ';
  END IF;

  UPDATE public.hr_tasks
  SET status = 'review',
      submitted_at = v_now,
      completion_note = NULLIF(btrim(COALESCE(p_note, '')), ''),
      completion_link = NULLIF(btrim(COALESCE(p_link, '')), ''),
      updated_at = v_now
  WHERE id = p_task_id
    AND status IN ('in_progress', 'revision');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'งานนี้ไม่อยู่ในสถานะที่ส่งตรวจได้';
  END IF;
END;
$$;


--
-- Name: hr_today_th(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_today_th() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT (now() AT TIME ZONE 'Asia/Bangkok')::DATE;
$$;


--
-- Name: hr_touch_opening_data(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_touch_opening_data() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;


--
-- Name: hr_validate_task_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_validate_task_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'review' THEN
    IF EXISTS (
      SELECT 1 FROM hr_task_checklist_items
      WHERE task_id = NEW.id AND is_completed = false
    ) THEN
      RAISE EXCEPTION 'กรุณาเช็กรายการงานให้ครบก่อนส่งตรวจ'
        USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(btrim(COALESCE(NEW.completion_note, '')), '') IS NULL
       AND NULLIF(btrim(COALESCE(NEW.completion_link, '')), '') IS NULL THEN
      RAISE EXCEPTION 'กรุณาแนบลิงก์ผลงาน หรือกรอกข้อความส่งงานอย่างน้อย 1 รายการ'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_validate_time_entry_work_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_validate_time_entry_work_location() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mode TEXT;
  v_request_id UUID;
BEGIN
  -- ข้อมูลจากเครื่องสแกน/HR ไม่ผ่านขั้นตอน GPS บน Employee Portal
  IF COALESCE(NEW.source, 'mobile') <> 'mobile' THEN
    NEW.work_location_type := 'office';
    NEW.wfh_request_id := NULL;
    RETURN NEW;
  END IF;
  SELECT work_mode INTO v_mode FROM hr_employees WHERE id = NEW.employee_id;
  IF v_mode = 'wfh' THEN
    NEW.work_location_type := 'wfh_permanent';
    NEW.wfh_request_id := NULL;
  ELSIF v_mode = 'hybrid' AND NEW.location_id IS NULL THEN
    SELECT id INTO v_request_id FROM hr_wfh_requests
    WHERE employee_id = NEW.employee_id AND status = 'approved'
      AND NEW.work_date BETWEEN start_date AND end_date
    ORDER BY approved_at DESC NULLS LAST LIMIT 1;
    IF v_request_id IS NULL THEN
      RAISE EXCEPTION 'ไม่พบคำขอ WFH ที่อนุมัติสำหรับวันนี้';
    END IF;
    NEW.work_location_type := 'wfh_approved';
    NEW.wfh_request_id := v_request_id;
  ELSE
    IF NEW.location_id IS NULL THEN
      RAISE EXCEPTION 'การลงเวลาเข้าออฟฟิศต้องระบุจุดพิกัดสำนักงาน';
    END IF;
    NEW.work_location_type := 'office';
    NEW.wfh_request_id := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_warning_audit_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO hr_warning_audit_logs(warning_id,actor_user_id,actor_employee_id,action,old_data,new_data,reason)
  VALUES(COALESCE(NEW.id,OLD.id),auth.uid(),hr_my_employee_id(),lower(TG_OP),CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,
    CASE WHEN TG_OP='UPDATE' AND OLD.warning_level IS DISTINCT FROM NEW.warning_level THEN NEW.level_override_reason ELSE NULL END);
  RETURN COALESCE(NEW,OLD);
END; $$;


--
-- Name: hr_warning_authorized_employees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_authorized_employees() RETURNS TABLE(id uuid, employee_code text, first_name text, last_name text, nickname text, user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id,e.employee_code,e.first_name,e.last_name,e.nickname,e.user_id
  FROM hr_employees e JOIN us_users u ON u.id=e.user_id
  WHERE u.role IN ('superadmin','admin','account','hr') AND u.is_active=true AND e.employment_status='active'
    AND check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr'])
  ORDER BY e.employee_code;
$$;


--
-- Name: hr_warning_employee_response(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_employee_response(p_warning uuid, p_outcome text, p_response text DEFAULT NULL::text, p_method text DEFAULT 'employee_portal'::text, p_attachments jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE emp UUID;
BEGIN
  SELECT id INTO emp FROM hr_employees WHERE user_id=auth.uid();
  IF NOT EXISTS(SELECT 1 FROM hr_warnings WHERE id=p_warning AND employee_id=emp AND status='pending_acknowledgement') THEN RAISE EXCEPTION 'ไม่พบใบเตือนที่รอรับทราบ'; END IF;
  IF p_outcome NOT IN ('acknowledged','refused') THEN RAISE EXCEPTION 'ผลการรับทราบไม่ถูกต้อง'; END IF;
  IF NULLIF(btrim(COALESCE(p_response,'')),'') IS NOT NULL THEN
    INSERT INTO hr_warning_employee_responses(warning_id,response_text,recorded_by,attachment_urls) VALUES(p_warning,p_response,auth.uid(),COALESCE(p_attachments,'[]'));
  END IF;
  INSERT INTO hr_warning_acknowledgements(warning_id,outcome,method,handled_by,note) VALUES(p_warning,p_outcome,p_method,auth.uid(),p_response);
  UPDATE hr_warnings SET status=CASE WHEN p_outcome='acknowledged' THEN 'acknowledged' ELSE 'acknowledgement_refused' END,
    acknowledged_at=now(),employee_response=COALESCE(NULLIF(btrim(COALESCE(p_response,'')),''),employee_response) WHERE id=p_warning;
END; $$;


--
-- Name: hr_warning_recommend_level(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_recommend_level(p_employee uuid, p_offense uuid) RETURNS TABLE(recommended_level text, basis jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH cfg AS (SELECT COALESCE(lookback_days,365) days FROM hr_warning_offense_types WHERE id=p_offense),
  history AS (
    SELECT id,warning_number,case_number,warning_level,incident_date
    FROM hr_warnings,cfg WHERE employee_id=p_employee AND offense_type_id=p_offense
      AND status IN ('approved','pending_acknowledgement','acknowledged','acknowledgement_refused','termination_review','closed')
      AND incident_date >= CURRENT_DATE-cfg.days
  ), rank AS (
    SELECT COALESCE(max(CASE warning_level WHEN 'termination_review' THEN 4 WHEN 'final' THEN 3
      WHEN 'written_2' THEN 3 WHEN 'written_1' THEN 2 WHEN 'verbal_2' THEN 2 WHEN 'verbal' THEN 1 ELSE 0 END),0) r FROM history
  )
  SELECT CASE r WHEN 0 THEN 'verbal' WHEN 1 THEN 'written_1' WHEN 2 THEN 'final' ELSE 'termination_review' END,
    COALESCE((SELECT jsonb_agg(to_jsonb(history) ORDER BY incident_date DESC) FROM history),'[]'::jsonb) FROM rank;
$$;


--
-- Name: hr_warning_record_acknowledgement(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_record_acknowledgement(p_warning uuid, p_outcome text, p_method text, p_note text DEFAULT NULL::text, p_witness uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกการรับทราบ'; END IF;
  IF p_outcome NOT IN ('acknowledged','refused') THEN RAISE EXCEPTION 'ผลการรับทราบไม่ถูกต้อง'; END IF;
  IF NOT EXISTS(SELECT 1 FROM hr_warnings WHERE id=p_warning AND status='pending_acknowledgement') THEN RAISE EXCEPTION 'เคสนี้ไม่ได้อยู่ในขั้นตอนรอรับทราบ'; END IF;
  IF p_outcome='refused' AND p_witness IS NULL THEN RAISE EXCEPTION 'กรุณาระบุพยานเมื่อพนักงานปฏิเสธรับทราบ'; END IF;
  INSERT INTO hr_warning_acknowledgements(warning_id,outcome,method,handled_by,witness_id,note) VALUES(p_warning,p_outcome,p_method,auth.uid(),p_witness,p_note);
  UPDATE hr_warnings SET status=CASE WHEN p_outcome='acknowledged' THEN 'acknowledged' ELSE 'acknowledgement_refused' END,acknowledged_at=now(),employee_response=COALESCE(NULLIF(btrim(COALESCE(p_note,'')),''),employee_response) WHERE id=p_warning;
END; $$;


--
-- Name: hr_warning_validate_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_validate_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.recommended_level IS NOT NULL AND NEW.warning_level IS DISTINCT FROM NEW.recommended_level
     AND NULLIF(btrim(COALESCE(NEW.level_override_reason,'')),'') IS NULL THEN
    RAISE EXCEPTION 'กรุณาระบุเหตุผลในการเปลี่ยนระดับการเตือน';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: hr_warnings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_warnings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    warning_number text,
    employee_id uuid NOT NULL,
    warning_level text DEFAULT 'verbal'::text NOT NULL,
    subject text NOT NULL,
    description text,
    incident_date date NOT NULL,
    issued_date date DEFAULT CURRENT_DATE NOT NULL,
    issued_by uuid,
    witness_id uuid,
    employee_response text,
    status text DEFAULT 'draft'::text NOT NULL,
    resolution_note text,
    resolved_at timestamp with time zone,
    attachment_urls jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    acknowledged_at timestamp with time zone,
    reference_warning_id uuid,
    case_number text,
    offense_type_id uuid,
    corrective_action text,
    recommended_level text,
    level_override_reason text,
    recommendation_basis jsonb DEFAULT '[]'::jsonb NOT NULL,
    reviewer_id uuid,
    approver_id uuid,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    effective_until date,
    created_by_user uuid,
    cancelled_at timestamp with time zone,
    closed_at timestamp with time zone,
    late_generated boolean DEFAULT false NOT NULL,
    late_incidents_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    late_start_date date,
    CONSTRAINT hr_warnings_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'changes_requested'::text, 'pending_approval'::text, 'approved'::text, 'pending_acknowledgement'::text, 'acknowledged'::text, 'acknowledgement_refused'::text, 'termination_review'::text, 'closed'::text, 'cancelled'::text, 'issued'::text, 'appealed'::text, 'resolved'::text]))),
    CONSTRAINT hr_warnings_warning_level_check CHECK ((warning_level = ANY (ARRAY['verbal'::text, 'verbal_2'::text, 'written_1'::text, 'written_2'::text, 'final'::text, 'termination_review'::text])))
);


--
-- Name: COLUMN hr_warnings.reference_warning_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_warnings.reference_warning_id IS 'Previous warning copied as the basis for this follow-up warning';


--
-- Name: hr_warning_workflow(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_warning_workflow(p_warning uuid, p_action text, p_note text DEFAULT NULL::text) RETURNS public.hr_warnings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE w hr_warnings; emp UUID;
BEGIN
  IF NOT check_user_role(auth.uid(),ARRAY['superadmin','admin','account','hr']) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ดำเนินการใบเตือน'; END IF;
  SELECT * INTO w FROM hr_warnings WHERE id=p_warning FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบเคสใบเตือน'; END IF;
  SELECT id INTO emp FROM hr_employees WHERE user_id=auth.uid();
  IF p_action='submit_review' AND w.status IN ('draft','changes_requested') THEN
    IF w.offense_type_id IS NULL OR NULLIF(btrim(COALESCE(w.corrective_action,'')),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุประเภทความผิดและสิ่งที่ต้องปรับปรุง'; END IF;
    UPDATE hr_warnings SET status='pending_review' WHERE id=p_warning;
    INSERT INTO hr_warning_approvals(warning_id,step,actor_id,action,note) VALUES(p_warning,'review',emp,'submitted',p_note);
  ELSIF p_action='send_approval' AND w.status='pending_review' THEN
    UPDATE hr_warnings SET status='pending_approval',reviewer_id=emp,reviewed_at=now() WHERE id=p_warning;
    INSERT INTO hr_warning_approvals(warning_id,step,actor_id,action,note) VALUES(p_warning,'review',emp,'approved',p_note);
  ELSIF p_action='return' AND w.status IN ('pending_review','pending_approval') THEN
    UPDATE hr_warnings SET status='changes_requested' WHERE id=p_warning;
    INSERT INTO hr_warning_approvals(warning_id,step,actor_id,action,note) VALUES(p_warning,CASE WHEN w.status='pending_review' THEN 'review' ELSE 'approval' END,emp,'returned',p_note);
  ELSIF p_action='approve' AND w.status='pending_approval' THEN
    IF w.approver_id IS NOT NULL AND w.approver_id IS DISTINCT FROM emp THEN RAISE EXCEPTION 'เฉพาะผู้อนุมัติที่ระบุในเคสเท่านั้นที่อนุมัติได้'; END IF;
    UPDATE hr_warnings SET status=CASE WHEN warning_level='termination_review' THEN 'termination_review' ELSE 'pending_acknowledgement' END,
      approver_id=emp,approved_at=now(),issued_date=CURRENT_DATE,
      warning_number=COALESCE(warning_number,'WRN-'||to_char(now(),'YYYY')||'-'||lpad(nextval('hr_warning_number_seq')::text,5,'0')) WHERE id=p_warning;
    INSERT INTO hr_warning_approvals(warning_id,step,actor_id,action,note) VALUES(p_warning,'approval',emp,'approved',p_note);
  ELSIF p_action='cancel' AND w.status<>'cancelled' AND (w.status<>'closed' OR w.late_generated) THEN
    IF NULLIF(btrim(p_note),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลในการยกเลิก'; END IF;
    UPDATE hr_warnings SET status='cancelled',cancelled_at=now(),resolution_note=p_note WHERE id=p_warning;
  ELSIF p_action='close' AND w.status IN ('acknowledged','acknowledgement_refused','termination_review') THEN
    UPDATE hr_warnings SET status='closed',closed_at=now() WHERE id=p_warning;
  ELSE RAISE EXCEPTION 'ไม่สามารถดำเนินการจากสถานะปัจจุบันได้'; END IF;
  RETURN (SELECT x FROM hr_warnings x WHERE x.id=p_warning);
END; $$;


--
-- Name: hr_wfh_cancel_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_wfh_cancel_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status = 'approved' AND NEW.status = 'cancelled' THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    VALUES (NEW.employee_id, 'wfh_result', 'คำขอ WFH ถูกยกเลิกแล้ว',
      'WFH วันที่ ' || NEW.start_date::text || ' ถึง ' || NEW.end_date::text ||
      ' ถูกยกเลิกโดย ' || NEW.cancelled_by_name || ' เหตุผล: ' || NEW.cancel_reason ||
      ' หากต้องการวันใหม่ กรุณาส่งคำขอและรออนุมัติอีกครั้ง', '/employee?notif=result', NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_wfh_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_wfh_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    SELECT e.id, 'wfh_approval_pending', 'มีคำขอ WFH รออนุมัติ',
      'พนักงานส่งคำขอ WFH วันที่ ' || NEW.start_date::text || ' ถึง ' || NEW.end_date::text,
      '/employee?notif=pending', NEW.id
    FROM hr_employees e
    JOIN us_users u ON u.id = e.user_id
    WHERE u.role IN ('superadmin', 'admin');
  ELSIF OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected') THEN
    INSERT INTO hr_notifications (employee_id, type, title, message, link, related_id)
    VALUES (
      NEW.employee_id,
      'wfh_result',
      CASE WHEN NEW.status = 'approved' THEN 'คำขอ WFH ได้รับการอนุมัติ' ELSE 'คำขอ WFH ถูกปฏิเสธ' END,
      CASE WHEN NEW.status = 'approved' THEN 'คุณสามารถลงเวลาแบบ WFH ในช่วงวันที่อนุมัติได้'
           ELSE COALESCE('เหตุผล: ' || NEW.reject_reason, 'คำขอ WFH ไม่ได้รับการอนุมัติ') END,
      '/employee?notif=result', NEW.id
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hr_work_schedules_single_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_work_schedules_single_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.is_default THEN
    UPDATE hr_work_schedules SET is_default = false WHERE id <> NEW.id AND is_default;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: import_marketplace_orders(uuid, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_marketplace_orders(p_config_id uuid, p_file_name text, p_row_count integer, p_known_duplicate_count integer, p_orders jsonb) RETURNS TABLE(batch_id uuid, imported_count integer, duplicate_count integer, reimported_count integer, tracking_conflict_count integer, imported_order_keys jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch_id UUID;
  v_order JSONB;
  v_order_id UUID;
  v_existing public.mp_orders%ROWTYPE;
  v_channel_code TEXT;
  v_order_no TEXT;
  v_order_key TEXT;
  v_tracking TEXT;
  v_tracking_key TEXT;
  v_imported_count INTEGER := 0;
  v_duplicate_count INTEGER := GREATEST(COALESCE(p_known_duplicate_count, 0), 0);
  v_reimported_count INTEGER := 0;
  v_tracking_conflict_count INTEGER := 0;
  v_imported_order_keys JSONB := '[]'::JSONB;
  v_version INTEGER;
  v_supersedes UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.mp_can_manage_new_orders() THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'คุณไม่มีสิทธิ์นำเข้างาน Marketplace';
  END IF;

  IF p_config_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.mp_channel_configs config
    WHERE config.id = p_config_id AND config.is_active = TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ไม่พบช่องทางนำเข้าที่เปิดใช้งาน กรุณาเลือกช่องทางใหม่';
  END IF;

  IF NULLIF(BTRIM(COALESCE(p_file_name, '')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ไม่พบชื่อไฟล์ที่ต้องการนำเข้า';
  END IF;

  IF p_orders IS NULL OR jsonb_typeof(p_orders) <> 'array'
     OR jsonb_array_length(p_orders) < 1 OR jsonb_array_length(p_orders) > 10000 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ไฟล์ต้องมีออเดอร์สำหรับนำเข้า 1 ถึง 10,000 รายการ';
  END IF;

  INSERT INTO public.mp_import_batches (
    config_id, file_name, row_count, order_count, duplicate_count, uploaded_by
  ) VALUES (
    p_config_id, BTRIM(p_file_name), GREATEST(COALESCE(p_row_count, 0), 0), 0,
    v_duplicate_count, auth.uid()
  ) RETURNING id INTO v_batch_id;

  FOR v_order IN SELECT value FROM jsonb_array_elements(p_orders)
  LOOP
    v_channel_code := BTRIM(COALESCE(v_order->>'channel_code', ''));
    v_order_no := BTRIM(COALESCE(v_order->>'marketplace_order_no', ''));
    v_order_key := lower(v_order_no);
    v_tracking := NULLIF(BTRIM(COALESCE(v_order->>'tracking_no', '')), '');
    IF v_tracking = '-' THEN v_tracking := NULL; END IF;
    v_tracking_key := upper(regexp_replace(COALESCE(v_tracking, ''), '[[:space:]]+', '', 'g'));

    IF v_channel_code = '' OR v_order_no = '' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'พบออเดอร์ที่ไม่มีช่องทางขายหรือเลขคำสั่งซื้อ';
    END IF;

    -- Serialize each logical Marketplace order across concurrent imports.
    PERFORM pg_advisory_xact_lock(hashtextextended('MP:' || v_channel_code || ':' || v_order_key, 0));

    -- Legacy uniqueness was case-sensitive. Check every normalized current row
    -- so an old case-variant cannot be bypassed by selecting a cancelled one.
    IF EXISTS (
      SELECT 1
      FROM public.mp_orders current_order
      WHERE current_order.channel_code = v_channel_code
        AND lower(btrim(current_order.marketplace_order_no)) = v_order_key
        AND current_order.is_current
        AND current_order.status <> 'cancelled'
        AND NOT EXISTS (
          SELECT 1 FROM public.or_orders billed
          WHERE billed.id = current_order.billed_order_id AND billed.status = 'ยกเลิก'
        )
    ) THEN
      v_duplicate_count := v_duplicate_count + 1;
      CONTINUE;
    END IF;

    SELECT * INTO v_existing
    FROM public.mp_orders current_order
    WHERE current_order.channel_code = v_channel_code
      AND lower(btrim(current_order.marketplace_order_no)) = v_order_key
      AND current_order.is_current
    ORDER BY current_order.created_at DESC, current_order.id DESC
    LIMIT 1
    FOR UPDATE;

    v_supersedes := NULL;
    v_version := 1;
    IF v_existing.id IS NOT NULL THEN
      v_supersedes := v_existing.id;
      v_version := GREATEST(COALESCE(v_existing.import_version, 1), 1) + 1;
    END IF;

    IF v_tracking_key <> '' THEN
      PERFORM pg_advisory_xact_lock(hashtextextended('TRACK:' || v_tracking_key, 0));
      IF EXISTS (
        SELECT 1 FROM public.or_orders active_bill
        WHERE COALESCE(active_bill.status, '') <> 'ยกเลิก'
          AND upper(regexp_replace(COALESCE(active_bill.tracking_number, ''), '[[:space:]]+', '', 'g')) = v_tracking_key
      ) OR EXISTS (
        SELECT 1 FROM public.mp_orders active_work
        WHERE active_work.is_current
          AND active_work.status <> 'cancelled'
          AND upper(regexp_replace(COALESCE(active_work.tracking_no, ''), '[[:space:]]+', '', 'g')) = v_tracking_key
      ) THEN
        v_tracking_conflict_count := v_tracking_conflict_count + 1;
        CONTINUE;
      END IF;
    END IF;

    IF v_supersedes IS NOT NULL THEN
      UPDATE public.mp_orders
      SET is_current = FALSE
      WHERE channel_code = v_channel_code
        AND lower(btrim(marketplace_order_no)) = v_order_key
        AND is_current;
      v_reimported_count := v_reimported_count + 1;
    END IF;

    INSERT INTO public.mp_orders (
      batch_id, config_id, channel_code, shipping_option, urgency_label, urgency_color,
      requires_express_receipt_number, marketplace_order_no, platform_status, buyer_username,
      order_date, payment_time, recipient_name, phone, address, province, district, postal_code,
      buyer_note, tracking_no, shipping_fee, order_total, raw_snapshot, ship_due_at, overdue_at,
      status, is_current, import_version, supersedes_mp_order_id
    ) VALUES (
      v_batch_id, p_config_id, v_channel_code, NULLIF(v_order->>'shipping_option', ''),
      NULLIF(v_order->>'urgency_label', ''), NULLIF(v_order->>'urgency_color', ''),
      COALESCE((v_order->>'requires_express_receipt_number')::BOOLEAN, FALSE), v_order_no,
      NULLIF(v_order->>'platform_status', ''), NULLIF(v_order->>'buyer_username', ''),
      NULLIF(v_order->>'order_date', '')::TIMESTAMPTZ, NULLIF(v_order->>'payment_time', '')::TIMESTAMPTZ,
      NULLIF(v_order->>'recipient_name', ''), NULLIF(v_order->>'phone', ''), NULLIF(v_order->>'address', ''),
      NULLIF(v_order->>'province', ''), NULLIF(v_order->>'district', ''), NULLIF(v_order->>'postal_code', ''),
      NULLIF(v_order->>'buyer_note', ''), v_tracking, NULLIF(v_order->>'shipping_fee', '')::NUMERIC,
      NULLIF(v_order->>'order_total', '')::NUMERIC, COALESCE(v_order->'raw_snapshot', '{}'::JSONB),
      NULLIF(v_order->>'ship_due_at', '')::TIMESTAMPTZ, NULLIF(v_order->>'overdue_at', '')::TIMESTAMPTZ,
      'new', TRUE, v_version, v_supersedes
    ) RETURNING id INTO v_order_id;

    INSERT INTO public.mp_order_items (
      mp_order_id, line_index, product_name_raw, sku_ref, variation, qty, unit_price,
      line_total, raw_snapshot, product_id
    )
    SELECT v_order_id, item.line_index, item.product_name_raw, item.sku_ref, item.variation,
      GREATEST(COALESCE(item.qty, 1), 1), item.unit_price, item.line_total,
      COALESCE(item.raw_snapshot, '{}'::JSONB), item.product_id
    FROM jsonb_to_recordset(COALESCE(v_order->'items', '[]'::JSONB)) AS item(
      line_index INTEGER, product_name_raw TEXT, sku_ref TEXT, variation TEXT, qty NUMERIC,
      unit_price NUMERIC, line_total NUMERIC, raw_snapshot JSONB, product_id UUID
    );

    v_imported_count := v_imported_count + 1;
    v_imported_order_keys := v_imported_order_keys || jsonb_build_array(jsonb_build_object(
      'channel_code', v_channel_code, 'marketplace_order_no', v_order_no
    ));
  END LOOP;

  UPDATE public.mp_import_batches
  SET order_count = v_imported_count, duplicate_count = v_duplicate_count
  WHERE id = v_batch_id;

  RETURN QUERY SELECT v_batch_id, v_imported_count, v_duplicate_count,
    v_reimported_count, v_tracking_conflict_count, v_imported_order_keys;
END;
$$;


--
-- Name: FUNCTION import_marketplace_orders(p_config_id uuid, p_file_name text, p_row_count integer, p_known_duplicate_count integer, p_orders jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.import_marketplace_orders(p_config_id uuid, p_file_name text, p_row_count integer, p_known_duplicate_count integer, p_orders jsonb) IS 'Atomically imports Marketplace orders, versions cancelled reimports, and rejects active tracking conflicts below RLS.';


--
-- Name: inv_deduct_stock_on_wms_picked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_deduct_stock_on_wms_picked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_product_id UUID;
  v_product_code TEXT;
  v_product_name TEXT;
  v_movement_id UUID;
  v_stock_qty NUMERIC;
  v_already_deducted NUMERIC := 0;
  v_deduct_qty NUMERIC := 0;
  v_on_hand NUMERIC := 0;
  v_reserved NUMERIC := 0;
  v_available_for_row NUMERIC := 0;
BEGIN
  IF NEW.status = 'cancelled' THEN RETURN NEW; END IF;

  SELECT p.id, p.product_code, p.product_name
  INTO v_product_id, v_product_code, v_product_name
  FROM public.pr_products p
  WHERE p.product_code = NEW.product_code
  LIMIT 1;

  IF v_product_id IS NULL THEN RETURN NEW; END IF;
  v_stock_qty := COALESCE(NEW.qty, 0);

  IF NEW.status = 'picked'
     AND (OLD.status IS NULL OR OLD.status NOT IN ('picked', 'correct'))
  THEN
    INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    VALUES (v_product_id, 0, v_stock_qty, 0)
    ON CONFLICT (product_id) DO UPDATE
      SET reserved = COALESCE(public.inv_stock_balances.reserved, 0) + v_stock_qty,
          updated_at = NOW();
  END IF;

  IF NEW.status = 'correct'
     AND (OLD.status IS NULL OR OLD.status <> 'correct')
  THEN
    SELECT COALESCE(SUM(-m.qty) FILTER (
      WHERE m.movement_type IN ('pick', 'pick_reversal')
    ), 0)
    INTO v_already_deducted
    FROM public.inv_stock_movements m
    WHERE m.ref_type = 'wms_orders' AND m.ref_id = NEW.id;

    v_deduct_qty := GREATEST(v_stock_qty - v_already_deducted, 0);

    INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    VALUES (v_product_id, 0, 0, 0)
    ON CONFLICT (product_id) DO NOTHING;

    SELECT COALESCE(b.on_hand, 0), COALESCE(b.reserved, 0)
    INTO v_on_hand, v_reserved
    FROM public.inv_stock_balances b
    WHERE b.product_id = v_product_id
    FOR UPDATE;

    v_available_for_row := v_on_hand - v_reserved
      + CASE WHEN OLD.status = 'picked' THEN v_stock_qty ELSE 0 END;
    IF v_available_for_row < v_deduct_qty THEN
      RAISE EXCEPTION 'สต๊อกพร้อมตัดของสินค้า % - % ไม่เพียงพอ ขาด % %',
        COALESCE(NULLIF(v_product_code, ''), v_product_id::TEXT),
        COALESCE(NULLIF(v_product_name, ''), NEW.product_name, '-'),
        v_deduct_qty - v_available_for_row,
        COALESCE(NULLIF(BTRIM(NEW.unit_name), ''), 'หน่วย');
    END IF;

    IF v_deduct_qty > 0 THEN
      PERFORM public.fn_reconcile_sellable_lots_to_on_hand(v_product_id);

      INSERT INTO public.inv_stock_movements (
        product_id, movement_type, qty, ref_type, ref_id, note
      ) VALUES (
        v_product_id, 'pick', -v_deduct_qty, 'wms_orders', NEW.id,
        'ตัดสต๊อกตามหน่วยสินค้า ' || COALESCE(NULLIF(BTRIM(NEW.unit_name), ''), 'ชิ้น')
      ) RETURNING id INTO v_movement_id;

      PERFORM public.fn_consume_stock_fifo(v_product_id, v_deduct_qty, v_movement_id);

      UPDATE public.inv_stock_balances
      SET on_hand = COALESCE(on_hand, 0) - v_deduct_qty,
          reserved = GREATEST(COALESCE(reserved, 0) - CASE WHEN OLD.status = 'picked' THEN v_stock_qty ELSE 0 END, 0),
          updated_at = NOW()
      WHERE product_id = v_product_id;

      PERFORM public.fn_recalc_product_landed_cost(v_product_id);
    ELSIF OLD.status = 'picked' THEN
      UPDATE public.inv_stock_balances
      SET reserved = GREATEST(COALESCE(reserved, 0) - v_stock_qty, 0),
          updated_at = NOW()
      WHERE product_id = v_product_id;
    END IF;
  END IF;

  IF NEW.status = 'out_of_stock' AND OLD.status = 'picked' THEN
    UPDATE public.inv_stock_balances
    SET reserved = GREATEST(COALESCE(reserved, 0) - v_stock_qty, 0),
        updated_at = NOW()
    WHERE product_id = v_product_id;
  END IF;

  IF NEW.status = 'returned' AND OLD.status IS DISTINCT FROM 'returned' THEN
    IF OLD.status = 'picked' THEN
      UPDATE public.inv_stock_balances
      SET reserved = GREATEST(COALESCE(reserved, 0) - v_stock_qty, 0),
          updated_at = NOW()
      WHERE product_id = v_product_id;
    ELSIF OLD.status = 'correct' THEN
      PERFORM public.fn_reverse_wms_stock(NEW.id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: is_current_user_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_current_user_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT u.is_active
      FROM public.us_users u
      WHERE u.id = auth.uid()
      LIMIT 1
    ),
    FALSE
  );
$$;


--
-- Name: is_current_wms_store_backup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_current_wms_store_backup() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.wms_store_backup_assignments assignment
    JOIN public.us_users app_user ON app_user.id = assignment.user_id
    WHERE assignment.user_id = auth.uid()
      AND assignment.is_active = true
      AND NOW() BETWEEN assignment.starts_at AND assignment.ends_at
      AND app_user.is_active IS DISTINCT FROM false
      AND app_user.role IN ('production', 'qc_staff', 'packing_staff')
  );
$$;


--
-- Name: kb_can_read_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_can_read_item(p_item_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.kb_items item
    WHERE item.id = p_item_id
      AND CASE
        WHEN public.kb_current_role() = 'superadmin' THEN true
        WHEN item.access_level = 'private' THEN false
        WHEN item.access_level = 'general' THEN public.kb_current_role() IS NOT NULL
        WHEN item.access_level = 'restricted' THEN EXISTS (
          SELECT 1 FROM public.kb_item_roles permission
          WHERE permission.item_id = item.id
            AND permission.role = public.kb_current_role()
        )
        ELSE false
      END
  );
$$;


--
-- Name: kb_create_item_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_create_item_version(p_item_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  item_row public.kb_items%ROWTYPE;
  next_version INTEGER;
  new_version_id UUID;
BEGIN
  SELECT * INTO item_row FROM public.kb_items WHERE id = p_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Knowledge item not found'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_item_id::text));
  SELECT COALESCE(MAX(version_no), 0) + 1 INTO next_version
  FROM public.kb_item_versions WHERE item_id = p_item_id;

  INSERT INTO public.kb_item_versions (
    item_id, version_no, title, description, content, category_id, machine_id,
    department_id, access_level, tags, allowed_roles, saved_by
  ) VALUES (
    item_row.id, next_version, item_row.title, item_row.description, item_row.content,
    item_row.category_id, item_row.machine_id, item_row.department_id,
    item_row.access_level, item_row.tags,
    ARRAY(SELECT role FROM public.kb_item_roles WHERE item_id = p_item_id ORDER BY role),
    item_row.updated_by
  ) RETURNING id INTO new_version_id;

  UPDATE public.kb_items SET active_version_id = new_version_id WHERE id = p_item_id;
  RETURN next_version;
END;
$$;


--
-- Name: kb_current_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_current_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT role FROM public.us_users
  WHERE id = auth.uid() AND COALESCE(is_active, true) = true
  LIMIT 1;
$$;


--
-- Name: kb_is_knowledge_manager(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_is_knowledge_manager() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT COALESCE(public.kb_current_role() IN ('superadmin', 'admin'), false); $$;


--
-- Name: kb_is_superadmin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_is_superadmin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid()
      AND role IN ('superadmin', 'admin')
      AND COALESCE(is_active, true) = true
  );
$$;


--
-- Name: kb_set_item_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_set_item_defaults() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.knowledge_code IS NULL OR btrim(NEW.knowledge_code) = '' THEN
    NEW.knowledge_code := 'KB-' || lpad(nextval('public.kb_knowledge_code_seq')::text, 6, '0');
  END IF;
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;


--
-- Name: kb_set_task_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_set_task_defaults() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.task_code IS NULL OR btrim(NEW.task_code) = '' THEN
    NEW.task_code := 'TASK-' || lpad(nextval('public.kb_task_code_seq')::text, 6, '0');
  END IF;
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;


