-- Name: kb_touch_category(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kb_touch_category() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
