--
-- Name: latest_purchase_prices_for_po(uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.latest_purchase_prices_for_po(p_product_ids uuid[], p_supplier_id uuid DEFAULT NULL::uuid) RETURNS TABLE(product_id uuid, unit_price numeric, po_no text, ordered_at timestamp with time zone, supplier_id uuid, supplier_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.erp_can_view_cost() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูราคาซื้อ';
  END IF;
  RETURN QUERY
  SELECT DISTINCT ON (i.product_id)
    i.product_id, i.unit_price::numeric, p.po_no::text,
    p.ordered_at::timestamptz, p.supplier_id, p.supplier_name::text
  FROM public.inv_po_items i JOIN public.inv_po p ON p.id = i.po_id
  WHERE i.product_id = ANY(p_product_ids)
    AND p.status IN ('ordered', 'partial', 'received', 'closed')
    AND p.ordered_at IS NOT NULL AND i.unit_price IS NOT NULL
  ORDER BY i.product_id,
    coalesce(p.supplier_id = p_supplier_id, false) DESC,
    p.ordered_at DESC, p.created_at DESC, p.id DESC, i.id DESC;
END;
$$;


--
-- Name: link_marketplace_bill_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_marketplace_bill_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.billed_order_id IS NOT NULL THEN
    UPDATE public.or_orders SET source_marketplace_order_id=NEW.id
    WHERE id=NEW.billed_order_id AND source_marketplace_order_id IS NULL;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: list_unread_order_chat_summaries(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_unread_order_chat_summaries(p_user_id uuid, p_role text, p_username text) RETURNS TABLE(order_id uuid, bill_no text, customer_name text, unread_count bigint, last_message_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text := lower(btrim(coalesce(p_role, '')));
  v_confirm_statuses text[] := ARRAY[
    'ตรวจสอบแล้ว',
    'ไม่ต้องออกแบบ',
    'รอออกแบบ',
    'ออกแบบแล้ว',
    'รอคอนเฟิร์ม',
    'คอนเฟิร์มแล้ว'
  ]::text[];
BEGIN
  IF v_role IN ('superadmin', 'admin') THEN
    RETURN QUERY
    SELECT o.id, o.bill_no, o.customer_name,
           count(m.id)::bigint,
           max(m.created_at)
    FROM or_order_chat_logs m
    JOIN or_orders o ON o.id = m.order_id
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz)
    GROUP BY o.id, o.bill_no, o.customer_name
    ORDER BY max(m.created_at) DESC;

  ELSIF v_role = 'sales-tr' THEN
    RETURN QUERY
    SELECT o.id, o.bill_no, o.customer_name,
           count(m.id)::bigint,
           max(m.created_at)
    FROM or_order_chat_logs m
    JOIN or_orders o ON o.id = m.order_id
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz)
      AND o.status IS NOT NULL
      AND o.status = ANY(v_confirm_statuses)
      AND (
        o.channel_code = 'PUMP'
        OR (
          COALESCE(o.requires_confirm_design, false) = true
          AND o.channel_code IS DISTINCT FROM 'PUMP'
        )
      )
      AND o.admin_user IN (
        SELECT DISTINCT TRIM(u.username) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.username IS NOT NULL AND TRIM(u.username) <> ''
        UNION
        SELECT DISTINCT TRIM(u.email) FROM us_users u
        WHERE u.role = 'sales-tr' AND u.email IS NOT NULL AND TRIM(u.email) <> ''
      )
    GROUP BY o.id, o.bill_no, o.customer_name
    ORDER BY max(m.created_at) DESC;

  ELSIF v_role IN ('sales-pump') THEN
    RETURN QUERY
    SELECT o.id, o.bill_no, o.customer_name,
           count(m.id)::bigint,
           max(m.created_at)
    FROM or_order_chat_logs m
    JOIN or_orders o ON o.id = m.order_id
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz)
      AND (
        _sales_pump_order_owned_by_session(o.admin_user, p_user_id)
        OR EXISTS (
          SELECT 1 FROM or_order_chat_logs mp
          WHERE mp.order_id = o.id
            AND mp.sender_id = p_user_id
            AND COALESCE(mp.is_hidden, false) = false
        )
      )
    GROUP BY o.id, o.bill_no, o.customer_name
    ORDER BY max(m.created_at) DESC;

  ELSIF v_role = 'production' THEN
    RETURN QUERY
    SELECT o.id, o.bill_no, o.customer_name,
           count(m.id)::bigint,
           max(m.created_at)
    FROM or_order_chat_logs m
    JOIN or_orders o ON o.id = m.order_id
    LEFT JOIN or_order_chat_reads r ON r.order_id = m.order_id AND r.user_id = p_user_id
    WHERE COALESCE(m.is_hidden, false) = false
      AND m.sender_id <> p_user_id
      AND m.created_at > COALESCE(r.last_read_at, '1970-01-01'::timestamptz)
      AND o.status IS NOT NULL
      AND o.status = ANY(v_confirm_statuses)
      AND (
        o.channel_code = 'PUMP'
        OR (
          COALESCE(o.requires_confirm_design, false) = true
          AND o.channel_code IS DISTINCT FROM 'PUMP'
        )
      )
    GROUP BY o.id, o.bill_no, o.customer_name
    ORDER BY max(m.created_at) DESC;
  END IF;

  RETURN;
END;
$$;


--
-- Name: manual_slip_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manual_slip_decide(p_order_id uuid, p_action text, p_rejected_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_order public.or_orders;
  v_actor TEXT;
  v_role TEXT;
  v_owner_role TEXT;
  v_new_order_status TEXT;
  v_count INTEGER;
  v_duplicate_bill_no TEXT;
  v_eligibility JSONB;
BEGIN
  SELECT role, COALESCE(NULLIF(trim(username), ''), NULLIF(trim(email), ''), auth.uid()::TEXT)
  INTO v_role, v_actor
  FROM public.us_users
  WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตัดสินผลตรวจสลิปมือ';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'ผลการตรวจสลิปไม่ถูกต้อง';
  END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิลที่ต้องการตรวจ'; END IF;
  IF v_order.status = 'ยกเลิก' THEN
    RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว ไม่สามารถอนุมัติหรือปฏิเสธได้';
  END IF;

  IF p_action = 'approved' THEN
    v_eligibility := public.manual_slip_submission_eligibility(p_order_id);
    IF COALESCE((v_eligibility->>'allowed')::BOOLEAN, FALSE) = FALSE
       AND v_eligibility->>'reason' = 'exact_trans_ref_duplicate'
    THEN
      RAISE EXCEPTION 'สลิปนี้ถูกใช้แล้วในบิล % ไม่สามารถอนุมัติตรวจมือได้',
        COALESCE(v_eligibility->>'duplicate_bill_no', '-');
    END IF;

    SELECT duplicate_order.bill_no
    INTO v_duplicate_bill_no
    FROM public.ac_manual_slip_checks pending
    JOIN public.ac_verified_slips slip
      ON slip.order_id <> pending.order_id
     AND COALESCE(slip.is_deleted, FALSE) = FALSE
     AND slip.easyslip_date IS NOT NULL
     AND slip.validation_status = 'passed'
     AND ABS(slip.verified_amount - pending.transfer_amount) <= 0.01
     AND date_trunc('minute', slip.easyslip_date)
         = date_trunc('minute', (pending.transfer_date || ' ' || pending.transfer_time)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
    JOIN public.or_orders duplicate_order ON duplicate_order.id = slip.order_id
    WHERE pending.order_id = p_order_id
      AND pending.status = 'pending'
      AND pending.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      AND pending.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      AND COALESCE(duplicate_order.status, '') NOT IN (
        'รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก'
      )
    ORDER BY slip.created_at DESC
    LIMIT 1;

    IF v_duplicate_bill_no IS NOT NULL THEN
      RAISE EXCEPTION 'ยอดและเวลาโอนตรงกับ EasySlip ที่ใช้ในบิล % ไม่สามารถอนุมัติตรวจมือได้', v_duplicate_bill_no;
    END IF;
  END IF;

  UPDATE public.ac_manual_slip_checks
  SET status = p_action,
      reviewed_by = v_actor,
      reviewed_at = now(),
      rejected_reason = CASE WHEN p_action = 'rejected' THEN NULLIF(trim(p_rejected_reason), '') ELSE NULL END
  WHERE order_id = p_order_id AND status = 'pending';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN RAISE EXCEPTION 'ไม่พบคำขอตรวจสลิปที่รอดำเนินการ'; END IF;

  SELECT u.role INTO v_owner_role
  FROM public.us_users u
  WHERE u.username = v_order.admin_user OR u.email = v_order.admin_user
  ORDER BY (u.username = v_order.admin_user) DESC NULLS LAST
  LIMIT 1;

  v_new_order_status := CASE
    WHEN p_action = 'rejected' THEN 'ตรวจสอบไม่ผ่าน'
    WHEN upper(trim(v_order.channel_code)) = 'WY' THEN 'ตรวจสอบแล้ว'
    WHEN v_owner_role = 'sales-tr' AND (
      (v_order.channel_code = 'PUMP' AND v_order.requires_confirm_design = FALSE)
      OR (v_order.channel_code IS DISTINCT FROM 'PUMP' AND COALESCE(v_order.requires_confirm_design, FALSE) = FALSE)
    ) THEN 'รอตรวจคำสั่งซื้อ'
    WHEN v_order.channel_code = 'PUMP' AND v_order.requires_confirm_design = FALSE THEN 'ไม่ต้องออกแบบ'
    ELSE 'ตรวจสอบแล้ว'
  END;
  UPDATE public.or_orders SET status = v_new_order_status WHERE id = p_order_id;

  RETURN jsonb_build_object('updated_count', v_count, 'order_status', v_new_order_status);
END;
$_$;


--
-- Name: manual_slip_exact_duplicate_orders(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manual_slip_exact_duplicate_orders(p_order_ids uuid[]) RETURNS TABLE(order_id uuid, duplicate_order_id uuid, duplicate_bill_no text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT ON (current_slip.order_id)
    current_slip.order_id,
    used_slip.order_id,
    used_order.bill_no
  FROM public.ac_verified_slips current_slip
  JOIN public.ac_verified_slips used_slip
    ON NULLIF(trim(used_slip.easyslip_trans_ref), '') = NULLIF(trim(current_slip.easyslip_trans_ref), '')
   AND used_slip.order_id <> current_slip.order_id
   AND COALESCE(used_slip.is_deleted, false) = false
  JOIN public.or_orders used_order ON used_order.id = used_slip.order_id
  WHERE current_slip.order_id = ANY(COALESCE(p_order_ids, ARRAY[]::UUID[]))
    AND COALESCE(current_slip.is_deleted, false) = false
    AND NULLIF(trim(current_slip.easyslip_trans_ref), '') IS NOT NULL
    AND COALESCE(used_order.status, '') NOT IN ('รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก')
    AND EXISTS (
      SELECT 1 FROM public.us_users actor
      WHERE actor.id = auth.uid()
        AND actor.role IN ('superadmin', 'admin', 'account', 'sales-tr', 'sales-pump', 'qc_order')
    )
  ORDER BY current_slip.order_id, used_slip.created_at DESC;
$$;


--
-- Name: manual_slip_find_duplicates(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manual_slip_find_duplicates(p_order_id uuid, p_entries jsonb) RETURNS TABLE(entry_index integer, duplicate_order_id uuid, duplicate_bill_no text, easyslip_date timestamp with time zone, verified_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_valid_entry_count INTEGER;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.us_users actor
    WHERE actor.id = auth.uid()
      AND actor.role IN ('superadmin', 'admin', 'account')
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจสอบสลิปมือ';
  END IF;

  IF p_order_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.or_orders o WHERE o.id = p_order_id
  ) THEN
    RAISE EXCEPTION 'ไม่พบบิลที่ต้องการตรวจ';
  END IF;

  IF p_entries IS NULL
     OR jsonb_typeof(p_entries) <> 'array'
     OR jsonb_array_length(p_entries) < 1
     OR jsonb_array_length(p_entries) > 20
  THEN
    RAISE EXCEPTION 'ข้อมูลสลิปต้องมี 1 ถึง 20 รายการ';
  END IF;

  SELECT COUNT(*)
  INTO v_valid_entry_count
  FROM jsonb_to_recordset(p_entries) AS input(
    entry_index INTEGER,
    transfer_date TEXT,
    transfer_time TEXT,
    transfer_amount NUMERIC
  )
  WHERE input.entry_index IS NOT NULL
    AND BTRIM(input.transfer_date) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    AND BTRIM(input.transfer_time) ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    AND input.transfer_amount >= 0;

  IF v_valid_entry_count <> jsonb_array_length(p_entries) THEN
    RAISE EXCEPTION 'วันที่ เวลา หรือยอดโอนที่ใช้ตรวจสอบไม่ถูกต้อง';
  END IF;

  RETURN QUERY
  WITH raw_input AS (
    SELECT
      input.entry_index,
      BTRIM(input.transfer_date) AS transfer_date,
      BTRIM(input.transfer_time) AS transfer_time,
      input.transfer_amount
    FROM jsonb_to_recordset(p_entries) AS input(
      entry_index INTEGER,
      transfer_date TEXT,
      transfer_time TEXT,
      transfer_amount NUMERIC
    )
  ), normalized_input AS (
    SELECT
      input.entry_index,
      input.transfer_amount,
      (input.transfer_date || ' ' || input.transfer_time)::TIMESTAMP
        AT TIME ZONE 'Asia/Bangkok' AS transfer_minute
    FROM raw_input input
    WHERE input.entry_index IS NOT NULL
      AND input.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      AND input.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      AND input.transfer_amount >= 0
  )
  SELECT
    input.entry_index,
    slip.order_id AS duplicate_order_id,
    duplicate_order.bill_no AS duplicate_bill_no,
    slip.easyslip_date,
    slip.verified_amount
  FROM normalized_input input
  JOIN public.ac_verified_slips slip
    ON slip.easyslip_date >= input.transfer_minute
   AND slip.easyslip_date < input.transfer_minute + INTERVAL '1 minute'
   AND slip.verified_amount BETWEEN input.transfer_amount - 0.01 AND input.transfer_amount + 0.01
   AND slip.order_id <> p_order_id
   AND COALESCE(slip.is_deleted, false) = false
  JOIN public.or_orders duplicate_order ON duplicate_order.id = slip.order_id
  WHERE COALESCE(duplicate_order.status, '') NOT IN (
    'รอลงข้อมูล', 'ลงข้อมูลผิด', 'ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ', 'ยกเลิก'
  )
  ORDER BY input.entry_index, slip.created_at DESC, slip.id;
END;
$_$;


--
-- Name: FUNCTION manual_slip_find_duplicates(p_order_id uuid, p_entries jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.manual_slip_find_duplicates(p_order_id uuid, p_entries jsonb) IS 'Finds used slips matching manual date, Bangkok minute and amount without returning full slip history or EasySlip payloads.';


--
-- Name: manual_slip_revoke_approval(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manual_slip_revoke_approval(p_order_id uuid, p_slip_ids uuid[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor text; v_order public.or_orders; v_ids uuid[]; v_count integer;
BEGIN
  SELECT coalesce(nullif(trim(username),''),email,id::text) INTO v_actor
    FROM public.us_users WHERE id=auth.uid() AND role='superadmin';
  IF NOT FOUND THEN RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้นที่ยกเลิกการอนุมัติสลิปมือได้'; END IF;
  IF nullif(trim(p_reason),'') IS NULL OR length(p_reason)>1000 THEN
    RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ยกเลิกการอนุมัติ (ไม่เกิน 1,000 ตัวอักษร)';
  END IF;
  -- Match the parent-first locking used by payment reuse and manual decisions.
  SELECT * INTO v_order FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
  IF v_order.status IN ('ยกเลิก','จัดส่งแล้ว') OR v_order.shipped_time IS NOT NULL
    OR v_order.work_order_id IS NOT NULL OR nullif(trim(v_order.work_order_name),'') IS NOT NULL THEN
    RAISE EXCEPTION 'บิลถูกยกเลิก เข้าใบงาน หรือจัดส่งแล้ว ไม่สามารถยกเลิกการอนุมัติสลิปมือได้';
  END IF;
  PERFORM id FROM public.ac_manual_slip_checks WHERE order_id=p_order_id ORDER BY id FOR UPDATE;
  SELECT array_agg(id ORDER BY id) INTO v_ids FROM public.ac_manual_slip_checks
    WHERE order_id=p_order_id AND status='approved' AND duplicate_of IS NULL;
  IF coalesce(cardinality(v_ids),0)=0 THEN RAISE EXCEPTION 'ไม่พบสลิปมือที่อนุมัติแล้ว กรุณารีเฟรช'; END IF;
  IF p_slip_ids IS NULL OR cardinality(p_slip_ids)<>cardinality(v_ids)
    OR NOT (p_slip_ids @> v_ids AND v_ids @> p_slip_ids) THEN
    RAISE EXCEPTION 'รายการสลิปเปลี่ยนแปลงแล้ว กรุณารีเฟรชและตรวจสอบอีกครั้ง';
  END IF;
  IF EXISTS(SELECT 1 FROM public.ac_manual_slip_checks WHERE order_id=p_order_id AND status='pending') THEN
    RAISE EXCEPTION 'มีรายการรอตรวจสลิปมือ กรุณาจัดการรายการรอตรวจก่อน';
  END IF;
  IF EXISTS(SELECT 1 FROM public.ac_bank_reconciliation_allocations WHERE order_id=p_order_id)
    OR EXISTS(SELECT 1 FROM public.ac_order_receipt_certifications WHERE order_id=p_order_id AND revoked_at IS NULL) THEN
    RAISE EXCEPTION 'บิลนี้มีการจับคู่กระทบยอดหรือรับรองเงินรับแล้ว กรุณายกเลิกการจับคู่หรือการรับรองก่อน';
  END IF;
  UPDATE public.ac_manual_slip_checks
    SET status='rejected', rejected_reason='ยกเลิกการอนุมัติ: '||trim(p_reason),
      approval_revoked_at=now(), approval_revoked_by=auth.uid(),
      approval_revoked_by_name=v_actor, approval_revoked_reason=trim(p_reason)
    WHERE id=ANY(v_ids) AND status='approved';
  GET DIAGNOSTICS v_count=ROW_COUNT;
  -- Do not rewind order/production status or remove verified EasySlip evidence.
  RETURN jsonb_build_object('revoked_count',v_count,'order_status',v_order.status);
END $$;


--
-- Name: manual_slip_submission_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manual_slip_submission_eligibility(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order public.or_orders;
  v_duplicate RECORD;
  v_has_duplicate_badge BOOLEAN := false;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.us_users actor
    WHERE actor.id = auth.uid()
      AND actor.role IN ('superadmin', 'admin', 'account', 'sales-tr', 'sales-pump', 'qc_order')
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจสอบสถานะส่งสลิปมือ';
  END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิลที่ต้องการส่งตรวจ'; END IF;

  IF v_order.status = 'ยกเลิก' THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'cancelled_order');
  END IF;

  SELECT * INTO v_duplicate
  FROM public.manual_slip_exact_duplicate_orders(ARRAY[p_order_id])
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'exact_trans_ref_duplicate',
      'duplicate_order_id', v_duplicate.duplicate_order_id,
      'duplicate_bill_no', v_duplicate.duplicate_bill_no
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.ac_verified_slips s
    WHERE s.order_id = p_order_id
      AND COALESCE(s.is_deleted, false) = false
      AND EXISTS (
        SELECT 1 FROM unnest(COALESCE(s.validation_errors, ARRAY[]::TEXT[])) err
        WHERE err ILIKE '%สลิปซ้ำ%'
      )
  ) INTO v_has_duplicate_badge;

  RETURN jsonb_build_object(
    'allowed', true,
    'reason', CASE WHEN v_has_duplicate_badge THEN 'fallback_duplicate_review' ELSE 'normal' END,
    'requires_exception_review', v_has_duplicate_badge
  );
END;
$$;


--
-- Name: manual_slip_submit(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manual_slip_submit(p_order_id uuid, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_order public.or_orders;
  v_actor TEXT;
  v_role TEXT;
  v_eligibility JSONB;
  v_kind TEXT;
  v_count INTEGER;
BEGIN
  SELECT role, COALESCE(NULLIF(trim(username), ''), NULLIF(trim(email), ''), auth.uid()::TEXT)
  INTO v_role, v_actor
  FROM public.us_users
  WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account', 'sales-tr', 'sales-pump') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ส่งตรวจสลิปมือ';
  END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิลที่ต้องการส่งตรวจ'; END IF;

  v_eligibility := public.manual_slip_submission_eligibility(p_order_id);
  IF COALESCE((v_eligibility->>'allowed')::BOOLEAN, false) = false THEN
    IF v_eligibility->>'reason' = 'exact_trans_ref_duplicate' THEN
      RAISE EXCEPTION 'สลิปนี้ถูกใช้แล้วในบิล % ไม่สามารถส่งตรวจสลิปมือได้', COALESCE(v_eligibility->>'duplicate_bill_no', '-');
    END IF;
    RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว ไม่สามารถส่งตรวจสลิปมือได้';
  END IF;

  IF EXISTS (SELECT 1 FROM public.ac_manual_slip_checks WHERE order_id = p_order_id AND status = 'pending') THEN
    RAISE EXCEPTION 'บิลนี้มีคำขอตรวจสลิปมือที่รอดำเนินการอยู่แล้ว';
  END IF;
  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array'
     OR jsonb_array_length(p_entries) < 1 OR jsonb_array_length(p_entries) > 20 THEN
    RAISE EXCEPTION 'ข้อมูลสลิปต้องมี 1 ถึง 20 รายการ';
  END IF;

  v_kind := CASE WHEN COALESCE((v_eligibility->>'requires_exception_review')::BOOLEAN, false)
    THEN 'duplicate_fallback_review' ELSE 'manual' END;

  INSERT INTO public.ac_manual_slip_checks (
    order_id, bill_no, transfer_date, transfer_time, transfer_amount,
    submitted_by, status, submission_kind
  )
  SELECT
    p_order_id,
    v_order.bill_no,
    trim(entry.transfer_date),
    trim(entry.transfer_time),
    entry.transfer_amount,
    v_actor,
    'pending',
    v_kind
  FROM jsonb_to_recordset(p_entries) AS entry(
    transfer_date TEXT,
    transfer_time TEXT,
    transfer_amount NUMERIC
  )
  WHERE entry.transfer_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    AND entry.transfer_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    AND entry.transfer_amount > 0;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> jsonb_array_length(p_entries) THEN
    RAISE EXCEPTION 'วันที่ เวลา หรือยอดโอนในคำขอไม่ถูกต้อง';
  END IF;

  RETURN jsonb_build_object(
    'inserted_count', v_count,
    'submission_kind', v_kind,
    'requires_exception_review', v_kind = 'duplicate_fallback_review'
  );
END;
$_$;


--
-- Name: mark_refund_slip_sent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_refund_slip_sent(p_refund_id uuid) RETURNS TABLE(refund_slip_sent_at timestamp with time zone, refund_slip_sent_by uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actor public.us_users%ROWTYPE;
  refund public.ac_refunds%ROWTYPE;
  order_owner text;
BEGIN
  SELECT * INTO actor FROM public.us_users WHERE id = auth.uid();
  IF actor.id IS NULL OR coalesce(actor.role, '') NOT IN ('sales-tr', 'sales-pump', 'admin', 'superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันส่งสลิปโอนคืน';
  END IF;

  SELECT * INTO refund FROM public.ac_refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบรายการโอนคืน';
  END IF;
  SELECT btrim(o.admin_user) INTO order_owner FROM public.or_orders o WHERE o.id = refund.order_id;

  IF actor.role = 'sales-pump' AND NOT (
    coalesce(nullif(btrim(actor.username), '') = order_owner, false)
    OR coalesce(nullif(btrim(actor.email), '') = order_owner, false)
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันรายการโอนคืนของผู้อื่น';
  END IF;
  IF actor.role = 'sales-tr' AND NOT EXISTS (
    SELECT 1 FROM public.us_users u
    WHERE u.role = 'sales-tr' AND (
      nullif(btrim(u.username), '') = order_owner
      OR nullif(btrim(u.email), '') = order_owner
    )
  ) THEN
    RAISE EXCEPTION 'รายการโอนคืนนี้อยู่นอกทีม Sales TR';
  END IF;
  IF coalesce(refund.status, '') <> 'approved' OR coalesce(cardinality(refund.refund_slip_paths), 0) = 0 THEN
    RAISE EXCEPTION 'บัญชีต้องอนุมัติและแนบสลิปโอนคืนก่อน';
  END IF;

  -- Repeated confirmation preserves the original sender and timestamp.
  IF refund.refund_slip_sent_at IS NULL THEN
    UPDATE public.ac_refunds r
    SET refund_slip_sent_at = now(), refund_slip_sent_by = actor.id
    WHERE r.id = p_refund_id
    RETURNING r.* INTO refund;
  END IF;
  RETURN QUERY SELECT refund.refund_slip_sent_at, refund.refund_slip_sent_by;
END;
$$;


--
-- Name: marketplace_correction_errors(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_correction_errors(p_order_id uuid, p_item_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_review jsonb; v_index integer;
BEGIN
  SELECT error_fields INTO v_review FROM public.or_order_reviews
    WHERE order_id=p_order_id AND status='rejected' ORDER BY reviewed_at DESC LIMIT 1;
  v_review:=coalesce(v_review,'{}'::jsonb);
  IF p_item_id IS NULL THEN RETURN v_review; END IF;
  IF jsonb_typeof(v_review->'item_ids')='array' THEN
    SELECT ordinality::integer-1 INTO v_index
      FROM jsonb_array_elements_text(v_review->'item_ids') WITH ORDINALITY
      WHERE value=p_item_id::text;
  ELSE
    SELECT position INTO v_index FROM (
      SELECT id,(row_number() OVER(ORDER BY coalesce(sort_order::bigint,
        substring(item_uid from '-([0-9]+)$')::bigint),created_at,id)-1)::integer AS position
      FROM public.or_order_items WHERE order_id=p_order_id
    ) positions WHERE id=p_item_id;
  END IF;
  RETURN (v_review-'items'-'item_ids') || coalesce(v_review->'items'->v_index,'{}'::jsonb);
END $_$;


--
-- Name: marketplace_product_field_enabled(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_product_field_enabled(p_product_id uuid, p_field text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(
    CASE WHEN p_field=ANY(coalesce(ov.required_fields,'{}'::text[])) THEN true
         ELSE (to_jsonb(ov)->>p_field)::boolean END,
    (to_jsonb(c)->>p_field)::boolean, true)
  FROM public.pr_products p
  LEFT JOIN public.pr_product_field_overrides ov ON ov.product_id=p.id
  LEFT JOIN public.pr_category_field_settings c ON c.category=btrim(p.product_category)
  WHERE p.id=p_product_id
$$;


--
-- Name: merge_plan_tracks(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_plan_tracks(p_job_id text, p_dept text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_current_tracks JSONB;
  v_dept_tracks    JSONB;
  v_proc           TEXT;
  v_proc_patch     JSONB;
  v_current_proc   JSONB;
  v_result         JSONB;
BEGIN
  -- Lock the row to prevent concurrent writes
  SELECT COALESCE(tracks, '{}'::jsonb)
    INTO v_current_tracks
    FROM plan_jobs
   WHERE id = p_job_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE WARNING 'merge_plan_tracks: plan_job id=% not found', p_job_id;
    RETURN NULL;
  END IF;

  v_dept_tracks := COALESCE(v_current_tracks -> p_dept, '{}'::jsonb);

  FOR v_proc IN SELECT jsonb_object_keys(p_patch)
  LOOP
    v_proc_patch  := p_patch -> v_proc;
    v_current_proc := COALESCE(v_dept_tracks -> v_proc,
                               '{"start":null,"end":null}'::jsonb);

    -- start_if_null: set start only when current value IS NULL
    IF v_proc_patch ? 'start_if_null'
       AND (v_current_proc ->> 'start') IS NULL THEN
      v_current_proc := jsonb_set(v_current_proc, '{start}',
                                  v_proc_patch -> 'start_if_null');
    END IF;

    -- explicit start (always overwrites)
    IF v_proc_patch ? 'start' THEN
      v_current_proc := jsonb_set(v_current_proc, '{start}',
                                  v_proc_patch -> 'start');
    END IF;

    -- explicit end (always overwrites)
    IF v_proc_patch ? 'end' THEN
      v_current_proc := jsonb_set(v_current_proc, '{end}',
                                  v_proc_patch -> 'end');
    END IF;

    v_dept_tracks := jsonb_set(v_dept_tracks, ARRAY[v_proc],
                               v_current_proc, true);
  END LOOP;

  v_result := jsonb_set(v_current_tracks, ARRAY[p_dept],
                         v_dept_tracks, true);

  -- Keep the row lock and merge semantics, but emit no UPDATE/WAL/Realtime
  -- when start_if_null or a retry did not change the stored tracks.
  IF v_result IS DISTINCT FROM v_current_tracks THEN
    UPDATE plan_jobs SET tracks = v_result WHERE id = p_job_id;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: merge_plan_tracks_by_name(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_plan_tracks_by_name(p_job_name text, p_dept text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job_id TEXT;
  v_count  INT;
BEGIN
  SELECT count(*) INTO v_count
    FROM plan_jobs
   WHERE name = p_job_name;

  IF v_count = 0 THEN
    RAISE WARNING 'merge_plan_tracks_by_name: no plan_job with name=%', p_job_name;
    RETURN NULL;
  END IF;

  IF v_count > 1 THEN
    RAISE WARNING 'merge_plan_tracks_by_name: % rows for name=%, using latest date',
                  v_count, p_job_name;
  END IF;

  SELECT id INTO v_job_id
    FROM plan_jobs
   WHERE name = p_job_name
   ORDER BY date DESC
   LIMIT 1;

  RETURN merge_plan_tracks(v_job_id, p_dept, p_patch);
END;
$$;


--
-- Name: merge_plan_tracks_by_work_order_id(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_plan_tracks_by_work_order_id(p_work_order_id uuid, p_dept text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job_id TEXT;
  v_count  INT;
BEGIN
  IF p_work_order_id IS NULL THEN
    RAISE EXCEPTION 'ต้องระบุ work_order_id';
  END IF;

  SELECT count(*) INTO v_count
    FROM plan_jobs
   WHERE work_order_id = p_work_order_id;

  IF v_count = 0 THEN
    RAISE WARNING 'merge_plan_tracks_by_work_order_id: no plan_job with work_order_id=%', p_work_order_id;
    RETURN NULL;
  END IF;

  SELECT id INTO v_job_id
    FROM plan_jobs
   WHERE work_order_id = p_work_order_id
   ORDER BY date DESC
   LIMIT 1;

  RETURN merge_plan_tracks(v_job_id, p_dept, p_patch);
END;
$$;


--
-- Name: mp_can_assign_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_can_assign_orders() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.us_users AS u
    WHERE u.id = auth.uid()
      AND u.is_active = TRUE
      AND (
        u.role = 'superadmin'
        OR EXISTS (
          SELECT 1
          FROM public.mp_assigner_permissions AS permission
          WHERE permission.user_id = u.id
            AND permission.can_assign = TRUE
        )
      )
  );
$$;


--
-- Name: mp_can_manage_new_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_can_manage_new_orders() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.us_users AS u
    LEFT JOIN public.st_user_menus AS menu
      ON menu.role = u.role
     AND menu.menu_key = 'marketplace-new'
    WHERE u.id = auth.uid()
      AND u.is_active = TRUE
      AND u.role <> 'sales-pump'
      AND (
        u.role = 'superadmin'
        OR COALESCE(menu.has_access, FALSE)
        OR public.mp_can_assign_orders()
      )
  );
$$;


--
-- Name: normalize_claim_billing_details(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_claim_billing_details(p_details jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB := '{}'::jsonb;
  v_part JSONB;
BEGIN
  IF jsonb_typeof(p_details) = 'object' THEN
    RETURN p_details;
  END IF;
  IF jsonb_typeof(p_details) = 'array' THEN
    FOR v_part IN SELECT value FROM jsonb_array_elements(p_details) WITH ORDINALITY AS parts(value, seq) ORDER BY seq
    LOOP
      IF jsonb_typeof(v_part) = 'object' THEN
        v_result := v_result || v_part;
      END IF;
    END LOOP;
  END IF;
  RETURN v_result;
END;
$$;


--
-- Name: normalize_shop_pickup_tracking_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_shop_pickup_tracking_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_default_method TEXT;
BEGIN
  IF NEW.fulfillment_method IS NULL THEN
    SELECT CASE WHEN COALESCE(c.is_self_pickup, false) THEN 'self_pickup' ELSE 'shipping' END
    INTO v_default_method
    FROM public.channels c
    WHERE c.channel_code = NEW.channel_code;
    NEW.fulfillment_method := COALESCE(v_default_method, 'shipping');
  END IF;

  IF NEW.fulfillment_method = 'self_pickup' THEN
    NEW.tracking_number := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: or_apply_payment_review_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_apply_payment_review_status(p_order_id uuid, p_status text, p_source text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text;
BEGIN
  IF p_source IS NULL OR p_source NOT IN ('easyslip','overpayment_request','order_review') THEN
    RAISE EXCEPTION 'ไม่รู้จักขั้นตอนเปลี่ยนสถานะ';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ','ตรวจสอบแล้ว','รอตรวจคำสั่งซื้อ',
    'ไม่ต้องออกแบบ','รอคอนเฟิร์ม','ใบสั่งงาน','ลงข้อมูลผิด') THEN
    RAISE EXCEPTION 'สถานะไม่ใช่ขั้นตอนตรวจข้อมูล/ชำระเงิน';
  END IF;
  PERFORM set_config('app.order_status_source',p_source,true);
  UPDATE public.or_orders SET status=p_status WHERE id=p_order_id RETURNING status INTO v_status;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิลหรือไม่มีสิทธิ์แก้ไข'; END IF;
  RETURN v_status;
END $$;


--
-- Name: or_approved_claim_financials(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_approved_claim_financials(p_order_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object('request_id',c.id,
    'price',COALESCE((s.value->>'price')::NUMERIC,
      greatest(0,(s.value->>'total_amount')::NUMERIC-COALESCE((s.value->>'shipping_cost')::NUMERIC,0)
        +COALESCE((s.value->>'discount')::NUMERIC,0))),
    'shipping_cost',COALESCE((s.value->>'shipping_cost')::NUMERIC,0),
    'discount',COALESCE((s.value->>'discount')::NUMERIC,0),
    'total_amount',greatest(0,COALESCE((s.value->>'total_amount')::NUMERIC,
      COALESCE((s.value->>'price')::NUMERIC,0)
      +COALESCE((s.value->>'shipping_cost')::NUMERIC,0)
      -COALESCE((s.value->>'discount')::NUMERIC,0))))
  FROM public.or_orders o
  JOIN public.or_claim_requests c ON c.created_claim_order_id=o.id AND c.status='approved'
  CROSS JOIN LATERAL (SELECT c.proposed_snapshot->'order' value) s
  WHERE o.id=p_order_id AND upper(COALESCE(o.bill_no,'')) LIKE 'REQ%'
    AND jsonb_typeof(s.value)='object' AND COALESCE(s.value->>'price',s.value->>'total_amount') IS NOT NULL
  ORDER BY c.reviewed_at DESC NULLS LAST,c.created_at DESC,c.id DESC LIMIT 1
$$;


--
-- Name: or_approved_overpayment_amount(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_approved_overpayment_amount(p_order_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT coalesce((SELECT sum(amount) FROM ac_refunds WHERE order_id=p_order_id AND status='approved' AND reason ILIKE '%โอนเกิน%'),0)
   +public.or_approved_waiver_amount(p_order_id)
$$;


--
-- Name: or_approved_waiver_amount(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_approved_waiver_amount(p_order_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT coalesce(sum(w.amount),0) FROM ac_overpayment_waivers w JOIN or_orders o ON o.id=w.order_id
 WHERE w.order_id=p_order_id AND w.status='approved' AND w.order_total=o.receivable_amount
   AND w.paid_amount=public.or_overpayment_paid(o.id)
$$;


--
-- Name: or_audit_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_audit_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    SELECT coalesce(username,email) INTO v_actor FROM public.us_users WHERE id=auth.uid();
    INSERT INTO public.or_order_status_history(order_id,bill_no,previous_status,requested_status,
      resulting_status,event_type,actor_id,actor_name,source,reason)
    VALUES(NEW.id,NEW.bill_no,OLD.status,NEW.status,NEW.status,'changed',auth.uid(),
      coalesce(v_actor,current_user),coalesce(nullif(current_setting('app.order_status_source',true),''),'order_update'),
      nullif(current_setting('app.order_status_reason',true),''));
  END IF;
  RETURN NEW;
END $$;


--
-- Name: or_cancel_shipping_conversion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_cancel_shipping_conversion(p_request_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r text; q public.or_shipping_conversion_requests;
BEGIN
 SELECT role INTO r FROM public.us_users WHERE id=auth.uid();
 SELECT * INTO q FROM public.or_shipping_conversion_requests WHERE id=p_request_id FOR UPDATE;
 IF r IS NULL OR r NOT IN ('superadmin','admin','sales-tr','sales-pump') OR (r NOT IN ('superadmin','admin') AND q.requested_by<>auth.uid()) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ยกเลิกคำขอ'; END IF;
 IF q.id IS NULL OR q.status<>'pending' OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ระบุเหตุผลสำหรับคำขอที่รอดำเนินการ'; END IF;
 IF EXISTS(SELECT 1 FROM public.or_shipping_conversion_payments WHERE request_id=q.id) THEN RAISE EXCEPTION 'มีค่าส่งชำระแล้ว ให้ฝ่ายบัญชีจัดการเงินก่อนยกเลิก'; END IF;
 UPDATE public.or_shipping_conversion_requests SET status='cancelled',review_reason=p_reason,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=q.id;
 UPDATE public.or_orders SET shipping_conversion_pending=false WHERE id=q.order_id;
END $$;


--
-- Name: or_complete_shipping_conversion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_complete_shipping_conversion(p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE q public.or_shipping_conversion_requests; o public.or_orders; paid numeric; actor text;
BEGIN
 SELECT * INTO q FROM public.or_shipping_conversion_requests WHERE id=p_request_id FOR UPDATE;
 IF q.id IS NULL THEN RAISE EXCEPTION 'ไม่พบคำขอ'; END IF;
 IF q.status='ready' THEN RETURN public.or_shipping_verified_balance(q.id)>=q.original_total+q.shipping_cost; END IF;
 IF q.status<>'pending' THEN RETURN false; END IF;
 SELECT * INTO o FROM public.or_orders WHERE id=q.order_id FOR UPDATE;
 IF o.status IN ('ยกเลิก','จัดส่งแล้ว') OR o.shipped_time IS NOT NULL OR o.fulfillment_method<>'self_pickup' THEN RAISE EXCEPTION 'สถานะบิลเปลี่ยนไป กรุณาตรวจสอบ'; END IF;
 IF q.shipping_cost=0 AND q.zero_approved_by IS NULL THEN RETURN false; END IF;
 SELECT public.or_shipping_verified_balance(q.id) INTO paid;
 IF paid < q.original_total+q.shipping_cost THEN RETURN false; END IF;
 SELECT coalesce(username,email,id::text) INTO actor FROM public.us_users WHERE id=q.requested_by;
 PERFORM set_config('app.shipping_conversion_write','yes',true);
 UPDATE public.or_shipping_conversion_requests SET status='ready',completed_at=now(),verification_error=NULL WHERE id=q.id;
 INSERT INTO public.or_fulfillment_change_logs(order_id,bill_no,from_method,to_method,reason,previous_status,previous_customer_address,previous_recipient_name,previous_tracking_number,changed_by,changed_by_user_id)
 VALUES(o.id,o.bill_no,'self_pickup','shipping',q.reason,o.status,o.customer_address,o.recipient_name,o.tracking_number,actor,q.requested_by);
 UPDATE public.or_orders SET fulfillment_method='shipping',shipping_cost=q.shipping_cost,total_amount=q.original_total+q.shipping_cost,
 recipient_name=q.details->>'recipient_name',customer_address=concat_ws(' ',q.details->>'address_line',q.details->>'sub_district',q.details->>'district',q.details->>'province',q.details->>'postal_code'),
 billing_details=coalesce(o.billing_details,'{}'::jsonb)|| (q.details - 'recipient_name' - 'carrier'),
 transport_meta=coalesce(o.transport_meta,'{}'::jsonb)||jsonb_build_object('carrier',q.details->>'carrier'),
 converted_from_self_pickup_at=now(),converted_from_self_pickup_by=actor,tracking_number=NULL,
 packing_meta=coalesce(o.packing_meta,'{}'::jsonb)-'parcelScanned'-'scanTime'
 WHERE id=o.id;
 RETURN true;
END $$;


--
-- Name: or_discount_automatic(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_automatic(p_header jsonb, p_items jsonb, p_promotions jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE link jsonb; p public.promotion; cfg jsonb; paid jsonb; count_ int; amount numeric; total_ numeric:=0;
 subtotal numeric:=round(coalesce((p_header->>'price')::numeric,0),2); val numeric; allocated numeric;
BEGIN
 IF jsonb_array_length(coalesce(p_promotions,'[]'))>1 AND EXISTS(
  SELECT 1 FROM jsonb_array_elements(p_promotions) x JOIN public.promotion pr ON pr.id=(x->>'promotion_id')::uuid WHERE NOT pr.allow_stack
 ) THEN RETURN 0; END IF;
 SELECT coalesce(jsonb_agg(x||jsonb_build_object('product_category',pr.product_category)),'[]') INTO paid
 FROM jsonb_array_elements(p_items) x JOIN public.pr_products pr ON pr.id=(x->>'product_id')::uuid
 WHERE NOT coalesce((x->>'is_free')::boolean,false) AND NOT coalesce((x->>'is_detail_row')::boolean,false);
 FOR link IN SELECT value FROM jsonb_array_elements(coalesce(p_promotions,'[]')) LOOP
  SELECT * INTO p FROM public.promotion WHERE id=(link->>'promotion_id')::uuid;
  IF p.id IS NULL OR p.rule_type='legacy' OR NOT p.is_active OR
   (cardinality(p.channel_codes)>0 AND NOT (p_header->>'channel_code'=ANY(p.channel_codes))) OR
   (p.start_date IS NOT NULL AND p.start_date>(now() AT TIME ZONE 'Asia/Bangkok')::date) OR
   (p.end_date IS NOT NULL AND p.end_date<(now() AT TIME ZONE 'Asia/Bangkok')::date) OR
   (jsonb_array_length(p_promotions)>1 AND NOT p.allow_stack) THEN CONTINUE; END IF;
  cfg:=p.rule_config; count_:=greatest(1,coalesce((link->>'application_count')::int,1));
  IF count_>greatest(1,coalesce((cfg->>'max_applications')::int,1)) THEN CONTINUE; END IF;
  val:=greatest(0,coalesce((cfg->>'discount_value')::numeric,0)); amount:=0;
  IF p.rule_type IN ('spend_fixed','spend_percent') THEN
   IF subtotal>=greatest(0,coalesce((cfg->>'threshold_amount')::numeric,0))*count_ THEN
    amount:=CASE WHEN p.rule_type='spend_percent' THEN subtotal*val/100 ELSE val*count_ END;
   END IF;
  ELSIF p.rule_type IN ('quantity_fixed','quantity_percent','bundle_fixed_price') THEN
   IF jsonb_array_length(coalesce(cfg->'condition_groups','[]'))=0 THEN CONTINUE; END IF;
   allocated:=public.or_discount_group_value(paid,cfg->'condition_groups',count_,p.rule_type='quantity_percent');
   IF allocated IS NOT NULL THEN
    amount:=CASE p.rule_type WHEN 'quantity_fixed' THEN val*count_
     WHEN 'quantity_percent' THEN CASE WHEN val<=100 THEN allocated*val/100 ELSE 0 END
     ELSE greatest(0,allocated-greatest(0,coalesce((cfg->>'set_price')::numeric,0))*count_) END;
   END IF;
  END IF;
  total_:=total_+round(least(subtotal,greatest(0,amount)),2);
 END LOOP;
 RETURN total_;
END $$;


--
-- Name: or_discount_can_manage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_can_manage(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.us_users u JOIN public.or_orders o ON o.id=p_id
 WHERE u.id=auth.uid() AND u.is_active AND (u.role IN ('superadmin','admin')
 OR (u.role IN ('sales-tr','sales-pump') AND (o.admin_user IN (u.username,u.email)
 OR (u.role='sales-tr' AND EXISTS(SELECT 1 FROM public.us_users owner WHERE owner.role='sales-tr' AND o.admin_user IN(owner.username,owner.email)))))))
$$;


--
-- Name: or_discount_group_value(jsonb, jsonb, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_group_value(p_items jsonb, p_groups jsonb, p_count integer, p_extra boolean DEFAULT false) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE ni int:=jsonb_array_length(p_items); ng int:=jsonb_array_length(p_groups); n int:=ni+ng+2;
 cap numeric[][]; cost numeric[][]; dist numeric[]; prev int[]; i int; j int; k int; v int; w int;
 qty numeric; demand numeric:=0; flow numeric:=0; pushed numeric; total_cost numeric:=0; expanded boolean:=false; changed boolean;
 item jsonb; grp jsonb; opt jsonb; need numeric; available numeric:=0;
BEGIN
 IF ng=0 THEN RETURN 0; END IF;
 cap:=array_fill(0::numeric,ARRAY[n,n]); cost:=array_fill(0::numeric,ARRAY[n,n]);
 FOR i IN 1..ni LOOP
  item:=p_items->(i-1); qty:=greatest(0,floor(coalesce((item->>'quantity')::numeric,0))); available:=available+qty;
  cap[1][i+1]:=qty;
  FOR j IN 1..ng LOOP
   grp:=p_groups->(j-1);
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(grp->'options','[]')) o
    WHERE (o->>'selector_type'='sku' AND o->>'product_id'=item->>'product_id') OR
    (o->>'selector_type'='category' AND o->>'category'=item->>'product_category')) THEN
    cap[i+1][ni+j+1]:=qty;
    cost[i+1][ni+j+1]:=-round(coalesce((item->>'unit_price')::numeric,0)*100);
    cost[ni+j+1][i+1]:=-cost[i+1][ni+j+1];
   END IF;
  END LOOP;
 END LOOP;
 FOR j IN 1..ng LOOP
  need:=greatest(1,floor(coalesce((p_groups->(j-1)->>'quantity')::numeric,1)))*p_count;
  cap[ni+j+1][n]:=need; demand:=demand+need;
 END LOOP;
 LOOP
  IF flow=demand THEN
   IF NOT p_extra OR expanded THEN EXIT; END IF;
   expanded:=true;
   FOR j IN 1..ng LOOP
    IF coalesce((p_groups->(j-1)->>'quantity_at_least')::boolean,false) THEN cap[ni+j+1][n]:=cap[ni+j+1][n]+available; demand:=demand+available; END IF;
   END LOOP;
   IF flow=demand THEN EXIT; END IF;
  END IF;
  dist:=array_fill(1e30::numeric,ARRAY[n]); prev:=array_fill(0,ARRAY[n]); dist[1]:=0;
  FOR k IN 1..n-1 LOOP
   changed:=false;
   FOR v IN 1..n LOOP
    FOR w IN 1..n LOOP
     IF cap[v][w]>0 AND dist[v]<1e30 AND dist[w]>dist[v]+cost[v][w] THEN
      dist[w]:=dist[v]+cost[v][w]; prev[w]:=v; changed:=true;
     END IF;
    END LOOP;
   END LOOP;
   EXIT WHEN NOT changed;
  END LOOP;
  EXIT WHEN prev[n]=0;
  pushed:=demand-flow; v:=n;
  WHILE v<>1 LOOP pushed:=least(pushed,cap[prev[v]][v]); v:=prev[v]; END LOOP;
  v:=n;
  WHILE v<>1 LOOP w:=prev[v]; cap[w][v]:=cap[w][v]-pushed; cap[v][w]:=cap[v][w]+pushed; total_cost:=total_cost+pushed*cost[w][v]; v:=w; END LOOP;
  flow:=flow+pushed;
 END LOOP;
 IF NOT expanded AND flow<demand THEN RETURN NULL; END IF;
 RETURN round(-total_cost/100,2);
END $$;


--
-- Name: or_discount_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_items(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(i)),'[]'::jsonb) FROM public.or_order_items i WHERE order_id=p_id
$$;


--
-- Name: or_discount_lines(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_lines(p_items jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT coalesce(jsonb_agg(line ORDER BY line::text),'[]'::jsonb) FROM (
 SELECT jsonb_build_object('product_id',x->>'product_id','quantity',coalesce((x->>'quantity')::numeric,0),
 'unit_price',round(coalesce((x->>'unit_price')::numeric,0),2),'is_free',coalesce((x->>'is_free')::boolean,false),
 'is_detail_row',coalesce((x->>'is_detail_row')::boolean,false)) line
 FROM jsonb_array_elements(coalesce(p_items,'[]')) x WHERE nullif(x->>'product_id','') IS NOT NULL) q
$$;


--
-- Name: or_discount_lock_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_lock_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.order_id IS DISTINCT FROM OLD.order_id THEN RAISE EXCEPTION 'ไม่สามารถย้ายรายการระหว่างบิล'; END IF;
 PERFORM 1 FROM public.or_orders WHERE id=coalesce((to_jsonb(NEW)->>'order_id')::uuid,(to_jsonb(OLD)->>'order_id')::uuid) FOR UPDATE;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: or_discount_snapshot(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_snapshot(p_header jsonb, p_items jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('price',round(coalesce((p_header->>'price')::numeric,0),2),'shipping_cost',round(coalesce((p_header->>'shipping_cost')::numeric,0),2),
 'discount',round(coalesce((p_header->>'discount')::numeric,0),2),'total_amount',round(coalesce((p_header->>'total_amount')::numeric,0),2),
 'channel_code',p_header->>'channel_code','payment_method',p_header->>'payment_method',
 'fulfillment_method',coalesce(p_header->>'fulfillment_method','shipping'),'items',public.or_discount_lines(p_items))
$$;


--
-- Name: or_discount_state(uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_discount_state(p_id uuid, p_header jsonb, p_items jsonb, p_promotions jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE snap jsonb:=public.or_discount_snapshot(p_header,p_items); r public.or_sales_discount_requests;
 d public.or_prebill_documents; required_ boolean; approved_ boolean:=false; auto_ numeric; o public.or_orders; source_ text;
BEGIN
 IF p_id IS NOT NULL THEN SELECT * INTO o FROM public.or_orders WHERE id=p_id; END IF;
 auto_:=public.or_discount_automatic(p_header,p_items,p_promotions);
 required_:=round(coalesce((p_header->>'discount')::numeric,0),2)>0 AND round((p_header->>'discount')::numeric,2)<>auto_;
 IF p_id IS NOT NULL THEN
  SELECT * INTO r FROM public.or_sales_discount_requests WHERE order_id=p_id ORDER BY created_at DESC,id DESC LIMIT 1;
  approved_:=r.status='approved' AND r.snapshot=snap;
  IF approved_ THEN source_:='sale'; END IF;
  IF o.source_prebill_document_id IS NOT NULL THEN
   SELECT * INTO d FROM public.or_prebill_documents WHERE id=o.source_prebill_document_id AND converted_order_id=p_id
    AND status='converted' AND approved_by IS NOT NULL AND approved_at IS NOT NULL AND approved_special_discount IS NOT NULL;
   IF d.id IS NOT NULL AND (d.discount_review_snapshot IS NULL OR d.discount_review_snapshot=public.or_prebill_discount_snapshot(to_jsonb(d),coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM public.or_prebill_items i WHERE document_id=d.id),'[]'))) AND d.approved_special_discount=d.special_discount AND (d.special_discount>0)
    AND snap=public.or_discount_snapshot(jsonb_build_object('price',d.subtotal,'shipping_cost',d.shipping_cost,
      'discount',d.promotion_discount+d.special_discount,'total_amount',d.total_amount,'channel_code',d.channel_code,
      'payment_method',d.payment_method,'fulfillment_method',coalesce(to_jsonb(o)->>'fulfillment_method','shipping')),
      coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM public.or_prebill_items i WHERE document_id=d.id),'[]')) THEN
     approved_:=true; source_:='prebill';
   END IF;
  END IF;
 END IF;
 approved_:=coalesce(approved_,false);
 -- Old unchanged commercial snapshots retain their previous workflow; no historical backfill.
 IF o.automatic_discount_snapshot=snap THEN required_:=false; END IF;
 IF o.id IS NOT NULL AND NOT o.discount_approval_enabled AND snap=public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id)) THEN required_:=false; END IF;
 RETURN jsonb_build_object('required',required_,'approved',approved_,'source',source_,
  'zero_payment',coalesce(approved_ AND (p_header->>'total_amount')::numeric=0,false),
  'status',CASE WHEN r.id IS NULL THEN 'none' WHEN r.snapshot<>snap AND r.status IN ('pending','approved') THEN 'stale' ELSE r.status END,
  'legacy_unchanged',o.id IS NOT NULL AND NOT o.discount_approval_enabled AND snap=public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id)),
  'reason',r.reason,'review_note',r.review_note,'automatic_discount',auto_);
END $$;


--
-- Name: or_guard_pickup_shipping(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_guard_pickup_shipping() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE pending boolean; controlled boolean:=coalesce(current_setting('app.shipping_conversion_write',true),'')='yes';
BEGIN
 IF TG_OP='UPDATE' THEN
 SELECT EXISTS(SELECT 1 FROM public.or_shipping_conversion_requests WHERE order_id=OLD.id AND status='pending') INTO pending;
 IF NOT controlled AND pending AND (NEW.fulfillment_method IS DISTINCT FROM OLD.fulfillment_method OR NEW.shipping_cost IS DISTINCT FROM OLD.shipping_cost OR NEW.total_amount IS DISTINCT FROM OLD.total_amount OR NEW.price IS DISTINCT FROM OLD.price OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.channel_code IS DISTINCT FROM OLD.channel_code OR NEW.payment_method IS DISTINCT FROM OLD.payment_method OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status NOT IN ('รอออกแบบ','ไม่ต้องออกแบบ','ออกแบบแล้ว','รอคอนเฟิร์ม','คอนเฟิร์มแล้ว','ใบสั่งงาน','ย้ายจากใบงาน','ใบงานกำลังผลิต')) OR NEW.shipped_time IS DISTINCT FROM OLD.shipped_time OR NEW.packing_meta IS DISTINCT FROM OLD.packing_meta OR NEW.transport_meta IS DISTINCT FROM OLD.transport_meta) THEN
 RAISE EXCEPTION 'รอฝ่ายขายจัดการจัดส่ง/ตรวจค่าส่ง/อนุมัติค่าส่ง 0 ก่อนแพ็ค'; END IF;
 IF NOT controlled AND NEW.fulfillment_method IS DISTINCT FROM OLD.fulfillment_method AND NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role IN ('superadmin','admin','sales-tr','sales-pump')) THEN RAISE EXCEPTION 'ฝ่ายขายเท่านั้นที่เปลี่ยนวิธีรับสินค้าได้'; END IF;
 IF NOT controlled AND OLD.fulfillment_method='self_pickup' AND NEW.fulfillment_method='shipping' THEN RAISE EXCEPTION 'ต้องเปลี่ยนผ่านคำขอฝ่ายขายและตรวจเงินก่อน'; END IF;
 IF ((NEW.status='จัดส่งแล้ว' AND OLD.status IS DISTINCT FROM NEW.status) OR (NEW.shipped_time IS NOT NULL AND NEW.shipped_time IS DISTINCT FROM OLD.shipped_time)) AND EXISTS(SELECT 1 FROM public.or_shipping_conversion_requests q WHERE q.order_id=OLD.id AND q.status='ready' AND public.or_shipping_verified_balance(q.id)<q.original_total+q.shipping_cost) THEN RAISE EXCEPTION 'ยอดชำระเปลี่ยนไป ต้องให้บัญชีตรวจสอบก่อนจัดส่ง'; END IF;
 IF NOT controlled AND EXISTS(SELECT 1 FROM public.or_shipping_conversion_requests WHERE order_id=OLD.id AND status='ready') AND
 (NEW.fulfillment_method IS DISTINCT FROM OLD.fulfillment_method OR NEW.shipping_cost IS DISTINCT FROM OLD.shipping_cost OR NEW.total_amount IS DISTINCT FROM OLD.total_amount OR NEW.price IS DISTINCT FROM OLD.price OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.payment_method IS DISTINCT FROM OLD.payment_method) THEN RAISE EXCEPTION 'ยอดที่ตรวจเงินแล้วต้องแก้ผ่านกระบวนการบัญชี'; END IF;
 END IF;
 NEW.shipping_conversion_pending:=EXISTS(SELECT 1 FROM public.or_shipping_conversion_requests WHERE order_id=NEW.id AND status='pending');
 IF NEW.fulfillment_method='self_pickup' THEN
 IF TG_OP='UPDATE' AND OLD.fulfillment_method='self_pickup' AND coalesce(OLD.shipping_cost,0)<>0 THEN
 -- Historical bills may already offset shipping with a discount. Preserve the
 -- financial snapshot on packing/status/address updates instead of deducting again.
 IF coalesce(current_setting('app.legacy_pickup_normalization',true),'')<>'yes' AND (NEW.price IS DISTINCT FROM OLD.price OR NEW.shipping_cost IS DISTINCT FROM OLD.shipping_cost
    OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.total_amount IS DISTINCT FROM OLD.total_amount) THEN
   RAISE EXCEPTION 'บิลรับเองเดิมมีค่าส่ง/ส่วนลดชดเชย ห้ามเปลี่ยนยอดอัตโนมัติ ต้องให้บัญชีตรวจสอบก่อน';
 END IF;
 ELSE
 NEW.total_amount:=greatest(0,coalesce(NEW.total_amount,0)-coalesce(NEW.shipping_cost,0));
 NEW.shipping_cost:=0;
 END IF;
 NEW.customer_address:=''; NEW.tracking_number:=NULL;
 NEW.billing_details:=coalesce(NEW.billing_details,'{}'::jsonb)-ARRAY['address_line','sub_district','district','province','postal_code','mobile_phone','original_customer_address'];
 END IF;
 RETURN NEW;
END $$;


--
-- Name: or_guard_refund_production_and_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_guard_refund_production_and_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_reason text; v_requested text; v_actor text;
BEGIN
  -- Gate every attachment path, including direct updates and legacy name-only links.
  IF (NEW.work_order_id IS NOT NULL OR nullif(trim(NEW.work_order_name),'') IS NOT NULL)
    AND (TG_OP='INSERT' OR NEW.work_order_id IS DISTINCT FROM OLD.work_order_id
      OR NEW.work_order_name IS DISTINCT FROM OLD.work_order_name) THEN
    v_reason:=public.or_refund_production_block(NEW.id,NEW.total_amount);
    IF v_reason IS NOT NULL THEN
      RAISE EXCEPTION 'บิล % เข้าใบงานไม่ได้: %',NEW.bill_no,v_reason;
    END IF;
  END IF;
  IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    v_requested:=NEW.status;
    -- An explicit packing reset clears shipped_time; cancellation remains allowed.
    IF OLD.status='จัดส่งแล้ว' AND OLD.shipped_time IS NOT NULL
      AND NEW.shipped_time IS NOT NULL AND NEW.status<>'ยกเลิก' THEN
      NEW.status:=OLD.status;
    ELSIF (OLD.work_order_id IS NOT NULL OR nullif(trim(OLD.work_order_name),'') IS NOT NULL)
      AND NEW.work_order_id IS NOT DISTINCT FROM OLD.work_order_id
      AND NEW.work_order_name IS NOT DISTINCT FROM OLD.work_order_name
      AND OLD.status<>'ยกเลิก'
      AND NEW.status IN ('รอลงข้อมูล','ลงข้อมูลเสร็จสิ้น','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน',
        'ตรวจสอบไม่สำเร็จ','รอตรวจคำสั่งซื้อ','ตรวจสอบแล้ว','รอออกแบบ','ไม่ต้องออกแบบ',
        'ออกแบบแล้ว','รอคอนเฟิร์ม','คอนเฟิร์มแล้ว','เสร็จสิ้น','ใบสั่งงาน') THEN
      NEW.status:=OLD.status;
    END IF;
    IF NEW.status IS DISTINCT FROM v_requested THEN
      SELECT coalesce(username,email) INTO v_actor FROM public.us_users WHERE id=auth.uid();
      INSERT INTO public.or_order_status_history(order_id,bill_no,previous_status,requested_status,
        resulting_status,event_type,actor_id,actor_name,source,reason)
      VALUES(OLD.id,OLD.bill_no,OLD.status,v_requested,NEW.status,'preserved',auth.uid(),
        coalesce(v_actor,current_user),coalesce(nullif(current_setting('app.order_status_source',true),''),'order_update'),
        'คงสถานะงานผลิต/ขนส่งไว้ ป้องกันการย้อนกลับจากขั้นตอนตรวจข้อมูลหรือการเงิน');
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: or_guard_sales_discount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_guard_sales_discount() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE state_ jsonb; role_ text; commercial_change boolean:=false;
BEGIN
 IF (TG_OP='INSERT' AND NEW.source_prebill_document_id IS NOT NULL) OR
  (TG_OP='UPDATE' AND NEW.source_prebill_document_id IS DISTINCT FROM OLD.source_prebill_document_id) THEN
  IF NEW.source_prebill_document_id IS NULL OR coalesce(current_setting('app.discount_prebill_conversion',true),'')<>NEW.source_prebill_document_id::text THEN
   RAISE EXCEPTION 'เอกสาร QT/PC ต้องเชื่อมผ่านขั้นตอนเปิดบิลเท่านั้น';
  END IF;
 END IF;
 IF TG_OP='INSERT' THEN NEW.automatic_discount_snapshot:=NULL; NEW.discount_approval_enabled:=true;
 ELSE
  NEW.automatic_discount_snapshot:=OLD.automatic_discount_snapshot;
  commercial_change:=public.or_discount_snapshot(to_jsonb(NEW),'[]')<>public.or_discount_snapshot(to_jsonb(OLD),'[]');
  NEW.discount_approval_enabled:=OLD.discount_approval_enabled OR NEW.discount_approval_enabled OR commercial_change;
 END IF;
 NEW.payment_not_required:=false;
 IF NEW.discount_approval_enabled AND NEW.source_marketplace_order_id IS NULL AND (to_jsonb(NEW)->>'web_import_snapshot') IS NULL AND upper(coalesce(NEW.bill_no,'')) NOT LIKE 'REQ%' THEN
  IF NEW.total_amount IS NULL OR NEW.price IS NULL OR NEW.discount IS NULL OR NEW.shipping_cost IS NULL THEN RAISE EXCEPTION 'กรุณาระบุยอดสินค้า ค่าส่ง ส่วนลด และยอดสุทธิ'; END IF;
  IF NEW.total_amount<0 OR NEW.discount<0 THEN RAISE EXCEPTION 'ยอดสุทธิและส่วนลดต้องไม่ติดลบ'; END IF;
  state_:=public.or_discount_state(NEW.id,to_jsonb(NEW),public.or_discount_items(NEW.id),
    coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.or_order_promotions p WHERE order_id=NEW.id),'[]'));
  NEW.payment_not_required:=coalesce((state_->>'zero_payment')::boolean,false);
  IF NEW.discount>0 AND NOT (state_->>'required')::boolean AND NEW.status NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ','ยกเลิก') THEN
   NEW.automatic_discount_snapshot:=public.or_discount_snapshot(to_jsonb(NEW),public.or_discount_items(NEW.id));
  END IF;

  IF NEW.payment_not_required AND NEW.status='ลงข้อมูลเสร็จสิ้น' THEN
   SELECT role INTO role_ FROM public.us_users WHERE NEW.admin_user IN(username,email) ORDER BY (username=NEW.admin_user) DESC NULLS LAST LIMIT 1;
   NEW.status:=CASE WHEN upper(NEW.channel_code)='WY' THEN 'ตรวจสอบแล้ว'
    WHEN role_='sales-tr' AND ((NEW.channel_code='PUMP' AND NEW.requires_confirm_design=false) OR (NEW.channel_code<>'PUMP' AND NOT coalesce(NEW.requires_confirm_design,false))) THEN 'รอตรวจคำสั่งซื้อ'
    WHEN NEW.channel_code='PUMP' AND NEW.requires_confirm_design=false THEN 'ไม่ต้องออกแบบ' ELSE 'ตรวจสอบแล้ว' END;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: or_tax_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.or_tax_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    header_id uuid NOT NULL,
    invoice_no text NOT NULL,
    invoice_date date NOT NULL,
    snapshot jsonb NOT NULL,
    flow_account_reference text DEFAULT ''::text NOT NULL,
    issued_by uuid NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: or_issue_tax_invoice(uuid, uuid, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_issue_tax_invoice(p_order_id uuid, p_header_id uuid, p_date date, p_snapshot jsonb, p_flow_reference text DEFAULT ''::text) RETURNS public.or_tax_invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE o public.or_orders; h public.bill_header_settings; doc public.or_tax_invoices; period_key text; next_number integer; expected_items jsonb; vat_rate numeric; base numeric; item_total numeric; canonical jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM us_users WHERE id=auth.uid() AND role IN ('account','superadmin')) THEN RAISE EXCEPTION 'เฉพาะบัญชีออกเอกสารได้'; END IF;
 PERFORM public.or_tax_require_menu('account-tax-invoice');
 SELECT * INTO o FROM or_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.status='ยกเลิก' OR NOT coalesce(o.billing_details @> '{"request_tax_invoice":true}',false) THEN RAISE EXCEPTION 'บิลไม่มีคำขอ'; END IF;
 SELECT * INTO doc FROM or_tax_invoices WHERE order_id=o.id;
 IF FOUND THEN RETURN doc; END IF;
 IF NOT public.or_tax_approved(o.billing_details,'invoice') THEN RAISE EXCEPTION 'รออนุมัติข้อมูลใบกำกับภาษี'; END IF;
 -- Previously issued legacy documents need manual recovery, never a new number.
 IF coalesce((o.billing_details->>'account_confirmed_tax')::boolean,false) THEN RAISE EXCEPTION 'เอกสารเก่า กรุณาตรวจเลขที่เคยออกก่อนนำเข้าทะเบียน'; END IF;
 SELECT * INTO h FROM bill_header_settings WHERE id=p_header_id;
 IF NOT FOUND OR nullif(trim(h.bill_code),'') IS NULL OR p_date IS NULL OR p_date>(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'เลือกบริษัทและวันที่ให้ถูกต้อง'; END IF;
 IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot)<>'object' THEN RAISE EXCEPTION 'ข้อมูลเอกสารไม่ถูกต้อง'; END IF;
 IF p_snapshot->>'customerName' IS DISTINCT FROM o.billing_details->>'tax_customer_name'
 OR p_snapshot->>'customerTaxId' IS DISTINCT FROM o.billing_details->>'tax_id'
 OR p_snapshot->>'customerAddress' IS DISTINCT FROM o.billing_details->>'tax_customer_address'
 OR abs(coalesce((p_snapshot->>'grandTotal')::numeric,-1)-o.total_amount)>0.01 THEN RAISE EXCEPTION 'ข้อมูลเอกสารไม่ตรงกับข้อมูลที่อนุมัติ'; END IF;
 IF jsonb_typeof(o.billing_details->'tax_items')='array' AND jsonb_array_length(o.billing_details->'tax_items')>0 THEN
  SELECT jsonb_agg(jsonb_build_object('description',t->>'product_name','quantity',(t->>'quantity')::numeric,'unitPrice',(t->>'unit_price')::numeric,'amount',(t->>'quantity')::numeric*(t->>'unit_price')::numeric)) INTO expected_items FROM jsonb_array_elements(o.billing_details->'tax_items') t;
  IF p_snapshot->'items' IS DISTINCT FROM expected_items THEN RAISE EXCEPTION 'รายการสินค้าไม่ตรงกับข้อมูลที่อนุมัติ'; END IF;
 END IF;
 vat_rate:=coalesce((o.billing_details->>'vat_rate')::numeric,7);
 base:=round(o.total_amount/(1+vat_rate/100),2);
 item_total:=o.total_amount+coalesce(o.discount,0)-coalesce(o.shipping_cost,0);
 canonical:=jsonb_build_object('customerName',o.billing_details->>'tax_customer_name','customerAddress',o.billing_details->>'tax_customer_address','customerTaxId',o.billing_details->>'tax_id',
 'customerBranch',CASE WHEN coalesce(o.billing_details->>'tax_branch','00000')='00000' THEN 'สำนักงานใหญ่' ELSE 'สาขา '||(o.billing_details->>'tax_branch') END,
 'customerPhone',coalesce(o.billing_details->>'tax_customer_phone',o.billing_details->>'mobile_phone',''),
 'items',coalesce(expected_items,jsonb_build_array(jsonb_build_object('description','สินค้า','quantity',1,'unitPrice',item_total,'amount',item_total))),
 'discount',coalesce(o.discount,0),'shippingCost',coalesce(o.shipping_cost,0),'subtotal',item_total,'netAmount',base,'vatAmount',o.total_amount-base,'vatRate',vat_rate,'grandTotal',o.total_amount);
 period_key:=to_char(p_date,'YYMM');
 IF EXISTS(SELECT 1 FROM or_orders legacy WHERE coalesce((legacy.billing_details->>'account_confirmed_tax')::boolean,false) AND NOT coalesce((legacy.billing_details->>'tax_request_closed')::boolean,false)
   AND NOT EXISTS(SELECT 1 FROM or_tax_invoices issued WHERE issued.order_id=legacy.id)
   AND to_char(coalesce(nullif(legacy.billing_details->>'account_confirmed_tax_at','')::timestamptz,legacy.created_at) AT TIME ZONE 'Asia/Bangkok','YYMM')=period_key)
   AND NOT EXISTS(SELECT 1 FROM or_tax_invoice_counters WHERE header_id=h.id AND period=period_key AND legacy_reviewed) THEN
   RAISE EXCEPTION 'มีเอกสารเก่าในเดือนนี้ กรุณาตรวจทะเบียนและยืนยันเลขล่าสุดก่อนเริ่มรันเลขใหม่';
 END IF;
 INSERT INTO or_tax_invoice_counters(header_id,period,last_number) VALUES(h.id,period_key,1)
 ON CONFLICT(header_id,period) DO UPDATE SET last_number=or_tax_invoice_counters.last_number+1
 RETURNING last_number INTO next_number;
 IF next_number>9999 THEN RAISE EXCEPTION 'เลขเอกสารเกิน 9999 รายการในเดือนนี้'; END IF;
 INSERT INTO or_tax_invoices(order_id,header_id,invoice_no,invoice_date,snapshot,flow_account_reference,issued_by)
 VALUES(o.id,h.id,h.bill_code||'IV'||period_key||lpad(next_number::text,4,'0'),p_date,
 p_snapshot||canonical||jsonb_build_object('companyData',to_jsonb(h),'orderBilling',o.billing_details,'orderTotal',o.total_amount),coalesce(trim(p_flow_reference),''),auth.uid()) RETURNING * INTO doc;
 PERFORM set_config('app.tax_write','yes',true);
 UPDATE or_orders SET billing_details=coalesce(billing_details,'{}')||jsonb_build_object('account_confirmed_tax',true,'account_confirmed_tax_at',now(),'account_confirmed_tax_by',auth.uid(),'erp_tax_invoice_no',doc.invoice_no) WHERE id=o.id;
 PERFORM set_config('app.tax_write','',true);
 INSERT INTO or_tax_audit(order_id,kind,action,after_data,actor_id) VALUES(o.id,'invoice','issue',to_jsonb(doc),auth.uid());
 RETURN doc;
END $$;


--
-- Name: or_lock_payment_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_lock_payment_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_ids uuid[];
BEGIN
  IF TG_OP='INSERT' THEN v_ids:=ARRAY[NEW.order_id];
  ELSIF TG_OP='DELETE' THEN v_ids:=ARRAY[OLD.order_id];
  ELSE v_ids:=ARRAY[OLD.order_id,NEW.order_id]; END IF;
  PERFORM 1 FROM public.or_orders WHERE id=ANY(v_ids) ORDER BY id FOR UPDATE;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: or_orders_normalize_claim_billing_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_orders_normalize_claim_billing_details() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.bill_no LIKE 'REQ%' THEN
    NEW.billing_details := public.normalize_claim_billing_details(NEW.billing_details);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: or_orders_strip_original_customer_address(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_orders_strip_original_customer_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.billing_details IS NOT NULL
     AND NEW.billing_details ? 'original_customer_address' THEN
    NEW.billing_details := NEW.billing_details - 'original_customer_address';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION or_orders_strip_original_customer_address(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.or_orders_strip_original_customer_address() IS 'Prevents stale raw address snapshots from being stored in billing_details.';


--
-- Name: or_overpayment_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_overpayment_paid(p_order_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT coalesce((SELECT sum(verified_amount) FROM ac_verified_slips WHERE order_id=p_order_id AND NOT coalesce(is_deleted,false)),0)
  +coalesce((SELECT sum(m.transfer_amount) FROM ac_manual_slip_checks m WHERE m.order_id=p_order_id
    AND m.status='approved' AND m.duplicate_of IS NULL
    AND NOT EXISTS(SELECT 1 FROM ac_verified_slips s WHERE s.order_id=m.order_id AND NOT coalesce(s.is_deleted,false)
      AND s.verified_amount=m.transfer_amount AND s.easyslip_date IS NOT NULL
      AND to_char(s.easyslip_date AT TIME ZONE 'Asia/Bangkok','YYYY-MM-DD')=trim(m.transfer_date)
      AND to_char(s.easyslip_date AT TIME ZONE 'Asia/Bangkok','HH24:MI')=trim(m.transfer_time))),0)
$$;


--
-- Name: or_prebill_discount_invalidate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_prebill_discount_invalidate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE items_ jsonb:=coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM public.or_prebill_items i WHERE document_id=NEW.id),'[]');
 old_snap jsonb:=public.or_prebill_discount_snapshot(to_jsonb(OLD),items_);
 new_snap jsonb:=public.or_prebill_discount_snapshot(to_jsonb(NEW),items_);
BEGIN
 IF NEW.converted_order_id IS DISTINCT FROM OLD.converted_order_id AND NEW.converted_order_id IS NOT NULL THEN
  IF OLD.converted_order_id IS NOT NULL OR NEW.status<>'converted' OR coalesce(current_setting('app.discount_prebill_conversion',true),'')<>NEW.id::text THEN
   RAISE EXCEPTION 'ไม่สามารถเปลี่ยนบิลอ้างอิงเพื่อใช้ผลอนุมัติ QT/PC ซ้ำ';
  END IF;
 END IF;
 IF NEW.status='pending_discount' AND OLD.status<>'pending_discount' THEN NEW.discount_review_snapshot:=new_snap;
 ELSE NEW.discount_review_snapshot:=coalesce(OLD.discount_review_snapshot,CASE WHEN OLD.status IN ('approved','pending_discount') THEN old_snap END); END IF;
 IF OLD.status IN ('approved','pending_discount') AND NEW.status=OLD.status AND new_snap<>old_snap THEN
  NEW.status:='active'; NEW.approved_at:=NULL; NEW.approved_by:=NULL; NEW.approved_special_discount:=NULL;
 END IF;
 IF NEW.status='approved' AND OLD.status<>'approved' THEN
  IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role='superadmin' AND is_active) THEN RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้น'; END IF;
  IF OLD.discount_review_snapshot IS NOT NULL AND OLD.discount_review_snapshot<>old_snap THEN RAISE EXCEPTION 'รายการ QT/PC เปลี่ยนแล้ว ต้องส่งขออนุมัติใหม่'; END IF;
  IF NEW.valid_until<(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'เอกสารหมดอายุ'; END IF;
  NEW.discount_review_snapshot:=new_snap;
 END IF;
 IF NEW.status='converted' AND NEW.special_discount>0 AND (OLD.status<>'approved' OR NEW.approved_by IS NULL OR NEW.approved_at IS NULL OR NEW.approved_special_discount IS DISTINCT FROM NEW.special_discount
 OR (OLD.discount_review_snapshot IS NOT NULL AND OLD.discount_review_snapshot<>old_snap)) THEN
  RAISE EXCEPTION 'ส่วนลด QT/PC ต้องได้รับอนุมัติและตรงกับรายการก่อนเปิดบิล';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: or_prebill_discount_item_invalidate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_prebill_discount_item_invalidate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE d public.or_prebill_documents;
BEGIN
 SELECT * INTO d FROM public.or_prebill_documents WHERE id=coalesce((to_jsonb(NEW)->>'document_id')::uuid,(to_jsonb(OLD)->>'document_id')::uuid) FOR UPDATE;
 IF d.status IN ('approved','pending_discount') AND d.discount_review_snapshot IS NOT NULL AND d.discount_review_snapshot<>
  public.or_prebill_discount_snapshot(to_jsonb(d),coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM public.or_prebill_items i WHERE document_id=d.id),'[]')) THEN
  UPDATE public.or_prebill_documents SET status='active',approved_at=NULL,approved_by=NULL,approved_special_discount=NULL WHERE id=d.id;
 END IF;
 RETURN NULL;
END $$;


--
-- Name: or_prebill_discount_lock_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_prebill_discount_lock_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE d public.or_prebill_documents;
BEGIN
 IF TG_OP='UPDATE' AND NEW.document_id IS DISTINCT FROM OLD.document_id THEN RAISE EXCEPTION 'ไม่สามารถย้ายรายการระหว่าง QT/PC'; END IF;
 SELECT * INTO d FROM public.or_prebill_documents WHERE id=coalesce((to_jsonb(NEW)->>'document_id')::uuid,(to_jsonb(OLD)->>'document_id')::uuid) FOR UPDATE;
 -- Capture pre-migration approvals only when an actual edit is attempted.
 IF d.status IN ('approved','pending_discount') AND d.discount_review_snapshot IS NULL THEN
  UPDATE public.or_prebill_documents SET updated_at=updated_at WHERE id=d.id;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: or_prebill_discount_snapshot(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_prebill_discount_snapshot(p_header jsonb, p_items jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT public.or_discount_snapshot(p_header||jsonb_build_object('price',p_header->'subtotal',
 'discount',coalesce((p_header->>'promotion_discount')::numeric,0)+coalesce((p_header->>'special_discount')::numeric,0)),p_items)
$$;


--
-- Name: or_preserve_approved_claim_financials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_preserve_approved_claim_financials() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v JSONB;
BEGIN
  IF upper(COALESCE(NEW.bill_no,'')) NOT LIKE 'REQ%' THEN RETURN NEW; END IF;
  v := public.or_approved_claim_financials(NEW.id);
  IF v IS NOT NULL THEN
    NEW.price := (v->>'price')::NUMERIC;
    NEW.shipping_cost := (v->>'shipping_cost')::NUMERIC;
    NEW.discount := (v->>'discount')::NUMERIC;
    NEW.total_amount := (v->>'total_amount')::NUMERIC;
  ELSIF EXISTS(SELECT 1 FROM public.or_claim_requests WHERE created_claim_order_id=NEW.id) THEN
    -- A pending revision must not replace the last approved bill amount.
    NEW.price := OLD.price; NEW.shipping_cost := OLD.shipping_cost;
    NEW.discount := OLD.discount; NEW.total_amount := OLD.total_amount;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: or_quote_conversion_shipping(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_quote_conversion_shipping(p_order_id uuid, p_details jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE o public.or_orders; base numeric; extra numeric;
BEGIN
 SELECT * INTO o FROM public.or_orders WHERE id=p_order_id;
 IF o.id IS NULL THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
 SELECT shipping_fee INTO base FROM public.or_shipping_fee_ranges WHERE o.price >= min_amount AND (max_amount IS NULL OR o.price <= max_amount) ORDER BY sort_order,min_amount LIMIT 1;
 IF EXISTS(SELECT 1 FROM public.or_shipping_fee_settings WHERE id=1 AND special_area_enabled) THEN
 SELECT surcharge INTO extra FROM public.or_shipping_area_rules a WHERE is_active
 AND (is_forever OR (now() AT TIME ZONE 'Asia/Bangkok')::date BETWEEN start_date AND end_date)
 AND (coalesce(cardinality(channel_codes),0)=0 OR o.channel_code=ANY(channel_codes))
 AND regexp_replace(upper(a.carrier),'(EXPRESS|ขนส่ง|[^A-Z0-9ก-๙])','','g')=regexp_replace(upper(p_details->>'carrier'),'(EXPRESS|ขนส่ง|[^A-Z0-9ก-๙])','','g')
 AND (nullif(a.postal_code,'') IS NULL OR a.postal_code=p_details->>'postal_code')
 AND public.or_shipping_address_key(a.province,'province')=public.or_shipping_address_key(p_details->>'province','province')
 AND public.or_shipping_address_key(a.district,'district')=public.or_shipping_address_key(p_details->>'district','district')
 AND (nullif(a.sub_district,'') IS NULL OR public.or_shipping_address_key(a.sub_district,'sub_district')=public.or_shipping_address_key(p_details->>'sub_district','sub_district'))
 ORDER BY (CASE WHEN cardinality(channel_codes)>0 THEN 100 ELSE 0 END+CASE WHEN nullif(a.sub_district,'') IS NOT NULL THEN 40 ELSE 0 END+CASE WHEN nullif(a.district,'') IS NOT NULL THEN 20 ELSE 0 END+CASE WHEN nullif(a.postal_code,'') IS NOT NULL THEN 10 ELSE 0 END+CASE WHEN nullif(a.province,'') IS NOT NULL THEN 5 ELSE 0 END) DESC,surcharge DESC LIMIT 1;
 END IF;
 IF base IS NULL AND extra IS NULL THEN RETURN NULL; END IF;
 RETURN coalesce(base,0)+coalesce(extra,0);
END $$;


--
-- Name: or_record_shipping_payment(uuid, text, numeric, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_record_shipping_payment(p_request_id uuid, p_trans_ref text, p_amount numeric, p_storage_path text, p_slip_image_url text, p_response jsonb, p_verified_by uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE q public.or_shipping_conversion_requests;
BEGIN
 SELECT * INTO q FROM public.or_shipping_conversion_requests WHERE id=p_request_id FOR UPDATE;
 IF q.id IS NULL OR q.status<>'pending' THEN RAISE EXCEPTION 'คำขอไม่ได้รอดำเนินการ'; END IF;
 IF q.shipping_cost=0 AND q.zero_approved_by IS NULL THEN RAISE EXCEPTION 'ต้องอนุมัติค่าส่ง 0 ก่อนตรวจสลิปเพิ่ม'; END IF;
 IF p_amount > q.original_total+q.shipping_cost-public.or_shipping_verified_balance(q.id) THEN RAISE EXCEPTION 'ยอดสลิปเกินยอดคงเหลือ กรุณาให้บัญชีตรวจสอบก่อน'; END IF;
 IF nullif(btrim(p_trans_ref),'') IS NULL OR p_amount IS NULL OR p_amount::text='NaN' OR p_amount<=0 THEN RAISE EXCEPTION 'ผลสลิปไม่ถูกต้อง'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('SLIP:'||p_trans_ref,0));
 IF EXISTS(SELECT 1 FROM public.ac_verified_slips WHERE easyslip_trans_ref=p_trans_ref AND validation_status='passed') THEN RAISE EXCEPTION 'สลิปนี้เคยใช้แล้ว'; END IF;
 INSERT INTO public.or_shipping_conversion_payments(request_id,trans_ref,amount,storage_path,response)
 VALUES(q.id,p_trans_ref,p_amount,p_storage_path,p_response);
 -- Mirror into the existing accounting/reconciliation ledger atomically. The
 -- balance helper excludes these references from the original bill receipts.
 PERFORM set_config('app.shipping_payment_write','yes',true);
 INSERT INTO public.ac_verified_slips(order_id,slip_image_url,slip_storage_path,verified_amount,verified_by,easyslip_response,easyslip_trans_ref,
 easyslip_date,easyslip_receiver_bank_id,easyslip_receiver_account,is_validated,validation_status,expected_amount,account_name_match,bank_code_match)
 VALUES(q.order_id,p_slip_image_url,p_storage_path,p_amount,p_verified_by,p_response,p_trans_ref,
 nullif(p_response#>>'{data,date}','')::timestamptz,p_response#>>'{data,receiver,bank,id}',p_response#>>'{data,receiver,account,bank,account}',true,'passed',q.original_total+q.shipping_cost,true,true);
 PERFORM set_config('app.shipping_payment_write','no',true);
 UPDATE public.or_shipping_conversion_requests SET verification_error=NULL,last_verification_at=now() WHERE id=q.id;
 RETURN public.or_complete_shipping_conversion(q.id);
END $$;


--
-- Name: or_refresh_shipping_conversion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_refresh_shipping_conversion(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r text; q public.or_shipping_conversion_requests; paid numeric; ready boolean;
BEGIN
 SELECT role INTO r FROM public.us_users WHERE id=auth.uid();
 SELECT * INTO q FROM public.or_shipping_conversion_requests WHERE id=p_request_id;
 IF r IS NULL OR r NOT IN ('superadmin','admin','account','sales-tr','sales-pump') OR q.id IS NULL
 OR (r IN ('sales-tr','sales-pump') AND q.requested_by<>auth.uid()) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจยอดคำขอนี้'; END IF;
 ready:=public.or_complete_shipping_conversion(q.id);
 paid:=public.or_shipping_verified_balance(q.id);
 RETURN jsonb_build_object('ready',ready,'paid',paid,'remaining',greatest(0,q.original_total+q.shipping_cost-paid));
END $$;


--
-- Name: or_refund_production_block(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_refund_production_block(p_order_id uuid, p_total numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_latest record; v_remaining numeric;
BEGIN
  IF EXISTS(SELECT 1 FROM ac_refunds WHERE order_id=p_order_id AND status='pending') THEN RETURN 'รออนุมัติคำขอโอนคืน'; END IF;
  IF EXISTS(SELECT 1 FROM ac_overpayment_waivers WHERE order_id=p_order_id AND status='pending') THEN RETURN 'รอบัญชีรับรองลูกค้าไม่รับเงินคืน'; END IF;
  SELECT * INTO v_latest FROM (
    SELECT status,rejected_reason,created_at,id FROM ac_refunds WHERE order_id=p_order_id
    UNION ALL SELECT status,rejected_reason,created_at,id FROM ac_overpayment_waivers WHERE order_id=p_order_id
  ) r ORDER BY created_at DESC,id DESC LIMIT 1;
  IF v_latest.status='rejected' THEN RETURN 'คำขอจัดการยอดเกินถูกปฏิเสธ: '||coalesce(v_latest.rejected_reason,'กรุณาแก้ไขและส่งคำขอใหม่'); END IF;
  -- p_total may be public.or_tax_receivable(NEW.total_amount,NEW.billing_details) in a BEFORE trigger, before the row is stored.
  SELECT receivable_amount INTO p_total FROM public.or_orders WHERE id=p_order_id;
  v_remaining:=public.or_overpayment_paid(p_order_id)-coalesce(p_total,0)
    -coalesce((SELECT sum(amount) FROM ac_refunds WHERE order_id=p_order_id AND status='approved' AND reason ILIKE '%โอนเกิน%'),0)
    -coalesce((SELECT sum(amount) FROM ac_overpayment_waivers WHERE order_id=p_order_id AND status='approved'
      AND order_total=p_total AND paid_amount=public.or_overpayment_paid(p_order_id)),0);
  IF v_remaining>0.01 THEN RETURN 'พบยอดโอนเกิน '||to_char(v_remaining,'FM999999999990.00')||' บาท ยังไม่ได้รับอนุมัติการจัดการยอดเกิน'; END IF;
  RETURN NULL;
END $$;


--
-- Name: or_request_shipping_conversion(uuid, numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_request_shipping_conversion(p_order_id uuid, p_shipping_cost numeric, p_details jsonb, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE o public.or_orders; r text; result uuid;
BEGIN
 SELECT role INTO r FROM public.us_users WHERE id=auth.uid();
 IF r IS NULL OR r NOT IN ('superadmin','admin','sales-tr','sales-pump') THEN RAISE EXCEPTION 'ฝ่ายขายเท่านั้นที่ขอเปลี่ยนเป็นจัดส่งได้'; END IF;
 SELECT * INTO o FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
 IF r IN ('sales-tr','sales-pump') AND NOT EXISTS(SELECT 1 FROM public.channel_role_visibility WHERE channel_code=o.channel_code AND role=r) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ช่องทางนี้'; END IF;
 IF r='sales-pump' AND NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND o.admin_user IN (username,email)) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการบิลของผู้อื่น'; END IF;
 IF o.id IS NULL OR o.fulfillment_method <> 'self_pickup' OR o.status IN ('ยกเลิก','จัดส่งแล้ว') OR o.shipped_time IS NOT NULL
    OR coalesce((o.transport_meta->>'customer_received')::boolean,false) THEN RAISE EXCEPTION 'บิลนี้ไม่สามารถเปลี่ยนเป็นจัดส่งได้'; END IF;
 IF p_shipping_cost IS NULL OR p_shipping_cost::text='NaN' OR p_shipping_cost < 0 OR p_shipping_cost <> round(p_shipping_cost,2) OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ระบุค่าส่งและเหตุผลให้ถูกต้อง'; END IF;
 IF coalesce(o.shipping_cost,0)<>0 THEN RAISE EXCEPTION 'บิลรับเองมีค่าส่งเดิม ให้บัญชีตรวจสอบก่อนเปลี่ยน'; END IF;
 IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' OR EXISTS (
 SELECT 1 FROM unnest(ARRAY['recipient_name','address_line','sub_district','district','province','postal_code','mobile_phone','carrier']) k WHERE nullif(btrim(p_details->>k),'') IS NULL
 ) OR (p_details->>'postal_code') !~ '^[0-9]{5}$' THEN RAISE EXCEPTION 'กรอกผู้รับ ที่อยู่ ขนส่ง และรหัสไปรษณีย์ให้ครบ'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tr_shipping_carriers WHERE code=p_details->>'carrier' AND is_active AND upper(code)<>'SELF') THEN RAISE EXCEPTION 'เลือกขนส่งที่ใช้งาน'; END IF;
 INSERT INTO public.or_shipping_conversion_requests(order_id,requested_by,shipping_cost,original_total,details,reason,suggested_shipping_cost)
 VALUES(o.id,auth.uid(),p_shipping_cost,o.total_amount,p_details,btrim(p_reason),public.or_quote_conversion_shipping(o.id,p_details)) RETURNING id INTO result;
 UPDATE public.or_orders SET shipping_conversion_pending=true WHERE id=o.id;
 RETURN result;
END $_$;


--
-- Name: or_review_zero_shipping(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_review_zero_shipping(p_request_id uuid, p_approve boolean, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r text; q public.or_shipping_conversion_requests;
BEGIN
 SELECT role INTO r FROM public.us_users WHERE id=auth.uid();
 IF r IS NULL OR r NOT IN ('superadmin','admin','account') THEN RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติค่าส่ง 0'; END IF;
 SELECT * INTO q FROM public.or_shipping_conversion_requests WHERE id=p_request_id FOR UPDATE;
 IF q.id IS NULL OR q.status<>'pending' OR q.shipping_cost<>0 OR q.zero_approved_by IS NOT NULL THEN RAISE EXCEPTION 'คำขอนี้ไม่อยู่ระหว่างรออนุมัติ'; END IF;
 IF p_approve IS NULL OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลการอนุมัติหรือปฏิเสธ'; END IF;
 UPDATE public.or_shipping_conversion_requests SET reviewed_by=auth.uid(),reviewed_at=now(),review_reason=btrim(p_reason),
 zero_approved_by=CASE WHEN p_approve THEN auth.uid() END,zero_approved_at=CASE WHEN p_approve THEN now() END,
 status=CASE WHEN p_approve THEN 'pending' ELSE 'rejected' END WHERE id=q.id;
 IF NOT p_approve THEN UPDATE public.or_orders SET shipping_conversion_pending=false WHERE id=q.order_id; END IF;
 RETURN public.or_complete_shipping_conversion(q.id);
END $$;


--
-- Name: or_shipping_address_key(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_shipping_address_key(p_value text, p_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
 SELECT CASE WHEN p_kind='province' AND v IN ('กรุงเทพฯ','กรุงเทพ','กทม') THEN 'กรุงเทพมหานคร' ELSE v END
 FROM (SELECT lower(regexp_replace(regexp_replace(btrim(coalesce(p_value,'')),
 CASE p_kind WHEN 'province' THEN '^(จังหวัด|จ\.)' WHEN 'district' THEN '^(เขต|อำเภอ|อ\.)' WHEN 'sub_district' THEN '^(แขวง|ตำบล|ต\.)' ELSE '^$' END,''), '[[:space:]._/\-]','','g')) v) n;
$_$;


--
-- Name: or_shipping_conversion_balances(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_shipping_conversion_balances(p_request_ids uuid[]) RETURNS TABLE(request_id uuid, paid numeric, remaining numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT q.id,b.paid,greatest(0,q.original_total+q.shipping_cost-b.paid)
 FROM public.or_shipping_conversion_requests q
 CROSS JOIN LATERAL (SELECT public.or_shipping_verified_balance(q.id) paid) b
 WHERE q.id=ANY(p_request_ids) AND EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role IN ('superadmin','admin','account','sales-tr','sales-pump'));
$$;


--
-- Name: or_shipping_verified_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_shipping_verified_balance(p_request_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT least(q.original_total,greatest(0,
 coalesce((SELECT sum(s.amount) FROM (SELECT max(verified_amount) amount FROM public.ac_verified_slips WHERE order_id=q.order_id AND validation_status='passed' AND coalesce(is_deleted,false)=false AND easyslip_trans_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.or_shipping_conversion_payments p WHERE p.trans_ref=ac_verified_slips.easyslip_trans_ref) GROUP BY easyslip_trans_ref) s),0)
 -coalesce((SELECT sum(amount) FROM public.ac_refunds WHERE order_id=q.order_id AND status IN ('pending','approved')),0)))
 +coalesce((SELECT sum(amount) FROM public.or_shipping_conversion_payments WHERE request_id=q.id),0)
 FROM public.or_shipping_conversion_requests q WHERE q.id=p_request_id;
$$;


--
-- Name: or_supersede_stale_waivers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_supersede_stale_waivers(p_order_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 UPDATE ac_overpayment_waivers w SET status='superseded',invalidated_at=now()
 FROM or_orders o WHERE w.order_id=o.id AND w.order_id=p_order_id AND w.status='approved'
  AND (w.order_total<>o.receivable_amount OR w.paid_amount<>public.or_overpayment_paid(o.id))
$$;


--
-- Name: or_sync_approved_claim_financials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_sync_approved_claim_financials() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v JSONB;
BEGIN
  IF NEW.status<>'approved' OR NEW.created_claim_order_id IS NULL THEN RETURN NEW; END IF;
  v := public.or_approved_claim_financials(NEW.created_claim_order_id);
  IF v IS NULL THEN RETURN NEW; END IF;
  UPDATE public.or_orders SET price=(v->>'price')::NUMERIC,
    shipping_cost=(v->>'shipping_cost')::NUMERIC,discount=(v->>'discount')::NUMERIC,
    total_amount=(v->>'total_amount')::NUMERIC,updated_at=now()
  WHERE id=NEW.created_claim_order_id
    AND (price,shipping_cost,discount,total_amount) IS DISTINCT FROM
      ((v->>'price')::NUMERIC,(v->>'shipping_cost')::NUMERIC,(v->>'discount')::NUMERIC,(v->>'total_amount')::NUMERIC);
  RETURN NEW;
END $$;


--
-- Name: or_tax_action(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_action(p_order_id uuid, p_kind text, p_action text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE o public.or_orders; role_name text; bd jsonb; prior jsonb; workflow jsonb; state text; reason text; patch jsonb;
BEGIN
 SELECT role INTO role_name FROM public.us_users WHERE id=auth.uid();
 IF role_name IS NULL THEN RAISE EXCEPTION 'ไม่มีสิทธิ์'; END IF;
 SELECT * INTO o FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.or_orders WHERE id=p_order_id) THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
 -- SECURITY DEFINER must separately enforce the caller's order visibility.
 IF role_name IN ('sales-tr','sales-pump') AND NOT EXISTS(SELECT 1 FROM public.us_users u WHERE (u.id=auth.uid() OR role_name='sales-tr' AND u.role='sales-tr') AND (u.username=o.admin_user OR u.email=o.admin_user)) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการบิลนี้'; END IF;
 IF role_name NOT IN ('sales-tr','sales-pump','account','superadmin','admin') OR o.status='ยกเลิก' THEN RAISE EXCEPTION 'ไม่สามารถทำรายการ'; END IF;
 PERFORM public.or_tax_require_menu(CASE WHEN p_action='resubmit' THEN 'orders-tax' WHEN p_kind='invoice' THEN 'account-tax-invoice' ELSE 'account-withholding' END);
 IF p_kind NOT IN ('invoice','withholding') THEN RAISE EXCEPTION 'ประเภทไม่ถูกต้อง'; END IF;
 bd:=coalesce(o.billing_details,'{}'); prior:=bd;
 IF NOT (bd @> CASE WHEN p_kind='invoice' THEN '{"request_tax_invoice":true}'::jsonb ELSE '{"withholding_requested":true}'::jsonb END) THEN RAISE EXCEPTION 'บิลไม่มีคำขอนี้'; END IF;
 workflow:=coalesce(bd->'tax_workflow','{}'); state:=coalesce(workflow->p_kind->>'status','pending');
 IF p_action IN ('approve','reject') THEN
  IF role_name NOT IN ('account','superadmin') THEN RAISE EXCEPTION 'เฉพาะบัญชีอนุมัติได้'; END IF;
  IF p_action='approve' AND (state<>'pending' OR public.or_tax_approved(bd,p_kind)) OR p_action='reject' AND state NOT IN ('pending','approved') THEN RAISE EXCEPTION 'สถานะคำขอไม่รองรับการทำรายการ'; END IF;
  IF p_action='reject' AND (o.work_order_id IS NOT NULL OR nullif(trim(o.work_order_name),'') IS NOT NULL OR EXISTS(SELECT 1 FROM or_tax_invoices WHERE order_id=o.id) OR bd->'withholding_receipt' IS NOT NULL) THEN RAISE EXCEPTION 'บิลเริ่มดำเนินงานหรือมีเอกสารแล้ว ส่งกลับแก้ไขไม่ได้'; END IF;
  IF p_payload->'expected_details' IS DISTINCT FROM bd OR (p_payload->>'expected_total')::numeric IS DISTINCT FROM o.total_amount THEN RAISE EXCEPTION 'ข้อมูลเปลี่ยนแล้ว กรุณารีเฟรชและตรวจใหม่'; END IF;
  reason:=nullif(trim(p_payload->>'reason'),'');
  IF p_action='reject' AND reason IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผล'; END IF;
  IF p_action='approve' THEN PERFORM public.or_tax_validate(bd); END IF;
  workflow:=jsonb_set(workflow,ARRAY[p_kind],jsonb_build_object('status',CASE WHEN p_action='approve' THEN 'approved' ELSE 'rejected' END,'reason',reason,'by',auth.uid(),'at',now()));
  bd:=jsonb_set(bd,'{tax_workflow}',workflow);
 ELSIF p_action='resubmit' THEN
  IF role_name NOT IN ('sales-tr','sales-pump','superadmin','admin') OR state<>'rejected' THEN RAISE EXCEPTION 'คำขอไม่อยู่ระหว่างแก้ไข'; END IF;
  IF o.work_order_id IS NOT NULL OR nullif(trim(o.work_order_name),'') IS NOT NULL THEN RAISE EXCEPTION 'บิลเข้าใบสั่งงานแล้ว'; END IF;
  IF EXISTS(SELECT 1 FROM public.or_tax_invoices WHERE order_id=o.id) THEN RAISE EXCEPTION 'ออกเอกสารแล้ว แก้ข้อมูลไม่ได้'; END IF;
  SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO patch FROM jsonb_each(p_payload) WHERE key IN ('tax_customer_name','tax_customer_address','tax_id','tax_branch','tax_address');
  IF nullif(trim(patch->>'tax_customer_name'),'') IS NULL OR coalesce(patch->>'tax_id','') !~ '^\d{13}$' OR nullif(trim(patch->>'tax_customer_address'),'') IS NULL THEN RAISE EXCEPTION 'กรอกข้อมูลภาษีให้ครบ'; END IF;
  bd:=bd||patch;
  PERFORM public.or_tax_validate(bd);
  workflow:=jsonb_set(workflow,ARRAY[p_kind],jsonb_build_object('status','pending','by',auth.uid(),'at',now()));
  -- Shared buyer data changed: invalidate the other approval too.
  IF bd @> '{"withholding_requested":true}' THEN workflow:=jsonb_set(workflow,ARRAY[CASE WHEN p_kind='invoice' THEN 'withholding' ELSE 'invoice' END],jsonb_build_object('status','pending','at',now())); END IF;
  bd:=jsonb_set(bd,'{tax_workflow}',workflow);
 ELSIF p_action='received' THEN
  IF role_name NOT IN ('account','superadmin') OR p_kind<>'withholding' OR NOT public.or_tax_approved(bd,p_kind) THEN RAISE EXCEPTION 'ยังไม่อนุมัติหรือไม่มีสิทธิ์'; END IF;
  IF bd->'withholding_receipt' IS NOT NULL THEN RAISE EXCEPTION 'บันทึกรับเอกสารแล้ว'; END IF;
  IF nullif(trim(p_payload->>'reference'),'') IS NULL OR nullif(p_payload->>'date','') IS NULL OR nullif(trim(p_payload->>'file_path'),'') IS NULL THEN RAISE EXCEPTION 'กรอกเลขเอกสาร วันที่ และแนบไฟล์'; END IF;
  IF (p_payload->>'date')::date>(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'วันที่เอกสารอยู่ในอนาคต'; END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='tax-evidence' AND name=p_payload->>'file_path' AND (storage.foldername(name))[1]=o.id::text) THEN RAISE EXCEPTION 'ไม่พบไฟล์แนบของบิลนี้'; END IF;
  bd:=jsonb_set(bd,'{withholding_receipt}',p_payload||jsonb_build_object('by',auth.uid(),'at',now()));
 ELSE RAISE EXCEPTION 'การทำรายการไม่ถูกต้อง'; END IF;
 PERFORM set_config('app.tax_write','yes',true);
 UPDATE public.or_orders SET billing_details=bd WHERE id=o.id;
 INSERT INTO public.or_tax_audit(order_id,kind,action,reason,before_data,after_data,actor_id) VALUES(o.id,p_kind,p_action,reason,prior,bd,auth.uid());
 PERFORM set_config('app.tax_write','',true);
END $_$;


--
-- Name: or_tax_approved(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_approved(p_details jsonb, p_kind text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT CASE WHEN p_kind='invoice' AND coalesce((p_details->>'account_confirmed_tax')::boolean,false) AND NOT coalesce((p_details->>'tax_request_closed')::boolean,false)
 THEN true ELSE coalesce(p_details->'tax_workflow'->p_kind->>'status','pending')='approved' END
$$;


--
-- Name: or_tax_close_cancelled(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_close_cancelled(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE o public.or_orders; bd jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM us_users WHERE id=auth.uid() AND role IN ('account','superadmin')) THEN RAISE EXCEPTION 'เฉพาะบัญชีปิดคำขอได้'; END IF;
 PERFORM public.or_tax_require_menu('account-tax-invoice');
 SELECT * INTO o FROM or_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR o.status<>'ยกเลิก' THEN RAISE EXCEPTION 'ปิดได้เฉพาะบิลยกเลิก'; END IF;
 bd:=coalesce(o.billing_details,'{}')||jsonb_build_object('account_confirmed_tax',true,'account_confirmed_tax_at',now(),'account_confirmed_tax_by',auth.uid(),'tax_request_closed',true,'tax_request_closed_reason','ยกเลิกบิล');
 PERFORM set_config('app.tax_write','yes',true);
 UPDATE or_orders SET billing_details=bd WHERE id=o.id;
 INSERT INTO or_tax_audit(order_id,kind,action,before_data,after_data,actor_id) VALUES(o.id,'invoice','close_cancelled',o.billing_details,bd,auth.uid());
 PERFORM set_config('app.tax_write','',true);
END $$;


--
-- Name: or_tax_flow_reference(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_flow_reference(p_order_id uuid, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE previous text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM us_users WHERE id=auth.uid() AND role IN ('account','superadmin')) THEN RAISE EXCEPTION 'เฉพาะบัญชีแก้เลขอ้างอิงได้'; END IF;
 PERFORM public.or_tax_require_menu('account-tax-invoice');
 SELECT flow_account_reference INTO previous FROM or_tax_invoices WHERE order_id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ยังไม่ได้ออกเอกสาร ERP'; END IF;
 UPDATE or_tax_invoices SET flow_account_reference=coalesce(trim(p_reference),'') WHERE order_id=p_order_id;
 INSERT INTO or_tax_audit(order_id,kind,action,before_data,after_data,actor_id)
 VALUES(p_order_id,'invoice','flow_reference',jsonb_build_object('reference',previous),jsonb_build_object('reference',p_reference),auth.uid());
END $$;


--
-- Name: or_tax_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE controlled boolean:=coalesce(current_setting('app.tax_write',true),'')='yes';
 changed boolean; k text; old_bd jsonb:=CASE WHEN TG_OP='UPDATE' THEN coalesce(OLD.billing_details,'{}') ELSE '{}' END;
 bd jsonb:=coalesce(NEW.billing_details,'{}');
BEGIN
 IF TG_OP='INSERT' THEN
  -- A new bill may copy buyer data, but never another bill's approval or documents.
  bd:=bd-ARRAY['tax_workflow','withholding_receipt','account_confirmed_tax','account_confirmed_tax_at','account_confirmed_tax_by','erp_tax_invoice_no','tax_request_closed','tax_request_closed_reason'];
 END IF;
 IF bd @> '{"withholding_requested":true}' THEN
  bd:=jsonb_set(bd,'{request_tax_invoice}','true');
  IF NEW.total_amount<0 OR coalesce((bd->>'vat_rate')::numeric,7)<0 THEN RAISE EXCEPTION 'ยอดบิลหรือ VAT ไม่ถูกต้อง'; END IF;
 END IF;
 IF NOT controlled THEN
  IF (bd->'tax_workflow') IS DISTINCT FROM (old_bd->'tax_workflow')
   OR (bd->'withholding_receipt') IS DISTINCT FROM (old_bd->'withholding_receipt')
   OR (bd->'account_confirmed_tax_at') IS DISTINCT FROM (old_bd->'account_confirmed_tax_at')
   OR (bd->'account_confirmed_tax_by') IS DISTINCT FROM (old_bd->'account_confirmed_tax_by')
   OR (bd->'erp_tax_invoice_no') IS DISTINCT FROM (old_bd->'erp_tax_invoice_no')
   OR (bd->'account_confirmed_tax') IS DISTINCT FROM (old_bd->'account_confirmed_tax') THEN
   RAISE EXCEPTION 'ต้องดำเนินการอนุมัติผ่านขั้นตอน TAX';
  END IF;
  IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.ac_verified_slips s WHERE s.order_id=NEW.id AND NOT coalesce(s.is_deleted,false) AND s.validation_status='passed') THEN
   IF coalesce(bd @> '{"request_tax_invoice":true}',false) IS DISTINCT FROM coalesce(old_bd @> '{"request_tax_invoice":true}',false)
    OR coalesce(bd @> '{"withholding_requested":true}',false) IS DISTINCT FROM coalesce(old_bd @> '{"withholding_requested":true}',false)
    OR coalesce(bd->>'vat_rate','7') IS DISTINCT FROM coalesce(old_bd->>'vat_rate','7') THEN
    RAISE EXCEPTION 'บิลผ่าน EasySlip แล้ว เปลี่ยนคำขอเอกสารภาษีย้อนหลังไม่ได้';
   END IF;
  END IF;
  changed:=false;
  FOREACH k IN ARRAY ARRAY['tax_customer_name','tax_customer_address','tax_id','tax_branch','tax_address','request_tax_invoice','withholding_requested'] LOOP
    IF (bd->k) IS DISTINCT FROM (old_bd->k) THEN changed:=true; END IF;
  END LOOP;
  IF TG_OP='UPDATE' AND changed AND (public.or_tax_approved(old_bd,'invoice') OR public.or_tax_approved(old_bd,'withholding')
   OR old_bd->'tax_workflow'->'invoice'->>'status'='rejected') THEN
   RAISE EXCEPTION 'แก้ข้อมูลคำขอเดิมผ่านเมนู TAX เท่านั้น';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.total_amount IS DISTINCT FROM OLD.total_amount OR NEW.shipping_cost IS DISTINCT FROM OLD.shipping_cost OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.price IS DISTINCT FROM OLD.price OR bd->'tax_items' IS DISTINCT FROM old_bd->'tax_items') THEN
  IF EXISTS(SELECT 1 FROM public.or_tax_invoices WHERE order_id=NEW.id) OR coalesce((old_bd->>'account_confirmed_tax')::boolean,false) AND NOT coalesce((old_bd->>'tax_request_closed')::boolean,false) THEN RAISE EXCEPTION 'ออกใบกำกับแล้ว ต้องใช้กระบวนการแก้เอกสารบัญชี'; END IF;
  IF bd @> '{"request_tax_invoice":true}' THEN
   bd:=jsonb_set(bd,'{tax_workflow}',jsonb_build_object('invoice',jsonb_build_object('status','pending'),'withholding',jsonb_build_object('status','pending')));
  END IF;
 END IF;
 IF (NEW.work_order_id IS NOT NULL OR nullif(trim(NEW.work_order_name),'') IS NOT NULL OR NEW.status='ใบสั่งงาน')
 AND (TG_OP='INSERT' OR NEW.work_order_id IS DISTINCT FROM OLD.work_order_id OR NEW.work_order_name IS DISTINCT FROM OLD.work_order_name OR NEW.status='ใบสั่งงาน' AND OLD.status IS DISTINCT FROM NEW.status) THEN
  IF bd @> '{"request_tax_invoice":true}' AND NOT public.or_tax_approved(bd,'invoice') THEN RAISE EXCEPTION 'รอบัญชีอนุมัติใบกำกับภาษี'; END IF;
  IF bd @> '{"withholding_requested":true}' AND NOT public.or_tax_approved(bd,'withholding') THEN RAISE EXCEPTION 'รอบัญชีอนุมัติหัก ณ ที่จ่าย'; END IF;
 END IF;
 NEW.billing_details:=CASE WHEN NEW.billing_details IS NULL AND bd='{}'::jsonb THEN NULL ELSE bd END;
 RETURN NEW;
END $$;


--
-- Name: or_tax_initialize_series(uuid, uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_initialize_series(p_order_id uuid, p_header_id uuid, p_period text, p_last_number integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE previous integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM us_users WHERE id=auth.uid() AND role IN ('account','superadmin')) THEN RAISE EXCEPTION 'เฉพาะบัญชีตั้งค่าเลขเอกสารได้'; END IF;
 PERFORM public.or_tax_require_menu('account-tax-invoice');
 IF p_period !~ '^\d{2}(0[1-9]|1[0-2])$' OR p_last_number<0 OR p_last_number>9999 OR nullif(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ระบุเดือน เลขล่าสุด และเหตุผลให้ถูกต้อง'; END IF;
 IF NOT EXISTS(SELECT 1 FROM or_orders WHERE id=p_order_id) THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
 SELECT last_number INTO previous FROM or_tax_invoice_counters WHERE header_id=p_header_id AND period=p_period FOR UPDATE;
 IF previous IS NOT NULL AND p_last_number<previous THEN RAISE EXCEPTION 'ห้ามลดเลขลำดับที่ใช้แล้ว'; END IF;
 INSERT INTO or_tax_invoice_counters(header_id,period,last_number,legacy_reviewed) VALUES(p_header_id,p_period,p_last_number,true)
 ON CONFLICT(header_id,period) DO UPDATE SET last_number=greatest(or_tax_invoice_counters.last_number,excluded.last_number),legacy_reviewed=true;
 INSERT INTO or_tax_audit(order_id,kind,action,reason,before_data,after_data,actor_id)
 VALUES(p_order_id,'invoice','initialize_series',trim(p_reason),jsonb_build_object('last_number',previous),jsonb_build_object('header_id',p_header_id,'period',p_period,'last_number',p_last_number),auth.uid());
END $_$;


--
-- Name: or_tax_queue(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_queue(p_mode text, p_state text DEFAULT 'pending'::text, p_search text DEFAULT ''::text, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 WITH actor AS (SELECT * FROM us_users WHERE id=auth.uid()), entries AS (
 SELECT to_jsonb(o)||jsonb_build_object('tax_document',(SELECT jsonb_build_object('invoice_no',doc.invoice_no,'flow_account_reference',doc.flow_account_reference) FROM or_tax_invoices doc WHERE doc.order_id=o.id)) order_data,o.id,o.created_at,k.kind,
  CASE WHEN k.kind='invoice' AND coalesce((o.billing_details->>'account_confirmed_tax')::boolean,false) THEN 'approved'
   ELSE coalesce(o.billing_details->'tax_workflow'->k.kind->>'status','pending') END state,
  k.kind='invoice' AND coalesce((o.billing_details->>'account_confirmed_tax')::boolean,false) issued,
  o.billing_details->'withholding_receipt' IS NOT NULL received
 FROM or_orders o CROSS JOIN actor CROSS JOIN (VALUES('invoice'),('withholding')) k(kind)
 WHERE o.status<>'ยกเลิก' AND NOT coalesce((o.billing_details->>'tax_request_closed')::boolean,false) AND o.billing_details @> '{"request_tax_invoice":true}'
  AND (k.kind='invoice' OR o.billing_details @> '{"withholding_requested":true}')
  AND (p_mode='sales' OR p_mode=k.kind)
  AND (actor.role='superadmin' OR EXISTS(SELECT 1 FROM st_user_menus m WHERE m.role=actor.role AND m.has_access AND m.menu_key=CASE WHEN p_mode='sales' THEN 'orders-tax' WHEN p_mode='invoice' THEN 'account-tax-invoice' ELSE 'account-withholding' END))
  AND (actor.role IN ('superadmin','admin','account') OR actor.role='sales-pump' AND o.admin_user IN (actor.username,actor.email)
    OR actor.role='sales-tr' AND EXISTS(SELECT 1 FROM us_users owner WHERE owner.role='sales-tr' AND o.admin_user IN (owner.username,owner.email)))
  AND (p_search='' OR strpos(lower(o.bill_no),lower(p_search))>0)
 ), filtered AS (SELECT * FROM entries WHERE CASE WHEN p_state='awaiting_receipt' THEN kind='withholding' AND state='approved' AND NOT received WHEN p_state='received' THEN kind='withholding' AND received WHEN p_state='issued' THEN issued WHEN p_state='approved' THEN state='approved' AND NOT issued ELSE state=p_state END),
 page AS (SELECT * FROM filtered ORDER BY created_at DESC,id,kind LIMIT 50 OFFSET greatest(0,p_offset))
 SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'),
  'total',(SELECT count(*) FROM filtered),'rejected_total',(SELECT count(*) FROM entries WHERE state='rejected'),
  'counts',jsonb_build_object('pending',(SELECT count(*) FROM entries WHERE state='pending'),'rejected',(SELECT count(*) FROM entries WHERE state='rejected'),
   'approved',(SELECT count(*) FROM entries WHERE state='approved' AND NOT issued),'issued',(SELECT count(*) FROM entries WHERE issued),
   'awaiting_receipt',(SELECT count(*) FROM entries WHERE kind='withholding' AND state='approved' AND NOT received),'received',(SELECT count(*) FROM entries WHERE kind='withholding' AND received)))
$$;


--
-- Name: or_tax_require_menu(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_require_menu(p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM us_users u WHERE u.id=auth.uid() AND (u.role='superadmin' OR EXISTS(SELECT 1 FROM st_user_menus m WHERE m.role=u.role AND m.menu_key=p_key AND m.has_access))) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์เมนูนี้'; END IF;
END $$;


--
-- Name: or_tax_validate(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_tax_validate(p_details jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE tin text:=coalesce(p_details->>'tax_id',''); checksum integer:=0; i integer; a jsonb:=p_details->'tax_address';
BEGIN
 IF nullif(trim(p_details->>'tax_customer_name'),'') IS NULL OR nullif(trim(p_details->>'tax_customer_address'),'') IS NULL OR tin !~ '^\d{13}$' OR tin='0000000000000' THEN RAISE EXCEPTION 'กรอกชื่อ ที่อยู่ และเลขภาษี 13 หลักให้ครบ'; END IF;
 FOR i IN 1..12 LOOP checksum:=checksum+substring(tin,i,1)::integer*(14-i); END LOOP;
 IF (11-checksum%11)%10<>right(tin,1)::integer THEN RAISE EXCEPTION 'เลขตรวจสอบผู้เสียภาษีไม่ถูกต้อง'; END IF;
 IF coalesce(p_details->>'tax_branch','00000') !~ '^\d{5}$' THEN RAISE EXCEPTION 'เลขสาขาต้องมี 5 หลัก'; END IF;
 IF a IS NOT NULL AND a<>'null'::jsonb THEN
  IF coalesce(a->>'postal_code','') !~ '^\d{5}$' OR nullif(a->>'sub_district','') IS NULL OR nullif(a->>'district','') IS NULL OR nullif(a->>'province','') IS NULL THEN RAISE EXCEPTION 'เลือกตำบล อำเภอ จังหวัด และรหัสไปรษณีย์ให้ครบ'; END IF;
  IF NOT EXISTS(SELECT 1 FROM thai_sub_districts t JOIN thai_districts d ON d.id=t.district_id JOIN thai_provinces p ON p.id=d.province_id
    WHERE t.name_th=a->>'sub_district' AND d.name_th=a->>'district' AND p.name_th=a->>'province'
    AND (t.zip_code=a->>'postal_code' OR EXISTS(SELECT 1 FROM thai_sub_district_postal_aliases alias WHERE alias.sub_district_id=t.id AND alias.zip_code=a->>'postal_code'))) THEN RAISE EXCEPTION 'ที่อยู่ไม่สัมพันธ์กับรหัสไปรษณีย์'; END IF;
 END IF;
END $_$;


--
-- Name: or_validate_sales_discount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_validate_sales_discount() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE o public.or_orders; id_ uuid; state_ jsonb;
BEGIN
 id_:=CASE WHEN TG_TABLE_NAME='or_orders' THEN (to_jsonb(NEW)->>'id')::uuid ELSE coalesce((to_jsonb(NEW)->>'order_id')::uuid,(to_jsonb(OLD)->>'order_id')::uuid) END;
 SELECT * INTO o FROM public.or_orders WHERE id=id_ FOR UPDATE;
 IF o.id IS NULL OR NOT o.discount_approval_enabled OR o.source_marketplace_order_id IS NOT NULL OR (to_jsonb(o)->>'web_import_snapshot') IS NOT NULL OR upper(coalesce(o.bill_no,'')) LIKE 'REQ%' THEN RETURN NULL; END IF;
 state_:=public.or_discount_state(o.id,to_jsonb(o),public.or_discount_items(o.id),coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.or_order_promotions p WHERE order_id=o.id),'[]'));
 UPDATE public.or_sales_discount_requests SET status=CASE WHEN o.status='ยกเลิก' THEN 'cancelled' ELSE 'stale' END
 WHERE order_id=o.id AND status IN ('pending','approved') AND (o.status='ยกเลิก' OR snapshot<>public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id)));
 IF o.status='ยกเลิก' THEN state_:=state_||jsonb_build_object('approved',false,'zero_payment',false); END IF;
 IF o.payment_not_required IS DISTINCT FROM coalesce((state_->>'zero_payment')::boolean,false) THEN
  UPDATE public.or_orders SET payment_not_required=coalesce((state_->>'zero_payment')::boolean,false) WHERE id=o.id;
 END IF;
 IF o.status NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ','ยกเลิก') THEN
  IF o.total_amount IS NULL OR o.price IS NULL OR o.shipping_cost IS NULL OR o.discount IS NULL OR o.total_amount<>round(o.price+o.shipping_cost-o.discount,2) OR o.total_amount<0 THEN RAISE EXCEPTION 'ยอดสุทธิไม่ตรงกับสินค้า ค่าส่ง และส่วนลด'; END IF;
  IF (state_->>'required')::boolean AND NOT (state_->>'approved')::boolean THEN RAISE EXCEPTION 'ส่วนลดต้องได้รับอนุมัติจาก superadmin และตรงกับรายการปัจจุบันก่อนยืนยันบิล'; END IF;
 END IF;
 RETURN NULL;
END $$;


--
-- Name: or_work_order_refund_blocks(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.or_work_order_refund_blocks(p_order_ids uuid[]) RETURNS TABLE(order_id uuid, bill_no text, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM us_users WHERE id=auth.uid() AND role IN ('superadmin','admin','sales-tr','sales-pump','account','qc_order','production')) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์'; END IF;
 RETURN QUERY SELECT o.id,o.bill_no,b.reason FROM or_orders o CROSS JOIN LATERAL (
 SELECT CASE WHEN o.billing_details @> '{"request_tax_invoice":true}' AND NOT public.or_tax_approved(o.billing_details,'invoice') THEN 'รอบัญชีอนุมัติใบกำกับภาษี'
 WHEN o.billing_details @> '{"withholding_requested":true}' AND NOT public.or_tax_approved(o.billing_details,'withholding') THEN 'รอบัญชีอนุมัติหัก ณ ที่จ่าย'
 ELSE public.or_refund_production_block(o.id,o.receivable_amount) END reason
 ) b WHERE o.id=ANY(p_order_ids) AND b.reason IS NOT NULL;
END $$;


--
-- Name: pk_convert_self_pickup_to_shipping(uuid, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_convert_self_pickup_to_shipping(p_order_id uuid, p_recipient_name text, p_original_address text, p_address_line text, p_sub_district text, p_district text, p_province text, p_postal_code text, p_mobile_phone text, p_reason text, p_changed_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_order public.or_orders;
  v_is_shipped BOOLEAN;
  v_tag JSONB;
  v_customer_address TEXT;
  v_changed_at TIMESTAMPTZ := now();
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role NOT IN ('superadmin', 'admin', 'packing_staff', 'production', 'sales-tr') THEN
    RAISE EXCEPTION 'Not authorized to change fulfillment method';
  END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  IF v_order.fulfillment_method <> 'self_pickup' THEN
    RAISE EXCEPTION 'This bill is not a self-pickup bill';
  END IF;

  IF NULLIF(btrim(COALESCE(p_recipient_name, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_address_line, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_province, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_postal_code, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_mobile_phone, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Recipient, address, province, postal code and phone are required';
  END IF;

  v_is_shipped := v_order.status = 'จัดส่งแล้ว';
  IF v_is_shipped AND v_role NOT IN ('superadmin', 'admin') THEN
    RAISE EXCEPTION 'Only superadmin/admin can reopen a shipped bill';
  END IF;
  IF v_is_shipped AND NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required to cancel shipment';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('PACK:' || COALESCE(v_order.work_order_name, ''), 0));

  INSERT INTO public.or_fulfillment_change_logs(
    order_id, bill_no, from_method, to_method, reason, previous_status,
    previous_customer_address, previous_recipient_name, previous_tracking_number,
    changed_by, changed_by_user_id, changed_at
  ) VALUES (
    v_order.id, v_order.bill_no, 'self_pickup', 'shipping',
    NULLIF(btrim(COALESCE(p_reason, '')), ''), v_order.status,
    v_order.customer_address, v_order.recipient_name, v_order.tracking_number,
    COALESCE(NULLIF(btrim(COALESCE(p_changed_by, '')), ''), 'unknown'), auth.uid(), v_changed_at
  );

  INSERT INTO public.pk_packing_reset_logs(
    order_id, work_order_name, reset_type, reason, previous_status,
    previous_packing_meta, previous_shipped_by, previous_shipped_time, reset_by
  ) VALUES (
    v_order.id, v_order.work_order_name,
    CASE WHEN v_is_shipped THEN 'cancel_shipment' ELSE 'rescan' END,
    COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), 'เปลี่ยนจากรับสินค้าเองเป็นจัดส่ง'),
    v_order.status, v_order.packing_meta, v_order.shipped_by, v_order.shipped_time,
    COALESCE(NULLIF(btrim(COALESCE(p_changed_by, '')), ''), 'unknown')
  );

  DELETE FROM public.pk_packing_unit_scans WHERE order_id = v_order.id;
  v_tag := CASE
    WHEN COALESCE(v_order.packing_meta, '{}'::jsonb) ? 'dailyPackingTag'
      THEN jsonb_build_object('dailyPackingTag', v_order.packing_meta->'dailyPackingTag')
    ELSE NULL
  END;
  v_customer_address := concat_ws(' ',
    NULLIF(btrim(COALESCE(p_address_line, '')), ''),
    NULLIF(btrim(COALESCE(p_sub_district, '')), ''),
    NULLIF(btrim(COALESCE(p_district, '')), ''),
    NULLIF(btrim(COALESCE(p_province, '')), ''),
    NULLIF(btrim(COALESCE(p_postal_code, '')), '')
  );

  UPDATE public.or_orders
  SET fulfillment_method = 'shipping',
      converted_from_self_pickup_at = v_changed_at,
      converted_from_self_pickup_by = COALESCE(NULLIF(btrim(COALESCE(p_changed_by, '')), ''), 'unknown'),
      recipient_name = btrim(p_recipient_name),
      customer_address = v_customer_address,
      billing_details = COALESCE(v_order.billing_details, '{}'::jsonb) || jsonb_build_object(
        'address_line', NULLIF(btrim(COALESCE(p_address_line, '')), ''),
        'sub_district', NULLIF(btrim(COALESCE(p_sub_district, '')), ''),
        'district', NULLIF(btrim(COALESCE(p_district, '')), ''),
        'province', NULLIF(btrim(COALESCE(p_province, '')), ''),
        'postal_code', NULLIF(btrim(COALESCE(p_postal_code, '')), ''),
        'mobile_phone', NULLIF(btrim(COALESCE(p_mobile_phone, '')), ''),
        'original_customer_address', COALESCE(NULLIF(btrim(COALESCE(p_original_address, '')), ''), v_customer_address)
      ),
      tracking_number = NULL,
      packing_meta = v_tag,
      status = CASE WHEN v_is_shipped THEN 'ใบงานกำลังผลิต' ELSE status END,
      shipped_by = CASE WHEN v_is_shipped THEN NULL ELSE shipped_by END,
      shipped_time = CASE WHEN v_is_shipped THEN NULL ELSE shipped_time END
  WHERE id = v_order.id;

  IF v_is_shipped AND v_order.work_order_name IS NOT NULL THEN
    UPDATE public.or_work_orders SET status = 'กำลังผลิต'
    WHERE work_order_name = v_order.work_order_name;
    PERFORM public.merge_plan_tracks_by_name(
      v_order.work_order_name,
      'PACK',
      jsonb_build_object(
        'เริ่มแพ็ค', jsonb_build_object('end', NULL),
        'เสร็จแล้ว', jsonb_build_object('start', NULL, 'end', NULL)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order.id,
    'work_order_name', v_order.work_order_name,
    'reopened_shipment', v_is_shipped,
    'changed_at', v_changed_at
  );
END;
$$;


--
-- Name: pk_fill_packing_upload_report_channel_order_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_fill_packing_upload_report_channel_order_no() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.channel_order_no IS NULL THEN
    NEW.channel_order_no := OLD.channel_order_no;
  END IF;

  IF NEW.channel_order_no IS NULL THEN
    SELECT orders.channel_order_no
      INTO NEW.channel_order_no
    FROM public.or_orders orders
    WHERE orders.work_order_name = NEW.work_order_name
      AND COALESCE(orders.status, '') <> 'ยกเลิก'
      AND LOWER(REGEXP_REPLACE(COALESCE(orders.tracking_number, ''), '[[:space:]]+', '', 'g'))
          = LOWER(REGEXP_REPLACE(COALESCE(NEW.tracking_number, ''), '[[:space:]]+', '', 'g'))
      AND orders.channel_order_no IS NOT NULL
    ORDER BY orders.updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: pk_finalize_work_order(text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_finalize_work_order(p_work_order_name text, p_order_ids uuid[], p_shipped_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_now TIMESTAMPTZ := now();
  v_pending INTEGER;
  v_updated INTEGER := 0;
  v_header_updated INTEGER := 0;
  v_incomplete RECORD;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role NOT IN ('packing_staff', 'production', 'sales-tr') THEN
    RAISE EXCEPTION 'Not authorized to finalize packing';
  END IF;
  IF NULLIF(trim(COALESCE(p_work_order_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Work order name is required';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('PACK:' || p_work_order_name, 0));

  IF COALESCE(array_length(p_order_ids, 1), 0) > 0 THEN
    IF EXISTS (
      SELECT 1 FROM unnest(p_order_ids) requested(id)
      LEFT JOIN public.or_orders o ON o.id = requested.id
      WHERE o.id IS NULL OR o.work_order_name IS DISTINCT FROM p_work_order_name OR o.status = 'ยกเลิก'
    ) THEN
      RAISE EXCEPTION 'One or more bills do not belong to this active work order';
    END IF;

    SELECT
      COALESCE(NULLIF(trim(o.bill_no), ''), o.id::TEXT) AS bill_ref,
      o.fulfillment_method,
      NULLIF(trim(COALESCE(o.tracking_number, '')), '') AS tracking_number,
      units.expected,
      scans.scanned
    INTO v_incomplete
    FROM public.or_orders o
    LEFT JOIN LATERAL (
      SELECT COALESCE(sum(LEAST(GREATEST(i.quantity, 1), 9999)), 0)::INTEGER AS expected
      FROM public.or_order_items i
      WHERE i.order_id = o.id
        AND NULLIF(trim(COALESCE(i.cancellation_stock_action, '')), '') IS NULL
    ) units ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::INTEGER AS scanned
      FROM public.pk_packing_unit_scans s
      WHERE s.order_id = o.id
    ) scans ON true
    WHERE o.id = ANY(p_order_ids)
      AND COALESCE(o.channel_code, '') <> 'OFFICE'
      AND (
        (o.fulfillment_method = 'shipping' AND NULLIF(trim(COALESCE(o.tracking_number, '')), '') IS NULL)
        OR units.expected <= 0
        OR scans.scanned < units.expected
      )
    ORDER BY o.bill_no NULLS LAST, o.id
    LIMIT 1;

    IF FOUND THEN
      IF v_incomplete.tracking_number IS NULL AND v_incomplete.fulfillment_method = 'shipping' THEN
        RAISE EXCEPTION 'จัดส่งไม่ได้: บิล % ยังไม่มีเลขพัสดุ', v_incomplete.bill_ref;
      ELSIF v_incomplete.expected <= 0 THEN
        RAISE EXCEPTION 'จัดส่งไม่ได้: บิล % ไม่มีรายการสินค้าที่ต้องจัดส่ง', v_incomplete.bill_ref;
      ELSE
        RAISE EXCEPTION 'จัดส่งไม่ได้: บิล % สแกนสินค้าไม่ครบ (%/%)',
          v_incomplete.bill_ref, v_incomplete.scanned, v_incomplete.expected;
      END IF;
    END IF;

    UPDATE public.or_orders
    SET status = 'จัดส่งแล้ว', shipped_by = p_shipped_by, shipped_time = v_now
    WHERE id = ANY(p_order_ids)
      AND work_order_name = p_work_order_name
      AND status <> 'ยกเลิก';
    GET DIAGNOSTICS v_updated = ROW_COUNT;
  END IF;

  SELECT count(*)::INTEGER INTO v_pending
  FROM public.or_orders
  WHERE work_order_name = p_work_order_name
    AND status <> 'ยกเลิก'
    AND status <> 'จัดส่งแล้ว';
  IF v_pending > 0 THEN
    RAISE EXCEPTION 'Cannot close work order: % bill(s) are not shipped', v_pending;
  END IF;

  UPDATE public.or_work_orders SET status = 'จัดส่งแล้ว'
  WHERE work_order_name = p_work_order_name;
  GET DIAGNOSTICS v_header_updated = ROW_COUNT;
  IF v_header_updated = 0 THEN RAISE EXCEPTION 'Work order header not found'; END IF;

  PERFORM public.merge_plan_tracks_by_name(
    p_work_order_name, 'PACK',
    jsonb_build_object(
      'เริ่มแพ็ค', jsonb_build_object('start_if_null', to_jsonb(v_now), 'end', to_jsonb(v_now)),
      'เสร็จแล้ว', jsonb_build_object('start_if_null', to_jsonb(v_now), 'end', to_jsonb(v_now))
    )
  );
  RETURN jsonb_build_object('success', true, 'shipped_count', v_updated, 'closed_at', v_now);
END;
$$;


--
-- Name: FUNCTION pk_finalize_work_order(p_work_order_name text, p_order_ids uuid[], p_shipped_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pk_finalize_work_order(p_work_order_name text, p_order_ids uuid[], p_shipped_by text) IS 'Finalize packing atomically; configured self-pickup channels skip tracking validation but still require all active product units to be scanned.';


--
-- Name: pk_guard_shipping_conversion_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_guard_shipping_conversion_scan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE target_order uuid;
BEGIN
 target_order:=CASE WHEN TG_OP='DELETE' THEN OLD.order_id ELSE NEW.order_id END;
 PERFORM 1 FROM public.or_orders WHERE id=target_order FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.or_shipping_conversion_requests WHERE order_id=target_order AND status='pending') THEN RAISE EXCEPTION 'รอตรวจค่าส่งหรืออนุมัติค่าส่ง 0 ก่อนแพ็ค'; END IF;
 IF EXISTS(SELECT 1 FROM public.or_shipping_conversion_requests q WHERE q.order_id=target_order AND q.status='ready' AND public.or_shipping_verified_balance(q.id)<q.original_total+q.shipping_cost) THEN RAISE EXCEPTION 'ยอดชำระเปลี่ยนไป ต้องตรวจสอบก่อนแพ็ค'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: pk_list_search_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_list_search_key(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT lower(regexp_replace(p_value,
    U&'[[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]', '', 'g'));
$$;


--
-- Name: pk_preserve_completed_upload_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_preserve_completed_upload_report() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- A late browser heartbeat must never downgrade server-confirmed success.
  IF OLD.status = 'success' AND NEW.status <> 'success' THEN
    NEW.status := 'success';
    NEW.uploaded_at := OLD.uploaded_at;
    NEW.last_error := NULL;
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;


--
-- Name: pk_reset_order_packing(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_reset_order_packing(p_order_id uuid, p_reason text, p_reset_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_order public.or_orders;
  v_is_shipped BOOLEAN;
  v_tag JSONB;
  v_reset_type TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role NOT IN ('superadmin', 'admin', 'packing_staff', 'production', 'sales-tr') THEN
    RAISE EXCEPTION 'Not authorized to reset packing';
  END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('PACK:' || COALESCE(v_order.work_order_name, ''), 0));

  v_is_shipped := v_order.status = 'จัดส่งแล้ว';
  IF v_is_shipped AND v_role NOT IN ('superadmin', 'admin') THEN
    RAISE EXCEPTION 'Only superadmin/admin can cancel a shipped order';
  END IF;
  IF v_is_shipped AND NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required to cancel shipment';
  END IF;
  v_reset_type := CASE WHEN v_is_shipped THEN 'cancel_shipment' ELSE 'rescan' END;

  INSERT INTO public.pk_packing_reset_logs(
    order_id, work_order_name, reset_type, reason, previous_status,
    previous_packing_meta, previous_shipped_by, previous_shipped_time, reset_by
  ) VALUES (
    v_order.id, v_order.work_order_name, v_reset_type,
    COALESCE(NULLIF(trim(p_reason), ''), 'เริ่มแพ็คใหม่'), v_order.status,
    v_order.packing_meta, v_order.shipped_by, v_order.shipped_time, p_reset_by
  );

  DELETE FROM public.pk_packing_unit_scans WHERE order_id = v_order.id;

  -- Keep the daily tag for traceability; clear only scan-state metadata.
  v_tag := CASE
    WHEN v_order.packing_meta ? 'dailyPackingTag'
      THEN jsonb_build_object('dailyPackingTag', v_order.packing_meta->'dailyPackingTag')
    ELSE NULL
  END;
  UPDATE public.or_orders
  SET status = CASE WHEN v_is_shipped THEN 'ใบงานกำลังผลิต' ELSE status END,
      packing_meta = v_tag,
      shipped_by = CASE WHEN v_is_shipped THEN NULL ELSE shipped_by END,
      shipped_time = CASE WHEN v_is_shipped THEN NULL ELSE shipped_time END
  WHERE id = v_order.id;

  IF v_is_shipped AND v_order.work_order_name IS NOT NULL THEN
    UPDATE public.or_work_orders SET status = 'กำลังผลิต'
    WHERE work_order_name = v_order.work_order_name;
    PERFORM public.merge_plan_tracks_by_name(
      v_order.work_order_name,
      'PACK',
      jsonb_build_object(
        'เริ่มแพ็ค', jsonb_build_object('end', NULL),
        'เสร็จแล้ว', jsonb_build_object('start', NULL, 'end', NULL)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'reset_type', v_reset_type,
    'work_order_name', v_order.work_order_name,
    'packing_tag', v_order.packing_meta->'dailyPackingTag'
  );
END;
$$;


--
-- Name: pk_shipped_work_orders_page(integer, integer, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_shipped_work_orders_page(p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_channel text DEFAULT NULL::text, p_packer text DEFAULT NULL::text, p_search text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH history AS MATERIALIZED (
    SELECT id, work_order_id, work_order_name, shipped_time, channel_code, shipped_by,
      bill_no, customer_name, tracking_number, express_receipt_number
    FROM public.or_orders
    WHERE status = 'จัดส่งแล้ว' AND work_order_name IS NOT NULL
  ), filtered AS (
    SELECT * FROM history
    -- Preserve the existing UTC calendar-date filtering, including undated rows.
    WHERE work_order_name <> ''
      AND (p_date_from IS NULL OR (shipped_time AT TIME ZONE 'UTC')::date >= p_date_from)
      AND (p_date_to IS NULL OR shipped_time IS NULL OR (shipped_time AT TIME ZONE 'UTC')::date <= p_date_to)
      AND (nullif(p_channel, '') IS NULL OR channel_code = p_channel)
      AND (nullif(p_packer, '') IS NULL OR shipped_by = p_packer)
  ), grouped AS MATERIALIZED (
    SELECT work_order_id, work_order_name, count(*) AS order_count,
      max(shipped_time) AS shipped_time,
      coalesce(jsonb_agg(DISTINCT channel_code) FILTER (WHERE nullif(channel_code, '') IS NOT NULL), '[]') AS channels,
      coalesce(jsonb_agg(DISTINCT shipped_by) FILTER (WHERE nullif(shipped_by, '') IS NOT NULL), '[]') AS packers
    FROM filtered
    GROUP BY work_order_id, work_order_name
    -- Search selects whole groups, not just the bill that matched.
    HAVING btrim(coalesce(p_search, '')) = '' OR bool_or(
      strpos(lower(coalesce(bill_no, '')), lower(btrim(p_search))) > 0
      OR strpos(lower(coalesce(customer_name, '')), lower(btrim(p_search))) > 0
      OR (public.pk_list_search_key(p_search) <> '' AND (
        strpos(public.pk_list_search_key(coalesce(tracking_number, '')), public.pk_list_search_key(p_search)) > 0
        OR strpos(public.pk_list_search_key(coalesce(express_receipt_number, '')), public.pk_list_search_key(p_search)) > 0
      ))
    )
  ), bounds AS (
    SELECT count(*) AS total, greatest(1, least(coalesce(p_page_size, 50), 100)) AS size
    FROM grouped
  ), pagination AS (
    SELECT *, greatest(1, least(greatest(coalesce(p_page, 1), 1),
      greatest(1, ceil(total::numeric / size)::integer))) AS page FROM bounds
  ), page_rows AS (
    SELECT * FROM grouped
    ORDER BY shipped_time ASC NULLS FIRST, work_order_name, work_order_id NULLS FIRST
    LIMIT (SELECT size FROM pagination)
    OFFSET (SELECT (page - 1)::bigint * size FROM pagination)
  )
  SELECT jsonb_build_object(
    'rows', coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.shipped_time ASC NULLS FIRST, r.work_order_name, r.work_order_id NULLS FIRST) FROM page_rows r), '[]'),
    'total', total, 'page', page,
    'channels', coalesce((SELECT jsonb_agg(v ORDER BY v) FROM (SELECT DISTINCT channel_code AS v FROM history WHERE nullif(btrim(channel_code), '') IS NOT NULL) f), '[]'),
    'packers', coalesce((SELECT jsonb_agg(v ORDER BY v) FROM (SELECT DISTINCT shipped_by AS v FROM history WHERE nullif(btrim(shipped_by), '') IS NOT NULL) f), '[]')
  ) FROM pagination;
$$;


--
-- Name: pk_start_work_order_packing(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_start_work_order_packing(p_work_order_name text, p_started_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.or_orders WHERE work_order_name=p_work_order_name AND shipping_conversion_pending) AND NOT EXISTS(SELECT 1 FROM public.or_orders WHERE work_order_name=p_work_order_name AND NOT shipping_conversion_pending AND status NOT IN ('ยกเลิก','จัดส่งแล้ว')) THEN RAISE EXCEPTION 'ใบงานมีบิลรอตรวจค่าส่ง/อนุมัติค่าส่ง 0'; END IF;
 RETURN public.pk_start_work_order_packing_before_shipping_guard(p_work_order_name,p_started_at);
END $$;


--
-- Name: pk_start_work_order_packing_before_shipping_guard(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_start_work_order_packing_before_shipping_guard(p_work_order_name text, p_started_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_name TEXT;
  v_started_at TIMESTAMPTZ;
  v_tracks JSONB;
BEGIN
  SELECT role INTO v_role
  FROM public.us_users
  WHERE id = auth.uid();

  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'production', 'packing_staff') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เริ่มแพ็ค (role: %)', coalesce(v_role, 'unknown');
  END IF;

  v_name := nullif(trim(coalesce(p_work_order_name, '')), '');
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'p_work_order_name ห้ามว่าง';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.plan_jobs WHERE name = v_name) THEN
    RAISE EXCEPTION 'ไม่พบใบงาน % ใน Plan', v_name;
  END IF;

  v_started_at := coalesce(p_started_at, now());
  v_tracks := public.merge_plan_tracks_by_name(
    v_name,
    'PACK',
    jsonb_build_object(
      'เริ่มแพ็ค',
      jsonb_build_object('start_if_null', to_jsonb(v_started_at))
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'work_order_name', v_name,
    'started_at', v_started_at,
    'tracks', v_tracks
  );
END;
$$;


--
-- Name: FUNCTION pk_start_work_order_packing_before_shipping_guard(p_work_order_name text, p_started_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pk_start_work_order_packing_before_shipping_guard(p_work_order_name text, p_started_at timestamp with time zone) IS 'บันทึกเวลาเริ่ม PACK ลง Plan เมื่อเปิดใบงานในหน้าแพ็ค โดยไม่เขียนทับเวลาเดิม';


--
-- Name: pk_touch_packing_device_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_touch_packing_device_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;


--
-- Name: pk_upload_reports_page(integer, integer, timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_upload_reports_page(p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_device_id text DEFAULT NULL::text, p_search text DEFAULT ''::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH visible AS NOT MATERIALIZED (
    SELECT id, user_id, recorded_by, device_id, device_name, folder_name, folder_path,
      work_order_name, tracking_number, channel_order_no, filename, storage_path,
      file_size_bytes, duration_seconds, status, retry_count, last_error, local_deleted,
      client_created_at, client_updated_at, uploaded_at, reported_at, quality_profile,
      requested_width, requested_height, requested_fps, requested_bitrate,
      actual_width, actual_height, actual_fps, mime_type, codec, recorder_bitrate, actual_bitrate
    FROM public.pk_packing_upload_queue_reports WHERE dismissed_at IS NULL
  ), searched AS MATERIALIZED (
    -- Keep the materialized search/summary working set narrow. Fetch wide video
    -- metadata only for the displayed IDs, avoiding temp-file spills on history.
    SELECT id, client_created_at, CASE
      WHEN status IN ('pending', 'uploading') AND (
        reported_at IS NULL OR NOT isfinite(reported_at)
        OR reported_at <= now() - CASE WHEN status = 'pending' THEN interval '30 minutes' ELSE interval '10 minutes' END
      ) THEN 'failed' ELSE status END AS effective_status
    FROM visible r
    WHERE (p_from IS NULL OR client_created_at >= p_from)
      -- JS Date filters have millisecond precision; retain the entire final ms.
      AND (p_to IS NULL OR client_created_at < p_to + interval '1 millisecond')
      AND (nullif(p_device_id, '') IS NULL OR device_id = p_device_id)
      AND (coalesce(public.pk_list_search_key(p_search), '') = '' OR EXISTS (
        SELECT 1 FROM unnest(ARRAY[recorded_by, device_name, folder_path, folder_name,
          work_order_name, tracking_number, channel_order_no, filename]) AS fields(value)
        WHERE strpos(public.pk_list_search_key(coalesce(value, '')), public.pk_list_search_key(p_search)) > 0
      ))
  ), matching AS (
    SELECT * FROM searched WHERE nullif(p_status, '') IS NULL OR effective_status = p_status
  ), bounds AS (
    SELECT count(*) AS total, greatest(1, least(coalesce(p_page_size, 50), 100)) AS size FROM matching
  ), pagination AS (
    SELECT *, greatest(1, least(greatest(coalesce(p_page, 1), 1),
      greatest(1, ceil(total::numeric / size)::integer))) AS page FROM bounds
  ), page_ids AS (
    SELECT id FROM matching ORDER BY client_created_at DESC, id DESC
    LIMIT (SELECT size FROM pagination)
    OFFSET (SELECT (page - 1)::bigint * size FROM pagination)
  ), page_rows AS (
    SELECT v.* FROM visible v JOIN page_ids p ON p.id = v.id
  )
  SELECT jsonb_build_object(
    'rows', coalesce((SELECT jsonb_agg(to_jsonb(r) - 'effective_status' ORDER BY r.client_created_at DESC, r.id DESC) FROM page_rows r), '[]'),
    'total', total, 'page', page, 'as_of', now(),
    'summary', (SELECT jsonb_build_object(
      'pending', count(*) FILTER (WHERE effective_status = 'pending'),
      'uploading', count(*) FILTER (WHERE effective_status = 'uploading'),
      'success', count(*) FILTER (WHERE effective_status = 'success'),
      'failed', count(*) FILTER (WHERE effective_status = 'failed')
    ) FROM searched),
    'stations', coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.last_seen_at DESC, d.device_id) FROM (
      SELECT device_id, user_id, device_name, last_username, is_active, quality_profile,
        folder_name, folder_path, pending_count, uploading_count, failed_count, last_seen_at
      FROM public.pk_packing_devices WHERE is_active = true
    ) d), '[]'),
    'devices', coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.device_id) FROM (
      SELECT DISTINCT ON (device_id) device_id, device_name FROM visible
      ORDER BY device_id, client_created_at DESC, id DESC
    ) d), '[]')
  ) FROM pagination;
$$;


--
-- Name: plan_apply_department_rename(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_apply_department_rename(p_old_name text, p_new_name text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old TEXT := btrim(COALESCE(p_old_name, ''));
  v_new TEXT := btrim(COALESCE(p_new_name, ''));
  v_data JSONB;
  v_key TEXT;
  v_object JSONB;
BEGIN
  IF v_old = '' OR v_new = '' THEN
    RAISE EXCEPTION 'ชื่อแผนกต้องไม่เป็นค่าว่าง';
  END IF;
  IF v_old = v_new THEN
    SELECT data INTO v_data FROM public.plan_settings WHERE id = 1;
    RETURN COALESCE(v_data, '{}'::JSONB);
  END IF;

  SELECT data INTO v_data
  FROM public.plan_settings
  WHERE id = 1
  FOR UPDATE;

  IF v_data IS NULL THEN
    RAISE EXCEPTION 'ไม่พบการตั้งค่าแผนการผลิต';
  END IF;

  -- A normal rename must not overwrite another department. If the old name is
  -- already absent, allow this call to repair stale rows left by an older rename.
  IF (v_data->'departments') ? v_old AND (v_data->'departments') ? v_new THEN
    RAISE EXCEPTION 'มีแผนกชื่อ % อยู่แล้ว', v_new;
  END IF;

  IF (v_data->'departments') ? v_old THEN
    v_data := jsonb_set(
      v_data,
      '{departments}',
      COALESCE((
        SELECT jsonb_agg(to_jsonb(CASE WHEN value = v_old THEN v_new ELSE value END) ORDER BY ordinality)
        FROM jsonb_array_elements_text(v_data->'departments') WITH ORDINALITY AS item(value, ordinality)
      ), '[]'::JSONB),
      true
    );
  END IF;

  FOREACH v_key IN ARRAY ARRAY[
    'processes', 'prepPerJob', 'startDelayPerJob', 'deptBreaks',
    'linesPerDept', 'departmentProductCategories'
  ] LOOP
    v_object := COALESCE(v_data->v_key, '{}'::JSONB);
    IF v_object ? v_old THEN
      v_object := (v_object - v_old)
        || jsonb_build_object(v_new, COALESCE(v_object->v_new, v_object->v_old));
      v_data := jsonb_set(v_data, ARRAY[v_key], v_object, true);
    END IF;
  END LOOP;

  UPDATE public.plan_jobs
  SET qty = CASE WHEN qty ? v_old THEN (qty - v_old) || jsonb_build_object(v_new, COALESCE(qty->v_new, qty->v_old)) ELSE qty END,
      tracks = CASE WHEN tracks ? v_old THEN (tracks - v_old) || jsonb_build_object(v_new, COALESCE(tracks->v_new, tracks->v_old)) ELSE tracks END,
      line_assignments = CASE WHEN line_assignments ? v_old THEN (line_assignments - v_old) || jsonb_build_object(v_new, COALESCE(line_assignments->v_new, line_assignments->v_old)) ELSE line_assignments END,
      manual_plan_starts = CASE WHEN manual_plan_starts ? v_old THEN (manual_plan_starts - v_old) || jsonb_build_object(v_new, COALESCE(manual_plan_starts->v_new, manual_plan_starts->v_old)) ELSE manual_plan_starts END,
      locked_plans = CASE WHEN locked_plans ? v_old THEN (locked_plans - v_old) || jsonb_build_object(v_new, COALESCE(locked_plans->v_new, locked_plans->v_old)) ELSE locked_plans END,
      follow_notes = CASE WHEN follow_notes ? v_old THEN (follow_notes - v_old) || jsonb_build_object(v_new, COALESCE(follow_notes->v_new, follow_notes->v_old)) ELSE follow_notes END
  WHERE qty ? v_old OR tracks ? v_old OR line_assignments ? v_old
     OR manual_plan_starts ? v_old OR locked_plans ? v_old OR follow_notes ? v_old;

  -- Prefer records already created under the new name when both names exist.
  DELETE FROM public.plan_employee_skills old_row
  USING public.plan_employee_skills new_row
  WHERE old_row.department_name = v_old
    AND new_row.department_name = v_new
    AND new_row.employee_id = old_row.employee_id
    AND new_row.process_name = old_row.process_name;
  UPDATE public.plan_employee_skills SET department_name = v_new WHERE department_name = v_old;

  DELETE FROM public.plan_operation_requirements old_row
  USING public.plan_operation_requirements new_row
  WHERE old_row.department_name = v_old
    AND new_row.department_name = v_new
    AND new_row.process_name = old_row.process_name;
  UPDATE public.plan_operation_requirements SET department_name = v_new WHERE department_name = v_old;

  -- Cancel only an obsolete active duplicate before changing the remaining history.
  UPDATE public.plan_worker_assignments old_row
  SET status = 'cancelled'
  WHERE old_row.department_name = v_old
    AND old_row.status NOT IN ('cancelled', 'completed')
    AND EXISTS (
      SELECT 1
      FROM public.plan_worker_assignments new_row
      WHERE new_row.department_name = v_new
        AND new_row.plan_job_id = old_row.plan_job_id
        AND new_row.employee_id = old_row.employee_id
        AND new_row.process_name = old_row.process_name
        AND new_row.assignment_role = old_row.assignment_role
        AND new_row.status NOT IN ('cancelled', 'completed')
    );
  UPDATE public.plan_worker_assignments SET department_name = v_new WHERE department_name = v_old;

  UPDATE public.pr_machinery_machines SET department_name = v_new WHERE department_name = v_old;

  UPDATE public.plan_settings
  SET data = v_data, updated_at = now()
  WHERE id = 1;

  RETURN v_data;
END;
$$;


--
-- Name: plan_worker_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.plan_worker_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_job_id text NOT NULL,
    employee_id uuid NOT NULL,
    department_name text NOT NULL,
    process_name text NOT NULL,
    line_no smallint DEFAULT 1 NOT NULL,
    planned_start timestamp with time zone NOT NULL,
    planned_end timestamp with time zone NOT NULL,
    status text DEFAULT 'planned'::text NOT NULL,
    assignment_source text DEFAULT 'manual'::text NOT NULL,
    score numeric(7,3),
    score_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    assigned_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    assignment_role text DEFAULT 'operator'::text NOT NULL,
    CONSTRAINT plan_worker_assignments_assignment_role_check CHECK ((assignment_role = ANY (ARRAY['operator'::text, 'supervisor'::text]))),
    CONSTRAINT plan_worker_assignments_assignment_source_check CHECK ((assignment_source = ANY (ARRAY['manual'::text, 'suggested'::text, 'automatic'::text]))),
    CONSTRAINT plan_worker_assignments_check CHECK ((planned_end > planned_start)),
    CONSTRAINT plan_worker_assignments_line_no_check CHECK ((line_no > 0)),
    CONSTRAINT plan_worker_assignments_status_check CHECK ((status = ANY (ARRAY['suggested'::text, 'planned'::text, 'confirmed'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text])))
);


--
-- Name: plan_assign_worker(text, uuid, text, text, integer, timestamp with time zone, timestamp with time zone, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_assign_worker(p_plan_job_id text, p_employee_id uuid, p_department_name text, p_process_name text, p_line_no integer, p_planned_start timestamp with time zone, p_planned_end timestamp with time zone, p_assignment_role text DEFAULT 'operator'::text, p_score numeric DEFAULT NULL::numeric, p_score_detail jsonb DEFAULT '{}'::jsonb) RETURNS public.plan_worker_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.plan_worker_assignments;
  v_existing public.plan_worker_assignments;
  v_capacity INTEGER := 1;
  v_peak INTEGER := 0;
  v_allow_supervisor_as_worker BOOLEAN := false;
  v_required_supervisors INTEGER := 0;
BEGIN
  IF NOT public.hr_is_admin() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดสรรกำลังคน'; END IF;
  IF p_planned_end <= p_planned_start THEN RAISE EXCEPTION 'ช่วงเวลาจัดสรรไม่ถูกต้อง'; END IF;
  IF p_assignment_role NOT IN ('operator','supervisor') THEN RAISE EXCEPTION 'ประเภทการจัดสรรไม่ถูกต้อง'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_employee_id::TEXT));

  -- Make repeated requests idempotent.
  SELECT * INTO v_existing
  FROM public.plan_worker_assignments
  WHERE plan_job_id = p_plan_job_id
    AND employee_id = p_employee_id
    AND department_name = p_department_name
    AND process_name = p_process_name
    AND assignment_role = p_assignment_role
    AND status NOT IN ('cancelled','completed')
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN v_existing;
  END IF;

  -- Promoting the current operator to supervisor is a role change, not a new
  -- overlapping job. The same row will subsequently cover both quotas.
  IF p_assignment_role = 'supervisor' THEN
    SELECT * INTO v_existing
    FROM public.plan_worker_assignments
    WHERE plan_job_id = p_plan_job_id
      AND employee_id = p_employee_id
      AND department_name = p_department_name
      AND process_name = p_process_name
      AND assignment_role = 'operator'
      AND status NOT IN ('cancelled','completed')
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.plan_worker_assignments
      SET assignment_role = 'supervisor',
          line_no = GREATEST(1, p_line_no),
          planned_start = p_planned_start,
          planned_end = p_planned_end,
          score = p_score,
          score_detail = COALESCE(score_detail, '{}'::JSONB)
            || COALESCE(p_score_detail, '{}'::JSONB)
            || jsonb_build_object(
              'role_promoted_from', 'operator',
              'role_promoted_at', now()
            ),
          updated_at = now()
      WHERE id = v_existing.id
      RETURNING * INTO v_row;
      RETURN v_row;
    END IF;
  END IF;

  -- If a supervisor already covers production, an operator request for the
  -- same person/process is already satisfied and must not create a duplicate.
  IF p_assignment_role = 'operator' THEN
    SELECT * INTO v_existing
    FROM public.plan_worker_assignments
    WHERE plan_job_id = p_plan_job_id
      AND employee_id = p_employee_id
      AND department_name = p_department_name
      AND process_name = p_process_name
      AND assignment_role = 'supervisor'
      AND status NOT IN ('cancelled','completed')
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      SELECT COALESCE((data->>'allow_supervisor_as_worker')::BOOLEAN, false)
      INTO v_allow_supervisor_as_worker
      FROM public.plan_settings
      WHERE id = 1;

      SELECT COALESCE(required_supervisors, 0)
      INTO v_required_supervisors
      FROM public.plan_operation_requirements
      WHERE department_name = p_department_name
        AND process_name = p_process_name;

      IF v_allow_supervisor_as_worker AND COALESCE(v_required_supervisors, 0) > 0 THEN
        RETURN v_existing;
      END IF;

      RAISE EXCEPTION 'พนักงานถูกจัดเป็นหัวหน้าคุมงานของกระบวนการนี้แล้ว';
    END IF;
  END IF;

  v_capacity := public.plan_employee_process_capacity(
    p_employee_id, p_department_name, p_process_name
  );
  v_peak := public.plan_assignment_peak_load(
    p_employee_id, p_planned_start, p_planned_end
  );

  IF v_peak >= v_capacity THEN
    RAISE EXCEPTION 'พนักงานรับงานกระบวนการ % พร้อมกันครบจำนวนสูงสุดแล้ว (% งาน) และช่วงคาบเกี่ยวเกิน 5 นาที', p_process_name, v_capacity;
  END IF;

  INSERT INTO public.plan_worker_assignments(
    plan_job_id, employee_id, department_name, process_name, line_no,
    planned_start, planned_end, status, assignment_source, assignment_role,
    score, score_detail, assigned_by
  ) VALUES (
    p_plan_job_id, p_employee_id, p_department_name, p_process_name, GREATEST(1,p_line_no),
    p_planned_start, p_planned_end, 'confirmed', 'manual', p_assignment_role,
    p_score, COALESCE(p_score_detail,'{}'::JSONB) || jsonb_build_object(
      'max_concurrent_jobs', v_capacity,
      'capacity_scope', 'employee_process',
      'overlap_tolerance_minutes', 5
    ), auth.uid()
  ) RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: plan_assignment_peak_load(uuid, timestamp with time zone, timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_assignment_peak_load(p_employee_id uuid, p_planned_start timestamp with time zone, p_planned_end timestamp with time zone, p_exclude_assignment_id uuid DEFAULT NULL::uuid, p_current_job_id text DEFAULT NULL::text, p_current_assignment_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH relevant AS (
    SELECT
      GREATEST(a.planned_start, p_planned_start) AS clipped_start,
      LEAST(a.planned_end, p_planned_end) AS clipped_end
    FROM public.plan_worker_assignments a
    WHERE a.employee_id = p_employee_id
      AND a.status NOT IN ('cancelled', 'completed')
      AND (p_exclude_assignment_id IS NULL OR a.id <> p_exclude_assignment_id)
      AND (
        p_current_job_id IS NULL
        OR a.plan_job_id <> p_current_job_id
        OR a.id < p_current_assignment_id
      )
      AND LEAST(a.planned_end, p_planned_end)
          - GREATEST(a.planned_start, p_planned_start) > INTERVAL '5 minutes'
  ), events AS (
    SELECT clipped_start AS event_at, 1 AS delta, 1 AS event_order FROM relevant
    UNION ALL
    SELECT clipped_end AS event_at, -1 AS delta, 0 AS event_order FROM relevant
  ), running AS (
    SELECT SUM(delta) OVER (
      ORDER BY event_at, event_order
      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS active_count
    FROM events
  )
  SELECT COALESCE(MAX(active_count), 0)::INTEGER FROM running;
$$;


--
-- Name: plan_employee_process_capacity(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_employee_process_capacity(p_employee_id uuid, p_department_name text, p_process_name text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT skill.max_concurrent_jobs
      FROM public.plan_employee_skills skill
      WHERE skill.employee_id = p_employee_id
        AND skill.department_name = p_department_name
        AND skill.process_name = p_process_name
    ),
    (
      SELECT profile.max_concurrent_jobs
      FROM public.plan_employee_profiles profile
      WHERE profile.employee_id = p_employee_id
    ),
    1
  )::INTEGER;
$$;


--
-- Name: plan_list_employees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_list_employees() RETURNS TABLE(id uuid, employee_code text, first_name text, last_name text, nickname text, employment_status text, department jsonb, "position" jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    e.id,
    e.employee_code,
    e.first_name,
    e.last_name,
    e.nickname,
    e.employment_status,
    CASE WHEN d.id IS NULL THEN NULL ELSE jsonb_build_object('name', d.name) END,
    CASE WHEN p.id IS NULL THEN NULL ELSE jsonb_build_object('name', p.name) END
  FROM public.hr_employees e
  LEFT JOIN public.hr_departments d ON d.id = e.department_id
  LEFT JOIN public.hr_positions p ON p.id = e.position_id
  WHERE EXISTS (
    SELECT 1
    FROM public.us_users u
    WHERE u.id = auth.uid()
      AND u.role IN ('superadmin', 'admin', 'production')
  )
  ORDER BY e.employee_code;
$$;


--
-- Name: plan_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.plan_jobs (
    id text NOT NULL,
    date text NOT NULL,
    name text NOT NULL,
    cut text,
    qty jsonb DEFAULT '{}'::jsonb NOT NULL,
    tracks jsonb DEFAULT '{}'::jsonb NOT NULL,
    line_assignments jsonb DEFAULT '{}'::jsonb NOT NULL,
    manual_plan_starts jsonb DEFAULT '{}'::jsonb NOT NULL,
    locked_plans jsonb DEFAULT '{}'::jsonb NOT NULL,
    order_index integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    is_production_voided boolean DEFAULT false NOT NULL,
    work_order_id uuid,
    follow_notes jsonb DEFAULT '{}'::jsonb NOT NULL,
    manpower_locked_at timestamp with time zone,
    manpower_locked_by uuid,
    production_voided_at timestamp with time zone
);


--
-- Name: COLUMN plan_jobs.follow_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.plan_jobs.follow_notes IS 'โน้ตติดตามของหัวหน้างานต่อแผนก: { "<dept>": "almost" (ใกล้เสร็จ) | "slow" (อาจจะช้า) } (284)';


--
-- Name: COLUMN plan_jobs.production_voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.plan_jobs.production_voided_at IS 'Time production was stopped because every active item in the work order was cancelled.';


--
-- Name: plan_lock_manpower(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_lock_manpower(p_plan_job_id text) RETURNS public.plan_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schedules JSONB := '{}'::JSONB;
BEGIN
  SELECT COALESCE(
    jsonb_object_agg(
      quantity.key || '|' || (process_item->>'name'),
      '{}'::JSONB
    ),
    '{}'::JSONB
  )
  INTO v_schedules
  FROM public.plan_jobs job
  CROSS JOIN LATERAL jsonb_each_text(COALESCE(job.qty, '{}'::JSONB)) quantity
  JOIN public.plan_settings settings ON settings.id = 1
  CROSS JOIN LATERAL jsonb_array_elements(
    COALESCE(settings.data->'processes'->quantity.key, '[]'::JSONB)
  ) process_item
  WHERE job.id = p_plan_job_id
    AND COALESCE(NULLIF(quantity.value, '')::NUMERIC, 0) > 0
    AND NULLIF(process_item->>'name', '') IS NOT NULL;

  RETURN public.plan_lock_manpower(p_plan_job_id, v_schedules);
END;
$$;


--
-- Name: plan_lock_manpower(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_lock_manpower(p_plan_job_id text, p_schedules jsonb) RETURNS public.plan_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.plan_jobs;
  v_missing INT := 0;
  v_process_count INT := 0;
  v_allow_supervisor_as_worker BOOLEAN := false;
BEGIN
  IF NOT public.hr_is_admin() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ล็อกแผนกำลังคน';
  END IF;

  SELECT * INTO v_job
  FROM public.plan_jobs
  WHERE id = p_plan_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบใบงาน';
  END IF;

  IF COALESCE(jsonb_typeof(p_schedules), '') <> 'object' THEN
    RAISE EXCEPTION 'ข้อมูลกระบวนการของใบงานไม่ถูกต้อง กรุณารีเฟรชหน้าแล้วลองใหม่';
  END IF;

  SELECT COUNT(*) INTO v_process_count
  FROM jsonb_object_keys(p_schedules) AS schedule_keys(schedule_key)
  WHERE position('|' IN schedule_key) > 1;

  IF v_process_count = 0 THEN
    RAISE EXCEPTION 'ไม่พบกระบวนการของใบงาน กรุณารีเฟรชหน้าแล้วลองใหม่';
  END IF;

  SELECT COALESCE((data->>'allow_supervisor_as_worker')::BOOLEAN, false)
  INTO v_allow_supervisor_as_worker
  FROM public.plan_settings
  WHERE id = 1;

  SELECT COALESCE(SUM(
    CASE
      WHEN v_allow_supervisor_as_worker AND active.required_supervisors > 0 THEN
        GREATEST(
          GREATEST(
            0,
            active.required_workers
              - (COALESCE(assigned.operator_count, 0) + COALESCE(assigned.supervisor_count, 0))
          ),
          GREATEST(
            0,
            active.required_supervisors - COALESCE(assigned.supervisor_count, 0)
          )
        )
      ELSE
        GREATEST(
          0,
          active.required_workers - COALESCE(assigned.operator_count, 0)
        )
        + GREATEST(
          0,
          active.required_supervisors - COALESCE(assigned.supervisor_count, 0)
        )
    END
  ), 0)::INT
  INTO v_missing
  FROM (
    SELECT
      split_part(schedule_key, '|', 1) AS department_name,
      substring(schedule_key FROM position('|' IN schedule_key) + 1) AS process_name,
      COALESCE(requirement.required_workers, 1) AS required_workers,
      COALESCE(requirement.required_supervisors, 0) AS required_supervisors
    FROM jsonb_object_keys(p_schedules) AS schedule_keys(schedule_key)
    LEFT JOIN public.plan_operation_requirements requirement
      ON requirement.department_name = split_part(schedule_key, '|', 1)
     AND requirement.process_name = substring(schedule_key FROM position('|' IN schedule_key) + 1)
    WHERE position('|' IN schedule_key) > 1
  ) active
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*) FILTER (WHERE assignment.assignment_role = 'operator') AS operator_count,
      COUNT(*) FILTER (WHERE assignment.assignment_role = 'supervisor') AS supervisor_count
    FROM public.plan_worker_assignments assignment
    WHERE assignment.plan_job_id = p_plan_job_id
      AND assignment.department_name = active.department_name
      AND assignment.process_name = active.process_name
      -- A completed assignment is still proof that the position was staffed.
      AND assignment.status <> 'cancelled'
  ) assigned ON true;

  IF v_missing > 0 THEN
    RAISE EXCEPTION 'ยังจัดกำลังคนไม่ครบ % ตำแหน่ง', v_missing;
  END IF;

  UPDATE public.plan_jobs
  SET manpower_locked_at = now(), manpower_locked_by = auth.uid()
  WHERE id = p_plan_job_id
  RETURNING * INTO v_job;

  RETURN v_job;
END;
$$;


--
-- Name: plan_prepare_employee_skill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_prepare_employee_skill() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- ซิงก์กลับไปยังฟิลด์เดิมสำหรับหน้าหรือรายงานรุ่นเก่า
  NEW.qualification_status := CASE
    WHEN NEW.skill_level = 0 THEN 'blocked'
    WHEN NEW.skill_level = 1 THEN 'training'
    ELSE 'qualified'
  END;
  NEW.proficiency := CASE NEW.skill_level WHEN 3 THEN 4 WHEN 2 THEN 3 ELSE 1 END;
  NEW.efficiency_percent := 100;

  IF NEW.skill_level < 2 THEN
    NEW.is_primary := false;
    NEW.is_supervisor := false;
  END IF;
  IF NEW.skill_level <= 1 THEN
    NEW.max_concurrent_jobs := 1;
  END IF;

  IF NOT NEW.is_primary THEN
    NEW.primary_queue_order := NULL;
  ELSIF NEW.primary_queue_order IS NULL THEN
    SELECT COALESCE(MAX(skill.primary_queue_order), 0) + 1
    INTO NEW.primary_queue_order
    FROM public.plan_employee_skills skill
    WHERE skill.department_name = NEW.department_name
      AND skill.process_name = NEW.process_name
      AND skill.is_primary
      AND (TG_OP = 'INSERT' OR skill.id <> NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: plan_prevent_cross_process_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_prevent_cross_process_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status NOT IN ('cancelled','completed') AND EXISTS (
    SELECT 1
    FROM public.plan_worker_assignments assignment
    WHERE assignment.employee_id = NEW.employee_id
      AND assignment.id <> NEW.id
      AND assignment.status NOT IN ('cancelled','completed')
      AND (assignment.department_name, assignment.process_name) IS DISTINCT FROM (NEW.department_name, NEW.process_name)
      AND LEAST(assignment.planned_end, NEW.planned_end) - GREATEST(assignment.planned_start, NEW.planned_start) > INTERVAL '5 minutes'
  ) THEN
    RAISE EXCEPTION 'พนักงานมีงานคนละกระบวนการในช่วงเวลานี้แล้ว งานซ้อนอนุญาตเฉพาะกระบวนการเดียวกัน';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: plan_rename_department(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_rename_department(p_old_name text, p_new_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid() AND role IN ('superadmin', 'admin')
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เปลี่ยนชื่อแผนก';
  END IF;
  RETURN public.plan_apply_department_rename(p_old_name, p_new_name);
END;
$$;


--
-- Name: plan_reorder_primary_queue(text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_reorder_primary_queue(p_department_name text, p_process_name text, p_employee_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expected_count INTEGER;
  v_submitted_count INTEGER;
BEGIN
  IF NOT public.hr_is_admin() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์จัดลำดับคิวงานหลัก';
  END IF;

  SELECT COUNT(*) INTO v_expected_count
  FROM public.plan_employee_skills
  WHERE department_name = p_department_name
    AND process_name = p_process_name
    AND is_primary;

  SELECT COUNT(DISTINCT submitted.employee_id) INTO v_submitted_count
  FROM unnest(COALESCE(p_employee_ids, ARRAY[]::UUID[])) AS submitted(employee_id);

  IF v_submitted_count <> v_expected_count OR EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_employee_ids, ARRAY[]::UUID[])) submitted(employee_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.plan_employee_skills skill
      WHERE skill.employee_id = submitted.employee_id
        AND skill.department_name = p_department_name
        AND skill.process_name = p_process_name
        AND skill.is_primary
    )
  ) THEN
    RAISE EXCEPTION 'รายชื่อคิวงานหลักมีการเปลี่ยนแปลง กรุณาโหลดข้อมูลใหม่แล้วลองอีกครั้ง';
  END IF;

  UPDATE public.plan_employee_skills skill
  SET primary_queue_order = ordered.queue_order
  FROM unnest(p_employee_ids) WITH ORDINALITY ordered(employee_id, queue_order)
  WHERE skill.employee_id = ordered.employee_id
    AND skill.department_name = p_department_name
    AND skill.process_name = p_process_name
    AND skill.is_primary;
END;
$$;


--
-- Name: plan_sync_job_manpower_schedule(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_sync_job_manpower_schedule(p_plan_job_id text, p_schedules jsonb, p_line_assignments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.plan_jobs;
  v_assignment public.plan_worker_assignments;
  v_conflict public.plan_worker_assignments;
  v_schedule JSONB;
  v_row JSONB;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
  v_line INT;
  v_capacity INT;
  v_peak INT;
  v_synced JSONB := '[]'::JSONB;
  v_reassignments JSONB := '[]'::JSONB;
BEGIN
  IF NOT public.hr_is_admin() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ปรับแผนกำลังคน'; END IF;
  SELECT * INTO v_job FROM public.plan_jobs WHERE id = p_plan_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบใบงาน'; END IF;
  IF v_job.manpower_locked_at IS NOT NULL THEN RAISE EXCEPTION 'ใบงานนี้บันทึกและล็อกกำลังคนแล้ว กรุณาปลดล็อกก่อนเปลี่ยนแผน'; END IF;

  FOR v_assignment IN
    SELECT * FROM public.plan_worker_assignments
    WHERE plan_job_id = p_plan_job_id AND status NOT IN ('cancelled','completed')
    ORDER BY id FOR UPDATE
  LOOP
    v_schedule := COALESCE(
      p_schedules -> (v_assignment.department_name || '|' || v_assignment.process_name),
      p_schedules -> v_assignment.department_name
    );
    IF v_schedule IS NULL THEN RAISE EXCEPTION 'ไม่พบเวลาของ % / %', v_assignment.department_name, v_assignment.process_name; END IF;
    v_start := (v_job.date || 'T' || (v_schedule->>'start') || ':00+07:00')::TIMESTAMPTZ;
    v_end := (v_job.date || 'T' || (v_schedule->>'end') || ':00+07:00')::TIMESTAMPTZ;
    IF v_end <= v_start THEN v_start := v_end - INTERVAL '1 minute'; END IF;
    v_line := GREATEST(1, COALESCE((p_line_assignments->>v_assignment.department_name)::INT,0)+1);
    v_capacity := public.plan_employee_process_capacity(
      v_assignment.employee_id,
      v_assignment.department_name,
      v_assignment.process_name
    );
    v_peak := public.plan_assignment_peak_load(
      v_assignment.employee_id, v_start, v_end, v_assignment.id,
      p_plan_job_id, v_assignment.id
    );

    IF v_peak >= v_capacity THEN
      SELECT x.* INTO v_conflict FROM public.plan_worker_assignments x
      WHERE x.employee_id = v_assignment.employee_id AND x.id <> v_assignment.id
        AND x.status NOT IN ('cancelled','completed')
        AND (x.plan_job_id <> p_plan_job_id OR x.id < v_assignment.id)
        AND LEAST(x.planned_end, v_end) - GREATEST(x.planned_start, v_start) > INTERVAL '5 minutes'
      ORDER BY x.planned_start, x.id LIMIT 1;
      IF v_assignment.status = 'in_progress' THEN
        RAISE EXCEPTION 'พนักงานในกระบวนการ % กำลังทำงานและเกินจำนวนงานซ้อนสูงสุดของกระบวนการ', v_assignment.process_name;
      END IF;
      UPDATE public.plan_worker_assignments
      SET status = 'cancelled', score_detail = COALESCE(score_detail,'{}'::JSONB) || jsonb_build_object(
        'cancel_reason','schedule_capacity_conflict','capacity_scope','employee_process',
        'max_concurrent_jobs',v_capacity,'cancelled_at',now(),
        'proposed_start',v_start,'proposed_end',v_end,
        'conflict_assignment_id',v_conflict.id,'conflict_plan_job_id',v_conflict.plan_job_id
      ) WHERE id = v_assignment.id;
      v_reassignments := v_reassignments || jsonb_build_array(jsonb_build_object(
        'assignment_id',v_assignment.id,'employee_id',v_assignment.employee_id,
        'department_name',v_assignment.department_name,'process_name',v_assignment.process_name,
        'proposed_start',v_start,'proposed_end',v_end,
        'conflict_plan_job_id',v_conflict.plan_job_id,'conflict_process_name',v_conflict.process_name,
        'conflict_start',v_conflict.planned_start,'conflict_end',v_conflict.planned_end
      ));
      CONTINUE;
    END IF;

    UPDATE public.plan_worker_assignments
    SET line_no = v_line, planned_start = v_start, planned_end = v_end,
        score_detail = COALESCE(score_detail,'{}'::JSONB) || jsonb_build_object(
          'max_concurrent_jobs',v_capacity,'capacity_scope','employee_process'
        )
    WHERE id = v_assignment.id
    RETURNING to_jsonb(plan_worker_assignments) INTO v_row;
    v_synced := v_synced || jsonb_build_array(v_row);
  END LOOP;
  RETURN jsonb_build_object('assignments',v_synced,'reassignments',v_reassignments);
END;
$$;


--
-- Name: plan_update_job_line_assignment(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_update_job_line_assignment(p_plan_job_id text, p_department_name text, p_line_index integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line_assignments jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.us_users u
    WHERE u.id = auth.uid()
      AND u.role IN ('superadmin', 'admin', 'production')
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขไลน์ผลิต';
  END IF;

  IF NULLIF(btrim(p_department_name), '') IS NULL OR p_line_index < 0 THEN
    RAISE EXCEPTION 'ข้อมูลไลน์ผลิตไม่ถูกต้อง';
  END IF;

  UPDATE public.plan_jobs
  SET line_assignments = jsonb_set(
    COALESCE(line_assignments, '{}'::jsonb),
    ARRAY[p_department_name],
    to_jsonb(p_line_index),
    true
  )
  WHERE id = p_plan_job_id
  RETURNING line_assignments INTO v_line_assignments;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบใบงาน';
  END IF;

  UPDATE public.plan_worker_assignments
  SET line_no = p_line_index + 1,
      updated_at = now()
  WHERE plan_job_id = p_plan_job_id
    AND department_name = p_department_name
    AND status <> 'cancelled';

  RETURN v_line_assignments;
END;
$$;


--
-- Name: pr_machinery_assign_ticket_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pr_machinery_assign_ticket_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.ticket_no IS NULL OR btrim(NEW.ticket_no) = '' THEN
    NEW.ticket_no := 'MT-' || to_char(COALESCE(NEW.reported_at, now()) AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD-HH24MISS')
      || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 4));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pr_machinery_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pr_machinery_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;


--
-- Name: prebill_accessible_owner_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prebill_accessible_owner_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT owner.id
  FROM public.us_users actor
  JOIN public.us_users owner ON (
    actor.role = 'superadmin'
    OR actor.id = owner.id
    OR (actor.role = 'sales-tr' AND owner.role = 'sales-tr')
  )
  WHERE actor.id = auth.uid();
$$;


--
-- Name: qc_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.qc_sessions (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    username text NOT NULL,
    filename text NOT NULL,
    start_time timestamp with time zone NOT NULL,
    end_time timestamp with time zone,
    total_items integer DEFAULT 0,
    pass_count integer DEFAULT 0,
    fail_count integer DEFAULT 0,
    kpi_score numeric(10,2),
    created_at timestamp with time zone DEFAULT now(),
    skipped_count integer DEFAULT 0 NOT NULL
);


--
-- Name: qc_finish_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qc_finish_session(p_session_id uuid) RETURNS public.qc_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session public.qc_sessions;
  v_work_order_name TEXT;
  v_total INTEGER;
  v_passed INTEGER;
  v_failed INTEGER;
  v_now TIMESTAMPTZ := now();
  v_duration_seconds NUMERIC;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid()
      AND role IN ('superadmin', 'admin', 'production', 'packing_staff')
  ) THEN
    RAISE EXCEPTION 'Not authorized to finish QC';
  END IF;

  SELECT * INTO v_session
  FROM public.qc_sessions
  WHERE id = p_session_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'QC session not found'; END IF;
  IF v_session.end_time IS NOT NULL THEN RETURN v_session; END IF;

  v_work_order_name := NULLIF(trim(regexp_replace(v_session.filename, '^WO-', '')), '');
  IF v_work_order_name IS NULL THEN RAISE EXCEPTION 'Invalid QC work order'; END IF;

  WITH active_units AS (
    SELECT oi.id AS order_item_id, unit_no AS unit_index
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id = o.id
    CROSS JOIN LATERAL generate_series(
      1,
      LEAST(GREATEST(COALESCE(floor(oi.quantity)::INTEGER, 1), 1), 9999)
    ) unit_no
    WHERE o.work_order_name = v_work_order_name
      AND COALESCE(o.status, '') <> 'ยกเลิก'
      AND NULLIF(trim(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
  ), current_results AS (
    SELECT u.order_item_id, u.unit_index, r.status
    FROM active_units u
    LEFT JOIN public.qc_records r
      ON r.session_id = p_session_id
     AND r.order_item_id = u.order_item_id
     AND r.unit_index = u.unit_index
  )
  SELECT count(*)::INTEGER,
         count(*) FILTER (WHERE status = 'pass')::INTEGER,
         count(*) FILTER (WHERE status = 'fail')::INTEGER
  INTO v_total, v_passed, v_failed
  FROM current_results;

  IF v_total <= 0 THEN RAISE EXCEPTION 'QC session has no active items'; END IF;
  IF v_passed <> v_total OR v_failed <> 0 THEN
    RAISE EXCEPTION 'QC results are incomplete: % of % item(s) passed', v_passed, v_total;
  END IF;

  v_duration_seconds := GREATEST(extract(epoch FROM (v_now - v_session.start_time)), 0);
  UPDATE public.qc_sessions
  SET end_time = v_now,
      total_items = v_total,
      pass_count = v_passed,
      fail_count = 0,
      skipped_count = 0,
      kpi_score = CASE WHEN v_total > 0 THEN v_duration_seconds / v_total ELSE 0 END
  WHERE id = p_session_id
  RETURNING * INTO v_session;

  RETURN v_session;
END;
$$;


--
-- Name: qc_records; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.qc_records (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    session_id uuid NOT NULL,
    item_uid text NOT NULL,
    qc_by text NOT NULL,
    status text NOT NULL,
    fail_reason text,
    is_rejected boolean DEFAULT false,
    retry_count integer DEFAULT 1,
    product_code text,
    product_name text,
    bill_no text,
    ink_color text,
    font text,
    floor text,
    cartoon_name text,
    line1 text,
    line2 text,
    line3 text,
    qty integer DEFAULT 1,
    remark text,
    created_at timestamp with time zone DEFAULT now(),
    reject_duration integer,
    workflow_status text DEFAULT 'pending'::text NOT NULL,
    attempt_started_at timestamp with time zone,
    resolved_at timestamp with time zone,
    last_result_at timestamp with time zone DEFAULT now(),
    order_id uuid,
    order_item_id uuid,
    unit_index integer,
    result_source text DEFAULT 'legacy'::text NOT NULL,
    CONSTRAINT qc_records_result_source_check CHECK ((result_source = ANY (ARRAY['manual'::text, 'recheck'::text, 'skip'::text, 'legacy'::text]))),
    CONSTRAINT qc_records_status_check CHECK ((status = ANY (ARRAY['pass'::text, 'fail'::text, 'pending'::text, 'skipped'::text]))),
    CONSTRAINT qc_records_unit_index_check CHECK (((unit_index IS NULL) OR (unit_index >= 1))),
    CONSTRAINT qc_records_workflow_status_check CHECK ((workflow_status = ANY (ARRAY['pending'::text, 'passed'::text, 'waiting_recheck'::text, 'escalated'::text, 'closed'::text])))
);


--
-- Name: COLUMN qc_records.reject_duration; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.qc_records.reject_duration IS 'Duration in seconds item was in Reject queue before this update (for KPI/CSV)';


--
-- Name: qc_resolve_escalation(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qc_resolve_escalation(p_record_id uuid, p_decision text, p_reason text, p_decided_by text) RETURNS public.qc_records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_record public.qc_records; v_now TIMESTAMPTZ := now();
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND role IN ('superadmin', 'admin')) THEN
    RAISE EXCEPTION 'Only admin can resolve escalated QC items';
  END IF;
  IF p_decision NOT IN ('special_recheck', 'produce_new', 'scrap', 'return_source') THEN
    RAISE EXCEPTION 'Invalid escalation decision';
  END IF;
  IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Decision reason is required'; END IF;
  SELECT * INTO v_record FROM public.qc_records WHERE id = p_record_id FOR UPDATE;
  IF NOT FOUND OR v_record.workflow_status <> 'escalated' THEN RAISE EXCEPTION 'Item is not escalated'; END IF;

  INSERT INTO public.qc_escalation_decisions(qc_record_id, decision, reason, decided_by)
  VALUES (p_record_id, p_decision, trim(p_reason), p_decided_by);

  UPDATE public.qc_records SET
    workflow_status = CASE WHEN p_decision = 'special_recheck' THEN 'waiting_recheck' ELSE 'closed' END,
    is_rejected = (p_decision = 'special_recheck'),
    attempt_started_at = CASE WHEN p_decision = 'special_recheck' THEN v_now ELSE NULL END,
    resolved_at = CASE WHEN p_decision = 'special_recheck' THEN NULL ELSE v_now END
  WHERE id = p_record_id RETURNING * INTO v_record;
  RETURN v_record;
END;
$$;


--
-- Name: qc_submit_recheck(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qc_submit_recheck(p_record_id uuid, p_result text, p_fail_reason text, p_qc_by text) RETURNS public.qc_records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_record public.qc_records;
  v_now TIMESTAMPTZ := now();
  v_attempt INTEGER;
  v_duration INTEGER;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND role IN ('production', 'packing_staff')) THEN
    RAISE EXCEPTION 'Not authorized to perform QC';
  END IF;
  IF p_result NOT IN ('pass', 'fail') THEN RAISE EXCEPTION 'Invalid QC result'; END IF;
  IF p_result = 'fail' AND NULLIF(trim(COALESCE(p_fail_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Fail reason is required';
  END IF;

  SELECT * INTO v_record FROM public.qc_records WHERE id = p_record_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'QC record not found'; END IF;
  IF NOT v_record.is_rejected OR v_record.workflow_status NOT IN ('waiting_recheck') THEN
    RAISE EXCEPTION 'This item is no longer waiting for recheck';
  END IF;

  v_attempt := COALESCE(v_record.retry_count, 1) + 1;
  v_duration := GREATEST(floor(extract(epoch FROM (v_now - COALESCE(v_record.attempt_started_at, v_record.created_at))))::INTEGER, 0);

  INSERT INTO public.qc_record_attempts (
    qc_record_id, session_id, item_uid, attempt_no, attempt_type, result,
    fail_reason, qc_by, started_at, completed_at, duration_seconds
  ) VALUES (
    v_record.id, v_record.session_id, v_record.item_uid, v_attempt,
    CASE WHEN v_attempt > 3 THEN 'special_recheck' ELSE 'recheck' END,
    p_result, CASE WHEN p_result = 'fail' THEN p_fail_reason ELSE NULL END,
    p_qc_by, COALESCE(v_record.attempt_started_at, v_record.created_at), v_now, v_duration
  );

  UPDATE public.qc_records SET
    status = p_result,
    fail_reason = CASE WHEN p_result = 'fail' THEN p_fail_reason ELSE NULL END,
    is_rejected = (p_result = 'fail'),
    retry_count = v_attempt,
    workflow_status = CASE
      WHEN p_result = 'pass' THEN 'passed'
      WHEN v_attempt >= 3 THEN 'escalated'
      ELSE 'waiting_recheck'
    END,
    qc_by = p_qc_by,
    last_result_at = v_now,
    reject_duration = v_duration,
    resolved_at = CASE WHEN p_result = 'pass' THEN v_now ELSE NULL END,
    attempt_started_at = CASE WHEN p_result = 'fail' THEN v_now ELSE NULL END
  WHERE id = p_record_id RETURNING * INTO v_record;
  RETURN v_record;
END;
$$;


--
-- Name: queue_deleted_time_clock_photo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_deleted_time_clock_photo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.photo_url IS NOT NULL AND btrim(OLD.photo_url) <> '' THEN
    INSERT INTO public.hr_time_clock_photo_cleanup_queue (path, reason, queued_at)
    VALUES (OLD.photo_url, 'time_entry_deleted', NOW())
    ON CONFLICT (path) DO UPDATE
      SET reason = EXCLUDED.reason,
          queued_at = EXCLUDED.queued_at;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: reconcile_work_order_after_cancellation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_work_order_after_cancellation(p_work_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_wo public.or_work_orders%ROWTYPE;
  v_active_orders INTEGER := 0;
  v_active_items INTEGER := 0;
  v_pending_stock INTEGER := 0;
  v_awaiting_shelf INTEGER := 0;
  v_cancelled_rows INTEGER := 0;
  v_state TEXT := NULL;
  v_status TEXT;
BEGIN
  IF p_work_order_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_work_order_id');
  END IF;

  SELECT * INTO v_wo
  FROM public.or_work_orders
  WHERE id = p_work_order_id
  FOR UPDATE;

  IF v_wo.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'work_order_not_found');
  END IF;

  SELECT COUNT(*)::INTEGER
  INTO v_active_items
  FROM public.or_order_items oi
  JOIN public.or_orders o ON o.id = oi.order_id
  WHERE (o.work_order_id = v_wo.id OR (o.work_order_id IS NULL AND BTRIM(COALESCE(o.work_order_name, '')) = BTRIM(v_wo.work_order_name)))
    AND COALESCE(o.status, '') <> 'ยกเลิก'
    AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL;

  SELECT COUNT(*)::INTEGER
  INTO v_active_orders
  FROM public.or_orders o
  WHERE (o.work_order_id = v_wo.id OR (o.work_order_id IS NULL AND BTRIM(COALESCE(o.work_order_name, '')) = BTRIM(v_wo.work_order_name)))
    AND COALESCE(o.status, '') NOT IN ('ยกเลิก', 'จัดส่งแล้ว')
    AND EXISTS (
      SELECT 1 FROM public.or_order_items oi
      WHERE oi.order_id = o.id
        AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
    );

  SELECT
    COUNT(*) FILTER (WHERE w.status = 'cancelled' AND w.stock_action IS NULL)::INTEGER,
    COUNT(*) FILTER (WHERE w.status = 'cancelled' AND w.stock_action = 'recalled')::INTEGER,
    COUNT(*)::INTEGER
  INTO v_pending_stock, v_awaiting_shelf, v_cancelled_rows
  FROM public.wms_orders w
  WHERE (w.work_order_id = v_wo.id OR (w.work_order_id IS NULL AND BTRIM(COALESCE(w.order_id, '')) = BTRIM(v_wo.work_order_name)))
    AND (w.status = 'cancelled' OR w.stock_action IN ('recalled', 'waste'));

  IF v_pending_stock > 0 THEN
    v_state := 'pending_stock';
  ELSIF v_awaiting_shelf > 0 THEN
    v_state := 'awaiting_shelf';
  ELSIF v_cancelled_rows > 0 OR v_active_items = 0 THEN
    v_state := 'closed';
  END IF;

  IF v_active_orders > 0 THEN
    v_status := CASE
      WHEN v_wo.status IN ('รอจัดการสต๊อก', 'รอคืนเข้าชั้น', 'จัดส่งแล้ว', 'ยกเลิก') THEN 'กำลังผลิต'
      ELSE v_wo.status
    END;
  ELSIF v_pending_stock > 0 THEN
    v_status := 'รอจัดการสต๊อก';
  ELSIF v_awaiting_shelf > 0 THEN
    v_status := 'รอคืนเข้าชั้น';
  ELSIF v_active_items > 0 THEN
    -- There are real items, but every remaining bill has already shipped.
    v_status := 'จัดส่งแล้ว';
  ELSE
    v_status := 'ยกเลิก';
  END IF;

  UPDATE public.or_work_orders
  SET order_count = v_active_orders,
      status = v_status,
      cancellation_state = v_state,
      plan_wo_modified = TRUE,
      updated_at = NOW()
  WHERE id = v_wo.id;

  -- A zero-active-item job must no longer look actionable in production/QC/PACK.
  -- Keep tracks intact for audit and let Plan render the row as cancelled/skipped.
  IF v_active_items = 0 THEN
    UPDATE public.plan_jobs
    SET is_production_voided = TRUE
    WHERE work_order_id = v_wo.id OR (work_order_id IS NULL AND name = v_wo.work_order_name);
  END IF;

  -- Cancellation notifications are lifecycle records. Once the stock decision
  -- is complete they leave the generic queue; physical shelf return remains
  -- visible through cancellation history and the WMS review queue.
  IF v_pending_stock = 0 THEN
    UPDATE public.wms_notifications
    SET status = 'fixed', is_read = TRUE
    WHERE type = 'ยกเลิกบิล'
      AND BTRIM(COALESCE(order_id, '')) = BTRIM(v_wo.work_order_name);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'work_order_id', v_wo.id,
    'work_order_name', v_wo.work_order_name,
    'status', v_status,
    'cancellation_state', v_state,
    'active_orders', v_active_orders,
    'active_items', v_active_items,
    'pending_stock', v_pending_stock,
    'awaiting_shelf', v_awaiting_shelf
  );
END;
$$;


--
-- Name: reject_borrow_requisition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_borrow_requisition(p_borrow_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role   TEXT;
  v_status TEXT;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธรายการยืม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_status;
  END IF;

  UPDATE public.wms_borrow_requisitions
  SET status = 'rejected', approved_by = auth.uid(), approved_at = NOW()
  WHERE id = p_borrow_id;
END;
$$;


--
-- Name: reject_return_requisition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_return_requisition(p_return_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_status TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = p_user_id;
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin','manager') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธรายการคืน (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status FROM wms_return_requisitions WHERE id = p_return_id;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'ไม่พบรายการคืน';
  END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_status;
  END IF;

  UPDATE wms_return_requisitions
  SET status = 'rejected',
      approved_by = p_user_id,
      approved_at = NOW()
  WHERE id = p_return_id;
END;
$$;


--
-- Name: reopen_failed_queue_from_manual_slip(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_failed_queue_from_manual_slip() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.status = 'pending')
     OR (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'rejected') THEN
    PERFORM public.reopen_order_failed_queue(NEW.order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reopen_failed_queue_from_refund(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_failed_queue_from_refund() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.reason ILIKE '%โอนเกิน%'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    PERFORM public.reopen_order_failed_queue(NEW.order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reopen_failed_queue_from_slip_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_failed_queue_from_slip_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'failed' THEN
    PERFORM public.reopen_order_failed_queue(NEW.order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reopen_order_failed_queue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_order_failed_queue(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.or_orders
  SET failed_queue_archived_at = NULL,
      failed_queue_archived_by = NULL,
      failed_queue_archived_by_name = NULL,
      failed_queue_archive_reason = NULL
  WHERE id = p_order_id
    AND failed_queue_archived_at IS NOT NULL;
END;
$$;


--
-- Name: reopen_order_failed_queue_on_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_order_failed_queue_on_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status IN ('ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ')
     AND OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.failed_queue_archived_at := NULL;
    NEW.failed_queue_archived_by := NULL;
    NEW.failed_queue_archived_by_name := NULL;
    NEW.failed_queue_archive_reason := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reorder_hr_companies(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_hr_companies(p_company_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  requested_count INTEGER := COALESCE(array_length(p_company_ids, 1), 0);
  existing_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO existing_count
  FROM public.hr_companies
  WHERE id = ANY(COALESCE(p_company_ids, ARRAY[]::UUID[]));

  IF requested_count = 0 OR existing_count <> requested_count THEN
    RAISE EXCEPTION 'Invalid company order';
  END IF;

  UPDATE public.hr_companies AS company
  SET sort_order = ordered.position,
      updated_at = NOW()
  FROM unnest(p_company_ids) WITH ORDINALITY AS ordered(id, position)
  WHERE company.id = ordered.id;
END;
$$;


--
-- Name: return_borrow_requisition(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_borrow_requisition(p_borrow_id uuid, p_items jsonb, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role        TEXT;
  v_status      TEXT;
  v_item        JSONB;
  v_product_id  UUID;
  v_return_qty  NUMERIC;
  v_borrow_item RECORD;
  v_all_done    BOOLEAN;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์รับคืนรายการยืม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status NOT IN ('approved', 'partial_returned', 'overdue') THEN
    RAISE EXCEPTION 'ไม่สามารถคืนได้ (status: %)', v_status;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_return_qty := (v_item->>'return_qty')::NUMERIC;
    IF v_return_qty IS NULL OR v_return_qty <= 0 THEN CONTINUE; END IF;

    SELECT * INTO v_borrow_item
    FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id AND product_id = v_product_id
    FOR UPDATE;

    IF v_borrow_item IS NULL THEN CONTINUE; END IF;
    IF v_borrow_item.returned_qty + v_borrow_item.written_off_qty + v_return_qty > v_borrow_item.qty THEN
      RAISE EXCEPTION 'จำนวนคืนเกินจำนวนที่ยืม (สินค้า: %)', v_product_id;
    END IF;

    UPDATE public.wms_borrow_requisition_items
    SET returned_qty = returned_qty + v_return_qty
    WHERE id = v_borrow_item.id;

    UPDATE public.inv_stock_balances
    SET reserved = GREATEST(COALESCE(reserved, 0) - v_return_qty, 0)
    WHERE product_id = v_product_id;
  END LOOP;

  SELECT NOT EXISTS (
    SELECT 1 FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id
      AND (returned_qty + written_off_qty) < qty
  ) INTO v_all_done;

  IF v_all_done THEN
    UPDATE public.wms_borrow_requisitions
    SET status = 'returned', returned_at = NOW()
    WHERE id = p_borrow_id;
  ELSE
    UPDATE public.wms_borrow_requisitions
    SET status = 'partial_returned'
    WHERE id = p_borrow_id AND status <> 'partial_returned';
  END IF;
END;
$$;


--
-- Name: reuse_manual_payment_after_order_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reuse_manual_payment_after_order_edit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_paid numeric; v_owner text;
BEGIN
 IF OLD.status NOT IN ('ลงข้อมูลผิด','รอลงข้อมูล','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ')
  OR NEW.status<>'ลงข้อมูลเสร็จสิ้น' OR NEW.work_order_id IS NOT NULL
  OR NEW.channel_code IS DISTINCT FROM OLD.channel_code
  OR NEW.payment_method IS DISTINCT FROM OLD.payment_method THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM public.ac_manual_slip_checks WHERE order_id=NEW.id AND status='pending') THEN RETURN NEW; END IF;
 SELECT sum(transfer_amount) INTO v_paid FROM public.ac_manual_slip_checks
 WHERE order_id=NEW.id AND status='approved' AND duplicate_of IS NULL
 AND approved_order_total=public.or_tax_receivable(NEW.total_amount,NEW.billing_details);
 v_paid:=coalesce(v_paid,0)-coalesce((SELECT sum(amount) FROM public.ac_refunds
  WHERE order_id=NEW.id AND status IN ('pending','approved')),0);
 IF coalesce(v_paid,0)<public.or_tax_receivable(NEW.total_amount,NEW.billing_details) OR public.or_tax_receivable(NEW.total_amount,NEW.billing_details)<=0 THEN RETURN NEW; END IF;
 SELECT role INTO v_owner FROM public.us_users
 WHERE username=NEW.admin_user OR email=NEW.admin_user
 ORDER BY (username=NEW.admin_user) DESC NULLS LAST LIMIT 1;
 NEW.status:=CASE
  WHEN upper(trim(NEW.channel_code))='WY' THEN 'ตรวจสอบแล้ว'
  WHEN v_owner='sales-tr' AND ((NEW.channel_code='PUMP' AND NEW.requires_confirm_design=FALSE)
   OR (NEW.channel_code IS DISTINCT FROM 'PUMP' AND coalesce(NEW.requires_confirm_design,FALSE)=FALSE)) THEN 'รอตรวจคำสั่งซื้อ'
  WHEN NEW.channel_code='PUMP' AND NEW.requires_confirm_design=FALSE THEN 'ไม่ต้องออกแบบ'
  ELSE 'ตรวจสอบแล้ว' END;
 RETURN NEW;
END $$;


--
-- Name: rpc_approve_amendment(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_amendment(p_amendment_id uuid, p_approver_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role      TEXT;
  v_uid       UUID := auth.uid();
  v_amendment RECORD;
  v_result    JSONB;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติ — ต้องเป็น superadmin หรือ admin เท่านั้น (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT * INTO v_amendment FROM or_order_amendments WHERE id = p_amendment_id;
  IF v_amendment.id IS NULL THEN RAISE EXCEPTION 'ไม่พบใบขอยกเลิก'; END IF;
  IF v_amendment.status <> 'pending' THEN
    RAISE EXCEPTION 'ใบขอยกเลิกนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_amendment.status;
  END IF;

  UPDATE or_order_amendments
  SET approved_by = v_uid, approved_at = NOW(), status = 'approved'
  WHERE id = p_amendment_id;

  v_result := rpc_execute_bill_cancellation(p_amendment_id);

  RETURN v_result;
END;
$$;


--
-- Name: rpc_approve_claim_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_claim_request(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role           TEXT;
  v_uid            UUID := auth.uid();
  v_req            RECORD;
  v_ref            RECORD;
  v_claim_bill     TEXT;
  v_prefix         TEXT;
  v_i              INT := 1;
  v_order          JSONB;
  v_items          JSONB;
  v_new_order_id   UUID;
  v_item           JSONB;
  v_idx            INT := 0;
  v_item_uid       TEXT;
  v_pay_date       DATE;
  v_pay_time       TIME;
  v_sched          TIMESTAMPTZ;
BEGIN
  SELECT u.role INTO v_role FROM us_users u WHERE u.id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติเคลม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT * INTO v_req FROM or_claim_requests WHERE id = p_request_id FOR UPDATE;
  IF v_req.id IS NULL THEN RAISE EXCEPTION 'ไม่พบคำขอเคลม'; END IF;
  IF v_req.status <> 'pending' THEN
    RAISE EXCEPTION 'คำขอนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_req.status;
  END IF;

  SELECT * INTO v_ref FROM or_orders WHERE id = v_req.ref_order_id;
  IF v_ref.id IS NULL THEN RAISE EXCEPTION 'ไม่พบบิลอ้างอิง'; END IF;
  IF v_ref.status IS DISTINCT FROM 'จัดส่งแล้ว' THEN
    RAISE EXCEPTION 'บิลอ้างอิงต้องเป็นสถานะจัดส่งแล้ว (ปัจจุบัน: %)', v_ref.status;
  END IF;

  IF length(trim(both FROM COALESCE(v_ref.bill_no, ''))) = 0 THEN
    RAISE EXCEPTION 'บิลอ้างอิงไม่มีเลขบิล';
  END IF;

  v_prefix := 'REQ' || trim(both FROM v_ref.bill_no);
  v_claim_bill := v_prefix;
  WHILE EXISTS (SELECT 1 FROM or_orders o WHERE o.bill_no = v_claim_bill) LOOP
    v_i := v_i + 1;
    IF v_i > 10000 THEN
      RAISE EXCEPTION 'ไม่พบเลขบิลเคลมว่างสำหรับบิลอ้างอิงนี้';
    END IF;
    v_claim_bill := v_prefix || '-' || v_i::TEXT;
  END LOOP;

  v_order := v_req.proposed_snapshot->'order';
  IF v_order IS NULL OR jsonb_typeof(v_order) <> 'object' THEN
    RAISE EXCEPTION 'ข้อมูลคำขอไม่สมบูรณ์ (order)';
  END IF;

  v_items := v_req.proposed_snapshot->'items';
  IF v_items IS NULL OR jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'ต้องมีรายการสินค้าอย่างน้อย 1 รายการ';
  END IF;

  IF v_order->>'payment_date' IS NOT NULL AND length(trim(v_order->>'payment_date')) > 0 THEN
    v_pay_date := (v_order->>'payment_date')::DATE;
  ELSE
    v_pay_date := v_ref.payment_date;
  END IF;

  IF v_order->>'payment_time' IS NOT NULL AND length(trim(v_order->>'payment_time')) > 0 THEN
    v_pay_time := (v_order->>'payment_time')::TIME;
  ELSE
    v_pay_time := v_ref.payment_time;
  END IF;

  IF v_order->>'scheduled_pickup_at' IS NOT NULL AND length(trim(v_order->>'scheduled_pickup_at')) > 0 THEN
    v_sched := (v_order->>'scheduled_pickup_at')::TIMESTAMPTZ;
  ELSE
    v_sched := v_ref.scheduled_pickup_at;
  END IF;

  INSERT INTO or_orders (
    channel_code,
    customer_name,
    customer_address,
    channel_order_no,
    recipient_name,
    scheduled_pickup_at,
    price,
    shipping_cost,
    discount,
    total_amount,
    payment_method,
    promotion,
    payment_date,
    payment_time,
    status,
    admin_user,
    entry_date,
    bill_no,
    claim_type,
    claim_details,
    billing_details,
    packing_meta,
    work_order_name,
    work_order_id,
    shipped_by,
    shipped_time,
    tracking_number,
    requires_confirm_design
  ) VALUES (
    COALESCE(NULLIF(trim(both FROM v_order->>'channel_code'), ''), v_ref.channel_code),
    COALESCE(v_order->>'customer_name', v_ref.customer_name),
    COALESCE(v_order->>'customer_address', v_ref.customer_address),
    CASE
      WHEN v_order ? 'channel_order_no' THEN NULLIF(trim(both FROM v_order->>'channel_order_no'), '')::TEXT
      ELSE v_ref.channel_order_no
    END,
    CASE
      WHEN v_order ? 'recipient_name' THEN NULLIF(trim(both FROM v_order->>'recipient_name'), '')::TEXT
      ELSE v_ref.recipient_name
    END,
    v_sched,
    COALESCE((v_order->>'price')::NUMERIC, v_ref.price, 0),
    COALESCE((v_order->>'shipping_cost')::NUMERIC, v_ref.shipping_cost, 0),
    COALESCE((v_order->>'discount')::NUMERIC, v_ref.discount, 0),
    COALESCE((v_order->>'total_amount')::NUMERIC, v_ref.total_amount, 0),
    CASE
      WHEN v_order ? 'payment_method' THEN NULLIF(v_order->>'payment_method', '')::TEXT
      ELSE v_ref.payment_method
    END,
    CASE
      WHEN v_order ? 'promotion' THEN NULLIF(v_order->>'promotion', '')::TEXT
      ELSE v_ref.promotion
    END,
    v_pay_date,
    v_pay_time,
    COALESCE(NULLIF(trim(both FROM v_order->>'status'), ''), 'รอลงข้อมูล'),
    COALESCE(NULLIF(trim(both FROM v_order->>'admin_user'), ''), v_ref.admin_user),
    COALESCE(
      CASE WHEN v_order->>'entry_date' IS NOT NULL AND length(trim(v_order->>'entry_date')) > 0
        THEN (v_order->>'entry_date')::DATE END,
      CURRENT_DATE
    ),
    v_claim_bill,
    trim(both FROM v_req.claim_type),
    CASE WHEN v_order ? 'claim_details' THEN NULLIF(v_order->>'claim_details', '')::TEXT END,
    COALESCE(v_order->'billing_details', v_ref.billing_details),
    CASE WHEN v_order ? 'packing_meta' THEN v_order->'packing_meta' END,
    CASE WHEN v_order ? 'work_order_name' THEN NULLIF(trim(both FROM v_order->>'work_order_name'), '')::TEXT END,
    NULL,
    CASE WHEN v_order ? 'shipped_by' THEN NULLIF(trim(both FROM v_order->>'shipped_by'), '')::TEXT END,
    CASE
      WHEN v_order ? 'shipped_time' AND v_order->>'shipped_time' IS NOT NULL AND length(trim(v_order->>'shipped_time')) > 0
        THEN (v_order->>'shipped_time')::TIMESTAMPTZ
      ELSE v_ref.shipped_time
    END,
    CASE WHEN v_order ? 'tracking_number' THEN NULLIF(trim(both FROM v_order->>'tracking_number'), '')::TEXT
      ELSE v_ref.tracking_number
    END,
    COALESCE((v_order->>'requires_confirm_design')::BOOLEAN, v_ref.requires_confirm_design, TRUE)
  )
  RETURNING id INTO v_new_order_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) AS t(value)
  LOOP
    v_idx := v_idx + 1;
    v_item_uid := v_claim_bill || '-' || v_idx::TEXT;

    INSERT INTO or_order_items (
      order_id,
      item_uid,
      product_id,
      product_name,
      quantity,
      unit_price,
      ink_color,
      product_type,
      cartoon_pattern,
      line_pattern,
      font,
      line_1,
      line_2,
      line_3,
      no_name_line,
      is_free,
      notes,
      file_attachment
    ) VALUES (
      v_new_order_id,
      v_item_uid,
      NULLIF(trim(both FROM v_item->>'product_id'), '')::UUID,
      COALESCE(trim(both FROM v_item->>'product_name'), ''),
      COALESCE((v_item->>'quantity')::INT, 1),
      COALESCE((v_item->>'unit_price')::NUMERIC, 0),
      NULLIF(trim(both FROM v_item->>'ink_color'), '')::TEXT,
      COALESCE(NULLIF(trim(both FROM v_item->>'product_type'), '')::TEXT, 'ชั้น1'),
      NULLIF(trim(both FROM v_item->>'cartoon_pattern'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_pattern'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'font'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_1'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_2'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_3'), '')::TEXT,
      COALESCE((v_item->>'no_name_line')::BOOLEAN, FALSE),
      COALESCE((v_item->>'is_free')::BOOLEAN, FALSE),
      NULLIF(trim(both FROM v_item->>'notes'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'file_attachment'), '')::TEXT
    );
  END LOOP;

  UPDATE or_claim_requests
  SET status = 'approved',
      reviewed_by = v_uid,
      reviewed_at = NOW(),
      created_claim_order_id = v_new_order_id
  WHERE id = p_request_id;

  RETURN jsonb_build_object(
    'order_id', v_new_order_id,
    'bill_no', v_claim_bill
  );
END;
$$;


--
-- Name: rpc_approve_inventory_adjustment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_inventory_adjustment(p_adjustment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_adjustment public.inv_adjustments%ROWTYPE;
  v_item record;
  v_config record;
  v_item_count integer;
  v_target_on_hand numeric;
  v_target_safety numeric;
  v_target_total numeric;
  v_current_total numeric;
  v_total_delta numeric;
  v_derived_target numeric;
  v_result jsonb;
  v_generated_item_id uuid;
  v_stock_items jsonb := '[]'::jsonb;
  v_safety_releases jsonb := '[]'::jsonb;
  v_safety_increases jsonb := '[]'::jsonb;
  v_changed_count integer := 0;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT u.role INTO v_role FROM public.us_users u
    WHERE u.id = auth.uid() AND u.is_active IS TRUE;
    IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'account') THEN
      RAISE EXCEPTION 'Not authorized to approve an inventory adjustment';
    END IF;
  END IF;

  -- Transaction-local capability consumed by the low-level stock helpers.
  -- It is set only after this RPC has authenticated an allowed approver.
  PERFORM set_config('app.inventory_adjustment_approval', 'on', true);

  SELECT * INTO v_adjustment FROM public.inv_adjustments
  WHERE id = p_adjustment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inventory adjustment not found'; END IF;
  IF v_adjustment.status <> 'pending' THEN
    RAISE EXCEPTION 'Only a pending inventory adjustment can be approved';
  END IF;
  SELECT count(*) INTO v_item_count FROM public.inv_adjustment_items
  WHERE adjustment_id = p_adjustment_id AND is_system_generated IS false;
  IF v_item_count = 0 THEN RAISE EXCEPTION 'Cannot approve an inventory adjustment with no items'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.inv_adjustment_items
    WHERE adjustment_id = p_adjustment_id
    GROUP BY product_id HAVING count(*) > 1
  ) THEN RAISE EXCEPTION 'Inventory adjustment contains duplicate products'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.inv_stock_movements
    WHERE ref_type = 'inv_adjustments' AND ref_id = p_adjustment_id
  ) THEN RAISE EXCEPTION 'This adjustment already has stock movements'; END IF;

  IF v_adjustment.adjustment_type = 'stocktake_reconcile' THEN
    IF EXISTS (
      SELECT 1
      FROM public.inv_adjustment_items i
      JOIN public.roll_material_configs c ON c.fg_product_id = i.product_id
      WHERE i.adjustment_id = p_adjustment_id AND i.is_system_generated IS false
    ) THEN
      RAISE EXCEPTION 'Derived roll FG cannot be entered in a stocktake; enter its mapped RM instead';
    END IF;

    FOR v_item IN
      SELECT i.* FROM public.inv_adjustment_items i
      WHERE i.adjustment_id = p_adjustment_id AND i.is_system_generated IS false
      ORDER BY i.product_id
    LOOP
      v_target_on_hand := COALESCE(v_item.after_on_hand, 0);
      v_target_safety := COALESCE(v_item.after_safety_stock, v_item.new_safety_stock, 0);
      SELECT COALESCE(b.on_hand, 0) + COALESCE(b.safety_stock, 0)
      INTO v_current_total FROM public.inv_stock_balances b
      WHERE b.product_id = v_item.product_id;
      v_current_total := COALESCE(v_current_total, 0);

      v_result := public.fn_reconcile_stocktake_product(
        v_item.product_id, v_target_on_hand, v_target_safety,
        p_adjustment_id, 'Stocktake reconciliation ' || v_adjustment.adjust_no
      );
      v_total_delta := (v_target_on_hand + v_target_safety) - v_current_total;
      UPDATE public.inv_adjustment_items
      SET approved_qty_delta = v_total_delta,
          approved_unit_cost = COALESCE((v_result->>'unit_cost')::numeric, 0),
          approved_total_cost_impact = v_total_delta * COALESCE((v_result->>'unit_cost')::numeric, 0)
      WHERE id = v_item.id;
      IF v_total_delta <> 0 THEN v_changed_count := v_changed_count + 1; END IF;
    END LOOP;

    -- RM is the source of truth. Recompute every affected FG from all mapped RM
    -- balances after the direct stocktake targets have been applied.
    FOR v_config IN
      SELECT DISTINCT c.id, c.fg_product_id, c.sheets_per_roll
      FROM public.roll_material_configs c
      JOIN public.roll_material_config_rms m ON m.config_id = c.id
      JOIN public.inv_adjustment_items i ON i.product_id = m.rm_product_id
      WHERE i.adjustment_id = p_adjustment_id
        AND i.is_system_generated IS false
      ORDER BY c.id
    LOOP
      IF COALESCE(v_config.sheets_per_roll, 0) <= 0 THEN
        RAISE EXCEPTION 'Roll formula has an invalid sheets-per-roll value for FG %', v_config.fg_product_id;
      END IF;

      SELECT ROUND(COALESCE(SUM(COALESCE(b.on_hand, 0)), 0) * v_config.sheets_per_roll, 2)
      INTO v_derived_target
      FROM public.roll_material_config_rms m
      LEFT JOIN public.inv_stock_balances b ON b.product_id = m.rm_product_id
      WHERE m.config_id = v_config.id;

      INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
      VALUES (v_config.fg_product_id, 0, 0, 0)
      ON CONFLICT (product_id) DO NOTHING;
      SELECT COALESCE(on_hand, 0), COALESCE(safety_stock, 0)
      INTO v_current_total, v_target_safety
      FROM public.inv_stock_balances
      WHERE product_id = v_config.fg_product_id
      FOR UPDATE;

      INSERT INTO public.inv_adjustment_items (
        adjustment_id, product_id, qty_delta, new_safety_stock,
        before_on_hand, after_on_hand, before_safety_stock, after_safety_stock,
        before_total_qty, after_total_qty, is_system_generated
      ) VALUES (
        p_adjustment_id, v_config.fg_product_id, v_derived_target - v_current_total,
        v_target_safety, v_current_total, v_derived_target,
        v_target_safety, v_target_safety,
        v_current_total + v_target_safety, v_derived_target + v_target_safety, true
      )
      RETURNING id INTO v_generated_item_id;

      v_result := public.fn_reconcile_stocktake_product(
        v_config.fg_product_id, v_derived_target, v_target_safety,
        p_adjustment_id, 'Derived FG from counted RM ' || v_adjustment.adjust_no
      );
      v_total_delta := v_derived_target - v_current_total;
      UPDATE public.inv_adjustment_items
      SET approved_qty_delta = v_total_delta,
          approved_unit_cost = COALESCE((v_result->>'unit_cost')::numeric, 0),
          approved_total_cost_impact = v_total_delta * COALESCE((v_result->>'unit_cost')::numeric, 0)
      WHERE id = v_generated_item_id;
      IF v_total_delta <> 0 THEN v_changed_count := v_changed_count + 1; END IF;
    END LOOP;
  ELSE
    -- Preserve the existing ordinary-adjustment and safety-reclassification flow.
    INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    SELECT DISTINCT i.product_id, 0, 0, 0
    FROM public.inv_adjustment_items i WHERE i.adjustment_id = p_adjustment_id
    ON CONFLICT (product_id) DO NOTHING;

    FOR v_item IN
      SELECT i.*, COALESCE(b.on_hand, 0) AS current_on_hand,
             COALESCE(b.safety_stock, 0) AS current_safety
      FROM public.inv_adjustment_items i
      JOIN public.inv_stock_balances b ON b.product_id = i.product_id
      WHERE i.adjustment_id = p_adjustment_id
      ORDER BY i.created_at, i.id FOR UPDATE OF b
    LOOP
      v_target_on_hand := COALESCE(v_item.after_on_hand, v_item.current_on_hand + COALESCE(v_item.qty_delta, 0));
      v_target_safety := COALESCE(v_item.after_safety_stock, v_item.new_safety_stock, v_item.current_safety);
      v_target_total := COALESCE(v_item.after_total_qty, v_target_on_hand + v_target_safety);
      IF v_target_on_hand < 0 OR v_target_safety < 0 OR v_target_total < 0 THEN
        RAISE EXCEPTION 'Inventory adjustment has a negative target for product %', v_item.product_id;
      END IF;
      v_current_total := v_item.current_on_hand + v_item.current_safety;
      v_total_delta := v_target_total - v_current_total;
      UPDATE public.inv_adjustment_items SET approved_qty_delta = v_total_delta WHERE id = v_item.id;

      IF v_target_safety < v_item.current_safety THEN
        v_safety_releases := v_safety_releases || jsonb_build_array(jsonb_build_object(
          'product_id', v_item.product_id, 'safety_stock', v_target_safety));
      ELSIF v_target_safety > v_item.current_safety THEN
        v_safety_increases := v_safety_increases || jsonb_build_array(jsonb_build_object(
          'product_id', v_item.product_id, 'safety_stock', v_target_safety));
      END IF;
      IF v_total_delta <> 0 THEN
        v_stock_items := v_stock_items || jsonb_build_array(jsonb_build_object(
          'product_id', v_item.product_id, 'qty_delta', v_total_delta,
          'movement_type', 'adjust', 'ref_type', 'inv_adjustments',
          'ref_id', p_adjustment_id, 'note', 'Inventory adjustment ' || v_adjustment.adjust_no));
      END IF;
      IF v_total_delta <> 0 OR v_target_safety <> v_item.current_safety THEN
        v_changed_count := v_changed_count + 1;
      END IF;
    END LOOP;
    IF jsonb_array_length(v_safety_releases) > 0 THEN PERFORM public.bulk_update_safety_stock(v_safety_releases); END IF;
    IF jsonb_array_length(v_stock_items) > 0 THEN PERFORM public.bulk_adjust_stock(v_stock_items); END IF;
    IF jsonb_array_length(v_safety_increases) > 0 THEN PERFORM public.bulk_update_safety_stock(v_safety_increases); END IF;
  END IF;

  UPDATE public.inv_adjustments SET status = 'approved', approved_by = auth.uid(), approved_at = now()
  WHERE id = p_adjustment_id;
  SELECT count(*) INTO v_item_count FROM public.inv_adjustment_items WHERE adjustment_id = p_adjustment_id;
  RETURN jsonb_build_object(
    'success', true, 'adjustment_id', p_adjustment_id,
    'adjust_no', v_adjustment.adjust_no, 'status', 'approved',
    'item_count', v_item_count, 'changed_count', v_changed_count
  );
END;
$$;


--
-- Name: FUNCTION rpc_approve_inventory_adjustment(p_adjustment_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_approve_inventory_adjustment(p_adjustment_id uuid) IS 'Approves inventory adjustments. Allowed roles: superadmin, admin, manager and account; store is creator-only.';


--
-- Name: rpc_approve_pr(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_pr(p_pr_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid  UUID := auth.uid();
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติ PR (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  UPDATE inv_pr
  SET status = 'approved', approved_by = v_uid, approved_at = NOW()
  WHERE id = p_pr_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'PR ไม่อยู่ในสถานะรออนุมัติ'; END IF;
END;
$$;


--
-- Name: rpc_approve_production_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_production_order(p_order_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role TEXT;
  v_status TEXT;
  v_over RECORD;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid AND is_active IS TRUE;
  IF v_role IS NULL OR v_role NOT IN ('store', 'admin', 'superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติใบแปรรูป';
  END IF;

  SELECT status INTO v_status FROM pp_production_orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบใบแปรรูป'; END IF;
  IF v_status <> 'pending' THEN RAISE EXCEPTION 'ใบแปรรูปไม่ได้อยู่ในสถานะรออนุมัติ'; END IF;

  SELECT p.product_code, COALESCE(b.on_hand, 0) AS on_hand, oi.qty, r.max_stock
  INTO v_over
  FROM pp_production_order_items oi
  JOIN pp_recipes r ON r.product_id = oi.product_id
  JOIN pr_products p ON p.id = oi.product_id
  LEFT JOIN inv_stock_balances b ON b.product_id = oi.product_id
  WHERE oi.order_id = p_order_id AND r.max_stock IS NOT NULL
    AND COALESCE(b.on_hand, 0) + oi.qty > r.max_stock
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'สินค้า % คงเหลือ % + ผลิต % จะเกิน Max %',
      v_over.product_code, v_over.on_hand, v_over.qty, v_over.max_stock;
  END IF;

  UPDATE pp_production_orders SET
    status = 'approved', approved_by = v_uid, approved_at = now()
  WHERE id = p_order_id;
END;
$$;


--
-- Name: rpc_approve_revised_claim_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_revised_claim_request(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role TEXT;
  v_request public.or_claim_requests%ROWTYPE;
  v_order public.or_orders%ROWTYPE;
  v_order_snapshot JSONB;
  v_items JSONB;
  v_item JSONB;
  v_idx INTEGER := 0;
  v_item_uid TEXT;
  v_price NUMERIC;
  v_shipping NUMERIC;
  v_discount NUMERIC;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติเคลม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT * INTO v_request
  FROM public.or_claim_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL OR v_request.status <> 'pending' OR v_request.created_claim_order_id IS NULL THEN
    RAISE EXCEPTION 'ไม่พบคำขอแก้ไขบิลเคลมที่รออนุมัติ';
  END IF;

  SELECT * INTO v_order
  FROM public.or_orders
  WHERE id = v_request.created_claim_order_id
  FOR UPDATE;

  IF v_order.id IS NULL OR v_order.status <> 'รออนุมัติเคลม' THEN
    RAISE EXCEPTION 'บิลเคลมไม่ได้อยู่ในสถานะรออนุมัติ';
  END IF;

  v_order_snapshot := v_request.proposed_snapshot->'order';
  v_items := v_request.proposed_snapshot->'items';
  IF v_order_snapshot IS NULL
     OR jsonb_typeof(v_order_snapshot) <> 'object'
     OR v_items IS NULL
     OR jsonb_typeof(v_items) <> 'array'
     OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'ข้อมูลบิลเคลมที่เสนอไม่สมบูรณ์';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_items) AS row(value)
    WHERE btrim(COALESCE(value->>'product_name', '')) = ''
       OR COALESCE((value->>'quantity')::INTEGER, 0) < 1
       OR COALESCE((value->>'unit_price')::NUMERIC, 0) < 0
  ) THEN
    RAISE EXCEPTION 'สินค้า จำนวน หรือราคาไม่ถูกต้อง';
  END IF;

  SELECT COALESCE(SUM(
    CASE WHEN COALESCE((value->>'is_free')::BOOLEAN, false)
      THEN 0
      ELSE COALESCE((value->>'quantity')::NUMERIC, 0) * COALESCE((value->>'unit_price')::NUMERIC, 0)
    END
  ), 0)
  INTO v_price
  FROM jsonb_array_elements(v_items) AS row(value);
  v_shipping := GREATEST(COALESCE((v_order_snapshot->>'shipping_cost')::NUMERIC, 0), 0);
  v_discount := GREATEST(COALESCE((v_order_snapshot->>'discount')::NUMERIC, 0), 0);
  v_order_snapshot := v_order_snapshot || jsonb_build_object(
    'price', v_price,
    'shipping_cost', v_shipping,
    'discount', v_discount,
    'total_amount', v_price + v_shipping - v_discount
  );

  UPDATE public.or_orders
  SET price = v_price,
      shipping_cost = v_shipping,
      discount = v_discount,
      total_amount = v_price + v_shipping - v_discount,
      status = 'รอลงข้อมูล',
      claim_shipping_confirmed_at = NULL,
      updated_at = now()
  WHERE id = v_order.id;

  DELETE FROM public.or_order_items WHERE order_id = v_order.id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) AS t(value)
  LOOP
    v_idx := v_idx + 1;
    v_item_uid := v_order.bill_no || '-' || v_idx::TEXT;

    INSERT INTO public.or_order_items (
      order_id, item_uid, product_id, product_name, quantity, unit_price,
      ink_color, product_type, cartoon_pattern, line_pattern, font,
      line_1, line_2, line_3, no_name_line, is_free, notes,
      file_attachment, attachment_name
    ) VALUES (
      v_order.id,
      v_item_uid,
      NULLIF(btrim(COALESCE(v_item->>'product_id', '')), '')::UUID,
      COALESCE(btrim(v_item->>'product_name'), ''),
      GREATEST(COALESCE((v_item->>'quantity')::INTEGER, 1), 1),
      GREATEST(COALESCE((v_item->>'unit_price')::NUMERIC, 0), 0),
      NULLIF(btrim(COALESCE(v_item->>'ink_color', '')), ''),
      COALESCE(NULLIF(btrim(COALESCE(v_item->>'product_type', '')), ''), 'ชั้น1'),
      NULLIF(btrim(COALESCE(v_item->>'cartoon_pattern', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'line_pattern', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'font', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'line_1', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'line_2', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'line_3', '')), ''),
      COALESCE((v_item->>'no_name_line')::BOOLEAN, false),
      COALESCE((v_item->>'is_free')::BOOLEAN, false),
      NULLIF(btrim(COALESCE(v_item->>'notes', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'file_attachment', '')), ''),
      NULLIF(btrim(COALESCE(v_item->>'attachment_name', '')), '')
    );
  END LOOP;

  UPDATE public.or_claim_requests
  SET status = 'approved',
      reviewed_by = v_uid,
      reviewed_at = now(),
      rejected_reason = NULL,
      proposed_snapshot = jsonb_set(proposed_snapshot, '{order}', v_order_snapshot)
  WHERE id = v_request.id;

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'bill_no', v_order.bill_no,
    'reapproved', true
  );
END;
$$;


--
-- Name: FUNCTION rpc_approve_revised_claim_request(p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_approve_revised_claim_request(p_request_id uuid) IS 'Applies an approved revision atomically to the existing REQ bill and returns it to shipping/slip confirmation.';


--
-- Name: rpc_assign_packing_tags(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_assign_packing_tags(p_tags jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record;
  v_tag jsonb;
  v_result jsonb := '{}'::jsonb;
  v_count integer := 0;
BEGIN
  IF jsonb_typeof(p_tags) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'p_tags must be an array';
  END IF;
  IF jsonb_array_length(p_tags) > 500 THEN
    RAISE EXCEPTION 'At most 500 tags per request';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_tags) AS t(value)
    WHERE jsonb_typeof(value) IS DISTINCT FROM 'object'
      OR jsonb_typeof(value->'order_id') IS DISTINCT FROM 'string'
      OR jsonb_typeof(value->'tag') IS DISTINCT FROM 'number'
  ) THEN RAISE EXCEPTION 'Invalid packing tag'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(p_tags) AS t(order_id uuid, tag numeric)
    WHERE order_id IS NULL OR tag IS NULL OR tag < 1
      OR tag > 9007199254740991 OR tag <> trunc(tag)
  ) OR (
    SELECT count(DISTINCT order_id) FROM jsonb_to_recordset(p_tags) AS t(order_id uuid, tag numeric)
  ) <> jsonb_array_length(p_tags) THEN
    RAISE EXCEPTION 'Invalid or duplicate packing tag';
  END IF;

  FOR r IN
    SELECT o.id, o.packing_meta, t.tag
    FROM public.or_orders o
    JOIN jsonb_to_recordset(p_tags) AS t(order_id uuid, tag numeric) ON t.order_id = o.id
    ORDER BY o.id FOR UPDATE OF o
  LOOP
    v_tag := r.packing_meta->'dailyPackingTag';
    IF v_tag IS NULL OR v_tag = 'null'::jsonb THEN
      UPDATE public.or_orders
      SET packing_meta = jsonb_set(
        CASE WHEN jsonb_typeof(packing_meta) = 'object' THEN packing_meta ELSE '{}'::jsonb END,
        '{dailyPackingTag}', to_jsonb(r.tag), true)
      WHERE id = r.id
      RETURNING packing_meta->'dailyPackingTag' INTO v_tag;
      IF NOT FOUND THEN RAISE EXCEPTION 'Cannot update a requested packing order'; END IF;
    END IF;
    v_result := v_result || jsonb_build_object(r.id::text, v_tag);
    v_count := v_count + 1;
  END LOOP;
  -- Do not silently display tags that RLS prevented us from saving. An error
  -- rolls the whole request back, including preceding rows in this batch.
  IF v_count <> jsonb_array_length(p_tags) THEN
    RAISE EXCEPTION 'A requested packing order is unavailable';
  END IF;
  RETURN v_result;
END;
$$;


--
-- Name: rpc_assign_wms_for_work_order(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_assign_wms_for_work_order(p_work_order_name text, p_picker_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role           TEXT;
  v_existing       INT;
  v_has_items      BOOLEAN;
  v_pick_norm      INT;
  v_pick_spare     INT;
  v_system         INT;
  v_picker_ok      BOOLEAN;
  v_wo             TEXT;
BEGIN
  v_wo := trim(both FROM coalesce(p_work_order_name, ''));

  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN (
    'superadmin', 'admin', 'store', 'manager', 'production'
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์มอบหมาย WMS (ต้องเป็น superadmin / admin / store / manager / production)';
  END IF;

  IF v_wo = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'ต้องระบุใบงาน');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM us_users WHERE id = p_picker_id AND role = 'picker'
  ) INTO v_picker_ok;

  IF NOT coalesce(v_picker_ok, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'ต้องระบุผู้ใช้ role picker ที่ถูกต้อง');
  END IF;

  SELECT COUNT(*) INTO v_existing
  FROM wms_orders
  WHERE trim(both FROM coalesce(order_id, '')) = v_wo
    AND status <> 'cancelled';

  IF v_existing > 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'ใบงานนี้ถูกสร้างในระบบ WMS แล้ว'
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM or_orders o
    JOIN or_order_items oi ON oi.order_id = o.id
    WHERE o.work_order_name = v_wo
  ) INTO v_has_items;

  IF NOT v_has_items THEN
    RETURN jsonb_build_object('success', false, 'error', 'ไม่พบรายการสินค้าในใบงานนี้');
  END IF;

  WITH base AS (
    SELECT
      o.id AS ord_id,
      oi.id AS ord_item_id,
      oi.product_id,
      max(oi.product_name::text) AS product_name,
      sum(coalesce(oi.quantity, 1)::numeric) AS sum_q,
      max(p.product_category)::text AS cat,
      max(p.product_code)::text AS product_code,
      max(p.storage_location)::text AS loc,
      max(coalesce(nullif(trim(p.unit_name::text), ''), 'ชิ้น')) AS unit_name
    FROM or_orders o
    JOIN or_order_items oi ON oi.order_id = o.id
    JOIN pr_products p ON p.id = oi.product_id
    WHERE o.work_order_name = v_wo
      AND fn_wms_is_pickable_category(p.product_category::text)
    GROUP BY o.id, oi.id, oi.product_id
  )
  INSERT INTO wms_orders (
    order_id, product_code, product_name, location, qty, unit_name,
    assigned_to, status, fulfillment_mode, source_order_id, source_order_item_id
  )
  SELECT
    v_wo,
    coalesce(nullif(trim(product_code), ''), product_name, 'N/A'),
    product_name,
    coalesce(loc, ''),
    CASE
      WHEN upper(coalesce(cat, '')) LIKE '%CONDO STAMP%'
        THEN ceil(sum_q / 5)::int
      ELSE sum_q::int
    END,
    unit_name,
    p_picker_id,
    'pending',
    'warehouse_pick',
    ord_id,
    ord_item_id
  FROM base;

  GET DIAGNOSTICS v_pick_norm = ROW_COUNT;

  WITH spare_src AS (
    SELECT
      o.id AS ord_id,
      p.rubber_code AS rc,
      sum(coalesce(oi.quantity, 1)::numeric) AS spare_qty
    FROM or_orders o
    JOIN or_order_items oi ON oi.order_id = o.id
    JOIN pr_products p ON p.id = oi.product_id
    WHERE o.work_order_name = v_wo
      AND p.rubber_code IS NOT NULL
      AND trim(p.rubber_code::text) <> ''
      AND fn_wms_is_pickable_category(p.product_category::text)
    GROUP BY o.id, p.rubber_code
  )
  INSERT INTO wms_orders (
    order_id, product_code, product_name, location, qty, unit_name,
    assigned_to, status, fulfillment_mode, source_order_id
  )
  SELECT
    v_wo,
    'SPARE_PART',
    'หน้ายาง+โฟม ' || rc,
    'อะไหล่',
    spare_qty::int,
    'ชิ้น',
    p_picker_id,
    'pending',
    'warehouse_pick',
    ord_id
  FROM spare_src;

  GET DIAGNOSTICS v_pick_spare = ROW_COUNT;

  WITH base_np AS (
    SELECT
      o.id AS ord_id,
      oi.id AS ord_item_id,
      oi.product_id,
      max(oi.product_name::text) AS product_name,
      sum(coalesce(oi.quantity, 1)::numeric) AS sum_q,
      max(p.product_category)::text AS cat,
      max(p.product_code)::text AS product_code,
      max(p.storage_location)::text AS loc,
      max(coalesce(nullif(trim(p.unit_name::text), ''), 'ชิ้น')) AS unit_name
    FROM or_orders o
    JOIN or_order_items oi ON oi.order_id = o.id
    JOIN pr_products p ON p.id = oi.product_id
    WHERE o.work_order_name = v_wo
      AND NOT fn_wms_is_pickable_category(p.product_category::text)
      AND oi.product_id IS NOT NULL
      AND p.product_code IS NOT NULL
      AND trim(p.product_code::text) <> ''
    GROUP BY o.id, oi.id, oi.product_id
  ),
  ins AS (
    INSERT INTO wms_orders (
      order_id, product_code, product_name, location, qty, unit_name,
      assigned_to, status, fulfillment_mode, source_order_id, source_order_item_id
    )
    SELECT
      v_wo,
      trim(product_code),
      product_name,
      coalesce(loc, ''),
      CASE
        WHEN upper(coalesce(cat, '')) LIKE '%CONDO STAMP%'
          THEN ceil(sum_q / 5)::int
        ELSE sum_q::int
      END,
      unit_name,
      p_picker_id,
      'pending',
      'system_complete',
      ord_id,
      ord_item_id
    FROM base_np
    RETURNING id
  )
  UPDATE wms_orders w
  SET status = 'correct'
  FROM ins
  WHERE w.id = ins.id;

  GET DIAGNOSTICS v_system = ROW_COUNT;

  IF (coalesce(v_pick_norm, 0) + coalesce(v_pick_spare, 0) + coalesce(v_system, 0)) = 0 THEN
    DELETE FROM wms_orders WHERE trim(both FROM coalesce(order_id, '')) = v_wo;
    RETURN jsonb_build_object(
      'success', false,
      'error',
      'ไม่มีรายการที่สร้าง WMS ได้ (ตรวจสอบ product_id / รหัสสินค้า)'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'work_order_name', v_wo,
    'warehouse_pick_main', coalesce(v_pick_norm, 0),
    'warehouse_pick_spare', coalesce(v_pick_spare, 0),
    'system_complete', coalesce(v_system, 0)
  );
END;
$$;


--
-- Name: FUNCTION rpc_assign_wms_for_work_order(p_work_order_name text, p_picker_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_assign_wms_for_work_order(p_work_order_name text, p_picker_id uuid) IS 'มอบหมายใบงาน WMS: แถวหยิบ pending + แถวไม่หยิบตัดสต๊อกอัตโนมัติ (system_complete)';


--
-- Name: rpc_assign_wms_for_work_order_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_assign_wms_for_work_order_v2(p_work_order_id uuid, p_picker_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT; v_existing INT; v_has_items BOOLEAN; v_pick_norm INT;
  v_pick_spare INT; v_system INT; v_sub_skip INT; v_picker_ok BOOLEAN; v_work_order_name TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF (v_role IS NULL OR v_role NOT IN ('superadmin','admin','store','manager','production'))
     AND NOT public.is_current_wms_store_backup() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์มอบหมาย WMS';
  END IF;
  IF p_work_order_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','ต้องระบุใบงาน'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('WMS_ASSIGN:'||p_work_order_id::TEXT,0));
  SELECT work_order_name INTO v_work_order_name FROM public.or_work_orders WHERE id=p_work_order_id;
  IF NULLIF(BTRIM(COALESCE(v_work_order_name,'')),'') IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','ไม่พบใบงาน');
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.us_users WHERE id=p_picker_id AND role='picker') INTO v_picker_ok;
  IF NOT COALESCE(v_picker_ok,false) THEN
    RETURN jsonb_build_object('success',false,'error','ต้องระบุผู้ใช้ role picker ที่ถูกต้อง');
  END IF;

  SELECT COUNT(*) INTO v_existing FROM public.wms_orders
  WHERE work_order_id=p_work_order_id AND status<>'cancelled'
    AND (fulfillment_mode='warehouse_pick' OR fulfillment_mode IS NULL);
  IF v_existing>0 THEN
    RETURN jsonb_build_object('success',false,'error','ใบงานนี้ถูกมอบหมาย Picker ในระบบ WMS แล้ว');
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.or_orders o JOIN public.or_order_items oi ON oi.order_id=o.id
    WHERE o.work_order_id=p_work_order_id AND NOT COALESCE(oi.is_detail_row,false)
  ) INTO v_has_items;
  IF NOT v_has_items THEN RETURN jsonb_build_object('success',false,'error','ไม่พบรายการสินค้าหลักในใบงานนี้'); END IF;

  WITH base AS (
    SELECT o.id source_order_id,oi.id source_order_item_id,oi.product_name,
      COALESCE(oi.quantity,1)::NUMERIC sum_q,p.product_category::TEXT cat,
      p.product_code::TEXT product_code,p.storage_location::TEXT loc,
      COALESCE(NULLIF(BTRIM(p.unit_name::TEXT),''),'ชิ้น') unit_name
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id=o.id
    JOIN public.pr_products p ON p.id=oi.product_id
    WHERE o.work_order_id=p_work_order_id AND NOT COALESCE(oi.is_detail_row,false)
      AND public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT)='warehouse_pick'
      AND NOT EXISTS (SELECT 1 FROM public.wms_orders w WHERE w.source_order_item_id=oi.id AND w.status<>'cancelled')
  ), ins AS (
    INSERT INTO public.wms_orders(work_order_id,order_id,source_order_id,source_order_item_id,
      product_code,product_name,location,qty,unit_name,status,assigned_to,fulfillment_mode)
    SELECT p_work_order_id,v_work_order_name,source_order_id,source_order_item_id,
      COALESCE(NULLIF(BTRIM(product_code),''),product_name,'N/A'),product_name,COALESCE(loc,''),sum_q,
      unit_name,'pending',p_picker_id,'warehouse_pick'
    FROM base RETURNING id
  ) SELECT COUNT(*) INTO v_pick_norm FROM ins;

  WITH spare AS (
    SELECT p.rubber_code rc,SUM(COALESCE(oi.quantity,1)::NUMERIC) sum_q
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id=o.id
    JOIN public.pr_products p ON p.id=oi.product_id
    WHERE o.work_order_id=p_work_order_id AND NOT COALESCE(oi.is_detail_row,false)
      AND NULLIF(BTRIM(COALESCE(p.rubber_code::TEXT,'')),'') IS NOT NULL
      AND public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT)='warehouse_pick'
    GROUP BY p.rubber_code
  ), ins2 AS (
    INSERT INTO public.wms_orders(work_order_id,order_id,source_order_id,source_order_item_id,
      product_code,product_name,location,qty,unit_name,status,assigned_to,fulfillment_mode)
    SELECT p_work_order_id,v_work_order_name,NULL,NULL,'SPARE_PART',rc::TEXT,'อะไหล่',sum_q,'ชิ้น',
      'pending',p_picker_id,'warehouse_pick' FROM spare RETURNING id
  ) SELECT COUNT(*) INTO v_pick_spare FROM ins2;

  PERFORM public.fn_wms_try_auto_consume_non_pick(v_work_order_name);
  SELECT COUNT(*) INTO v_system FROM public.wms_orders
    WHERE work_order_id=p_work_order_id AND fulfillment_mode='system_complete' AND status='correct';
  SELECT COUNT(*) INTO v_sub_skip FROM public.wms_orders
    WHERE work_order_id=p_work_order_id AND fulfillment_mode='sub_warehouse_skip' AND status='correct';
  RETURN jsonb_build_object('success',true,'work_order_id',p_work_order_id,'work_order_name',v_work_order_name,
    'warehouse_pick_main',COALESCE(v_pick_norm,0),'warehouse_pick_spare',COALESCE(v_pick_spare,0),
    'system_complete',COALESCE(v_system,0),'sub_warehouse_skip',COALESCE(v_sub_skip,0));
END;
$$;


--
-- Name: rpc_audit_movement_products(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_audit_movement_products(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(product_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM us_users WHERE id=auth.uid() AND is_active AND role IN ('superadmin','admin','store','sales-tr','account','auditor')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูรายการสินค้า Audit';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_from >= p_to THEN RAISE EXCEPTION 'ช่วงวันที่ไม่ถูกต้อง'; END IF;
  RETURN QUERY
  WITH moved AS (
    SELECT m.product_id FROM inv_stock_movements m
    WHERE m.created_at >= p_from AND m.created_at < p_to
      AND m.movement_type NOT IN ('reserve','unreserve','reservation','release_reservation')
    UNION
    SELECT i.product_id FROM wh_stock_transfer_items i JOIN wh_stock_transfers t ON t.id=i.transfer_id
    WHERE (t.posted_at >= p_from AND t.posted_at < p_to)
       OR (t.cancelled_at >= p_from AND t.cancelled_at < p_to AND t.posted_at IS NOT NULL)
  ), expanded AS (
    SELECT m.product_id FROM moved m
    UNION
    SELECT s.product_id FROM moved m
    JOIN wh_sub_wms_map_sources source ON source.product_id=m.product_id
    JOIN wh_sub_wms_map_spares s ON s.group_id=source.group_id
  )
  SELECT DISTINCT p.id FROM expanded e JOIN pr_products p ON p.id=e.product_id
  WHERE p.is_active AND NOT EXISTS (SELECT 1 FROM roll_material_configs c WHERE c.fg_product_id=p.id)
  ORDER BY p.id;
END;
$$;


--
-- Name: rpc_backfill_plan_pick_end_from_wms(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_backfill_plan_pick_end_from_wms(p_work_order_id uuid DEFAULT NULL::uuid, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_wid UUID;
  v_ts TIMESTAMPTZ;
  v_patch JSONB;
  v_berk JSONB;
  v_has_pick_end BOOLEAN;
  v_has_deliver_end BOOLEAN;
  v_review_count INT;
  v_bad_count INT;
  v_updated JSONB := '[]'::jsonb;
  v_skipped JSONB := '[]'::jsonb;
  v_n_updated INT := 0;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store', 'manager', 'production') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ไม่มีสิทธิ์ใช้ฟังก์ชันนี้');
  END IF;

  IF p_work_order_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM plan_jobs WHERE work_order_id = p_work_order_id) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'ไม่พบ plan_jobs สำหรับ work_order_id นี้'
      );
    END IF;
  END IF;

  FOR v_wid IN
    SELECT DISTINCT pj.work_order_id
    FROM plan_jobs pj
    WHERE pj.work_order_id IS NOT NULL
      AND (p_work_order_id IS NULL OR pj.work_order_id = p_work_order_id)
  LOOP
    SELECT COUNT(*) INTO v_review_count
    FROM wms_orders w
    WHERE w.work_order_id = v_wid
      AND (
        (w.fulfillment_mode = 'warehouse_pick' AND w.status <> 'cancelled')
        OR (w.fulfillment_mode = 'warehouse_pick' AND w.status = 'cancelled' AND w.stock_action = 'recalled')
        OR (w.fulfillment_mode IS NULL AND w.status <> 'cancelled')
        OR (w.fulfillment_mode IS NULL AND w.status = 'cancelled' AND w.stock_action = 'recalled')
      );

    IF v_review_count = 0 THEN
      v_skipped := v_skipped || jsonb_build_object('work_order_id', v_wid, 'reason', 'no_wms_review_rows');
      CONTINUE;
    END IF;

    SELECT COUNT(*) INTO v_bad_count
    FROM wms_orders w
    WHERE w.work_order_id = v_wid
      AND (
        (w.fulfillment_mode = 'warehouse_pick' AND w.status <> 'cancelled')
        OR (w.fulfillment_mode = 'warehouse_pick' AND w.status = 'cancelled' AND w.stock_action = 'recalled')
        OR (w.fulfillment_mode IS NULL AND w.status <> 'cancelled')
        OR (w.fulfillment_mode IS NULL AND w.status = 'cancelled' AND w.stock_action = 'recalled')
      )
      AND w.status NOT IN ('correct', 'wrong', 'not_find', 'out_of_stock', 'returned');

    IF v_bad_count > 0 THEN
      v_skipped := v_skipped || jsonb_build_object('work_order_id', v_wid, 'reason', 'inspect_not_complete');
      CONTINUE;
    END IF;

    SELECT tracks -> 'เบิก' INTO v_berk
    FROM plan_jobs
    WHERE work_order_id = v_wid
    ORDER BY date DESC
    LIMIT 1;

    v_has_pick_end :=
      jsonb_typeof(COALESCE(v_berk -> 'หยิบของ' -> 'end', 'null'::jsonb)) = 'string';
    v_has_deliver_end :=
      jsonb_typeof(COALESCE(v_berk -> 'ส่งมอบ' -> 'end', 'null'::jsonb)) = 'string';

    IF NOT p_force AND v_has_pick_end AND v_has_deliver_end THEN
      v_skipped := v_skipped || jsonb_build_object('work_order_id', v_wid, 'reason', 'already_stamped');
      CONTINUE;
    END IF;

    SELECT MAX(w.end_time) INTO v_ts
    FROM wms_orders w
    WHERE w.work_order_id = v_wid
      AND (w.fulfillment_mode = 'warehouse_pick' OR w.fulfillment_mode IS NULL);

    IF v_ts IS NULL THEN
      SELECT MAX(w.updated_at) INTO v_ts
      FROM wms_orders w
      WHERE w.work_order_id = v_wid
        AND (
          (w.fulfillment_mode = 'warehouse_pick' AND w.status <> 'cancelled')
          OR (w.fulfillment_mode = 'warehouse_pick' AND w.status = 'cancelled' AND w.stock_action = 'recalled')
          OR (w.fulfillment_mode IS NULL AND w.status <> 'cancelled')
          OR (w.fulfillment_mode IS NULL AND w.status = 'cancelled' AND w.stock_action = 'recalled')
        )
        AND w.status IN ('correct', 'wrong', 'not_find', 'out_of_stock', 'returned');
    END IF;

    IF v_ts IS NULL THEN
      v_ts := NOW();
    END IF;

    v_patch := jsonb_build_object(
      'หยิบของ', jsonb_build_object('start_if_null', to_jsonb(v_ts), 'end', to_jsonb(v_ts)),
      'ส่งมอบ', jsonb_build_object('start_if_null', to_jsonb(v_ts), 'end', to_jsonb(v_ts))
    );

    PERFORM merge_plan_tracks_by_work_order_id(v_wid, 'เบิก', v_patch);

    v_updated := v_updated || to_jsonb(v_wid);
    v_n_updated := v_n_updated + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'updated_count', v_n_updated,
    'updated_work_order_ids', v_updated,
    'skipped', v_skipped
  );
END;
$$;


--
-- Name: FUNCTION rpc_backfill_plan_pick_end_from_wms(p_work_order_id uuid, p_force boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_backfill_plan_pick_end_from_wms(p_work_order_id uuid, p_force boolean) IS 'ย้อนประทับเวลาเสร็จแผนก เบิก (หยิบของ/ส่งมอบ) เมื่อ WMS ตรวจครบแล้ว — แก้ใบงานเดิมที่ไม่ถูก stamp จากบั๊ก allCorrect';


--
-- Name: rpc_bulk_import_products_with_stock(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_bulk_import_products_with_stock(items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_role           TEXT;
  item             JSONB;
  v_product_id     UUID;
  v_product_code   TEXT;
  v_initial_stock  NUMERIC;
  v_safety_stock   NUMERIC;
  v_unit_cost      NUMERIC;
  v_on_hand        NUMERIC;
  v_imported       INT := 0;
  v_skipped        INT := 0;
  v_errors         JSONB := '[]'::JSONB;
  v_order_days_raw TEXT;
  v_order_days     INTEGER;
  v_seller_type    TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ import สินค้า (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(items)
  LOOP
    v_product_code := item->>'product_code';

    IF EXISTS (SELECT 1 FROM pr_products WHERE product_code = v_product_code) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    v_initial_stock := COALESCE((item->>'initial_stock')::NUMERIC, 0);
    v_safety_stock  := COALESCE((item->>'safety_stock')::NUMERIC, 0);
    v_unit_cost     := COALESCE((item->>'unit_cost')::NUMERIC, 0);

    v_order_days_raw := NULLIF(TRIM(COALESCE(item->>'order_point_days', '')), '');
    v_order_days := CASE
      WHEN v_order_days_raw IS NULL THEN NULL
      WHEN v_order_days_raw !~ '^[0-9]+(\.[0-9]+)?$' THEN NULL
      ELSE FLOOR(v_order_days_raw::NUMERIC)::INTEGER
    END;

    v_seller_type := fn_normalize_seller_type(item->>'seller_type');
    IF item ? 'seller_type'
       AND NULLIF(TRIM(COALESCE(item->>'seller_type', '')), '') IS NOT NULL
       AND v_seller_type IS NULL THEN
      v_errors := v_errors || jsonb_build_object(
        'product_code', v_product_code,
        'error', 'seller_type ไม่ถูกต้อง (ใช้ thailand หรือ foreign)'
      );
      CONTINUE;
    END IF;

    IF v_safety_stock > v_initial_stock THEN
      v_safety_stock := v_initial_stock;
    END IF;

    v_on_hand := v_initial_stock - v_safety_stock;

    BEGIN
      INSERT INTO pr_products (
        product_code, product_name, product_category, product_type,
        seller_name, seller_name_cn, seller_purchase_channel, seller_type,
        product_name_cn, order_point, order_point_days,
        rubber_code, storage_location,
        unit_cost, landed_cost, safety_stock,
        unit_name, unit_multiplier,
        is_active
      )
      VALUES (
        v_product_code,
        item->>'product_name',
        NULLIF(item->>'product_category', ''),
        COALESCE(NULLIF(item->>'product_type', ''), 'FG'),
        NULLIF(item->>'seller_name', ''),
        NULLIF(item->>'seller_name_cn', ''),
        NULLIF(item->>'seller_purchase_channel', ''),
        v_seller_type,
        NULLIF(item->>'product_name_cn', ''),
        NULLIF(item->>'order_point', ''),
        v_order_days,
        NULLIF(item->>'rubber_code', ''),
        NULLIF(item->>'storage_location', ''),
        v_unit_cost,
        CASE WHEN v_unit_cost > 0 THEN v_unit_cost ELSE 0 END,
        v_safety_stock,
        COALESCE(NULLIF(item->>'unit_name', ''), 'ชิ้น'),
        GREATEST(COALESCE((item->>'unit_multiplier')::NUMERIC, 1), 0.01),
        TRUE
      )
      RETURNING id INTO v_product_id;

      IF v_initial_stock > 0 THEN
        INSERT INTO inv_stock_balances (product_id, on_hand, reserved, safety_stock)
        VALUES (v_product_id, v_on_hand, 0, v_safety_stock);

        IF v_on_hand > 0 THEN
          INSERT INTO inv_stock_lots (
            product_id, qty_initial, qty_remaining, unit_cost,
            ref_type, ref_id, is_safety_stock
          )
          VALUES (
            v_product_id, v_on_hand, v_on_hand, v_unit_cost,
            'initial_import', NULL, FALSE
          );

          INSERT INTO inv_stock_movements (
            product_id, movement_type, qty, ref_type, note,
            unit_cost, total_cost
          )
          VALUES (
            v_product_id, 'adjust', v_on_hand, 'initial_import',
            'นำเข้าสต๊อคเริ่มต้น',
            v_unit_cost, v_on_hand * v_unit_cost
          );
        END IF;

        IF v_safety_stock > 0 THEN
          INSERT INTO inv_stock_lots (
            product_id, qty_initial, qty_remaining, unit_cost,
            ref_type, ref_id, is_safety_stock
          )
          VALUES (
            v_product_id, v_safety_stock, v_safety_stock, v_unit_cost,
            'initial_import', NULL, TRUE
          );

          INSERT INTO inv_stock_movements (
            product_id, movement_type, qty, ref_type, note,
            unit_cost, total_cost
          )
          VALUES (
            v_product_id, 'adjust', v_safety_stock, 'initial_import',
            'นำเข้า safety stock เริ่มต้น',
            v_unit_cost, v_safety_stock * v_unit_cost
          );
        END IF;

        PERFORM fn_recalc_product_landed_cost(v_product_id);
      END IF;

      v_imported := v_imported + 1;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_object(
        'product_code', v_product_code,
        'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'imported', v_imported,
    'skipped', v_skipped,
    'errors', v_errors
  );
END;
$_$;


--
-- Name: rpc_cancel_inventory_adjustment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_inventory_adjustment(p_adjustment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_adjustment public.inv_adjustments%ROWTYPE;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT u.role INTO v_role
    FROM public.us_users u
    WHERE u.id = auth.uid() AND u.is_active IS TRUE;

    IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
      RAISE EXCEPTION 'Not authorized to cancel an inventory adjustment';
    END IF;
  END IF;

  IF p_reason IS NULL OR char_length(btrim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'Cancellation reason must contain at least 3 characters';
  END IF;

  SELECT * INTO v_adjustment
  FROM public.inv_adjustments
  WHERE id = p_adjustment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory adjustment not found';
  END IF;
  IF v_adjustment.status <> 'pending' THEN
    RAISE EXCEPTION 'Only a pending inventory adjustment can be cancelled';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.inv_stock_movements
    WHERE ref_type = 'inv_adjustments' AND ref_id = p_adjustment_id
  ) THEN
    RAISE EXCEPTION 'This adjustment already has stock movements and cannot be cancelled';
  END IF;

  UPDATE public.inv_adjustments
  SET status = 'cancelled',
      cancelled_by = auth.uid(),
      cancelled_at = now(),
      cancel_reason = btrim(p_reason)
  WHERE id = p_adjustment_id;

  RETURN jsonb_build_object(
    'success', true,
    'adjustment_id', p_adjustment_id,
    'adjust_no', v_adjustment.adjust_no,
    'status', 'cancelled'
  );
END;
$$;


--
-- Name: FUNCTION rpc_cancel_inventory_adjustment(p_adjustment_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_cancel_inventory_adjustment(p_adjustment_id uuid, p_reason text) IS 'Cancels a pending inventory adjustment only when no stock movement exists, with user/time/reason audit fields.';


--
-- Name: or_prebill_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.or_prebill_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_type text NOT NULL,
    document_no text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    channel_code text NOT NULL,
    header_name text NOT NULL,
    customer_name text DEFAULT 'ลูกค้า'::text NOT NULL,
    customer_address text,
    recipient_name text,
    customer_phone text,
    billing_details jsonb DEFAULT '{}'::jsonb NOT NULL,
    delivery_term text DEFAULT '1-3 วัน'::text NOT NULL,
    valid_until date NOT NULL,
    payment_method text,
    subtotal numeric(14,2) DEFAULT 0 NOT NULL,
    shipping_cost numeric(14,2) DEFAULT 0 NOT NULL,
    promotion_discount numeric(14,2) DEFAULT 0 NOT NULL,
    special_discount numeric(14,2) DEFAULT 0 NOT NULL,
    special_discount_type text,
    special_discount_value numeric(14,2) DEFAULT 0 NOT NULL,
    total_amount numeric(14,2) DEFAULT 0 NOT NULL,
    promotion_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    promotion_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    shipping_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    internal_note text,
    discount_request_note text,
    discount_requested_at timestamp with time zone,
    discount_requested_by uuid,
    approved_special_discount numeric(14,2),
    approval_note text,
    approved_at timestamp with time zone,
    approved_by uuid,
    rejection_note text,
    converted_order_id uuid,
    converted_at timestamp with time zone,
    source_document_id uuid,
    owner_id uuid DEFAULT auth.uid() NOT NULL,
    owner_name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    stock_reservation_enabled boolean DEFAULT true NOT NULL,
    discount_review_snapshot jsonb,
    CONSTRAINT or_prebill_documents_document_type_check CHECK ((document_type = ANY (ARRAY['quotation'::text, 'production_confirmation'::text]))),
    CONSTRAINT or_prebill_documents_special_discount_type_check CHECK (((special_discount_type IS NULL) OR (special_discount_type = ANY (ARRAY['amount'::text, 'percent'::text])))),
    CONSTRAINT or_prebill_documents_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'pending_discount'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'converted'::text, 'cancelled'::text]))),
    CONSTRAINT or_prebill_non_negative CHECK (((subtotal >= (0)::numeric) AND (shipping_cost >= (0)::numeric) AND (promotion_discount >= (0)::numeric) AND (special_discount >= (0)::numeric) AND (special_discount_value >= (0)::numeric) AND (total_amount >= (0)::numeric)))
);


--
-- Name: TABLE or_prebill_documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.or_prebill_documents IS 'QT/PC documents before a real order; never consumed by operational order flows';


--
-- Name: rpc_cancel_prebill_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_prebill_document(p_document_id uuid) RETURNS public.or_prebill_documents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc public.or_prebill_documents;
BEGIN
  SELECT * INTO v_doc
  FROM public.or_prebill_documents
  WHERE id = p_document_id
  FOR UPDATE;

  IF v_doc.id IS NULL THEN RAISE EXCEPTION 'ไม่พบเอกสาร'; END IF;
  IF NOT public.can_manage_prebill_document(v_doc.owner_id) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยกเลิกเอกสารนี้';
  END IF;
  IF v_doc.status = 'converted' OR v_doc.converted_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'ไม่สามารถยกเลิกเอกสารที่เปิดบิลแล้วได้';
  END IF;
  IF v_doc.status = 'cancelled' THEN RETURN v_doc; END IF;

  UPDATE public.or_prebill_documents
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_document_id
  RETURNING * INTO v_doc;
  RETURN v_doc;
END;
$$;


--
-- Name: rpc_cancel_stock_transfer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_stock_transfer(p_transfer_id uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_transfer public.wh_stock_transfers%ROWTYPE; v_item RECORD;
BEGIN
  IF NOT public.can_manage_warehouse_locations() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ยกเลิกใบย้าย'; END IF;
  SELECT * INTO v_transfer FROM public.wh_stock_transfers WHERE id=p_transfer_id FOR UPDATE;
  IF v_transfer.id IS NULL OR v_transfer.status='cancelled' THEN RAISE EXCEPTION 'ไม่พบใบย้ายหรือใบถูกยกเลิกแล้ว'; END IF;
  IF v_transfer.status='posted' THEN
    FOR v_item IN SELECT * FROM public.wh_stock_transfer_items WHERE transfer_id=p_transfer_id LOOP
      UPDATE public.wh_location_stock SET qty=qty-v_item.qty, updated_at=NOW()
      WHERE product_id=v_item.product_id AND location_id=v_transfer.to_location_id AND qty>=v_item.qty;
      IF NOT FOUND THEN RAISE EXCEPTION 'ยกเลิกไม่ได้: สินค้าที่ปลายทางคงเหลือไม่พอ'; END IF;
      INSERT INTO public.wh_location_stock(product_id, location_id, qty)
      VALUES (v_item.product_id, v_transfer.from_location_id, v_item.qty)
      ON CONFLICT (product_id, location_id) DO UPDATE SET qty=public.wh_location_stock.qty+EXCLUDED.qty, updated_at=NOW();
    END LOOP;
  END IF;
  UPDATE public.wh_stock_transfers SET status='cancelled', cancelled_by=auth.uid(), cancelled_at=NOW(), cancel_note=NULLIF(BTRIM(p_note),'')
  WHERE id=p_transfer_id;
END;
$$;


--
-- Name: rpc_cancel_sub_warehouse_replenishment_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_sub_warehouse_replenishment_request(p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.can_request_sub_warehouse_stock() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยกเลิกคำขอเบิกสินค้าคลังย่อย';
  END IF;

  UPDATE public.wh_sub_warehouse_replenishment_requests
  SET status = 'cancelled', cancelled_at = NOW(), updated_at = NOW()
  WHERE id = p_request_id
    AND requested_by = auth.uid()
    AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบคำขอที่แก้ไขได้ หรือคำขอนี้ถูกดำเนินการแล้ว';
  END IF;
  RETURN true;
END;
$$;


--
-- Name: rpc_cancel_wms_for_amendment(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_wms_for_amendment(p_work_order_name text, p_amendment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_wms      RECORD;
  v_reversed INT := 0;
  v_released INT := 0;
  v_product_id UUID;
BEGIN
  FOR v_wms IN
    SELECT id, product_code, qty, status
    FROM wms_orders
    WHERE order_id = p_work_order_name
      AND status NOT IN ('cancelled')
  LOOP
    -- หา product_id จาก product_code
    SELECT id INTO v_product_id
    FROM pr_products
    WHERE product_code = v_wms.product_code
    LIMIT 1;

    IF v_wms.status = 'correct' AND v_product_id IS NOT NULL THEN
      PERFORM fn_reverse_wms_stock(v_wms.id);
      v_reversed := v_reversed + 1;

    ELSIF v_wms.status = 'picked' AND v_product_id IS NOT NULL THEN
      UPDATE inv_stock_balances
      SET reserved = GREATEST(COALESCE(reserved, 0) - v_wms.qty, 0)
      WHERE product_id = v_product_id;
      v_released := v_released + 1;
    END IF;

    -- ยกเลิก wms row (ไม่ใช้ update status เพราะ trigger จะทำงาน)
    -- ลบ row แทนเพื่อไม่ให้ trigger inv_deduct_stock_on_wms_picked ทำงานซ้ำ
    DELETE FROM wms_orders WHERE id = v_wms.id;
  END LOOP;

  RETURN jsonb_build_object(
    'reversed_count', v_reversed,
    'released_count', v_released,
    'work_order_name', p_work_order_name
  );
END;
$$;


--
-- Name: rpc_change_machinery_status(uuid, public.pr_machinery_status, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_change_machinery_status(p_machine_id uuid, p_status public.pr_machinery_status, p_note text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_current_status public.pr_machinery_status;
  v_changed_at timestamptz := clock_timestamp();
BEGIN
  IF NOT public.check_user_role(
    auth.uid(),
    ARRAY['superadmin', 'admin', 'production', 'production_mb', 'manager', 'technician']
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เปลี่ยนสถานะเครื่องจักร';
  END IF;

  SELECT machine.current_status
    INTO v_current_status
  FROM public.pr_machinery_machines AS machine
  WHERE machine.id = p_machine_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบเครื่องจักร';
  END IF;

  IF v_current_status = p_status THEN
    RETURN false;
  END IF;

  UPDATE public.pr_machinery_status_events
  SET ended_at = v_changed_at
  WHERE machine_id = p_machine_id
    AND ended_at IS NULL;

  UPDATE public.pr_machinery_machines
  SET current_status = p_status,
      status_changed_at = v_changed_at
  WHERE id = p_machine_id;

  INSERT INTO public.pr_machinery_status_events (
    machine_id, status, started_at, ended_at, note, created_by
  ) VALUES (
    p_machine_id, p_status, v_changed_at, NULL, p_note, auth.uid()
  );

  RETURN true;
END;
$$;


--
-- Name: rpc_check_order_discount(uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_check_order_discount(p_order_id uuid, p_header jsonb, p_items jsonb, p_promotions jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND is_active AND role IN ('superadmin','admin','sales-tr','sales-pump','account','qc_order'))
  OR (p_order_id IS NOT NULL AND NOT public.or_discount_can_manage(p_order_id) AND NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND is_active AND role IN ('account','qc_order'))) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์'; END IF;
 RETURN public.or_discount_state(p_order_id,p_header,p_items,p_promotions);
END $$;


--
-- Name: rpc_check_order_edit_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_check_order_edit_eligibility(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_pending_amend INT := 0;
  v_linked BOOLEAN := false;
BEGIN
  SELECT id, status, shipped_time, work_order_id, work_order_name, bill_no, is_locked
  INTO v_order
  FROM public.or_orders
  WHERE id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('error', 'ไม่พบออเดอร์');
  END IF;

  IF v_order.is_locked THEN
    RETURN jsonb_build_object(
      'can_direct_edit', false,
      'can_edit_name_lines_only', false,
      'needs_amendment', false,
      'needs_credit_note', false,
      'is_locked', true,
      'reason', 'บิลนี้ถูกล็อกแล้ว ไม่สามารถแก้ไขได้'
    );
  END IF;

  IF v_order.status = 'จัดส่งแล้ว' OR v_order.shipped_time IS NOT NULL THEN
    RETURN jsonb_build_object(
      'can_direct_edit', false,
      'can_edit_name_lines_only', false,
      'needs_amendment', false,
      'needs_credit_note', false,
      'is_shipped', true,
      'order_status', v_order.status,
      'reason', 'บิลจัดส่งแล้ว — กรุณาใช้ระบบเคลมแทน'
    );
  END IF;

  IF v_order.status = 'ยกเลิก' THEN
    RETURN jsonb_build_object(
      'can_direct_edit', false,
      'can_edit_name_lines_only', false,
      'needs_amendment', false,
      'needs_credit_note', false,
      'reason', 'บิลถูกยกเลิกแล้ว ไม่สามารถแก้ไขได้'
    );
  END IF;

  SELECT count(*) INTO v_pending_amend
  FROM public.or_order_amendments
  WHERE order_id = p_order_id AND status = 'pending';

  IF v_pending_amend > 0 THEN
    RETURN jsonb_build_object(
      'can_direct_edit', false,
      'can_edit_name_lines_only', false,
      'needs_amendment', false,
      'needs_credit_note', false,
      'has_pending_amendment', true,
      'reason', 'บิลนี้มีคำขอยกเลิกรออนุมัติอยู่แล้ว'
    );
  END IF;

  v_linked := v_order.work_order_id IS NOT NULL
    OR nullif(trim(coalesce(v_order.work_order_name, '')), '') IS NOT NULL;

  IF v_linked THEN
    RETURN jsonb_build_object(
      'can_direct_edit', false,
      'can_edit_name_lines_only', true,
      'needs_amendment', false,
      'needs_credit_note', false,
      'order_status', v_order.status,
      'reason', 'บิลยังไม่จัดส่ง — แก้ไขได้เฉพาะชื่อบรรทัด 1–3'
    );
  END IF;

  RETURN jsonb_build_object(
    'can_direct_edit', true,
    'can_edit_name_lines_only', false,
    'needs_amendment', false,
    'needs_credit_note', false,
    'order_status', v_order.status,
    'reason', 'สามารถแก้ไขได้โดยตรง'
  );
END;
$$;


--
-- Name: FUNCTION rpc_check_order_edit_eligibility(p_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_check_order_edit_eligibility(p_order_id uuid) IS 'บิลที่ผูกใบงานแก้ชื่อบรรทัด 1–3 ได้จนกว่า status=จัดส่งแล้ว หรือ shipped_time มีค่า';


--
-- Name: rpc_claim_packing_device(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_claim_packing_device(p_target_device_id text, p_current_device_id text, p_device_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_username TEXT;
  v_target public.pk_packing_devices%ROWTYPE;
  v_name TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'กรุณาเข้าสู่ระบบก่อนผูกสถานีแพ็ค';
  END IF;

  SELECT username INTO v_username
  FROM public.us_users
  WHERE id = v_uid AND COALESCE(is_active, TRUE) IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบผู้ใช้งานที่เปิดใช้งานอยู่';
  END IF;

  SELECT * INTO v_target
  FROM public.pk_packing_devices
  WHERE device_id = p_target_device_id
    AND is_active IS TRUE
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบทะเบียนสถานีแพ็คที่เลือก';
  END IF;

  IF COALESCE(p_current_device_id, '') <> p_target_device_id
     AND v_target.last_seen_at >= NOW() - INTERVAL '2 minutes' THEN
    RAISE EXCEPTION 'สถานี % กำลังออนไลน์อยู่ กรุณาปิดหน้าแพ็คที่เครื่องเดิมและรอ 2 นาที', v_target.device_name;
  END IF;

  IF COALESCE(p_current_device_id, '') <> ''
     AND EXISTS (
       SELECT 1
       FROM public.pk_packing_devices current_device
       WHERE current_device.device_id = p_current_device_id
         AND current_device.user_id <> v_uid
     ) THEN
    RAISE EXCEPTION 'ทะเบียน Browser ปัจจุบันไม่ได้เป็นของผู้ใช้งานที่เข้าสู่ระบบ';
  END IF;

  IF COALESCE(p_current_device_id, '') <> ''
     AND p_current_device_id <> p_target_device_id THEN
    UPDATE public.pk_packing_upload_queue_reports
    SET device_id = p_target_device_id,
        device_name = COALESCE(NULLIF(BTRIM(p_device_name), ''), v_target.device_name)
    WHERE device_id = p_current_device_id;

    UPDATE public.pk_packing_videos
    SET device_id = p_target_device_id,
        device_name = COALESCE(NULLIF(BTRIM(p_device_name), ''), v_target.device_name)
    WHERE device_id = p_current_device_id;

    UPDATE public.pk_packing_devices
    SET is_active = FALSE,
        pending_count = 0,
        uploading_count = 0,
        failed_count = 0
    WHERE device_id = p_current_device_id;
  END IF;

  v_name := COALESCE(NULLIF(BTRIM(p_device_name), ''), v_target.device_name);

  UPDATE public.pk_packing_devices
  SET user_id = v_uid,
      last_username = COALESCE(NULLIF(BTRIM(v_username), ''), 'unknown'),
      device_name = v_name,
      is_active = TRUE,
      claimed_at = NOW(),
      claimed_by = v_uid,
      last_seen_at = NOW()
  WHERE device_id = p_target_device_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'device_id', p_target_device_id,
    'device_name', v_name,
    'last_username', COALESCE(NULLIF(BTRIM(v_username), ''), 'unknown')
  );
END;
$$;


--
-- Name: FUNCTION rpc_claim_packing_device(p_target_device_id text, p_current_device_id text, p_device_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_claim_packing_device(p_target_device_id text, p_current_device_id text, p_device_name text) IS 'Reclaims an offline packing station for the current browser and remaps its queue/video records.';


--
-- Name: rpc_complete_production_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_complete_production_order(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'กรุณาโหลดหน้าใหม่และบันทึกผลผลิตจริงก่อนรับเข้า';
END;
$$;


--
-- Name: rpc_complete_production_order_actual(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_complete_production_order_actual(p_order_id uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid uuid := auth.uid(); v_role text; v_status text; v_item record; v_recipe uuid;
  v_input jsonb; v_m jsonb; v_b jsonb; v_r record; v_product record;
  v_actual numeric; v_used numeric; v_return numeric; v_waste numeric; v_short numeric;
  v_qty numeric; v_cost numeric; v_material_cost numeric; v_shortage_cost numeric;
  v_byproduct_cost numeric; v_total numeric; v_unit numeric; v_balance numeric;
  v_max numeric; v_move uuid; v_report jsonb; v_materials jsonb; v_byproducts jsonb;
  v_any_short boolean := false;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid AND is_active IS TRUE;
  IF v_role IS NULL OR v_role NOT IN ('store','admin','superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันรับเข้าผลผลิต';
  END IF;
  SELECT status INTO v_status FROM pp_production_orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS DISTINCT FROM 'processing' THEN RAISE EXCEPTION 'ใบแปรรูปไม่ได้อยู่ระหว่างการผลิต หรือปิดงานแล้ว'; END IF;
  -- Serialize edits to the item rows while validating and applying the receipt.
  PERFORM 1 FROM pp_production_order_items WHERE order_id = p_order_id ORDER BY id FOR UPDATE;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'กรุณาระบุผลผลิตจริง'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <> (SELECT count(*) FROM pp_production_order_items WHERE order_id = p_order_id)
     OR (SELECT count(DISTINCT x->>'item_id') FROM jsonb_array_elements(p_items) x) <> jsonb_array_length(p_items)
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) x WHERE NOT EXISTS
       (SELECT 1 FROM pp_production_order_items oi WHERE oi.order_id = p_order_id AND oi.id::text = x->>'item_id')) THEN
    RAISE EXCEPTION 'รายการผลผลิตไม่ตรงกับใบแปรรูป';
  END IF;

  -- Lock recipes and their lines for a consistent completion snapshot.
  PERFORM 1 FROM pp_recipes WHERE product_id IN (SELECT product_id FROM pp_production_order_items WHERE order_id = p_order_id) ORDER BY id FOR SHARE;
  PERFORM 1 FROM pp_recipe_includes WHERE recipe_id IN (SELECT r.id FROM pp_recipes r JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id) ORDER BY id FOR SHARE;
  PERFORM 1 FROM pp_recipe_removes WHERE recipe_id IN (SELECT r.id FROM pp_recipes r JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id) ORDER BY id FOR SHARE;
  -- Create and lock balance rows in a stable order, including shared materials.
  FOR v_product IN
    SELECT product_id FROM pp_production_order_items WHERE order_id=p_order_id
    UNION SELECT i.product_id FROM pp_recipe_includes i JOIN pp_recipes r ON r.id=i.recipe_id JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id
    UNION SELECT i.product_id FROM pp_recipe_removes i JOIN pp_recipes r ON r.id=i.recipe_id JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id
    ORDER BY product_id
  LOOP
    INSERT INTO inv_stock_balances(product_id,on_hand,reserved,safety_stock) VALUES(v_product.product_id,0,0,0) ON CONFLICT(product_id) DO NOTHING;
    PERFORM 1 FROM inv_stock_balances WHERE product_id=v_product.product_id FOR UPDATE;
  END LOOP;

  FOR v_item IN SELECT oi.*,p.product_code,p.product_name FROM pp_production_order_items oi JOIN pr_products p ON p.id=oi.product_id WHERE order_id=p_order_id ORDER BY oi.id LOOP
    SELECT x INTO v_input FROM jsonb_array_elements(p_items) x WHERE x->>'item_id'=v_item.id::text;
    IF COALESCE(v_input->>'actual_qty','') !~ '^\d+(\.\d{1,2})?$' THEN RAISE EXCEPTION 'จำนวนผลิตจริงไม่ถูกต้อง'; END IF;
    v_actual := (v_input->>'actual_qty')::numeric;
    IF v_actual > v_item.qty THEN RAISE EXCEPTION 'จำนวนผลิตจริงเกินจำนวนที่ขอ'; END IF;
    IF v_actual < v_item.qty THEN
      v_any_short := true;
      IF COALESCE(v_input->>'reason_code','') NOT IN ('วัตถุดิบในห่อไม่ครบ','วัตถุดิบไม่เพียงพอ','ชำรุดระหว่างผลิต','สูญเสียระหว่างผลิต','อื่น ๆ') OR btrim(COALESCE(v_input->>'reason',''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลและรายละเอียดที่ผลิตขาด'; END IF;
    END IF;
    SELECT id,max_stock INTO v_recipe,v_max FROM pp_recipes WHERE product_id=v_item.product_id;
    IF v_recipe IS NULL THEN RAISE EXCEPTION 'ไม่พบสูตรแปรรูป'; END IF;
    IF jsonb_typeof(v_input->'materials') IS DISTINCT FROM 'array' OR jsonb_typeof(v_input->'byproducts') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'กรุณาระบุรายการวัตถุดิบและสินค้าที่แยกคืน'; END IF;
    IF jsonb_array_length(v_input->'materials') <> (SELECT count(DISTINCT product_id) FROM pp_recipe_includes WHERE recipe_id=v_recipe)
       OR (SELECT count(DISTINCT x->>'product_id') FROM jsonb_array_elements(v_input->'materials') x) <> jsonb_array_length(v_input->'materials')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_input->'materials') x WHERE NOT EXISTS (SELECT 1 FROM pp_recipe_includes WHERE recipe_id=v_recipe AND product_id::text=x->>'product_id')) THEN RAISE EXCEPTION 'รายการวัตถุดิบไม่ตรงกับสูตร กรุณาเปิดบันทึกผลผลิตใหม่'; END IF;
    IF jsonb_array_length(v_input->'byproducts') <> (SELECT count(DISTINCT product_id) FROM pp_recipe_removes WHERE recipe_id=v_recipe)
       OR (SELECT count(DISTINCT x->>'product_id') FROM jsonb_array_elements(v_input->'byproducts') x) <> jsonb_array_length(v_input->'byproducts')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_input->'byproducts') x WHERE NOT EXISTS (SELECT 1 FROM pp_recipe_removes WHERE recipe_id=v_recipe AND product_id::text=x->>'product_id')) THEN RAISE EXCEPTION 'รายการสินค้าที่แยกคืนไม่ตรงกับสูตร'; END IF;
    v_material_cost:=0; v_shortage_cost:=0; v_byproduct_cost:=0; v_materials:='[]'; v_byproducts:='[]';
    FOR v_r IN SELECT i.product_id,round(sum(i.qty)*v_item.qty,2) planned_qty,p.product_code,p.product_name FROM pp_recipe_includes i JOIN pr_products p ON p.id=i.product_id WHERE recipe_id=v_recipe GROUP BY i.product_id,p.product_code,p.product_name ORDER BY i.product_id LOOP
      SELECT x INTO v_m FROM jsonb_array_elements(v_input->'materials') x WHERE x->>'product_id'=v_r.product_id::text;
      IF EXISTS (SELECT 1 FROM unnest(ARRAY['used_qty','returned_qty','waste_qty','shortage_qty']) k WHERE COALESCE(v_m->>k,'') !~ '^\d+(\.\d{1,2})?$') THEN RAISE EXCEPTION 'จำนวนวัตถุดิบไม่ถูกต้อง'; END IF;
      v_used:=(v_m->>'used_qty')::numeric; v_return:=(v_m->>'returned_qty')::numeric; v_waste:=(v_m->>'waste_qty')::numeric; v_short:=(v_m->>'shortage_qty')::numeric;
      IF v_used+v_return+v_waste+v_short <> v_r.planned_qty THEN RAISE EXCEPTION 'ยอดใช้ คืน สูญเสีย และขาดจากห่อ ของ % ไม่ตรงกับยอดตามเอกสาร %',v_r.product_code,v_r.planned_qty; END IF;
      IF (v_used<>v_r.planned_qty OR v_waste>0 OR v_short>0) AND btrim(COALESCE(v_m->>'reason',''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลส่วนต่างวัตถุดิบ %',v_r.product_code; END IF;
      v_qty:=v_used+v_waste+v_short;
      SELECT on_hand INTO v_balance FROM inv_stock_balances WHERE product_id=v_r.product_id;
      IF v_balance < v_qty THEN RAISE EXCEPTION 'สต็อกวัตถุดิบ % ไม่เพียงพอ ต้องการ % คงเหลือ %',v_r.product_code,v_qty,v_balance; END IF;
      -- Nothing was deducted at start: unused returns remain in stock, no extra receipt.
      v_cost:=0;
      IF v_used+v_waste>0 THEN
        INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by) VALUES(v_r.product_id,'pp_consume',-(v_used+v_waste),'pp_production_orders',p_order_id,'ใช้ผลิตจริงและสูญเสีย: '||COALESCE(v_m->>'reason',''),v_uid) RETURNING id INTO v_move;
        v_cost:=fn_consume_stock_fifo(v_r.product_id,v_used+v_waste,v_move);
        v_material_cost:=v_material_cost+v_cost;
      END IF;
      v_m:=jsonb_build_object('product_id',v_r.product_id,'product_code',v_r.product_code,'product_name',v_r.product_name,'planned_qty',v_r.planned_qty,'used_qty',v_used,'returned_qty',v_return,'waste_qty',v_waste,'shortage_qty',v_short,'reason',COALESCE(v_m->>'reason',''),'material_cost',v_cost);
      v_cost:=0;
      IF v_short>0 THEN
        INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by) VALUES(v_r.product_id,'pp_shortage',-v_short,'pp_production_orders',p_order_id,'ขาดจากห่อ: '||(v_m->>'reason'),v_uid) RETURNING id INTO v_move;
        v_cost:=fn_consume_stock_fifo(v_r.product_id,v_short,v_move);
        v_shortage_cost:=v_shortage_cost+v_cost;
      END IF;
      UPDATE inv_stock_balances SET on_hand=on_hand-v_qty,updated_at=now() WHERE product_id=v_r.product_id;
      PERFORM fn_recalc_product_landed_cost(v_r.product_id);
      v_materials:=v_materials||jsonb_build_array(v_m||jsonb_build_object('shortage_cost',v_cost));
    END LOOP;
    FOR v_r IN SELECT i.product_id,round(sum(i.qty)*v_item.qty,2) planned_qty,sum(i.qty*i.unit_cost)/NULLIF(sum(i.qty),0) unit_cost,p.product_code,p.product_name FROM pp_recipe_removes i JOIN pr_products p ON p.id=i.product_id WHERE recipe_id=v_recipe GROUP BY i.product_id,p.product_code,p.product_name ORDER BY i.product_id LOOP
      SELECT x INTO v_b FROM jsonb_array_elements(v_input->'byproducts') x WHERE x->>'product_id'=v_r.product_id::text;
      IF COALESCE(v_b->>'qty','') !~ '^\d+(\.\d{1,2})?$' THEN RAISE EXCEPTION 'จำนวนสินค้าที่แยกคืนไม่ถูกต้อง'; END IF;
      v_qty:=(v_b->>'qty')::numeric; v_cost:=v_qty*COALESCE(v_r.unit_cost,0);
      IF v_r.unit_cost<0 THEN RAISE EXCEPTION 'ต้นทุนสินค้าแยกคืนต้องไม่ติดลบ'; END IF;
      v_byproduct_cost:=v_byproduct_cost+v_cost;
      IF v_qty>0 THEN
        UPDATE inv_stock_balances SET on_hand=on_hand+v_qty,updated_at=now() WHERE product_id=v_r.product_id;
        INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by,unit_cost,total_cost) VALUES(v_r.product_id,'pp_remove',v_qty,'pp_production_orders',p_order_id,'รับสินค้าแยกคืนตามจริง',v_uid,v_r.unit_cost,v_cost);
        INSERT INTO inv_stock_lots(product_id,qty_initial,qty_remaining,unit_cost,ref_type,ref_id) VALUES(v_r.product_id,v_qty,v_qty,v_r.unit_cost,'pp_production_orders',p_order_id);
        PERFORM fn_recalc_product_landed_cost(v_r.product_id);
      END IF;
      v_byproducts:=v_byproducts||jsonb_build_array(jsonb_build_object('product_id',v_r.product_id,'product_code',v_r.product_code,'product_name',v_r.product_name,'planned_qty',v_r.planned_qty,'qty',v_qty,'unit_cost',v_r.unit_cost,'total_cost',v_cost));
    END LOOP;
    v_total:=v_material_cost-v_byproduct_cost;
    IF v_total<0 THEN RAISE EXCEPTION 'มูลค่าสินค้าแยกคืนเกินต้นทุนวัตถุดิบที่ใช้จริง'; END IF;
    v_unit:=CASE WHEN v_actual>0 THEN round(v_total/v_actual,4) ELSE 0 END;
    SELECT on_hand INTO v_balance FROM inv_stock_balances WHERE product_id=v_item.product_id;
    IF v_actual>0 AND v_max IS NOT NULL AND v_balance+v_actual>v_max THEN RAISE EXCEPTION 'จำนวนรับเข้าจริงเกิน Max ที่กำหนด'; END IF;
    IF v_actual>0 THEN
      UPDATE inv_stock_balances SET on_hand=on_hand+v_actual,updated_at=now() WHERE product_id=v_item.product_id;
      INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by,unit_cost,total_cost) VALUES(v_item.product_id,'pp_produce',v_actual,'pp_production_orders',p_order_id,'รับผลผลิตจริง ปิดงานไม่ค้างยอดขาด',v_uid,v_unit,v_total);
      INSERT INTO inv_stock_lots(product_id,qty_initial,qty_remaining,unit_cost,ref_type,ref_id) VALUES(v_item.product_id,v_actual,v_actual,v_unit,'pp_production_orders',p_order_id);
      PERFORM fn_recalc_product_landed_cost(v_item.product_id);
    END IF;
    v_report:=jsonb_build_object('item_id',v_item.id,'product_code',v_item.product_code,'product_name',v_item.product_name,'planned_qty',v_item.qty,'actual_qty',v_actual,'reason_code',COALESCE(v_input->>'reason_code',''),'reason',COALESCE(v_input->>'reason',''),'materials',v_materials,'byproducts',v_byproducts,'material_cost',v_material_cost,'shortage_cost',v_shortage_cost,'byproduct_cost',v_byproduct_cost,'production_loss_cost',CASE WHEN v_actual=0 THEN v_total ELSE 0 END,'unit_cost',v_unit,'total_cost',CASE WHEN v_actual>0 THEN v_total ELSE 0 END);
    UPDATE pp_production_order_items SET actual_qty=v_actual,completion_report=v_report,unit_cost=v_unit,total_cost=CASE WHEN v_actual>0 THEN v_total ELSE 0 END WHERE id=v_item.id;
  END LOOP;
  UPDATE pp_production_orders SET status='completed',completion_short=v_any_short,completed_by=v_uid,completed_at=now() WHERE id=p_order_id;
END;
$_$;


--
-- Name: rpc_confirm_claim_req_shipping(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_confirm_claim_req_shipping(p_order_id uuid, p_recipient_name text, p_customer_address text, p_mobile_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_rec TEXT := trim(both FROM coalesce(p_recipient_name, ''));
  v_addr TEXT := trim(both FROM coalesce(p_customer_address, ''));
  v_phone TEXT := trim(both FROM coalesce(p_mobile_phone, ''));
  v_bill TEXT;
  v_bd jsonb;
BEGIN
  SELECT u.role INTO v_role FROM us_users u WHERE u.id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'sales-tr', 'sales-pump') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันที่อยู่บิลเคลม (REQ)';
  END IF;

  SELECT o.bill_no, o.billing_details INTO v_bill, v_bd
  FROM or_orders o WHERE o.id = p_order_id FOR UPDATE;

  IF v_bill IS NULL THEN
    RAISE EXCEPTION 'ไม่พบบิล';
  END IF;
  IF v_bill NOT LIKE 'REQ%' THEN
    RAISE EXCEPTION 'บิลนี้ไม่ใช่บิลเคลม (REQ)';
  END IF;

  IF length(v_rec) = 0 OR length(v_addr) = 0 OR length(v_phone) = 0 THEN
    RAISE EXCEPTION 'กรุณากรอกชื่อผู้รับ ที่อยู่จัดส่ง และเบอร์โทรให้ครบ';
  END IF;

  v_bd := coalesce(v_bd, '{}'::jsonb);
  v_bd := v_bd || jsonb_build_object('mobile_phone', v_phone);

  UPDATE or_orders SET
    recipient_name = v_rec,
    customer_address = v_addr,
    billing_details = v_bd,
    claim_shipping_confirmed_at = NOW(),
    updated_at = NOW(),
    status = CASE
      WHEN status IS DISTINCT FROM 'รอลงข้อมูล' THEN status
      WHEN trim(both FROM coalesce(channel_code, '')) = 'PUMP' THEN 'เสร็จสิ้น'::text
      ELSE 'ใบสั่งงาน'::text
    END
  WHERE id = p_order_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: rpc_confirm_machinery_stock_transfer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_confirm_machinery_stock_transfer(p_transfer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_transfer public.pr_machinery_stock_transfers%ROWTYPE;
  v_main_balance public.inv_stock_balances%ROWTYPE;
  v_machinery_balance public.pr_machinery_stock_balances%ROWTYPE;
  v_movement_id UUID;
  v_unit_cost NUMERIC := 0;
BEGIN
  IF NOT public.can_confirm_machinery_stock_transfer() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันการโอนสต๊อก';
  END IF;

  SELECT * INTO v_transfer
  FROM public.pr_machinery_stock_transfers
  WHERE id = p_transfer_id
  FOR UPDATE;

  IF v_transfer.id IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการโอน'; END IF;
  IF v_transfer.status <> 'pending' THEN RAISE EXCEPTION 'รายการนี้ถูกดำเนินการแล้ว'; END IF;

  IF v_transfer.direction = 'to_main' THEN
    SELECT * INTO v_machinery_balance
    FROM public.pr_machinery_stock_balances
    WHERE product_id = v_transfer.product_id
    FOR UPDATE;

    IF v_machinery_balance.product_id IS NULL OR v_machinery_balance.qty < v_transfer.qty THEN
      RAISE EXCEPTION 'สต๊อก Machinery ไม่เพียงพอสำหรับการคืน';
    END IF;

    v_unit_cost := COALESCE(v_machinery_balance.average_unit_cost,0);

    UPDATE public.pr_machinery_stock_balances
    SET qty = qty - v_transfer.qty, updated_at = NOW()
    WHERE product_id = v_transfer.product_id;

    INSERT INTO public.inv_stock_balances(product_id, on_hand, reserved, safety_stock)
    VALUES (v_transfer.product_id, v_transfer.qty, 0, 0)
    ON CONFLICT (product_id) DO UPDATE SET
      on_hand = COALESCE(public.inv_stock_balances.on_hand,0) + EXCLUDED.on_hand,
      updated_at = NOW();

    INSERT INTO public.inv_stock_movements(
      product_id, movement_type, qty, ref_type, ref_id, note,
      unit_cost, total_cost, created_by
    ) VALUES (
      v_transfer.product_id, 'machinery_return_in', v_transfer.qty,
      'pr_machinery_stock_transfers', v_transfer.id,
      'รับคืนจากคลังอะไหล่ Machinery ' || v_transfer.transfer_no,
      v_unit_cost, v_transfer.qty * v_unit_cost, auth.uid()
    ) RETURNING id INTO v_movement_id;

    INSERT INTO public.inv_stock_lots(
      product_id, qty_initial, qty_remaining, unit_cost,
      ref_type, ref_id, is_safety_stock
    ) VALUES (
      v_transfer.product_id, v_transfer.qty, v_transfer.qty, v_unit_cost,
      'pr_machinery_stock_transfers', v_transfer.id, FALSE
    );

    INSERT INTO public.pr_machinery_stock_moves(
      product_id, qty_delta, movement_type, unit_cost, transfer_id, note, created_by
    ) VALUES (
      v_transfer.product_id, -v_transfer.qty, 'transfer_out', v_unit_cost,
      v_transfer.id, v_transfer.transfer_no, auth.uid()
    );
  ELSE
    SELECT * INTO v_main_balance
    FROM public.inv_stock_balances
    WHERE product_id = v_transfer.product_id
    FOR UPDATE;

    IF v_main_balance.id IS NULL
       OR COALESCE(v_main_balance.on_hand,0) - COALESCE(v_main_balance.reserved,0) < v_transfer.qty THEN
      RAISE EXCEPTION 'สต๊อกหลักที่พร้อมใช้ไม่เพียงพอ';
    END IF;

    PERFORM public.fn_reconcile_sellable_lots_to_on_hand(v_transfer.product_id);
    UPDATE public.inv_stock_balances
    SET on_hand = on_hand - v_transfer.qty, updated_at = NOW()
    WHERE product_id = v_transfer.product_id;

    INSERT INTO public.inv_stock_movements(
      product_id, movement_type, qty, ref_type, ref_id, note, created_by
    ) VALUES (
      v_transfer.product_id, 'machinery_transfer_out', -v_transfer.qty,
      'pr_machinery_stock_transfers', v_transfer.id,
      'โอนเข้าคลังอะไหล่ Machinery ' || v_transfer.transfer_no, auth.uid()
    ) RETURNING id INTO v_movement_id;

    PERFORM public.fn_consume_stock_fifo(v_transfer.product_id, v_transfer.qty, v_movement_id);
    SELECT COALESCE(unit_cost,0) INTO v_unit_cost
    FROM public.inv_stock_movements
    WHERE id = v_movement_id;

    INSERT INTO public.pr_machinery_stock_balances(product_id, qty, average_unit_cost)
    VALUES (v_transfer.product_id, v_transfer.qty, v_unit_cost)
    ON CONFLICT (product_id) DO UPDATE SET
      average_unit_cost = CASE
        WHEN public.pr_machinery_stock_balances.qty + EXCLUDED.qty > 0 THEN
          ((public.pr_machinery_stock_balances.qty * public.pr_machinery_stock_balances.average_unit_cost)
            + (EXCLUDED.qty * EXCLUDED.average_unit_cost))
          / (public.pr_machinery_stock_balances.qty + EXCLUDED.qty)
        ELSE 0 END,
      qty = public.pr_machinery_stock_balances.qty + EXCLUDED.qty,
      updated_at = NOW();

    INSERT INTO public.pr_machinery_stock_moves(
      product_id, qty_delta, movement_type, unit_cost, transfer_id, note, created_by
    ) VALUES (
      v_transfer.product_id, v_transfer.qty, 'transfer_in', v_unit_cost,
      v_transfer.id, v_transfer.transfer_no, auth.uid()
    );
  END IF;

  UPDATE public.pr_machinery_stock_transfers
  SET status = 'confirmed', confirmed_by = auth.uid(), confirmed_at = NOW(),
      main_stock_movement_id = v_movement_id, updated_at = NOW()
  WHERE id = v_transfer.id;

  PERFORM public.fn_recalc_product_landed_cost(v_transfer.product_id);
END;
$$;


--
-- Name: rpc_convert_pr_to_po(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_convert_pr_to_po(p_pr_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_name text DEFAULT NULL::text, p_prices jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_po_id UUID;
  v_po_no TEXT;
  v_total NUMERIC(14,2) := 0;
  v_pr_item RECORD;
  v_price NUMERIC(12,2);
  v_subtotal NUMERIC(14,2);
BEGIN
  IF NOT EXISTS (SELECT 1 FROM inv_pr WHERE id = p_pr_id AND status = 'approved') THEN
    RAISE EXCEPTION 'PR ไม่อยู่ในสถานะอนุมัติ';
  END IF;

  IF EXISTS (SELECT 1 FROM inv_po WHERE pr_id = p_pr_id) THEN
    RAISE EXCEPTION 'PR นี้ถูกแปลงเป็น PO แล้ว';
  END IF;

  v_po_no := 'PO-' || to_char(NOW(), 'YYYYMMDD') || '-' || lpad(floor(random()*9000+1000)::text, 4, '0');

  INSERT INTO inv_po (po_no, pr_id, status, supplier_id, supplier_name, note)
  VALUES (v_po_no, p_pr_id, 'open', p_supplier_id, p_supplier_name, NULL)
  RETURNING id INTO v_po_id;

  FOR v_pr_item IN
    SELECT pri.product_id, pri.qty, pri.unit, pri.estimated_price
    FROM inv_pr_items pri
    WHERE pri.pr_id = p_pr_id
  LOOP
    v_price := NULL;
    SELECT (elem->>'unit_price')::NUMERIC INTO v_price
    FROM jsonb_array_elements(p_prices) elem
    WHERE (elem->>'product_id')::UUID = v_pr_item.product_id
    LIMIT 1;

    IF v_price IS NULL THEN
      v_price := v_pr_item.estimated_price;
    END IF;
    IF v_price IS NULL THEN
      SELECT last_price INTO v_price FROM v_product_last_price WHERE product_id = v_pr_item.product_id;
    END IF;

    v_subtotal := COALESCE(v_price, 0) * v_pr_item.qty;
    v_total := v_total + v_subtotal;

    INSERT INTO inv_po_items (po_id, product_id, qty, unit_price, subtotal, unit)
    VALUES (v_po_id, v_pr_item.product_id, v_pr_item.qty, v_price, v_subtotal, v_pr_item.unit);
  END LOOP;

  UPDATE inv_po SET total_amount = v_total, grand_total = v_total WHERE id = v_po_id;

  RETURN jsonb_build_object('id', v_po_id, 'po_no', v_po_no, 'total_amount', v_total);
END;
$$;


