--
-- Name: rpc_convert_pr_to_po(uuid, uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_convert_pr_to_po(p_pr_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_name text DEFAULT NULL::text, p_prices jsonb DEFAULT '[]'::jsonb, p_note text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  PERFORM 1 FROM inv_pr WHERE id=p_pr_id FOR UPDATE;
  result := public.rpc_convert_pr_to_po_before_cost_guard(p_pr_id,p_supplier_id,p_supplier_name,
    CASE WHEN public.erp_can_view_cost() THEN p_prices ELSE '[]'::jsonb END,p_note,auth.uid());
  RETURN CASE WHEN public.erp_can_view_cost() THEN result ELSE result-'total_amount'-'grand_total' END;
END $$;


--
-- Name: rpc_convert_pr_to_po_before_cost_guard(uuid, uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_convert_pr_to_po_before_cost_guard(p_pr_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_name text DEFAULT NULL::text, p_prices jsonb DEFAULT '[]'::jsonb, p_note text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_po_id UUID;
  v_po_no TEXT;
  v_total NUMERIC(14,2) := 0;
  v_pr_item RECORD;
  v_price NUMERIC(12,2);
  v_subtotal NUMERIC(14,2);
  v_today TEXT;
  v_seq INT;
BEGIN
  IF EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND role = 'store') THEN
    RAISE EXCEPTION 'Store role is limited to GR receiving';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM inv_pr WHERE id = p_pr_id AND status = 'approved') THEN
    RAISE EXCEPTION 'PR ไม่อยู่ในสถานะอนุมัติ';
  END IF;

  IF EXISTS (SELECT 1 FROM inv_po WHERE pr_id = p_pr_id) THEN
    RAISE EXCEPTION 'PR นี้ถูกแปลงเป็น PO แล้ว';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('po_no_gen'));

  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(po_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM inv_po
  WHERE po_no LIKE 'PO-' || v_today || '-___';

  v_po_no := 'PO-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO inv_po (po_no, pr_id, status, supplier_id, supplier_name, note, created_by)
  VALUES (v_po_no, p_pr_id, 'open', p_supplier_id, p_supplier_name, p_note, p_user_id)
  RETURNING id INTO v_po_id;

  FOR v_pr_item IN
    SELECT pri.product_id, pri.qty, pri.unit, pri.estimated_price, pri.note
    FROM inv_pr_items pri
    WHERE pri.pr_id = p_pr_id
  LOOP
    v_price := NULL;
    SELECT (elem->>'unit_price')::NUMERIC INTO v_price
    FROM jsonb_array_elements(p_prices) elem
    WHERE (elem->>'product_id')::UUID = v_pr_item.product_id
    LIMIT 1;

    IF v_price IS NULL THEN
      v_price := v_pr_item.estimated_price;
    END IF;
    IF v_price IS NULL THEN
      SELECT last_price INTO v_price FROM v_product_last_price WHERE product_id = v_pr_item.product_id;
    END IF;

    v_subtotal := COALESCE(v_price, 0) * v_pr_item.qty;
    v_total := v_total + v_subtotal;

    INSERT INTO inv_po_items (po_id, product_id, qty, unit_price, subtotal, unit, note)
    VALUES (v_po_id, v_pr_item.product_id, v_pr_item.qty, v_price, v_subtotal, v_pr_item.unit, v_pr_item.note);
  END LOOP;

  UPDATE inv_po SET total_amount = v_total, grand_total = v_total WHERE id = v_po_id;

  RETURN jsonb_build_object('id', v_po_id, 'po_no', v_po_no, 'total_amount', v_total);
END;
$$;


--
-- Name: rpc_convert_prebill_to_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_convert_prebill_to_order(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_doc public.or_prebill_documents;
  v_bill_no TEXT;
  v_order_id UUID;
  v_period TEXT := to_char(timezone('Asia/Bangkok', now()), 'YYMM');
  v_last INTEGER;
  v_promotion_names TEXT;
  v_bill_creator TEXT;
  v_billing_details JSONB;
BEGIN
  SELECT * INTO v_doc FROM public.or_prebill_documents WHERE id = p_document_id FOR UPDATE;
  IF v_doc.id IS NULL OR NOT public.can_manage_prebill_document(v_doc.owner_id) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์';
  END IF;
  IF v_doc.converted_order_id IS NOT NULL OR v_doc.status = 'converted' THEN
    RAISE EXCEPTION 'เอกสารนี้เปิดบิลแล้ว';
  END IF;
  IF v_doc.valid_until < timezone('Asia/Bangkok', now())::DATE THEN
    RAISE EXCEPTION 'เอกสารหมดอายุ กรุณาสร้างเอกสารใหม่';
  END IF;
  IF v_doc.status NOT IN ('active', 'approved') THEN
    RAISE EXCEPTION 'สถานะเอกสารยังไม่พร้อมเปิดบิล';
  END IF;

  SELECT COALESCE(NULLIF(btrim(username), ''), NULLIF(btrim(email), ''), 'unknown')
  INTO v_bill_creator FROM public.us_users WHERE id = auth.uid();
  v_billing_details := COALESCE(v_doc.billing_details, '{}'::jsonb);
  IF NULLIF(btrim(v_doc.customer_phone), '') IS NOT NULL THEN
    v_billing_details := v_billing_details || jsonb_build_object('mobile_phone', btrim(v_doc.customer_phone));
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(v_doc.channel_code || v_period));
  SELECT COALESCE(max(CASE WHEN right(bill_no, 4) ~ '^[0-9]{4}$'
    THEN right(bill_no, 4)::INTEGER END), 0) INTO v_last
  FROM public.or_orders WHERE bill_no LIKE v_doc.channel_code || v_period || '____';
  v_bill_no := v_doc.channel_code || v_period || lpad((v_last + 1)::TEXT, 4, '0');
  SELECT string_agg(x->>'name', ', ') INTO v_promotion_names
  FROM jsonb_array_elements(v_doc.promotion_snapshot) x;

  PERFORM set_config('app.discount_prebill_conversion',v_doc.id::text,true);
  INSERT INTO public.or_orders(
    channel_code, bill_no, status, price, shipping_cost, discount, total_amount,
    payment_method, promotion, customer_name, customer_address, recipient_name, admin_user,
    entry_date, billing_details, source_prebill_document_id, prebill_price_locked,
    requires_confirm_design, source_prebill_document_type, source_prebill_owner_name
  ) VALUES (
    v_doc.channel_code, v_bill_no, 'รอลงข้อมูล', v_doc.subtotal, v_doc.shipping_cost,
    v_doc.promotion_discount + v_doc.special_discount, v_doc.total_amount,
    v_doc.payment_method, v_promotion_names, v_doc.customer_name, COALESCE(v_doc.customer_address, ''),
    v_doc.recipient_name, v_bill_creator, timezone('Asia/Bangkok', now())::DATE, v_billing_details,
    v_doc.id, true, false, v_doc.document_type, v_doc.owner_name
  ) RETURNING id INTO v_order_id;

  INSERT INTO public.or_order_items(
    id, order_id, item_uid, product_id, product_name, quantity, unit_price,
    ink_color, product_type, cartoon_pattern, line_pattern, font,
    line_1, line_2, line_3, no_name_line, is_free, notes,
    file_attachment, attachment_name, is_detail_row, parent_item_id
  )
  SELECT i.id, v_order_id, v_bill_no || '-' || row_number() OVER (ORDER BY i.sort_order, i.id),
    i.product_id, i.product_name, i.quantity, CASE WHEN i.is_free THEN 0 ELSE i.unit_price END,
    i.ink_color, i.product_type, i.cartoon_pattern, i.line_pattern, i.font,
    i.line_1, i.line_2, i.line_3, i.no_name_line, i.is_free, i.notes,
    i.file_attachment, i.attachment_name, i.is_detail_row, i.parent_item_id
  FROM public.or_prebill_items i WHERE i.document_id = v_doc.id
  ORDER BY i.sort_order, i.id;

  INSERT INTO public.or_order_promotions(
    order_id, promotion_id, promotion_name_snapshot, promotion_version,
    rule_snapshot, application_count, selected_by
  )
  SELECT v_order_id, p.id,
    COALESCE(NULLIF(snapshot.value->>'name', ''), p.name),
    COALESCE((snapshot.value->>'version')::INTEGER, p.version, 1),
    COALESCE(snapshot.value, to_jsonb(p)),
    GREATEST(COALESCE((snapshot.value->'evaluation'->>'application_count')::INTEGER, 1), 1),
    v_bill_creator
  FROM unnest(v_doc.promotion_ids) AS selected(promotion_id)
  JOIN public.promotion p ON p.id = selected.promotion_id
  LEFT JOIN LATERAL (
    SELECT value FROM jsonb_array_elements(v_doc.promotion_snapshot) value
    WHERE value->>'id' = selected.promotion_id::TEXT LIMIT 1
  ) snapshot ON true
  ON CONFLICT (order_id, promotion_id) DO NOTHING;

  UPDATE public.or_prebill_documents
  SET status = 'converted', converted_order_id = v_order_id,
      converted_at = now(), updated_at = now()
  WHERE id = v_doc.id;

  PERFORM set_config('app.discount_prebill_conversion','',true);
  RETURN jsonb_build_object('order_id', v_order_id, 'bill_no', v_bill_no);
END;
$_$;


--
-- Name: rpc_convert_sample_to_product(uuid, uuid, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_convert_sample_to_product(p_sample_id uuid, p_item_id uuid, p_product_code text, p_product_name text, p_product_name_cn text DEFAULT NULL::text, p_product_type text DEFAULT 'FG'::text, p_product_category text DEFAULT NULL::text, p_seller_name text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid UUID := COALESCE(auth.uid(), p_user_id);
  v_product_id UUID;
  v_all_converted BOOLEAN;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'manager', 'store', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แปลง Sample เป็นสินค้า (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  INSERT INTO pr_products (product_code, product_name, product_name_cn, product_type, product_category, seller_name, is_active)
  VALUES (p_product_code, p_product_name, p_product_name_cn, p_product_type, p_product_category, p_seller_name, true)
  RETURNING id INTO v_product_id;

  UPDATE inv_sample_items
  SET converted_product_id = v_product_id
  WHERE id = p_item_id AND sample_id = p_sample_id;

  SELECT bool_and(converted_product_id IS NOT NULL)
  INTO v_all_converted
  FROM inv_sample_items
  WHERE sample_id = p_sample_id;

  IF v_all_converted THEN
    UPDATE inv_samples SET status = 'converted' WHERE id = p_sample_id;
  END IF;

  RETURN v_product_id;
END;
$$;


--
-- Name: rpc_copy_machinery_checklist_settings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_copy_machinery_checklist_settings(p_source_machine_id uuid, p_target_machine_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_checklist_count integer := 0;
  v_access_count integer := 0;
BEGIN
  IF NOT public.check_user_role(
    auth.uid(),
    ARRAY['superadmin', 'admin', 'production', 'technician']
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์คัดลอกการตั้งค่า Checklist เครื่องจักร';
  END IF;

  IF p_source_machine_id = p_target_machine_id THEN
    RAISE EXCEPTION 'เครื่องต้นฉบับและเครื่องปลายทางต้องไม่ใช่เครื่องเดียวกัน';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.pr_machinery_machines WHERE id = p_source_machine_id) THEN
    RAISE EXCEPTION 'ไม่พบเครื่องต้นฉบับ';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.pr_machinery_machines WHERE id = p_target_machine_id) THEN
    RAISE EXCEPTION 'ไม่พบเครื่องปลายทาง';
  END IF;

  INSERT INTO public.pr_machinery_checklist_items (
    machine_id,
    label,
    description,
    input_type,
    min_value,
    max_value,
    unit,
    requires_photo,
    is_required,
    frequency,
    sort_order,
    is_active
  )
  SELECT
    p_target_machine_id,
    source.label,
    source.description,
    source.input_type,
    source.min_value,
    source.max_value,
    source.unit,
    source.requires_photo,
    source.is_required,
    source.frequency,
    source.sort_order,
    true
  FROM public.pr_machinery_checklist_items source
  WHERE source.machine_id = p_source_machine_id
    AND source.is_active = true
    AND NOT EXISTS (
      SELECT 1
      FROM public.pr_machinery_checklist_items target
      WHERE target.machine_id = p_target_machine_id
        AND target.is_active = true
        AND target.sort_order = source.sort_order
        AND target.label = source.label
    );

  GET DIAGNOSTICS v_checklist_count = ROW_COUNT;

  INSERT INTO public.pr_machinery_inspection_machine_users (
    machine_id,
    user_id,
    created_by
  )
  SELECT
    p_target_machine_id,
    source.user_id,
    auth.uid()
  FROM public.pr_machinery_inspection_machine_users source
  WHERE source.machine_id = p_source_machine_id
  ON CONFLICT (machine_id, user_id) DO NOTHING;

  GET DIAGNOSTICS v_access_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'checklist_count', v_checklist_count,
    'access_count', v_access_count
  );
END;
$$;


--
-- Name: rpc_correct_po_unit_costs(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_correct_po_unit_costs(p_po_id uuid, p_reason text, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_po public.inv_po%ROWTYPE;
  v_item jsonb;
  v_po_item public.inv_po_items%ROWTYPE;
  v_product record;
  v_correction_id uuid;
  v_correction_no text;
  v_new_price numeric;
  v_old_price numeric;
  v_price_delta numeric;
  v_qty_received numeric;
  v_qty_remaining numeric;
  v_qty_consumed numeric;
  v_inventory_delta numeric;
  v_consumed_delta numeric;
  v_total_inventory_delta numeric := 0;
  v_total_consumed_delta numeric := 0;
  v_new_total numeric;
  v_new_grand_total numeric;
  v_changed_count integer := 0;
  v_seen_item_ids uuid[] := ARRAY[]::uuid[];
  v_impacts jsonb := '[]'::jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT u.role INTO v_role
    FROM public.us_users u
    WHERE u.id = v_uid AND u.is_active IS TRUE;

    IF v_role IS DISTINCT FROM 'superadmin' THEN
      RAISE EXCEPTION 'Only an active superadmin can correct a historical PO cost';
    END IF;
  END IF;

  IF p_reason IS NULL OR char_length(btrim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'A correction reason of at least 5 characters is required';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'At least one PO item is required';
  END IF;

  SELECT * INTO v_po FROM public.inv_po WHERE id = p_po_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PO not found'; END IF;
  IF v_po.status NOT IN ('open', 'ordered', 'partial', 'received', 'closed') THEN
    RAISE EXCEPTION 'PO status % cannot be cost-corrected', v_po.status;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.inv_po_items
    WHERE po_id = p_po_id
    GROUP BY product_id HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'This PO contains duplicate product rows and requires data review before cost correction';
  END IF;

  INSERT INTO public.inv_po_cost_corrections (
    po_id, po_no_snapshot, reason, old_total_amount, new_total_amount,
    old_grand_total, new_grand_total, corrected_by
  ) VALUES (
    v_po.id, v_po.po_no, btrim(p_reason), COALESCE(v_po.total_amount, 0), COALESCE(v_po.total_amount, 0),
    COALESCE(v_po.grand_total, 0), COALESCE(v_po.grand_total, 0), v_uid
  ) RETURNING id, correction_no INTO v_correction_id, v_correction_no;

  PERFORM set_config('app.allow_historical_po_cost_correction', 'on', true);

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    IF NULLIF(v_item->>'item_id', '') IS NULL OR NULLIF(v_item->>'new_unit_price', '') IS NULL THEN
      RAISE EXCEPTION 'Every correction item requires item_id and new_unit_price';
    END IF;
    IF (v_item->>'item_id')::uuid = ANY(v_seen_item_ids) THEN
      RAISE EXCEPTION 'Duplicate PO item in correction request';
    END IF;
    v_seen_item_ids := array_append(v_seen_item_ids, (v_item->>'item_id')::uuid);

    v_new_price := (v_item->>'new_unit_price')::numeric;
    IF v_new_price < 0 THEN RAISE EXCEPTION 'Unit price cannot be negative'; END IF;

    SELECT * INTO v_po_item
    FROM public.inv_po_items
    WHERE id = (v_item->>'item_id')::uuid AND po_id = p_po_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PO item does not belong to this PO'; END IF;
    v_old_price := COALESCE(v_po_item.unit_price, 0);
    IF v_new_price = v_old_price THEN CONTINUE; END IF;
    v_price_delta := v_new_price - v_old_price;

    SELECT p.product_code, p.product_name
      INTO v_product
    FROM public.pr_products p WHERE p.id = v_po_item.product_id;

    SELECT COALESCE(SUM(gi.qty_received), 0)
      INTO v_qty_received
    FROM public.inv_gr g
    JOIN public.inv_gr_items gi ON gi.gr_id = g.id
    WHERE g.po_id = p_po_id AND gi.product_id = v_po_item.product_id;

    SELECT COALESCE(SUM(sl.qty_remaining), 0)
      INTO v_qty_remaining
    FROM public.inv_stock_lots sl
    JOIN public.inv_gr g ON g.id = sl.ref_id AND sl.ref_type = 'inv_gr'
    WHERE g.po_id = p_po_id AND sl.product_id = v_po_item.product_id;

    v_qty_consumed := GREATEST(v_qty_received - v_qty_remaining, 0);
    v_inventory_delta := round(v_price_delta * v_qty_remaining, 2);
    v_consumed_delta := round(v_price_delta * v_qty_consumed, 2);

    UPDATE public.inv_po_items
    SET unit_price = v_new_price,
        subtotal = round(COALESCE(qty, 0) * v_new_price, 2)
    WHERE id = v_po_item.id;

    IF v_po.pr_id IS NOT NULL THEN
      UPDATE public.inv_pr_items
      SET estimated_price = v_new_price
      WHERE pr_id = v_po.pr_id AND product_id = v_po_item.product_id;
    END IF;

    -- Shipping is unchanged, so applying only the purchase-price delta preserves
    -- the existing domestic/international shipping portion of each GR lot.
    UPDATE public.inv_stock_lots sl
    SET unit_cost = GREATEST(0, COALESCE(sl.unit_cost, 0) + v_price_delta)
    FROM public.inv_gr g
    WHERE sl.ref_type = 'inv_gr' AND sl.ref_id = g.id
      AND g.po_id = p_po_id AND sl.product_id = v_po_item.product_id;

    UPDATE public.inv_stock_movements sm
    SET unit_cost = GREATEST(0, COALESCE(sm.unit_cost, 0) + v_price_delta),
        total_cost = round(ABS(sm.qty) * GREATEST(0, COALESCE(sm.unit_cost, 0) + v_price_delta), 2)
    FROM public.inv_gr g
    WHERE sm.ref_type = 'inv_gr' AND sm.ref_id = g.id
      AND sm.movement_type = 'gr' AND sm.product_id = v_po_item.product_id
      AND g.po_id = p_po_id;

    PERFORM public.fn_recalc_product_landed_cost(v_po_item.product_id);

    INSERT INTO public.inv_po_cost_correction_items (
      correction_id, po_item_id, product_id, product_code_snapshot, product_name_snapshot,
      old_unit_price, new_unit_price, qty_ordered, qty_received, qty_remaining, qty_consumed,
      inventory_value_delta, consumed_cost_delta
    ) VALUES (
      v_correction_id, v_po_item.id, v_po_item.product_id, v_product.product_code, v_product.product_name,
      v_old_price, v_new_price, COALESCE(v_po_item.qty, 0), v_qty_received, v_qty_remaining, v_qty_consumed,
      v_inventory_delta, v_consumed_delta
    );

    v_changed_count := v_changed_count + 1;
    v_total_inventory_delta := v_total_inventory_delta + v_inventory_delta;
    v_total_consumed_delta := v_total_consumed_delta + v_consumed_delta;
    v_impacts := v_impacts || jsonb_build_array(jsonb_build_object(
      'item_id', v_po_item.id,
      'product_code', v_product.product_code,
      'old_unit_price', v_old_price,
      'new_unit_price', v_new_price,
      'qty_received', v_qty_received,
      'qty_remaining', v_qty_remaining,
      'qty_consumed', v_qty_consumed,
      'inventory_value_delta', v_inventory_delta,
      'consumed_cost_delta', v_consumed_delta
    ));
  END LOOP;

  IF v_changed_count = 0 THEN
    RAISE EXCEPTION 'No unit price was changed';
  END IF;

  SELECT COALESCE(SUM(COALESCE(subtotal, qty * COALESCE(unit_price, 0))), 0)
    INTO v_new_total
  FROM public.inv_po_items WHERE po_id = p_po_id;
  v_new_grand_total := v_new_total + COALESCE(v_po.intl_shipping_cost_thb, 0);

  UPDATE public.inv_po
  SET total_amount = v_new_total, grand_total = v_new_grand_total, updated_at = now()
  WHERE id = p_po_id;

  UPDATE public.inv_po_cost_corrections
  SET new_total_amount = v_new_total,
      new_grand_total = v_new_grand_total,
      inventory_value_delta = v_total_inventory_delta,
      consumed_cost_delta = v_total_consumed_delta
  WHERE id = v_correction_id;

  RETURN jsonb_build_object(
    'success', true,
    'correction_id', v_correction_id,
    'correction_no', v_correction_no,
    'changed_count', v_changed_count,
    'new_total_amount', v_new_total,
    'new_grand_total', v_new_grand_total,
    'inventory_value_delta', v_total_inventory_delta,
    'consumed_cost_delta', v_total_consumed_delta,
    'items', v_impacts
  );
END;
$$;


--
-- Name: rpc_create_inventory_adjustment(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_inventory_adjustment(p_adjustment_type text, p_reason_code text, p_note text, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_role text;
  v_adjustment_id uuid;
  v_adjust_no text;
  v_today text;
  v_seq integer;
  v_input record;
  v_product record;
  v_current_on_hand numeric;
  v_current_safety numeric;
  v_target_on_hand numeric;
  v_target_safety numeric;
  v_qty_delta numeric;
  v_item_count integer := 0;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT u.role INTO v_role
    FROM public.us_users u
    WHERE u.id = auth.uid() AND u.is_active IS TRUE;
    IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'account', 'store') THEN
      RAISE EXCEPTION 'Not authorized to create an inventory adjustment';
    END IF;
  END IF;

  IF p_adjustment_type IS NULL OR p_adjustment_type NOT IN (
    'audit_adjustment', 'stocktake_reconcile', 'safety_reclass'
  ) THEN
    RAISE EXCEPTION 'Invalid inventory adjustment type';
  END IF;
  IF btrim(COALESCE(p_note, '')) = '' THEN
    RAISE EXCEPTION 'Inventory adjustment note is required';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Inventory adjustment must contain at least one item';
  END IF;
  IF jsonb_array_length(p_items) > 5000 THEN
    RAISE EXCEPTION 'Inventory adjustment contains too many items';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_items) AS x(product_id uuid, target_on_hand numeric, target_safety numeric)
    GROUP BY x.product_id
    HAVING x.product_id IS NULL OR count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Inventory adjustment contains an invalid or duplicate product';
  END IF;

  -- A derived roll FG is never a stocktake input. Its target is generated from RM.
  IF p_adjustment_type = 'stocktake_reconcile' AND EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_items) AS x(product_id uuid, target_on_hand numeric, target_safety numeric)
    JOIN public.roll_material_configs c ON c.fg_product_id = x.product_id
  ) THEN
    RAISE EXCEPTION 'Derived roll FG cannot be entered in a stocktake; enter its mapped RM instead';
  END IF;

  -- One RM mapped to several FG formulas is ambiguous and must be fixed first.
  IF p_adjustment_type = 'stocktake_reconcile' AND EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_items) AS x(product_id uuid, target_on_hand numeric, target_safety numeric)
    JOIN public.roll_material_config_rms m ON m.rm_product_id = x.product_id
    GROUP BY x.product_id
    HAVING count(DISTINCT m.config_id) > 1 AND NOT (
    count(DISTINCT (SELECT c.pairing_group_id FROM public.roll_material_configs c WHERE c.id = m.config_id)) = 1
    AND bool_and((SELECT c.pairing_group_id IS NOT NULL FROM public.roll_material_configs c WHERE c.id = m.config_id))
    AND count(DISTINCT (SELECT c.sheets_per_roll FROM public.roll_material_configs c WHERE c.id = m.config_id)) = 1
    AND bool_and((SELECT c.sheets_per_roll > 0 FROM public.roll_material_configs c WHERE c.id = m.config_id))
    AND bool_and((SELECT count(*) = 1 FROM public.roll_material_config_rms links WHERE links.config_id = m.config_id))
  )
  ) THEN
    RAISE EXCEPTION 'A roll RM is mapped to more than one FG formula';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('inventory_adjustment_no_gen'));
  v_today := to_char(clock_timestamp() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');
  SELECT COALESCE(MAX(split_part(a.adjust_no, '-', 3)::integer), 0) + 1
  INTO v_seq
  FROM public.inv_adjustments a
  WHERE a.adjust_no ~ ('^ADJ-' || v_today || '-[0-9]+$');
  v_adjust_no := 'ADJ-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO public.inv_adjustments (
    adjust_no, status, adjustment_type, reason_code, created_by, note
  ) VALUES (
    v_adjust_no, 'pending', p_adjustment_type,
    NULLIF(btrim(COALESCE(p_reason_code, '')), ''), auth.uid(), btrim(p_note)
  ) RETURNING id INTO v_adjustment_id;

  PERFORM 1
  FROM public.inv_stock_balances b
  JOIN (
    SELECT x.product_id
    FROM jsonb_to_recordset(p_items) AS x(product_id uuid, target_on_hand numeric, target_safety numeric)
  ) requested ON requested.product_id = b.product_id
  ORDER BY b.product_id
  FOR UPDATE OF b;

  FOR v_input IN
    SELECT x.product_id, x.target_on_hand, x.target_safety
    FROM jsonb_to_recordset(p_items) AS x(
      product_id uuid, target_on_hand numeric, target_safety numeric
    )
    ORDER BY x.product_id
  LOOP
    SELECT p.id, p.product_code, p.product_name INTO v_product
    FROM public.pr_products p
    WHERE p.id = v_input.product_id AND p.is_active IS TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Product not found or inactive: %', v_input.product_id;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.wh_sub_wms_map_spares s
      WHERE s.product_id = v_input.product_id
    ) THEN
      RAISE EXCEPTION 'Product % must be adjusted through its linked production SKU', v_product.product_code;
    END IF;

    SELECT COALESCE(b.on_hand, 0), COALESCE(b.safety_stock, 0)
    INTO v_current_on_hand, v_current_safety
    FROM public.inv_stock_balances b
    WHERE b.product_id = v_input.product_id;
    IF NOT FOUND THEN
      v_current_on_hand := 0;
      v_current_safety := 0;
    END IF;

    v_target_safety := COALESCE(v_input.target_safety, v_current_safety);
    IF p_adjustment_type = 'safety_reclass' THEN
      v_target_on_hand := v_current_on_hand + v_current_safety - v_target_safety;
      v_qty_delta := 0;
    ELSE
      v_target_on_hand := v_input.target_on_hand;
      v_qty_delta := v_target_on_hand - v_current_on_hand;
    END IF;

    IF v_target_on_hand IS NULL OR v_target_safety IS NULL
       OR v_target_on_hand < 0 OR v_target_safety < 0 THEN
      RAISE EXCEPTION 'Invalid target quantity for product %', v_product.product_code;
    END IF;
    IF p_adjustment_type <> 'stocktake_reconcile'
       AND v_target_on_hand = v_current_on_hand AND v_target_safety = v_current_safety THEN
      CONTINUE;
    END IF;

    INSERT INTO public.inv_adjustment_items (
      adjustment_id, product_id, qty_delta, new_safety_stock, new_order_point,
      before_on_hand, after_on_hand, before_safety_stock, after_safety_stock,
      before_total_qty, after_total_qty, is_system_generated
    ) VALUES (
      v_adjustment_id, v_input.product_id, v_qty_delta, v_target_safety, NULL,
      v_current_on_hand, v_target_on_hand, v_current_safety, v_target_safety,
      v_current_on_hand + v_current_safety,
      v_target_on_hand + v_target_safety,
      false
    );
    v_item_count := v_item_count + 1;
  END LOOP;

  IF v_item_count = 0 THEN
    RAISE EXCEPTION 'Inventory adjustment has no changed items';
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'adjustment_id', v_adjustment_id,
    'adjust_no', v_adjust_no, 'status', 'pending', 'item_count', v_item_count
  );
END;
$_$;


--
-- Name: FUNCTION rpc_create_inventory_adjustment(p_adjustment_type text, p_reason_code text, p_note text, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_create_inventory_adjustment(p_adjustment_type text, p_reason_code text, p_note text, p_items jsonb) IS 'Creates inventory adjustments. Allowed roles: superadmin, admin, manager, account and store.';


--
-- Name: rpc_create_machinery_pr(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_machinery_pr(p_items jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_pr_id uuid;
  v_pr_no text;
  v_item jsonb;
  v_last_price numeric(12,2);
  v_today text;
  v_seq int;
  v_product_id uuid;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'production', 'production_mb', 'manager', 'technician') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างคำขอซื้อ Machinery';
  END IF;
  IF jsonb_array_length(COALESCE(p_items, '[]'::jsonb)) = 0 THEN
    RAISE EXCEPTION 'กรุณาเลือกรายการสินค้า';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('pr_no_gen'));
  v_today := to_char(now() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');
  SELECT COALESCE(MAX(CAST(split_part(pr_no, '-', 3) AS integer)), 0) + 1 INTO v_seq
  FROM inv_pr WHERE pr_no LIKE 'PR-' || v_today || '-___';
  v_pr_no := 'PR-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO inv_pr(pr_no, status, requested_by, requested_at, note, pr_type)
  VALUES(v_pr_no, 'pending', auth.uid(), now(), p_note, 'machinery') RETURNING id INTO v_pr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    IF NOT EXISTS (SELECT 1 FROM pr_machinery_purchase_products WHERE product_id = v_product_id AND enabled) THEN
      RAISE EXCEPTION 'สินค้านี้ไม่ได้เปิดให้ขอซื้อใน Machinery';
    END IF;
    SELECT last_price INTO v_last_price FROM v_product_last_price WHERE product_id = v_product_id;
    INSERT INTO inv_pr_items(pr_id, product_id, qty, unit, estimated_price, last_purchase_price, note)
    VALUES(v_pr_id, v_product_id, (v_item->>'qty')::numeric, v_item->>'unit', v_last_price, v_last_price, v_item->>'note');
  END LOOP;
  RETURN jsonb_build_object('id', v_pr_id, 'pr_no', v_pr_no);
END;
$$;


--
-- Name: rpc_create_pr(jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_pr(p_items jsonb, p_note text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pr_id UUID;
  v_pr_no TEXT;
  v_item JSONB;
  v_last_price NUMERIC(12,2);
  v_today TEXT;
  v_seq INT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('pr_no_gen'));

  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(pr_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM inv_pr
  WHERE pr_no LIKE 'PR-' || v_today || '-___';

  v_pr_no := 'PR-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO inv_pr (pr_no, status, requested_by, requested_at, note)
  VALUES (v_pr_no, 'pending', p_user_id, NOW(), p_note)
  RETURNING id INTO v_pr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT last_price INTO v_last_price
    FROM v_product_last_price
    WHERE product_id = (v_item->>'product_id')::UUID;

    INSERT INTO inv_pr_items (pr_id, product_id, qty, unit, estimated_price, last_purchase_price, note)
    VALUES (
      v_pr_id,
      (v_item->>'product_id')::UUID,
      (v_item->>'qty')::NUMERIC,
      v_item->>'unit',
      (v_item->>'estimated_price')::NUMERIC,
      COALESCE(v_last_price, NULL),
      v_item->>'note'
    );
  END LOOP;

  RETURN jsonb_build_object('id', v_pr_id, 'pr_no', v_pr_no);
END;
$$;


--
-- Name: rpc_create_pr(jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_pr(p_items jsonb, p_note text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_pr_type text DEFAULT 'normal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pr_id UUID;
  v_pr_no TEXT;
  v_item JSONB;
  v_last_price NUMERIC(12,2);
  v_today TEXT;
  v_seq INT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('pr_no_gen'));

  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(pr_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM inv_pr
  WHERE pr_no LIKE 'PR-' || v_today || '-___';

  v_pr_no := 'PR-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO inv_pr (pr_no, status, requested_by, requested_at, note, pr_type)
  VALUES (v_pr_no, 'pending', p_user_id, NOW(), p_note, COALESCE(p_pr_type, 'normal'))
  RETURNING id INTO v_pr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT last_price INTO v_last_price
    FROM v_product_last_price
    WHERE product_id = (v_item->>'product_id')::UUID;

    INSERT INTO inv_pr_items (pr_id, product_id, qty, unit, estimated_price, last_purchase_price, note)
    VALUES (
      v_pr_id,
      (v_item->>'product_id')::UUID,
      (v_item->>'qty')::NUMERIC,
      v_item->>'unit',
      (v_item->>'estimated_price')::NUMERIC,
      COALESCE(v_last_price, NULL),
      v_item->>'note'
    );
  END LOOP;

  RETURN jsonb_build_object('id', v_pr_id, 'pr_no', v_pr_no);
END;
$$;


--
-- Name: rpc_create_pr(jsonb, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_pr(p_items jsonb, p_note text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_pr_type text DEFAULT 'normal'::text, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid UUID := COALESCE(auth.uid(), p_user_id);
  v_pr_id UUID;
  v_pr_no TEXT;
  v_item JSONB;
  v_last_price NUMERIC(12,2);
  v_today TEXT;
  v_seq INT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้าง PR (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('pr_no_gen'));
  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(pr_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM inv_pr
  WHERE pr_no LIKE 'PR-' || v_today || '-___';

  v_pr_no := 'PR-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO inv_pr (pr_no, status, requested_by, requested_at, note, pr_type, supplier_id, supplier_name)
  VALUES (v_pr_no, 'pending', v_uid, NOW(), p_note, COALESCE(p_pr_type, 'normal'), p_supplier_id, p_supplier_name)
  RETURNING id INTO v_pr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT last_price INTO v_last_price
    FROM v_product_last_price
    WHERE product_id = (v_item->>'product_id')::UUID;

    INSERT INTO inv_pr_items (pr_id, product_id, qty, unit, estimated_price, last_purchase_price, note)
    VALUES (
      v_pr_id,
      (v_item->>'product_id')::UUID,
      (v_item->>'qty')::NUMERIC,
      v_item->>'unit',
      v_last_price,
      v_last_price,
      v_item->>'note'
    );
  END LOOP;

  RETURN jsonb_build_object('id', v_pr_id, 'pr_no', v_pr_no);
END;
$$;


--
-- Name: rpc_create_pr_seller(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_pr_seller(p_name text, p_name_cn text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_id UUID;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เพิ่มผู้ขาย (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF COALESCE(trim(p_name), '') = '' THEN
    RAISE EXCEPTION 'กรุณาระบุชื่อผู้ขาย';
  END IF;

  INSERT INTO pr_sellers (name, name_cn, is_active)
  VALUES (trim(p_name), COALESCE(trim(p_name_cn), ''), true)
  ON CONFLICT (name) DO UPDATE
    SET name_cn = EXCLUDED.name_cn,
        is_active = true,
        updated_at = NOW()
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'id', v_id,
    'name', trim(p_name),
    'name_cn', COALESCE(trim(p_name_cn), '')
  );
END;
$$;


--
-- Name: rpc_create_production_order(text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_production_order(p_title text, p_note text, p_items jsonb, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role     TEXT;
  v_uid      UUID := auth.uid();
  v_order_id UUID;
  v_doc_no   TEXT;
  v_item     JSONB;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'store', 'production', 'packing_staff') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างใบผลิต (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  v_doc_no := rpc_generate_pp_doc_no();

  INSERT INTO pp_production_orders (doc_no, title, status, note, created_by)
  VALUES (v_doc_no, p_title, 'open', p_note, v_uid)
  RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO pp_production_order_items (order_id, product_id, qty)
    VALUES (
      v_order_id,
      (v_item->>'product_id')::UUID,
      (v_item->>'qty')::NUMERIC
    );
  END LOOP;

  RETURN jsonb_build_object('id', v_order_id, 'doc_no', v_doc_no);
END;
$$;


--
-- Name: rpc_create_receiving_case(uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_receiving_case(p_po_id uuid, p_method text, p_reason text, p_items jsonb, p_assigned_to uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_item jsonb; v_po_item inv_po_items%ROWTYPE; v_reserved numeric; v_qty numeric;
BEGIN
  IF NOT public.erp_can_manage_receiving_cases() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการยอดค้างรับ'; END IF;
  IF p_method IS NULL OR p_method NOT IN ('refund','cancel_unpaid','vendor_refused','dispute') OR nullif(btrim(p_reason),'') IS NULL THEN
    RAISE EXCEPTION 'กรุณาระบุวิธีจัดการและเหตุผล';
  END IF;
  PERFORM 1 FROM inv_po WHERE id = p_po_id AND status IN ('ordered','partial') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PO ไม่อยู่ในสถานะที่จัดการยอดค้างรับได้'; END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'กรุณาเลือกรายการ'; END IF;
  IF p_assigned_to IS NOT NULL AND NOT EXISTS (SELECT 1 FROM us_users WHERE id = p_assigned_to) THEN RAISE EXCEPTION 'ไม่พบผู้รับผิดชอบ'; END IF;
  INSERT INTO inv_receiving_cases(po_id,method,status,reason,assigned_to,created_by)
    VALUES(p_po_id,p_method,CASE WHEN p_method = 'dispute' THEN 'dispute' ELSE 'pending' END,btrim(p_reason),coalesce(p_assigned_to,auth.uid()),auth.uid()) RETURNING id INTO v_id;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    SELECT * INTO v_po_item FROM inv_po_items WHERE id = (v_item->>'po_item_id')::uuid AND po_id = p_po_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'รายการไม่อยู่ใน PO'; END IF;
    v_qty := (v_item->>'qty')::numeric;
    IF v_qty IS NULL OR v_qty <= 0 OR v_qty <> round(v_qty,2) OR v_qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'จำนวนไม่ถูกต้อง'; END IF;
    SELECT coalesce(sum(i.qty),0) INTO v_reserved FROM inv_receiving_case_items i JOIN inv_receiving_cases c ON c.id=i.case_id
      WHERE i.po_item_id=v_po_item.id AND c.status IN ('pending','dispute');
    IF v_qty > v_po_item.qty - coalesce(v_po_item.qty_received_total,0) - coalesce(v_po_item.resolution_qty,0) - v_reserved THEN
      RAISE EXCEPTION 'จำนวนเกินยอดค้างรับที่ยังไม่มีคำขอ กรุณาโหลดข้อมูลใหม่';
    END IF;
    INSERT INTO inv_receiving_case_items(case_id,po_item_id,qty) VALUES(v_id,v_po_item.id,v_qty);
  END LOOP;
  INSERT INTO inv_receiving_case_events(case_id,action,note,actor_id) VALUES(v_id,'created',p_method,auth.uid());
  RETURN v_id;
END $$;


--
-- Name: rpc_create_roll_pairing_group(uuid, uuid[], numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_roll_pairing_group(p_rm_id uuid, p_fg_ids uuid[], p_sheets numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_group uuid := gen_random_uuid(); v_fg uuid; v_config uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND is_active IS TRUE AND role IN ('superadmin','admin','store')) THEN
    RAISE EXCEPTION 'Not authorized to manage roll pairings';
  END IF;
  IF p_sheets IS NULL OR p_sheets <= 0 OR p_sheets::text IN ('NaN','Infinity','-Infinity') OR p_sheets <> round(p_sheets,2) OR p_sheets >= 10000000000 THEN
    RAISE EXCEPTION 'Invalid sheets per roll';
  END IF;
  IF coalesce(cardinality(p_fg_ids),0) = 0 OR cardinality(p_fg_ids) <> (SELECT count(DISTINCT id) FROM unnest(p_fg_ids) id) THEN
    RAISE EXCEPTION 'Select distinct FG products';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('roll_pairing_groups'));
  PERFORM 1 FROM public.pr_products WHERE id = p_rm_id AND product_type = 'RM' AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active RM not found'; END IF;
  IF EXISTS (SELECT 1 FROM public.roll_material_config_rms WHERE rm_product_id = p_rm_id)
     OR EXISTS (SELECT 1 FROM public.roll_material_configs WHERE rm_product_id = p_rm_id) THEN
    RAISE EXCEPTION 'RM already paired; existing pairings will not be replaced';
  END IF;
  FOR v_fg IN SELECT id FROM unnest(p_fg_ids) id ORDER BY id LOOP
    PERFORM 1 FROM public.pr_products WHERE id = v_fg AND product_type = 'FG' AND is_active IS TRUE FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active FG not found'; END IF;
    INSERT INTO public.roll_material_configs(fg_product_id,rm_product_id,sheets_per_roll,pairing_group_id)
      VALUES(v_fg,p_rm_id,p_sheets,v_group) RETURNING id INTO v_config;
    INSERT INTO public.roll_material_config_rms(config_id,rm_product_id) VALUES(v_config,p_rm_id);
  END LOOP;
  PERFORM public.fn_initialize_multi_fg_pairing_stock(v_group);
END $$;


--
-- Name: rpc_create_sample(jsonb, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_sample(p_items jsonb, p_sample_label text, p_note text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_receipt_status text DEFAULT 'received'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := COALESCE(auth.uid(), p_user_id);
  v_sample_id UUID;
  v_sample_no TEXT;
  v_item JSONB;
BEGIN
  IF COALESCE(trim(p_sample_label), '') = '' THEN
    RAISE EXCEPTION 'กรุณาระบุชื่อเรียกสินค้า';
  END IF;
  IF p_receipt_status NOT IN ('pending_receipt', 'received') THEN
    RAISE EXCEPTION 'สถานะรับสินค้าไม่ถูกต้อง';
  END IF;

  v_sample_no := 'SMP-' || to_char(NOW(), 'YYYYMMDD') || '-' || lpad(floor(random() * 9000 + 1000)::text, 4, '0');

  INSERT INTO inv_samples (sample_no, status, received_by, received_at, sample_label, note)
  VALUES (
    v_sample_no,
    p_receipt_status,
    CASE WHEN p_receipt_status = 'received' THEN v_uid ELSE NULL END,
    CASE WHEN p_receipt_status = 'received' THEN NOW() ELSE NULL END,
    trim(p_sample_label),
    p_note
  )
  RETURNING id INTO v_sample_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO inv_sample_items (sample_id, product_name_manual, image_url, qty, note)
    VALUES (
      v_sample_id,
      NULLIF(trim(v_item->>'product_name_manual'), ''),
      NULLIF(trim(v_item->>'image_url'), ''),
      COALESCE((v_item->>'qty')::NUMERIC, 0),
      NULLIF(trim(v_item->>'note'), '')
    );
  END LOOP;

  RETURN jsonb_build_object('id', v_sample_id, 'sample_no', v_sample_no);
END;
$$;


--
-- Name: rpc_create_stock_transfer(uuid, uuid, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_stock_transfer(p_from_location_id uuid, p_to_location_id uuid, p_items jsonb, p_note text DEFAULT NULL::text, p_post boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_transfer_id UUID;
  v_item JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
BEGIN
  IF NOT public.can_manage_warehouse_locations() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างใบย้ายตำแหน่ง';
  END IF;
  IF p_from_location_id IS NULL OR p_to_location_id IS NULL OR p_from_location_id = p_to_location_id THEN
    RAISE EXCEPTION 'ต้นทางและปลายทางต้องไม่ซ้ำกัน';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'กรุณาเพิ่มสินค้าอย่างน้อย 1 รายการ';
  END IF;

  INSERT INTO public.wh_stock_transfers(
    transfer_no, from_location_id, to_location_id, status, note, created_by
  ) VALUES (
    public.fn_next_stock_transfer_no(), p_from_location_id, p_to_location_id,
    CASE WHEN p_post THEN 'posted' ELSE 'draft' END,
    NULLIF(BTRIM(p_note), ''), auth.uid()
  ) RETURNING id INTO v_transfer_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_qty := (v_item->>'qty')::NUMERIC;
    IF v_qty IS NULL OR v_qty <= 0 THEN RAISE EXCEPTION 'จำนวนย้ายต้องมากกว่า 0'; END IF;

    INSERT INTO public.wh_stock_transfer_items(transfer_id, product_id, qty)
    VALUES (v_transfer_id, v_product_id, v_qty);

    IF p_post THEN
      UPDATE public.wh_location_stock
      SET qty = qty - v_qty, updated_at = NOW()
      WHERE product_id = v_product_id AND location_id = p_from_location_id AND qty >= v_qty;
      IF NOT FOUND THEN RAISE EXCEPTION 'สินค้าในจุดต้นทางมีไม่เพียงพอ'; END IF;

      INSERT INTO public.wh_location_stock(product_id, location_id, qty)
      VALUES (v_product_id, p_to_location_id, v_qty)
      ON CONFLICT (product_id, location_id) DO UPDATE
        SET qty = public.wh_location_stock.qty + EXCLUDED.qty, updated_at = NOW();
    END IF;
  END LOOP;

  IF p_post THEN
    UPDATE public.wh_stock_transfers
    SET posted_by = auth.uid(), posted_at = NOW()
    WHERE id = v_transfer_id;
  END IF;
  RETURN v_transfer_id;
END;
$$;


--
-- Name: rpc_create_work_order_with_plan(text, uuid[], text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_work_order_with_plan(p_work_order_name text, p_order_ids uuid[], p_plan_job_id text, p_plan_date text, p_cut text, p_qty jsonb, p_order_index integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT; v_work_order_id UUID; v_requested INT; v_locked INT; v_auto_end TIMESTAMPTZ;
  v_previous_deferred_work_order TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin','order_staff','packing_staff','manager','production') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างใบงาน';
  END IF;
  IF NULLIF(BTRIM(COALESCE(p_work_order_name,'')),'') IS NULL
     OR NULLIF(BTRIM(COALESCE(p_plan_job_id,'')),'') IS NULL
     OR NULLIF(BTRIM(COALESCE(p_plan_date,'')),'') IS NULL
     OR COALESCE(CARDINALITY(p_order_ids),0)=0 THEN
    RAISE EXCEPTION 'ข้อมูลสร้างใบงานไม่ครบ';
  END IF;
  v_requested:=(SELECT COUNT(DISTINCT id) FROM UNNEST(p_order_ids) AS requested(id));
  PERFORM 1 FROM public.or_orders WHERE id=ANY(p_order_ids) ORDER BY id FOR UPDATE;
  SELECT COUNT(*) INTO v_locked FROM public.or_orders
  WHERE id=ANY(p_order_ids) AND work_order_id IS NULL
    AND (
      status IN ('ใบสั่งงาน','คอนเฟิร์มแล้ว','เสร็จสิ้น','ย้ายจากใบงาน')
      OR (status='ตรวจสอบแล้ว' AND UPPER(BTRIM(COALESCE(channel_code,'')))='WY')
    );
  IF v_locked<>v_requested THEN
    RAISE EXCEPTION 'มีบิลบางรายการไม่อยู่ในคิวหรือถูกนำไปสร้างใบงานแล้ว กรุณารีเฟรช';
  END IF;

  INSERT INTO public.or_work_orders(work_order_name,status,order_count)
  VALUES(BTRIM(p_work_order_name),'กำลังผลิต',v_requested)
  RETURNING id INTO v_work_order_id;

  v_previous_deferred_work_order:=current_setting('app.defer_auto_wms_work_order_id',true);
  PERFORM set_config('app.defer_auto_wms_work_order_id',v_work_order_id::TEXT,true);
  UPDATE public.or_orders SET
    work_order_id=v_work_order_id,work_order_name=BTRIM(p_work_order_name),
    plan_released_from_work_order=NULL,plan_released_from_work_order_id=NULL,plan_released_at=NULL,
    status=CASE WHEN status='ย้ายจากใบงาน' THEN 'ใบสั่งงาน' ELSE status END
  WHERE id=ANY(p_order_ids);
  -- Restore before any other work; PostgreSQL also rolls this local setting
  -- back together with the statement if a validation/stock trigger raises.
  PERFORM set_config('app.defer_auto_wms_work_order_id',COALESCE(v_previous_deferred_work_order,''),true);

  INSERT INTO public.plan_jobs(id,date,name,work_order_id,cut,qty,tracks,line_assignments,
    manual_plan_starts,locked_plans,order_index)
  VALUES(BTRIM(p_plan_job_id),BTRIM(p_plan_date),BTRIM(p_work_order_name),v_work_order_id,p_cut,
    COALESCE(p_qty,'{}'::JSONB),'{}','{}','{}','{}',COALESCE(p_order_index,0));

  PERFORM public.fn_wms_try_auto_consume_non_pick(p_work_order_name);
  IF NOT EXISTS (
    SELECT 1 FROM public.or_orders o JOIN public.or_order_items oi ON oi.order_id=o.id
    JOIN public.pr_products p ON p.id=oi.product_id
    WHERE o.work_order_id=v_work_order_id AND NOT COALESCE(oi.is_detail_row,false)
      AND public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT)='warehouse_pick'
  ) THEN
    SELECT MAX(end_time) INTO v_auto_end FROM public.wms_orders WHERE work_order_id=v_work_order_id;
    v_auto_end:=COALESCE(v_auto_end,NOW());
    PERFORM public.merge_plan_tracks_by_work_order_id(v_work_order_id,'เบิก',jsonb_build_object(
      'หยิบของ',jsonb_build_object('start_if_null',v_auto_end,'end',v_auto_end),
      'ส่งมอบ',jsonb_build_object('start_if_null',v_auto_end,'end',v_auto_end)
    ));
  END IF;
  RETURN jsonb_build_object('success',true,'work_order_id',v_work_order_id,'work_order_name',BTRIM(p_work_order_name));
END;
$$;


--
-- Name: rpc_data_delete_all_products(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_data_delete_all_products(p_confirm_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_table TEXT;
  v_truncate_tables TEXT := '';
  v_product_count BIGINT;
  v_deleted BIGINT := 0;
  v_blockers JSONB;
BEGIN
  PERFORM erp_data_assert_superadmin();

  IF COALESCE(p_confirm_text, '') <> 'DELETE ALL PRODUCTS' THEN
    RAISE EXCEPTION 'ข้อความยืนยันไม่ถูกต้อง ต้องพิมพ์: DELETE ALL PRODUCTS';
  END IF;

  SELECT jsonb_build_object(
    'or_orders', COALESCE((SELECT COUNT(*) FROM or_orders), 0),
    'inv_stock_balances', COALESCE((SELECT COUNT(*) FROM inv_stock_balances), 0),
    'inv_stock_lots', COALESCE((SELECT COUNT(*) FROM inv_stock_lots), 0),
    'wms_orders', COALESCE((SELECT COUNT(*) FROM wms_orders), 0),
    'pp_production_orders', COALESCE((SELECT COUNT(*) FROM pp_production_orders), 0),
    'inv_po', COALESCE((SELECT COUNT(*) FROM inv_po), 0),
    'inv_pr', COALESCE((SELECT COUNT(*) FROM inv_pr), 0)
  )
  INTO v_blockers;

  IF (v_blockers->>'or_orders')::BIGINT > 0
    OR (v_blockers->>'inv_stock_balances')::BIGINT > 0
    OR (v_blockers->>'inv_stock_lots')::BIGINT > 0
    OR (v_blockers->>'wms_orders')::BIGINT > 0
    OR (v_blockers->>'pp_production_orders')::BIGINT > 0
    OR (v_blockers->>'inv_po')::BIGINT > 0
    OR (v_blockers->>'inv_pr')::BIGINT > 0
  THEN
    RAISE EXCEPTION 'ต้องล้างข้อมูลธุรกรรมก่อน (ใช้ ล้างข้อมูลอย่างเดียว) blockers: %', v_blockers::TEXT;
  END IF;

  SELECT COUNT(*) INTO v_product_count FROM pr_products;

  FOREACH v_table IN ARRAY erp_data_product_dependent_master_tables()
  LOOP
    IF to_regclass('public.' || v_table) IS NOT NULL THEN
      v_truncate_tables := v_truncate_tables || CASE WHEN v_truncate_tables = '' THEN '' ELSE ', ' END || format('%I', v_table);
    END IF;
  END LOOP;

  IF v_truncate_tables <> '' THEN
    EXECUTE 'TRUNCATE ' || v_truncate_tables;
  END IF;

  DELETE FROM pr_products WHERE id IS NOT NULL;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_products', v_deleted,
    'previous_product_count', v_product_count,
    'hr_policy', 'preserved',
    'note', 'pr_sellers และ master อื่นๆ ยังอยู่ — นำเข้าสินค้าใหม่ได้ทันที'
  );
END;
$$;


--
-- Name: rpc_data_delete_all_sellers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_data_delete_all_sellers(p_confirm_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_seller_count BIGINT;
  v_deleted BIGINT := 0;
  v_blockers JSONB;
BEGIN
  PERFORM erp_data_assert_superadmin();

  IF COALESCE(p_confirm_text, '') <> 'DELETE ALL SELLERS' THEN
    RAISE EXCEPTION 'ข้อความยืนยันไม่ถูกต้อง ต้องพิมพ์: DELETE ALL SELLERS';
  END IF;

  SELECT jsonb_build_object(
    'or_orders', COALESCE((SELECT COUNT(*) FROM or_orders), 0),
    'inv_stock_balances', COALESCE((SELECT COUNT(*) FROM inv_stock_balances), 0),
    'inv_stock_lots', COALESCE((SELECT COUNT(*) FROM inv_stock_lots), 0),
    'wms_orders', COALESCE((SELECT COUNT(*) FROM wms_orders), 0),
    'pp_production_orders', COALESCE((SELECT COUNT(*) FROM pp_production_orders), 0),
    'inv_po', COALESCE((SELECT COUNT(*) FROM inv_po), 0),
    'inv_pr', COALESCE((SELECT COUNT(*) FROM inv_pr), 0)
  )
  INTO v_blockers;

  IF (v_blockers->>'or_orders')::BIGINT > 0
    OR (v_blockers->>'inv_stock_balances')::BIGINT > 0
    OR (v_blockers->>'inv_stock_lots')::BIGINT > 0
    OR (v_blockers->>'wms_orders')::BIGINT > 0
    OR (v_blockers->>'pp_production_orders')::BIGINT > 0
    OR (v_blockers->>'inv_po')::BIGINT > 0
    OR (v_blockers->>'inv_pr')::BIGINT > 0
  THEN
    RAISE EXCEPTION 'ต้องล้างข้อมูลธุรกรรมก่อน (ใช้ ล้างข้อมูลอย่างเดียว) blockers: %', v_blockers::TEXT;
  END IF;

  SELECT COUNT(*) INTO v_seller_count FROM pr_sellers;

  DELETE FROM pr_sellers WHERE id IS NOT NULL;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_sellers', v_deleted,
    'previous_seller_count', v_seller_count,
    'hr_policy', 'preserved',
    'note', 'ชื่อผู้ขายในสินค้า (seller_name) ยังอยู่ — ซิงก์จากสินค้าหรือเพิ่มมือใหม่ได้'
  );
END;
$$;


--
-- Name: rpc_data_operation_create(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_data_operation_create(p_operation_type text, p_target_year integer DEFAULT NULL::integer, p_stock_strategy text DEFAULT 'opening'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid UUID;
  v_id UUID;
  v_stock_strategy TEXT := COALESCE(NULLIF(p_stock_strategy, ''), 'opening');
BEGIN
  v_uid := public.erp_data_assert_superadmin();

  IF p_operation_type NOT IN ('annual_close', 'reset_only', 'backup_only', 'go_live_reset') THEN
    RAISE EXCEPTION 'operation_type ไม่ถูกต้อง';
  END IF;
  IF v_stock_strategy NOT IN ('opening', 'zero') THEN
    RAISE EXCEPTION 'stock_strategy ไม่ถูกต้อง';
  END IF;
  IF p_operation_type = 'annual_close' AND p_target_year IS NULL THEN
    RAISE EXCEPTION 'ต้องระบุปีสำหรับปิดงวดรายปี';
  END IF;

  INSERT INTO public.erp_data_operations (
    operation_type, target_year, stock_strategy, status, requested_by
  ) VALUES (
    p_operation_type,
    p_target_year,
    CASE WHEN p_operation_type = 'backup_only' THEN 'opening' ELSE v_stock_strategy END,
    'draft',
    v_uid
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'operation_id', v_id);
END;
$$;


--
-- Name: rpc_data_operation_mark_backup_verified(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_data_operation_mark_backup_verified(p_operation_id uuid, p_manifest jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := erp_data_assert_superadmin();

  UPDATE erp_data_operations
  SET status = CASE
        WHEN operation_type = 'backup_only' THEN 'completed'
        ELSE 'backup_verified'
      END,
      backup_started_at = COALESCE(backup_started_at, NOW()),
      backup_verified_at = NOW(),
      summary = summary || jsonb_build_object('backup_manifest', p_manifest, 'backup_verified_by', v_uid),
      error_message = NULL
  WHERE id = p_operation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบ operation';
  END IF;

  RETURN jsonb_build_object('success', true, 'operation_id', p_operation_id);
END;
$$;


--
-- Name: rpc_data_operation_preview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_data_operation_preview(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid UUID;
  v_op public.erp_data_operations%ROWTYPE;
  v_table TEXT;
  v_count BIGINT;
  v_table_counts JSONB := '[]'::JSONB;
  v_total BIGINT := 0;
  v_blockers JSONB;
  v_database_size BIGINT := pg_database_size(current_database());
BEGIN
  v_uid := public.erp_data_assert_superadmin();
  PERFORM pg_advisory_xact_lock(hashtext('erp_data_operation:' || p_operation_id::TEXT));

  SELECT * INTO v_op
  FROM public.erp_data_operations
  WHERE id = p_operation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบ operation'; END IF;

  DELETE FROM public.erp_data_operation_table_counts
  WHERE operation_id = p_operation_id AND phase = 'preview';

  FOREACH v_table IN ARRAY public.erp_data_tables_for_operation(v_op.operation_type)
  LOOP
    IF to_regclass('public.' || v_table) IS NOT NULL THEN
      EXECUTE format('SELECT COUNT(*) FROM %I', v_table) INTO v_count;
      INSERT INTO public.erp_data_operation_table_counts(operation_id, phase, table_name, row_count)
      VALUES (p_operation_id, 'preview', v_table, v_count)
      ON CONFLICT (operation_id, phase, table_name)
      DO UPDATE SET row_count = EXCLUDED.row_count, recorded_at = NOW();
      v_total := v_total + v_count;
      v_table_counts := v_table_counts || jsonb_build_array(
        jsonb_build_object('table_name', v_table, 'row_count', v_count)
      );
    END IF;
  END LOOP;

  SELECT jsonb_build_object(
    'open_orders', COALESCE((SELECT COUNT(*) FROM public.or_orders WHERE status IS DISTINCT FROM 'จัดส่งแล้ว' AND status IS DISTINCT FROM 'ยกเลิก'), 0),
    'pending_wms_orders', COALESCE((SELECT COUNT(*) FROM public.wms_orders WHERE status NOT IN ('correct', 'wrong', 'not_find', 'out_of_stock', 'cancelled', 'system_complete')), 0),
    'open_qc_sessions', COALESCE((SELECT COUNT(*) FROM public.qc_sessions WHERE end_time IS NULL), 0),
    'open_purchase_orders', COALESCE((SELECT COUNT(*) FROM public.inv_po WHERE status NOT IN ('closed', 'cancelled', 'received')), 0),
    'pending_requisitions', COALESCE((SELECT COUNT(*) FROM public.wms_requisitions WHERE status = 'pending'), 0),
    'warning_only_for_go_live', v_op.operation_type = 'go_live_reset',
    'hr_policy', 'preserve_all_hr'
  ) INTO v_blockers;

  UPDATE public.erp_data_operations
  SET status = CASE WHEN status = 'draft' THEN 'previewed' ELSE status END,
      summary = summary || jsonb_build_object(
        'last_preview_at', NOW(),
        'preview_total_rows', v_total,
        'database_size_bytes', v_database_size,
        'blockers', v_blockers,
        'table_scope', CASE WHEN operation_type = 'go_live_reset' THEN 'go_live_trial_data' ELSE 'standard_transactional' END
      ),
      error_message = NULL
  WHERE id = p_operation_id;

  RETURN jsonb_build_object(
    'success', true,
    'operation_id', p_operation_id,
    'operation_type', v_op.operation_type,
    'stock_strategy', v_op.stock_strategy,
    'target_year', v_op.target_year,
    'database_size_bytes', v_database_size,
    'total_rows', v_total,
    'table_counts', v_table_counts,
    'blockers', v_blockers,
    'hr_policy', jsonb_build_object(
      'preserve_default', true,
      'message', 'เก็บข้อมูล HR, Master สินค้า, ผู้ขาย, ผู้ใช้ และการตั้งค่าทั้งหมด'
    )
  );
END;
$$;


--
-- Name: rpc_data_reset_execute(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_data_reset_execute(p_operation_id uuid, p_confirm_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid UUID;
  v_op public.erp_data_operations%ROWTYPE;
  v_tables TEXT[];
  v_remaining_tables TEXT[];
  v_deferred_tables TEXT[];
  v_table TEXT;
  v_deleted_any BOOLEAN;
  v_count BIGINT;
  v_before JSONB := '[]'::JSONB;
  v_after JSONB := '[]'::JSONB;
  v_expected_confirm TEXT;
  v_epoch_id BIGINT;
  v_opening_products INT := 0;
BEGIN
  v_uid := public.erp_data_assert_superadmin();
  PERFORM pg_advisory_xact_lock(hashtext('erp_data_reset_execute'));
  PERFORM pg_advisory_xact_lock(hashtext('erp_data_operation:' || p_operation_id::TEXT));

  SELECT * INTO v_op
  FROM public.erp_data_operations
  WHERE id = p_operation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบ operation'; END IF;
  IF v_op.operation_type = 'backup_only' THEN
    RAISE EXCEPTION 'operation นี้เป็นสำรองข้อมูลอย่างเดียว ไม่สามารถล้างข้อมูลได้';
  END IF;

  v_expected_confirm := CASE
    WHEN v_op.operation_type = 'annual_close' THEN 'CLOSE YEAR ' || v_op.target_year::TEXT
    WHEN v_op.operation_type = 'go_live_reset' THEN 'GO LIVE RESET'
    ELSE 'RESET DATA'
  END;
  IF COALESCE(p_confirm_text, '') <> v_expected_confirm THEN
    RAISE EXCEPTION 'ข้อความยืนยันไม่ถูกต้อง ต้องพิมพ์: %', v_expected_confirm;
  END IF;
  IF v_op.operation_type IN ('annual_close', 'go_live_reset')
     AND v_op.backup_verified_at IS NULL THEN
    RAISE EXCEPTION 'ต้องสำรองข้อมูลและตรวจสอบ manifest สำเร็จก่อนล้างข้อมูล';
  END IF;

  v_tables := public.erp_data_tables_for_operation(v_op.operation_type);

  UPDATE public.erp_data_operations
  SET status = 'reset_running', reset_started_at = NOW(), error_message = NULL
  WHERE id = p_operation_id;

  CREATE TEMP TABLE _erp_opening_stock ON COMMIT DROP AS
  SELECT
    product_id,
    COALESCE(is_safety_stock, FALSE) AS is_safety_stock,
    ROUND(SUM(qty_remaining), 2) AS qty,
    CASE
      WHEN SUM(qty_remaining) = 0 THEN 0
      ELSE ROUND(SUM(qty_remaining * unit_cost) / SUM(qty_remaining), 4)
    END AS unit_cost
  FROM public.inv_stock_lots
  WHERE qty_remaining > 0
  GROUP BY product_id, COALESCE(is_safety_stock, FALSE);

  DELETE FROM public.erp_data_operation_table_counts
  WHERE operation_id = p_operation_id AND phase IN ('before_reset', 'after_reset');

  -- Record the complete before-state before any cascade can remove child rows.
  FOREACH v_table IN ARRAY v_tables
  LOOP
    IF to_regclass('public.' || v_table) IS NOT NULL THEN
      EXECUTE format('SELECT COUNT(*) FROM %I', v_table) INTO v_count;
      INSERT INTO public.erp_data_operation_table_counts(operation_id, phase, table_name, row_count)
      VALUES (p_operation_id, 'before_reset', v_table, v_count)
      ON CONFLICT (operation_id, phase, table_name)
      DO UPDATE SET row_count = EXCLUDED.row_count, recorded_at = NOW();
      v_before := v_before || jsonb_build_array(jsonb_build_object('table_name', v_table, 'row_count', v_count));
    END IF;
  END LOOP;

  -- Delete in dependency-aware passes. FK-restricted parents are deferred until
  -- their scoped children are gone. An out-of-scope RESTRICT dependency aborts
  -- the whole transaction rather than deleting unrelated data via CASCADE.
  v_remaining_tables := v_tables;
  WHILE COALESCE(array_length(v_remaining_tables, 1), 0) > 0
  LOOP
    v_deferred_tables := ARRAY[]::TEXT[];
    v_deleted_any := FALSE;

    FOREACH v_table IN ARRAY v_remaining_tables
    LOOP
      IF to_regclass('public.' || v_table) IS NULL THEN
        v_deleted_any := TRUE;
      ELSE
        BEGIN
          -- WHERE clause is intentional for environments with pg_safeupdate.
          EXECUTE format('DELETE FROM %I WHERE TRUE', v_table);
          v_deleted_any := TRUE;
        EXCEPTION WHEN foreign_key_violation THEN
          v_deferred_tables := array_append(v_deferred_tables, v_table);
        END;
      END IF;
    END LOOP;

    IF COALESCE(array_length(v_deferred_tables, 1), 0) = 0 THEN
      EXIT;
    END IF;
    IF NOT v_deleted_any THEN
      RAISE EXCEPTION 'ไม่สามารถล้างข้อมูลได้ เนื่องจากมี Foreign Key นอกขอบเขตอ้างอิงตาราง: %',
        array_to_string(v_deferred_tables, ', ');
    END IF;
    v_remaining_tables := v_deferred_tables;
  END LOOP;

  IF v_op.operation_type = 'annual_close' OR v_op.stock_strategy = 'opening' THEN
    UPDATE public.ac_inventory_epochs SET is_active = FALSE WHERE is_active = TRUE;
    INSERT INTO public.ac_inventory_epochs(epoch_name, started_at, is_active, note, created_by)
    VALUES (
      CASE
        WHEN v_op.operation_type = 'annual_close' THEN 'YEAR-' || v_op.target_year::TEXT
        WHEN v_op.operation_type = 'go_live_reset' THEN 'GO-LIVE-' || to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD-HH24MI')
        ELSE 'RESET-' || to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD-HH24MI')
      END,
      NOW(), TRUE,
      'Created by data operation ' || p_operation_id::TEXT,
      v_uid
    ) RETURNING id INTO v_epoch_id;

    INSERT INTO public.ac_inventory_epoch_openings(
      epoch_id, product_id, opening_qty, opening_value, opening_safety_qty, opening_safety_value
    )
    SELECT
      v_epoch_id,
      product_id,
      SUM(CASE WHEN is_safety_stock = FALSE THEN qty ELSE 0 END),
      SUM(CASE WHEN is_safety_stock = FALSE THEN qty * unit_cost ELSE 0 END),
      SUM(CASE WHEN is_safety_stock = TRUE THEN qty ELSE 0 END),
      SUM(CASE WHEN is_safety_stock = TRUE THEN qty * unit_cost ELSE 0 END)
    FROM _erp_opening_stock
    GROUP BY product_id;

    INSERT INTO public.inv_stock_lots(product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id, is_safety_stock)
    SELECT product_id, qty, qty, unit_cost, 'erp_data_operation', p_operation_id, is_safety_stock
    FROM _erp_opening_stock
    WHERE qty > 0;

    INSERT INTO public.inv_stock_movements(product_id, movement_type, qty, ref_type, ref_id, note, created_by, unit_cost, total_cost)
    SELECT product_id, 'opening', qty, 'erp_data_operation', p_operation_id,
           'ยอดยกมาจากการล้างข้อมูลทดลองก่อนเริ่มใช้งานจริง',
           v_uid, unit_cost, ROUND(qty * unit_cost, 2)
    FROM _erp_opening_stock
    WHERE qty > 0;

    INSERT INTO public.inv_stock_balances(product_id, on_hand, reserved, safety_stock)
    SELECT
      product_id,
      SUM(CASE WHEN is_safety_stock = FALSE THEN qty ELSE 0 END),
      0,
      SUM(CASE WHEN is_safety_stock = TRUE THEN qty ELSE 0 END)
    FROM _erp_opening_stock
    GROUP BY product_id;

    GET DIAGNOSTICS v_opening_products = ROW_COUNT;

    UPDATE public.pr_products p
    SET landed_cost = COALESCE((
      SELECT SUM(l.qty_remaining * l.unit_cost) / NULLIF(SUM(l.qty_remaining), 0)
      FROM public.inv_stock_lots l
      WHERE l.product_id = p.id AND l.qty_remaining > 0
    ), 0)
    WHERE p.id IS NOT NULL;
  ELSE
    UPDATE public.pr_products
    SET landed_cost = 0
    WHERE landed_cost IS DISTINCT FROM 0;
  END IF;

  FOREACH v_table IN ARRAY v_tables
  LOOP
    IF to_regclass('public.' || v_table) IS NOT NULL THEN
      EXECUTE format('SELECT COUNT(*) FROM %I', v_table) INTO v_count;
      INSERT INTO public.erp_data_operation_table_counts(operation_id, phase, table_name, row_count)
      VALUES (p_operation_id, 'after_reset', v_table, v_count)
      ON CONFLICT (operation_id, phase, table_name)
      DO UPDATE SET row_count = EXCLUDED.row_count, recorded_at = NOW();
      v_after := v_after || jsonb_build_array(jsonb_build_object('table_name', v_table, 'row_count', v_count));
    END IF;
  END LOOP;

  UPDATE public.erp_data_operations
  SET status = 'completed',
      reset_completed_at = NOW(),
      summary = summary || jsonb_build_object(
        'before_reset', v_before,
        'after_reset', v_after,
        'inventory_epoch_id', v_epoch_id,
        'opening_balance_products', v_opening_products,
        'master_policy', 'products_users_sellers_settings_hr_preserved',
        'storage_policy', 'objects_not_deleted'
      ),
      error_message = NULL
  WHERE id = p_operation_id;

  RETURN jsonb_build_object(
    'success', true,
    'operation_id', p_operation_id,
    'operation_type', v_op.operation_type,
    'inventory_epoch_id', v_epoch_id,
    'opening_balance_products', v_opening_products,
    'stock_strategy', v_op.stock_strategy,
    'master_data_preserved', true,
    'storage_objects_deleted', false,
    'after_reset', v_after
  );
END;
$$;


--
-- Name: rpc_delete_cancelled_prebill_documents(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_delete_cancelled_prebill_documents(p_document_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  IF NOT public.check_user_role(auth.uid(), ARRAY['superadmin']) THEN
    RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้นที่ลบเอกสารถาวรได้';
  END IF;
  IF COALESCE(cardinality(p_document_ids), 0) = 0 THEN RETURN 0; END IF;
  IF EXISTS (
    SELECT 1 FROM public.or_prebill_documents
    WHERE id = ANY(p_document_ids) AND status <> 'cancelled'
  ) THEN
    RAISE EXCEPTION 'ลบถาวรได้เฉพาะเอกสารในแถบยกเลิก';
  END IF;

  PERFORM set_config('app.prebill_hard_delete', 'on', true);
  DELETE FROM public.or_prebill_documents
  WHERE id = ANY(p_document_ids) AND status = 'cancelled';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: rpc_delete_prebill_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_delete_prebill_document(p_document_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN public.rpc_delete_cancelled_prebill_documents(ARRAY[p_document_id]) = 1;
END;
$$;


--
-- Name: rpc_discount_approval_queue(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_discount_approval_queue(p_status text DEFAULT 'pending'::text, p_type text DEFAULT 'all'::text, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE result_ jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND is_active AND role='superadmin') THEN RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้น'; END IF;
 WITH rows_ AS (
 SELECT 'sale'::text source,r.id,o.id document_id,o.bill_no document_no,r.requested_name owner_name,r.reason,
 (r.snapshot->>'price')::numeric subtotal,(r.snapshot->>'shipping_cost')::numeric shipping_cost,
 (r.snapshot->>'discount')::numeric discount,(r.snapshot->>'total_amount')::numeric total_amount,r.created_at,
 CASE WHEN o.status='ยกเลิก' THEN 'cancelled' WHEN r.status IN ('pending','approved') AND r.snapshot<>public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id)) THEN 'stale' ELSE r.status END status,
 r.reviewed_name,r.reviewed_at,r.review_note,r.snapshot||jsonb_build_object('items',coalesce((SELECT jsonb_agg(x||jsonb_build_object('product_name',p.product_name)) FROM jsonb_array_elements(r.snapshot->'items') x LEFT JOIN public.pr_products p ON p.id=(x->>'product_id')::uuid),'[]')) snapshot
 FROM public.or_sales_discount_requests r JOIN public.or_orders o ON o.id=r.order_id
 UNION ALL
 SELECT CASE d.document_type WHEN 'quotation' THEN 'QT' ELSE 'PC' END,d.id,d.id,d.document_no,d.owner_name,d.discount_request_note,
 coalesce((d.discount_review_snapshot->>'price')::numeric,d.subtotal),coalesce((d.discount_review_snapshot->>'shipping_cost')::numeric,d.shipping_cost),coalesce((d.discount_review_snapshot->>'discount')::numeric,d.promotion_discount+d.special_discount),coalesce((d.discount_review_snapshot->>'total_amount')::numeric,d.total_amount),coalesce(d.discount_requested_at,d.created_at),
 CASE WHEN d.status='pending_discount' AND d.valid_until>=(now() AT TIME ZONE 'Asia/Bangkok')::date THEN 'pending'
 WHEN d.status IN ('approved','converted') AND d.approved_by IS NOT NULL THEN 'approved'
 WHEN d.status='rejected' THEN 'rejected' WHEN d.status='cancelled' THEN 'cancelled' WHEN d.status='pending_discount' THEN 'expired' ELSE 'stale' END,
 u.username,d.approved_at,coalesce(d.approval_note,d.rejection_note),jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM public.or_prebill_items i WHERE document_id=d.id),'[]'))
 FROM public.or_prebill_documents d LEFT JOIN public.us_users u ON u.id=d.approved_by
 WHERE d.discount_requested_at IS NOT NULL
 ), filtered AS (SELECT * FROM rows_ WHERE (p_status='all' OR status=p_status) AND (p_type='all' OR source=p_type)),
 page AS (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT 50 OFFSET greatest(0,p_offset))
 SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'),
 'count',(SELECT count(*) FROM filtered),'pending_count',(SELECT count(*) FROM rows_ WHERE status='pending')) INTO result_;
 RETURN result_;
END $$;


--
-- Name: rpc_dismiss_packing_upload_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_dismiss_packing_upload_report(p_report_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_reported_at TIMESTAMPTZ;
  v_is_admin BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'กรุณาเข้าสู่ระบบ';
  END IF;

  SELECT r.user_id,r.status,r.reported_at
  INTO v_owner,v_status,v_reported_at
  FROM public.pk_packing_upload_queue_reports r
  WHERE r.id=p_report_id AND r.dismissed_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.us_users u
    WHERE u.id=v_uid AND u.role IN ('superadmin','admin')
  ) INTO v_is_admin;

  IF NOT v_is_admin AND v_owner IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ลบรายการของเครื่องหรือผู้ใช้อื่น';
  END IF;

  IF NOT (
    v_status='failed'
    OR (v_status='uploading' AND v_reported_at < NOW()-INTERVAL '10 minutes')
    OR (v_status='pending' AND v_reported_at < NOW()-INTERVAL '30 minutes')
  ) THEN
    RAISE EXCEPTION 'ลบได้เฉพาะรายการที่มีปัญหาหรือค้างเท่านั้น';
  END IF;

  UPDATE public.pk_packing_upload_queue_reports
  SET dismissed_at=NOW(),dismissed_by=v_uid
  WHERE id=p_report_id;

  RETURN TRUE;
END;
$$;


--
-- Name: FUNCTION rpc_dismiss_packing_upload_report(p_report_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_dismiss_packing_upload_report(p_report_id uuid) IS 'Soft-deletes a failed/stale Packing upload report. Admins may dismiss any row; owners may dismiss their own.';


--
-- Name: rpc_execute_bill_cancellation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_execute_bill_cancellation(p_amendment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_amendment RECORD;
  v_order RECORD;
  v_snapshot_order JSONB;
  v_remove_ids UUID[];
  v_all_item_ids UUID[];
  v_target_item_ids UUID[];
  v_items_left INT := 0;
  v_active_orders_in_wo INT := 0;
  v_cancelled_wms INT := 0;
  v_new_total NUMERIC := 0;
  v_new_rev INT;
  v_is_partial BOOLEAN := false;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr') THEN
    RAISE EXCEPTION 'no permission to cancel bill (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT * INTO v_amendment FROM public.or_order_amendments WHERE id = p_amendment_id FOR UPDATE;
  IF v_amendment.id IS NULL THEN RAISE EXCEPTION 'amendment not found'; END IF;
  IF v_amendment.status = 'executed' THEN RAISE EXCEPTION 'amendment already executed'; END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id = v_amendment.order_id FOR UPDATE;
  IF v_order.id IS NULL THEN RAISE EXCEPTION 'order not found'; END IF;
  SELECT row_to_json(o)::JSONB INTO v_snapshot_order FROM public.or_orders o WHERE o.id = v_order.id;
  SELECT array_agg(id) INTO v_all_item_ids FROM public.or_order_items WHERE order_id = v_order.id;

  IF v_amendment.changes_json IS NOT NULL AND v_amendment.changes_json ? 'remove_item_ids' THEN
    SELECT array_agg((x#>>'{}')::UUID) INTO v_remove_ids
    FROM jsonb_array_elements(v_amendment.changes_json->'remove_item_ids') x;
  END IF;
  v_is_partial := v_remove_ids IS NOT NULL AND array_length(v_remove_ids, 1) > 0;
  v_target_item_ids := CASE WHEN v_is_partial THEN v_remove_ids ELSE v_all_item_ids END;

  IF v_is_partial AND EXISTS (
    SELECT 1 FROM unnest(v_remove_ids) rid
    WHERE NOT EXISTS (SELECT 1 FROM public.or_order_items oi WHERE oi.id = rid AND oi.order_id = v_order.id)
  ) THEN RAISE EXCEPTION 'some remove_item_ids do not belong to this order'; END IF;

  INSERT INTO public.wms_notifications(type, order_id, picker_id, status, is_read)
  SELECT DISTINCT 'ยกเลิกบิล', COALESCE(v_order.work_order_name, v_order.bill_no), w.assigned_to, 'unread', FALSE
  FROM public.wms_orders w
  WHERE w.assigned_to IS NOT NULL
    AND w.status NOT IN ('cancelled', 'returned')
    AND ((w.source_order_id = v_order.id AND (NOT v_is_partial OR w.source_order_item_id = ANY(v_target_item_ids)))
      OR w.source_order_item_id = ANY(v_target_item_ids));

  WITH changed AS (
    UPDATE public.wms_orders w
    SET status_before_cancel = COALESCE(w.status_before_cancel, w.status),
        cancelled_at = COALESCE(w.cancelled_at, NOW()),
        cancelled_by = COALESCE(w.cancelled_by, auth.uid()),
        stock_action = CASE
          WHEN w.status IN ('pending', 'out_of_stock')
           AND NOT EXISTS (
             SELECT 1 FROM public.inv_stock_movements m
             WHERE m.ref_type = 'wms_orders' AND m.ref_id = w.id AND m.movement_type = 'pick'
           ) THEN 'not_picked'
          ELSE NULL
        END,
        status = 'cancelled',
        end_time = COALESCE(w.end_time, NOW())
    WHERE w.status NOT IN ('cancelled', 'returned')
      AND ((w.source_order_id = v_order.id AND (NOT v_is_partial OR w.source_order_item_id = ANY(v_target_item_ids)))
        OR w.source_order_item_id = ANY(v_target_item_ids))
    RETURNING 1
  ) SELECT COUNT(*) INTO v_cancelled_wms FROM changed;

  IF NOT v_is_partial AND v_order.work_order_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_active_orders_in_wo
    FROM public.or_orders o
    WHERE o.work_order_id = v_order.work_order_id AND o.id <> v_order.id
      AND COALESCE(o.status, '') NOT IN ('ยกเลิก', 'จัดส่งแล้ว');

    IF v_active_orders_in_wo = 0 THEN
      WITH legacy_changed AS (
        UPDATE public.wms_orders w
        SET status_before_cancel = COALESCE(w.status_before_cancel, w.status),
            cancelled_at = COALESCE(w.cancelled_at, NOW()),
            cancelled_by = COALESCE(w.cancelled_by, auth.uid()),
            stock_action = CASE
              WHEN w.status IN ('pending', 'out_of_stock')
               AND NOT EXISTS (
                 SELECT 1 FROM public.inv_stock_movements m
                 WHERE m.ref_type = 'wms_orders' AND m.ref_id = w.id AND m.movement_type = 'pick'
               ) THEN 'not_picked'
              ELSE NULL
            END,
            status = 'cancelled', end_time = COALESCE(w.end_time, NOW())
        WHERE w.work_order_id = v_order.work_order_id
          AND w.source_order_id IS NULL AND w.source_order_item_id IS NULL
          AND w.status NOT IN ('cancelled', 'returned')
        RETURNING 1
      ) SELECT v_cancelled_wms + COUNT(*) INTO v_cancelled_wms FROM legacy_changed;
    END IF;
  END IF;

  UPDATE public.or_order_items
  SET cancellation_stock_action = 'pending'
  WHERE order_id = v_order.id AND id = ANY(v_target_item_ids);

  UPDATE public.or_order_items oi
  SET cancellation_stock_action = 'not_picked'
  WHERE oi.order_id = v_order.id AND oi.id = ANY(v_target_item_ids)
    AND (
      (
        EXISTS (SELECT 1 FROM public.wms_orders w WHERE w.source_order_item_id = oi.id)
        AND NOT EXISTS (
          SELECT 1 FROM public.wms_orders w
          WHERE w.source_order_item_id = oi.id AND COALESCE(w.stock_action, '') <> 'not_picked'
        )
      )
      OR NOT EXISTS (
        SELECT 1 FROM public.wms_orders w
        WHERE w.source_order_id = v_order.id
           OR w.work_order_id = v_order.work_order_id
           OR BTRIM(COALESCE(w.order_id, '')) = BTRIM(COALESCE(v_order.work_order_name, ''))
      )
    );

  SELECT COUNT(*) INTO v_items_left
  FROM public.or_order_items
  WHERE order_id = v_order.id AND cancellation_stock_action IS NULL;

  IF v_items_left = 0 THEN
    UPDATE public.or_orders SET status = 'ยกเลิก', updated_at = NOW() WHERE id = v_order.id;
  ELSE
    SELECT COALESCE(SUM(COALESCE(quantity, 1) * COALESCE(unit_price, 0)), 0)
    INTO v_new_total FROM public.or_order_items
    WHERE order_id = v_order.id AND cancellation_stock_action IS NULL;
    UPDATE public.or_orders SET total_amount = v_new_total, updated_at = NOW() WHERE id = v_order.id;
  END IF;

  v_new_rev := COALESCE(v_order.revision_no, 0) + 1;
  INSERT INTO public.or_order_revisions(
    order_id, revision_no, change_source, change_source_id, snapshot_order, snapshot_items, created_by
  ) VALUES (
    v_order.id, v_new_rev, 'amendment', p_amendment_id, v_snapshot_order,
    COALESCE(v_amendment.items_before,
      (SELECT COALESCE(jsonb_agg(row_to_json(oi)::JSONB), '[]'::JSONB)
       FROM public.or_order_items oi WHERE oi.order_id = v_order.id)),
    (SELECT COALESCE(username, email) FROM public.us_users WHERE id = v_amendment.approved_by)
  );

  UPDATE public.or_orders SET revision_no = v_new_rev WHERE id = v_order.id;
  UPDATE public.or_order_amendments SET status = 'executed', executed_at = NOW() WHERE id = p_amendment_id;
  IF v_order.work_order_id IS NOT NULL THEN
    PERFORM public.fn_recompute_work_order_order_count(v_order.work_order_id);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE, 'amendment_no', v_amendment.amendment_no, 'bill_no', v_order.bill_no,
    'cancelled_wms_count', v_cancelled_wms, 'revision_no', v_new_rev, 'partial', v_items_left > 0
  );
END;
$$;


--
-- Name: FUNCTION rpc_execute_bill_cancellation(p_amendment_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_execute_bill_cancellation(p_amendment_id uuid) IS 'ยกเลิกเฉพาะ WMS rows ของบิล/รายการที่อนุมัติ และคงแถวสินค้าไว้เพื่อ Audit โดยตัดออกจาก fulfillment ด้วย cancellation_stock_action';


--
-- Name: rpc_fulfill_sub_warehouse_replenishment_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_fulfill_sub_warehouse_replenishment_request(p_request_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request public.wh_sub_warehouse_replenishment_requests%ROWTYPE;
  v_requester_name TEXT;
  v_move_id UUID;
BEGIN
  IF NOT public.can_manage_sub_warehouse_stock() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันเติมสต๊อคคลังย่อย';
  END IF;

  SELECT * INTO v_request
  FROM public.wh_sub_warehouse_replenishment_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'ไม่พบคำขอเบิก';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'คำขอนี้ถูกดำเนินการแล้ว';
  END IF;

  SELECT COALESCE(NULLIF(BTRIM(username), ''), NULLIF(BTRIM(email), ''), v_request.requested_by::TEXT)
  INTO v_requester_name
  FROM public.us_users
  WHERE id = v_request.requested_by;

  INSERT INTO public.wh_sub_warehouse_stock_moves (
    sub_warehouse_id, product_id, qty_delta, reason, note, created_by,
    replenishment_request_id
  ) VALUES (
    v_request.sub_warehouse_id,
    v_request.product_id,
    v_request.requested_qty,
    'เติมสต๊อคตามคำขอ',
    'คำขอของ ' || COALESCE(v_requester_name, v_request.requested_by::TEXT),
    auth.uid(),
    v_request.id
  )
  RETURNING id INTO v_move_id;

  UPDATE public.wh_sub_warehouse_replenishment_requests
  SET status = 'fulfilled', fulfilled_by = auth.uid(), fulfilled_at = NOW(), updated_at = NOW()
  WHERE id = v_request.id;

  RETURN v_move_id;
END;
$$;


--
-- Name: rpc_generate_amendment_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_generate_amendment_no() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_today TEXT;
  v_seq   INT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('amendment_no_gen'));
  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(amendment_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM or_order_amendments
  WHERE amendment_no LIKE 'AM-' || v_today || '-%';

  RETURN 'AM-' || v_today || '-' || lpad(v_seq::text, 3, '0');
END;
$$;


--
-- Name: rpc_generate_pp_doc_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_generate_pp_doc_no() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_today TEXT;
  v_seq   INT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('pp_doc_no_gen'));

  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(doc_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM pp_production_orders
  WHERE doc_no LIKE 'PP-' || v_today || '-___';

  RETURN 'PP-' || v_today || '-' || lpad(v_seq::text, 3, '0');
END;
$$;


--
-- Name: rpc_get_audit_legacy_sub_warehouse_snapshots(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_audit_legacy_sub_warehouse_snapshots(p_audit_id uuid) RETURNS TABLE(item_id uuid, snapshot jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT i.id,public.fn_audit_sub_warehouse_snapshot(i.product_id,COALESCE(a.frozen_at,a.created_at))
  FROM public.inv_audit_items i JOIN public.inv_audits a ON a.id=i.audit_id
  WHERE a.id=p_audit_id AND i.sub_warehouse_snapshot IS NULL
  ORDER BY i.id;
$$;


--
-- Name: rpc_get_next_product_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_next_product_code(p_product_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_prefix TEXT;
  v_max_code BIGINT;
  v_next BIGINT;
BEGIN
  v_prefix := CASE UPPER(p_product_type)
    WHEN 'FG' THEN '11'
    WHEN 'RM' THEN '99'
    ELSE NULL
  END;

  IF v_prefix IS NULL THEN
    RAISE EXCEPTION 'รองรับเฉพาะ FG/RM';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('rpc_get_next_product_code:' || v_prefix));

  SELECT MAX(product_code::BIGINT)
  INTO v_max_code
  FROM pr_products
  WHERE product_code ~ '^[0-9]+$'
    AND LEFT(product_code, 2) = v_prefix;

  IF v_max_code IS NULL THEN
    v_next := (v_prefix || '0000001')::BIGINT;
  ELSE
    v_next := v_max_code + 1;
  END IF;

  RETURN v_next::TEXT;
END;
$_$;


--
-- Name: rpc_get_packing_wms_item_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_packing_wms_item_readiness(p_work_order_id uuid) RETURNS TABLE(order_item_id uuid, order_id uuid, picker_required boolean, picker_correct_qty numeric, expected_qty numeric, ready boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH active_items AS (
    SELECT
      oi.id AS order_item_id,
      o.id AS order_id,
      COALESCE(oi.quantity, 1)::NUMERIC AS expected_qty,
      UPPER(BTRIM(COALESCE(p.product_code::TEXT, ''))) AS product_code_key,
      CASE
        WHEN p.id IS NULL THEN 'system_complete'
        ELSE public.fn_wms_item_fulfillment_mode(p.id, p.product_category::TEXT)
      END AS current_mode
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id = o.id
    LEFT JOIN public.pr_products p ON p.id = oi.product_id
    WHERE o.work_order_id = p_work_order_id
      AND o.status <> 'ยกเลิก'
      AND NOT COALESCE(oi.is_detail_row, FALSE)
      AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
  ), item_groups AS (
    SELECT
      item.product_code_key,
      SUM(item.expected_qty)::NUMERIC AS expected_qty,
      BOOL_OR(item.current_mode = 'warehouse_pick') AS current_picker_required
    FROM active_items item
    GROUP BY item.product_code_key
  ), wms_groups AS (
    SELECT
      UPPER(BTRIM(COALESCE(w.product_code, ''))) AS product_code_key,
      COALESCE(SUM(w.qty) FILTER (WHERE w.status <> 'cancelled'), 0)::NUMERIC AS active_qty,
      COALESCE(SUM(w.qty) FILTER (WHERE w.status = 'correct'), 0)::NUMERIC AS correct_qty
    FROM public.wms_orders w
    WHERE w.work_order_id = p_work_order_id
    GROUP BY UPPER(BTRIM(COALESCE(w.product_code, '')))
  ), group_readiness AS (
    SELECT
      item.product_code_key,
      COALESCE(wms.correct_qty, 0)::NUMERIC AS correct_qty,
      item.current_picker_required AS picker_required,
      CASE
        WHEN NOT item.current_picker_required THEN TRUE
        WHEN COALESCE(wms.active_qty, 0) > 0
          THEN COALESCE(wms.correct_qty, 0) >= item.expected_qty
        ELSE FALSE
      END AS ready
    FROM item_groups item
    LEFT JOIN wms_groups wms ON wms.product_code_key = item.product_code_key
  )
  SELECT
    item.order_item_id,
    item.order_id,
    readiness.picker_required,
    CASE
      WHEN readiness.ready THEN item.expected_qty
      ELSE LEAST(readiness.correct_qty, item.expected_qty)
    END,
    item.expected_qty,
    readiness.ready
  FROM active_items item
  JOIN group_readiness readiness ON readiness.product_code_key = item.product_code_key
  ORDER BY item.order_id, item.order_item_id;
$$;


--
-- Name: FUNCTION rpc_get_packing_wms_item_readiness(p_work_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_get_packing_wms_item_readiness(p_work_order_id uuid) IS 'Returns per-item readiness; current automatic/non-picker products are ready even when an obsolete warehouse_pick snapshot exists.';


--
-- Name: rpc_get_packing_wms_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_packing_wms_readiness(p_work_order_id uuid) RETURNS TABLE(order_id uuid, picker_required_qty numeric, picker_correct_qty numeric, picker_missing_qty numeric, ready boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH active_items AS (
    SELECT
      o.id AS order_id,
      COALESCE(oi.quantity, 1)::NUMERIC AS expected_qty,
      UPPER(BTRIM(COALESCE(p.product_code::TEXT, ''))) AS product_code_key,
      public.fn_wms_item_fulfillment_mode(p.id, p.product_category::TEXT) AS current_mode
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id = o.id
    JOIN public.pr_products p ON p.id = oi.product_id
    WHERE o.work_order_id = p_work_order_id
      AND o.status <> 'ยกเลิก'
      AND NOT COALESCE(oi.is_detail_row, FALSE)
      AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
  ), item_groups AS (
    SELECT
      item.product_code_key,
      SUM(item.expected_qty)::NUMERIC AS expected_qty,
      BOOL_OR(item.current_mode = 'warehouse_pick') AS current_picker_required
    FROM active_items item
    GROUP BY item.product_code_key
  ), wms_groups AS (
    SELECT
      UPPER(BTRIM(COALESCE(w.product_code, ''))) AS product_code_key,
      COALESCE(SUM(w.qty) FILTER (WHERE w.status <> 'cancelled'), 0)::NUMERIC AS active_qty,
      COALESCE(SUM(w.qty) FILTER (WHERE w.status = 'correct'), 0)::NUMERIC AS correct_qty
    FROM public.wms_orders w
    WHERE w.work_order_id = p_work_order_id
    GROUP BY UPPER(BTRIM(COALESCE(w.product_code, '')))
  ), group_readiness AS (
    SELECT
      item.product_code_key,
      item.expected_qty,
      COALESCE(wms.correct_qty, 0)::NUMERIC AS correct_qty,
      item.current_picker_required AS picker_required,
      CASE
        WHEN NOT item.current_picker_required THEN TRUE
        WHEN COALESCE(wms.active_qty, 0) > 0
          THEN COALESCE(wms.correct_qty, 0) >= item.expected_qty
        ELSE FALSE
      END AS ready
    FROM item_groups item
    LEFT JOIN wms_groups wms ON wms.product_code_key = item.product_code_key
  ), per_item AS (
    SELECT item.*, readiness.picker_required, readiness.ready
    FROM active_items item
    JOIN group_readiness readiness ON readiness.product_code_key = item.product_code_key
  ), per_order AS (
    SELECT
      item.order_id,
      COALESCE(SUM(item.expected_qty) FILTER (WHERE item.picker_required), 0)::NUMERIC AS required_qty,
      COALESCE(SUM(
        CASE WHEN item.picker_required AND item.ready THEN item.expected_qty ELSE 0 END
      ), 0)::NUMERIC AS correct_qty,
      COALESCE(SUM(
        CASE WHEN item.picker_required AND NOT item.ready THEN item.expected_qty ELSE 0 END
      ), 0)::NUMERIC AS missing_qty,
      COALESCE(BOOL_AND(item.ready), TRUE) AS is_ready
    FROM per_item item
    GROUP BY item.order_id
  )
  SELECT
    o.id,
    COALESCE(summary.required_qty, 0),
    COALESCE(summary.correct_qty, 0),
    COALESCE(summary.missing_qty, 0),
    COALESCE(summary.is_ready, TRUE)
  FROM public.or_orders o
  LEFT JOIN per_order summary ON summary.order_id = o.id
  WHERE o.work_order_id = p_work_order_id
    AND o.status <> 'ยกเลิก'
  ORDER BY o.bill_no, o.id;
$$;


--
-- Name: rpc_get_pending_po_by_product(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_pending_po_by_product() RETURNS TABLE(product_id uuid, pending_qty numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT
    poi.product_id,
    SUM(
      GREATEST(
        COALESCE(poi.qty, 0)
        - COALESCE(poi.qty_received_total, 0)
        - COALESCE(poi.resolution_qty, 0),
        0
      )
    ) AS pending_qty
  FROM inv_po_items poi
  JOIN inv_po po ON po.id = poi.po_id
  WHERE po.status IN ('ordered', 'partial')
  GROUP BY poi.product_id
  HAVING SUM(
    GREATEST(
      COALESCE(poi.qty, 0)
      - COALESCE(poi.qty_received_total, 0)
      - COALESCE(poi.resolution_qty, 0),
      0
    )
  ) > 0;
$$;


--
-- Name: rpc_get_pending_po_details_by_product(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_pending_po_details_by_product() RETURNS TABLE(product_id uuid, pending_qty numeric, po_details jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  SELECT u.role
    INTO v_role
  FROM public.us_users AS u
  WHERE u.id = auth.uid()
    AND u.is_active IS TRUE;

  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account', 'store') THEN
    RAISE EXCEPTION 'Not authorized to view pending purchase orders';
  END IF;

  RETURN QUERY
  WITH outstanding AS (
    SELECT
      poi.product_id,
      po.id AS po_id,
      po.po_no,
      po.status,
      po.expected_arrival_date,
      GREATEST(
        COALESCE(poi.qty, 0)
        - COALESCE(poi.qty_received_total, 0)
        - COALESCE(poi.resolution_qty, 0),
        0
      ) AS item_pending_qty
    FROM public.inv_po_items AS poi
    JOIN public.inv_po AS po ON po.id = poi.po_id
    WHERE po.status IN ('open', 'ordered', 'partial')
  )
  SELECT
    outstanding.product_id,
    SUM(outstanding.item_pending_qty)::numeric AS pending_qty,
    jsonb_agg(
      jsonb_build_object(
        'po_id', outstanding.po_id,
        'po_no', outstanding.po_no,
        'status', outstanding.status,
        'pending_qty', outstanding.item_pending_qty,
        'expected_arrival_date', outstanding.expected_arrival_date
      )
      ORDER BY outstanding.po_no
    ) AS po_details
  FROM outstanding
  WHERE outstanding.item_pending_qty > 0
  GROUP BY outstanding.product_id;
END;
$$;


--
-- Name: rpc_get_plan_bill_name_edit_history(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_plan_bill_name_edit_history(p_work_order_ids uuid[]) RETURNS TABLE(log_id uuid, work_order_id uuid, order_id uuid, bill_no text, edited_by text, edited_at timestamp with time zone, changes jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    l.id,
    o.work_order_id,
    o.id,
    coalesce(l.bill_no, o.bill_no),
    l.edited_by,
    l.edited_at,
    filtered.changes
  FROM public.ac_bill_edit_logs l
  JOIN public.or_orders o ON o.id = l.order_id
  CROSS JOIN LATERAL (
    SELECT jsonb_agg(entry.value ORDER BY entry.ordinality) AS changes
    FROM jsonb_array_elements(coalesce(l.changes, '[]'::jsonb))
      WITH ORDINALITY AS entry(value, ordinality)
    WHERE coalesce(entry.value->>'field', '') ~ '^line_[123]:'
  ) filtered
  WHERE auth.uid() IS NOT NULL
    AND o.work_order_id = ANY(coalesce(p_work_order_ids, ARRAY[]::UUID[]))
    AND filtered.changes IS NOT NULL
  ORDER BY l.edited_at DESC;
$$;


--
-- Name: rpc_get_product_location_labels(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_product_location_labels(p_product_id uuid) RETURNS TABLE(label_type text, location_id uuid, code text, default_name text, display_name text, configured_name text, qty numeric, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH product_row AS (
    SELECT id, NULLIF(BTRIM(storage_location), '') AS legacy_location
    FROM public.pr_products
    WHERE id = p_product_id
  )
  SELECT
    'movement'::TEXT,
    NULL::UUID,
    'MOVEMENT'::TEXT,
    'Movement'::TEXT,
    COALESCE(label.display_name, product_row.legacy_location, 'Movement')::TEXT,
    label.display_name::TEXT,
    COALESCE(balance.on_hand, 0)::NUMERIC,
    -200
  FROM product_row
  LEFT JOIN public.wh_product_location_labels label
    ON label.product_id = product_row.id AND label.label_type = 'movement'
  LEFT JOIN public.inv_stock_balances balance ON balance.product_id = product_row.id

  UNION ALL

  SELECT
    'storage'::TEXT,
    location.id,
    location.code::TEXT,
    COALESCE(NULLIF(BTRIM(location.name), ''), location.code)::TEXT,
    COALESCE(label.display_name, NULLIF(BTRIM(location.name), ''), location.code)::TEXT,
    label.display_name::TEXT,
    COALESCE(stock.qty, 0)::NUMERIC,
    location.sort_order
  FROM public.wh_storage_locations location
  CROSS JOIN product_row
  LEFT JOIN public.wh_product_location_labels label
    ON label.product_id = product_row.id
   AND label.label_type = 'storage'
   AND label.location_id = location.id
  LEFT JOIN public.wh_location_stock stock
    ON stock.product_id = product_row.id AND stock.location_id = location.id
  WHERE location.is_active

  UNION ALL

  SELECT
    'safety'::TEXT,
    NULL::UUID,
    'SAFETY'::TEXT,
    'Safety stock'::TEXT,
    COALESCE(label.display_name, 'Safety stock')::TEXT,
    label.display_name::TEXT,
    COALESCE(balance.safety_stock, 0)::NUMERIC,
    2000000000
  FROM product_row
  LEFT JOIN public.wh_product_location_labels label
    ON label.product_id = product_row.id AND label.label_type = 'safety'
  LEFT JOIN public.inv_stock_balances balance ON balance.product_id = product_row.id

  -- UNION output columns must be referenced by output position here.
  ORDER BY 8, 3;
$$;


--
-- Name: rpc_get_product_location_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_product_location_summary(p_product_id uuid) RETURNS TABLE(location_id uuid, code text, name text, location_type text, qty numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    location.id,
    location.code,
    COALESCE(label.display_name, location.name),
    location.location_type,
    COALESCE(stock.qty, 0)
  FROM public.wh_storage_locations location
  LEFT JOIN public.wh_location_stock stock
    ON stock.location_id = location.id AND stock.product_id = p_product_id
  LEFT JOIN public.wh_product_location_labels label
    ON label.product_id = p_product_id
   AND label.label_type = 'storage'
   AND label.location_id = location.id
  WHERE location.is_active AND COALESCE(stock.qty, 0) <> 0
  ORDER BY CASE location.location_type WHEN 'picking' THEN 0 WHEN 'reserve' THEN 1 WHEN 'hold' THEN 2 ELSE 3 END,
           location.sort_order, location.code;
$$;


--
-- Name: rpc_get_product_reservations(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_product_reservations(p_product_ids uuid[]) RETURNS TABLE(source_type text, source_id uuid, document_type text, document_no text, source_document_no text, customer_name text, owner_name text, product_id uuid, qty numeric, expires_on date, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'กรุณาเข้าสู่ระบบ'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.us_users u WHERE u.id=auth.uid()
    AND (u.role IN ('superadmin','admin','sales-tr','store','account','production','manager')
      OR EXISTS(SELECT 1 FROM public.st_user_menus m WHERE m.role=u.role AND m.menu_key IN ('warehouse','warehouse-stock') AND m.has_access))) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดูรายการจองคลัง' USING ERRCODE='42501';
  END IF;
  PERFORM public.fn_expire_document_reservations();
  RETURN QUERY
  SELECT 'prebill'::text,d.id,CASE d.document_type WHEN 'quotation' THEN 'QT' ELSE 'PC' END,
    d.document_no,NULL::text,d.customer_name,d.owner_name,r.product_id,r.qty,d.valid_until,d.status
  FROM public.inv_document_reservations r JOIN public.or_prebill_documents d ON d.id=r.source_id
  WHERE r.source_type='prebill' AND r.qty>0 AND r.product_id=ANY(p_product_ids)
  UNION ALL
  SELECT 'order',o.id,CASE WHEN o.bill_no LIKE 'REQ%' THEN 'claim' ELSE 'sale' END,
    o.bill_no,d.document_no,o.customer_name,o.admin_user,r.product_id,r.qty,NULL::date,o.status
  FROM public.inv_document_reservations r JOIN public.or_orders o ON o.id=r.source_id
  LEFT JOIN public.or_prebill_documents d ON d.id=o.source_prebill_document_id
  WHERE r.source_type='order' AND r.qty>0 AND r.product_id=ANY(p_product_ids)
  UNION ALL
  SELECT CASE WHEN o.id IS NULL THEN 'wms' ELSE 'order' END,coalesce(o.id,w.id),
    CASE WHEN o.id IS NULL THEN 'wms' WHEN o.bill_no LIKE 'REQ%' THEN 'claim' ELSE 'sale' END,
    coalesce(o.bill_no,w.order_id),d.document_no,coalesce(o.customer_name,'-'),coalesce(o.admin_user,'-'),
    p.id,w.qty,NULL::date,CASE WHEN w.status='cancelled' THEN 'cancelled_pending_stock' ELSE 'picked' END
  FROM public.wms_orders w JOIN public.pr_products p ON p.product_code=w.product_code
  LEFT JOIN public.or_orders o ON o.id=coalesce(w.source_order_id,(SELECT i.order_id FROM public.or_order_items i WHERE i.id=w.source_order_item_id))
  LEFT JOIN public.or_prebill_documents d ON d.id=o.source_prebill_document_id
  WHERE p.id=ANY(p_product_ids) AND (w.status='picked' OR (w.status='cancelled' AND w.status_before_cancel='picked' AND w.stock_action IS NULL))
  UNION ALL
  SELECT 'borrow',b.id,'borrow',b.borrow_no,NULL::text,'-',coalesce(u.username,u.email,'-'),
    i.product_id,greatest(i.qty-coalesce(i.returned_qty,0)-coalesce(i.written_off_qty,0),0),b.due_date,b.status
  FROM public.wms_borrow_requisition_items i JOIN public.wms_borrow_requisitions b ON b.id=i.borrow_requisition_id
  LEFT JOIN public.us_users u ON u.id=b.created_by
  WHERE i.product_id=ANY(p_product_ids) AND b.status IN ('approved','partial_returned','overdue')
    AND i.qty-coalesce(i.returned_qty,0)-coalesce(i.written_off_qty,0)>0;
END $$;


--
-- Name: rpc_get_product_transfer_history(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_product_transfer_history(p_product_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(id uuid, transfer_no text, created_at timestamp with time zone, posted_at timestamp with time zone, from_code text, to_code text, qty numeric, status text, created_by_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT transfer.id, transfer.transfer_no, transfer.created_at, transfer.posted_at,
         source.code, destination.code, item.qty, transfer.status,
         COALESCE(NULLIF(BTRIM(author.username),''), author.email, transfer.created_by::TEXT)
  FROM public.wh_stock_transfer_items item
  JOIN public.wh_stock_transfers transfer ON transfer.id=item.transfer_id
  JOIN public.wh_storage_locations source ON source.id=transfer.from_location_id
  JOIN public.wh_storage_locations destination ON destination.id=transfer.to_location_id
  LEFT JOIN public.us_users author ON author.id=transfer.created_by
  WHERE item.product_id=p_product_id AND transfer.status='posted'
  ORDER BY COALESCE(transfer.posted_at, transfer.created_at) DESC, transfer.id DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit,5),1),100);
$$;


--
-- Name: rpc_get_reservation_stock(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_reservation_stock(p_type text DEFAULT NULL::text, p_source uuid DEFAULT NULL::uuid) RETURNS TABLE(product_id uuid, on_hand numeric, reserved numeric, safety_stock numeric, own_reserved numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'กรุณาเข้าสู่ระบบ'; END IF;
  PERFORM public.fn_expire_document_reservations();
  -- Prebill ownership follows the existing team visibility policy.
  IF p_source IS NOT NULL THEN
    IF p_type='prebill' AND NOT public.can_manage_prebill_document((SELECT owner_id FROM public.or_prebill_documents WHERE id=p_source)) THEN
      RAISE EXCEPTION 'ไม่มีสิทธิ์ดูเอกสาร';
    END IF;
  END IF;
  RETURN QUERY SELECT b.product_id,b.on_hand,b.reserved,b.safety_stock,
    coalesce((SELECT sum(r.qty) FROM public.inv_document_reservations r WHERE r.product_id=b.product_id AND r.source_type=p_type AND r.source_id=p_source),0)
    +CASE WHEN p_type='order' AND EXISTS(SELECT 1 FROM public.or_orders o WHERE o.id=p_source AND o.stock_reservation_enabled) THEN coalesce((SELECT sum(w.qty) FROM public.wms_orders w
      JOIN public.or_order_items i ON i.id=w.source_order_item_id
      WHERE i.order_id=p_source AND i.product_id=b.product_id AND w.status IN ('picked','correct')),0) ELSE 0 END
  FROM public.inv_stock_balances b ORDER BY b.product_id;
END $$;


--
-- Name: rpc_get_sub_warehouse_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_sub_warehouse_balances(p_sub_warehouse_id uuid) RETURNS TABLE(product_id uuid, product_code text, product_name text, unit_name text, qty_on_hand numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.product_code, p.product_name, p.unit_name, COALESCE(balance.qty_on_hand, 0)
  FROM public.wh_sub_warehouse_products assigned
  JOIN public.pr_products p ON p.id = assigned.product_id
  LEFT JOIN public.wh_sub_warehouse_balances balance
    ON balance.sub_warehouse_id = assigned.sub_warehouse_id
   AND balance.product_id = assigned.product_id
  WHERE assigned.sub_warehouse_id = p_sub_warehouse_id
  ORDER BY assigned.sort_order, assigned.created_at, p.product_code;
$$;


--
-- Name: rpc_get_sub_warehouse_daily_stock_sheet(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_sub_warehouse_daily_stock_sheet(p_sub_warehouse_id uuid, p_date date) RETURNS TABLE(product_id uuid, product_code text, product_name text, unit_name text, received_opening numeric, replenish_day numeric, reduce_day numeric, wms_opening numeric, wms_day numeric, balance_opening numeric, balance_eod numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH bounds AS (
    SELECT
      make_timestamptz(EXTRACT(YEAR FROM p_date)::INT,EXTRACT(MONTH FROM p_date)::INT,
        EXTRACT(DAY FROM p_date)::INT,0,0,0,'Asia/Bangkok') AS day_start,
      make_timestamptz(EXTRACT(YEAR FROM p_date)::INT,EXTRACT(MONTH FROM p_date)::INT,
        EXTRACT(DAY FROM p_date)::INT,0,0,0,'Asia/Bangkok')+INTERVAL '1 day' AS day_end_excl
  ), groups_scope AS (
    SELECT map_group.id FROM public.wh_sub_wms_map_groups map_group
    WHERE map_group.sub_warehouse_id IS NULL OR map_group.sub_warehouse_id=p_sub_warehouse_id
  ), wms_usage AS (
    SELECT wms.product_code,wms.qty,
      COALESCE(
        summary.checked_at,
        completion.completed_at,
        CASE WHEN wms.fulfillment_mode IN ('system_complete','sub_warehouse_skip') THEN wms.end_time END
      ) AS used_at,
      CASE
        WHEN requisition.id IS NOT NULL OR UPPER(BTRIM(COALESCE(wms.order_id,''))) LIKE 'REQ-%' THEN 'requisition'
        WHEN wms.work_order_id IS NOT NULL OR EXISTS (
          SELECT 1 FROM public.or_orders sales_order
          WHERE BTRIM(COALESCE(sales_order.work_order_name,''))=BTRIM(COALESCE(wms.order_id,''))
        ) THEN 'work_order'
        ELSE 'other'
      END AS usage_source
    FROM public.wms_orders wms
    LEFT JOIN public.wms_requisitions requisition ON requisition.requisition_id=wms.order_id
    LEFT JOIN LATERAL (
      SELECT wms_summary.checked_at FROM public.wms_order_summaries wms_summary
      WHERE BTRIM(wms_summary.order_id)=BTRIM(wms.order_id)
      ORDER BY wms_summary.checked_at LIMIT 1
    ) summary ON TRUE
    LEFT JOIN LATERAL (
      SELECT work_order.wms_review_completed_at AS completed_at
      FROM public.or_work_orders work_order
      WHERE work_order.id=wms.work_order_id
         OR (wms.work_order_id IS NULL AND BTRIM(work_order.work_order_name)=BTRIM(wms.order_id))
      ORDER BY (work_order.id=wms.work_order_id) DESC,work_order.created_at DESC
      LIMIT 1
    ) completion ON TRUE
    WHERE wms.status='correct'
  ), group_wms_open AS (
    SELECT source.group_id,COALESCE(SUM(usage.qty),0)::NUMERIC qty
    FROM public.wh_sub_wms_map_sources source
    JOIN groups_scope ON groups_scope.id=source.group_id
    JOIN public.pr_products product_source ON product_source.id=source.product_id
    JOIN wms_usage usage ON usage.product_code::TEXT=product_source.product_code::TEXT
    CROSS JOIN bounds
    WHERE usage.usage_source='work_order' AND usage.used_at<bounds.day_start
    GROUP BY source.group_id
  ), group_wms_day AS (
    SELECT source.group_id,COALESCE(SUM(usage.qty),0)::NUMERIC qty
    FROM public.wh_sub_wms_map_sources source
    JOIN groups_scope ON groups_scope.id=source.group_id
    JOIN public.pr_products product_source ON product_source.id=source.product_id
    JOIN wms_usage usage ON usage.product_code::TEXT=product_source.product_code::TEXT
    CROSS JOIN bounds
    WHERE usage.usage_source='work_order'
      AND usage.used_at>=bounds.day_start AND usage.used_at<bounds.day_end_excl
    GROUP BY source.group_id
  ), spare_group AS (
    SELECT spare.product_id,spare.group_id FROM public.wh_sub_wms_map_spares spare
    JOIN groups_scope ON groups_scope.id=spare.group_id
  ), products AS (
    SELECT assigned.product_id,product.product_code,product.product_name,product.unit_name
    FROM public.wh_sub_warehouse_products assigned
    JOIN public.pr_products product ON product.id=assigned.product_id
    WHERE assigned.sub_warehouse_id=p_sub_warehouse_id
  ), recv_open AS (
    SELECT movement.product_id,COALESCE(SUM(movement.qty_delta),0)::NUMERIC qty
    FROM public.wh_sub_warehouse_stock_moves movement CROSS JOIN bounds
    WHERE movement.sub_warehouse_id=p_sub_warehouse_id AND movement.created_at<bounds.day_start
    GROUP BY movement.product_id
  ), recv_day AS (
    SELECT movement.product_id,
      COALESCE(SUM(CASE WHEN movement.qty_delta>0 THEN movement.qty_delta ELSE 0 END),0)::NUMERIC replenish,
      COALESCE(SUM(CASE WHEN movement.qty_delta<0 THEN movement.qty_delta ELSE 0 END),0)::NUMERIC reduce_sum
    FROM public.wh_sub_warehouse_stock_moves movement CROSS JOIN bounds
    WHERE movement.sub_warehouse_id=p_sub_warehouse_id
      AND movement.created_at>=bounds.day_start AND movement.created_at<bounds.day_end_excl
    GROUP BY movement.product_id
  ), wms_open AS (
    SELECT usage.product_code::TEXT,COALESCE(SUM(usage.qty),0)::NUMERIC qty
    FROM wms_usage usage CROSS JOIN bounds
    WHERE usage.usage_source='work_order' AND usage.used_at<bounds.day_start
    GROUP BY usage.product_code
  ), wms_day_tbl AS (
    SELECT usage.product_code::TEXT,COALESCE(SUM(usage.qty),0)::NUMERIC qty
    FROM wms_usage usage CROSS JOIN bounds
    WHERE usage.usage_source='work_order'
      AND usage.used_at>=bounds.day_start AND usage.used_at<bounds.day_end_excl
    GROUP BY usage.product_code
  )
  SELECT product_row.product_id,product_row.product_code,product_row.product_name,product_row.unit_name,
    COALESCE(recv_open.qty,0)::NUMERIC,COALESCE(recv_day.replenish,0)::NUMERIC,
    COALESCE(recv_day.reduce_sum,0)::NUMERIC,
    (CASE WHEN spare_group.group_id IS NOT NULL THEN COALESCE(group_open.qty,0) ELSE COALESCE(wms_open.qty,0) END)::NUMERIC,
    (CASE WHEN spare_group.group_id IS NOT NULL THEN COALESCE(group_day.qty,0) ELSE COALESCE(wms_day.qty,0) END)::NUMERIC,
    (COALESCE(recv_open.qty,0)-CASE WHEN spare_group.group_id IS NOT NULL THEN COALESCE(group_open.qty,0) ELSE COALESCE(wms_open.qty,0) END)::NUMERIC,
    ((COALESCE(recv_open.qty,0)+COALESCE(recv_day.replenish,0)+COALESCE(recv_day.reduce_sum,0))
      -(CASE WHEN spare_group.group_id IS NOT NULL THEN COALESCE(group_open.qty,0) ELSE COALESCE(wms_open.qty,0) END)
      -(CASE WHEN spare_group.group_id IS NOT NULL THEN COALESCE(group_day.qty,0) ELSE COALESCE(wms_day.qty,0) END))::NUMERIC
  FROM products product_row
  LEFT JOIN spare_group ON spare_group.product_id=product_row.product_id
  LEFT JOIN group_wms_open group_open ON group_open.group_id=spare_group.group_id
  LEFT JOIN group_wms_day group_day ON group_day.group_id=spare_group.group_id
  LEFT JOIN recv_open ON recv_open.product_id=product_row.product_id
  LEFT JOIN recv_day ON recv_day.product_id=product_row.product_id
  LEFT JOIN wms_open ON wms_open.product_code=product_row.product_code
  LEFT JOIN wms_day_tbl wms_day ON wms_day.product_code=product_row.product_code
  ORDER BY product_row.product_code;
$$;


--
-- Name: rpc_get_sub_warehouse_moves(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_sub_warehouse_moves(p_sub_warehouse_id uuid, p_date_from date, p_date_to date, p_product_code text DEFAULT NULL::text) RETURNS TABLE(id uuid, created_at timestamp with time zone, created_by uuid, created_by_name text, product_id uuid, product_code text, product_name text, unit_name text, qty_delta numeric, reason text, note text, balance_after numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH bounds AS (
    SELECT
      make_timestamptz(EXTRACT(YEAR FROM p_date_from)::INT, EXTRACT(MONTH FROM p_date_from)::INT,
        EXTRACT(DAY FROM p_date_from)::INT, 0, 0, 0, 'Asia/Bangkok') AS range_start,
      make_timestamptz(EXTRACT(YEAR FROM p_date_to)::INT, EXTRACT(MONTH FROM p_date_to)::INT,
        EXTRACT(DAY FROM p_date_to)::INT, 0, 0, 0, 'Asia/Bangkok') + INTERVAL '1 day' AS range_end_excl
  ), ranked AS (
    SELECT movement.*, product.product_code, product.product_name, product.unit_name,
      COALESCE(NULLIF(BTRIM(actor.username), ''), NULLIF(BTRIM(actor.email), ''), movement.created_by::TEXT) AS actor_name,
      SUM(movement.qty_delta) OVER (
        PARTITION BY movement.product_id
        ORDER BY movement.created_at, movement.id
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
      ) AS running_balance
    FROM public.wh_sub_warehouse_stock_moves movement
    JOIN public.pr_products product ON product.id = movement.product_id
    LEFT JOIN public.us_users actor ON actor.id = movement.created_by
    WHERE movement.sub_warehouse_id = p_sub_warehouse_id
  )
  SELECT ranked.id, ranked.created_at, ranked.created_by, ranked.actor_name,
    ranked.product_id, ranked.product_code, ranked.product_name, ranked.unit_name,
    ranked.qty_delta, ranked.reason, ranked.note, ranked.running_balance
  FROM ranked CROSS JOIN bounds
  WHERE ranked.created_at >= bounds.range_start
    AND ranked.created_at < bounds.range_end_excl
    AND (
      p_product_code IS NULL OR BTRIM(p_product_code) = ''
      OR ranked.product_code ILIKE ('%' || BTRIM(p_product_code) || '%')
      OR ranked.product_name ILIKE ('%' || BTRIM(p_product_code) || '%')
    )
  ORDER BY ranked.created_at DESC, ranked.id DESC;
$$;


--
-- Name: rpc_get_sub_warehouse_other_wms_details(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_sub_warehouse_other_wms_details(p_sub_warehouse_id uuid, p_product_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(wms_order_id uuid, order_reference text, product_code text, product_name text, qty numeric, unit_name text, used_at timestamp with time zone, fulfillment_mode text, picker_name text, classification_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH groups_scope AS (
    SELECT g.id
    FROM public.wh_sub_wms_map_groups g
    WHERE g.sub_warehouse_id IS NULL
       OR g.sub_warehouse_id = p_sub_warehouse_id
  ), matched_groups AS (
    SELECT DISTINCT sp.group_id
    FROM public.wh_sub_wms_map_spares sp
    JOIN groups_scope gs ON gs.id = sp.group_id
    WHERE sp.product_id = p_product_id
  ), target_codes AS (
    SELECT p.product_code::TEXT AS product_code
    FROM public.wh_sub_wms_map_sources src
    JOIN matched_groups mg ON mg.group_id = src.group_id
    JOIN public.pr_products p ON p.id = src.product_id
    UNION ALL
    SELECT p.product_code::TEXT
    FROM public.pr_products p
    WHERE p.id = p_product_id
      AND NOT EXISTS (SELECT 1 FROM matched_groups)
  ), usage AS (
    SELECT
      w.id,
      w.order_id,
      w.product_code,
      w.product_name,
      COALESCE(w.qty, 0)::NUMERIC AS qty,
      w.unit_name,
      COALESCE(
        s.checked_at,
        CASE
          WHEN w.fulfillment_mode IN ('system_complete', 'sub_warehouse_skip') THEN w.end_time
        END
      ) AS used_at,
      w.fulfillment_mode,
      picker.username::TEXT AS picker_name,
      r.id AS requisition_id,
      w.work_order_id,
      EXISTS (
        SELECT 1
        FROM public.or_orders o
        WHERE BTRIM(COALESCE(o.work_order_name, '')) = BTRIM(COALESCE(w.order_id, ''))
      ) AS has_work_order
    FROM public.wms_orders w
    JOIN target_codes tc ON tc.product_code = w.product_code::TEXT
    LEFT JOIN public.wms_requisitions r ON r.requisition_id = w.order_id
    LEFT JOIN public.us_users picker ON picker.id = w.assigned_to
    LEFT JOIN LATERAL (
      SELECT ws.checked_at
      FROM public.wms_order_summaries ws
      WHERE ws.order_id = w.order_id
      ORDER BY ws.checked_at
      LIMIT 1
    ) s ON TRUE
    WHERE auth.uid() IS NOT NULL
      AND w.status = 'correct'
  )
  SELECT
    u.id,
    u.order_id,
    u.product_code,
    u.product_name,
    u.qty,
    u.unit_name,
    u.used_at,
    u.fulfillment_mode,
    u.picker_name,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(u.order_id, '')), '') IS NULL
        THEN 'ไม่มีเลขอ้างอิง WMS'
      ELSE 'ไม่พบใบงานหรือใบเบิกที่ตรงกับเลขอ้างอิง'
    END
  FROM usage u
  WHERE u.used_at >= p_from
    AND u.used_at <= p_to
    AND u.requisition_id IS NULL
    AND UPPER(BTRIM(COALESCE(u.order_id, ''))) NOT LIKE 'REQ-%'
    AND u.work_order_id IS NULL
    AND NOT u.has_work_order
  ORDER BY u.used_at DESC, u.order_id, u.product_code;
$$;


--
-- Name: rpc_get_sub_warehouse_replenishment_requests(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_sub_warehouse_replenishment_requests(p_sub_warehouse_id uuid) RETURNS TABLE(id uuid, sub_warehouse_id uuid, product_id uuid, product_code text, product_name text, unit_name text, requested_qty numeric, status text, requested_by uuid, requester_name text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    request.id,
    request.sub_warehouse_id,
    request.product_id,
    product.product_code,
    product.product_name,
    product.unit_name,
    request.requested_qty,
    request.status,
    request.requested_by,
    COALESCE(NULLIF(BTRIM(requester.username), ''), NULLIF(BTRIM(requester.email), ''), request.requested_by::TEXT),
    request.created_at,
    request.updated_at
  FROM public.wh_sub_warehouse_replenishment_requests request
  JOIN public.pr_products product ON product.id = request.product_id
  LEFT JOIN public.us_users requester ON requester.id = request.requested_by
  WHERE request.sub_warehouse_id = p_sub_warehouse_id
    AND request.status = 'pending'
    AND (
      public.can_manage_sub_warehouse_stock()
      OR (public.can_request_sub_warehouse_stock() AND request.requested_by = auth.uid())
    )
  ORDER BY request.created_at, request.id;
$$;


--
-- Name: rpc_get_warehouse_fifo_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_warehouse_fifo_status() RETURNS TABLE(product_id uuid, sellable_lot_count bigint, sellable_lot_qty numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT u.role
    INTO v_role
    FROM public.us_users u
    WHERE u.id = auth.uid()
      AND u.is_active IS TRUE;

    IF v_role IS NULL THEN
      RAISE EXCEPTION 'Not authorized to view warehouse FIFO status';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    p.id AS product_id,
    COUNT(l.id) FILTER (
      WHERE l.qty_remaining > 0
        AND COALESCE(l.is_safety_stock, FALSE) IS FALSE
    ) AS sellable_lot_count,
    COALESCE(
      SUM(l.qty_remaining) FILTER (
        WHERE l.qty_remaining > 0
          AND COALESCE(l.is_safety_stock, FALSE) IS FALSE
      ),
      0
    ) AS sellable_lot_qty
  FROM public.pr_products p
  LEFT JOIN public.inv_stock_lots l
    ON l.product_id = p.id
  WHERE p.is_active IS TRUE
  GROUP BY p.id;
END;
$$;


--
-- Name: FUNCTION rpc_get_warehouse_fifo_status(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_get_warehouse_fifo_status() IS 'Returns only active normal FIFO lot counts and quantities for warehouse indicators; never exposes lot costs.';


--
-- Name: rpc_get_wms_correct_qty_by_product(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_wms_correct_qty_by_product(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(product_code text, correct_qty numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH usage AS (
    SELECT
      w.product_code,
      COALESCE(w.qty, 0)::NUMERIC AS qty,
      COALESCE(
        summary.checked_at,
        completion.completed_at,
        CASE
          WHEN w.fulfillment_mode IN ('system_complete', 'sub_warehouse_skip') THEN w.end_time
        END
      ) AS used_at
    FROM public.wms_orders w
    LEFT JOIN LATERAL (
      SELECT ws.checked_at
      FROM public.wms_order_summaries ws
      WHERE BTRIM(ws.order_id) = BTRIM(w.order_id)
      ORDER BY ws.checked_at
      LIMIT 1
    ) summary ON TRUE
    LEFT JOIN LATERAL (
      SELECT wo.wms_review_completed_at AS completed_at
      FROM public.or_work_orders wo
      WHERE wo.id = w.work_order_id
         OR (w.work_order_id IS NULL AND BTRIM(wo.work_order_name) = BTRIM(w.order_id))
      ORDER BY (wo.id = w.work_order_id) DESC, wo.created_at DESC
      LIMIT 1
    ) completion ON TRUE
    WHERE w.status = 'correct'
  )
  SELECT usage.product_code, COALESCE(SUM(usage.qty), 0)::NUMERIC
  FROM usage
  WHERE usage.used_at >= p_from AND usage.used_at <= p_to
  GROUP BY usage.product_code
  ORDER BY usage.product_code;
$$;


--
-- Name: rpc_get_wms_stock_anomalies(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_wms_stock_anomalies(p_from_date date, p_to_date date) RETURNS TABLE(order_item_id uuid, order_id uuid, bill_no text, entry_date date, work_order_id uuid, work_order_name text, product_code text, product_name text, unit_name text, expected_qty numeric, wms_qty numeric, correct_qty numeric, deducted_qty numeric, anomaly_type text, repairable boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT oi.id order_item_id,o.id order_id,o.bill_no,o.entry_date,o.work_order_id,o.work_order_name,
      p.product_code::TEXT,oi.product_name,COALESCE(NULLIF(BTRIM(p.unit_name::TEXT),''),'ชิ้น') unit_name,
      COALESCE(oi.quantity,1)::NUMERIC expected_qty
    FROM public.or_orders o
    JOIN public.or_order_items oi ON oi.order_id=o.id
    JOIN public.pr_products p ON p.id=oi.product_id
    WHERE o.entry_date BETWEEN p_from_date AND p_to_date
      AND EXISTS (SELECT 1 FROM public.us_users au WHERE au.id=auth.uid()
        AND au.role IN ('superadmin','admin','store','manager'))
      AND o.status='จัดส่งแล้ว' AND NOT COALESCE(oi.is_detail_row,false)
      AND COALESCE(oi.cancellation_stock_action,'')<>'recalled'
      AND o.work_order_id IS NOT NULL
  ), wms_agg AS (
    SELECT w.source_order_item_id,
      SUM(w.qty) FILTER (WHERE w.status<>'cancelled') wms_qty,
      SUM(w.qty) FILTER (WHERE w.status='correct') correct_qty
    FROM public.wms_orders w WHERE w.source_order_item_id IS NOT NULL
    GROUP BY w.source_order_item_id
  ), movement_agg AS (
    SELECT w.source_order_item_id,
      SUM(-m.qty) FILTER (WHERE m.movement_type IN ('pick','pick_reversal')) stock_qty,
      COUNT(*) FILTER (WHERE m.movement_type='pick_reversal') reversal_count
    FROM public.wms_orders w
    JOIN public.inv_stock_movements m ON m.ref_type='wms_orders' AND m.ref_id=w.id
    WHERE w.source_order_item_id IS NOT NULL
    GROUP BY w.source_order_item_id
  ), agg AS (
    SELECT b.*,COALESCE(w.wms_qty,0) wms_qty,COALESCE(w.correct_qty,0) correct_qty,
      COALESCE(m.stock_qty,0) deducted_qty,COALESCE(m.reversal_count,0) reversal_count,
      public.fn_wms_item_has_unlinked_legacy_conflict(b.order_item_id) legacy_conflict
    FROM base b
    LEFT JOIN wms_agg w ON w.source_order_item_id=b.order_item_id
    LEFT JOIN movement_agg m ON m.source_order_item_id=b.order_item_id
  )
  SELECT a.order_item_id,a.order_id,a.bill_no,a.entry_date,a.work_order_id,a.work_order_name,
    a.product_code,a.product_name,a.unit_name,a.expected_qty,a.wms_qty,a.correct_qty,a.deducted_qty,
    CASE WHEN a.legacy_conflict THEN 'legacy_conflict'
         WHEN a.wms_qty<a.expected_qty THEN 'missing_wms'
         WHEN a.wms_qty>a.expected_qty THEN 'excess_wms'
         WHEN a.correct_qty<>a.expected_qty THEN 'not_correct'
         WHEN a.correct_qty<>a.deducted_qty THEN 'stock_movement_mismatch'
         ELSE 'unknown' END,
    CASE
      WHEN a.wms_qty<a.expected_qty AND NOT public.fn_wms_item_has_legacy_stock_conflict(a.order_item_id) THEN true
      WHEN a.wms_qty=a.expected_qty AND a.correct_qty=a.expected_qty
        AND a.deducted_qty>a.correct_qty AND a.reversal_count=0 AND NOT a.legacy_conflict THEN true
      ELSE false
    END
  FROM agg a
  WHERE a.wms_qty<>a.expected_qty OR a.correct_qty<>a.expected_qty
    OR a.correct_qty<>a.deducted_qty OR a.legacy_conflict
  ORDER BY a.entry_date DESC,a.bill_no,a.product_code;
$$;


--
-- Name: rpc_get_wms_usage_breakdown_by_product(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_wms_usage_breakdown_by_product(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(product_code text, correct_qty numeric, work_order_qty numeric, requisition_qty numeric, other_qty numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH usage AS (
    SELECT
      w.product_code,
      COALESCE(w.qty, 0)::NUMERIC AS qty,
      COALESCE(
        summary.checked_at,
        completion.completed_at,
        CASE
          WHEN w.fulfillment_mode IN ('system_complete', 'sub_warehouse_skip') THEN w.end_time
        END
      ) AS used_at,
      CASE
        WHEN requisition.id IS NOT NULL OR UPPER(BTRIM(COALESCE(w.order_id, ''))) LIKE 'REQ-%'
          THEN 'requisition'
        WHEN w.work_order_id IS NOT NULL
          OR EXISTS (
            SELECT 1 FROM public.or_orders sales_order
            WHERE BTRIM(COALESCE(sales_order.work_order_name, '')) = BTRIM(COALESCE(w.order_id, ''))
          ) THEN 'work_order'
        ELSE 'other'
      END AS usage_source
    FROM public.wms_orders w
    LEFT JOIN public.wms_requisitions requisition ON requisition.requisition_id = w.order_id
    LEFT JOIN LATERAL (
      SELECT ws.checked_at
      FROM public.wms_order_summaries ws
      WHERE BTRIM(ws.order_id) = BTRIM(w.order_id)
      ORDER BY ws.checked_at
      LIMIT 1
    ) summary ON TRUE
    LEFT JOIN LATERAL (
      SELECT wo.wms_review_completed_at AS completed_at
      FROM public.or_work_orders wo
      WHERE wo.id = w.work_order_id
         OR (w.work_order_id IS NULL AND BTRIM(wo.work_order_name) = BTRIM(w.order_id))
      ORDER BY (wo.id = w.work_order_id) DESC, wo.created_at DESC
      LIMIT 1
    ) completion ON TRUE
    WHERE w.status = 'correct'
  )
  SELECT
    usage.product_code,
    COALESCE(SUM(usage.qty), 0)::NUMERIC,
    COALESCE(SUM(usage.qty) FILTER (WHERE usage.usage_source = 'work_order'), 0)::NUMERIC,
    COALESCE(SUM(usage.qty) FILTER (WHERE usage.usage_source = 'requisition'), 0)::NUMERIC,
    COALESCE(SUM(usage.qty) FILTER (WHERE usage.usage_source = 'other'), 0)::NUMERIC
  FROM usage
  WHERE usage.used_at >= p_from AND usage.used_at <= p_to
  GROUP BY usage.product_code
  ORDER BY usage.product_code;
$$;


--
-- Name: rpc_import_products(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_import_products(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  item jsonb;
  product public.pr_products%ROWTYPE;
  v_id uuid;
  v_inserted integer := 0;
  v_updated integer := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid() AND role = 'superadmin' AND is_active IS TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'เฉพาะ superadmin ที่เปิดใช้งานเท่านั้นที่นำเข้าสินค้าได้';
  END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'ข้อมูลนำเข้าต้องเป็นรายการสินค้า';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) x
    GROUP BY lower(btrim(x->>'product_code')) HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'รหัสสินค้าซ้ำในรายการนำเข้า';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_items) ORDER BY value->>'product_code' LOOP
    -- Whitelist writable fields below; payload IDs and stock/cost metadata
    -- cannot overwrite existing records outside the import template.
    product := jsonb_populate_record(NULL::public.pr_products, item);
    product.product_code := btrim(product.product_code);
    product.product_name := btrim(product.product_name);
    product.product_type := coalesce(nullif(product.product_type, ''), 'FG');
    product.unit_name := coalesce(nullif(btrim(product.unit_name), ''), 'ชิ้น');
    product.unit_multiplier := coalesce(product.unit_multiplier, 1);
    product.unit_cost := coalesce(product.unit_cost, 0);
    IF coalesce(product.product_code, '') = '' OR coalesce(product.product_name, '') = ''
      OR product.product_type NOT IN ('FG', 'RM', 'PP')
      OR product.unit_multiplier <= 0 OR product.unit_cost < 0
      OR product.unit_cost::text IN ('NaN', 'Infinity', '-Infinity')
      OR product.unit_multiplier::text IN ('NaN', 'Infinity', '-Infinity')
      OR product.order_point_days < 0 THEN
      RAISE EXCEPTION 'ข้อมูลสินค้าไม่ถูกต้อง: %', product.product_code;
    END IF;
    IF jsonb_typeof(item->'channel_prices') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'ราคาช่องทางไม่ถูกต้อง: %', product.product_code;
    END IF;
    v_id := NULL;
    INSERT INTO public.pr_products (
      product_code, product_name, seller_name, product_name_cn, order_point,
      order_point_days, product_category, product_type, rubber_code,
      storage_location, unit_cost, unit_name, unit_multiplier, is_active
    ) VALUES (
      product.product_code, product.product_name, product.seller_name, product.product_name_cn,
      product.order_point, product.order_point_days, product.product_category, product.product_type,
      product.rubber_code, product.storage_location, product.unit_cost, product.unit_name,
      product.unit_multiplier, true
    ) ON CONFLICT (product_code) DO NOTHING RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      v_inserted := v_inserted + 1;
    ELSE
      UPDATE public.pr_products SET
        product_name = product.product_name, seller_name = product.seller_name,
        product_name_cn = product.product_name_cn, order_point = product.order_point,
        order_point_days = product.order_point_days, product_category = product.product_category,
        product_type = product.product_type, rubber_code = product.rubber_code,
        storage_location = product.storage_location, unit_cost = product.unit_cost,
        unit_name = product.unit_name, unit_multiplier = product.unit_multiplier
      WHERE product_code = product.product_code RETURNING id INTO v_id;
      v_updated := v_updated + 1;
    END IF;
    DELETE FROM public.pr_product_channel_prices WHERE product_id = v_id;
    INSERT INTO public.pr_product_channel_prices (product_id, channel_code, sale_price)
      SELECT v_id, key, value::numeric FROM jsonb_each_text(item->'channel_prices');
  END LOOP;
  RETURN jsonb_build_object('inserted', v_inserted, 'updated', v_updated);
END;
$$;


--
-- Name: rpc_inventory_adjustment_item_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_inventory_adjustment_item_counts() RETURNS TABLE(adjustment_id uuid, item_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT item.adjustment_id, count(*)::bigint AS item_count
  FROM public.inv_adjustment_items item
  GROUP BY item.adjustment_id;
$$;


--
-- Name: FUNCTION rpc_inventory_adjustment_item_counts(); Type: COMMENT; Schema: public; Owner: -
