--
-- Name: rpc_inventory_balances_as_of(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_inventory_balances_as_of(p_as_of_date date) RETURNS TABLE(product_id uuid, product_code text, product_name text, product_type text, product_category text, is_active boolean, on_hand numeric, safety_stock numeric, total_in_stock numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH params AS (
    SELECT ((p_as_of_date + 1)::timestamp AT TIME ZONE 'Asia/Bangkok') AS cutoff
  ),
  future_movements AS (
    SELECT m.product_id, COALESCE(SUM(m.qty), 0) AS qty
    FROM public.inv_stock_movements m, params x
    WHERE m.created_at >= x.cutoff
    GROUP BY m.product_id
  ),
  future_safety_changes AS (
    SELECT i.product_id,
      COALESCE(SUM(COALESCE(i.after_safety_stock, i.new_safety_stock, 0) - COALESCE(i.before_safety_stock, 0)), 0) AS qty
    FROM public.inv_adjustment_items i
    JOIN public.inv_adjustments a ON a.id = i.adjustment_id
    CROSS JOIN params x
    WHERE a.status = 'approved'
      AND COALESCE(a.approved_at, a.created_at) >= x.cutoff
      AND (i.after_safety_stock IS NOT NULL OR i.new_safety_stock IS NOT NULL)
    GROUP BY i.product_id
  )
  SELECT
    p.id,
    p.product_code,
    p.product_name,
    p.product_type,
    p.product_category,
    COALESCE(p.is_active, TRUE),
    ROUND(CASE
      WHEN snap.id IS NOT NULL THEN snap.on_hand
      WHEN p.created_at >= x.cutoff THEN 0
      ELSE (COALESCE(b.on_hand, 0) + COALESCE(b.safety_stock, 0) - COALESCE(fm.qty, 0))
           - (COALESCE(b.safety_stock, 0) - COALESCE(fs.qty, 0))
    END, 2) AS on_hand,
    ROUND(CASE
      WHEN snap.id IS NOT NULL THEN snap.safety_stock
      WHEN p.created_at >= x.cutoff THEN 0
      ELSE COALESCE(b.safety_stock, 0) - COALESCE(fs.qty, 0)
    END, 2) AS safety_stock,
    ROUND(CASE
      WHEN snap.id IS NOT NULL THEN snap.on_hand + snap.safety_stock
      WHEN p.created_at >= x.cutoff THEN 0
      ELSE COALESCE(b.on_hand, 0) + COALESCE(b.safety_stock, 0) - COALESCE(fm.qty, 0)
    END, 2) AS total_in_stock
  FROM public.pr_products p
  CROSS JOIN params x
  LEFT JOIN public.inv_stock_balances b ON b.product_id = p.id
  LEFT JOIN future_movements fm ON fm.product_id = p.id
  LEFT JOIN future_safety_changes fs ON fs.product_id = p.id
  LEFT JOIN LATERAL (
    SELECT h.id, h.on_hand, h.safety_stock
    FROM public.inv_stock_balance_history h
    WHERE h.product_id = p.id AND h.recorded_at < x.cutoff
    ORDER BY h.recorded_at DESC, h.id DESC
    LIMIT 1
  ) snap ON TRUE
  ORDER BY p.product_code;
$$;


--
-- Name: rpc_mark_po_ordered(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_mark_po_ordered(p_po_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid  UUID := auth.uid();
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin-tr', 'manager') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สั่งซื้อ PO (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  UPDATE inv_po
  SET status = 'ordered', ordered_by = v_uid, ordered_at = NOW()
  WHERE id = p_po_id AND status = 'open';
  IF NOT FOUND THEN RAISE EXCEPTION 'PO ไม่อยู่ในสถานะเปิด'; END IF;
END;
$$;


--
-- Name: rpc_next_prebill_document_no(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_next_prebill_document_no(p_channel_code text, p_document_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_period TEXT := to_char(timezone('Asia/Bangkok', now()), 'YYMM');
  v_number INTEGER;
  v_prefix TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role NOT IN ('superadmin', 'sales-tr', 'sales-pump') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างเอกสาร QT/PC';
  END IF;
  IF p_document_type NOT IN ('quotation', 'production_confirmation') THEN
    RAISE EXCEPTION 'ประเภทเอกสารไม่ถูกต้อง';
  END IF;

  SELECT document_prefix INTO v_prefix
  FROM public.or_prebill_channel_settings
  WHERE channel_code = btrim(p_channel_code) AND document_type = p_document_type;

  v_prefix := COALESCE(NULLIF(btrim(v_prefix), ''),
    CASE WHEN p_document_type = 'quotation' THEN 'QT' ELSE 'PC' END || '-' || upper(btrim(p_channel_code)));

  INSERT INTO public.or_prebill_number_sequences(channel_code, document_type, period, last_number)
  VALUES (btrim(p_channel_code), p_document_type, v_period, 1)
  ON CONFLICT (channel_code, document_type, period)
  DO UPDATE SET last_number = public.or_prebill_number_sequences.last_number + 1
  RETURNING last_number INTO v_number;

  RETURN v_prefix || '-' || v_period || '-' || lpad(v_number::TEXT, 4, '0');
END;
$$;


--
-- Name: rpc_next_work_order_name(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_next_work_order_name(p_prefix text, p_date_part text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_role TEXT;
  v_prefix TEXT;
  v_prefix_pattern TEXT;
  v_date TEXT;
  v_next INT;
  v_seed INT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'order_staff', 'packing_staff', 'manager', 'production') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างเลขใบงาน';
  END IF;

  v_prefix := trim(both FROM coalesce(p_prefix,''));
  v_date := trim(both FROM coalesce(p_date_part,''));
  IF v_prefix = '' OR v_date = '' THEN
    RAISE EXCEPTION 'ข้อมูลไม่ครบ (prefix/date_part)';
  END IF;

  -- Escape PostgreSQL regular-expression metacharacters before matching
  -- existing names. The original prefix remains unchanged in the result.
  v_prefix_pattern := regexp_replace(v_prefix, '([.\\+*?\[\]^$(){}|])', '\\\1', 'g');

  PERFORM pg_advisory_xact_lock(hashtext('wo_seq:' || v_prefix || ':' || v_date));

  SELECT COALESCE(
    MAX((regexp_match(wo.work_order_name, ('^' || v_prefix_pattern || '-' || v_date || '-R([0-9]+)$')))[1]::int),
    0
  )
  INTO v_seed
  FROM or_work_orders wo
  WHERE wo.work_order_name ~ ('^' || v_prefix_pattern || '-' || v_date || '-R[0-9]+$')
    AND (
      wo.status IS DISTINCT FROM 'ยกเลิก'
      OR (
        EXISTS (
          SELECT 1 FROM plan_jobs pj
          WHERE pj.work_order_id = wo.id
            AND pj.is_production_voided = true
        )
        AND NOT fn_work_order_wms_fully_returned_or_cleared(wo.id)
      )
    );

  INSERT INTO or_work_order_sequences(prefix, date_part, last_r_no)
  VALUES (v_prefix, v_date, v_seed)
  ON CONFLICT (prefix, date_part)
  DO UPDATE SET
    last_r_no = EXCLUDED.last_r_no,
    updated_at = now();

  UPDATE or_work_order_sequences
  SET last_r_no = last_r_no + 1,
      updated_at = now()
  WHERE prefix = v_prefix AND date_part = v_date
  RETURNING last_r_no INTO v_next;

  RETURN v_prefix || '-' || v_date || '-R' || v_next::text;
END;
$_$;


--
-- Name: rpc_plan_active_work_order_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_plan_active_work_order_count() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(DISTINCT o.work_order_id)
  FROM public.or_orders o
  WHERE o.work_order_id IS NOT NULL
    AND COALESCE(o.status, '') NOT IN ('ยกเลิก', 'จัดส่งแล้ว');
$$;


--
-- Name: rpc_plan_import_tracking_batch(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_plan_import_tracking_batch(p_work_order_name text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_row RECORD;
  v_bill_no TEXT;
  v_tracking TEXT;
  v_tracking_normalized TEXT;
  v_order public.or_orders;
  v_match_count INTEGER;
  v_processed INTEGER := 0;
  v_updated INTEGER := 0;
  v_unchanged INTEGER := 0;
  v_duplicate INTEGER := 0;
  v_not_found INTEGER := 0;
  v_outside_work_order INTEGER := 0;
  v_invalid INTEGER := 0;
  v_failed INTEGER := 0;
  v_results JSONB := '[]'::JSONB;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role NOT IN ('superadmin', 'admin', 'production', 'packing_staff') THEN
    RAISE EXCEPTION 'Not authorized to import parcel tracking numbers';
  END IF;

  p_work_order_name := NULLIF(btrim(COALESCE(p_work_order_name, '')), '');
  IF p_work_order_name IS NULL THEN
    RAISE EXCEPTION 'Work order name is required';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'Rows must be a JSON array';
  END IF;
  IF jsonb_array_length(p_rows) > 100 THEN
    RAISE EXCEPTION 'A tracking import batch cannot exceed 100 rows';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_rows) AS item
    WHERE NULLIF(btrim(COALESCE(item->>'bill_no', '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(item->>'tracking_number', '')), '') IS NOT NULL
    GROUP BY upper(btrim(item->>'bill_no'))
    HAVING count(DISTINCT upper(btrim(item->>'tracking_number'))) > 1
  ) THEN
    RAISE EXCEPTION 'One or more order numbers have multiple tracking numbers in the same import batch';
  END IF;

  FOR v_row IN
    SELECT value AS data, ordinality::INTEGER AS row_no
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY
  LOOP
    v_processed := v_processed + 1;
    v_bill_no := NULLIF(btrim(COALESCE(v_row.data->>'bill_no', '')), '');
    v_tracking := NULLIF(btrim(COALESCE(v_row.data->>'tracking_number', '')), '');
    v_tracking_normalized := upper(v_tracking);

    IF v_bill_no IS NULL OR v_tracking IS NULL THEN
      v_invalid := v_invalid + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'row_no', v_row.row_no,
        'bill_no', COALESCE(v_bill_no, ''),
        'tracking_number', COALESCE(v_tracking, ''),
        'status', 'invalid',
        'message', 'เลขออเดอร์หรือเลขพัสดุว่าง'
      ));
      CONTINUE;
    END IF;

    SELECT count(*)::INTEGER INTO v_match_count
    FROM public.or_orders
    WHERE work_order_name = p_work_order_name
      AND bill_no = v_bill_no;

    IF v_match_count = 0 THEN
      IF EXISTS (SELECT 1 FROM public.or_orders WHERE bill_no = v_bill_no) THEN
        v_outside_work_order := v_outside_work_order + 1;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'row_no', v_row.row_no,
          'bill_no', v_bill_no,
          'tracking_number', v_tracking,
          'status', 'outside_work_order',
          'message', 'พบบิล แต่ไม่ได้อยู่ในใบงานที่เลือก'
        ));
      ELSE
        v_not_found := v_not_found + 1;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'row_no', v_row.row_no,
          'bill_no', v_bill_no,
          'tracking_number', v_tracking,
          'status', 'not_found',
          'message', 'ไม่พบเลขออเดอร์'
        ));
      END IF;
      CONTINUE;
    ELSIF v_match_count > 1 THEN
      v_invalid := v_invalid + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'row_no', v_row.row_no,
        'bill_no', v_bill_no,
        'tracking_number', v_tracking,
        'status', 'invalid',
        'message', 'พบเลขออเดอร์ซ้ำในใบงานเดียวกัน'
      ));
      CONTINUE;
    END IF;

    SELECT * INTO v_order
    FROM public.or_orders
    WHERE work_order_name = p_work_order_name
      AND bill_no = v_bill_no
    FOR UPDATE;

    IF upper(COALESCE(NULLIF(btrim(v_order.tracking_number), ''), '')) = v_tracking_normalized THEN
      v_unchanged := v_unchanged + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'row_no', v_row.row_no,
        'bill_no', v_bill_no,
        'tracking_number', v_tracking,
        'status', 'unchanged',
        'message', 'เลขพัสดุตรงกับข้อมูลเดิม'
      ));
      CONTINUE;
    END IF;

    -- Serialize the same normalized tracking number across concurrent imports.
    PERFORM pg_advisory_xact_lock(hashtextextended('TRACK:' || v_tracking_normalized, 0));

    IF EXISTS (
      SELECT 1 FROM public.or_orders other
      WHERE other.id IS DISTINCT FROM v_order.id
        AND COALESCE(other.status, '') <> 'ยกเลิก'
        AND upper(btrim(other.tracking_number)) = v_tracking_normalized
    ) THEN
      v_duplicate := v_duplicate + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'row_no', v_row.row_no,
        'bill_no', v_bill_no,
        'tracking_number', v_tracking,
        'status', 'duplicate',
        'message', 'เลขพัสดุซ้ำกับบิลอื่นในระบบ'
      ));
      CONTINUE;
    END IF;

    BEGIN
      UPDATE public.or_orders
      SET tracking_number = v_tracking
      WHERE id = v_order.id;

      v_updated := v_updated + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'row_no', v_row.row_no,
        'bill_no', v_bill_no,
        'tracking_number', v_tracking,
        'status', 'updated',
        'message', 'บันทึกสำเร็จ'
      ));
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'row_no', v_row.row_no,
        'bill_no', v_bill_no,
        'tracking_number', v_tracking,
        'status', 'error',
        'message', SQLERRM
      ));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'processed', v_processed,
    'updated', v_updated,
    'unchanged', v_unchanged,
    'duplicate', v_duplicate,
    'not_found', v_not_found,
    'outside_work_order', v_outside_work_order,
    'invalid', v_invalid,
    'failed', v_failed,
    'results', v_results
  );
END;
$$;


--
-- Name: rpc_plan_release_orders_to_workqueue(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_plan_release_orders_to_workqueue(p_work_order_name text, p_order_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role     TEXT;
  v_wo       TEXT;
  v_uid      UUID;
  v_remain   INT;
  v_legacy   BOOLEAN;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN (
    'superadmin', 'admin', 'store', 'manager', 'production', 'admin_qc'
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ย้ายบิลไปใบสั่งงาน';
  END IF;

  v_wo := trim(both FROM coalesce(p_work_order_name, ''));
  IF v_wo = '' OR p_order_ids IS NULL OR array_length(p_order_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ข้อมูลไม่ครบ');
  END IF;

  FOREACH v_uid IN ARRAY p_order_ids
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM or_orders o
      WHERE o.id = v_uid AND trim(both FROM coalesce(o.work_order_name, '')) = v_wo
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'บิลไม่อยู่ในใบงานนี้');
    END IF;
  END LOOP;

  SELECT EXISTS (
    SELECT 1 FROM wms_orders w
    WHERE trim(both FROM coalesce(w.order_id, '')) = v_wo
      AND w.source_order_id IS NULL
      AND w.status NOT IN ('cancelled', 'returned')
  ) INTO v_legacy;

  IF v_legacy THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'wms_legacy',
      'error', 'ใบงานนี้ได้มีการเบิกสินค้าไปแล้ว ติดต่อหัวหน้างานเพื่อทำการยกเลิกบิล หากต้องการเปลี่ยนแปลง'
    );
  END IF;

  UPDATE wms_orders w
  SET plan_line_released = true
  WHERE trim(both FROM coalesce(w.order_id, '')) = v_wo
    AND w.source_order_id = ANY (p_order_ids)
    AND w.status IN ('picked', 'correct', 'system_complete')
    AND w.status NOT IN ('cancelled', 'returned');

  DELETE FROM wms_orders w
  WHERE trim(both FROM coalesce(w.order_id, '')) = v_wo
    AND w.source_order_id = ANY (p_order_ids)
    AND w.status = 'pending';

  UPDATE or_orders o
  SET
    work_order_name = NULL,
    status = 'ใบสั่งงาน',
    plan_released_from_work_order = v_wo,
    plan_released_at = NOW(),
    updated_at = NOW()
  WHERE o.id = ANY (p_order_ids)
    AND trim(both FROM coalesce(o.work_order_name, '')) = v_wo;

  SELECT COUNT(*) INTO v_remain
  FROM or_orders o
  WHERE trim(both FROM coalesce(o.work_order_name, '')) = v_wo;

  IF v_remain = 0 THEN
    DELETE FROM wms_orders w
    WHERE trim(both FROM coalesce(w.order_id, '')) = v_wo
      AND NOT (
        w.plan_line_released = true
        AND w.status IN ('picked', 'correct', 'system_complete')
      );
    IF fn_plan_job_has_any_track_start(v_wo) THEN
      UPDATE plan_jobs
      SET
        qty = fn_plan_qty_json_for_work_order(v_wo),
        is_production_voided = true
      WHERE trim(both FROM name) = v_wo;
      DELETE FROM or_work_orders WHERE trim(both FROM coalesce(work_order_name, '')) = v_wo;
    ELSE
      DELETE FROM plan_jobs WHERE trim(both FROM name) = v_wo;
      DELETE FROM or_work_orders WHERE trim(both FROM coalesce(work_order_name, '')) = v_wo;
    END IF;
  ELSE
    UPDATE or_work_orders wo
    SET
      order_count = v_remain,
      plan_wo_modified = true
    WHERE trim(both FROM coalesce(wo.work_order_name, '')) = v_wo;

    UPDATE plan_jobs pj
    SET qty = fn_plan_qty_json_for_work_order(v_wo)
    WHERE trim(both FROM pj.name) = v_wo;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'work_order_name', v_wo,
    'remaining_bills', v_remain
  );
END;
$$;


--
-- Name: FUNCTION rpc_plan_release_orders_to_workqueue(p_work_order_name text, p_order_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_plan_release_orders_to_workqueue(p_work_order_name text, p_order_ids uuid[]) IS 'ย้ายบิลกลับคิว Plan→ใบสั่งงาน: ลบแถว WMS pending, ทำเครื่องหมายแถวหยิบ/ตรวจเพื่อคืนคลัง, อัปเดต or_orders + plan_jobs.qty';


--
-- Name: rpc_plan_release_orders_to_workqueue_v2(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_plan_release_orders_to_workqueue_v2(p_work_order_id uuid, p_order_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role     TEXT;
  v_wo_name  TEXT;
  v_uid      UUID;
  v_remain   INT;
  v_legacy   BOOLEAN;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store', 'manager', 'production', 'admin_qc') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ย้ายบิลไปใบสั่งงาน';
  END IF;

  IF p_work_order_id IS NULL OR p_order_ids IS NULL OR array_length(p_order_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ข้อมูลไม่ครบ');
  END IF;

  SELECT work_order_name INTO v_wo_name
  FROM or_work_orders
  WHERE id = p_work_order_id;

  IF v_wo_name IS NULL OR trim(v_wo_name) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'ไม่พบใบงาน');
  END IF;

  FOREACH v_uid IN ARRAY p_order_ids
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM or_orders o
      WHERE o.id = v_uid AND o.work_order_id = p_work_order_id
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'บิลไม่อยู่ในใบงานนี้');
    END IF;
  END LOOP;

  SELECT EXISTS (
    SELECT 1 FROM wms_orders w
    WHERE w.work_order_id = p_work_order_id
      AND w.source_order_id IS NULL
      AND w.status NOT IN ('cancelled', 'returned')
  ) INTO v_legacy;

  IF v_legacy THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'wms_legacy',
      'error', 'ใบงานนี้ได้มีการเบิกสินค้าไปแล้ว ติดต่อหัวหน้างานเพื่อทำการยกเลิกบิล หากต้องการเปลี่ยนแปลง'
    );
  END IF;

  UPDATE wms_orders w
  SET plan_line_released = true
  WHERE w.work_order_id = p_work_order_id
    AND w.source_order_id = ANY (p_order_ids)
    AND w.status IN ('picked', 'correct', 'system_complete')
    AND w.status NOT IN ('cancelled', 'returned');

  DELETE FROM wms_orders w
  WHERE w.work_order_id = p_work_order_id
    AND w.source_order_id = ANY (p_order_ids)
    AND w.status = 'pending';

  UPDATE or_orders o
  SET
    work_order_id = NULL,
    work_order_name = NULL,
    status = 'ใบสั่งงาน'::text,
    plan_released_from_work_order = v_wo_name,
    plan_released_from_work_order_id = p_work_order_id,
    plan_released_at = NOW(),
    updated_at = NOW()
  WHERE o.id = ANY (p_order_ids)
    AND o.work_order_id = p_work_order_id;

  SELECT COUNT(*) INTO v_remain
  FROM or_orders o
  WHERE o.work_order_id = p_work_order_id
    AND COALESCE(o.status, '') NOT IN (
      U&'\0E22\0E01\0E40\0E25\0E34\0E01',
      U&'\0E08\0E31\0E14\0E2A\0E48\0E07\0E41\0E25\0E49\0E27'
    );

  IF v_remain = 0 THEN
    DELETE FROM wms_orders w
    WHERE w.work_order_id = p_work_order_id
      AND NOT (
        w.plan_line_released = true
        AND w.status IN ('picked', 'correct', 'system_complete')
      );

    IF EXISTS (
      SELECT 1
      FROM plan_jobs pj
      WHERE pj.work_order_id = p_work_order_id
        AND fn_plan_job_has_any_track_start(pj.name)
    ) THEN
      UPDATE plan_jobs
      SET
        qty = fn_plan_qty_json_for_work_order(v_wo_name),
        is_production_voided = true
      WHERE work_order_id = p_work_order_id;
    ELSE
      DELETE FROM plan_jobs WHERE work_order_id = p_work_order_id;
    END IF;

    UPDATE or_work_orders
    SET
      status = 'ยกเลิก',
      order_count = 0,
      plan_wo_modified = true
    WHERE id = p_work_order_id;
  ELSE
    UPDATE or_work_orders wo
    SET
      order_count = v_remain,
      plan_wo_modified = true
    WHERE wo.id = p_work_order_id;

    UPDATE plan_jobs pj
    SET qty = fn_plan_qty_json_for_work_order(v_wo_name)
    WHERE pj.work_order_id = p_work_order_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'work_order_id', p_work_order_id,
    'work_order_name', v_wo_name,
    'remaining_bills', v_remain
  );
END;
$$;


--
-- Name: FUNCTION rpc_plan_release_orders_to_workqueue_v2(p_work_order_id uuid, p_order_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_plan_release_orders_to_workqueue_v2(p_work_order_id uuid, p_order_ids uuid[]) IS 'ย้ายบิลกลับคิว Plan→ใบสั่งงาน: เขียนสถานะใบสั่งงานโดยตรง (soft-deprecate สถานะย้ายจากใบงาน)';


--
-- Name: rpc_plan_work_order_metrics(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_plan_work_order_metrics(p_work_order_ids uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH requested AS (
    SELECT DISTINCT id FROM unnest(p_work_order_ids) AS ids(id) WHERE id IS NOT NULL
  ), orders AS MATERIALIZED (
    SELECT o.id, o.work_order_id, o.status FROM public.or_orders o
    JOIN requested r ON r.id = o.work_order_id
  ), bills AS (
    SELECT work_order_id, count(*) AS bill_count FROM orders
    WHERE status <> 'ยกเลิก' GROUP BY work_order_id
  ), categories AS (
    -- Match the existing category loader: all orders and item rows, including
    -- cancelled/detail rows; positive finite quantities, otherwise one unit.
    SELECT o.work_order_id,
      btrim(p.product_category::text, U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') AS category,
      sum(CASE WHEN i.quantity > 0 AND i.quantity::text NOT IN ('NaN','Infinity','-Infinity')
        THEN i.quantity ELSE 1 END) AS qty
    FROM orders o JOIN public.or_order_items i ON i.order_id = o.id
    JOIN public.v_cost_safe_pr_products p ON p.id = i.product_id
    WHERE i.product_id IS NOT NULL
    GROUP BY o.work_order_id, category
  ), quantities AS (
    SELECT work_order_id, jsonb_object_agg(category, qty) AS category_qty
    FROM categories WHERE category <> '' AND category IS NOT NULL GROUP BY work_order_id
  )
  SELECT coalesce(jsonb_object_agg(r.id::text, jsonb_build_object(
    'bill_count', coalesce(b.bill_count, 0), 'category_qty', coalesce(q.category_qty, '{}'::jsonb)
  )), '{}'::jsonb)
  FROM requested r LEFT JOIN bills b ON b.work_order_id = r.id
  LEFT JOIN quantities q ON q.work_order_id = r.id;
$$;


--
-- Name: rpc_post_stock_transfer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_stock_transfer(p_transfer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_transfer public.wh_stock_transfers%ROWTYPE; v_item RECORD;
BEGIN
  IF NOT public.can_manage_warehouse_locations() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันใบย้าย'; END IF;
  SELECT * INTO v_transfer FROM public.wh_stock_transfers WHERE id = p_transfer_id FOR UPDATE;
  IF v_transfer.id IS NULL THEN RAISE EXCEPTION 'ไม่พบใบย้าย'; END IF;
  IF v_transfer.status <> 'draft' THEN RAISE EXCEPTION 'ยืนยันได้เฉพาะใบสถานะร่าง'; END IF;

  FOR v_item IN SELECT * FROM public.wh_stock_transfer_items WHERE transfer_id = p_transfer_id
  LOOP
    UPDATE public.wh_location_stock SET qty = qty - v_item.qty, updated_at = NOW()
    WHERE product_id = v_item.product_id AND location_id = v_transfer.from_location_id AND qty >= v_item.qty;
    IF NOT FOUND THEN RAISE EXCEPTION 'สินค้าในจุดต้นทางมีไม่เพียงพอ'; END IF;
    INSERT INTO public.wh_location_stock(product_id, location_id, qty)
    VALUES (v_item.product_id, v_transfer.to_location_id, v_item.qty)
    ON CONFLICT (product_id, location_id) DO UPDATE
      SET qty = public.wh_location_stock.qty + EXCLUDED.qty, updated_at = NOW();
  END LOOP;
  UPDATE public.wh_stock_transfers SET status='posted', posted_by=auth.uid(), posted_at=NOW()
  WHERE id=p_transfer_id;
END;
$$;


--
-- Name: rpc_process_inventory_return_items(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_process_inventory_return_items(p_return_id uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_status TEXT;
  v_expected_count INTEGER;
  v_supplied_count INTEGER;
  v_item RECORD;
  v_avg_cost NUMERIC;
  v_parent_disposition TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ดำเนินการสินค้าตีกลับ (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.inv_returns
  WHERE id = p_return_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบใบรับสินค้าตีกลับ'; END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ดำเนินการแล้ว (status: %)', v_status;
  END IF;

  SELECT count(*) INTO v_expected_count
  FROM public.inv_return_items
  WHERE return_id = p_return_id;

  SELECT count(DISTINCT x.item_id) INTO v_supplied_count
  FROM jsonb_to_recordset(COALESCE(p_items, '[]'::jsonb)) AS x(item_id UUID, disposition TEXT)
  JOIN public.inv_return_items i ON i.id = x.item_id AND i.return_id = p_return_id
  WHERE x.disposition IN ('return_to_stock', 'waste', 'lost');

  IF v_expected_count = 0 OR v_supplied_count <> v_expected_count THEN
    RAISE EXCEPTION 'กรุณาระบุผลตรวจให้ครบทุกสินค้า';
  END IF;

  FOR v_item IN
    SELECT i.id, i.product_id, i.qty, x.disposition
    FROM jsonb_to_recordset(p_items) AS x(item_id UUID, disposition TEXT)
    JOIN public.inv_return_items i ON i.id = x.item_id AND i.return_id = p_return_id
  LOOP
    v_avg_cost := public.fn_get_current_avg_cost(v_item.product_id);

    IF v_item.disposition = 'return_to_stock' THEN
      INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
      VALUES (v_item.product_id, v_item.qty, 0, 0)
      ON CONFLICT (product_id) DO UPDATE
        SET on_hand = inv_stock_balances.on_hand + v_item.qty;

      INSERT INTO public.inv_stock_movements (
        product_id, movement_type, qty, ref_type, ref_id, note, created_by, unit_cost, total_cost
      ) VALUES (
        v_item.product_id, 'return', v_item.qty, 'inv_returns', p_return_id,
        'สินค้าตีกลับ: คืนกลับสต๊อค', auth.uid(), v_avg_cost, v_item.qty * v_avg_cost
      );

      INSERT INTO public.inv_stock_lots (
        product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id
      ) VALUES (
        v_item.product_id, v_item.qty, v_item.qty, v_avg_cost, 'inv_returns', p_return_id
      );

      PERFORM public.fn_recalc_product_landed_cost(v_item.product_id);
    ELSE
      -- Returned goods were already deducted when shipped. Waste/lost must not deduct on_hand again.
      INSERT INTO public.inv_stock_movements (
        product_id, movement_type, qty, ref_type, ref_id, note, created_by, unit_cost, total_cost
      ) VALUES (
        v_item.product_id,
        CASE WHEN v_item.disposition = 'waste' THEN 'return_waste' ELSE 'return_lost' END,
        0, 'inv_returns', p_return_id,
        CASE WHEN v_item.disposition = 'waste'
          THEN format('สินค้าตีกลับ: ของเสีย จำนวน %s', v_item.qty)
          ELSE format('สินค้าตีกลับ: สูญหาย จำนวน %s', v_item.qty)
        END,
        auth.uid(), v_avg_cost, v_item.qty * v_avg_cost
      );
    END IF;

    UPDATE public.inv_return_items
    SET disposition = v_item.disposition
    WHERE id = v_item.id;
  END LOOP;

  SELECT CASE
    WHEN count(DISTINCT disposition) = 1 THEN min(disposition)
    ELSE 'mixed'
  END INTO v_parent_disposition
  FROM public.inv_return_items
  WHERE return_id = p_return_id;

  UPDATE public.inv_returns
  SET status = 'received', disposition = v_parent_disposition,
      received_by = auth.uid(), received_at = NOW()
  WHERE id = p_return_id;
END;
$$;


--
-- Name: rpc_product_sales_bills(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_product_sales_bills(p_product_id uuid, p_from_date date, p_to_date date) RETURNS TABLE(order_id uuid, bill_no text, work_order_name text, entry_date date, order_status text, total_qty numeric, total_amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    o.id AS order_id,
    o.bill_no,
    o.work_order_name,
    o.entry_date,
    o.status AS order_status,
    COALESCE(SUM(oi.quantity), 0) AS total_qty,
    COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS total_amount
  FROM public.or_order_items oi
  JOIN public.or_orders o ON o.id = oi.order_id
  WHERE oi.product_id = p_product_id
    AND o.entry_date >= p_from_date
    AND o.entry_date <= p_to_date
    AND BTRIM(COALESCE(o.status, '')) IN ('จัดส่งแล้ว', 'เสร็จสิ้น')
    AND NULLIF(BTRIM(COALESCE(oi.cancellation_stock_action, '')), '') IS NULL
  GROUP BY o.id, o.bill_no, o.work_order_name, o.entry_date, o.status
  ORDER BY o.entry_date DESC, o.bill_no DESC;
$$;


--
-- Name: rpc_product_sales_summary(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_product_sales_summary(p_from_date date, p_to_date date) RETURNS TABLE(product_id uuid, product_code text, product_name text, product_type text, total_qty numeric, total_amount numeric, order_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT
    p.id            AS product_id,
    p.product_code,
    p.product_name,
    p.product_type,
    COALESCE(SUM(oi.quantity), 0)                  AS total_qty,
    COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS total_amount,
    COUNT(DISTINCT oi.order_id)                    AS order_count
  FROM or_order_items oi
  JOIN or_orders o ON o.id = oi.order_id
  JOIN pr_products p ON p.id = oi.product_id
  LEFT JOIN LATERAL (
    SELECT 1 AS hit
    FROM wms_orders w
    WHERE w.stock_action = 'recalled'
      AND w.status = 'cancelled'
      AND (
        w.source_order_item_id = oi.id
        OR (
          w.source_order_item_id IS NULL
          AND trim(both FROM coalesce(w.order_id, '')) = trim(both FROM coalesce(o.work_order_name, ''))
          AND upper(trim(both FROM coalesce(w.product_code, ''))) = upper(trim(both FROM coalesce(p.product_code::text, '')))
        )
      )
    LIMIT 1
  ) recalled_line ON true
  WHERE o.entry_date >= p_from_date
    AND o.entry_date <= p_to_date
    -- นับเฉพาะยอดขายที่ปิดงานแล้วจริง
    AND trim(both FROM coalesce(o.status, '')) IN (
      U&'\0E08\0E31\0E14\0E2A\0E48\0E07\0E41\0E25\0E49\0E27', -- จัดส่งแล้ว
      U&'\0E40\0E2A\0E23\0E47\0E08\0E2A\0E34\0E49\0E19'      -- เสร็จสิ้น
    )
    AND oi.product_id IS NOT NULL
    AND COALESCE(oi.cancellation_stock_action, '') <> 'recalled'
    AND recalled_line.hit IS NULL
  GROUP BY p.id, p.product_code, p.product_name, p.product_type
  ORDER BY total_qty DESC;
$$;


--
-- Name: rpc_qc_skip_eligibility(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_qc_skip_eligibility(p_work_order_name text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_settings public.qc_skip_settings%ROWTYPE;
  v_now timestamptz := now();
  v_today date := timezone('Asia/Bangkok', now())::date;
  v_total integer := 0;
  v_done integer := 0;
  v_remaining integer := 0;
  v_backlog integer := 0;
  v_available integer := 0;
  v_required integer := 0;
  v_plan_end timestamptz;
  v_plan_start timestamptz;
  v_pack_start timestamptz;
  v_actual_qc_start timestamptz;
  v_pickup_deadline timestamptz;
  v_deadline timestamptz;
  v_predicted_finish timestamptz;
  v_capacity numeric := 0;
  v_minutes_available numeric := 0;
  v_is_mandatory boolean := false;
  v_mandatory_reasons jsonb := '[]'::jsonb;
  v_reasons jsonb := '[]'::jsonb;
  v_is_urgent boolean := false;
  v_plan_date date;
  v_plan_job_id text;
  v_qc_start_seconds numeric;
  v_qc_end_seconds numeric;
  v_pack_start_seconds numeric;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL THEN RAISE EXCEPTION 'ไม่พบสิทธิ์ผู้ใช้งาน'; END IF;

  SELECT * INTO v_settings FROM public.qc_skip_settings WHERE id = 1;

  SELECT COALESCE(sum(GREATEST(COALESCE(oi.quantity, 0), 0)), 0)::integer
  INTO v_total
  FROM public.or_orders o
  JOIN public.or_order_items oi ON oi.order_id = o.id
  WHERE o.work_order_name = p_work_order_name
    AND COALESCE(o.status, '') NOT IN ('ยกเลิก', 'ยกเลิกคำสั่งซื้อ');

  SELECT count(DISTINCT r.item_uid)::integer INTO v_done
  FROM public.qc_records r
  WHERE r.item_uid IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.or_orders o
      WHERE o.work_order_name = p_work_order_name
        AND r.bill_no = o.bill_no
    )
    AND r.status IN ('pass', 'fail');
  v_remaining := GREATEST(v_total - v_done, 0);

  IF EXISTS (
    SELECT 1 FROM public.qc_mandatory_rules r
    JOIN public.or_orders o ON o.work_order_name = p_work_order_name
    WHERE r.is_active AND r.rule_type = 'claim' AND COALESCE(o.claim_type, '') <> ''
  ) THEN
    v_is_mandatory := true;
    v_mandatory_reasons := v_mandatory_reasons || jsonb_build_array('บิลเคลม');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.qc_mandatory_rules r
    JOIN public.or_orders o ON o.work_order_name = p_work_order_name
    JOIN public.or_order_items oi ON oi.order_id = o.id
    JOIN public.pr_products p ON p.id = oi.product_id
    WHERE r.is_active
      AND ((r.rule_type = 'category' AND r.rule_value = COALESCE(p.product_category, ''))
        OR (r.rule_type = 'product' AND r.rule_value = p.id::text))
  ) THEN
    v_is_mandatory := true;
    SELECT COALESCE(jsonb_agg(DISTINCT r.label), '[]'::jsonb)
    INTO v_mandatory_reasons
    FROM public.qc_mandatory_rules r
    JOIN public.or_orders o ON o.work_order_name = p_work_order_name
    JOIN public.or_order_items oi ON oi.order_id = o.id
    JOIN public.pr_products p ON p.id = oi.product_id
    WHERE r.is_active
      AND ((r.rule_type = 'category' AND r.rule_value = COALESCE(p.product_category, ''))
        OR (r.rule_type = 'product' AND r.rule_value = p.id::text));
  END IF;

  SELECT pj.id, pj.date,
         NULLIF(pj.locked_plans->'QC'->>'start', '')::numeric,
         NULLIF(pj.locked_plans->'QC'->>'end', '')::numeric,
         NULLIF(pj.locked_plans->'PACK'->>'start', '')::numeric
  INTO v_plan_job_id, v_plan_date, v_qc_start_seconds, v_qc_end_seconds, v_pack_start_seconds
  FROM public.plan_jobs pj
  WHERE pj.name = p_work_order_name
  ORDER BY pj.date DESC, pj.order_index DESC
  LIMIT 1;

  IF v_plan_date IS NOT NULL AND v_qc_start_seconds IS NOT NULL THEN
    v_plan_start := (v_plan_date::timestamp + make_interval(secs => v_qc_start_seconds)) AT TIME ZONE 'Asia/Bangkok';
  END IF;
  IF v_plan_date IS NOT NULL AND v_qc_end_seconds IS NOT NULL THEN
    v_plan_end := (v_plan_date::timestamp + make_interval(secs => v_qc_end_seconds)) AT TIME ZONE 'Asia/Bangkok';
  END IF;
  IF v_plan_date IS NOT NULL AND v_pack_start_seconds IS NOT NULL THEN
    v_pack_start := (v_plan_date::timestamp + make_interval(secs => v_pack_start_seconds)) AT TIME ZONE 'Asia/Bangkok';
  END IF;

  IF v_plan_job_id IS NOT NULL THEN
    SELECT min(NULLIF(step.value->>'start', '')::timestamptz)
    INTO v_actual_qc_start
    FROM public.plan_jobs pj
    CROSS JOIN LATERAL jsonb_each(COALESCE(pj.tracks->'QC', '{}'::jsonb)) step
    WHERE pj.id = v_plan_job_id;

    v_plan_start := COALESCE(v_plan_start, (
      SELECT min(a.planned_start) FROM public.plan_worker_assignments a
      WHERE a.plan_job_id = v_plan_job_id AND a.department_name = 'QC' AND a.status <> 'cancelled'
    ));
    v_plan_end := COALESCE(v_plan_end, (
      SELECT max(a.planned_end) FROM public.plan_worker_assignments a
      WHERE a.plan_job_id = v_plan_job_id AND a.department_name = 'QC' AND a.status <> 'cancelled'
    ));
    v_pack_start := COALESCE(v_pack_start, (
      SELECT min(a.planned_start) FROM public.plan_worker_assignments a
      WHERE a.plan_job_id = v_plan_job_id AND a.department_name = 'PACK' AND a.status <> 'cancelled'
    ));
  END IF;

  SELECT min((v_today::timestamp + s.pickup_time - make_interval(mins => s.pack_buffer_minutes)) AT TIME ZONE 'Asia/Bangkok')
  INTO v_pickup_deadline
  FROM public.qc_channel_pickup_schedules s
  WHERE s.is_active
    AND s.day_of_week = extract(dow FROM v_today)::integer
    AND EXISTS (
      SELECT 1 FROM public.or_orders o
      WHERE o.work_order_name = p_work_order_name AND o.channel_code = s.channel_code
    );

  SELECT count(DISTINCT pj.name)::integer INTO v_backlog
  FROM public.plan_jobs pj
  WHERE pj.date = v_today
    AND COALESCE(pj.is_production_voided, false) = false
    AND COALESCE(pj.tracks->'QC'->'เสร็จแล้ว'->>'end', '') = '';

  SELECT count(DISTINCT e.id)::integer INTO v_available
  FROM public.hr_employees e
  JOIN public.plan_employee_skills sk ON sk.employee_id = e.id
  WHERE e.employment_status IN ('active', 'probation')
    AND sk.department_name = 'QC'
    AND sk.qualification_status <> 'blocked'
    AND (sk.valid_until IS NULL OR sk.valid_until >= v_today)
    AND EXISTS (
      SELECT 1 FROM public.hr_time_entries te
      WHERE te.employee_id = e.id AND te.work_date = v_today AND te.entry_type = 'clock_in'
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.hr_leave_requests lr
      WHERE lr.employee_id = e.id AND lr.status = 'approved'
        AND v_today BETWEEN lr.start_date AND lr.end_date
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.plan_worker_assignments a
      WHERE a.employee_id = e.id
        AND a.status NOT IN ('cancelled', 'completed')
        AND a.department_name <> 'QC'
        AND v_now >= a.planned_start AND v_now < a.planned_end
    );

  SELECT COALESCE(max(required_workers), 0)::integer INTO v_required
  FROM public.plan_operation_requirements
  WHERE department_name = 'QC';

  v_deadline := LEAST(
    COALESCE(v_plan_end, 'infinity'::timestamptz),
    COALESCE(v_pack_start, 'infinity'::timestamptz),
    COALESCE(v_pickup_deadline, 'infinity'::timestamptz)
  );
  IF v_deadline = 'infinity'::timestamptz THEN v_deadline := v_now + interval '8 hours'; END IF;

  IF v_available > 0 THEN
    v_predicted_finish := v_now + make_interval(secs => (v_remaining / (v_available * v_settings.fallback_items_per_worker_hour) * 3600)::integer);
  ELSE
    v_predicted_finish := v_now + interval '24 hours';
  END IF;
  v_minutes_available := GREATEST(extract(epoch FROM (v_deadline - v_now)) / 60, 0);
  v_capacity := v_available * v_settings.fallback_items_per_worker_hour * v_minutes_available / 60;

  IF v_plan_end IS NOT NULL AND v_predicted_finish > v_plan_end + make_interval(mins => v_settings.delay_threshold_minutes) THEN
    v_is_urgent := true; v_reasons := v_reasons || jsonb_build_array('คาดว่า QC ช้ากว่าแผน');
  END IF;
  IF v_backlog >= v_settings.backlog_work_orders_threshold THEN
    v_is_urgent := true; v_reasons := v_reasons || jsonb_build_array('ใบงานรอ QC เกินเกณฑ์');
  END IF;
  IF v_remaining > v_capacity THEN
    v_is_urgent := true; v_reasons := v_reasons || jsonb_build_array('จำนวนชิ้นเกินกำลังคนก่อน deadline');
  END IF;
  IF v_pack_start IS NOT NULL AND v_predicted_finish > v_pack_start THEN
    v_is_urgent := true; v_reasons := v_reasons || jsonb_build_array('คาดว่าจะกระทบเวลาเริ่ม PACK');
  END IF;
  IF v_plan_start IS NOT NULL AND v_now > v_plan_start AND v_actual_qc_start IS NULL THEN
    v_is_urgent := true; v_reasons := v_reasons || jsonb_build_array('งานเข้า QC ช้ากว่าแผน');
  END IF;
  IF v_pickup_deadline IS NOT NULL AND v_predicted_finish > v_pickup_deadline THEN
    v_is_urgent := true; v_reasons := v_reasons || jsonb_build_array('คาดว่าไม่ทันรอบขนส่ง');
  END IF;

  RETURN jsonb_build_object(
    'eligible', CASE
      WHEN v_role IN ('superadmin', 'admin') THEN true
      ELSE v_settings.enabled AND v_settings.production_enabled AND v_role = 'production' AND v_is_urgent AND NOT v_is_mandatory
    END,
    'role', v_role,
    'urgent', v_is_urgent,
    'mandatory_qc', v_is_mandatory,
    'mandatory_reasons', v_mandatory_reasons,
    'reasons', v_reasons,
    'remaining_items', v_remaining,
    'backlog_work_orders', v_backlog,
    'available_qc_workers', v_available,
    'required_qc_workers', v_required,
    'capacity_before_deadline', round(v_capacity, 1),
    'predicted_finish', v_predicted_finish,
    'plan_qc_start', v_plan_start,
    'plan_qc_end', v_plan_end,
    'pack_start', v_pack_start,
    'pickup_deadline', v_pickup_deadline,
    'evaluated_at', v_now
  );
END;
$$;


--
-- Name: rpc_recalc_po_landed_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_recalc_po_landed_cost(p_po_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    SELECT u.role
      INTO v_role
    FROM public.us_users AS u
    WHERE u.id = auth.uid()
      AND u.is_active IS TRUE;

    IF v_role IS NULL
       OR v_role NOT IN ('superadmin', 'admin', 'account', 'manager') THEN
      RAISE EXCEPTION 'Not authorized to recalculate PO landed cost';
    END IF;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.inv_po WHERE id = p_po_id) THEN
    RAISE EXCEPTION 'PO not found';
  END IF;

  PERFORM public.fn_update_product_landed_costs(p_po_id);
END;
$$;


--
-- Name: rpc_receive_gr(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_receive_gr(p_po_id uuid, p_items jsonb, p_shipping jsonb DEFAULT '{}'::jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb; i jsonb; poi inv_po_items%ROWTYPE;
BEGIN
  IF NOT public.erp_can_manage_receiving_cases() AND NOT EXISTS (SELECT 1 FROM us_users WHERE id=auth.uid() AND role IN ('picker','manager','auditor')) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์รับสินค้า'; END IF;
  PERFORM 1 FROM inv_po WHERE id=p_po_id FOR UPDATE;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'ไม่มีรายการรับ'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) x GROUP BY x->>'product_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'สินค้าซ้ำในใบรับ'; END IF;
  FOR i IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    SELECT * INTO poi FROM inv_po_items WHERE po_id=p_po_id AND product_id=(i->>'product_id')::uuid FOR UPDATE;
    IF NOT FOUND OR (i->>'qty_received') IS NULL OR (i->>'qty_received')::numeric < 0 OR (i->>'qty_received')::numeric::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'รายการรับไม่ถูกต้อง'; END IF;
    IF coalesce(poi.resolution_qty,0)>0 AND (i->>'qty_received')::numeric > greatest(poi.qty-coalesce(poi.qty_received_total,0)-poi.resolution_qty,0) THEN RAISE EXCEPTION 'จำนวนรับเกินยอดคงเหลือหลังปิดยอดค้างรับ'; END IF;
  END LOOP;
  r := public.rpc_receive_gr_before_cases(p_po_id,p_items,p_shipping,auth.uid());
  UPDATE inv_po SET status='closed' WHERE id=p_po_id AND status='received' AND EXISTS (SELECT 1 FROM inv_po_items WHERE po_id=p_po_id AND resolution_qty>0);
  RETURN r;
END $$;


--
-- Name: rpc_receive_gr_before_cases(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_receive_gr_before_cases(p_po_id uuid, p_items jsonb, p_shipping jsonb DEFAULT '{}'::jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_gr_id          UUID;
  v_gr_no          TEXT;
  v_item           JSONB;
  v_gr_item_id     UUID;
  v_images         JSONB;
  v_image          JSONB;
  v_image_count    INT;
  v_storage_path   TEXT;
  v_storage_bucket TEXT;
  v_size_bytes     BIGINT;
  v_sort_order     INT;
  v_has_shortage   BOOLEAN := FALSE;
  v_total_received NUMERIC := 0;
  v_dom_cost       NUMERIC(14,2);
  v_dom_cpp        NUMERIC(12,4);
  v_qty_recv       NUMERIC;
  v_qty_ord        NUMERIC;
  v_qty_short      NUMERIC;
  v_today          TEXT;
  v_seq            INT;
  v_all_fulfilled  BOOLEAN;
  v_intl_thb       NUMERIC;
  v_total_po_qty   NUMERIC;
  v_intl_cpp       NUMERIC;
  v_lot_rec        RECORD;
  v_lot_cost       NUMERIC;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM inv_po WHERE id = p_po_id AND status IN ('ordered', 'partial')) THEN
    RAISE EXCEPTION 'PO ไม่อยู่ในสถานะที่รับสินค้าได้';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('gr_no_gen'));

  v_today := to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD');

  SELECT COALESCE(MAX(CAST(SPLIT_PART(gr_no, '-', 3) AS INTEGER)), 0) + 1
  INTO v_seq
  FROM inv_gr
  WHERE gr_no LIKE 'GR-' || v_today || '-___';

  v_gr_no := 'GR-' || v_today || '-' || lpad(v_seq::text, 3, '0');

  INSERT INTO inv_gr (
    gr_no, po_id, status, received_by, received_at, note,
    dom_shipping_company, dom_shipping_cost, shortage_note
  )
  VALUES (
    v_gr_no, p_po_id, 'received', p_user_id, NOW(), p_shipping->>'note',
    p_shipping->>'dom_shipping_company',
    (p_shipping->>'dom_shipping_cost')::NUMERIC,
    p_shipping->>'shortage_note'
  )
  RETURNING id INTO v_gr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_qty_recv  := (v_item->>'qty_received')::NUMERIC;
    v_qty_ord   := (v_item->>'qty_ordered')::NUMERIC;
    v_qty_short := GREATEST(v_qty_ord - v_qty_recv, 0);

    IF v_qty_short > 0 THEN
      v_has_shortage := TRUE;
    END IF;

    v_total_received := v_total_received + v_qty_recv;

    INSERT INTO inv_gr_items (gr_id, product_id, qty_received, qty_ordered, qty_shortage, shortage_note)
    VALUES (
      v_gr_id,
      (v_item->>'product_id')::UUID,
      v_qty_recv, v_qty_ord, v_qty_short,
      v_item->>'shortage_note'
    )
    RETURNING id INTO v_gr_item_id;

    v_images := COALESCE(v_item->'images', '[]'::JSONB);
    IF jsonb_typeof(v_images) <> 'array' THEN
      RAISE EXCEPTION 'images ต้องเป็น array (product_id=%)', (v_item->>'product_id');
    END IF;
    IF jsonb_array_length(v_images) > 5 THEN
      RAISE EXCEPTION 'แนบรูปได้ไม่เกิน 5 รูปต่อรายการสินค้า (product_id=%)', (v_item->>'product_id');
    END IF;

    v_image_count := 0;
    FOR v_image IN SELECT * FROM jsonb_array_elements(v_images)
    LOOP
      v_image_count := v_image_count + 1;
      v_storage_path := NULLIF(TRIM(v_image->>'storage_path'), '');
      IF v_storage_path IS NULL THEN
        RAISE EXCEPTION 'storage_path ห้ามว่าง (product_id=%)', (v_item->>'product_id');
      END IF;

      v_storage_bucket := COALESCE(NULLIF(TRIM(v_image->>'storage_bucket'), ''), 'gr-item-images');
      v_sort_order := COALESCE(NULLIF(v_image->>'sort_order', '')::INT, v_image_count);
      v_size_bytes := NULLIF(v_image->>'size_bytes', '')::BIGINT;

      INSERT INTO inv_gr_item_images (
        gr_item_id, storage_bucket, storage_path, file_name, mime_type, size_bytes, sort_order
      )
      VALUES (
        v_gr_item_id,
        v_storage_bucket,
        v_storage_path,
        NULLIF(TRIM(v_image->>'file_name'), ''),
        NULLIF(TRIM(v_image->>'mime_type'), ''),
        v_size_bytes,
        v_sort_order
      );
    END LOOP;

    UPDATE inv_po_items
    SET qty_received_total = qty_received_total + v_qty_recv
    WHERE po_id = p_po_id AND product_id = (v_item->>'product_id')::UUID;

    IF v_qty_recv > 0 THEN
      INSERT INTO inv_stock_balances (product_id, on_hand, reserved, safety_stock)
      VALUES ((v_item->>'product_id')::UUID, v_qty_recv, 0, 0)
      ON CONFLICT (product_id) DO UPDATE SET
        on_hand = inv_stock_balances.on_hand + v_qty_recv,
        updated_at = NOW();

      INSERT INTO inv_stock_movements (product_id, movement_type, qty, ref_type, ref_id, note, created_by)
      VALUES (
        (v_item->>'product_id')::UUID,
        'gr', v_qty_recv, 'inv_gr', v_gr_id,
        'รับเข้าจาก GR ' || v_gr_no, p_user_id
      );
    END IF;
  END LOOP;

  v_dom_cost := (p_shipping->>'dom_shipping_cost')::NUMERIC;
  v_dom_cpp  := CASE
    WHEN v_dom_cost IS NOT NULL AND v_dom_cost > 0 AND v_total_received > 0
    THEN v_dom_cost / v_total_received ELSE 0 END;

  IF v_dom_cost IS NOT NULL AND v_dom_cost > 0 AND v_total_received > 0 THEN
    UPDATE inv_gr SET dom_cost_per_piece = v_dom_cpp WHERE id = v_gr_id;
  END IF;

  SELECT COALESCE(intl_shipping_cost_thb, 0) INTO v_intl_thb FROM inv_po WHERE id = p_po_id;
  SELECT COALESCE(SUM(qty), 0) INTO v_total_po_qty FROM inv_po_items WHERE po_id = p_po_id;
  v_intl_cpp := CASE WHEN v_total_po_qty > 0 THEN v_intl_thb / v_total_po_qty ELSE 0 END;

  FOR v_lot_rec IN
    SELECT sm.id AS movement_id, sm.product_id, sm.qty AS qty_recv,
           COALESCE(poi.unit_price, 0) AS unit_price
    FROM inv_stock_movements sm
    JOIN inv_po_items poi ON poi.po_id = p_po_id AND poi.product_id = sm.product_id
    WHERE sm.ref_type = 'inv_gr' AND sm.ref_id = v_gr_id
      AND sm.movement_type = 'gr' AND sm.qty > 0
  LOOP
    v_lot_cost := v_lot_rec.unit_price + v_intl_cpp + v_dom_cpp;

    INSERT INTO inv_stock_lots (product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id)
    VALUES (v_lot_rec.product_id, v_lot_rec.qty_recv, v_lot_rec.qty_recv, v_lot_cost, 'inv_gr', v_gr_id);

    UPDATE inv_stock_movements
    SET unit_cost  = v_lot_cost,
        total_cost = v_lot_rec.qty_recv * v_lot_cost
    WHERE id = v_lot_rec.movement_id;

    PERFORM fn_recalc_product_landed_cost(v_lot_rec.product_id);
  END LOOP;

  IF v_has_shortage THEN
    UPDATE inv_gr SET status = 'partial' WHERE id = v_gr_id;
  END IF;

  SELECT NOT EXISTS (
    SELECT 1 FROM inv_po_items
    WHERE po_id = p_po_id
      AND (qty_received_total + COALESCE(resolution_qty, 0)) < qty
  ) INTO v_all_fulfilled;

  IF v_all_fulfilled THEN
    UPDATE inv_po SET status = 'received' WHERE id = p_po_id;
  ELSE
    UPDATE inv_po SET status = 'partial' WHERE id = p_po_id;
  END IF;

  RETURN jsonb_build_object(
    'id', v_gr_id,
    'gr_no', v_gr_no,
    'status', CASE WHEN v_has_shortage THEN 'partial' ELSE 'received' END,
    'total_received', v_total_received
  );
END;
$$;


--
-- Name: rpc_receive_gr_with_tracking(uuid, jsonb, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_receive_gr_with_tracking(p_po_id uuid, p_items jsonb, p_shipping jsonb DEFAULT '{}'::jsonb, p_user_id uuid DEFAULT NULL::uuid, p_tracking_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_tracking_number TEXT;
BEGIN
  v_tracking_number := NULLIF(BTRIM(p_tracking_number), '');

  IF v_tracking_number IS NOT NULL AND char_length(v_tracking_number) > 100 THEN
    RAISE EXCEPTION 'เลขพัสดุต้องไม่เกิน 100 ตัวอักษร';
  END IF;

  -- Reuse the established receiving transaction, including stock, lot-cost,
  -- shortage, and image handling, then attach tracking within this transaction.
  v_result := public.rpc_receive_gr(p_po_id, p_items, p_shipping, p_user_id);

  UPDATE public.inv_gr
  SET tracking_number = v_tracking_number
  WHERE id = (v_result->>'id')::UUID;

  RETURN v_result || jsonb_build_object('tracking_number', v_tracking_number);
END;
$$;


--
-- Name: rpc_receiving_case_action(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_receiving_case_action(p_case_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c inv_receiving_cases%ROWTYPE; f inv_receiving_case_finance%ROWTYPE; i record; v_po uuid; v_note text := coalesce(p_data->>'note',''); v_amount numeric; v_method text;
BEGIN
  IF NOT public.erp_can_manage_receiving_cases() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการยอดค้างรับ'; END IF;
  SELECT po_id INTO v_po FROM inv_receiving_cases WHERE id=p_case_id;
  IF v_po IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการติดตาม'; END IF;
  -- Same lock order as receiving and case creation: PO, case, PO items.
  PERFORM 1 FROM inv_po WHERE id=v_po FOR UPDATE;
  SELECT * INTO c FROM inv_receiving_cases WHERE id=p_case_id FOR UPDATE;
  IF p_action IN ('approve','reject','settle') AND NOT public.erp_can_view_cost() THEN RAISE EXCEPTION 'เฉพาะ superadmin, admin, account'; END IF;
  IF p_action = 'approve' THEN
    IF c.status <> 'pending' THEN RAISE EXCEPTION 'รายการไม่ได้รออนุมัติ'; END IF;
    IF NOT EXISTS (SELECT 1 FROM inv_po WHERE id=v_po AND status IN ('ordered','partial')) THEN RAISE EXCEPTION 'สถานะ PO เปลี่ยนแล้ว'; END IF;
    FOR i IN SELECT ci.qty requested_qty, poi.* FROM inv_receiving_case_items ci JOIN inv_po_items poi ON poi.id=ci.po_item_id WHERE ci.case_id=c.id ORDER BY poi.id FOR UPDATE OF poi LOOP
      IF i.requested_qty > i.qty - coalesce(i.qty_received_total,0) - coalesce(i.resolution_qty,0) THEN RAISE EXCEPTION 'มีการรับสินค้าเพิ่มแล้ว กรุณาปฏิเสธคำขอนี้และสร้างใหม่ตามยอดปัจจุบัน'; END IF;
      UPDATE inv_po_items SET resolution_qty=coalesce(resolution_qty,0)+i.requested_qty,
        resolution_type=CASE c.method WHEN 'cancel_unpaid' THEN 'cancelled' WHEN 'vendor_refused' THEN 'vendor_refused' ELSE 'refund' END,
        resolution_note=c.reason,resolved_by=auth.uid(),resolved_at=now() WHERE id=i.id;
    END LOOP;
    IF c.method IN ('refund','cancel_unpaid') THEN
      v_amount := (p_data->>'amount')::numeric;
      IF v_amount IS NULL OR v_amount <= 0 OR v_amount <> round(v_amount,2) OR v_amount::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'ระบุยอดเงินตามข้อตกลงให้ถูกต้อง'; END IF;
      INSERT INTO inv_receiving_case_finance(case_id,expected_amount,currency) VALUES(c.id,v_amount,upper(p_data->>'currency'));
    END IF;
    UPDATE inv_receiving_cases SET approved_by=auth.uid(),approved_at=now(),
      status=CASE c.method WHEN 'refund' THEN 'refund_pending' WHEN 'cancel_unpaid' THEN 'adjustment_pending' ELSE 'completed' END,
      completed_at=CASE WHEN c.method='vendor_refused' THEN now() ELSE NULL END WHERE id=c.id;
    IF NOT EXISTS (SELECT 1 FROM inv_po_items WHERE po_id=v_po AND qty > coalesce(qty_received_total,0)+coalesce(resolution_qty,0)) THEN
      UPDATE inv_po SET status='closed',updated_at=now() WHERE id=v_po;
    END IF;
  ELSIF p_action = 'reject' THEN
    IF c.status NOT IN ('pending','dispute') OR nullif(btrim(v_note),'') IS NULL THEN RAISE EXCEPTION 'ต้องเป็นรายการรออนุมัติ/ข้อพิพาท และระบุเหตุผล'; END IF;
    UPDATE inv_receiving_cases SET status='rejected',completed_at=now() WHERE id=c.id;
  ELSIF p_action = 'resubmit' THEN
    v_method := p_data->>'method';
    IF c.status <> 'dispute' OR v_method IS NULL OR v_method NOT IN ('refund','cancel_unpaid','vendor_refused') OR nullif(btrim(v_note),'') IS NULL THEN RAISE EXCEPTION 'เลือกวิธีจัดการและระบุผลการติดตาม'; END IF;
    UPDATE inv_receiving_cases SET method=v_method,status='pending',reason=v_note WHERE id=c.id;
    v_note := v_method || ': ' || v_note;
  ELSIF p_action = 'settle' THEN
    IF c.status NOT IN ('refund_pending','adjustment_pending') THEN RAISE EXCEPTION 'รายการไม่ได้รอบันทึกยอด'; END IF;
    SELECT * INTO f FROM inv_receiving_case_finance WHERE case_id=c.id FOR UPDATE;
    v_amount := (p_data->>'amount')::numeric;
    IF v_amount IS NULL OR v_amount <= 0 OR v_amount <> round(v_amount,2) OR v_amount::text IN ('NaN','Infinity','-Infinity') OR v_amount > f.expected_amount-f.settled_amount THEN RAISE EXCEPTION 'จำนวนเงินต้องมากกว่า 0 และไม่เกินยอดคงเหลือ'; END IF;
    INSERT INTO inv_receiving_case_settlements(case_id,amount,reference,settled_on,actor_id)
      VALUES(c.id,v_amount,btrim(p_data->>'reference'),(p_data->>'settled_on')::date,auth.uid());
    UPDATE inv_receiving_case_finance SET settled_amount=settled_amount+v_amount WHERE case_id=c.id;
    IF f.settled_amount+v_amount = f.expected_amount THEN UPDATE inv_receiving_cases SET status='completed',completed_at=now() WHERE id=c.id; END IF;
    -- Never put amounts or banking references in the operational audit trail.
    v_note := '';
  ELSIF p_action = 'note' THEN
    IF nullif(btrim(v_note),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุผลการติดตาม'; END IF;
  ELSE RAISE EXCEPTION 'คำสั่งไม่ถูกต้อง';
  END IF;
  UPDATE inv_receiving_cases SET updated_at=now() WHERE id=c.id;
  INSERT INTO inv_receiving_case_events(case_id,action,note,actor_id) VALUES(c.id,p_action,v_note,auth.uid());
END $$;


--
-- Name: rpc_receiving_case_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_receiving_case_users() RETURNS TABLE(id uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
