  SELECT u.id,coalesce(nullif(u.username,''),u.id::text) FROM us_users u
  WHERE public.erp_can_manage_receiving_cases() ORDER BY u.username;
$$;


--
-- Name: rpc_reconcile_reservation_excess(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reconcile_reservation_excess(p_items jsonb, p_reason text) RETURNS TABLE(batch_id uuid, product_id uuid, product_code text, old_reserved numeric, new_reserved numeric, released_qty numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record; a record; v_batch uuid:=gen_random_uuid();
BEGIN
 IF auth.uid() IS NULL THEN
   IF session_user NOT IN ('postgres','supabase_admin') AND NOT pg_has_role(session_user,'postgres','MEMBER') THEN RAISE EXCEPTION 'กรุณาเข้าสู่ระบบ'; END IF;
 ELSIF NOT public.check_user_role(auth.uid(),ARRAY['superadmin','admin','store']) THEN
   RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ยอดจอง' USING ERRCODE='42501';
 END IF;
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)=0
    OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'ต้องระบุรายการและเหตุผล'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <>
    (SELECT count(DISTINCT (x.value->>'product_id')::uuid) FROM jsonb_array_elements(p_items) x) THEN
   RAISE EXCEPTION 'รายการสินค้าซ้ำหรือไม่มีรหัส';
 END IF;
 -- Locks serialize with all reservation writers; compare with the reviewed snapshot.
 FOR r IN SELECT (x.value->>'product_id')::uuid AS id FROM jsonb_array_elements(p_items) x ORDER BY id LOOP
   PERFORM 1 FROM public.inv_stock_balances b WHERE b.product_id=r.id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบยอดสินค้า %',r.id; END IF;
 END LOOP;
 FOR r IN SELECT x.value AS input FROM jsonb_array_elements(p_items) x ORDER BY x.value->>'product_id' LOOP
   SELECT * INTO STRICT a FROM public.fn_reservation_audit(ARRAY[(r.input->>'product_id')::uuid]);
   IF a.reserved IS DISTINCT FROM (r.input->>'expected_reserved')::numeric
      OR a.linked_reserved IS DISTINCT FROM (r.input->>'expected_linked_reserved')::numeric THEN
     RAISE EXCEPTION 'ยอดเปลี่ยนหลังตรวจ กรุณาตรวจใหม่: %',a.product_code;
   END IF;
   IF a.classification<>'excess_with_completed_evidence' THEN
     RAISE EXCEPTION 'หลักฐานไม่ครบหรือไม่ใช่ยอดจองส่วนเกิน: % (%)',a.product_code,a.classification;
   END IF;
   INSERT INTO public.inv_reservation_reconciliations(batch_id,product_id,old_reserved,new_reserved,reason,evidence)
   VALUES(v_batch,a.product_id,a.reserved,a.linked_reserved,p_reason,a.evidence);
   UPDATE public.inv_stock_balances b SET reserved=a.linked_reserved,updated_at=now() WHERE b.product_id=a.product_id;
   batch_id:=v_batch; product_id:=a.product_id; product_code:=a.product_code;
   old_reserved:=a.reserved; new_reserved:=a.linked_reserved; released_qty:=a.reserved-a.linked_reserved;
   RETURN NEXT;
 END LOOP;
END $$;


--
-- Name: rpc_record_cancellation_waste(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_record_cancellation_waste(p_wms_order_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_movement RECORD;
  v_product_id UUID;
  v_qty NUMERIC;
  v_avg_cost NUMERIC;
  v_wms RECORD;
  v_reserved_qty NUMERIC := 0;
BEGIN
  SELECT id, status, product_code, qty, stock_action, source_order_item_id, order_id
  INTO v_wms FROM public.wms_orders WHERE id = p_wms_order_id;
  IF v_wms.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'wms row not found'); END IF;
  IF v_wms.stock_action IS NOT NULL THEN RETURN jsonb_build_object('success', false, 'error', 'already processed'); END IF;

  SELECT sm.id, sm.product_id, ABS(sm.qty) AS qty, sm.unit_cost
  INTO v_movement
  FROM public.inv_stock_movements sm
  WHERE sm.ref_type = 'wms_orders' AND sm.ref_id = p_wms_order_id AND sm.movement_type = 'pick'
  ORDER BY sm.created_at DESC LIMIT 1;

  IF v_movement.id IS NULL THEN
    SELECT id INTO v_product_id FROM public.pr_products WHERE product_code = v_wms.product_code LIMIT 1;
    IF v_wms.status = 'picked' AND v_product_id IS NOT NULL THEN
      v_reserved_qty := COALESCE(v_wms.qty, 0);
      UPDATE public.inv_stock_balances
      SET reserved = GREATEST(COALESCE(reserved, 0) - v_reserved_qty, 0), updated_at = NOW()
      WHERE product_id = v_product_id;
    END IF;
    UPDATE public.wms_orders SET stock_action = 'waste' WHERE id = p_wms_order_id;
    IF v_wms.source_order_item_id IS NOT NULL THEN
      UPDATE public.or_order_items SET cancellation_stock_action = 'waste' WHERE id = v_wms.source_order_item_id;
    END IF;
    RETURN jsonb_build_object('success', true, 'note', 'released reserved and marked as waste', 'released_reserved_qty', v_reserved_qty);
  END IF;

  v_product_id := v_movement.product_id;
  v_qty := v_movement.qty;
  v_avg_cost := COALESCE(v_movement.unit_cost, 0);
  INSERT INTO public.inv_stock_movements
    (product_id, movement_type, qty, ref_type, ref_id, note, unit_cost, total_cost, created_by)
  VALUES
    (v_product_id, 'waste', 0, 'wms_orders', p_wms_order_id, 'Waste mark from cancelled bill', v_avg_cost, 0, p_user_id);
  UPDATE public.wms_orders SET stock_action = 'waste' WHERE id = p_wms_order_id;

  IF v_wms.source_order_item_id IS NOT NULL THEN
    UPDATE public.or_order_items SET cancellation_stock_action = 'waste' WHERE id = v_wms.source_order_item_id;
  ELSE
    UPDATE public.or_order_items oi
    SET cancellation_stock_action = 'waste'
    FROM public.or_orders o, public.pr_products p
    WHERE oi.order_id = o.id AND p.id = oi.product_id
      AND oi.cancellation_stock_action = 'pending'
      AND TRIM(COALESCE(o.work_order_name, '')) = TRIM(COALESCE(v_wms.order_id, ''))
      AND UPPER(TRIM(COALESCE(p.product_code::TEXT, ''))) = UPPER(TRIM(COALESCE(v_wms.product_code, '')));
  END IF;
  RETURN jsonb_build_object('success', true, 'product_id', v_product_id, 'qty', v_qty, 'action', 'waste');
END;
$$;


--
-- Name: rpc_record_waste_cost(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_record_waste_cost(p_items jsonb, p_ref_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_item       JSONB;
  v_product_id UUID;
  v_qty        NUMERIC;
  v_movement_id UUID;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_qty        := (v_item->>'qty')::NUMERIC;

    IF v_qty IS NULL OR v_qty <= 0 THEN CONTINUE; END IF;

    INSERT INTO inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, created_by
    )
    VALUES (
      v_product_id, 'waste', -v_qty, 'inv_returns', p_ref_id,
      'ตีเป็นของเสีย', p_user_id
    )
    RETURNING id INTO v_movement_id;

    PERFORM fn_consume_stock_fifo(v_product_id, v_qty, v_movement_id);

    UPDATE inv_stock_balances
    SET on_hand = on_hand - v_qty
    WHERE product_id = v_product_id;

    PERFORM fn_recalc_product_landed_cost(v_product_id);
  END LOOP;
END;
$$;


