--
-- Name: rpc_reject_amendment(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reject_amendment(p_amendment_id uuid, p_approver_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role   TEXT;
  v_status TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = p_approver_id;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธ — ต้องเป็น superadmin หรือ admin เท่านั้น';
  END IF;

  SELECT status INTO v_status FROM or_order_amendments WHERE id = p_amendment_id;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'ใบขอแก้ไขนี้ไม่อยู่ในสถานะรออนุมัติ';
  END IF;

  UPDATE or_order_amendments
  SET status = 'rejected', approved_by = p_approver_id,
      approved_at = NOW(), rejected_reason = p_reason
  WHERE id = p_amendment_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: rpc_reject_claim_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reject_claim_request(p_request_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid  UUID := auth.uid();
  v_n    INT;
BEGIN
  SELECT u.role INTO v_role FROM us_users u WHERE u.id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธเคลม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  UPDATE or_claim_requests r
  SET status = 'rejected',
      reviewed_by = v_uid,
      reviewed_at = NOW(),
      rejected_reason = NULLIF(trim(both FROM p_reason), '')
  WHERE r.id = p_request_id
    AND r.status = 'pending';

  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN
    RAISE EXCEPTION 'ไม่พบคำขอที่รออนุมัติ หรืออัปเดตไม่สำเร็จ';
  END IF;
END;
$$;


--
-- Name: rpc_reject_pr(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reject_pr(p_pr_id uuid, p_user_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid  UUID := auth.uid();
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธ PR (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  UPDATE inv_pr
  SET status = 'rejected', rejected_by = v_uid, rejected_at = NOW(), rejection_reason = p_reason
  WHERE id = p_pr_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'PR ไม่อยู่ในสถานะรออนุมัติ'; END IF;
END;
$$;


--
-- Name: rpc_reject_production_order(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reject_production_order(p_order_id uuid, p_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_role TEXT; v_status TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid AND is_active IS TRUE;
  IF v_role IS NULL OR v_role NOT IN ('store', 'admin', 'superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธใบแปรรูป';
  END IF;
  SELECT status INTO v_status FROM pp_production_orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบใบแปรรูป'; END IF;
  IF v_status <> 'pending' THEN RAISE EXCEPTION 'ใบแปรรูปไม่ได้อยู่ในสถานะรออนุมัติ'; END IF;
  UPDATE pp_production_orders SET status = 'rejected', rejected_by = v_uid,
    rejected_at = now(), rejection_reason = p_reason WHERE id = p_order_id;
END;
$$;


--
-- Name: rpc_reorder_sub_warehouse_products(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reorder_sub_warehouse_products(p_sub_warehouse_id uuid, p_product_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_expected_count INTEGER;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN (
    'superadmin', 'admin', 'sales-tr', 'qc_order', 'sales-pump', 'qc_staff',
    'packing_staff', 'account', 'store', 'production', 'hr'
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์จัดลำดับสินค้าคลังย่อย';
  END IF;

  SELECT count(*) INTO v_expected_count
  FROM public.wh_sub_warehouse_products
  WHERE sub_warehouse_id = p_sub_warehouse_id;

  IF cardinality(p_product_ids) <> v_expected_count
     OR (SELECT count(DISTINCT ordered_pid.pid) FROM unnest(p_product_ids) AS ordered_pid(pid)) <> v_expected_count
     OR EXISTS (
       SELECT 1 FROM unnest(p_product_ids) AS ordered_pid(pid)
       WHERE NOT EXISTS (
         SELECT 1 FROM public.wh_sub_warehouse_products assigned
         WHERE assigned.sub_warehouse_id = p_sub_warehouse_id
           AND assigned.product_id = ordered_pid.pid
       )
     ) THEN
    RAISE EXCEPTION 'รายการสินค้าสำหรับจัดลำดับไม่ครบหรือไม่ถูกต้อง';
  END IF;

  UPDATE public.wh_sub_warehouse_products assigned
  SET sort_order = ordered.position
  FROM unnest(p_product_ids) WITH ORDINALITY AS ordered(product_id, position)
  WHERE assigned.sub_warehouse_id = p_sub_warehouse_id
    AND assigned.product_id = ordered.product_id;
END;
$$;


--
-- Name: rpc_repair_all_wms_missing_items(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_repair_all_wms_missing_items(p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT; r RECORD; v_result JSONB;
  v_repaired_rows INT:=0; v_repaired_qty NUMERIC:=0; v_picker_rows INT:=0;
  v_system_rows INT:=0; v_skipped_rows INT:=0; v_errors JSONB:='[]'::JSONB;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin','store') THEN RAISE EXCEPTION 'ไม่มีสิทธิ์ซ่อมสต๊อค'; END IF;
  IF p_from_date IS NULL OR p_to_date IS NULL OR p_from_date>p_to_date THEN RAISE EXCEPTION 'ช่วงวันที่ไม่ถูกต้อง'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('wms-bulk-repair-'||p_from_date::TEXT||'-'||p_to_date::TEXT));

  FOR r IN
    SELECT * FROM public.rpc_get_wms_stock_anomalies(p_from_date,p_to_date)
    WHERE anomaly_type='missing_wms' AND repairable
    ORDER BY work_order_name,bill_no,product_code,order_item_id
  LOOP
    BEGIN
      v_result:=public.rpc_repair_wms_missing_item(r.order_item_id);
      IF COALESCE((v_result->>'created_qty')::NUMERIC,0)>0 THEN
        v_repaired_rows:=v_repaired_rows+1;
        v_repaired_qty:=v_repaired_qty+(v_result->>'created_qty')::NUMERIC;
        IF v_result->>'mode'='system_complete' THEN v_system_rows:=v_system_rows+1;
        ELSE v_picker_rows:=v_picker_rows+1; END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_skipped_rows:=v_skipped_rows+1;
      IF jsonb_array_length(v_errors)<20 THEN
        v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
          'bill_no',r.bill_no,'product_code',r.product_code,'error',SQLERRM));
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success',true,'repaired_rows',v_repaired_rows,
    'repaired_qty',v_repaired_qty,'system_complete_rows',v_system_rows,
    'picker_rows',v_picker_rows,'skipped_rows',v_skipped_rows,'errors',v_errors);
END;
$$;


--
-- Name: rpc_repair_wms_excess_deduction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_repair_wms_excess_deduction(p_order_item_id uuid, p_reason text DEFAULT 'Repair excess WMS stock deduction from anomaly screen'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_product_id UUID;
  v_expected NUMERIC := 0;
  v_wms_qty NUMERIC := 0;
  v_correct NUMERIC := 0;
  v_deducted NUMERIC := 0;
  v_excess NUMERIC := 0;
  v_remaining NUMERIC := 0;
  v_restore NUMERIC := 0;
  v_restored_cost NUMERIC := 0;
  v_ref_id UUID;
  v_cons RECORD;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF v_role IS DISTINCT FROM 'superadmin' THEN
    RAISE EXCEPTION 'Only superadmin can repair an excess stock deduction';
  END IF;
  IF LENGTH(BTRIM(COALESCE(p_reason,''))) < 3 THEN
    RAISE EXCEPTION 'A repair reason is required';
  END IF;

  SELECT oi.product_id, COALESCE(oi.quantity,1)
  INTO v_product_id, v_expected
  FROM public.or_order_items oi
  WHERE oi.id=p_order_item_id
  FOR UPDATE;
  IF v_product_id IS NULL THEN RAISE EXCEPTION 'Order item not found'; END IF;

  PERFORM 1 FROM public.wms_orders w
  WHERE w.source_order_item_id=p_order_item_id FOR UPDATE;

  IF public.fn_wms_item_has_unlinked_legacy_conflict(p_order_item_id) THEN
    RAISE EXCEPTION 'Unlinked legacy WMS rows must be reviewed manually';
  END IF;

  SELECT COALESCE(SUM(w.qty) FILTER (WHERE w.status<>'cancelled'),0),
         COALESCE(SUM(w.qty) FILTER (WHERE w.status='correct'),0),
         (ARRAY_AGG(w.id ORDER BY w.created_at,w.id) FILTER (WHERE w.status='correct'))[1]
  INTO v_wms_qty,v_correct,v_ref_id
  FROM public.wms_orders w WHERE w.source_order_item_id=p_order_item_id;

  SELECT COALESCE(SUM(-m.qty) FILTER (WHERE m.movement_type IN ('pick','pick_reversal')),0)
  INTO v_deducted
  FROM public.wms_orders w
  JOIN public.inv_stock_movements m ON m.ref_type='wms_orders' AND m.ref_id=w.id
  WHERE w.source_order_item_id=p_order_item_id;

  IF v_wms_qty<>v_expected OR v_correct<>v_expected THEN
    RAISE EXCEPTION 'WMS quantities must match the sold quantity before repairing stock';
  END IF;
  IF v_deducted<=v_correct THEN
    RAISE EXCEPTION 'No excess stock deduction was found';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.wms_orders w
    JOIN public.inv_stock_movements m ON m.ref_type='wms_orders' AND m.ref_id=w.id
    WHERE w.source_order_item_id=p_order_item_id AND m.movement_type='pick_reversal'
  ) THEN
    RAISE EXCEPTION 'Existing reversals require manual review';
  END IF;

  v_excess := v_deducted-v_correct;
  v_remaining := v_excess;

  FOR v_cons IN
    SELECT lc.id,lc.lot_id,lc.qty,lc.unit_cost
    FROM public.wms_orders w
    JOIN public.inv_stock_movements m ON m.ref_type='wms_orders' AND m.ref_id=w.id AND m.movement_type='pick'
    JOIN public.inv_lot_consumptions lc ON lc.movement_id=m.id
    WHERE w.source_order_item_id=p_order_item_id
    ORDER BY m.created_at DESC,lc.created_at DESC
    FOR UPDATE OF lc
  LOOP
    EXIT WHEN v_remaining<=0;
    v_restore:=LEAST(v_cons.qty,v_remaining);
    UPDATE public.inv_stock_lots SET qty_remaining=qty_remaining+v_restore WHERE id=v_cons.lot_id;
    IF v_restore=v_cons.qty THEN
      DELETE FROM public.inv_lot_consumptions WHERE id=v_cons.id;
    ELSE
      UPDATE public.inv_lot_consumptions SET qty=qty-v_restore WHERE id=v_cons.id;
    END IF;
    v_restored_cost:=v_restored_cost+(v_restore*COALESCE(v_cons.unit_cost,0));
    v_remaining:=v_remaining-v_restore;
  END LOOP;

  INSERT INTO public.inv_stock_movements(
    product_id,movement_type,qty,ref_type,ref_id,note,unit_cost,total_cost,created_by
  ) VALUES (
    v_product_id,'pick_reversal',v_excess,'wms_orders',v_ref_id,
    'คืนยอดตัดสต๊อก WMS ซ้ำ: '||BTRIM(p_reason),
    CASE WHEN v_excess>0 THEN v_restored_cost/v_excess ELSE 0 END,
    v_restored_cost,auth.uid()
  );

  UPDATE public.inv_stock_balances
  SET on_hand=COALESCE(on_hand,0)+v_excess,updated_at=NOW()
  WHERE product_id=v_product_id;
  PERFORM public.fn_recalc_product_landed_cost(v_product_id);

  INSERT INTO public.wms_stock_repair_audit(order_item_id,product_id,repaired_qty,reason,repaired_by)
  VALUES(p_order_item_id,v_product_id,v_excess,BTRIM(p_reason),auth.uid());

  RETURN jsonb_build_object('success',true,'repaired_qty',v_excess);
END;
$$;


--
-- Name: rpc_repair_wms_missing_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_repair_wms_missing_item(p_order_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT; v_item RECORD; v_existing NUMERIC; v_missing NUMERIC; v_picker UUID; v_mode TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin','store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ซ่อมสต๊อค';
  END IF;

  SELECT oi.id,oi.order_id,oi.product_name,COALESCE(oi.quantity,1)::NUMERIC qty,
    o.work_order_id,o.work_order_name,p.product_code::TEXT product_code,
    COALESCE(p.storage_location::TEXT,'') location,
    COALESCE(NULLIF(BTRIM(p.unit_name::TEXT),''),'ชิ้น') unit_name,
    public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT) fulfillment_mode
  INTO v_item
  FROM public.or_order_items oi
  JOIN public.or_orders o ON o.id=oi.order_id
  JOIN public.pr_products p ON p.id=oi.product_id
  WHERE oi.id=p_order_item_id AND NOT COALESCE(oi.is_detail_row,false)
  FOR UPDATE OF oi;

  IF v_item.id IS NULL OR v_item.work_order_id IS NULL THEN
    RAISE EXCEPTION 'ไม่พบรายการหรือรายการยังไม่มีใบงาน';
  END IF;
  SELECT COALESCE(SUM(qty),0) INTO v_existing FROM public.wms_orders
  WHERE source_order_item_id=p_order_item_id AND status<>'cancelled';
  v_missing:=v_item.qty-v_existing;
  IF v_missing<=0 THEN
    RETURN jsonb_build_object('success',true,'created_qty',0,'message','รายการตรงกันแล้ว');
  END IF;
  IF public.fn_wms_item_has_legacy_stock_conflict(p_order_item_id) THEN
    RAISE EXCEPTION 'พบ WMS/Movement รุ่นเก่าหรือยอด Movement ไม่สัมพันธ์ ระบบบล็อกเพื่อป้องกันตัดซ้ำ';
  END IF;

  v_mode:=v_item.fulfillment_mode;
  IF v_mode='warehouse_pick' THEN
    SELECT assigned_to INTO v_picker FROM public.wms_orders
    WHERE work_order_id=v_item.work_order_id
      AND (fulfillment_mode='warehouse_pick' OR fulfillment_mode IS NULL)
      AND status<>'cancelled' AND assigned_to IS NOT NULL
    ORDER BY created_at DESC LIMIT 1;
    IF v_picker IS NULL THEN
      RAISE EXCEPTION 'ไม่พบผู้หยิบของของใบงาน กรุณามอบหมาย Picker ก่อน';
    END IF;
  END IF;

  INSERT INTO public.wms_orders(work_order_id,order_id,source_order_id,source_order_item_id,
    product_code,product_name,location,qty,unit_name,status,assigned_to,fulfillment_mode)
  VALUES(v_item.work_order_id,v_item.work_order_name,v_item.order_id,v_item.id,v_item.product_code,
    v_item.product_name,v_item.location,v_missing,v_item.unit_name,'pending',v_picker,v_mode);

  IF v_mode IN ('system_complete','sub_warehouse_skip') THEN
    UPDATE public.wms_orders SET status='correct',end_time=NOW()
    WHERE source_order_item_id=v_item.id AND status='pending' AND fulfillment_mode=v_mode;
  END IF;
  RETURN jsonb_build_object('success',true,'created_qty',v_missing,'mode',v_mode);
END;
$$;


--
-- Name: FUNCTION rpc_repair_wms_missing_item(p_order_item_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_repair_wms_missing_item(p_order_item_id uuid) IS 'Repairs one missing WMS line with legacy duplicate safeguards and supports legacy NULL fulfillment_mode picker assignments.';


--
-- Name: rpc_request_machinery_stock_return(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_request_machinery_stock_return(p_product_id uuid, p_qty numeric, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id UUID;
  v_available NUMERIC := 0;
BEGIN
  IF NOT public.can_manage_machinery_spares_all() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างคำขอคืนอะไหล่เข้าคลังหลัก';
  END IF;
  IF COALESCE(p_qty,0) <= 0 OR p_qty <> TRUNC(p_qty) THEN
    RAISE EXCEPTION 'จำนวนที่ขอคืนต้องเป็นจำนวนเต็มมากกว่า 0';
  END IF;

  SELECT COALESCE(qty,0)
  INTO v_available
  FROM public.pr_machinery_stock_balances
  WHERE product_id = p_product_id;

  IF v_available < p_qty THEN
    RAISE EXCEPTION 'สต๊อก Machinery ไม่เพียงพอสำหรับการคืน';
  END IF;

  INSERT INTO public.pr_machinery_stock_transfers(
    transfer_no, product_id, qty, direction, note, requested_by
  ) VALUES (
    public.fn_next_machinery_transfer_no(), p_product_id, p_qty, 'to_main',
    NULLIF(BTRIM(p_note),''), auth.uid()
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: rpc_request_machinery_stock_transfer(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_request_machinery_stock_transfer(p_product_id uuid, p_qty numeric, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id UUID;
BEGIN
  IF NOT public.can_manage_machinery_spares_all() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างคำขอโอนอะไหล่';
  END IF;
  IF COALESCE(p_qty,0) <= 0 OR p_qty <> TRUNC(p_qty) THEN RAISE EXCEPTION 'จำนวนที่ขอโอนต้องเป็นจำนวนเต็มมากกว่า 0'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.pr_machinery_purchase_products
    WHERE product_id = p_product_id AND enabled = true
  ) THEN RAISE EXCEPTION 'สินค้านี้ยังไม่ได้เปิดใช้ใน Machinery'; END IF;

  INSERT INTO public.pr_machinery_stock_transfers(
    transfer_no, product_id, qty, note, requested_by
  ) VALUES (
    public.fn_next_machinery_transfer_no(), p_product_id, p_qty,
    NULLIF(BTRIM(p_note),''), auth.uid()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: rpc_request_prebill_discount(uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_request_prebill_discount(p_document_id uuid, p_discount_type text, p_discount_value numeric, p_note text) RETURNS public.or_prebill_documents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc public.or_prebill_documents;
  v_name TEXT;
  v_discount NUMERIC;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND is_active) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์'; END IF;
  SELECT COALESCE(username, email) INTO v_name FROM public.us_users WHERE id = auth.uid();
  SELECT * INTO v_doc FROM public.or_prebill_documents WHERE id = p_document_id FOR UPDATE;
  IF v_doc.id IS NULL OR NOT public.can_manage_prebill_document(v_doc.owner_id) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์';
  END IF;
  IF v_doc.status NOT IN ('draft', 'active', 'rejected') THEN
    RAISE EXCEPTION 'สถานะเอกสารไม่อนุญาตให้ขอส่วนลด';
  END IF;
  IF p_discount_type NOT IN ('amount', 'percent') OR p_discount_value <= 0 THEN
    RAISE EXCEPTION 'ส่วนลดไม่ถูกต้อง';
  END IF;
  IF btrim(COALESCE(p_note, '')) = '' THEN RAISE EXCEPTION 'กรุณาระบุหมายเหตุคำขอ'; END IF;
  v_discount := CASE WHEN p_discount_type = 'percent'
    THEN round(v_doc.subtotal * least(p_discount_value, 100) / 100, 2)
    ELSE least(p_discount_value, v_doc.subtotal)
  END;
  v_discount:=least(v_discount,greatest(0,v_doc.subtotal+v_doc.shipping_cost-v_doc.promotion_discount));
  IF v_discount<=0 THEN RAISE EXCEPTION 'ไม่มียอดคงเหลือให้ขอส่วนลด'; END IF;
  UPDATE public.or_prebill_documents SET
    status = 'pending_discount', special_discount_type = p_discount_type,
    special_discount_value = p_discount_value, special_discount = v_discount,
    discount_request_note = btrim(p_note), discount_requested_at = now(),
    discount_requested_by = auth.uid(), approved_special_discount = NULL,
    approved_at = NULL, approved_by = NULL, approval_note = NULL, rejection_note = NULL,
    total_amount = greatest(0, subtotal + shipping_cost - promotion_discount - v_discount),
    updated_at = now()
  WHERE id = p_document_id RETURNING * INTO v_doc;
  INSERT INTO public.or_prebill_approval_logs(
    document_id, action, requested_discount, note, actor_id, actor_name
  ) VALUES (p_document_id, 'requested', v_discount, btrim(p_note), auth.uid(), v_name);
  RETURN v_doc;
END;
$$;


--
-- Name: rpc_request_sales_discount(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_request_sales_discount(p_order_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE o public.or_orders; req uuid; snap jsonb; state_ jsonb; who text;
BEGIN
 IF NOT public.or_discount_can_manage(p_order_id) THEN RAISE EXCEPTION 'ไม่มีสิทธิ์'; END IF;
 SELECT * INTO o FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
 IF o.status NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') OR o.work_order_id IS NOT NULL
  OR o.source_prebill_document_id IS NOT NULL OR o.source_marketplace_order_id IS NOT NULL OR upper(o.bill_no) LIKE 'REQ%' THEN RAISE EXCEPTION 'บิลนี้ไม่สามารถส่งขอส่วนลดโดยตรงได้'; END IF;
 IF btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลขอส่วนลด'; END IF;
 snap:=public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id));
 IF o.total_amount IS NULL OR o.price IS NULL OR o.discount IS NULL OR o.shipping_cost IS NULL OR o.discount<=0 OR o.total_amount<0 OR o.discount>o.price+o.shipping_cost OR o.total_amount<>round(o.price+o.shipping_cost-o.discount,2)
  OR jsonb_array_length(snap->'items')=0 THEN RAISE EXCEPTION 'สินค้า ส่วนลด หรือยอดสุทธิไม่ถูกต้อง'; END IF;
 UPDATE public.or_sales_discount_requests SET status='stale' WHERE order_id=o.id AND status IN ('pending','approved');
 SELECT coalesce(username,email) INTO who FROM public.us_users WHERE id=auth.uid();
 INSERT INTO public.or_sales_discount_requests(order_id,status,snapshot,reason,requested_by,requested_name)
 VALUES(o.id,'pending',snap,btrim(p_reason),auth.uid(),who) RETURNING id INTO req;
 UPDATE public.or_orders SET discount_approval_enabled=true WHERE id=o.id;
 RETURN req;
END $$;


--
-- Name: rpc_resolve_cancelled_wms(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_resolve_cancelled_wms(p_wms_order_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_wms public.wms_orders%ROWTYPE;
  v_product_id UUID;
  v_stock_qty NUMERIC := 0;
  v_net_deducted NUMERIC := 0;
  v_movement_id UUID;
  v_result JSONB;
  v_on_hand NUMERIC := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการสต๊อกรายการยกเลิก';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('not_picked', 'recall', 'waste') THEN
    RAISE EXCEPTION 'วิธีจัดการไม่ถูกต้อง: %', p_action;
  END IF;

  SELECT * INTO v_wms
  FROM public.wms_orders
  WHERE id = p_wms_order_id
  FOR UPDATE;

  IF v_wms.id IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการ WMS'; END IF;
  IF v_wms.status <> 'cancelled' THEN RAISE EXCEPTION 'รายการนี้ไม่ได้อยู่ในสถานะยกเลิก'; END IF;
  IF v_wms.stock_action IS NOT NULL THEN
    RETURN jsonb_build_object('success', TRUE, 'already_processed', TRUE, 'action', v_wms.stock_action);
  END IF;

  SELECT COALESCE(SUM(-m.qty) FILTER (
    WHERE m.movement_type IN ('pick', 'pick_reversal')
  ), 0)
  INTO v_net_deducted
  FROM public.inv_stock_movements m
  WHERE m.ref_type = 'wms_orders' AND m.ref_id = v_wms.id;
  v_net_deducted := GREATEST(v_net_deducted, 0);

  SELECT p.id INTO v_product_id
  FROM public.pr_products p
  WHERE UPPER(BTRIM(COALESCE(p.product_code::TEXT, ''))) = UPPER(BTRIM(COALESCE(v_wms.product_code, '')))
  LIMIT 1;
  v_stock_qty := COALESCE(v_wms.qty, 0);

  IF p_action = 'not_picked' THEN
    IF v_net_deducted > 0 OR COALESCE(v_wms.status_before_cancel, '') IN ('picked', 'correct') THEN
      RAISE EXCEPTION 'รายการนี้เคยหยิบหรือมีการตัดสต๊อกแล้ว กรุณาเลือกคืนสต๊อกหรือของเสีย';
    END IF;
    UPDATE public.wms_orders SET stock_action = 'not_picked' WHERE id = v_wms.id;

  ELSIF p_action = 'recall' THEN
    IF v_net_deducted > 0 THEN
      PERFORM public.fn_reverse_wms_stock(v_wms.id);
    ELSIF v_wms.status_before_cancel = 'picked' THEN
      IF v_product_id IS NULL THEN RAISE EXCEPTION 'ไม่พบสินค้าในคลัง'; END IF;
      PERFORM 1 FROM public.inv_stock_balances WHERE product_id = v_product_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบยอดคงเหลือของสินค้าในคลัง'; END IF;
      UPDATE public.inv_stock_balances
      SET reserved = GREATEST(COALESCE(reserved, 0) - v_stock_qty, 0), updated_at = NOW()
      WHERE product_id = v_product_id;
      UPDATE public.wms_orders SET stock_action = 'recalled' WHERE id = v_wms.id;
    ELSE
      RAISE EXCEPTION 'รายการนี้ไม่มีการหยิบหรือตัดสต๊อก กรุณาเลือก “ไม่ได้หยิบ”';
    END IF;

  ELSE
    IF v_net_deducted > 0 THEN
      SELECT public.rpc_record_cancellation_waste(v_wms.id, auth.uid()) INTO v_result;
    ELSIF v_wms.status_before_cancel = 'picked' THEN
      IF v_product_id IS NULL THEN RAISE EXCEPTION 'ไม่พบสินค้าในคลัง'; END IF;
      SELECT COALESCE(on_hand, 0) INTO v_on_hand
      FROM public.inv_stock_balances
      WHERE product_id = v_product_id
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบยอดคงเหลือของสินค้าในคลัง'; END IF;
      IF v_on_hand < v_stock_qty THEN
        RAISE EXCEPTION 'ยอดคงเหลือไม่พอสำหรับบันทึกของเสีย ขาด %', v_stock_qty - v_on_hand;
      END IF;
      INSERT INTO public.inv_stock_movements(
        product_id, movement_type, qty, ref_type, ref_id, note, created_by
      ) VALUES (
        v_product_id, 'waste', -v_stock_qty, 'wms_orders', v_wms.id,
        'ของเสียจากบิลยกเลิกหลังหยิบแต่ก่อนตรวจหยิบถูก', auth.uid()
      ) RETURNING id INTO v_movement_id;
      PERFORM public.fn_consume_stock_fifo(v_product_id, v_stock_qty, v_movement_id);
      UPDATE public.inv_stock_balances
      SET on_hand = COALESCE(on_hand, 0) - v_stock_qty,
          reserved = GREATEST(COALESCE(reserved, 0) - v_stock_qty, 0),
          updated_at = NOW()
      WHERE product_id = v_product_id;
      PERFORM public.fn_recalc_product_landed_cost(v_product_id);
      UPDATE public.wms_orders SET stock_action = 'waste' WHERE id = v_wms.id;
    ELSE
      RAISE EXCEPTION 'รายการนี้ไม่มีการหยิบหรือตัดสต๊อก กรุณาเลือก “ไม่ได้หยิบ”';
    END IF;
  END IF;

  IF v_wms.source_order_item_id IS NOT NULL THEN
    UPDATE public.or_order_items
    SET cancellation_stock_action = CASE WHEN p_action = 'recall' THEN 'recalled' ELSE p_action END
    WHERE id = v_wms.source_order_item_id;
  ELSE
    UPDATE public.or_order_items oi
    SET cancellation_stock_action = CASE WHEN p_action = 'recall' THEN 'recalled' ELSE p_action END
    FROM public.or_orders o, public.pr_products p
    WHERE oi.order_id = o.id
      AND p.id = oi.product_id
      AND oi.cancellation_stock_action = 'pending'
      AND BTRIM(COALESCE(o.work_order_name, '')) = BTRIM(COALESCE(v_wms.order_id, ''))
      AND UPPER(BTRIM(COALESCE(p.product_code::TEXT, ''))) = UPPER(BTRIM(COALESCE(v_wms.product_code, '')));
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'action', CASE WHEN p_action = 'recall' THEN 'recalled' ELSE p_action END,
    'net_deducted_qty', v_net_deducted
  );
END;
$$;


