-- Name: rpc_resolve_po_shortage(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_resolve_po_shortage(p_po_id uuid, p_resolutions jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
