--
-- Name: rpc_resubmit_rejected_claim_request(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_resubmit_rejected_claim_request(p_request_id uuid, p_proposed_snapshot jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role TEXT;
  v_request public.or_claim_requests%ROWTYPE;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'sales-tr', 'sales-pump', 'qc_order', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขและส่งคำขอเคลมอีกครั้ง';
  END IF;

  SELECT * INTO v_request
  FROM public.or_claim_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL OR v_request.status <> 'rejected' THEN
    RAISE EXCEPTION 'ไม่พบคำขอเคลมที่ถูกปฏิเสธ หรือรายการนี้ถูกส่งใหม่แล้ว';
  END IF;

  IF p_proposed_snapshot IS NULL
     OR jsonb_typeof(p_proposed_snapshot) <> 'object'
     OR jsonb_typeof(p_proposed_snapshot->'order') <> 'object'
     OR jsonb_typeof(p_proposed_snapshot->'items') <> 'array'
     OR jsonb_array_length(p_proposed_snapshot->'items') = 0 THEN
    RAISE EXCEPTION 'ข้อมูลบิลเคลมไม่สมบูรณ์';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.or_orders reference_order
    WHERE reference_order.id = v_request.ref_order_id
      AND reference_order.status = 'จัดส่งแล้ว'
  ) THEN
    RAISE EXCEPTION 'บิลอ้างอิงต้องอยู่ในสถานะจัดส่งแล้ว';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.or_claim_requests other
    WHERE other.ref_order_id = v_request.ref_order_id
      AND other.status = 'pending'
      AND other.id <> v_request.id
  ) THEN
    RAISE EXCEPTION 'บิลอ้างอิงนี้มีคำขอเคลมที่รออนุมัติอยู่แล้ว';
  END IF;

  UPDATE public.or_claim_requests
  SET proposed_snapshot = p_proposed_snapshot,
      rejection_history = COALESCE(rejection_history, '[]'::JSONB) || jsonb_build_array(
        jsonb_build_object(
          'reason', rejected_reason,
          'reviewed_by', reviewed_by,
          'reviewed_at', reviewed_at,
          'resubmitted_by', v_uid,
          'resubmitted_at', now()
        )
      ),
      status = 'pending',
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejected_reason = NULL,
      resubmitted_at = now(),
      resubmission_count = COALESCE(resubmission_count, 0) + 1
  WHERE id = p_request_id;
END;
$$;


--
-- Name: rpc_return_machinery_part(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_return_machinery_part(p_usage_id uuid, p_qty numeric, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_usage public.pr_machinery_incident_parts%ROWTYPE;
  v_returned NUMERIC := 0;
  v_current public.pr_machinery_stock_balances%ROWTYPE;
  v_return_id UUID;
BEGIN
  IF NOT public.can_use_machinery_spares() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์คืนอะไหล่'; END IF;
  IF COALESCE(p_qty,0) <= 0 OR p_qty <> TRUNC(p_qty) THEN RAISE EXCEPTION 'จำนวนที่คืนต้องเป็นจำนวนเต็มมากกว่า 0'; END IF;
  SELECT * INTO v_usage FROM public.pr_machinery_incident_parts
  WHERE id = p_usage_id AND event_type = 'use' FOR UPDATE;
  IF v_usage.id IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการใช้อะไหล่'; END IF;
  SELECT COALESCE(SUM(qty),0) INTO v_returned FROM public.pr_machinery_incident_parts
  WHERE return_of_id = v_usage.id AND event_type = 'return';
  IF v_returned + p_qty > v_usage.qty THEN RAISE EXCEPTION 'จำนวนคืนมากกว่าจำนวนที่ใช้'; END IF;

  SELECT * INTO v_current FROM public.pr_machinery_stock_balances
  WHERE product_id = v_usage.product_id FOR UPDATE;
  INSERT INTO public.pr_machinery_stock_balances(product_id, qty, average_unit_cost)
  VALUES (v_usage.product_id, p_qty, v_usage.unit_cost)
  ON CONFLICT (product_id) DO UPDATE SET
    average_unit_cost = CASE
      WHEN public.pr_machinery_stock_balances.qty + EXCLUDED.qty > 0 THEN
        ((public.pr_machinery_stock_balances.qty * public.pr_machinery_stock_balances.average_unit_cost)
          + (EXCLUDED.qty * EXCLUDED.average_unit_cost))
        / (public.pr_machinery_stock_balances.qty + EXCLUDED.qty)
      ELSE 0 END,
    qty = public.pr_machinery_stock_balances.qty + EXCLUDED.qty,
    updated_at = NOW();

  INSERT INTO public.pr_machinery_incident_parts(
    incident_id, machine_id, product_id, event_type, qty, unit_cost,
    return_of_id, note, performed_by
  ) VALUES (
    v_usage.incident_id, v_usage.machine_id, v_usage.product_id, 'return', p_qty,
    v_usage.unit_cost, v_usage.id, NULLIF(BTRIM(p_note),''), auth.uid()
  ) RETURNING id INTO v_return_id;
  INSERT INTO public.pr_machinery_stock_moves(
    product_id, qty_delta, movement_type, unit_cost, incident_part_id, note, created_by
  ) VALUES (
    v_usage.product_id, p_qty, 'part_return', v_usage.unit_cost,
    v_return_id, 'คืนอะไหล่', auth.uid()
  );
  RETURN v_return_id;
END;
$$;


--
-- Name: rpc_review_prebill_discount(uuid, boolean, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_review_prebill_discount(p_document_id uuid, p_approve boolean, p_approved_discount numeric, p_note text) RETURNS public.or_prebill_documents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc public.or_prebill_documents;
  v_name TEXT;
  v_requested NUMERIC;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role='superadmin' AND is_active) THEN RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้น'; END IF;
  IF p_approve IS NULL THEN RAISE EXCEPTION 'กรุณาระบุผลพิจารณา'; END IF;
  IF NOT p_approve AND btrim(coalesce(p_note,''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ไม่อนุมัติ'; END IF;
  SELECT COALESCE(username, email) INTO v_name FROM public.us_users WHERE id = auth.uid();
  SELECT * INTO v_doc FROM public.or_prebill_documents WHERE id = p_document_id FOR UPDATE;
  IF v_doc.id IS NULL OR v_doc.status <> 'pending_discount' THEN RAISE EXCEPTION 'เอกสารไม่ได้รออนุมัติ'; END IF;
  v_requested := v_doc.special_discount;
  IF p_approve THEN
    UPDATE public.or_prebill_documents SET status = 'approved',
      approved_special_discount = greatest(0, least(COALESCE(p_approved_discount, special_discount), subtotal, greatest(0,subtotal+shipping_cost-promotion_discount))),
      special_discount = greatest(0, least(COALESCE(p_approved_discount, special_discount), subtotal, greatest(0,subtotal+shipping_cost-promotion_discount))),
      approved_at = now(), approved_by = auth.uid(), approval_note = NULLIF(btrim(COALESCE(p_note,'')), ''),
      rejection_note = NULL,
      total_amount = greatest(0, subtotal + shipping_cost - promotion_discount - greatest(0, least(COALESCE(p_approved_discount, special_discount), subtotal, greatest(0,subtotal+shipping_cost-promotion_discount)))),
      updated_at = now()
    WHERE id = p_document_id RETURNING * INTO v_doc;
    INSERT INTO public.or_prebill_approval_logs(document_id, action, requested_discount, approved_discount, note, actor_id, actor_name)
    VALUES (p_document_id, 'approved', v_requested, v_doc.approved_special_discount, p_note, auth.uid(), v_name);
  ELSE
    UPDATE public.or_prebill_documents SET status = 'rejected', rejection_note = NULLIF(btrim(COALESCE(p_note,'')), ''),
      special_discount = 0, total_amount = greatest(0, subtotal + shipping_cost - promotion_discount), updated_at = now()
    WHERE id = p_document_id RETURNING * INTO v_doc;
    INSERT INTO public.or_prebill_approval_logs(document_id, action, requested_discount, note, actor_id, actor_name)
    VALUES (p_document_id, 'rejected', v_requested, p_note, auth.uid(), v_name);
  END IF;
  RETURN v_doc;
END;
$$;


--
-- Name: rpc_review_sales_discount(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_review_sales_discount(p_request_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.or_sales_discount_requests; o public.or_orders; who text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND is_active AND role='superadmin') THEN RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้นที่อนุมัติส่วนลดได้'; END IF;
 IF p_approve IS NULL THEN RAISE EXCEPTION 'กรุณาระบุผลพิจารณา'; END IF;
 SELECT * INTO r FROM public.or_sales_discount_requests WHERE id=p_request_id;
 SELECT * INTO o FROM public.or_orders WHERE id=r.order_id FOR UPDATE;
 SELECT * INTO r FROM public.or_sales_discount_requests WHERE id=p_request_id FOR UPDATE;
 IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'คำขอไม่ได้รออนุมัติ'; END IF;
 IF o.status NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') OR o.work_order_id IS NOT NULL
  OR r.snapshot<>public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id)) THEN RAISE EXCEPTION 'รายการหรือยอดเปลี่ยนแล้ว ต้องส่งขออนุมัติใหม่'; END IF;
 IF NOT p_approve AND btrim(coalesce(p_note,''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ไม่อนุมัติ'; END IF;
 SELECT coalesce(username,email) INTO who FROM public.us_users WHERE id=auth.uid();
 UPDATE public.or_sales_discount_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
 reviewed_by=auth.uid(),reviewed_name=who,reviewed_at=now(),review_note=nullif(btrim(p_note),'') WHERE id=r.id;
END $$;


--
-- Name: rpc_save_bill_edit_with_revision(uuid, jsonb, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_save_bill_edit_with_revision(p_order_id uuid, p_order_data jsonb, p_items jsonb, p_user_name text, p_edit_changes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role          TEXT;
  v_order         RECORD;
  v_snapshot_order JSONB;
  v_snapshot_items JSONB;
  v_new_rev       INT;
  v_bill_no       TEXT;
  v_item          JSONB;
  v_idx           INT := 0;
  v_item_uid      TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account', 'sales-tr', 'sales-pump') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขบิล (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT * INTO v_order FROM or_orders WHERE id = p_order_id;
  IF v_order.id IS NULL THEN RAISE EXCEPTION 'ไม่พบออเดอร์'; END IF;

  SELECT row_to_json(o)::jsonb INTO v_snapshot_order
  FROM or_orders o WHERE o.id = p_order_id;

  SELECT COALESCE(jsonb_agg(row_to_json(oi)::jsonb), '[]'::jsonb)
  INTO v_snapshot_items
  FROM or_order_items oi WHERE oi.order_id = p_order_id;

  UPDATE or_orders SET
    customer_name    = COALESCE(p_order_data->>'customer_name', customer_name),
    customer_address = COALESCE(p_order_data->>'customer_address', customer_address),
    channel_code     = COALESCE(p_order_data->>'channel_code', channel_code),
    total_amount     = COALESCE((p_order_data->>'total_amount')::numeric, total_amount),
    price            = COALESCE((p_order_data->>'price')::numeric, price),
    shipping_cost    = COALESCE((p_order_data->>'shipping_cost')::numeric, shipping_cost),
    discount         = COALESCE((p_order_data->>'discount')::numeric, discount),
    payment_method   = COALESCE(p_order_data->>'payment_method', payment_method),
    payment_date     = COALESCE(p_order_data->>'payment_date', payment_date),
    payment_time     = COALESCE(p_order_data->>'payment_time', payment_time),
    promotion        = COALESCE(p_order_data->>'promotion', promotion),
    tracking_number  = COALESCE(p_order_data->>'tracking_number', tracking_number),
    recipient_name   = COALESCE(p_order_data->>'recipient_name', recipient_name),
    channel_order_no = COALESCE(p_order_data->>'channel_order_no', channel_order_no),
    confirm_note     = COALESCE(p_order_data->>'confirm_note', confirm_note),
    status           = COALESCE(p_order_data->>'status', status),
    billing_details  = CASE
      WHEN p_order_data ? 'billing_details' THEN (p_order_data->'billing_details')
      ELSE billing_details
    END,
    updated_at       = NOW()
  WHERE id = p_order_id;

  v_bill_no := COALESCE(v_order.bill_no, '');

  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    DELETE FROM or_order_items WHERE order_id = p_order_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      v_idx := v_idx + 1;
      v_item_uid := CASE WHEN v_bill_no <> '' THEN v_bill_no || '-' || v_idx
                         ELSE 'EDIT-' || v_idx END;

      INSERT INTO or_order_items (
        order_id, item_uid, product_id, product_name, quantity,
        unit_price, ink_color, product_type, cartoon_pattern,
        line_pattern, font, line_1, line_2, line_3,
        no_name_line, is_free, notes, file_attachment
      ) VALUES (
        p_order_id,
        v_item_uid,
        CASE WHEN v_item->>'product_id' IS NOT NULL AND v_item->>'product_id' <> ''
             THEN (v_item->>'product_id')::uuid ELSE NULL END,
        COALESCE(v_item->>'product_name', ''),
        COALESCE((v_item->>'quantity')::int, 1),
        COALESCE((v_item->>'unit_price')::numeric, 0),
        v_item->>'ink_color',
        COALESCE(v_item->>'product_type', 'ชั้น1'),
        v_item->>'cartoon_pattern',
        v_item->>'line_pattern',
        v_item->>'font',
        v_item->>'line_1',
        v_item->>'line_2',
        v_item->>'line_3',
        COALESCE((v_item->>'no_name_line')::boolean, false),
        COALESCE((v_item->>'is_free')::boolean, false),
        v_item->>'notes',
        v_item->>'file_attachment'
      );
    END LOOP;
  END IF;

  v_new_rev := COALESCE(v_order.revision_no, 0) + 1;

  INSERT INTO or_order_revisions (
    order_id, revision_no, change_source, change_source_id,
    snapshot_order, snapshot_items, created_by
  ) VALUES (
    p_order_id, v_new_rev, 'direct_edit', NULL,
    v_snapshot_order, v_snapshot_items, p_user_name
  );

  UPDATE or_orders SET revision_no = v_new_rev WHERE id = p_order_id;

  INSERT INTO ac_bill_edit_logs (
    order_id, bill_no, edited_by,
    changes, items_snapshot_before, items_snapshot_after
  ) VALUES (
    p_order_id, v_bill_no, p_user_name,
    p_edit_changes, v_snapshot_items,
    (SELECT COALESCE(jsonb_agg(row_to_json(oi)::jsonb), '[]'::jsonb)
     FROM or_order_items oi WHERE oi.order_id = p_order_id)
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: rpc_save_marketplace_bill(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_save_marketplace_bill(p_order_id uuid, p_order_data jsonb, p_items jsonb) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_order public.or_orders;
  v_assignments text;
  v_status text;
  v_allowed text[] := ARRAY[
    'channel_code','customer_name','customer_address','channel_order_no','recipient_name',
    'scheduled_pickup_at','tracking_number','express_receipt_number','price','shipping_cost',
    'discount','total_amount','payment_method','promotion','payment_date','payment_time',
    'fulfillment_method','requires_confirm_design','status','entry_date','billing_details','last_edited_by'
  ];
BEGIN
  IF jsonb_typeof(p_order_data) IS DISTINCT FROM 'object' OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'ข้อมูลบิลหรือรายการสินค้าไม่ถูกต้อง';
  END IF;
  IF jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'กรุณาตรวจสอบรายการสินค้าและ SKU ต้นทางก่อนบันทึก'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_order_data) AS fields(key) WHERE NOT key=ANY(v_allowed)) THEN
    RAISE EXCEPTION 'มีฟิลด์บิลที่ไม่อนุญาตให้แก้ไข';
  END IF;
  IF nullif(p_order_data->>'status','') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุสถานะบิล'; END IF;

  SELECT * INTO v_order FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบหรือไม่มีสิทธิ์แก้ไขบิล'; END IF;
  IF v_order.source_marketplace_order_id IS NULL THEN RAISE EXCEPTION 'บิลนี้ไม่ได้มาจาก Marketplace'; END IF;
  IF v_order.status='รอตรวจคำสั่งซื้อ' THEN
    RAISE EXCEPTION 'บิล Marketplace อยู่ระหว่างรอตรวจคำสั่งซื้อ กรุณาตีกลับก่อนแก้ไขข้อมูล';
  END IF;

  PERFORM public.rpc_save_order_items(p_order_id,p_items);
  SELECT string_agg(format('%I = proposed.%I',key,key),', ' ORDER BY key)
    INTO v_assignments FROM jsonb_object_keys(p_order_data) AS fields(key);
  EXECUTE format('UPDATE public.or_orders AS target SET %s
    FROM jsonb_populate_record(NULL::public.or_orders,$1) AS proposed
    WHERE target.id=$2 RETURNING target.status',v_assignments)
    INTO v_status USING p_order_data,p_order_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่สามารถบันทึกบิลได้'; END IF;
  RETURN v_status;
END $_$;


--
-- Name: rpc_save_order_items(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_save_order_items(p_order_id uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE x jsonb; r record; v_item public.or_order_items; v_existing public.or_order_items; v_position integer := 0; v_sequence bigint; v_bill_no text;
BEGIN
  PERFORM 1 FROM public.or_orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบหรือไม่มีสิทธิ์แก้ไขบิล'; END IF;
  IF jsonb_typeof(p_items)<>'array' THEN RAISE EXCEPTION 'รายการสินค้าไม่ถูกต้อง'; END IF;
  PERFORM set_config('app.reservation_save','order:'||p_order_id::text,true);
  FOR r IN SELECT product_id FROM public.or_order_items WHERE order_id=p_order_id AND product_id IS NOT NULL
    UNION SELECT (value->>'product_id')::uuid FROM jsonb_array_elements(p_items) WHERE value->>'product_id' IS NOT NULL ORDER BY product_id
  LOOP PERFORM 1 FROM public.inv_stock_balances WHERE product_id=r.product_id FOR UPDATE; END LOOP;
  SELECT bill_no INTO v_bill_no FROM public.or_orders WHERE id=p_order_id;
  SELECT greatest(coalesce(max(substring(item_uid from '-([0-9]+)$')::bigint),0),
    (SELECT item_uid_sequence FROM public.or_orders WHERE id=p_order_id)) INTO v_sequence
    FROM public.or_order_items WHERE order_id=p_order_id;
  DELETE FROM public.or_order_items i WHERE order_id=p_order_id
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_items) candidate WHERE (candidate.value->>'id')::uuid=i.id);
  FOR x IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_position := v_position + 1;
    x := x || jsonb_build_object('sort_order',v_position);
    SELECT * INTO v_existing FROM public.or_order_items WHERE id=(x->>'id')::uuid AND order_id=p_order_id;
    IF FOUND THEN
      v_item:=jsonb_populate_record(v_existing,x||jsonb_build_object('order_id',p_order_id,'item_uid',v_existing.item_uid));
      UPDATE public.or_order_items SET product_id=v_item.product_id,product_name=v_item.product_name,quantity=v_item.quantity,
        sort_order=v_item.sort_order,item_uid=v_item.item_uid,is_detail_row=v_item.is_detail_row,parent_item_id=v_item.parent_item_id,unit_price=v_item.unit_price,
        ink_color=v_item.ink_color,product_type=v_item.product_type,cartoon_pattern=v_item.cartoon_pattern,line_pattern=v_item.line_pattern,
        font=v_item.font,line_1=v_item.line_1,line_2=v_item.line_2,line_3=v_item.line_3,no_name_line=v_item.no_name_line,
        is_free=v_item.is_free,notes=v_item.notes,file_attachment=v_item.file_attachment,attachment_name=v_item.attachment_name
      WHERE id=v_item.id AND order_id=p_order_id;
    ELSE
      v_sequence := v_sequence + 1;
      IF v_bill_no IS NOT NULL THEN
        x := x || jsonb_build_object('item_uid',v_bill_no||'-'||v_sequence);
      END IF;
      v_item:=jsonb_populate_record(NULL::public.or_order_items,
        jsonb_build_object('created_at',now(),'updated_at',now())||x||jsonb_build_object('order_id',p_order_id));
      INSERT INTO public.or_order_items SELECT (v_item).*;
    END IF;
  END LOOP;
  PERFORM set_config('app.reservation_save','',true);
  UPDATE public.or_orders SET updated_at=now(),item_uid_sequence=v_sequence WHERE id=p_order_id;
END $_$;


--
-- Name: rpc_save_prebill_document(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_save_prebill_document(p_id uuid, p_document jsonb, p_items jsonb) RETURNS public.or_prebill_documents
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_doc public.or_prebill_documents; v_item public.or_prebill_items; x jsonb; r record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'กรุณาเข้าสู่ระบบ'; END IF;
  IF jsonb_typeof(p_items)<>'array' THEN RAISE EXCEPTION 'รายการสินค้าไม่ถูกต้อง'; END IF;
  IF p_id IS NOT NULL THEN
    SELECT * INTO STRICT v_doc FROM public.or_prebill_documents WHERE id=p_id FOR UPDATE;
  ELSE
    v_doc:=jsonb_populate_record(NULL::public.or_prebill_documents,
      jsonb_build_object('id',gen_random_uuid(),'status','draft','owner_id',auth.uid(),'special_discount_value',0,
      'stock_reservation_enabled',true,'created_at',now(),'updated_at',now()));
  END IF;
  IF v_doc.status IN ('converted','cancelled') THEN RAISE EXCEPTION 'เอกสารนี้แก้ไขไม่ได้'; END IF;
  PERFORM set_config('app.reservation_save','prebill:'||v_doc.id::text,true);
  p_document:=p_document-'id'-'stock_reservation_enabled'-'converted_order_id'-'converted_at'-'approved_at'-'approved_by'-'approved_special_discount';
  v_doc:=jsonb_populate_record(v_doc,p_document);
  -- Lock products in a consistent order before replacing any rows.
  FOR r IN SELECT product_id FROM public.or_prebill_items WHERE document_id=v_doc.id AND product_id IS NOT NULL
    UNION SELECT (value->>'product_id')::uuid FROM jsonb_array_elements(p_items) WHERE value->>'product_id' IS NOT NULL ORDER BY product_id
  LOOP PERFORM 1 FROM public.inv_stock_balances WHERE product_id=r.product_id FOR UPDATE; END LOOP;
  IF p_id IS NULL THEN INSERT INTO public.or_prebill_documents SELECT (v_doc).*;
  ELSE
    UPDATE public.or_prebill_documents SET
      document_type=v_doc.document_type,document_no=v_doc.document_no,status=v_doc.status,channel_code=v_doc.channel_code,
      header_name=v_doc.header_name,customer_name=v_doc.customer_name,customer_address=v_doc.customer_address,
      recipient_name=v_doc.recipient_name,customer_phone=v_doc.customer_phone,billing_details=v_doc.billing_details,
      delivery_term=v_doc.delivery_term,valid_until=v_doc.valid_until,payment_method=v_doc.payment_method,
      subtotal=v_doc.subtotal,shipping_cost=v_doc.shipping_cost,promotion_discount=v_doc.promotion_discount,
      special_discount=v_doc.special_discount,total_amount=v_doc.total_amount,promotion_ids=v_doc.promotion_ids,
      promotion_snapshot=v_doc.promotion_snapshot,shipping_snapshot=v_doc.shipping_snapshot,internal_note=v_doc.internal_note,
      owner_id=v_doc.owner_id,owner_name=v_doc.owner_name,source_document_id=v_doc.source_document_id,updated_at=now()
    WHERE id=p_id;
  END IF;
  DELETE FROM public.or_prebill_items WHERE document_id=v_doc.id;
  FOR x IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_item:=jsonb_populate_record(NULL::public.or_prebill_items,
      jsonb_build_object('id',gen_random_uuid(),'document_id',v_doc.id,'created_at',now(),'updated_at',now())||x||jsonb_build_object('document_id',v_doc.id));
    INSERT INTO public.or_prebill_items SELECT (v_item).*;
  END LOOP;
  PERFORM set_config('app.reservation_save','',true);
  UPDATE public.or_prebill_documents SET updated_at=now() WHERE id=v_doc.id;
  SELECT * INTO STRICT v_doc FROM public.or_prebill_documents WHERE id=v_doc.id;
  RETURN v_doc;
END $$;


--
-- Name: rpc_set_machinery_machine_parts(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_machinery_machine_parts(p_machine_id uuid, p_product_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_product_id UUID;
BEGIN
  IF NOT public.can_manage_machinery_spares_all() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์กำหนดอะไหล่ประจำเครื่อง';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pr_machinery_machines WHERE id = p_machine_id) THEN
    RAISE EXCEPTION 'ไม่พบเครื่องจักร';
  END IF;
  DELETE FROM public.pr_machinery_machine_parts WHERE machine_id = p_machine_id;
  FOREACH v_product_id IN ARRAY COALESCE(p_product_ids, ARRAY[]::UUID[])
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.pr_machinery_purchase_products
      WHERE product_id = v_product_id AND enabled = true
    ) THEN
      RAISE EXCEPTION 'สินค้าที่เลือกยังไม่ได้เปิดใช้ในตั้งค่าสินค้า Machinery';
    END IF;
    INSERT INTO public.pr_machinery_machine_parts(machine_id, product_id, created_by)
    VALUES (p_machine_id, v_product_id, auth.uid()) ON CONFLICT DO NOTHING;
  END LOOP;
END;
$$;


--
-- Name: rpc_set_product_location_labels(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_product_location_labels(p_product_id uuid, p_labels jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item JSONB;
  v_type TEXT;
  v_location_id UUID;
  v_name TEXT;
  v_movement_name TEXT;
  v_move_location_id UUID;
BEGIN
  IF NOT public.can_manage_product_location_labels() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขชื่อจุดจัดเก็บสินค้า';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pr_products WHERE id = p_product_id) THEN
    RAISE EXCEPTION 'ไม่พบสินค้า';
  END IF;
  IF p_labels IS NULL OR jsonb_typeof(p_labels) <> 'array' THEN
    RAISE EXCEPTION 'รูปแบบข้อมูลจุดจัดเก็บไม่ถูกต้อง';
  END IF;

  SELECT id INTO v_move_location_id
  FROM public.wh_storage_locations
  WHERE LOWER(BTRIM(code)) = 'move'
  LIMIT 1;

  DELETE FROM public.wh_product_location_labels WHERE product_id = p_product_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_labels)
  LOOP
    v_type := NULLIF(BTRIM(v_item->>'label_type'), '');
    v_name := NULLIF(BTRIM(v_item->>'display_name'), '');
    v_location_id := NULLIF(v_item->>'location_id', '')::UUID;

    IF v_name IS NULL THEN CONTINUE; END IF;
    IF v_type NOT IN ('movement', 'storage', 'safety') THEN
      RAISE EXCEPTION 'ประเภทจุดจัดเก็บไม่ถูกต้อง';
    END IF;
    IF v_type = 'storage' AND (
      v_location_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.wh_storage_locations WHERE id = v_location_id
      )
    ) THEN
      RAISE EXCEPTION 'ไม่พบจุดจัดเก็บที่เลือก';
    END IF;

    INSERT INTO public.wh_product_location_labels(
      product_id, label_type, location_id, display_name, updated_by
    ) VALUES (
      p_product_id,
      v_type,
      CASE WHEN v_type = 'storage' THEN v_location_id ELSE NULL END,
      v_name,
      auth.uid()
    );

    IF v_type = 'movement'
       OR (v_type = 'storage' AND v_location_id = v_move_location_id) THEN
      v_movement_name := v_name;
    END IF;
  END LOOP;

  UPDATE public.pr_products
  SET storage_location = v_movement_name,
      updated_at = NOW()
  WHERE id = p_product_id;
END;
$$;


--
-- Name: FUNCTION rpc_set_product_location_labels(p_product_id uuid, p_labels jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_set_product_location_labels(p_product_id uuid, p_labels jsonb) IS 'Replaces product-specific storage labels and syncs the MOVE label to pr_products.storage_location.';


--
-- Name: rpc_set_sub_warehouse_replenishment_request(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_sub_warehouse_replenishment_request(p_sub_warehouse_id uuid, p_product_id uuid, p_requested_qty numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request_id UUID;
BEGIN
  IF NOT public.can_request_sub_warehouse_stock() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ขอเบิกสินค้าคลังย่อย';
  END IF;
  IF p_requested_qty IS NULL OR p_requested_qty <= 0 THEN
    RAISE EXCEPTION 'จำนวนที่ขอเบิกต้องมากกว่า 0';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.wh_sub_warehouses warehouse
    WHERE warehouse.id = p_sub_warehouse_id AND warehouse.is_active = true
  ) OR NOT EXISTS (
    SELECT 1 FROM public.wh_sub_warehouse_products assigned
    WHERE assigned.sub_warehouse_id = p_sub_warehouse_id
      AND assigned.product_id = p_product_id
  ) THEN
    RAISE EXCEPTION 'ไม่พบสินค้านี้ในคลังย่อยที่เลือก';
  END IF;

  INSERT INTO public.wh_sub_warehouse_replenishment_requests (
    sub_warehouse_id, product_id, requested_qty, requested_by
  ) VALUES (
    p_sub_warehouse_id, p_product_id, p_requested_qty, auth.uid()
  )
  ON CONFLICT (sub_warehouse_id, product_id, requested_by)
    WHERE status = 'pending'
  DO UPDATE SET
    requested_qty = EXCLUDED.requested_qty,
    updated_at = NOW()
  RETURNING id INTO v_request_id;

  RETURN v_request_id;
END;
$$;


--
-- Name: rpc_start_inventory_epoch(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_start_inventory_epoch(p_pin text, p_epoch_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid UUID := auth.uid();
  v_epoch_id BIGINT;
  v_epoch_name TEXT;
  v_rows INT := 0;
  v_opening_value NUMERIC := 0;
BEGIN
  IF COALESCE(p_pin, '') <> '1688' THEN
    RAISE EXCEPTION 'รหัสยืนยันไม่ถูกต้อง';
  END IF;

  IF v_uid IS NOT NULL THEN
    SELECT role INTO v_role FROM us_users WHERE id = v_uid;
    IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
      RAISE EXCEPTION 'ไม่มีสิทธิ์เริ่มรอบบัญชีสต๊อกใหม่';
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('inventory_epoch_start'));

  UPDATE ac_inventory_epochs
  SET is_active = FALSE
  WHERE is_active = TRUE;

  v_epoch_name := COALESCE(
    NULLIF(trim(COALESCE(p_epoch_name, '')), ''),
    'EPOCH-' || to_char(NOW() AT TIME ZONE 'Asia/Bangkok', 'YYYYMMDD-HH24MI')
  );

  INSERT INTO ac_inventory_epochs (
    epoch_name, started_at, is_active, note, created_by
  )
  VALUES (
    v_epoch_name, NOW(), TRUE, p_note, v_uid
  )
  RETURNING id INTO v_epoch_id;

  INSERT INTO ac_inventory_epoch_openings (
    epoch_id, product_id, opening_qty, opening_value, opening_safety_qty, opening_safety_value
  )
  SELECT
    v_epoch_id,
    l.product_id,
    ROUND(SUM(CASE WHEN COALESCE(l.is_safety_stock, FALSE) = FALSE THEN l.qty_remaining ELSE 0 END), 2) AS opening_qty,
    ROUND(SUM(CASE WHEN COALESCE(l.is_safety_stock, FALSE) = FALSE THEN l.qty_remaining * l.unit_cost ELSE 0 END), 2) AS opening_value,
    ROUND(SUM(CASE WHEN COALESCE(l.is_safety_stock, FALSE) = TRUE  THEN l.qty_remaining ELSE 0 END), 2) AS opening_safety_qty,
    ROUND(SUM(CASE WHEN COALESCE(l.is_safety_stock, FALSE) = TRUE  THEN l.qty_remaining * l.unit_cost ELSE 0 END), 2) AS opening_safety_value
  FROM inv_stock_lots l
  WHERE l.qty_remaining > 0
  GROUP BY l.product_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  SELECT COALESCE(SUM(opening_value), 0)
  INTO v_opening_value
  FROM ac_inventory_epoch_openings
  WHERE epoch_id = v_epoch_id;

  RETURN jsonb_build_object(
    'success', true,
    'epoch_id', v_epoch_id,
    'epoch_name', v_epoch_name,
    'snapshot_products', v_rows,
    'opening_inventory_value', ROUND(v_opening_value, 2),
    'created_by', v_uid
  );
END;
$$;


--
-- Name: FUNCTION rpc_start_inventory_epoch(p_pin text, p_epoch_name text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_start_inventory_epoch(p_pin text, p_epoch_name text, p_note text) IS 'เริ่มรอบบัญชีสต๊อก: PIN 1688 บังคับเสมอ. ถ้ามี auth.uid() ต้องเป็น superadmin/admin/account. ถ้าไม่มี uid (เช่น SQL Editor) ใช้ได้เมื่อ PIN ถูก — created_by อาจเป็น NULL';


--
-- Name: rpc_start_production_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_start_production_order(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid AND is_active IS TRUE;
  IF v_role IS NULL OR v_role NOT IN ('production', 'packing_staff', 'admin', 'superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เริ่มแปรรูป';
  END IF;
  UPDATE pp_production_orders SET status = 'processing', started_by = v_uid, started_at = now()
  WHERE id = p_order_id AND status = 'approved';
  IF NOT FOUND THEN RAISE EXCEPTION 'ใบแปรรูปไม่ได้อยู่ในสถานะรอแปรรูป'; END IF;
END;
$$;


--
-- Name: rpc_submit_amendment(uuid, text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_submit_amendment(p_order_id uuid, p_reason_type text, p_reason_detail text, p_changes_json jsonb, p_items_after jsonb, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_amendment_no TEXT;
  v_bill_no      TEXT;
  v_items_before JSONB;
  v_amendment_id UUID;
  v_pending      INT;
BEGIN
  -- ตรวจว่ายังไม่มี pending amendment
  SELECT COUNT(*) INTO v_pending
  FROM or_order_amendments
  WHERE order_id = p_order_id AND status = 'pending';

  IF v_pending > 0 THEN
    RAISE EXCEPTION 'บิลนี้มีใบขอแก้ไขรออนุมัติอยู่แล้ว';
  END IF;

  SELECT bill_no INTO v_bill_no FROM or_orders WHERE id = p_order_id;

  -- เก็บ snapshot items ปัจจุบัน
  SELECT COALESCE(jsonb_agg(row_to_json(oi)::jsonb), '[]'::jsonb)
  INTO v_items_before
  FROM or_order_items oi
  WHERE oi.order_id = p_order_id;

  v_amendment_no := rpc_generate_amendment_no();

  INSERT INTO or_order_amendments (
    amendment_no, order_id, bill_no, reason_type, reason_detail,
    status, requested_by, changes_json, items_before, items_after
  ) VALUES (
    v_amendment_no, p_order_id, v_bill_no, p_reason_type, p_reason_detail,
    'pending', p_user_id, p_changes_json, v_items_before, p_items_after
  ) RETURNING id INTO v_amendment_id;

  RETURN jsonb_build_object(
    'id', v_amendment_id,
    'amendment_no', v_amendment_no,
    'status', 'pending'
  );
END;
$$;


--
-- Name: rpc_submit_claim_order_revision(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_submit_claim_order_revision(p_order_id uuid, p_proposed_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role TEXT;
  v_request public.or_claim_requests%ROWTYPE;
  v_order public.or_orders%ROWTYPE;
  v_snapshot JSONB;
  v_price NUMERIC;
  v_shipping NUMERIC;
  v_discount NUMERIC;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'sales-tr', 'sales-pump', 'qc_order', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขและส่งบิลเคลมอนุมัติใหม่';
  END IF;

  SELECT * INTO v_order
  FROM public.or_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_order.id IS NULL OR upper(COALESCE(v_order.bill_no, '')) NOT LIKE 'REQ%' THEN
    RAISE EXCEPTION 'ไม่พบบิลเคลม';
  END IF;
  IF v_order.status NOT IN ('ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ') THEN
    RAISE EXCEPTION 'ส่งอนุมัติใหม่ได้เฉพาะบิลที่ตรวจสอบสลิปไม่ผ่าน';
  END IF;

  SELECT * INTO v_request
  FROM public.or_claim_requests
  WHERE created_claim_order_id = p_order_id
  ORDER BY reviewed_at DESC NULLS LAST, created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_request.id IS NULL OR v_request.status <> 'approved' THEN
    RAISE EXCEPTION 'ไม่พบคำขอเคลมที่อนุมัติแล้วของบิลนี้';
  END IF;

  IF p_proposed_snapshot IS NULL
     OR jsonb_typeof(p_proposed_snapshot) <> 'object'
     OR jsonb_typeof(p_proposed_snapshot->'order') <> 'object'
     OR jsonb_typeof(p_proposed_snapshot->'items') <> 'array'
     OR jsonb_array_length(p_proposed_snapshot->'items') = 0 THEN
    RAISE EXCEPTION 'ข้อมูลบิลเคลมที่แก้ไขไม่สมบูรณ์';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_proposed_snapshot->'items') AS row(value)
    WHERE btrim(COALESCE(value->>'product_name', '')) = ''
       OR COALESCE((value->>'quantity')::INTEGER, 0) < 1
       OR COALESCE((value->>'unit_price')::NUMERIC, 0) < 0
  ) THEN
    RAISE EXCEPTION 'สินค้า จำนวน หรือราคาไม่ถูกต้อง';
  END IF;

  SELECT COALESCE(SUM(
    CASE WHEN COALESCE((value->>'is_free')::BOOLEAN, false)
      THEN 0
      ELSE COALESCE((value->>'quantity')::NUMERIC, 0) * COALESCE((value->>'unit_price')::NUMERIC, 0)
    END
  ), 0)
  INTO v_price
  FROM jsonb_array_elements(p_proposed_snapshot->'items') AS row(value);

  v_shipping := GREATEST(COALESCE((p_proposed_snapshot->'order'->>'shipping_cost')::NUMERIC, 0), 0);
  v_discount := GREATEST(COALESCE((p_proposed_snapshot->'order'->>'discount')::NUMERIC, 0), 0);
  v_snapshot := jsonb_set(
    p_proposed_snapshot,
    '{order}',
    (p_proposed_snapshot->'order') || jsonb_build_object(
      'price', v_price,
      'shipping_cost', v_shipping,
      'discount', v_discount,
      'total_amount', v_price + v_shipping - v_discount
    )
  );

  UPDATE public.or_claim_requests
  SET proposed_snapshot = v_snapshot,
      approval_history = COALESCE(approval_history, '[]'::JSONB) || jsonb_build_array(
        jsonb_build_object(
          'reviewed_by', reviewed_by,
          'reviewed_at', reviewed_at,
          'revision_submitted_by', v_uid,
          'revision_submitted_at', now()
        )
      ),
      status = 'pending',
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejected_reason = NULL,
      reapproval_count = COALESCE(reapproval_count, 0) + 1
  WHERE id = v_request.id;

  UPDATE public.or_orders
  SET status = 'รออนุมัติเคลม',
      claim_shipping_confirmed_at = NULL,
      updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'request_id', v_request.id,
    'order_id', p_order_id,
    'bill_no', v_order.bill_no,
    'status', 'pending'
  );
END;
$$;


--
-- Name: FUNCTION rpc_submit_claim_order_revision(p_order_id uuid, p_proposed_snapshot jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_submit_claim_order_revision(p_order_id uuid, p_proposed_snapshot jsonb) IS 'Submits changed items/prices of an existing failed-slip REQ bill for account reapproval without mutating the approved bill.';


--
-- Name: rpc_submit_production_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_submit_production_order(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role   TEXT;
  v_status TEXT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'store', 'production', 'packing_staff') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ส่งอนุมัติใบผลิต (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status FROM pp_production_orders WHERE id = p_order_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบใบผลิต'; END IF;
  IF v_status <> 'open' THEN
    RAISE EXCEPTION 'ใบผลิตไม่อยู่ในสถานะเปิด (status: %)', v_status;
  END IF;

  UPDATE pp_production_orders SET status = 'pending' WHERE id = p_order_id;
END;
$$;


