--
-- Name: rpc_sync_pr_sellers_from_products(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_sync_pr_sellers_from_products() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_inserted INT := 0;
  v_updated INT := 0;
  rec RECORD;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ซิงก์รายชื่อผู้ขาย';
  END IF;

  FOR rec IN
    SELECT
      TRIM(seller_name) AS name,
      MAX(NULLIF(TRIM(seller_name_cn), '')) AS name_cn,
      MAX(NULLIF(TRIM(seller_purchase_channel), '')) AS purchase_channel,
      CASE
        WHEN COUNT(*) FILTER (WHERE fn_normalize_seller_type(seller_type) = 'thailand') >
             COUNT(*) FILTER (WHERE fn_normalize_seller_type(seller_type) = 'foreign')
          THEN 'thailand'
        WHEN COUNT(*) FILTER (WHERE fn_normalize_seller_type(seller_type) = 'foreign') > 0
          THEN 'foreign'
        ELSE NULL
      END AS seller_type
    FROM pr_products
    WHERE seller_name IS NOT NULL AND TRIM(seller_name) <> ''
    GROUP BY TRIM(seller_name)
  LOOP
    IF EXISTS (SELECT 1 FROM pr_sellers WHERE name = rec.name) THEN
      v_updated := v_updated + 1;
    ELSE
      v_inserted := v_inserted + 1;
    END IF;

    PERFORM fn_upsert_pr_seller_from_product(
      rec.name,
      rec.name_cn,
      rec.purchase_channel,
      rec.seller_type
    );
  END LOOP;

  RETURN jsonb_build_object(
    'inserted', v_inserted,
    'updated', v_updated,
    'synced_from_products', v_inserted + v_updated
  );
END;
$$;


--
-- Name: FUNCTION rpc_sync_pr_sellers_from_products(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_sync_pr_sellers_from_products() IS 'ดึงชื่อและ metadata ผู้ขายจาก pr_products เข้า pr_sellers (upsert); เรียกได้เฉพาะ superadmin, admin';


--
-- Name: rpc_trial_balance_products(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_trial_balance_products(p_year integer, p_month integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_month_start TIMESTAMPTZ;
  v_month_end   TIMESTAMPTZ;
  v_result      JSONB;
BEGIN
  v_month_start := make_timestamptz(p_year, p_month, 1, 0, 0, 0, 'Asia/Bangkok');
  v_month_end   := v_month_start + INTERVAL '1 month';

  WITH current_lots AS (
    SELECT product_id,
           SUM(CASE WHEN is_safety_stock = FALSE THEN qty_remaining ELSE 0 END) AS current_qty,
           SUM(CASE WHEN is_safety_stock = FALSE THEN qty_remaining * unit_cost ELSE 0 END) AS current_val,
           SUM(CASE WHEN is_safety_stock = TRUE  THEN qty_remaining ELSE 0 END) AS ss_qty
    FROM inv_stock_lots
    WHERE qty_remaining > 0
    GROUP BY product_id
  ),
  after_month AS (
    SELECT product_id,
           SUM(qty)        AS net_qty,
           SUM(total_cost) AS net_val
    FROM inv_stock_movements
    WHERE created_at >= v_month_end
      AND movement_type <> 'waste'
      AND total_cost IS NOT NULL
    GROUP BY product_id
  ),
  month_movements AS (
    SELECT product_id,
           SUM(qty)        AS net_qty,
           SUM(total_cost) AS net_val
    FROM inv_stock_movements
    WHERE created_at >= v_month_start AND created_at < v_month_end
      AND movement_type <> 'waste'
      AND total_cost IS NOT NULL
    GROUP BY product_id
  ),
  month_by_type AS (
    SELECT product_id,
           SUM(CASE WHEN movement_type = 'gr'                                   THEN qty ELSE 0 END) AS purchases_qty,
           SUM(CASE WHEN movement_type = 'gr'                                   THEN total_cost ELSE 0 END) AS purchases_val,
           SUM(CASE WHEN movement_type = 'pick'                                 THEN ABS(qty) ELSE 0 END) AS cogs_qty,
           SUM(CASE WHEN movement_type = 'pick'                                 THEN ABS(total_cost) ELSE 0 END) AS cogs_val,
           SUM(CASE WHEN movement_type IN ('return_requisition','return')       THEN qty ELSE 0 END) AS returns_qty,
           SUM(CASE WHEN movement_type IN ('return_requisition','return')       THEN total_cost ELSE 0 END) AS returns_val,
           SUM(CASE WHEN movement_type = 'waste'                                THEN ABS(qty) ELSE 0 END) AS waste_qty,
           SUM(CASE WHEN movement_type = 'waste'                                THEN ABS(total_cost) ELSE 0 END) AS waste_val,
           SUM(CASE WHEN movement_type = 'adjust'                               THEN qty ELSE 0 END) AS adjust_qty,
           SUM(CASE WHEN movement_type = 'adjust'                               THEN total_cost ELSE 0 END) AS adjust_val
    FROM inv_stock_movements
    WHERE created_at >= v_month_start AND created_at < v_month_end
      AND total_cost IS NOT NULL
    GROUP BY product_id
  ),
  all_products AS (
    SELECT DISTINCT product_id FROM (
      SELECT product_id FROM current_lots
      UNION
      SELECT product_id FROM month_by_type
    ) u
  ),
  result AS (
    SELECT
      ap.product_id,
      pp.product_code,
      pp.product_name,
      ROUND(COALESCE(cl.current_val, 0) - COALESCE(am.net_val, 0) - COALESCE(mm.net_val, 0), 2) AS beginning_value,
      ROUND(COALESCE(cl.current_qty, 0) - COALESCE(am.net_qty, 0) - COALESCE(mm.net_qty, 0), 2) AS beginning_qty,
      ROUND(COALESCE(cl.current_val, 0) - COALESCE(am.net_val, 0), 2) AS ending_value,
      ROUND(COALESCE(cl.current_qty, 0) - COALESCE(am.net_qty, 0), 2) AS ending_qty,
      ROUND(COALESCE(cl.ss_qty, 0), 2) AS safety_stock_qty,
      ROUND(COALESCE(cl.ss_qty, 0) * fn_get_latest_gr_lot_cost(ap.product_id), 2) AS safety_stock_value,
      ROUND(COALESCE(mt.purchases_qty, 0), 2) AS purchases_qty,
      ROUND(COALESCE(mt.purchases_val, 0), 2) AS purchases_value,
      ROUND(COALESCE(mt.cogs_qty, 0), 2) AS cogs_qty,
      ROUND(COALESCE(mt.cogs_val, 0), 2) AS cogs_value,
      ROUND(COALESCE(mt.returns_qty, 0), 2) AS returns_qty,
      ROUND(COALESCE(mt.returns_val, 0), 2) AS returns_value,
      ROUND(COALESCE(mt.waste_qty, 0), 2) AS waste_qty,
      ROUND(COALESCE(mt.waste_val, 0), 2) AS waste_value,
      ROUND(COALESCE(mt.adjust_qty, 0), 2) AS adjust_qty,
      ROUND(COALESCE(mt.adjust_val, 0), 2) AS adjust_value
    FROM all_products ap
    JOIN pr_products pp ON pp.id = ap.product_id
    LEFT JOIN current_lots cl ON cl.product_id = ap.product_id
    LEFT JOIN after_month am ON am.product_id = ap.product_id
    LEFT JOIN month_movements mm ON mm.product_id = ap.product_id
    LEFT JOIN month_by_type mt ON mt.product_id = ap.product_id
    ORDER BY pp.product_code
  )
  SELECT COALESCE(jsonb_agg(row_to_json(result)), '[]'::JSONB)
  INTO v_result
  FROM result;

  RETURN v_result;
END;
$$;


--
-- Name: rpc_trial_balance_summary(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_trial_balance_summary(p_year integer, p_month integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_month_start TIMESTAMPTZ;
  v_month_end   TIMESTAMPTZ;
  v_calc_start  TIMESTAMPTZ;
  v_use_epoch   BOOLEAN := FALSE;
  v_epoch_id    BIGINT;
  v_epoch_start TIMESTAMPTZ;
  v_opening_inventory NUMERIC := 0;
  v_opening_safety    NUMERIC := 0;
  v_net_before_month  NUMERIC := 0;
  v_purchases        NUMERIC := 0;
  v_cogs             NUMERIC := 0;
  v_requisition_cogs NUMERIC := 0;
  v_customer_cogs    NUMERIC := 0;
  v_returns          NUMERIC := 0;
  v_waste            NUMERIC := 0;
  v_adjustments      NUMERIC := 0;
  v_current_lot_val  NUMERIC := 0;
  v_current_ss_val   NUMERIC := 0;
  v_after_month_net  NUMERIC := 0;
  v_month_net        NUMERIC := 0;
  v_ending           NUMERIC := 0;
  v_beginning        NUMERIC := 0;
  v_movement_count   INT := 0;
  v_product_count    INT := 0;
  v_gross_sales      NUMERIC := 0;
  v_refunds_approved NUMERIC := 0;
  v_net_sales        NUMERIC := 0;
  v_gross_profit     NUMERIC := 0;
  v_gross_margin_pct NUMERIC := 0;
  v_rec              RECORD;
BEGIN
  v_month_start := make_timestamptz(p_year, p_month, 1, 0, 0, 0, 'Asia/Bangkok');
  v_month_end   := v_month_start + INTERVAL '1 month';
  v_calc_start := v_month_start;

  SELECT id, started_at
  INTO v_epoch_id, v_epoch_start
  FROM ac_inventory_epochs
  WHERE is_active = TRUE
  ORDER BY started_at DESC, id DESC
  LIMIT 1;

  IF v_epoch_id IS NOT NULL AND v_month_end > v_epoch_start THEN
    v_use_epoch := TRUE;
    IF v_epoch_start > v_calc_start THEN
      v_calc_start := v_epoch_start;
    END IF;
  END IF;

  FOR v_rec IN
    SELECT movement_type,
           SUM(total_cost) AS total,
           COUNT(*)        AS cnt
    FROM inv_stock_movements
    WHERE created_at >= v_calc_start AND created_at < v_month_end
      AND total_cost IS NOT NULL
    GROUP BY movement_type
  LOOP
    v_movement_count := v_movement_count + v_rec.cnt;
    CASE v_rec.movement_type
      WHEN 'gr'                   THEN v_purchases   := v_rec.total;
      WHEN 'pick'                 THEN v_cogs        := ABS(v_rec.total);
      WHEN 'pick_reversal'        THEN v_cogs        := v_cogs - v_rec.total;
      WHEN 'return_requisition'   THEN v_returns     := v_returns + v_rec.total;
      WHEN 'return'               THEN v_returns     := v_returns + v_rec.total;
      WHEN 'waste'                THEN v_waste       := ABS(v_rec.total);
      WHEN 'adjust'               THEN v_adjustments := v_rec.total;
      ELSE NULL;
    END CASE;
  END LOOP;

  SELECT COUNT(DISTINCT product_id) INTO v_product_count
  FROM inv_stock_movements
  WHERE created_at >= v_calc_start AND created_at < v_month_end;

  WITH safety_qty AS (
    SELECT product_id, SUM(qty_remaining) AS ss_qty
    FROM inv_stock_lots
    WHERE qty_remaining > 0
      AND is_safety_stock = TRUE
    GROUP BY product_id
  )
  SELECT COALESCE(SUM(sq.ss_qty * fn_get_latest_gr_lot_cost(sq.product_id)), 0)
  INTO v_current_ss_val
  FROM safety_qty sq;

  IF v_use_epoch THEN
    SELECT
      COALESCE(SUM(opening_value), 0),
      COALESCE(SUM(opening_safety_value), 0)
    INTO v_opening_inventory, v_opening_safety
    FROM ac_inventory_epoch_openings
    WHERE epoch_id = v_epoch_id;

    IF v_month_start > v_epoch_start THEN
      SELECT COALESCE(SUM(total_cost), 0)
      INTO v_net_before_month
      FROM inv_stock_movements
      WHERE created_at >= v_epoch_start
        AND created_at < v_month_start
        AND movement_type <> 'waste'
        AND total_cost IS NOT NULL;
    END IF;

    v_beginning := v_opening_inventory + v_net_before_month;

    SELECT COALESCE(SUM(total_cost), 0)
    INTO v_month_net
    FROM inv_stock_movements
    WHERE created_at >= v_calc_start AND created_at < v_month_end
      AND movement_type <> 'waste'
      AND total_cost IS NOT NULL;

    v_ending := v_beginning + v_month_net;
    v_current_ss_val := COALESCE(v_current_ss_val, v_opening_safety);
  ELSE
    SELECT COALESCE(SUM(qty_remaining * unit_cost), 0)
    INTO v_current_lot_val
    FROM inv_stock_lots
    WHERE qty_remaining > 0 AND is_safety_stock = FALSE;

    SELECT COALESCE(SUM(total_cost), 0)
    INTO v_after_month_net
    FROM inv_stock_movements
    WHERE created_at >= v_month_end
      AND movement_type <> 'waste'
      AND total_cost IS NOT NULL;

    v_ending := v_current_lot_val - v_after_month_net;

    SELECT COALESCE(SUM(total_cost), 0)
    INTO v_month_net
    FROM inv_stock_movements
    WHERE created_at >= v_month_start AND created_at < v_month_end
      AND movement_type <> 'waste'
      AND total_cost IS NOT NULL;

    v_beginning := v_ending - v_month_net;
  END IF;

  SELECT COALESCE(SUM(
    CASE
      WHEN sm.movement_type = 'pick' THEN ABS(sm.total_cost)
      WHEN sm.movement_type = 'pick_reversal' THEN -sm.total_cost
      ELSE 0
    END
  ), 0)
  INTO v_requisition_cogs
  FROM inv_stock_movements sm
  JOIN wms_orders wo ON wo.id = sm.ref_id
  WHERE sm.created_at >= v_calc_start
    AND sm.created_at < v_month_end
    AND sm.ref_type = 'wms_orders'
    AND sm.movement_type IN ('pick', 'pick_reversal')
    AND sm.total_cost IS NOT NULL
    AND wo.order_id LIKE 'REQ-%';

  v_customer_cogs := v_cogs - v_requisition_cogs;

  WITH picked_orders AS (
    SELECT DISTINCT o.id, o.total_amount
    FROM inv_stock_movements sm
    JOIN wms_orders wo
      ON wo.id = sm.ref_id
     AND sm.ref_type = 'wms_orders'
     AND sm.movement_type = 'pick'
    JOIN or_orders o
      ON o.work_order_name = wo.order_id
    WHERE sm.created_at >= v_calc_start
      AND sm.created_at < v_month_end
      AND o.status <> 'ยกเลิก'
  )
  SELECT COALESCE(SUM(total_amount), 0)
  INTO v_gross_sales
  FROM picked_orders;

  SELECT COALESCE(SUM(r.amount), 0)
  INTO v_refunds_approved
  FROM ac_refunds r
  JOIN or_orders o ON o.id = r.order_id
  WHERE r.status = 'approved'
    AND o.shipped_time IS NOT NULL
    AND o.shipped_time >= v_calc_start
    AND o.shipped_time < v_month_end;

  v_net_sales := ROUND(v_gross_sales / 1.07, 2);
  v_gross_profit := v_net_sales - v_cogs;
  v_gross_margin_pct := CASE
    WHEN ABS(v_net_sales) < 0.000001 THEN 0
    ELSE (v_gross_profit / v_net_sales) * 100
  END;

  RETURN jsonb_build_object(
    'beginning_inventory', ROUND(v_beginning, 2),
    'ending_inventory',    ROUND(v_ending, 2),
    'safety_stock_value',  ROUND(v_current_ss_val, 2),
    'purchases',           ROUND(v_purchases, 2),
    'cogs',                ROUND(v_cogs, 2),
    'requisition_cogs',    ROUND(v_requisition_cogs, 2),
    'customer_cogs',       ROUND(v_customer_cogs, 2),
    'returns',             ROUND(v_returns, 2),
    'waste',               ROUND(v_waste, 2),
    'adjustments',         ROUND(v_adjustments, 2),
    'gross_sales',         ROUND(v_gross_sales, 2),
    'refunds_approved',    ROUND(v_refunds_approved, 2),
    'net_sales',           ROUND(v_net_sales, 2),
    'gross_profit',        ROUND(v_gross_profit, 2),
    'gross_margin_pct',    ROUND(v_gross_margin_pct, 2),
    'movement_count',      v_movement_count,
    'product_count',       v_product_count
  );
END;
$$;


--
-- Name: rpc_update_machinery_pr(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_machinery_pr(p_pr_id uuid, p_items jsonb, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_product_id uuid;
  v_qty numeric;
  v_last_price numeric(12,2);
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.inv_pr
    WHERE id = p_pr_id
      AND pr_type = 'machinery'
      AND requested_by = auth.uid()
  ) THEN
    RAISE EXCEPTION 'ไม่พบคำขอซื้อ หรือไม่มีสิทธิ์แก้ไขคำขอนี้';
  END IF;

  IF EXISTS (SELECT 1 FROM public.inv_po WHERE pr_id = p_pr_id) THEN
    RAISE EXCEPTION 'คำขอนี้สร้าง PO แล้ว ไม่สามารถแก้ไขได้';
  END IF;

  IF jsonb_array_length(COALESCE(p_items, '[]'::jsonb)) = 0 THEN
    RAISE EXCEPTION 'คำขอซื้อต้องมีสินค้าอย่างน้อย 1 รายการ';
  END IF;

  UPDATE public.inv_pr
  SET note = NULLIF(btrim(p_note), ''), updated_at = now()
  WHERE id = p_pr_id;

  DELETE FROM public.inv_pr_items WHERE pr_id = p_pr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_qty := (v_item->>'qty')::numeric;

    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'จำนวนสินค้าต้องมากกว่า 0';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.pr_machinery_purchase_products
      WHERE product_id = v_product_id AND enabled
    ) THEN
      RAISE EXCEPTION 'สินค้านี้ไม่ได้เปิดให้ขอซื้อใน Machinery';
    END IF;

    SELECT last_price INTO v_last_price
    FROM public.v_product_last_price
    WHERE product_id = v_product_id;

    INSERT INTO public.inv_pr_items(
      pr_id, product_id, qty, unit, estimated_price, last_purchase_price, note
    ) VALUES (
      p_pr_id,
      v_product_id,
      v_qty,
      v_item->>'unit',
      v_last_price,
      v_last_price,
      NULLIF(btrim(v_item->>'note'), '')
    );
  END LOOP;
END;
$$;


--
-- Name: rpc_update_order_item_attachment(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_order_item_attachment(p_item_id uuid, p_file_attachment text DEFAULT NULL::text, p_attachment_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_role text;
  v_link text := NULLIF(btrim(p_file_attachment), '');
  v_name text := NULLIF(btrim(p_attachment_name), '');
BEGIN
  SELECT u.role
    INTO v_role
  FROM public.us_users AS u
  WHERE u.id = auth.uid()
    AND u.is_active IS TRUE;

  IF v_role IS DISTINCT FROM 'production' THEN
    RAISE EXCEPTION 'Only production can use this attachment-only update';
  END IF;

  IF v_link IS NOT NULL AND (
    char_length(v_link) > 2048
    OR v_link !~* '^https?://[^[:space:]]+$'
  ) THEN
    RAISE EXCEPTION 'Invalid attachment URL';
  END IF;

  IF v_name IS NOT NULL AND char_length(v_name) > 255 THEN
    RAISE EXCEPTION 'Attachment name is too long';
  END IF;

  UPDATE public.or_order_items
  SET file_attachment = v_link,
      attachment_name = v_name
  WHERE id = p_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found';
  END IF;
END;
$_$;


--
-- Name: FUNCTION rpc_update_order_item_attachment(p_item_id uuid, p_file_attachment text, p_attachment_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_update_order_item_attachment(p_item_id uuid, p_file_attachment text, p_attachment_name text) IS 'Production-only narrow update for or_order_items.file_attachment and attachment_name';


--
-- Name: rpc_update_order_item_name_lines(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_order_item_name_lines(p_order_id uuid, p_lines jsonb, p_edited_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_order RECORD;
  v_pending_amend INT := 0;
  v_elem JSONB;
  v_uid TEXT;
  v_row RECORD;
  v_new_l1 TEXT;
  v_new_l2 TEXT;
  v_new_l3 TEXT;
  v_changes JSONB := '[]'::jsonb;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'p_order_id ห้ามว่าง';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'p_lines ต้องเป็น JSON array';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN (
    'superadmin', 'admin', 'account', 'sales-tr', 'sales-pump'
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขบิล (role: %)', coalesce(v_role, 'unknown');
  END IF;

  -- Locking the order serializes this edit with the packing shipment update.
  SELECT id, status, shipped_time, bill_no, is_locked, work_order_id, work_order_name
  INTO v_order
  FROM public.or_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_order.id IS NULL THEN RAISE EXCEPTION 'ไม่พบออเดอร์'; END IF;
  IF v_order.is_locked THEN RAISE EXCEPTION 'บิลถูกล็อก'; END IF;
  IF v_order.status = 'จัดส่งแล้ว' OR v_order.shipped_time IS NOT NULL THEN
    RAISE EXCEPTION 'บิลจัดส่งแล้ว ไม่สามารถแก้ชื่อได้';
  END IF;
  IF v_order.status = 'ยกเลิก' THEN
    RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว';
  END IF;
  IF v_order.work_order_id IS NULL
     AND nullif(trim(coalesce(v_order.work_order_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'บิลยังไม่ผูกใบงาน กรุณาใช้การแก้ไขบิลแบบเต็ม';
  END IF;

  SELECT count(*) INTO v_pending_amend
  FROM public.or_order_amendments
  WHERE order_id = p_order_id AND status = 'pending';
  IF v_pending_amend > 0 THEN
    RAISE EXCEPTION 'บิลมีคำขอยกเลิกรออนุมัติ';
  END IF;

  FOR v_elem IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    CONTINUE WHEN v_elem IS NULL OR jsonb_typeof(v_elem) <> 'object';
    v_uid := trim(coalesce(v_elem->>'item_uid', ''));
    CONTINUE WHEN v_uid = '';

    SELECT * INTO v_row
    FROM public.or_order_items
    WHERE order_id = p_order_id AND item_uid = v_uid
    FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบรายการ item_uid=%', v_uid; END IF;
    IF coalesce(v_row.no_name_line, false) THEN
      RAISE EXCEPTION 'รายการ % ไม่รับชื่อ (no_name_line) ไม่สามารถแก้บรรทัดได้', v_uid;
    END IF;

    v_new_l1 := nullif(trim(coalesce(v_elem->>'line_1', '')), '');
    v_new_l2 := nullif(trim(coalesce(v_elem->>'line_2', '')), '');
    v_new_l3 := nullif(trim(coalesce(v_elem->>'line_3', '')), '');

    IF v_row.line_1 IS DISTINCT FROM v_new_l1 THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'line_1:' || v_uid, 'label', format('บรรทัด 1 (%s)', v_uid),
        'before', coalesce(v_row.line_1, ''), 'after', coalesce(v_new_l1, '')
      ));
    END IF;
    IF v_row.line_2 IS DISTINCT FROM v_new_l2 THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'line_2:' || v_uid, 'label', format('บรรทัด 2 (%s)', v_uid),
        'before', coalesce(v_row.line_2, ''), 'after', coalesce(v_new_l2, '')
      ));
    END IF;
    IF v_row.line_3 IS DISTINCT FROM v_new_l3 THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'line_3:' || v_uid, 'label', format('บรรทัด 3 (%s)', v_uid),
        'before', coalesce(v_row.line_3, ''), 'after', coalesce(v_new_l3, '')
      ));
    END IF;

    IF v_row.line_1 IS DISTINCT FROM v_new_l1
       OR v_row.line_2 IS DISTINCT FROM v_new_l2
       OR v_row.line_3 IS DISTINCT FROM v_new_l3 THEN
      UPDATE public.or_order_items
      SET line_1 = v_new_l1,
          line_2 = v_new_l2,
          line_3 = v_new_l3,
          updated_at = now()
      WHERE id = v_row.id;
    END IF;
  END LOOP;

  IF jsonb_array_length(v_changes) > 0 THEN
    INSERT INTO public.ac_bill_edit_logs (
      order_id, bill_no, edited_by, changes, snapshot_before, snapshot_after
    ) VALUES (
      p_order_id,
      nullif(v_order.bill_no, ''),
      coalesce(nullif(trim(p_edited_by), ''), 'unknown'),
      v_changes,
      NULL,
      NULL
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'changes_count', jsonb_array_length(v_changes));
END;
$$;


--
-- Name: FUNCTION rpc_update_order_item_name_lines(p_order_id uuid, p_lines jsonb, p_edited_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_update_order_item_name_lines(p_order_id uuid, p_lines jsonb, p_edited_by text) IS 'แก้ชื่อบรรทัด 1–3 ของบิลที่ผูกใบงาน จนกว่าบิลจะถูกจัดส่ง';


--
-- Name: rpc_update_order_limited_fields(uuid, jsonb, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_order_limited_fields(p_order_id uuid, p_lines jsonb, p_channel_order_no text, p_tracking_number text, p_express_receipt_number text, p_edited_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_role TEXT;
  v_order RECORD;
  v_pending_amend INT := 0;
  v_channel_order_no TEXT := nullif(trim(coalesce(p_channel_order_no, '')), '');
  v_tracking_number TEXT := nullif(trim(coalesce(p_tracking_number, '')), '');
  v_express_receipt_number TEXT := nullif(trim(coalesce(p_express_receipt_number, '')), '');
  v_elem JSONB;
  v_uid TEXT;
  v_row RECORD;
  v_is_condo BOOLEAN;
  v_new_ink_color TEXT;
  v_new_product_type TEXT;
  v_new_cartoon_pattern TEXT;
  v_new_font TEXT;
  v_new_no_name_line BOOLEAN;
  v_new_l1 TEXT;
  v_new_l2 TEXT;
  v_new_l3 TEXT;
  v_changes JSONB := '[]'::jsonb;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'p_order_id ห้ามว่าง';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'p_lines ต้องเป็น JSON array';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account', 'sales-tr', 'sales-pump') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขบิล (role: %)', coalesce(v_role, 'unknown');
  END IF;

  SELECT id, status, shipped_time, bill_no, is_locked, work_order_id, work_order_name,
         channel_order_no, tracking_number, express_receipt_number
  INTO v_order
  FROM public.or_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_order.id IS NULL THEN RAISE EXCEPTION 'ไม่พบออเดอร์'; END IF;
  IF v_order.is_locked THEN RAISE EXCEPTION 'บิลถูกล็อก'; END IF;
  IF v_order.status = 'จัดส่งแล้ว' OR v_order.shipped_time IS NOT NULL THEN
    RAISE EXCEPTION 'บิลจัดส่งแล้ว ไม่สามารถแก้ไขข้อมูลได้';
  END IF;
  IF v_order.status = 'ยกเลิก' THEN
    RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว';
  END IF;
  IF v_order.work_order_id IS NULL
     AND nullif(trim(coalesce(v_order.work_order_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'บิลยังไม่ผูกใบงาน กรุณาใช้การแก้ไขบิลแบบเต็ม';
  END IF;

  SELECT count(*) INTO v_pending_amend
  FROM public.or_order_amendments
  WHERE order_id = p_order_id AND status = 'pending';
  IF v_pending_amend > 0 THEN
    RAISE EXCEPTION 'บิลมีคำขอยกเลิกรออนุมัติ';
  END IF;

  IF v_tracking_number IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.or_orders
    WHERE id <> p_order_id
      AND COALESCE(status, '') <> 'ยกเลิก'
      AND upper(regexp_replace(COALESCE(tracking_number, ''), '[[:space:]]+', '', 'g'))
          = upper(regexp_replace(v_tracking_number, '[[:space:]]+', '', 'g'))
  ) THEN
    RAISE EXCEPTION 'เลขพัสดุซ้ำกับรายการในระบบ';
  END IF;

  IF v_order.channel_order_no IS DISTINCT FROM v_channel_order_no THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'channel_order_no', 'label', 'เลขคำสั่งซื้อ',
      'before', coalesce(v_order.channel_order_no, ''), 'after', coalesce(v_channel_order_no, '')
    ));
  END IF;
  IF v_order.tracking_number IS DISTINCT FROM v_tracking_number THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'tracking_number', 'label', 'เลขพัสดุ',
      'before', coalesce(v_order.tracking_number, ''), 'after', coalesce(v_tracking_number, '')
    ));
  END IF;
  IF v_order.express_receipt_number IS DISTINCT FROM v_express_receipt_number THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'express_receipt_number', 'label', 'เลขรับพัสดุด่วน',
      'before', coalesce(v_order.express_receipt_number, ''), 'after', coalesce(v_express_receipt_number, '')
    ));
  END IF;

  UPDATE public.or_orders
  SET channel_order_no = v_channel_order_no,
      tracking_number = v_tracking_number,
      express_receipt_number = v_express_receipt_number,
      last_edited_by = coalesce(nullif(trim(p_edited_by), ''), 'unknown')
  WHERE id = p_order_id;

  FOR v_elem IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    CONTINUE WHEN v_elem IS NULL OR jsonb_typeof(v_elem) <> 'object';
    v_uid := trim(coalesce(v_elem->>'item_uid', ''));
    CONTINUE WHEN v_uid = '';

    SELECT * INTO v_row
    FROM public.or_order_items
    WHERE order_id = p_order_id AND item_uid = v_uid
    FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบรายการ item_uid=%', v_uid; END IF;

    SELECT (
      coalesce(v_row.is_detail_row, false)
      OR v_row.parent_item_id IS NOT NULL
      OR trim(coalesce(v_row.product_name, '')) LIKE 'ตรายางคอนโด%'
      OR EXISTS (
        SELECT 1
        FROM public.pr_products p
        WHERE p.id = v_row.product_id
          AND (
            upper(trim(coalesce(p.product_category, ''))) LIKE 'CONDO STAMP%'
            OR trim(coalesce(p.product_name, '')) LIKE 'ตรายางคอนโด%'
          )
      )
    ) INTO v_is_condo;

    v_new_ink_color := CASE WHEN v_elem ? 'ink_color'
      THEN nullif(trim(coalesce(v_elem->>'ink_color', '')), '') ELSE v_row.ink_color END;
    v_new_product_type := CASE WHEN v_elem ? 'product_type'
      THEN nullif(trim(coalesce(v_elem->>'product_type', '')), '') ELSE v_row.product_type END;
    v_new_cartoon_pattern := CASE WHEN v_elem ? 'cartoon_pattern'
      THEN nullif(trim(coalesce(v_elem->>'cartoon_pattern', '')), '') ELSE v_row.cartoon_pattern END;
    v_new_font := CASE WHEN v_elem ? 'font'
      THEN nullif(trim(coalesce(v_elem->>'font', '')), '') ELSE v_row.font END;
    v_new_no_name_line := CASE WHEN v_elem ? 'no_name_line'
      THEN coalesce((v_elem->>'no_name_line')::boolean, false) ELSE coalesce(v_row.no_name_line, false) END;
    v_new_l1 := CASE WHEN v_elem ? 'line_1'
      THEN nullif(trim(coalesce(v_elem->>'line_1', '')), '') ELSE v_row.line_1 END;
    v_new_l2 := CASE WHEN v_elem ? 'line_2'
      THEN nullif(trim(coalesce(v_elem->>'line_2', '')), '') ELSE v_row.line_2 END;
    v_new_l3 := CASE WHEN v_elem ? 'line_3'
      THEN nullif(trim(coalesce(v_elem->>'line_3', '')), '') ELSE v_row.line_3 END;

    IF v_row.product_type IS DISTINCT FROM v_new_product_type THEN
      IF NOT v_is_condo THEN
        RAISE EXCEPTION 'แก้ไขชั้นได้เฉพาะสินค้าตรายางคอนโด (รายการ %)', v_uid;
      END IF;
      IF v_new_product_type IS NULL OR v_new_product_type !~ '^ชั้น[1-5]$' THEN
        RAISE EXCEPTION 'ชั้นของตรายางคอนโดไม่ถูกต้อง (รายการ %)', v_uid;
      END IF;
    END IF;

    IF v_row.ink_color IS DISTINCT FROM v_new_ink_color THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'ink_color:' || v_uid, 'label', format('สีหมึก (%s)', v_uid),
        'before', coalesce(v_row.ink_color, ''), 'after', coalesce(v_new_ink_color, '')
      ));
    END IF;
    IF v_row.product_type IS DISTINCT FROM v_new_product_type THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'product_type:' || v_uid, 'label', format('ชั้น (%s)', v_uid),
        'before', coalesce(v_row.product_type, ''), 'after', coalesce(v_new_product_type, '')
      ));
    END IF;
    IF v_row.cartoon_pattern IS DISTINCT FROM v_new_cartoon_pattern THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'cartoon_pattern:' || v_uid, 'label', format('ลาย (%s)', v_uid),
        'before', coalesce(v_row.cartoon_pattern, ''), 'after', coalesce(v_new_cartoon_pattern, '')
      ));
    END IF;
    IF v_row.font IS DISTINCT FROM v_new_font THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'font:' || v_uid, 'label', format('ฟอนต์ (%s)', v_uid),
        'before', coalesce(v_row.font, ''), 'after', coalesce(v_new_font, '')
      ));
    END IF;
    IF coalesce(v_row.no_name_line, false) IS DISTINCT FROM v_new_no_name_line THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'no_name_line:' || v_uid, 'label', format('ไม่รับชื่อ (%s)', v_uid),
        'before', CASE WHEN coalesce(v_row.no_name_line, false) THEN 'ใช่' ELSE 'ไม่ใช่' END,
        'after', CASE WHEN v_new_no_name_line THEN 'ใช่' ELSE 'ไม่ใช่' END
      ));
    END IF;
    IF v_row.line_1 IS DISTINCT FROM v_new_l1 THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'line_1:' || v_uid, 'label', format('บรรทัด 1 (%s)', v_uid),
        'before', coalesce(v_row.line_1, ''), 'after', coalesce(v_new_l1, '')
      ));
    END IF;
    IF v_row.line_2 IS DISTINCT FROM v_new_l2 THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'line_2:' || v_uid, 'label', format('บรรทัด 2 (%s)', v_uid),
        'before', coalesce(v_row.line_2, ''), 'after', coalesce(v_new_l2, '')
      ));
    END IF;
    IF v_row.line_3 IS DISTINCT FROM v_new_l3 THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'field', 'line_3:' || v_uid, 'label', format('บรรทัด 3 (%s)', v_uid),
        'before', coalesce(v_row.line_3, ''), 'after', coalesce(v_new_l3, '')
      ));
    END IF;

    IF v_row.ink_color IS DISTINCT FROM v_new_ink_color
       OR v_row.product_type IS DISTINCT FROM v_new_product_type
       OR v_row.cartoon_pattern IS DISTINCT FROM v_new_cartoon_pattern
       OR v_row.font IS DISTINCT FROM v_new_font
       OR coalesce(v_row.no_name_line, false) IS DISTINCT FROM v_new_no_name_line
       OR v_row.line_1 IS DISTINCT FROM v_new_l1
       OR v_row.line_2 IS DISTINCT FROM v_new_l2
       OR v_row.line_3 IS DISTINCT FROM v_new_l3 THEN
      UPDATE public.or_order_items
      SET ink_color = v_new_ink_color,
          product_type = v_new_product_type,
          cartoon_pattern = v_new_cartoon_pattern,
          font = v_new_font,
          no_name_line = v_new_no_name_line,
          line_1 = v_new_l1,
          line_2 = v_new_l2,
          line_3 = v_new_l3,
          updated_at = now()
      WHERE id = v_row.id;
    END IF;
  END LOOP;

  IF jsonb_array_length(v_changes) > 0 THEN
    INSERT INTO public.ac_bill_edit_logs (
      order_id, bill_no, edited_by, changes, snapshot_before, snapshot_after
    ) VALUES (
      p_order_id,
      nullif(v_order.bill_no, ''),
      coalesce(nullif(trim(p_edited_by), ''), 'unknown'),
      v_changes,
      NULL,
      NULL
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'changes_count', jsonb_array_length(v_changes));
END;
$_$;


--
-- Name: FUNCTION rpc_update_order_limited_fields(p_order_id uuid, p_lines jsonb, p_channel_order_no text, p_tracking_number text, p_express_receipt_number text, p_edited_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_update_order_limited_fields(p_order_id uuid, p_lines jsonb, p_channel_order_no text, p_tracking_number text, p_express_receipt_number text, p_edited_by text) IS 'แก้ข้อมูลจัดส่ง สีหมึก ลาย ฟอนต์ ไม่รับชื่อ บรรทัด 1–3 และชั้นเฉพาะตรายางคอนโด จนกว่าจะจัดส่ง พร้อมบันทึกประวัติ';


--
-- Name: rpc_update_order_limited_fields_with_shipping(uuid, jsonb, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_order_limited_fields_with_shipping(p_order_id uuid, p_lines jsonb, p_channel_order_no text, p_tracking_number text, p_express_receipt_number text, p_shipping_details jsonb, p_edited_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_base_result JSONB;
  v_order RECORD;
  v_before_billing JSONB;
  v_after_billing JSONB;
  v_customer_name TEXT;
  v_recipient_name TEXT;
  v_customer_address TEXT;
  v_address_line TEXT;
  v_sub_district TEXT;
  v_district TEXT;
  v_province TEXT;
  v_postal_code TEXT;
  v_mobile_phone TEXT;
  v_changes JSONB := '[]'::jsonb;
  v_address_change_count INT := 0;
BEGIN
  IF p_shipping_details IS NULL OR jsonb_typeof(p_shipping_details) <> 'object' THEN
    RAISE EXCEPTION 'p_shipping_details ต้องเป็น JSON object';
  END IF;

  -- This RPC performs the role, lock, linked-work-order, pending-amendment,
  -- duplicate-tracking and shipped checks. Its row lock remains held until
  -- this outer function finishes, preventing packing from shipping the bill
  -- between the check and the address update.
  SELECT public.rpc_update_order_limited_fields(
    p_order_id,
    p_lines,
    p_channel_order_no,
    p_tracking_number,
    p_express_receipt_number,
    p_edited_by
  ) INTO v_base_result;

  SELECT
    id, bill_no, status, shipped_time, customer_name, recipient_name,
    customer_address, billing_details
  INTO v_order
  FROM public.or_orders
  WHERE id = p_order_id
  FOR UPDATE;

  -- Defence in depth: do not rely only on the inner RPC for this business
  -- invariant. This also protects the function if the inner RPC changes later.
  IF v_order.status = 'จัดส่งแล้ว' OR v_order.shipped_time IS NOT NULL THEN
    RAISE EXCEPTION 'บิลจัดส่งแล้ว ไม่สามารถแก้ไขข้อมูลจัดส่งได้';
  END IF;

  v_before_billing := coalesce(v_order.billing_details, '{}'::jsonb);
  v_customer_name := coalesce(nullif(trim(p_shipping_details->>'customer_name'), ''), v_order.customer_name);
  v_recipient_name := nullif(trim(coalesce(p_shipping_details->>'recipient_name', '')), '');
  v_customer_address := coalesce(nullif(trim(p_shipping_details->>'customer_address'), ''), v_order.customer_address);
  v_address_line := nullif(trim(coalesce(p_shipping_details->>'address_line', '')), '');
  v_sub_district := nullif(trim(coalesce(p_shipping_details->>'sub_district', '')), '');
  v_district := nullif(trim(coalesce(p_shipping_details->>'district', '')), '');
  v_province := nullif(trim(coalesce(p_shipping_details->>'province', '')), '');
  v_postal_code := nullif(trim(coalesce(p_shipping_details->>'postal_code', '')), '');
  v_mobile_phone := nullif(trim(coalesce(p_shipping_details->>'mobile_phone', '')), '');

  v_after_billing := v_before_billing || jsonb_build_object(
    'address_line', v_address_line,
    'sub_district', v_sub_district,
    'district', v_district,
    'province', v_province,
    'postal_code', v_postal_code,
    'mobile_phone', v_mobile_phone
  );

  IF v_order.customer_name IS DISTINCT FROM v_customer_name THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'customer_name', 'label', 'ชื่อลูกค้า/ช่องทาง',
      'before', coalesce(v_order.customer_name, ''), 'after', coalesce(v_customer_name, '')
    ));
  END IF;
  IF v_order.recipient_name IS DISTINCT FROM v_recipient_name THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'recipient_name', 'label', 'ชื่อผู้รับ',
      'before', coalesce(v_order.recipient_name, ''), 'after', coalesce(v_recipient_name, '')
    ));
  END IF;
  IF v_order.customer_address IS DISTINCT FROM v_customer_address THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'customer_address', 'label', 'ที่อยู่เต็ม',
      'before', coalesce(v_order.customer_address, ''), 'after', coalesce(v_customer_address, '')
    ));
  END IF;
  IF (v_before_billing->>'address_line') IS DISTINCT FROM v_address_line THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'billing_details.address_line', 'label', 'ที่อยู่',
      'before', coalesce(v_before_billing->>'address_line', ''), 'after', coalesce(v_address_line, '')
    ));
  END IF;
  IF (v_before_billing->>'sub_district') IS DISTINCT FROM v_sub_district THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'billing_details.sub_district', 'label', 'แขวง/ตำบล',
      'before', coalesce(v_before_billing->>'sub_district', ''), 'after', coalesce(v_sub_district, '')
    ));
  END IF;
  IF (v_before_billing->>'district') IS DISTINCT FROM v_district THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'billing_details.district', 'label', 'เขต/อำเภอ',
      'before', coalesce(v_before_billing->>'district', ''), 'after', coalesce(v_district, '')
    ));
  END IF;
  IF (v_before_billing->>'province') IS DISTINCT FROM v_province THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'billing_details.province', 'label', 'จังหวัด',
      'before', coalesce(v_before_billing->>'province', ''), 'after', coalesce(v_province, '')
    ));
  END IF;
  IF (v_before_billing->>'postal_code') IS DISTINCT FROM v_postal_code THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'billing_details.postal_code', 'label', 'รหัสไปรษณีย์',
      'before', coalesce(v_before_billing->>'postal_code', ''), 'after', coalesce(v_postal_code, '')
    ));
  END IF;
  IF (v_before_billing->>'mobile_phone') IS DISTINCT FROM v_mobile_phone THEN
    v_changes := v_changes || jsonb_build_array(jsonb_build_object(
      'field', 'billing_details.mobile_phone', 'label', 'เบอร์โทรมือถือ',
      'before', coalesce(v_before_billing->>'mobile_phone', ''), 'after', coalesce(v_mobile_phone, '')
    ));
  END IF;

  v_address_change_count := jsonb_array_length(v_changes);

  IF v_address_change_count > 0 THEN
    UPDATE public.or_orders
    SET customer_name = v_customer_name,
        recipient_name = v_recipient_name,
        customer_address = v_customer_address,
        billing_details = v_after_billing,
        last_edited_by = coalesce(nullif(trim(p_edited_by), ''), 'unknown')
    WHERE id = p_order_id;

    INSERT INTO public.ac_bill_edit_logs (
      order_id, bill_no, edited_by, changes, snapshot_before, snapshot_after
    ) VALUES (
      p_order_id,
      nullif(v_order.bill_no, ''),
      coalesce(nullif(trim(p_edited_by), ''), 'unknown'),
      v_changes,
      jsonb_build_object(
        'customer_name', v_order.customer_name,
        'recipient_name', v_order.recipient_name,
        'customer_address', v_order.customer_address,
        'billing_details', v_before_billing
      ),
      jsonb_build_object(
        'customer_name', v_customer_name,
        'recipient_name', v_recipient_name,
        'customer_address', v_customer_address,
        'billing_details', v_after_billing
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'changes_count', coalesce((v_base_result->>'changes_count')::int, 0) + v_address_change_count
  );
END;
$$;


--
-- Name: FUNCTION rpc_update_order_limited_fields_with_shipping(p_order_id uuid, p_lines jsonb, p_channel_order_no text, p_tracking_number text, p_express_receipt_number text, p_shipping_details jsonb, p_edited_by text); Type: COMMENT; Schema: public; Owner: -
--

