--
-- Name: rpc_update_po(uuid, text, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_po(p_po_id uuid, p_note text DEFAULT NULL::text, p_expected_arrival_date date DEFAULT NULL::date, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_item JSONB;
  v_total NUMERIC := 0;
  v_subtotal NUMERIC;
  v_ship_thb NUMERIC;
BEGIN
  IF NOT public.erp_can_view_cost() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขข้อมูลต้นทุน'; END IF;
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไข PO (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM inv_po WHERE id = p_po_id AND status = 'open') THEN
    RAISE EXCEPTION 'PO ไม่อยู่ในสถานะเปิด ไม่สามารถแก้ไขได้';
  END IF;

  UPDATE inv_po
  SET note = p_note,
      expected_arrival_date = p_expected_arrival_date,
      updated_at = NOW()
  WHERE id = p_po_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_subtotal := COALESCE((v_item->>'unit_price')::NUMERIC, 0) * COALESCE((v_item->>'qty')::NUMERIC, 0);
    v_total := v_total + v_subtotal;

    UPDATE inv_po_items
    SET unit_price = (v_item->>'unit_price')::NUMERIC,
        qty = COALESCE((v_item->>'qty')::NUMERIC, qty),
        note = v_item->>'note',
        subtotal = v_subtotal
    WHERE id = (v_item->>'item_id')::UUID AND po_id = p_po_id;
  END LOOP;

  SELECT intl_shipping_cost_thb INTO v_ship_thb FROM inv_po WHERE id = p_po_id;

  UPDATE inv_po
  SET
    total_amount = v_total,
    grand_total = v_total + COALESCE(v_ship_thb, 0)
  WHERE id = p_po_id;

  RETURN jsonb_build_object('total_amount', v_total);
END;
$$;


--
-- Name: rpc_update_po_expected_arrival_date(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_po_expected_arrival_date(p_po_id uuid, p_expected_arrival_date date, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid UUID := COALESCE(auth.uid(), p_user_id);
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขกำหนดเข้า PO (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM inv_po
    WHERE id = p_po_id
      AND status IN ('open', 'ordered', 'partial')
  ) THEN
    RAISE EXCEPTION 'PO ไม่อยู่ในสถานะที่แก้ไขกำหนดเข้าได้';
  END IF;

  UPDATE inv_po
  SET expected_arrival_date = p_expected_arrival_date,
      updated_at = NOW()
  WHERE id = p_po_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบ PO';
  END IF;
END;
$$;


--
-- Name: rpc_update_po_nonfinancial(uuid, text, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_po_nonfinancial(p_po_id uuid, p_note text DEFAULT NULL::text, p_expected_arrival_date date DEFAULT NULL::date, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_item jsonb;
  v_total numeric := 0;
  v_shipping numeric := 0;
BEGIN
  IF NOT public.erp_can_view_cost() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขข้อมูลต้นทุน'; END IF;
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role <> 'admin' THEN
    RAISE EXCEPTION 'Only admin can use the non-financial PO update';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.inv_po WHERE id = p_po_id AND status = 'open'
  ) THEN
    RAISE EXCEPTION 'PO is not open';
  END IF;

  UPDATE public.inv_po
  SET note = p_note,
      expected_arrival_date = p_expected_arrival_date,
      updated_at = now()
  WHERE id = p_po_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    UPDATE public.inv_po_items
    SET qty = COALESCE((v_item->>'qty')::numeric, qty),
        note = v_item->>'note'
    WHERE id = (v_item->>'item_id')::uuid
      AND po_id = p_po_id;
  END LOOP;

  SELECT COALESCE(sum(qty * COALESCE(unit_price, 0)), 0)
    INTO v_total
  FROM public.inv_po_items
  WHERE po_id = p_po_id;

  SELECT COALESCE(intl_shipping_cost_thb, 0)
    INTO v_shipping
  FROM public.inv_po
  WHERE id = p_po_id;

  UPDATE public.inv_po
  SET total_amount = v_total,
      grand_total = v_total + v_shipping,
      updated_at = now()
  WHERE id = p_po_id;

  RETURN jsonb_build_object('total_amount', v_total);
END;
$$;


--
-- Name: rpc_update_po_receiving_note(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_po_receiving_note(p_po_id uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'manager', 'store', 'account', 'picker', 'auditor') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกหมายเหตุรับสินค้า';
  END IF;

  UPDATE public.inv_po
  SET receiving_note = NULLIF(BTRIM(p_note), ''), updated_at = NOW()
  WHERE id = p_po_id AND status IN ('open', 'ordered', 'partial');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบ PO หรือ PO ไม่อยู่ในสถานะที่บันทึกหมายเหตุรับสินค้าได้';
  END IF;
END;
$$;


--
-- Name: rpc_update_po_shipment_entries(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_po_shipment_entries(p_po_id uuid, p_entries jsonb DEFAULT '[]'::jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_role TEXT;
  v_uid UUID := COALESCE(auth.uid(), p_user_id);
  v_entries JSONB := COALESCE(p_entries, '[]'::JSONB);
  v_entry JSONB;
  v_tracking_summary TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'manager', 'store', 'account', 'picker', 'auditor') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกข้อมูลขนส่ง PO (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF jsonb_typeof(v_entries) <> 'array' OR jsonb_array_length(v_entries) > 50 THEN
    RAISE EXCEPTION 'ข้อมูลขนส่งต้องเป็นรายการและมีได้ไม่เกิน 50 รายการ';
  END IF;

  FOR v_entry IN SELECT value FROM jsonb_array_elements(v_entries)
  LOOP
    IF jsonb_typeof(v_entry) <> 'object'
      OR NULLIF(BTRIM(v_entry->>'vehicle_number'), '') IS NULL
      OR NULLIF(BTRIM(v_entry->>'tracking_number'), '') IS NULL
      OR char_length(BTRIM(v_entry->>'vehicle_number')) > 50
      OR char_length(BTRIM(v_entry->>'tracking_number')) > 100
      OR COALESCE(v_entry->>'box_count', '') !~ '^[1-9][0-9]*$'
    THEN
      RAISE EXCEPTION 'แต่ละรายการต้องมีเลขรถ เลขพัสดุ และจำนวนลังที่ถูกต้อง';
    END IF;
  END LOOP;

  SELECT NULLIF(BTRIM(value->>'tracking_number'), '')
  INTO v_tracking_summary
  FROM jsonb_array_elements(v_entries) WITH ORDINALITY AS rows(value, ordinality)
  ORDER BY ordinality
  LIMIT 1;

  UPDATE public.inv_po
  SET shipment_entries = v_entries,
      tracking_number = v_tracking_summary,
      updated_at = NOW()
  WHERE id = p_po_id
    AND status IN ('open', 'ordered', 'partial');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบ PO หรือ PO ไม่อยู่ในสถานะที่บันทึกข้อมูลขนส่งได้';
  END IF;
END;
$_$;


--
-- Name: rpc_update_po_tracking_number(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_po_tracking_number(p_po_id uuid, p_tracking_number text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid UUID := COALESCE(auth.uid(), p_user_id);
  v_tracking_number TEXT := NULLIF(BTRIM(p_tracking_number), '');
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'manager', 'store', 'account', 'picker', 'auditor') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกเลขพัสดุ PO (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF v_tracking_number IS NOT NULL AND char_length(v_tracking_number) > 100 THEN
    RAISE EXCEPTION 'เลขพัสดุต้องไม่เกิน 100 ตัวอักษร';
  END IF;

  UPDATE public.inv_po
  SET tracking_number = v_tracking_number,
      updated_at = NOW()
  WHERE id = p_po_id
    AND status IN ('open', 'ordered', 'partial');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบ PO หรือ PO ไม่อยู่ในสถานะที่บันทึกเลขพัสดุได้';
  END IF;
END;
$$;


--
-- Name: rpc_update_pr(uuid, jsonb, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_pr(p_pr_id uuid, p_items jsonb, p_note text DEFAULT NULL::text, p_pr_type text DEFAULT NULL::text, p_supplier_id uuid DEFAULT NULL::uuid, p_supplier_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_item JSONB;
  v_last_price NUMERIC(12,2);
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไข PR (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM inv_pr WHERE id = p_pr_id AND status = 'pending') THEN
    RAISE EXCEPTION 'PR ไม่อยู่ในสถานะรออนุมัติ ไม่สามารถแก้ไขได้';
  END IF;

  UPDATE inv_pr
  SET note = p_note,
      pr_type = COALESCE(p_pr_type, pr_type),
      supplier_id = p_supplier_id,
      supplier_name = p_supplier_name,
      updated_at = NOW()
  WHERE id = p_pr_id;

  DELETE FROM inv_pr_items WHERE pr_id = p_pr_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT last_price INTO v_last_price
    FROM v_product_last_price
    WHERE product_id = (v_item->>'product_id')::UUID;

    INSERT INTO inv_pr_items (pr_id, product_id, qty, unit, estimated_price, last_purchase_price, note)
    VALUES (
      p_pr_id,
      (v_item->>'product_id')::UUID,
      (v_item->>'qty')::NUMERIC,
      v_item->>'unit',
      v_last_price,
      v_last_price,
      v_item->>'note'
    );
  END LOOP;
END;
$$;


--
-- Name: rpc_update_product_location_label(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_product_location_label(p_product_id uuid, p_label_type text, p_location_id uuid, p_display_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_name TEXT := NULLIF(BTRIM(p_display_name), '');
BEGIN
  IF NOT public.can_manage_product_location_labels() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขชื่อจุดจัดเก็บสินค้า';
  END IF;
  IF p_label_type NOT IN ('movement', 'storage', 'safety') OR v_name IS NULL THEN
    RAISE EXCEPTION 'ข้อมูลชื่อจุดจัดเก็บไม่ถูกต้อง';
  END IF;
  IF p_label_type = 'storage' AND (
    p_location_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.wh_storage_locations WHERE id = p_location_id
    )
  ) THEN
    RAISE EXCEPTION 'ไม่พบจุดจัดเก็บที่เลือก';
  END IF;

  DELETE FROM public.wh_product_location_labels
  WHERE product_id = p_product_id
    AND label_type = p_label_type
    AND (
      (p_label_type = 'storage' AND location_id = p_location_id)
      OR (p_label_type <> 'storage' AND location_id IS NULL)
    );

  INSERT INTO public.wh_product_location_labels(
    product_id, label_type, location_id, display_name, updated_by
  ) VALUES (
    p_product_id,
    p_label_type,
    CASE WHEN p_label_type = 'storage' THEN p_location_id ELSE NULL END,
    v_name,
    auth.uid()
  );

  IF p_label_type = 'movement' THEN
    UPDATE public.pr_products
    SET storage_location = v_name, updated_at = NOW()
    WHERE id = p_product_id;
  END IF;
END;
$$;


--
-- Name: rpc_update_roll_group_sheets(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_roll_group_sheets(p_config_id uuid, p_sheets numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_group uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND is_active IS TRUE AND role IN ('superadmin','admin','store')) THEN
    RAISE EXCEPTION 'Not authorized to manage roll pairings';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('roll_pairing_groups'));
  SELECT pairing_group_id INTO v_group FROM public.roll_material_configs WHERE id = p_config_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pairing not found'; END IF;
  IF (v_group IS NOT NULL AND p_sheets IS NULL) OR (p_sheets IS NOT NULL AND (p_sheets <= 0 OR p_sheets::text IN ('NaN','Infinity','-Infinity') OR p_sheets <> round(p_sheets,2) OR p_sheets >= 10000000000)) THEN
    RAISE EXCEPTION 'Invalid sheets per roll';
  END IF;
  UPDATE public.roll_material_configs SET sheets_per_roll = p_sheets, updated_at = now()
  WHERE id = p_config_id OR (v_group IS NOT NULL AND pairing_group_id = v_group);
END $$;


--
-- Name: rpc_update_sample(uuid, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_sample(p_sample_id uuid, p_items jsonb, p_sample_label text, p_note text DEFAULT NULL::text, p_receipt_status text DEFAULT 'received'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_item JSONB;
  v_item_id UUID;
  v_keep_ids UUID[] := ARRAY[]::UUID[];
  v_current_status TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'store', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขสินค้าตัวอย่าง';
  END IF;
  IF COALESCE(trim(p_sample_label), '') = '' OR jsonb_array_length(COALESCE(p_items, '[]'::jsonb)) = 0 THEN
    RAISE EXCEPTION 'ต้องระบุสินค้าอย่างน้อย 1 รายการ';
  END IF;
  IF p_receipt_status NOT IN ('pending_receipt', 'received') THEN
    RAISE EXCEPTION 'สถานะการรับสินค้าไม่ถูกต้อง';
  END IF;

  SELECT status INTO v_current_status FROM public.inv_samples WHERE id = p_sample_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบสินค้าตัวอย่าง'; END IF;

  UPDATE public.inv_samples
  SET sample_label = trim(p_sample_label), note = NULLIF(trim(p_note), ''),
      status = CASE WHEN v_current_status IN ('pending_receipt', 'received') THEN p_receipt_status ELSE v_current_status END,
      received_at = CASE WHEN v_current_status IN ('pending_receipt', 'received') AND p_receipt_status = 'received' THEN COALESCE(received_at, now()) WHEN p_receipt_status = 'pending_receipt' THEN NULL ELSE received_at END,
      received_by = CASE WHEN v_current_status IN ('pending_receipt', 'received') AND p_receipt_status = 'received' THEN COALESCE(received_by, auth.uid()) WHEN p_receipt_status = 'pending_receipt' THEN NULL ELSE received_by END
  WHERE id = p_sample_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_item_id := NULLIF(v_item->>'id', '')::UUID;
    IF v_item_id IS NULL THEN
      INSERT INTO public.inv_sample_items (sample_id, product_name_manual, image_url, qty, note)
      VALUES (p_sample_id, trim(v_item->>'product_name_manual'), NULLIF(v_item->>'image_url', ''), GREATEST(COALESCE((v_item->>'qty')::NUMERIC, 1), 1), NULLIF(trim(v_item->>'note'), ''))
      RETURNING id INTO v_item_id;
    ELSE
      UPDATE public.inv_sample_items
      SET product_name_manual = trim(v_item->>'product_name_manual'), image_url = NULLIF(v_item->>'image_url', ''), qty = GREATEST(COALESCE((v_item->>'qty')::NUMERIC, 1), 1), note = NULLIF(trim(v_item->>'note'), '')
      WHERE id = v_item_id AND sample_id = p_sample_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'รายการสินค้าไม่ถูกต้อง'; END IF;
    END IF;
    v_keep_ids := array_append(v_keep_ids, v_item_id);
  END LOOP;

  DELETE FROM public.inv_sample_items
  WHERE sample_id = p_sample_id AND NOT (id = ANY(v_keep_ids)) AND converted_product_id IS NULL;
END;
$$;


--
-- Name: rpc_update_sample_test(uuid, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_sample_test(p_sample_id uuid, p_status text, p_user_id uuid DEFAULT NULL::uuid, p_test_note text DEFAULT NULL::text, p_rejection_reason text DEFAULT NULL::text, p_item_results jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid  UUID := auth.uid();
  v_item JSONB;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin-tr', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ทดสอบ Sample (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF p_status NOT IN ('testing', 'approved', 'rejected') THEN
    RAISE EXCEPTION 'สถานะไม่ถูกต้อง: %', p_status;
  END IF;

  UPDATE inv_samples
  SET status = p_status,
      tested_by = CASE WHEN p_status IN ('approved', 'rejected') THEN v_uid ELSE tested_by END,
      tested_at = CASE WHEN p_status IN ('approved', 'rejected') THEN NOW() ELSE tested_at END,
      test_result = CASE WHEN p_status = 'approved' THEN 'passed' WHEN p_status = 'rejected' THEN 'failed' ELSE test_result END,
      test_note = COALESCE(p_test_note, test_note),
      rejection_reason = CASE WHEN p_status = 'rejected' THEN p_rejection_reason ELSE rejection_reason END
  WHERE id = p_sample_id;

  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบ Sample'; END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_item_results)
  LOOP
    UPDATE inv_sample_items
    SET item_test_result = v_item->>'result',
        item_test_note = v_item->>'note'
    WHERE id = (v_item->>'item_id')::UUID AND sample_id = p_sample_id;
  END LOOP;
END;
$$;


--
-- Name: rpc_update_sample_test(uuid, text, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_sample_test(p_sample_id uuid, p_status text, p_user_id uuid DEFAULT NULL::uuid, p_testing_by_name text DEFAULT NULL::text, p_test_note text DEFAULT NULL::text, p_rejection_reason text DEFAULT NULL::text, p_item_results jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_uid  UUID := COALESCE(auth.uid(), p_user_id);
  v_item JSONB;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'manager', 'store', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ทดสอบ Sample (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  IF p_status NOT IN ('testing', 'approved', 'rejected') THEN
    RAISE EXCEPTION 'สถานะไม่ถูกต้อง: %', p_status;
  END IF;

  IF p_status = 'testing' AND COALESCE(trim(p_testing_by_name), '') = '' THEN
    RAISE EXCEPTION 'กรุณาระบุผู้ทดสอบ';
  END IF;

  UPDATE inv_samples
  SET status = p_status,
      testing_by_name = CASE WHEN p_status = 'testing' THEN trim(p_testing_by_name) ELSE testing_by_name END,
      testing_started_by = CASE WHEN p_status = 'testing' THEN v_uid ELSE testing_started_by END,
      testing_started_at = CASE WHEN p_status = 'testing' THEN NOW() ELSE testing_started_at END,
      tested_by = CASE WHEN p_status IN ('approved', 'rejected') THEN v_uid ELSE tested_by END,
      tested_at = CASE WHEN p_status IN ('approved', 'rejected') THEN NOW() ELSE tested_at END,
      approved_by = CASE WHEN p_status = 'approved' THEN v_uid ELSE approved_by END,
      approved_at = CASE WHEN p_status = 'approved' THEN NOW() ELSE approved_at END,
      test_result = CASE WHEN p_status = 'approved' THEN 'passed' WHEN p_status = 'rejected' THEN 'failed' ELSE test_result END,
      test_note = COALESCE(p_test_note, test_note),
      rejection_reason = CASE WHEN p_status = 'rejected' THEN p_rejection_reason ELSE rejection_reason END
  WHERE id = p_sample_id;

  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบ Sample'; END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_item_results)
  LOOP
    UPDATE inv_sample_items
    SET item_test_result = v_item->>'result',
        item_test_note = v_item->>'note'
    WHERE id = (v_item->>'item_id')::UUID AND sample_id = p_sample_id;
  END LOOP;
END;
$$;


--
-- Name: rpc_upsert_storage_location(uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_upsert_storage_location(p_id uuid, p_code text, p_name text DEFAULT NULL::text, p_location_type text DEFAULT 'reserve'::text, p_is_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id UUID;
BEGIN
  IF NOT public.can_manage_warehouse_locations() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการจุดจัดเก็บ';
  END IF;
  IF NULLIF(BTRIM(p_code), '') IS NULL THEN
    RAISE EXCEPTION 'กรุณาระบุรหัสจุดจัดเก็บ';
  END IF;
  IF p_location_type NOT IN ('picking', 'reserve', 'hold', 'unallocated') THEN
    RAISE EXCEPTION 'ประเภทจุดจัดเก็บไม่ถูกต้อง';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.wh_storage_locations(code, name, location_type, is_active, created_by)
    VALUES (UPPER(BTRIM(p_code)), NULLIF(BTRIM(p_name), ''), p_location_type, p_is_active, auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.wh_storage_locations
    SET code = UPPER(BTRIM(p_code)), name = NULLIF(BTRIM(p_name), ''),
        location_type = p_location_type, is_active = p_is_active, updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'ไม่พบจุดจัดเก็บ'; END IF;
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: rpc_use_machinery_part(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_use_machinery_part(p_incident_id uuid, p_product_id uuid, p_qty numeric, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_incident public.pr_machinery_incidents%ROWTYPE;
  v_balance public.pr_machinery_stock_balances%ROWTYPE;
  v_usage_id UUID;
BEGIN
  IF NOT public.can_use_machinery_spares() THEN RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกการใช้อะไหล่'; END IF;
  IF COALESCE(p_qty,0) <= 0 OR p_qty <> TRUNC(p_qty) THEN RAISE EXCEPTION 'จำนวนที่ใช้ต้องเป็นจำนวนเต็มมากกว่า 0'; END IF;
  SELECT * INTO v_incident FROM public.pr_machinery_incidents WHERE id = p_incident_id FOR UPDATE;
  IF v_incident.id IS NULL THEN RAISE EXCEPTION 'ไม่พบใบแจ้งซ่อม'; END IF;
  IF v_incident.status <> 'repairing' THEN RAISE EXCEPTION 'บันทึกอะไหล่ได้เมื่อสถานะเป็นกำลังซ่อมเท่านั้น'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.pr_machinery_machine_parts
    WHERE machine_id = v_incident.machine_id AND product_id = p_product_id
  ) THEN RAISE EXCEPTION 'อะไหล่นี้ไม่ได้กำหนดไว้สำหรับเครื่องจักร'; END IF;

  SELECT * INTO v_balance FROM public.pr_machinery_stock_balances
  WHERE product_id = p_product_id FOR UPDATE;
  IF v_balance.product_id IS NULL OR v_balance.qty < p_qty THEN RAISE EXCEPTION 'สต๊อกอะไหล่ Machinery ไม่เพียงพอ'; END IF;
  UPDATE public.pr_machinery_stock_balances SET qty = qty - p_qty, updated_at = NOW()
  WHERE product_id = p_product_id;

  INSERT INTO public.pr_machinery_incident_parts(
    incident_id, machine_id, product_id, event_type, qty, unit_cost, note, performed_by
  ) VALUES (
    p_incident_id, v_incident.machine_id, p_product_id, 'use', p_qty,
    v_balance.average_unit_cost, NULLIF(BTRIM(p_note),''), auth.uid()
  ) RETURNING id INTO v_usage_id;
  INSERT INTO public.pr_machinery_stock_moves(
    product_id, qty_delta, movement_type, unit_cost, incident_part_id, note, created_by
  ) VALUES (
    p_product_id, -p_qty, 'part_use', v_balance.average_unit_cost,
    v_usage_id, v_incident.ticket_no, auth.uid()
  );
  RETURN v_usage_id;
END;
$$;


--
-- Name: rpc_use_machinery_part_at(uuid, uuid, numeric, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_use_machinery_part_at(p_incident_id uuid, p_product_id uuid, p_qty numeric, p_note text, p_performed_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_incident public.pr_machinery_incidents%ROWTYPE;
  v_balance public.pr_machinery_stock_balances%ROWTYPE;
  v_usage_id UUID;
BEGIN
  IF NOT public.can_use_machinery_spares() THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์บันทึกการใช้อะไหล่';
  END IF;
  IF COALESCE(p_qty,0) <= 0 OR p_qty <> TRUNC(p_qty) THEN
    RAISE EXCEPTION 'จำนวนที่ใช้ต้องเป็นจำนวนเต็มมากกว่า 0';
  END IF;

  SELECT * INTO v_incident
  FROM public.pr_machinery_incidents
  WHERE id = p_incident_id
  FOR UPDATE;

  IF v_incident.id IS NULL THEN RAISE EXCEPTION 'ไม่พบใบแจ้งซ่อม'; END IF;
  IF v_incident.status <> 'repairing' THEN
    RAISE EXCEPTION 'บันทึกอะไหล่ได้เมื่อสถานะเป็นกำลังซ่อมเท่านั้น';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.pr_machinery_machine_parts
    WHERE machine_id = v_incident.machine_id
      AND product_id = p_product_id
  ) THEN
    RAISE EXCEPTION 'อะไหล่นี้ไม่ได้กำหนดไว้สำหรับเครื่องจักร';
  END IF;

  SELECT * INTO v_balance
  FROM public.pr_machinery_stock_balances
  WHERE product_id = p_product_id
  FOR UPDATE;

  IF v_balance.product_id IS NULL OR v_balance.qty < p_qty THEN
    RAISE EXCEPTION 'สต๊อกอะไหล่ Machinery ไม่เพียงพอ';
  END IF;

  UPDATE public.pr_machinery_stock_balances
  SET qty = qty - p_qty, updated_at = NOW()
  WHERE product_id = p_product_id;

  INSERT INTO public.pr_machinery_incident_parts(
    incident_id, machine_id, product_id, event_type, qty, unit_cost,
    note, performed_by, performed_at
  ) VALUES (
    p_incident_id, v_incident.machine_id, p_product_id, 'use', p_qty,
    v_balance.average_unit_cost, NULLIF(BTRIM(p_note),''), auth.uid(),
    COALESCE(p_performed_at, NOW())
  ) RETURNING id INTO v_usage_id;

  INSERT INTO public.pr_machinery_stock_moves(
    product_id, qty_delta, movement_type, unit_cost, incident_part_id, note, created_by
  ) VALUES (
    p_product_id, -p_qty, 'part_use', v_balance.average_unit_cost,
    v_usage_id, v_incident.ticket_no, auth.uid()
  );

  RETURN v_usage_id;
END;
$$;


--
-- Name: FUNCTION rpc_use_machinery_part_at(p_incident_id uuid, p_product_id uuid, p_qty numeric, p_note text, p_performed_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_use_machinery_part_at(p_incident_id uuid, p_product_id uuid, p_qty numeric, p_note text, p_performed_at timestamp with time zone) IS 'Records spare usage using the operator-specified actual date/time while created_at remains the audit creation time.';


--
-- Name: rpc_void_wms_orders(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_void_wms_orders(p_wms_order_ids uuid[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT; v_row public.wms_orders%ROWTYPE; v_id UUID; v_source_action TEXT;
  v_reversed NUMERIC; v_expected_reverse NUMERIC; v_reverse_product UUID; v_count INT := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF v_role IS DISTINCT FROM 'superadmin' THEN RAISE EXCEPTION 'เฉพาะ superadmin เท่านั้นที่ยกเลิกรายการได้'; END IF;
  IF coalesce(array_length(p_wms_order_ids,1),0)=0 THEN RAISE EXCEPTION 'ไม่พบรายการ'; END IF;
  IF length(trim(coalesce(p_reason,'')))<3 THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลอย่างน้อย 3 ตัวอักษร'; END IF;

  FOREACH v_id IN ARRAY p_wms_order_ids LOOP
    SELECT * INTO v_row FROM public.wms_orders WHERE id=v_id FOR UPDATE;
    IF v_row.id IS NULL OR v_row.status='cancelled' THEN CONTINUE; END IF;
    v_reversed := 0;
    IF v_row.status='correct' THEN
      SELECT cancellation_stock_action INTO v_source_action
      FROM public.or_order_items WHERE id=v_row.source_order_item_id;
      SELECT m.product_id,abs(m.qty) INTO v_reverse_product,v_expected_reverse
      FROM public.inv_stock_movements m
      WHERE m.ref_type='wms_orders' AND m.ref_id=v_row.id AND m.movement_type='pick'
      ORDER BY m.created_at DESC LIMIT 1;
      v_reversed := public.fn_reverse_wms_stock(v_row.id);
      -- fn_reverse_wms_stock restores FIFO-consumed lots. If stock was negative and no lot
      -- existed, restore the remaining balance explicitly so a void can never deduct twice.
      IF v_reverse_product IS NOT NULL AND coalesce(v_reversed,0)<coalesce(v_expected_reverse,0) THEN
        INSERT INTO public.inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note)
        VALUES(v_reverse_product,'pick_reversal',v_expected_reverse-coalesce(v_reversed,0),
          'wms_orders',v_row.id,'คืนสต๊อคส่วนที่ไม่มี FIFO lot จากการยกเลิกรายการ WMS');
        UPDATE public.inv_stock_balances SET on_hand=coalesce(on_hand,0)+v_expected_reverse-coalesce(v_reversed,0)
        WHERE product_id=v_reverse_product;
        v_reversed:=v_expected_reverse;
      END IF;
      -- Voiding a WMS row is not cancellation of the sold order item.
      UPDATE public.or_order_items SET cancellation_stock_action=v_source_action
      WHERE id=v_row.source_order_item_id;
    ELSIF v_row.status='picked' THEN
      UPDATE public.inv_stock_balances b
      SET reserved=greatest(coalesce(b.reserved,0)-(v_row.qty*coalesce(p.unit_multiplier,1)),0)
      FROM public.pr_products p
      WHERE p.id=b.product_id AND p.product_code=v_row.product_code;
    END IF;

    INSERT INTO public.wms_order_void_audit(
      wms_order_id,work_order_id,order_display_name,source_order_id,source_order_item_id,
      product_code,product_name,qty,previous_status,reason,stock_reversed_qty,voided_by
    ) VALUES (v_row.id,v_row.work_order_id,v_row.order_id,v_row.source_order_id,v_row.source_order_item_id,
      v_row.product_code,v_row.product_name,v_row.qty,v_row.status,trim(p_reason),coalesce(v_reversed,0),auth.uid());

    UPDATE public.wms_orders SET status='cancelled',voided_at=now(),voided_by=auth.uid(),
      void_reason=trim(p_reason),void_previous_status=v_row.status,end_time=coalesce(end_time,now())
    WHERE id=v_row.id;
    v_count:=v_count+1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'voided_count',v_count);
END;
$$;


--
-- Name: rpc_wms_assigned_names(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_wms_assigned_names(p_work_order_names text[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH requested AS (
    SELECT DISTINCT name FROM unnest(p_work_order_names) names(name) WHERE name IS NOT NULL
  ), headers AS MATERIALIZED (
    SELECT id, btrim(work_order_name) AS name FROM public.or_work_orders
    WHERE btrim(work_order_name) IN (SELECT name FROM requested)
  ), candidates AS MATERIALIZED (
    SELECT w.work_order_id, btrim(w.order_id) AS legacy_name FROM public.wms_orders w
    WHERE (w.fulfillment_mode = 'warehouse_pick' OR w.fulfillment_mode IS NULL)
      AND w.status <> 'cancelled'
      AND (btrim(w.order_id) IN (SELECT name FROM requested)
        OR w.work_order_id IN (SELECT id FROM headers))
  ), assigned AS (
    SELECT legacy_name AS name FROM candidates
    UNION
    SELECT h.name FROM candidates c JOIN headers h ON h.id = c.work_order_id
  )
  SELECT coalesce(jsonb_agg(name ORDER BY name), '[]'::jsonb)
  FROM requested WHERE name IN (SELECT name FROM assigned);
$$;


--
-- Name: sales_owns_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_owns_order(p_order_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.or_orders o
    JOIN public.us_users u ON u.id = auth.uid()
    WHERE o.id = p_order_id
      AND u.role IN ('sales-tr', 'sales-pump')
      AND trim(COALESCE(o.admin_user, '')) <> ''
      AND lower(trim(COALESCE(o.admin_user, ''))) IN (
        lower(trim(COALESCE(u.username, ''))),
        lower(trim(COALESCE(u.email, ''))),
        lower(trim(COALESCE(auth.jwt() ->> 'email', '')))
      )
  );
$$;


--
-- Name: set_adjustment_item_estimated_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_adjustment_item_estimated_cost() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cost numeric := 0;
BEGIN
  SELECT COALESCE(NULLIF(landed_cost, 0), unit_cost, 0)
    INTO v_cost
  FROM public.pr_products
  WHERE id = NEW.product_id;

  NEW.estimated_unit_cost := COALESCE(v_cost, 0);
  NEW.estimated_total_cost_impact := COALESCE(NEW.qty_delta, 0) * COALESCE(v_cost, 0);
  RETURN NEW;
END;
$$;


--
-- Name: set_bill_item_initial_sort_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_bill_item_initial_sort_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
  IF NEW.sort_order IS NULL THEN
    NEW.sort_order := substring(NEW.item_uid from '-([0-9]+)$')::integer;
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: set_machinery_purchase_product(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_machinery_purchase_product(p_product_id uuid, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM us_users WHERE id = auth.uid() AND role IN ('superadmin', 'admin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตั้งค่ารายการสินค้า';
  END IF;
  INSERT INTO pr_machinery_purchase_products(product_id, enabled, updated_by, updated_at)
  VALUES (p_product_id, p_enabled, auth.uid(), now())
  ON CONFLICT (product_id) DO UPDATE
    SET enabled = EXCLUDED.enabled, updated_by = auth.uid(), updated_at = now();
END;
$$;


--
-- Name: set_sub_warehouse_product_sort_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sub_warehouse_product_sort_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.sort_order <= 0 THEN
    SELECT COALESCE(MAX(sort_order), 0) + 1 INTO NEW.sort_order
    FROM public.wh_sub_warehouse_products
    WHERE sub_warehouse_id = NEW.sub_warehouse_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: submit_overpayment_waiver(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_overpayment_waiver(p_order_id uuid, p_reason text, p_evidence_url text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_order public.or_orders; v_user public.us_users; v_paid numeric; v_amount numeric; v_id uuid; v_owner_role text; v_next text;
BEGIN
  SELECT * INTO v_user FROM us_users WHERE id=auth.uid();
  IF v_user.role IS NULL OR v_user.role NOT IN ('superadmin','admin','admin-tr','account','order_staff','sales-tr','sales-pump') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ส่งคำขอไม่รับเงินคืน';
  END IF;
  IF nullif(trim(p_reason),'') IS NULL OR length(p_reason)>1000 THEN
    RAISE EXCEPTION 'กรุณาระบุเหตุผลที่ลูกค้าไม่รับเงินคืน (ไม่เกิน 1,000 ตัวอักษร)';
  END IF;
  IF nullif(trim(p_evidence_url),'') IS NOT NULL
    AND trim(p_evidence_url) !~ '^https?://[^[:space:]]+$' THEN
    RAISE EXCEPTION 'กรุณากรอกลิงก์หลักฐานให้ถูกต้อง โดยขึ้นต้นด้วย https:// หรือ http://';
  END IF;
  SELECT * INTO v_order FROM or_orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิล'; END IF;
  IF v_user.role IN ('sales-tr','sales-pump') AND v_order.admin_user IS DISTINCT FROM v_user.username
    AND v_order.admin_user IS DISTINCT FROM v_user.email THEN RAISE EXCEPTION 'ไม่มีสิทธิ์จัดการบิลนี้'; END IF;
  IF v_order.status='ยกเลิก' THEN RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว'; END IF;
  PERFORM public.or_supersede_stale_waivers(p_order_id);
  IF EXISTS(SELECT 1 FROM ac_refunds WHERE order_id=p_order_id AND status IN ('pending','approved') AND reason ILIKE '%โอนเกิน%') THEN
    RAISE EXCEPTION 'บิลนี้มีคำขอโอนคืนแล้ว กรุณาจัดการคำขอเดิมก่อน';
  END IF;
  IF EXISTS(SELECT 1 FROM ac_overpayment_waivers WHERE order_id=p_order_id AND status IN ('pending','approved')) THEN
    RAISE EXCEPTION 'บิลนี้มีคำขอไม่รับเงินคืนที่รอพิจารณาหรืออนุมัติแล้ว';
  END IF;
  v_paid:=public.or_overpayment_paid(p_order_id); v_amount:=v_paid-v_order.receivable_amount;
  IF v_amount<=0.01 THEN RAISE EXCEPTION 'ไม่พบยอดโอนเกินที่ต้องจัดการ'; END IF;
  INSERT INTO ac_overpayment_waivers(order_id,amount,order_total,paid_amount,reason,evidence_url,created_by,created_by_name)
    VALUES(p_order_id,v_amount,v_order.receivable_amount,v_paid,trim(p_reason),nullif(trim(p_evidence_url),''),auth.uid(),coalesce(v_user.username,v_user.email,v_user.id::text)) RETURNING id INTO v_id;
  SELECT role INTO v_owner_role FROM us_users WHERE username=v_order.admin_user OR email=v_order.admin_user
    ORDER BY (username=v_order.admin_user) DESC NULLS LAST LIMIT 1;
  v_next:=CASE WHEN upper(trim(v_order.channel_code))='WY' THEN 'ตรวจสอบแล้ว'
    WHEN v_owner_role='sales-tr' AND ((v_order.channel_code='PUMP' AND v_order.requires_confirm_design=FALSE)
      OR (v_order.channel_code IS DISTINCT FROM 'PUMP' AND coalesce(v_order.requires_confirm_design,FALSE)=FALSE)) THEN 'รอตรวจคำสั่งซื้อ'
    WHEN v_order.channel_code='PUMP' AND v_order.requires_confirm_design=FALSE THEN 'ไม่ต้องออกแบบ'
    ELSE 'ตรวจสอบแล้ว' END;
  PERFORM public.or_apply_payment_review_status(p_order_id,v_next,'overpayment_request');
  RETURN v_id;
END $_$;


--
-- Name: sync_adjustment_item_actual_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_adjustment_item_actual_cost() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.ref_type = 'inv_adjustments' AND NEW.ref_id IS NOT NULL THEN
    UPDATE public.inv_adjustment_items ai
    SET approved_unit_cost = CASE
          WHEN COALESCE(ai.qty_delta, 0) <> 0
            THEN ABS(COALESCE(NEW.total_cost, 0) / ai.qty_delta)
          ELSE 0
        END,
        approved_total_cost_impact = COALESCE(NEW.total_cost, 0)
    WHERE ai.adjustment_id = NEW.ref_id
      AND ai.product_id = NEW.product_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_cancelled_erp_bill_to_marketplace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_cancelled_erp_bill_to_marketplace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'ยกเลิก' AND OLD.status IS DISTINCT FROM NEW.status THEN
    UPDATE public.mp_orders
    SET status = 'cancelled',
        cancel_note = COALESCE(cancel_note, 'บิล ERP ที่เชื่อมโยงถูกยกเลิก'),
        cancelled_at = COALESCE(cancelled_at, now()),
        cancelled_by = COALESCE(cancelled_by, auth.uid())
    WHERE billed_order_id = NEW.id
      AND is_current
      AND status = 'done';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_order_parcel_return_marker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_order_parcel_return_marker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.has_parcel_return := EXISTS (
    SELECT 1 FROM public.inv_returns r WHERE r.ref_bill_no = NEW.bill_no
  );
  RETURN NEW;
END;
$$;


--
-- Name: sync_parcel_return_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_parcel_return_orders() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    UPDATE public.or_orders o
    SET has_parcel_return = EXISTS (
      SELECT 1 FROM public.inv_returns r WHERE r.ref_bill_no = o.bill_no
    )
    WHERE o.bill_no = OLD.ref_bill_no;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    UPDATE public.or_orders o
    SET has_parcel_return = EXISTS (
      SELECT 1 FROM public.inv_returns r WHERE r.ref_bill_no = o.bill_no
    )
    WHERE o.bill_no = NEW.ref_bill_no;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: tr_audit_bank_classification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_audit_bank_classification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF ROW(OLD.classification_rule_id,OLD.classification_name,OLD.reconciliation_status) IS DISTINCT FROM
 ROW(NEW.classification_rule_id,NEW.classification_name,NEW.reconciliation_status) AND (OLD.reconciliation_status='ignored' OR NEW.reconciliation_status='ignored') THEN
 INSERT INTO public.ac_bank_classification_audit(transaction_id,old_rule_id,old_name,old_status,new_rule_id,new_name,new_status,actor_id)
 VALUES(NEW.id,OLD.classification_rule_id,OLD.classification_name,OLD.reconciliation_status,NEW.classification_rule_id,NEW.classification_name,NEW.reconciliation_status,auth.uid());
 END IF; RETURN NEW;
END $$;


--
-- Name: tr_cancel_pending_manual_slips(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_cancel_pending_manual_slips() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'ยกเลิก' AND OLD.status IS DISTINCT FROM NEW.status THEN
    UPDATE public.ac_manual_slip_checks
    SET status = 'cancelled',
        cancelled_at = now(),
        reviewed_at = COALESCE(reviewed_at, now()),
        reviewed_by = COALESCE(reviewed_by, 'ระบบ: บิลยกเลิก'),
        rejected_reason = NULL
    WHERE order_id = NEW.id
      AND status = 'pending';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_classify_bank_statement_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_classify_bank_statement_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rule public.ac_bank_transaction_rules;
BEGIN
  IF NEW.reconciliation_status = 'matched' THEN RETURN NEW; END IF;

  SELECT * INTO v_rule
  FROM public.bank_matching_rule(
    NEW.bank_setting_id,
    NEW.transaction_type,
    NEW.channel,
    NEW.description,
    NEW.debit_amount,
    NEW.credit_amount
  );

  IF v_rule.id IS NOT NULL THEN
    NEW.reconciliation_status := 'ignored';
    NEW.classification_rule_id := v_rule.id;
    NEW.classification_name := v_rule.classification_name;
    NEW.classified_at := now();
    NEW.classified_by := auth.uid();
  ELSIF NEW.reconciliation_status='ignored' THEN
    NEW.reconciliation_status := 'unmatched';
    NEW.classification_rule_id := NULL;
    NEW.classification_name := NULL;
    NEW.classified_at := NULL;
    NEW.classified_by := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_delivery_check_delete_import(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_delete_import(p_import_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_import public.tr_delivery_check_imports;
  v_row_count INTEGER;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ลบประวัติการนำเข้า';
  END IF;

  SELECT * INTO v_import FROM public.tr_delivery_check_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'ไม่พบประวัติการนำเข้าที่ต้องการลบ'; END IF;

  SELECT count(*) INTO v_row_count
  FROM public.tr_delivery_check_rows
  WHERE import_id = p_import_id;

  DELETE FROM public.tr_delivery_check_imports WHERE id = p_import_id;

  RETURN jsonb_build_object(
    'deleted_import_id', v_import.id,
    'file_name', v_import.file_name,
    'carrier', v_import.carrier,
    'deleted_row_count', v_row_count
  );
END;
$$;


--
-- Name: tr_delivery_check_find_previous_duplicates(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_find_previous_duplicates(p_tracking_keys text[]) RETURNS TABLE(tracking_no_normalized text, tracking_no text, previous_import_id uuid, previous_file_name text, previous_carrier text, previous_imported_at timestamp with time zone, previous_pickup_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจประวัติไฟล์ขนส่ง';
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (row.tracking_no_normalized)
    row.tracking_no_normalized,
    row.tracking_no,
    import.id,
    import.file_name,
    import.carrier,
    import.uploaded_at,
    row.pickup_at
  FROM public.tr_delivery_check_rows row
  JOIN public.tr_delivery_check_imports import ON import.id = row.import_id
  WHERE row.source_kind = 'carrier'
    AND row.tracking_no_normalized = ANY(coalesce(p_tracking_keys, ARRAY[]::TEXT[]))
  ORDER BY row.tracking_no_normalized, import.uploaded_at DESC, row.created_at DESC;
END;
$$;


--
-- Name: tr_delivery_check_import(text, text, text, text, date, date, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_import(p_carrier text, p_file_name text, p_file_hash text, p_sheet_name text, p_pickup_date_from date, p_pickup_date_to date, p_warnings jsonb, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_import_id UUID;
  v_item JSONB;
  v_order RECORD;
  v_candidate_count INTEGER;
  v_order_no TEXT;
  v_tracking_no TEXT;
  v_order_key TEXT;
  v_tracking_key TEXT;
  v_is_consignment BOOLEAN;
  v_match_status TEXT;
  v_match_method TEXT;
  v_match_detail TEXT;
  v_order_id UUID;
  v_source_count INTEGER := 0;
  v_matched_count INTEGER := 0;
  v_issue_count INTEGER := 0;
  v_consignment_count INTEGER := 0;
  v_system_only_count INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์นำเข้าไฟล์ตรวจสอบการส่ง';
  END IF;
  IF nullif(btrim(p_carrier), '') IS NULL THEN
    RAISE EXCEPTION 'กรุณาเลือกบริษัทขนส่ง';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'ไฟล์ไม่มีรายการสำหรับนำเข้า';
  END IF;

  INSERT INTO public.tr_delivery_check_imports (
    carrier, file_name, file_hash, sheet_name, pickup_date_from, pickup_date_to,
    source_row_count, warnings, uploaded_by
  ) VALUES (
    upper(btrim(p_carrier)), p_file_name, p_file_hash, p_sheet_name,
    p_pickup_date_from, p_pickup_date_to, jsonb_array_length(p_rows),
    coalesce(p_warnings, '[]'::JSONB), auth.uid()
  ) RETURNING id INTO v_import_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_source_count := v_source_count + 1;
    v_order_no := nullif(btrim(coalesce(v_item->>'order_no', '')), '');
    v_tracking_no := nullif(btrim(coalesce(v_item->>'tracking_no', '')), '');
    v_order_key := public.tr_normalize_delivery_key(v_order_no);
    v_tracking_key := public.tr_normalize_delivery_key(v_tracking_no);
    v_is_consignment := coalesce((v_item->>'is_consignment')::BOOLEAN, false);
    v_match_status := 'unmatched';
    v_match_method := NULL;
    v_match_detail := NULL;
    v_order_id := NULL;

    IF v_is_consignment THEN
      v_match_status := 'consignment';
      v_consignment_count := v_consignment_count + 1;
    ELSIF v_tracking_key = '' THEN
      v_match_status := 'invalid';
      v_match_detail := 'ไม่มี Tracking No.';
      v_issue_count := v_issue_count + 1;
    ELSE
      SELECT count(*)
      INTO v_candidate_count
      FROM public.or_orders o
      WHERE COALESCE(o.status, '') <> 'ยกเลิก'
        AND public.tr_normalize_delivery_key(o.tracking_number) = v_tracking_key;

      IF v_candidate_count = 1 THEN
        SELECT o.id, o.bill_no, o.channel_order_no, o.tracking_number
        INTO v_order
        FROM public.or_orders o
        WHERE COALESCE(o.status, '') <> 'ยกเลิก'
        AND public.tr_normalize_delivery_key(o.tracking_number) = v_tracking_key
        LIMIT 1;
        v_order_id := v_order.id;
        v_match_method := 'tracking_number';
        IF v_order_key <> '' AND v_order_key IN (
          public.tr_normalize_delivery_key(v_order.bill_no),
          public.tr_normalize_delivery_key(v_order.channel_order_no)
        ) THEN
          v_match_status := 'matched';
          v_matched_count := v_matched_count + 1;
        ELSE
          v_match_status := 'tracking_only';
          v_match_detail := 'Tracking ตรง แต่ Order No. ไม่ตรงกับเลขบิลในระบบ';
          v_issue_count := v_issue_count + 1;
        END IF;
      ELSIF v_candidate_count > 1 THEN
        v_match_status := 'ambiguous';
        v_match_detail := 'พบ Tracking ซ้ำในระบบมากกว่า 1 บิล';
        v_issue_count := v_issue_count + 1;
      ELSE
        SELECT count(*)
        INTO v_candidate_count
        FROM public.or_orders o
        WHERE COALESCE(o.status, '') <> 'ยกเลิก'
          AND v_order_key <> '' AND v_order_key IN (
          public.tr_normalize_delivery_key(o.bill_no),
          public.tr_normalize_delivery_key(o.channel_order_no)
        );

        IF v_candidate_count = 1 THEN
          SELECT o.id, o.bill_no, o.channel_order_no, o.tracking_number
          INTO v_order
          FROM public.or_orders o
          WHERE COALESCE(o.status, '') <> 'ยกเลิก'
          AND v_order_key <> '' AND v_order_key IN (
            public.tr_normalize_delivery_key(o.bill_no),
            public.tr_normalize_delivery_key(o.channel_order_no)
          )
          LIMIT 1;
          v_order_id := v_order.id;
          v_match_method := CASE
            WHEN v_order_key = public.tr_normalize_delivery_key(v_order.bill_no) THEN 'bill_no'
            ELSE 'channel_order_no'
          END;
          v_match_status := 'order_only';
          v_match_detail := 'Order No. ตรง แต่ Tracking ไม่ตรงกับระบบ';
          v_issue_count := v_issue_count + 1;
        ELSIF v_candidate_count > 1 THEN
          v_match_status := 'ambiguous';
          v_match_detail := 'พบ Order No. ซ้ำในระบบมากกว่า 1 บิล';
          v_issue_count := v_issue_count + 1;
        ELSE
          v_match_status := 'unmatched';
          v_match_detail := 'ไม่พบเลขพัสดุหรือเลขบิลในระบบ';
          v_issue_count := v_issue_count + 1;
        END IF;
      END IF;
    END IF;

    INSERT INTO public.tr_delivery_check_rows (
      import_id, source_kind, source_row_number, pickup_at,
      order_no, order_no_normalized, tracking_no, tracking_no_normalized,
      sender, consignee, consignee_phone, consignee_address,
      is_consignment, note, order_id, match_status, match_method, match_detail, raw_data
    ) VALUES (
      v_import_id, 'carrier', (v_item->>'source_row_number')::INTEGER,
      nullif(v_item->>'pickup_at', '')::TIMESTAMPTZ,
      v_order_no, v_order_key, v_tracking_no, v_tracking_key,
      nullif(v_item->>'sender', ''), nullif(v_item->>'consignee', ''),
      nullif(v_item->>'consignee_phone', ''), nullif(v_item->>'consignee_address', ''),
      v_is_consignment, nullif(v_item->>'note', ''), v_order_id,
      v_match_status, v_match_method, v_match_detail, coalesce(v_item->'raw_data', '{}'::JSONB)
    );
  END LOOP;

  UPDATE public.tr_delivery_check_rows r
  SET has_duplicate = true,
      match_detail = concat_ws(' / ', r.match_detail, 'Tracking ซ้ำในไฟล์')
  WHERE r.import_id = v_import_id
    AND r.source_kind = 'carrier'
    AND r.tracking_no_normalized <> ''
    AND EXISTS (
      SELECT 1 FROM public.tr_delivery_check_rows duplicate_row
      WHERE duplicate_row.import_id = r.import_id
        AND duplicate_row.source_kind = 'carrier'
        AND duplicate_row.tracking_no_normalized = r.tracking_no_normalized
        AND duplicate_row.id <> r.id
    );

  -- Add bills shipped by the selected carrier during the pickup-file dates but
  -- absent from the carrier file. Consignments never create a missing ERP bill.
  INSERT INTO public.tr_delivery_check_rows (
    import_id, source_kind, pickup_at, order_no, order_no_normalized,
    tracking_no, tracking_no_normalized, sender, consignee,
    consignee_phone, consignee_address, order_id, match_status, match_detail, raw_data
  )
  SELECT
    v_import_id, 'system', o.shipped_time, o.bill_no,
    public.tr_normalize_delivery_key(o.bill_no), o.tracking_number,
    public.tr_normalize_delivery_key(o.tracking_number), o.channel_code,
    coalesce(o.recipient_name, o.customer_name),
    nullif(o.billing_details->>'mobile_phone', ''), o.customer_address,
    o.id, 'system_only', 'ระบบระบุว่าส่งแล้ว แต่ไม่พบในไฟล์ขนส่ง',
    jsonb_build_object('bill_no', o.bill_no, 'channel_code', o.channel_code, 'shipped_time', o.shipped_time)
  FROM public.or_orders o
  LEFT JOIN public.channels c ON c.channel_code = o.channel_code
  WHERE o.status = 'จัดส่งแล้ว'
    AND coalesce(o.fulfillment_method, CASE WHEN coalesce(c.is_self_pickup, false) THEN 'self_pickup' ELSE 'shipping' END) = 'shipping'
    AND upper(coalesce(c.default_carrier, 'OTHER')) = upper(btrim(p_carrier))
    AND (o.shipped_time AT TIME ZONE 'Asia/Bangkok')::DATE BETWEEN p_pickup_date_from AND p_pickup_date_to
    AND NOT EXISTS (
      SELECT 1 FROM public.tr_delivery_check_rows r
      WHERE r.import_id = v_import_id AND r.order_id = o.id
    );

  GET DIAGNOSTICS v_system_only_count = ROW_COUNT;
  SELECT count(*)
  INTO v_issue_count
  FROM public.tr_delivery_check_rows
  WHERE import_id = v_import_id
    AND (match_status NOT IN ('matched', 'manual_match', 'consignment') OR has_duplicate);

  UPDATE public.tr_delivery_check_imports
  SET source_row_count = v_source_count,
      matched_count = v_matched_count,
      issue_count = v_issue_count,
      consignment_count = v_consignment_count,
      system_only_count = v_system_only_count,
      updated_at = now()
  WHERE id = v_import_id;

  RETURN jsonb_build_object(
    'import_id', v_import_id,
    'source_row_count', v_source_count,
    'matched_count', v_matched_count,
    'issue_count', v_issue_count,
    'consignment_count', v_consignment_count,
    'system_only_count', v_system_only_count
  );
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'ไฟล์นี้เคยนำเข้าสำหรับขนส่งรายนี้แล้ว';
END;
$$;


--
-- Name: tr_delivery_check_mark_previous_import(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_mark_previous_import() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_previous RECORD;
BEGIN
  IF NEW.source_kind <> 'carrier' OR coalesce(NEW.tracking_no_normalized, '') = '' THEN
    RETURN NEW;
  END IF;

  SELECT
    old_row.import_id,
    old_row.pickup_at,
    old_import.file_name,
    old_import.carrier,
    old_import.uploaded_at
  INTO v_previous
  FROM public.tr_delivery_check_rows old_row
  JOIN public.tr_delivery_check_imports old_import ON old_import.id = old_row.import_id
  WHERE old_row.source_kind = 'carrier'
    AND old_row.import_id <> NEW.import_id
    AND old_row.tracking_no_normalized = NEW.tracking_no_normalized
  ORDER BY old_import.uploaded_at DESC, old_row.created_at DESC
  LIMIT 1;

  IF v_previous.import_id IS NOT NULL THEN
    NEW.has_previous_import := true;
    NEW.previous_import_id := v_previous.import_id;
    NEW.previous_file_name := v_previous.file_name;
    NEW.previous_carrier := v_previous.carrier;
    NEW.previous_imported_at := v_previous.uploaded_at;
    NEW.previous_pickup_at := v_previous.pickup_at;
    NEW.match_detail := concat_ws(' / ', NEW.match_detail, 'Tracking นี้เคยนำเข้าแล้ว');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_delivery_check_rows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tr_delivery_check_rows (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    import_id uuid NOT NULL,
    source_kind text DEFAULT 'carrier'::text NOT NULL,
    source_row_number integer,
    pickup_at timestamp with time zone,
    order_no text,
    order_no_normalized text DEFAULT ''::text NOT NULL,
    tracking_no text,
    tracking_no_normalized text DEFAULT ''::text NOT NULL,
    sender text,
    consignee text,
    consignee_phone text,
    consignee_address text,
    is_consignment boolean DEFAULT false NOT NULL,
    note text,
    order_id uuid,
    match_status text DEFAULT 'unmatched'::text NOT NULL,
    match_method text,
    match_detail text,
    has_duplicate boolean DEFAULT false NOT NULL,
    review_status text DEFAULT 'open'::text NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    raw_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    has_previous_import boolean DEFAULT false NOT NULL,
    previous_import_id uuid,
    previous_file_name text,
    previous_carrier text,
    previous_imported_at timestamp with time zone,
    previous_pickup_at timestamp with time zone,
    CONSTRAINT tr_delivery_check_rows_match_status_check CHECK ((match_status = ANY (ARRAY['matched'::text, 'tracking_only'::text, 'order_only'::text, 'ambiguous'::text, 'unmatched'::text, 'consignment'::text, 'system_only'::text, 'invalid'::text, 'manual_match'::text]))),
    CONSTRAINT tr_delivery_check_rows_review_status_check CHECK ((review_status = ANY (ARRAY['open'::text, 'resolved'::text]))),
    CONSTRAINT tr_delivery_check_rows_source_kind_check CHECK ((source_kind = ANY (ARRAY['carrier'::text, 'system'::text])))
);


--
-- Name: tr_delivery_check_move_to_review(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_move_to_review(p_row_id uuid, p_note text) RETURNS public.tr_delivery_check_rows
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_row public.tr_delivery_check_rows;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขผลตรวจสอบการส่ง';
  END IF;
  SELECT * INTO v_row FROM public.tr_delivery_check_rows WHERE id = p_row_id FOR UPDATE;
  IF v_row.id IS NULL OR v_row.source_kind <> 'carrier' OR NOT v_row.is_consignment THEN
    RAISE EXCEPTION 'รายการนี้ไม่ใช่รายการฝากส่ง';
  END IF;
  -- Serialize summary refreshes for this import.
  PERFORM 1 FROM public.tr_delivery_check_imports WHERE id = v_row.import_id FOR UPDATE;
  UPDATE public.tr_delivery_check_rows
  SET is_consignment = false, match_status = 'unmatched', match_method = 'manual_review',
      match_detail = 'เจ้าหน้าที่เปลี่ยนจากฝากส่งเป็นต้องตรวจ',
      note = nullif(btrim(coalesce(p_note, '')), ''), review_status = 'open',
      reviewed_by = NULL, reviewed_at = NULL, updated_at = now()
  WHERE id = p_row_id RETURNING * INTO v_row;
  UPDATE public.tr_delivery_check_imports i
  SET consignment_count = (SELECT count(*) FROM public.tr_delivery_check_rows r WHERE r.import_id = i.id AND r.source_kind = 'carrier' AND r.match_status = 'consignment'), updated_at = now()
  WHERE i.id = v_row.import_id;
  PERFORM public.tr_delivery_check_rebuild_system_only(v_row.import_id);
  RETURN v_row;
END;
$$;


--
-- Name: tr_delivery_check_rebuild_system_only(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_rebuild_system_only(p_import_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_issue_count INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ประมวลผลรายการตรวจสอบการส่ง';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tr_delivery_check_imports WHERE id = p_import_id) THEN
    RAISE EXCEPTION 'ไม่พบรอบนำเข้า';
  END IF;

  DELETE FROM public.tr_delivery_check_rows
  WHERE import_id = p_import_id AND source_kind = 'system';

  SELECT count(*) INTO v_issue_count
  FROM public.tr_delivery_check_rows row
  WHERE row.import_id = p_import_id
    AND row.source_kind = 'carrier'
    AND row.review_status = 'open'
    AND (
      row.match_status NOT IN ('matched', 'manual_match', 'consignment')
      OR row.has_duplicate
      OR row.has_previous_import
    );

  UPDATE public.tr_delivery_check_imports
  SET system_only_count = 0,
      issue_count = v_issue_count,
      updated_at = now()
  WHERE id = p_import_id;

  RETURN jsonb_build_object('system_only_count', 0, 'issue_count', v_issue_count);
END;
$$;


--
-- Name: tr_delivery_check_refresh_import_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_refresh_import_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  SELECT
    count(*) FILTER (WHERE source_kind = 'carrier'),
    count(*) FILTER (WHERE match_status IN ('matched', 'manual_match')),
    count(*) FILTER (
      WHERE match_status NOT IN ('matched', 'manual_match', 'consignment')
         OR has_duplicate
         OR has_previous_import
    ),
    count(*) FILTER (WHERE match_status = 'consignment'),
    count(*) FILTER (WHERE match_status = 'system_only')
  INTO
    NEW.source_row_count,
    NEW.matched_count,
    NEW.issue_count,
    NEW.consignment_count,
    NEW.system_only_count
  FROM public.tr_delivery_check_rows
  WHERE import_id = NEW.id;
  RETURN NEW;
END;
$$;


--
-- Name: tr_delivery_check_review_row(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_check_review_row(p_row_id uuid, p_note text, p_resolved boolean DEFAULT false) RETURNS public.tr_delivery_check_rows
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_row public.tr_delivery_check_rows;
  v_issue_count INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขผลตรวจสอบการส่ง';
  END IF;

  UPDATE public.tr_delivery_check_rows
  SET note = nullif(btrim(coalesce(p_note, '')), ''),
      review_status = CASE WHEN p_resolved THEN 'resolved' ELSE review_status END,
      reviewed_by = CASE WHEN p_resolved THEN auth.uid() ELSE reviewed_by END,
      reviewed_at = CASE WHEN p_resolved THEN now() ELSE reviewed_at END,
      updated_at = now()
  WHERE id = p_row_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการตรวจสอบ'; END IF;

  SELECT count(*) INTO v_issue_count
  FROM public.tr_delivery_check_rows row
  WHERE row.import_id = v_row.import_id
    AND row.source_kind = 'carrier'
    AND row.review_status = 'open'
    AND (
      row.match_status NOT IN ('matched', 'manual_match', 'consignment')
      OR row.has_duplicate
      OR row.has_previous_import
    );

  UPDATE public.tr_delivery_check_imports
  SET issue_count = v_issue_count,
      updated_at = now()
  WHERE id = v_row.import_id;

  RETURN v_row;
END;
$$;


--
-- Name: tr_delivery_classify_consignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_classify_consignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.source_kind = 'carrier'
    AND public.tr_delivery_is_consignment(NEW.order_no) THEN
    NEW.is_consignment := true;
    NEW.match_status := 'consignment';
    NEW.note := coalesce(nullif(btrim(NEW.note), ''), nullif(btrim(NEW.order_no), ''));
    NEW.order_id := NULL;
    NEW.match_method := NULL;
    NEW.match_detail := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_delivery_is_consignment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_is_consignment(p_order_no text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT coalesce(p_order_no, '') ~* '(moshi|โมชิ|ฝากส่ง)'
    OR public.tr_normalize_delivery_key(p_order_no)
      !~ '^[A-Z][A-Z0-9]*[0-9]{2}(0[1-9]|1[0-2])[0-9]{4,}$';
$_$;


--
-- Name: tr_delivery_tracking_workspace(date, date, text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_delivery_tracking_workspace(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_status text DEFAULT 'all'::text, p_search text DEFAULT ''::text, p_carrier text DEFAULT ''::text, p_channel text DEFAULT ''::text, p_date_basis text DEFAULT 'created'::text, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result JSONB;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid()
  AND role IN ('superadmin','admin','admin-tr','sales-tr','packing_staff', 'account')) THEN
  RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจสอบการส่ง';
 END IF;
 IF p_date_basis NOT IN ('created','packed') THEN RAISE EXCEPTION 'วันที่กรองไม่ถูกต้อง'; END IF;
 WITH scoped AS (
  SELECT o.id,o.bill_no,o.channel_order_no,o.created_at,o.channel_code,o.tracking_number,
   o.recipient_name,o.customer_name,o.status erp_status,o.shipped_time packed_at,
   COALESCE(o.fulfillment_method='self_pickup',c.is_self_pickup,false) self_pickup
  FROM public.or_orders o LEFT JOIN public.channels c ON c.channel_code=o.channel_code
  WHERE o.created_at >= TIMESTAMPTZ '2026-09-01 00:00:00+07'
   AND COALESCE(o.channel_code,'') NOT IN ('SPTR','FSPTR','TTTR','LZTR','PGTR','WY')
   AND o.fulfillment_method IS DISTINCT FROM 'self_pickup'
   AND NOT COALESCE(c.is_self_pickup,false)
   AND COALESCE(o.status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ')
   AND (p_from IS NULL OR CASE WHEN p_date_basis='packed' THEN o.shipped_time ELSE o.created_at END >= p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_to IS NULL OR CASE WHEN p_date_basis='packed' THEN o.shipped_time ELSE o.created_at END < (p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_channel='' OR o.channel_code=p_channel)
   AND (p_search='' OR strpos(lower(concat_ws(' ',o.bill_no,o.channel_order_no,o.tracking_number,o.recipient_name,o.customer_name)),lower(p_search))>0)
 ), evidence AS (
  SELECT o.*,r.id source_id,r.import_id,r.file_name,r.carrier,r.pickup_at,r.tracking_no carrier_tracking,
   r.order_no carrier_order_no,r.raw_data,r.match_detail,r.match_status,r.has_duplicate,
   r.candidate_count,r.keys_match,r.review_status,
   COALESCE(NULLIF(btrim(r.raw_data->>'สถานะงานรับ'),''),'') pickup_status
  FROM scoped o LEFT JOIN LATERAL (
   SELECT d.*,i.file_name,i.carrier,i.uploaded_at,
    (SELECT count(*) FROM public.or_orders other WHERE
      (d.tracking_no_normalized<>'' AND public.tr_normalize_delivery_key(other.tracking_number)=d.tracking_no_normalized)
      OR (d.order_no_normalized<>'' AND (public.tr_normalize_delivery_key(other.bill_no)=d.order_no_normalized
       OR public.tr_normalize_delivery_key(other.channel_order_no)=d.order_no_normalized))) candidate_count,
    (d.match_status='manual_match' AND d.order_id=o.id OR
     (d.tracking_no_normalized<>'' AND d.tracking_no_normalized=public.tr_normalize_delivery_key(o.tracking_number)
      AND d.order_no_normalized<>'' AND d.order_no_normalized IN
       (public.tr_normalize_delivery_key(o.bill_no),public.tr_normalize_delivery_key(o.channel_order_no))
      AND (d.order_id IS NULL OR d.order_id=o.id))) keys_match
   FROM public.tr_delivery_check_rows d JOIN public.tr_delivery_check_imports i ON i.id=d.import_id
   WHERE d.source_kind='carrier' AND NOT d.is_consignment
    AND (d.order_id=o.id OR (d.tracking_no_normalized<>'' AND d.tracking_no_normalized=public.tr_normalize_delivery_key(o.tracking_number))
     OR (d.order_no_normalized<>'' AND d.order_no_normalized IN
       (public.tr_normalize_delivery_key(o.bill_no),public.tr_normalize_delivery_key(o.channel_order_no))))
   ORDER BY d.pickup_at DESC NULLS LAST,i.uploaded_at DESC,d.source_row_number DESC,d.id LIMIT 1
  ) r ON TRUE
 ), classified AS (
  SELECT e.*,CASE
   WHEN self_pickup THEN 'self_pickup'
   WHEN source_id IS NOT NULL AND (NOT keys_match OR has_duplicate OR (candidate_count<>1 AND match_status<>'manual_match')) THEN 'needs_review'
   WHEN source_id IS NOT NULL AND lower(pickup_status) IN ('รับพัสดุไม่สำเร็จ','รับไม่สำเร็จ','ยกเลิก') THEN 'pickup_issue'
   WHEN source_id IS NOT NULL AND lower(pickup_status) IN ('รับพัสดุแล้ว','รับพัสดุสำเร็จ','รับพัสดุเรียบร้อย','picked up','picked_up') THEN 'received'
   WHEN source_id IS NOT NULL AND pickup_status='ยังไม่ได้รับพัสดุ' THEN 'awaiting_pickup'
   WHEN source_id IS NOT NULL THEN 'carrier_recorded'
   WHEN packed_at IS NULL THEN 'pending_pack'
   WHEN public.tr_normalize_delivery_key(tracking_number)='' THEN 'no_tracking'
   ELSE 'awaiting_carrier' END delivery_state
  FROM evidence e
 ), base AS (SELECT * FROM classified WHERE p_carrier='' OR carrier=p_carrier),
 filtered AS (SELECT * FROM base WHERE p_status='all' OR delivery_state=p_status
  OR (p_status='issues' AND delivery_state IN ('needs_review','pickup_issue','carrier_recorded'))
  OR (p_status='pending' AND delivery_state NOT IN ('received','self_pickup'))),
 page AS (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT 50 OFFSET greatest(p_offset,0))
 SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(to_jsonb(page)-'raw_data') FROM page),'[]'::JSONB),
  'count',(SELECT count(*) FROM filtered),'summary',jsonb_build_object('bills',(SELECT count(*) FROM base),
   'states',COALESCE((SELECT jsonb_object_agg(delivery_state,n) FROM (SELECT delivery_state,count(*) n FROM base GROUP BY delivery_state) s),'{}'::JSONB)),
  'channels',(SELECT COALESCE(jsonb_agg(channel_code),'[]'::JSONB) FROM (SELECT DISTINCT o.channel_code FROM public.or_orders o LEFT JOIN public.channels ch ON ch.channel_code=o.channel_code
   WHERE COALESCE(o.channel_code,'') NOT IN ('SPTR','FSPTR','TTTR','LZTR','PGTR','WY')
   AND o.fulfillment_method IS DISTINCT FROM 'self_pickup' AND NOT COALESCE(ch.is_self_pickup,false)
   AND o.created_at>=TIMESTAMPTZ '2026-09-01 00:00:00+07' AND COALESCE(o.status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') ORDER BY o.channel_code) c),
  'carriers',(SELECT COALESCE(jsonb_agg(carrier),'[]'::JSONB) FROM (SELECT DISTINCT carrier FROM public.tr_delivery_check_imports ORDER BY carrier) c)) INTO v_result;
 RETURN v_result;
END $$;


--
-- Name: tr_fn_claim_order_direct_to_plan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_fn_claim_order_direct_to_plan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.bill_no LIKE 'REQ%'
     AND NEW.claim_shipping_confirmed_at IS NOT NULL
     AND NEW.status = 'ตรวจสอบแล้ว' THEN
    NEW.status := CASE
      WHEN BTRIM(COALESCE(NEW.channel_code, '')) = 'PUMP' THEN 'เสร็จสิ้น'::text
      ELSE 'ใบสั่งงาน'::text
    END;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tr_fn_or_orders_req_shipping_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_fn_or_orders_req_shipping_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_wq text[] := ARRAY['ใบสั่งงาน','คอนเฟิร์มแล้ว','เสร็จสิ้น','ย้ายจากใบงาน'];
BEGIN
  IF NEW.bill_no IS NULL OR NEW.bill_no NOT LIKE 'REQ%' THEN
    RETURN NEW;
  END IF;
  IF NEW.claim_shipping_confirmed_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status = ANY(v_wq)
     AND NOT (OLD.status = ANY(v_wq))
     AND OLD.status IS DISTINCT FROM 'ใบงานกำลังผลิต' THEN
    RAISE EXCEPTION
      'บิลเคลม (REQ): กรุณายืนยันที่อยู่จัดส่ง (ชื่อผู้รับ ที่อยู่ เบอร์โทร) ในเมนู ออเดอร์ → บิลเคลม (REQ) ก่อนปรับสถานะเป็น %',
      NEW.status
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_fn_sync_revised_claim_review_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_fn_sync_revised_claim_review_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.created_claim_order_id IS NULL OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'pending' THEN
    UPDATE public.or_orders
    SET status = 'รออนุมัติเคลม',
        claim_shipping_confirmed_at = NULL,
        updated_at = now()
    WHERE id = NEW.created_claim_order_id
      AND status IN ('ตรวจสอบไม่ผ่าน', 'ตรวจสอบไม่สำเร็จ');
  ELSIF NEW.status = 'rejected' THEN
    UPDATE public.or_orders
    SET status = 'ตรวจสอบไม่ผ่าน',
        updated_at = now()
    WHERE id = NEW.created_claim_order_id
      AND status = 'รออนุมัติเคลม';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tr_guard_bank_certified_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_bank_certified_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_total numeric; v_cert numeric; v_bank numeric;
BEGIN
 SELECT receivable_amount INTO v_total FROM or_orders WHERE id=NEW.order_id FOR UPDATE;
 SELECT coalesce(sum(amount),0) INTO v_cert FROM ac_order_receipt_certifications WHERE order_id=NEW.order_id AND revoked_at IS NULL;
 IF v_cert>0 THEN
  SELECT coalesce(sum(allocated_amount),0) INTO v_bank FROM ac_bank_reconciliation_allocations WHERE order_id=NEW.order_id AND id<>NEW.id;
  IF v_cert+v_bank+NEW.allocated_amount>v_total+public.or_approved_overpayment_amount(NEW.order_id)+0.01 THEN
    RAISE EXCEPTION 'บิลมีการรับรองเงินรับแล้ว กรุณายกเลิกหรือปรับการรับรองก่อนจับคู่เพื่อไม่ให้นับเงินซ้ำ';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: tr_guard_fully_allocated_bank_bill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_fully_allocated_bank_bill() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_bill_no text; v_limit numeric; v_allocated numeric;
BEGIN
 SELECT bill_no,receivable_amount INTO v_bill_no,v_limit FROM or_orders WHERE id=NEW.order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบบิลที่ต้องการจับคู่'; END IF;
 v_limit:=coalesce(v_limit,0)+public.or_approved_overpayment_amount(NEW.order_id);
 SELECT coalesce(sum(allocated_amount),0) INTO v_allocated FROM ac_bank_reconciliation_allocations
   WHERE order_id=NEW.order_id AND id IS DISTINCT FROM NEW.id;
 IF v_allocated>=v_limit-0.01 THEN
   RAISE EXCEPTION 'เลขบิล % ถูกจับคู่ครบตามยอดที่อนุมัติแล้ว กรุณายกเลิกคู่เดิมก่อนหากต้องการเปลี่ยนรายการ',v_bill_no;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: tr_guard_manual_slip_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_manual_slip_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_eligibility JSONB;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_eligibility := public.manual_slip_submission_eligibility(NEW.order_id);
    IF COALESCE((v_eligibility->>'allowed')::BOOLEAN, false) = false THEN
      IF v_eligibility->>'reason' = 'exact_trans_ref_duplicate' THEN
        RAISE EXCEPTION 'สลิปนี้ถูกใช้แล้วในบิล % ไม่สามารถส่งตรวจสลิปมือได้', COALESCE(v_eligibility->>'duplicate_bill_no', '-');
      END IF;
      RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว ไม่สามารถส่งตรวจสลิปมือได้';
    END IF;
    NEW.submission_kind := CASE
      WHEN COALESCE((v_eligibility->>'requires_exception_review')::BOOLEAN, false)
        THEN 'duplicate_fallback_review'
      ELSE 'manual'
    END;
  ELSIF OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected')
        AND EXISTS (SELECT 1 FROM public.or_orders o WHERE o.id = NEW.order_id AND o.status = 'ยกเลิก') THEN
    RAISE EXCEPTION 'บิลถูกยกเลิกแล้ว ไม่สามารถอนุมัติหรือปฏิเสธได้';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_guard_shipped_order_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_shipped_order_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.shipped_time IS NOT NULL AND NEW.status = 'เสร็จสิ้น' THEN
    NEW.status := 'จัดส่งแล้ว';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tr_guard_shipping_until_wms_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_shipping_until_wms_ready() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status='จัดส่งแล้ว'
     AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.work_order_id IS NOT NULL
     AND NOT public.fn_wms_order_ready_for_packing(NEW.id) THEN
    RAISE EXCEPTION 'จัดส่งไม่ได้: บิล % ยังไม่ได้หยิบและตรวจสินค้าใน WMS ครบ',
      COALESCE(NULLIF(BTRIM(NEW.bill_no),''),NEW.id::TEXT);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tr_guard_shipping_until_wms_ready(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tr_guard_shipping_until_wms_ready() IS 'Blocks every shipping path, including direct updates, while Picker-required order lines are not WMS correct.';


--
-- Name: tr_guard_single_bank_transaction_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_guard_single_bank_transaction_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.ac_bank_reconciliation_allocations existing
    WHERE existing.transaction_id = NEW.transaction_id
      AND existing.id <> NEW.id
  ) THEN
    RAISE EXCEPTION 'รายการเงินเข้าใน Statement นี้ถูกจับคู่กับบิลอื่นแล้ว';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_inv_sample_items_single_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_inv_sample_items_single_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.inv_sample_items
    WHERE sample_id = NEW.sample_id AND id IS DISTINCT FROM NEW.id
  ) THEN
    RAISE EXCEPTION 'สินค้าตัวอย่างหนึ่งใบรับสามารถมีได้เพียง 1 รายการ';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tr_normalize_delivery_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_normalize_delivery_key(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT upper(
    replace(replace(replace(replace(
      regexp_replace(coalesce(p_value, ''), '[[:space:]]+', '', 'g'),
      chr(8203), ''), chr(8204), ''), chr(8205), ''), chr(65279), '')
  );
$$;


--
-- Name: tr_or_order_items_sync_pack_plan_on_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_or_order_items_sync_pack_plan_on_scan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wo text;
  v_ts timestamptz;
  v_patch jsonb;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF tr_pack_should_skip_track() THEN
    RETURN NEW;
  END IF;

  -- Only when status transitions to "สแกนแล้ว"
  IF NEW.packing_status IS DISTINCT FROM 'สแกนแล้ว'
     OR OLD.packing_status IS NOT DISTINCT FROM NEW.packing_status THEN
    RETURN NEW;
  END IF;

  SELECT NULLIF(trim(both FROM coalesce(o.work_order_name, '')), '')
    INTO v_wo
  FROM or_orders o
  WHERE o.id = NEW.order_id
  LIMIT 1;
  IF v_wo IS NULL THEN
    RETURN NEW;
  END IF;

  v_ts := COALESCE(NEW.item_scan_time, now());
  v_patch := jsonb_build_object(
    'เริ่มแพ็ค', jsonb_build_object('start_if_null', to_jsonb(v_ts))
  );

  PERFORM merge_plan_tracks_by_name(v_wo, 'PACK', v_patch);
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tr_or_order_items_sync_pack_plan_on_scan(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tr_or_order_items_sync_pack_plan_on_scan() IS 'After or_order_items.packing_status becomes สแกนแล้ว, stamp PACK เริ่มแพ็ค.start on latest plan_jobs row for the related work order (skip admin/superadmin).';


--
-- Name: tr_or_orders_sync_pack_plan_on_parcel_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_or_orders_sync_pack_plan_on_parcel_scan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wo TEXT;
  v_new_scanned BOOLEAN;
  v_old_scanned BOOLEAN;
  v_ts TIMESTAMPTZ;
BEGIN
  v_new_scanned := coalesce((NEW.packing_meta->>'parcelScanned')::boolean, false);
  v_old_scanned := coalesce((OLD.packing_meta->>'parcelScanned')::boolean, false);

  IF NOT v_new_scanned OR v_old_scanned THEN
    RETURN NEW;
  END IF;

  v_wo := nullif(trim(coalesce(NEW.work_order_name, '')), '');
  IF v_wo IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_ts := nullif(NEW.packing_meta->>'scanTime', '')::timestamptz;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
    v_ts := NULL;
  END;

  PERFORM public.merge_plan_tracks_by_name(
    v_wo,
    'PACK',
    jsonb_build_object(
      'เริ่มแพ็ค',
      jsonb_build_object('start_if_null', to_jsonb(coalesce(v_ts, now())))
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tr_or_orders_sync_pack_plan_on_parcel_scan(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tr_or_orders_sync_pack_plan_on_parcel_scan() IS 'After or_orders.packing_meta.parcelScanned becomes true, stamp PACK เริ่มแพ็ค.start on latest plan_jobs row for the related work order (skip admin/superadmin).';


--
-- Name: tr_or_orders_sync_pack_plan_when_wo_shipped(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_or_orders_sync_pack_plan_when_wo_shipped() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wo text;
  v_pending int;
  v_now timestamptz;
  v_patch jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM 'จัดส่งแล้ว'
       OR OLD.status IS NOT DISTINCT FROM NEW.status THEN
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'จัดส่งแล้ว' THEN
      RETURN NEW;
    END IF;
  ELSE
    RETURN NEW;
  END IF;

  v_wo := NULLIF(trim(both FROM coalesce(NEW.work_order_name, '')), '');
  IF v_wo IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT count(*)::int INTO v_pending
  FROM or_orders o
  WHERE o.work_order_name = v_wo
    AND o.status IS DISTINCT FROM 'ยกเลิก'
    AND o.status IS DISTINCT FROM 'จัดส่งแล้ว';

  IF v_pending > 0 THEN
    RETURN NEW;
  END IF;

  v_now := COALESCE(NEW.shipped_time, now());
  v_patch := jsonb_build_object(
    'เริ่มแพ็ค', jsonb_build_object(
      'start_if_null', to_jsonb(v_now),
      'end', to_jsonb(v_now)
    ),
    'เสร็จแล้ว', jsonb_build_object(
      'start_if_null', to_jsonb(v_now),
      'end', to_jsonb(v_now)
    )
  );

  PERFORM merge_plan_tracks_by_name(v_wo, 'PACK', v_patch);

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tr_or_orders_sync_pack_plan_when_wo_shipped(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tr_or_orders_sync_pack_plan_when_wo_shipped() IS 'After a bill becomes จัดส่งแล้ว, if all non-cancelled bills in that work order are shipped, set PACK เริ่มแพ็ค+เสร็จแล้ว on latest plan_jobs row.';


