--
-- Name: tr_qc_sessions_sync_qc_plan_on_close(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_qc_sessions_sync_qc_plan_on_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wo TEXT;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
  v_patch JSONB;
BEGIN
  IF TG_OP <> 'UPDATE' OR OLD.end_time IS NOT NULL OR NEW.end_time IS NULL THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.total_items, 0) <= 0
     OR COALESCE(NEW.pass_count, 0) + COALESCE(NEW.skipped_count, 0) <> NEW.total_items
     OR COALESCE(NEW.fail_count, 0) <> 0 THEN
    RETURN NEW;
  END IF;

  v_wo := NULLIF(trim(COALESCE(NEW.filename, '')), '');
  IF v_wo IS NULL OR v_wo NOT LIKE 'WO-%' THEN RETURN NEW; END IF;
  v_wo := NULLIF(trim(substr(v_wo, 4)), '');
  IF v_wo IS NULL THEN RETURN NEW; END IF;

  v_start := COALESCE(NEW.start_time, now());
  v_end := NEW.end_time;
  v_patch := jsonb_build_object(
    'เริ่มQC', jsonb_build_object('start_if_null', to_jsonb(v_start), 'end', to_jsonb(v_end)),
    'เสร็จแล้ว', jsonb_build_object('start_if_null', to_jsonb(v_start), 'end', to_jsonb(v_end))
  );
  PERFORM public.merge_plan_tracks_by_name(v_wo, 'QC', v_patch);
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tr_qc_sessions_sync_qc_plan_on_close(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tr_qc_sessions_sync_qc_plan_on_close() IS 'After qc_sessions.end_time is set (session closed), stamp QC เริ่มQC+เสร็จแล้ว on latest plan_jobs row for the related work order (filename WO-<name>).';


--
-- Name: tr_qc_sessions_sync_qc_plan_on_create(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_qc_sessions_sync_qc_plan_on_create() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wo text;
  v_start timestamptz;
  v_patch jsonb;
  v_role text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  -- Skip for admin/superadmin (same rule as QC UI).
  -- auth.uid() is available when called via Supabase authenticated clients.
  IF auth.uid() IS NOT NULL THEN
    SELECT u.role INTO v_role
    FROM us_users u
    WHERE u.id = auth.uid()
    LIMIT 1;
    IF v_role IN ('admin', 'superadmin') THEN
      RETURN NEW;
    END IF;
  END IF;

  v_wo := NULLIF(trim(both FROM coalesce(NEW.filename, '')), '');
  IF v_wo IS NULL OR v_wo NOT LIKE 'WO-%' THEN
    RETURN NEW;
  END IF;

  v_wo := substr(v_wo, 4);
  v_wo := NULLIF(trim(both FROM v_wo), '');
  IF v_wo IS NULL THEN
    RETURN NEW;
  END IF;

  v_start := COALESCE(NEW.start_time, now());
  v_patch := jsonb_build_object(
    'เริ่มQC', jsonb_build_object(
      'start_if_null', to_jsonb(v_start)
    )
  );

  PERFORM merge_plan_tracks_by_name(v_wo, 'QC', v_patch);

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tr_qc_sessions_sync_qc_plan_on_create(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tr_qc_sessions_sync_qc_plan_on_create() IS 'After qc_sessions is inserted (filename WO-<name>), set QC เริ่มQC.start on latest plan_jobs row via merge_plan_tracks_by_name, skipping admin/superadmin.';


--
-- Name: tr_sync_bank_rule_classification_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_sync_bank_rule_classification_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 UPDATE public.ac_bank_statement_transactions t
 SET reconciliation_status='unmatched',classification_rule_id=NULL,classification_name=NULL,classified_at=NULL,classified_by=NULL
 WHERE t.classification_rule_id=NEW.id AND t.reconciliation_status='ignored'
 AND (NOT NEW.is_active OR (NEW.bank_setting_id IS NOT NULL AND NEW.bank_setting_id<>t.bank_setting_id)
 OR NOT (NEW.direction='both' OR NEW.direction='credit' AND t.credit_amount>0 OR NEW.direction='debit' AND t.debit_amount>0)
 OR strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(btrim(NEW.match_keyword)))=0)
 AND NOT EXISTS(SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.transaction_id=t.id);
 UPDATE public.ac_bank_statement_transactions SET classification_name=NEW.classification_name
 WHERE classification_rule_id=NEW.id AND reconciliation_status='ignored' AND classification_name IS DISTINCT FROM NEW.classification_name;
 RETURN NEW;
END $$;


--
-- Name: tr_sync_manual_verified_twins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tr_sync_manual_verified_twins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order_id UUID;
BEGIN
  v_order_id := NEW.order_id;

  IF TG_TABLE_NAME = 'ac_manual_slip_checks' THEN
    IF NEW.status = 'approved' THEN
      PERFORM public.bank_sync_manual_verified_twins(v_order_id);
    END IF;
    PERFORM public.bank_relink_allocations_to_verified_slips(v_order_id);
  ELSIF TG_TABLE_NAME = 'ac_verified_slips' THEN
    IF NEW.easyslip_date IS NOT NULL AND NEW.validation_status = 'passed' THEN
      PERFORM public.bank_sync_manual_verified_twins(v_order_id);
      PERFORM public.bank_relink_allocations_to_verified_slips(v_order_id);
    END IF;
  ELSIF TG_TABLE_NAME = 'ac_bank_reconciliation_allocations' THEN
    PERFORM public.bank_sync_manual_verified_twins(v_order_id);
    PERFORM public.bank_relink_allocations_to_verified_slips(v_order_id);
  END IF;

  RETURN NEW;
END;
$$;


