-- Name: trg_capture_wms_cancellation_origin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_capture_wms_cancellation_origin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
    NEW.status_before_cancel := COALESCE(NEW.status_before_cancel, OLD.status);
    NEW.cancelled_at := COALESCE(NEW.cancelled_at, NOW());
    NEW.cancelled_by := COALESCE(NEW.cancelled_by, auth.uid());
  END IF;
  RETURN NEW;
END;
$$;


