    RAISE EXCEPTION 'เฉพาะ superadmin และ admin เท่านั้นที่แก้วันที่เริ่มใช้งานเครื่องได้';
  ELSIF TG_OP = 'UPDATE'
     AND NEW.commissioned_on IS DISTINCT FROM OLD.commissioned_on
     AND NOT public.can_manage_machinery_spares_all() THEN
    RAISE EXCEPTION 'เฉพาะ superadmin และ admin เท่านั้นที่แก้วันที่เริ่มใช้งานเครื่องได้';
  END IF;
  RETURN NEW;
END;
$$;


