--
-- Name: trg_reconcile_order_cancellation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_reconcile_order_cancellation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_work_order_id UUID;
BEGIN
  SELECT o.work_order_id INTO v_work_order_id
  FROM public.or_orders o WHERE o.id = NEW.order_id;
  IF v_work_order_id IS NOT NULL THEN
    PERFORM public.reconcile_work_order_after_cancellation(v_work_order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_reconcile_wms_cancelled_work_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_reconcile_wms_cancelled_work_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_work_order_id UUID;
BEGIN
  v_work_order_id := NEW.work_order_id;
  IF v_work_order_id IS NULL THEN
    SELECT id INTO v_work_order_id
    FROM public.or_work_orders
    WHERE BTRIM(work_order_name) = BTRIM(COALESCE(NEW.order_id, ''))
    ORDER BY created_at DESC LIMIT 1;
  END IF;
  IF v_work_order_id IS NOT NULL THEN
    PERFORM public.reconcile_work_order_after_cancellation(v_work_order_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_stamp_voided_plan_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_stamp_voided_plan_job() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_voided_at TIMESTAMPTZ;
  v_dept TEXT;
  v_has_started BOOLEAN;
BEGIN
  IF NEW.is_production_voided = TRUE
     AND COALESCE(OLD.is_production_voided, FALSE) = FALSE THEN
    v_voided_at := COALESCE(NEW.production_voided_at, NOW());
    NEW.production_voided_at := v_voided_at;
    NEW.tracks := COALESCE(NEW.tracks, '{}'::JSONB);

    FOREACH v_dept IN ARRAY ARRAY['QC', 'PACK'] LOOP
      SELECT EXISTS (
        SELECT 1
        FROM jsonb_each(COALESCE(NEW.tracks -> v_dept, '{}'::JSONB)) AS step
        WHERE NULLIF(step.value ->> 'start', '') IS NOT NULL
      ) INTO v_has_started;

      IF v_has_started THEN
        NEW.tracks := jsonb_set(
          NEW.tracks,
          ARRAY[v_dept, 'ยกเลิก'],
          jsonb_build_object('start', NULL, 'end', to_jsonb(v_voided_at)),
          TRUE
        );
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


