--
-- Name: trg_sync_location_stock_from_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_sync_location_stock_from_balance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_previous_on_hand NUMERIC := 0;
  v_delta NUMERIC;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_previous_on_hand := COALESCE(OLD.on_hand, 0);
  END IF;

  v_delta := COALESCE(NEW.on_hand, 0) - v_previous_on_hand;
  IF v_delta <> 0 THEN
    PERFORM public.fn_apply_location_stock_delta(NEW.product_id, v_delta);
  END IF;
  RETURN NEW;
END;
$$;


