--
-- Name: trg_sync_plan_pick_end_after_wms_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_sync_plan_pick_end_after_wms_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.work_order_id IS NOT NULL
     AND NEW.status IN ('correct', 'wrong', 'not_find', 'out_of_stock', 'returned')
     AND (
       NEW.fulfillment_mode = 'warehouse_pick'
       OR NEW.fulfillment_mode IS NULL
     ) THEN
    PERFORM public.fn_sync_plan_pick_end_from_wms(NEW.work_order_id, NOW());
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_wms_promote_system_complete_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_wms_promote_system_complete_pending() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.fulfillment_mode = 'system_complete'
     AND NEW.status = 'pending'
  THEN
    UPDATE wms_orders
    SET status = 'correct'
    WHERE id = NEW.id
      AND status = 'pending';
  END IF;
  RETURN NEW;
END;
$$;


