--
-- Name: ac_v_ecommerce_marketplace_bill_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ac_v_ecommerce_marketplace_bill_reconciliation WITH (security_invoker='true') AS
 WITH wallet AS (
         SELECT ac_ecommerce_wallet_transactions.channel_id,
            ac_ecommerce_wallet_transactions.order_no,
            sum(ac_ecommerce_wallet_transactions.amount) AS wallet_amount,
            max(ac_ecommerce_wallet_transactions.transaction_at) AS wallet_received_at,
            count(*) AS wallet_transaction_count
           FROM public.ac_ecommerce_wallet_transactions
          WHERE (ac_ecommerce_wallet_transactions.order_no IS NOT NULL)
          GROUP BY ac_ecommerce_wallet_transactions.channel_id, ac_ecommerce_wallet_transactions.order_no
        ), line_totals AS (
         SELECT ac_ecommerce_order_lines.order_id,
            count(*) AS line_count,
            sum(ac_ecommerce_order_lines.qty) AS item_qty,
            sum(ac_ecommerce_order_lines.returned_qty) AS returned_qty
           FROM public.ac_ecommerce_order_lines
          GROUP BY ac_ecommerce_order_lines.order_id
        )
 SELECT channel.id AS channel_id,
    channel.code AS channel_code,
    channel.display_name AS channel_name,
    mp.marketplace_order_no AS order_no,
    mp.id AS marketplace_work_id,
    mp.status AS marketplace_status,
    mp.order_total AS marketplace_order_total,
    mp.billed_at AS marketplace_billed_at,
    o.id AS ecommerce_order_id,
    o.platform_status,
        CASE
            WHEN (o.id IS NULL) THEN 'not_found'::text
            ELSE COALESCE(o.delivery_status, 'other'::text)
        END AS delivery_status,
    o.refund_status,
    o.buyer_username,
    COALESCE(o.ordered_at, mp.order_date) AS ordered_at,
    o.paid_at,
    o.shipped_at,
    o.completed_at,
    COALESCE(o.tracking_no, mp.tracking_no) AS tracking_no,
    o.buyer_paid,
    o.merchandise_total,
    COALESCE(o.order_total, mp.order_total, erp.total_amount) AS order_total,
    o.province,
    COALESCE(lines.line_count, (0)::bigint) AS line_count,
    COALESCE(lines.item_qty, (0)::numeric) AS item_qty,
    COALESCE(lines.returned_qty, (0)::numeric) AS returned_qty,
    s.settled_at,
    s.gross_sales,
    s.platform_fee_total,
    s.seller_cost_total,
    s.fee_category_count,
    s.payout_amount,
    s.fee_breakdown,
    wallet.wallet_amount,
    wallet.wallet_received_at,
    erp.id AS erp_order_id,
    COALESCE(erp.bill_no, mp.billed_bill_no) AS erp_bill_no,
    erp.total_amount AS erp_order_total,
    (o.id IS NOT NULL) AS order_matched,
    (s.id IS NOT NULL) AS income_matched,
    (wallet.order_no IS NOT NULL) AS balance_matched,
        CASE
            WHEN erp.has_parcel_return THEN 'parcel_returned'::text
            WHEN (correction.manual_status IS NOT NULL) THEN correction.manual_status
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'cancelled'::text) THEN 'cancelled'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'returned'::text) THEN 'returned'::text
            WHEN ((s.id IS NOT NULL) AND (s.payout_amount = (0)::numeric) AND (COALESCE(wallet.wallet_amount, (0)::numeric) = (0)::numeric)) THEN 'paid_zero'::text
            WHEN ((s.id IS NOT NULL) AND (wallet.order_no IS NOT NULL) AND (abs((s.payout_amount - wallet.wallet_amount)) <= 0.02)) THEN 'paid'::text
            WHEN ((s.id IS NOT NULL) AND (wallet.order_no IS NOT NULL)) THEN 'amount_mismatch'::text
            WHEN (s.id IS NOT NULL) THEN 'waiting_wallet'::text
            WHEN (o.id IS NULL) THEN 'not_found_order'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'delivered'::text) THEN 'waiting_settlement'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'shipping'::text) THEN 'in_transit'::text
            ELSE 'waiting_delivery'::text
        END AS reconciliation_status,
        CASE
            WHEN (s.id IS NULL) THEN NULL::numeric
            ELSE (s.payout_amount - COALESCE(wallet.wallet_amount, (0)::numeric))
        END AS payout_variance,
    correction.manual_status,
    correction.note AS manual_note,
    correction.updated_at AS manual_updated_at
   FROM ((((((((public.mp_orders mp
     JOIN public.mp_channel_configs config ON ((config.id = mp.config_id)))
     JOIN public.ac_ecommerce_channels channel ON ((channel.id = config.ecommerce_channel_id)))
     LEFT JOIN public.ac_ecommerce_orders o ON (((o.channel_id = channel.id) AND (lower(btrim(o.order_no)) = lower(btrim(mp.marketplace_order_no))))))
     LEFT JOIN line_totals lines ON ((lines.order_id = o.id)))
     LEFT JOIN public.ac_ecommerce_settlements s ON (((s.channel_id = channel.id) AND (lower(btrim(s.order_no)) = lower(btrim(mp.marketplace_order_no))))))
     LEFT JOIN wallet ON (((wallet.channel_id = channel.id) AND (lower(btrim(wallet.order_no)) = lower(btrim(mp.marketplace_order_no))))))
     LEFT JOIN public.ac_ecommerce_reconciliation_overrides correction ON (((correction.channel_id = channel.id) AND (lower(btrim(correction.order_no)) = lower(btrim(mp.marketplace_order_no))))))
     LEFT JOIN LATERAL ( SELECT orders.id,
            orders.bill_no,
            orders.total_amount,
            orders.has_parcel_return
           FROM public.or_orders orders
          WHERE ((orders.id = mp.billed_order_id) OR ((mp.billed_order_id IS NULL) AND (orders.bill_no = mp.billed_bill_no)))
          ORDER BY (orders.id = mp.billed_order_id) DESC, orders.created_at DESC
         LIMIT 1) erp ON (true))
  WHERE (mp.is_current AND (mp.status <> 'cancelled'::text) AND ((mp.billed_order_id IS NOT NULL) OR (mp.billed_bill_no IS NOT NULL)));


--
-- Name: VIEW ac_v_ecommerce_marketplace_bill_reconciliation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.ac_v_ecommerce_marketplace_bill_reconciliation IS 'Current non-cancelled ERP bill opened from Marketplace, with optional order, income and balance matches; superseded imports remain in mp_orders for audit.';


--
-- Name: ac_v_ecommerce_order_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ac_v_ecommerce_order_reconciliation WITH (security_invoker='true') AS
 WITH order_keys AS (
         SELECT ac_ecommerce_orders.channel_id,
            ac_ecommerce_orders.order_no
           FROM public.ac_ecommerce_orders
        UNION
         SELECT ac_ecommerce_settlements.channel_id,
            ac_ecommerce_settlements.order_no
           FROM public.ac_ecommerce_settlements
        UNION
         SELECT ac_ecommerce_wallet_transactions.channel_id,
            ac_ecommerce_wallet_transactions.order_no
           FROM public.ac_ecommerce_wallet_transactions
          WHERE (ac_ecommerce_wallet_transactions.order_no IS NOT NULL)
        ), wallet AS (
         SELECT ac_ecommerce_wallet_transactions.channel_id,
            ac_ecommerce_wallet_transactions.order_no,
            sum(ac_ecommerce_wallet_transactions.amount) AS wallet_amount,
            max(ac_ecommerce_wallet_transactions.transaction_at) AS wallet_received_at,
            count(*) AS wallet_transaction_count
           FROM public.ac_ecommerce_wallet_transactions
          WHERE (ac_ecommerce_wallet_transactions.order_no IS NOT NULL)
          GROUP BY ac_ecommerce_wallet_transactions.channel_id, ac_ecommerce_wallet_transactions.order_no
        ), line_totals AS (
         SELECT l.order_id,
            count(*) AS line_count,
            sum(l.qty) AS item_qty,
            sum(l.returned_qty) AS returned_qty
           FROM public.ac_ecommerce_order_lines l
          GROUP BY l.order_id
        )
 SELECT k.channel_id,
    c.code AS channel_code,
    c.display_name AS channel_name,
    k.order_no,
    o.id AS ecommerce_order_id,
    o.platform_status,
    COALESCE(o.delivery_status, 'other'::text) AS delivery_status,
    o.refund_status,
    o.buyer_username,
    COALESCE(o.ordered_at, s.ordered_at) AS ordered_at,
    o.paid_at,
    o.shipped_at,
    o.completed_at,
    o.tracking_no,
    o.buyer_paid,
    o.merchandise_total,
    o.order_total,
    o.estimated_commission,
    o.estimated_transaction_fee,
    o.estimated_service_fee,
    o.estimated_shipping_cost,
    o.province,
    o.district,
    o.postal_code,
    COALESCE(lt.line_count, (0)::bigint) AS line_count,
    COALESCE(lt.item_qty, (0)::numeric) AS item_qty,
    COALESCE(lt.returned_qty, (0)::numeric) AS returned_qty,
    s.settled_at,
    s.gross_sales,
    s.seller_discounts,
    s.refunds,
    s.shipping_net,
    s.platform_fee_total,
    s.seller_cost_total,
    s.fee_category_count,
    s.payout_amount,
    s.fee_breakdown,
    w.wallet_amount,
    w.wallet_received_at,
    COALESCE(w.wallet_transaction_count, (0)::bigint) AS wallet_transaction_count,
    erp.id AS erp_order_id,
    erp.bill_no AS erp_bill_no,
    erp.status AS erp_order_status,
    erp.total_amount AS erp_order_total,
        CASE
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'cancelled'::text) THEN 'cancelled'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'returned'::text) THEN 'returned'::text
            WHEN ((s.id IS NOT NULL) AND (s.payout_amount = (0)::numeric) AND (COALESCE(w.wallet_amount, (0)::numeric) = (0)::numeric)) THEN 'paid_zero'::text
            WHEN ((s.id IS NOT NULL) AND (w.order_no IS NOT NULL) AND (abs((s.payout_amount - w.wallet_amount)) <= 0.02)) THEN 'paid'::text
            WHEN ((s.id IS NOT NULL) AND (w.order_no IS NOT NULL)) THEN 'amount_mismatch'::text
            WHEN (s.id IS NOT NULL) THEN 'waiting_wallet'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'delivered'::text) THEN 'waiting_settlement'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'shipping'::text) THEN 'in_transit'::text
            ELSE 'needs_review'::text
        END AS reconciliation_status,
        CASE
            WHEN (s.id IS NULL) THEN NULL::numeric
            ELSE (s.payout_amount - COALESCE(w.wallet_amount, (0)::numeric))
        END AS payout_variance
   FROM ((((((order_keys k
     JOIN public.ac_ecommerce_channels c ON ((c.id = k.channel_id)))
     LEFT JOIN public.ac_ecommerce_orders o ON (((o.channel_id = k.channel_id) AND (o.order_no = k.order_no))))
     LEFT JOIN line_totals lt ON ((lt.order_id = o.id)))
     LEFT JOIN public.ac_ecommerce_settlements s ON (((s.channel_id = k.channel_id) AND (s.order_no = k.order_no))))
     LEFT JOIN wallet w ON (((w.channel_id = k.channel_id) AND (w.order_no = k.order_no))))
     LEFT JOIN LATERAL ( SELECT oo.id,
            oo.bill_no,
            oo.status,
            oo.total_amount
           FROM public.or_orders oo
          WHERE ((oo.channel_order_no IS NOT NULL) AND (lower(TRIM(BOTH FROM oo.channel_order_no)) = lower(TRIM(BOTH FROM k.order_no))))
          ORDER BY oo.created_at DESC
         LIMIT 1) erp ON (true));


--
-- Name: VIEW ac_v_ecommerce_order_reconciliation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.ac_v_ecommerce_order_reconciliation IS 'One row per platform order, joining delivery, settlement, wallet payout and ERP bill.';


--
-- Name: ac_v_ecommerce_order_reconciliation_core; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ac_v_ecommerce_order_reconciliation_core WITH (security_invoker='true') AS
 WITH order_keys AS (
         SELECT ac_ecommerce_orders.channel_id,
            ac_ecommerce_orders.order_no
           FROM public.ac_ecommerce_orders
        UNION
         SELECT ac_ecommerce_settlements.channel_id,
            ac_ecommerce_settlements.order_no
           FROM public.ac_ecommerce_settlements
        UNION
         SELECT ac_ecommerce_wallet_transactions.channel_id,
            ac_ecommerce_wallet_transactions.order_no
           FROM public.ac_ecommerce_wallet_transactions
          WHERE (ac_ecommerce_wallet_transactions.order_no IS NOT NULL)
        ), wallet AS (
         SELECT ac_ecommerce_wallet_transactions.channel_id,
            ac_ecommerce_wallet_transactions.order_no,
            sum(ac_ecommerce_wallet_transactions.amount) AS wallet_amount,
            max(ac_ecommerce_wallet_transactions.transaction_at) AS wallet_received_at,
            count(*) AS wallet_transaction_count
           FROM public.ac_ecommerce_wallet_transactions
          WHERE (ac_ecommerce_wallet_transactions.order_no IS NOT NULL)
          GROUP BY ac_ecommerce_wallet_transactions.channel_id, ac_ecommerce_wallet_transactions.order_no
        ), line_totals AS (
         SELECT ac_ecommerce_order_lines.order_id,
            count(*) AS line_count,
            sum(ac_ecommerce_order_lines.qty) AS item_qty,
            sum(ac_ecommerce_order_lines.returned_qty) AS returned_qty
           FROM public.ac_ecommerce_order_lines
          GROUP BY ac_ecommerce_order_lines.order_id
        )
 SELECT k.channel_id,
    c.code AS channel_code,
    c.display_name AS channel_name,
    k.order_no,
    o.id AS ecommerce_order_id,
    o.platform_status,
    COALESCE(o.delivery_status, 'other'::text) AS delivery_status,
    o.refund_status,
    o.buyer_username,
    COALESCE(o.ordered_at, s.ordered_at) AS ordered_at,
    o.paid_at,
    o.shipped_at,
    o.completed_at,
    o.tracking_no,
    o.buyer_paid,
    o.merchandise_total,
    o.order_total,
    o.province,
    COALESCE(lt.line_count, (0)::bigint) AS line_count,
    COALESCE(lt.item_qty, (0)::numeric) AS item_qty,
    COALESCE(lt.returned_qty, (0)::numeric) AS returned_qty,
    s.settled_at,
    s.gross_sales,
    s.platform_fee_total,
    s.seller_cost_total,
    s.fee_category_count,
    s.payout_amount,
    s.fee_breakdown,
    w.wallet_amount,
    w.wallet_received_at,
        CASE
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'cancelled'::text) THEN 'cancelled'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'returned'::text) THEN 'returned'::text
            WHEN ((s.id IS NOT NULL) AND (s.payout_amount = (0)::numeric) AND (COALESCE(w.wallet_amount, (0)::numeric) = (0)::numeric)) THEN 'paid_zero'::text
            WHEN ((s.id IS NOT NULL) AND (w.order_no IS NOT NULL) AND (abs((s.payout_amount - w.wallet_amount)) <= 0.02)) THEN 'paid'::text
            WHEN ((s.id IS NOT NULL) AND (w.order_no IS NOT NULL)) THEN 'amount_mismatch'::text
            WHEN (s.id IS NOT NULL) THEN 'waiting_wallet'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'delivered'::text) THEN 'waiting_settlement'::text
            WHEN (COALESCE(o.delivery_status, 'other'::text) = 'shipping'::text) THEN 'in_transit'::text
            ELSE 'needs_review'::text
        END AS reconciliation_status,
        CASE
            WHEN (s.id IS NULL) THEN NULL::numeric
            ELSE (s.payout_amount - COALESCE(w.wallet_amount, (0)::numeric))
        END AS payout_variance
   FROM (((((order_keys k
     JOIN public.ac_ecommerce_channels c ON ((c.id = k.channel_id)))
     LEFT JOIN public.ac_ecommerce_orders o ON (((o.channel_id = k.channel_id) AND (o.order_no = k.order_no))))
     LEFT JOIN line_totals lt ON ((lt.order_id = o.id)))
     LEFT JOIN public.ac_ecommerce_settlements s ON (((s.channel_id = k.channel_id) AND (s.order_no = k.order_no))))
     LEFT JOIN wallet w ON (((w.channel_id = k.channel_id) AND (w.order_no = k.order_no))));


