--
-- Name: ac_v_ecommerce_sale_lines_enriched; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ac_v_ecommerce_sale_lines_enriched AS
 SELECT sl.id,
    sl.batch_id,
    sl.row_index,
    sl.order_no,
    sl.payment_at,
    sl.sku_ref,
    sl.price_orig,
    sl.price_sell,
    sl.qty,
    sl.line_total,
    sl.commission,
    sl.transaction_fee,
    sl.platform_fees_plus1,
    sl.buyer_note,
    sl.province,
    sl.district,
    sl.postal_code,
    sl.created_at,
    b.channel_id,
    b.file_name,
    b.uploaded_at,
    c.code AS channel_code,
    c.display_name AS channel_name,
    p.product_name AS product_name_from_sku,
    o.id AS erp_order_id,
    o.bill_no AS erp_bill_no,
    o.status AS erp_order_status,
    o.total_amount AS erp_order_total,
    COALESCE(oi_match.erp_line_amount, (0)::numeric) AS erp_line_amount_for_sku,
    (o.id IS NOT NULL) AS erp_order_found,
    (oi_match.erp_line_amount IS NOT NULL) AS erp_sku_line_found,
        CASE
            WHEN ((sl.line_total IS NULL) OR (oi_match.erp_line_amount IS NULL)) THEN NULL::boolean
            WHEN (abs((COALESCE(sl.line_total, (0)::numeric) - COALESCE(oi_match.erp_line_amount, (0)::numeric))) <= 0.02) THEN true
            ELSE false
        END AS erp_amount_matches_line
   FROM (((((public.ac_ecommerce_sale_lines sl
     JOIN public.ac_ecommerce_import_batches b ON ((b.id = sl.batch_id)))
     JOIN public.ac_ecommerce_channels c ON ((c.id = b.channel_id)))
     LEFT JOIN public.pr_products p ON ((lower(TRIM(BOTH FROM p.product_code)) = lower(NULLIF(TRIM(BOTH FROM sl.sku_ref), ''::text)))))
     LEFT JOIN public.or_orders o ON (((o.channel_order_no IS NOT NULL) AND (sl.order_no IS NOT NULL) AND (lower(TRIM(BOTH FROM o.channel_order_no)) = lower(TRIM(BOTH FROM sl.order_no))))))
     LEFT JOIN LATERAL ( SELECT sum(((COALESCE(oi.quantity, 0))::numeric * COALESCE(oi.unit_price, (0)::numeric))) AS erp_line_amount
           FROM (public.or_order_items oi
             JOIN public.pr_products pr ON ((pr.id = oi.product_id)))
          WHERE ((oi.order_id = o.id) AND (sl.sku_ref IS NOT NULL) AND (lower(TRIM(BOTH FROM pr.product_code)) = lower(TRIM(BOTH FROM sl.sku_ref))))) oi_match ON (true));


--
-- Name: VIEW ac_v_ecommerce_sale_lines_enriched; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.ac_v_ecommerce_sale_lines_enriched IS 'Ecommerce import lines with ERP reconcile hints; filter payment_at / channel_id in query.';


