    status text DEFAULT 'draft'::text NOT NULL,
    requested_by uuid,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    backup_started_at timestamp with time zone,
    backup_verified_at timestamp with time zone,
    reset_started_at timestamp with time zone,
    reset_completed_at timestamp with time zone,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text,
    CONSTRAINT erp_data_operations_operation_type_check CHECK ((operation_type = ANY (ARRAY['annual_close'::text, 'reset_only'::text, 'backup_only'::text, 'go_live_reset'::text]))),
    CONSTRAINT erp_data_operations_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'previewed'::text, 'backup_running'::text, 'backup_verified'::text, 'reset_running'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT erp_data_operations_stock_strategy_check CHECK ((stock_strategy = ANY (ARRAY['opening'::text, 'zero'::text])))
);


