    category text,
    description text,
    department_id uuid,
    location text,
    purchase_date date,
    purchase_cost numeric(14,2),
    current_value numeric(14,2),
    status text DEFAULT 'active'::text NOT NULL,
    assigned_employee_id uuid,
    images jsonb DEFAULT '[]'::jsonb NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    serial_number text,
    sub_type text,
    vendor_name text,
    received_date date,
    warranty_expire_date date,
    useful_life_years numeric(6,2),
    depreciation_per_year numeric(14,2),
    has_warranty boolean DEFAULT false NOT NULL,
    warranty_period integer,
    warranty_unit text,
    documents jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT hr_assets_status_check CHECK ((status = ANY (ARRAY['active'::text, 'borrowed'::text, 'maintenance'::text, 'retired'::text, 'disposed'::text, 'lost'::text]))),
    CONSTRAINT hr_assets_warranty_unit_check CHECK (((warranty_unit IS NULL) OR (warranty_unit = ANY (ARRAY['day'::text, 'year'::text]))))
);


--
-- Name: COLUMN hr_assets.current_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.current_value IS 'มูลค่าปัจจุบัน = มูลค่าตอนซื้อ − (ค่าเสื่อม/ปี × ปีที่ใช้งานไปแล้ว) ไม่ต่ำกว่า 0';


--
-- Name: COLUMN hr_assets.serial_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.serial_number IS 'S/N ของทรัพย์สิน';


--
-- Name: COLUMN hr_assets.sub_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.sub_type IS 'ประเภทย่อย เช่น Notebook, Printer, Monitor';


--
-- Name: COLUMN hr_assets.vendor_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.vendor_name IS 'ชื่อผู้ขาย';


--
-- Name: COLUMN hr_assets.received_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.received_date IS 'วันที่รับเข้า';


--
-- Name: COLUMN hr_assets.warranty_expire_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.warranty_expire_date IS 'วันหมดประกัน — คำนวณจากวันที่ซื้อ + ระยะประกัน';


--
-- Name: COLUMN hr_assets.useful_life_years; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.useful_life_years IS 'อายุการใช้งาน (ปี) — ใช้คำนวณค่าเสื่อม/ปี';


--
-- Name: COLUMN hr_assets.depreciation_per_year; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.depreciation_per_year IS 'ค่าเสื่อมราคาต่อปี = มูลค่าตอนซื้อ ÷ อายุการใช้งาน';


--
-- Name: COLUMN hr_assets.has_warranty; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.has_warranty IS 'มีการรับประกันหรือไม่ — false = วันหมดประกันเท่ากับวันที่ซื้อ';


--
-- Name: COLUMN hr_assets.warranty_period; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_assets.warranty_period IS 'ระยะเวลารับประกัน (จำนวน) ใช้คู่กับ warranty_unit';


--
-- Name: COLUMN hr_assets.warranty_unit; Type: COMMENT; Schema: public; Owner: -
