--
-- Name: hr_employee_opening_attendance; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_employee_opening_attendance (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    year integer NOT NULL,
    effective_date date NOT NULL,
    absence_days numeric(6,2) DEFAULT 0 NOT NULL,
    late_count integer DEFAULT 0 NOT NULL,
    late_minutes integer DEFAULT 0 NOT NULL,
    early_leave_count integer DEFAULT 0 NOT NULL,
    early_leave_minutes integer DEFAULT 0 NOT NULL,
    note text,
    updated_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_employee_opening_attendance_absence_days_check CHECK ((absence_days >= (0)::numeric)),
    CONSTRAINT hr_employee_opening_attendance_check CHECK ((EXTRACT(year FROM effective_date) = (year)::numeric)),
    CONSTRAINT hr_employee_opening_attendance_early_leave_count_check CHECK ((early_leave_count >= 0)),
    CONSTRAINT hr_employee_opening_attendance_early_leave_minutes_check CHECK ((early_leave_minutes >= 0)),
    CONSTRAINT hr_employee_opening_attendance_late_count_check CHECK ((late_count >= 0)),
    CONSTRAINT hr_employee_opening_attendance_late_minutes_check CHECK ((late_minutes >= 0)),
    CONSTRAINT hr_employee_opening_attendance_year_check CHECK (((year >= 2000) AND (year <= 2200)))
);


