    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_employee_opening_leave_balances_check CHECK ((EXTRACT(year FROM effective_date) = (year)::numeric)),
    CONSTRAINT hr_employee_opening_leave_balances_opening_remaining_days_check CHECK ((opening_remaining_days >= (0)::numeric)),
    CONSTRAINT hr_employee_opening_leave_balances_year_check CHECK (((year >= 2000) AND (year <= 2200)))
);


