-- Name: hr_employees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_employees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_code text NOT NULL,
    citizen_id text,
    prefix text,
    first_name text NOT NULL,
    last_name text NOT NULL,
    first_name_en text,
    last_name_en text,
    nickname text,
    birth_date date,
    gender text,
    religion text,
    address jsonb,
    current_address jsonb,
    phone text,
    emergency_contact jsonb,
    photo_url text,
    department_id uuid,
    position_id uuid,
    salary numeric(12,2),
    hire_date date,
    probation_end_date date,
    employment_status text DEFAULT 'active'::text,
    user_id uuid,
    telegram_chat_id text,
    documents jsonb DEFAULT '[]'::jsonb,
    card_issue_date date,
    card_expiry_date date,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    contract_type text DEFAULT 'permanent'::text NOT NULL,
    clock_location_id uuid,
    work_schedule_id uuid,
    nationality text,
    position_allowance numeric(12,2),
    work_mode text DEFAULT 'office'::text NOT NULL,
    company_id uuid,
    monthly_personal_tax numeric(12,2) DEFAULT 0 NOT NULL,
    monthly_social_security numeric(12,2) DEFAULT 0 NOT NULL,
    monthly_student_loan numeric(12,2) DEFAULT 0 NOT NULL,
    monthly_company_loan numeric(12,2) DEFAULT 0 NOT NULL,
    monthly_savings numeric(12,2) DEFAULT 0 NOT NULL,
    savings_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    company_loan_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    company_loan_opening_installments integer DEFAULT 0 NOT NULL,
    income_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    personal_tax_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    student_loan_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    social_security_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    contract_end_date date,
    savings_maximum numeric(12,2),
    ewf_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    social_security_enabled boolean DEFAULT false NOT NULL,
    social_security_start_date date,
    compensation_effective_date date,
    pay_schedule_id uuid,
    pay_schedule_effective_date date,
    CONSTRAINT hr_employees_company_loan_opening_balance_check CHECK ((company_loan_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_company_loan_opening_installments_check CHECK ((company_loan_opening_installments >= 0)),
    CONSTRAINT hr_employees_contract_type_check CHECK ((contract_type = ANY (ARRAY['permanent'::text, 'daily'::text]))),
    CONSTRAINT hr_employees_ewf_opening_balance_check CHECK ((ewf_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_income_opening_balance_check CHECK ((income_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_monthly_company_loan_check CHECK ((monthly_company_loan >= (0)::numeric)),
    CONSTRAINT hr_employees_monthly_personal_tax_check CHECK ((monthly_personal_tax >= (0)::numeric)),
    CONSTRAINT hr_employees_monthly_savings_check CHECK ((monthly_savings >= (0)::numeric)),
    CONSTRAINT hr_employees_monthly_social_security_check CHECK ((monthly_social_security >= (0)::numeric)),
    CONSTRAINT hr_employees_monthly_student_loan_check CHECK ((monthly_student_loan >= (0)::numeric)),
    CONSTRAINT hr_employees_personal_tax_opening_balance_check CHECK ((personal_tax_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_savings_maximum_check CHECK (((savings_maximum IS NULL) OR (savings_maximum >= (0)::numeric))),
    CONSTRAINT hr_employees_savings_opening_balance_check CHECK ((savings_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_social_security_opening_balance_nonnegative CHECK ((social_security_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_student_loan_opening_balance_check CHECK ((student_loan_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_employees_work_mode_check CHECK ((work_mode = ANY (ARRAY['office'::text, 'hybrid'::text, 'wfh'::text, 'no_clock'::text])))
);


--
-- Name: COLUMN hr_employees.contract_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.contract_type IS 'permanent=ประจำ, daily=รายวัน';


--
-- Name: COLUMN hr_employees.work_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.work_mode IS 'office=เข้าออฟฟิศ, hybrid=เข้าออฟฟิศและขอ WFH ได้, wfh=WFH ประจำ, no_clock=ไม่ต้องบันทึกเวลาเข้าออก';


--
-- Name: COLUMN hr_employees.contract_end_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.contract_end_date IS 'วันที่สิ้นสุดสัญญาจ้าง ใช้แจ้งเตือนล่วงหน้า 60 วันและเรียงลำดับอายุสัญญา';


--
-- Name: COLUMN hr_employees.savings_maximum; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.savings_maximum IS 'เพดานยอดเงินสะสมรวม เมื่อถึงเพดานระบบเงินเดือนจะหยุดหัก; NULL = ไม่จำกัด';


--
-- Name: COLUMN hr_employees.ewf_opening_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.ewf_opening_balance IS 'ยอดสะสม EWF ก่อนเริ่มใช้ระบบ';


--
-- Name: COLUMN hr_employees.social_security_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.social_security_enabled IS 'Explicit enrollment switch controlling social security deductions for monthly and daily payroll';


--
-- Name: COLUMN hr_employees.social_security_start_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hr_employees.social_security_start_date IS 'Recorded social security enrollment date; independent of the payroll deduction switch';


