    employee_id uuid NOT NULL,
    payroll_month date NOT NULL,
    excess_days numeric(8,4) DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    note text,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    salary_base numeric(12,2) DEFAULT 0 NOT NULL,
    deduction_amount numeric(12,2) DEFAULT 0 NOT NULL,
    pay_type text DEFAULT 'permanent'::text NOT NULL,
    CONSTRAINT hr_leave_payroll_deductions_deduction_amount_check CHECK ((deduction_amount >= (0)::numeric)),
    CONSTRAINT hr_leave_payroll_deductions_excess_days_check CHECK ((excess_days >= (0)::numeric)),
    CONSTRAINT hr_leave_payroll_deductions_pay_type_check CHECK ((pay_type = ANY (ARRAY['permanent'::text, 'daily'::text]))),
    CONSTRAINT hr_leave_payroll_deductions_payroll_month_check CHECK ((payroll_month = (date_trunc('month'::text, (payroll_month)::timestamp with time zone))::date)),
    CONSTRAINT hr_leave_payroll_deductions_salary_base_check CHECK ((salary_base >= (0)::numeric)),
    CONSTRAINT hr_leave_payroll_deductions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'sent'::text])))
);


