    leave_mode text DEFAULT 'full_day'::text NOT NULL,
    start_time time without time zone,
    end_time time without time zone,
    total_hours numeric(5,2),
    is_emergency boolean DEFAULT false NOT NULL,
    cancelled_by uuid,
    cancelled_by_name text,
    cancelled_at timestamp with time zone,
    CONSTRAINT hr_leave_requests_leave_mode_check CHECK ((leave_mode = ANY (ARRAY['full_day'::text, 'hourly'::text])))
);

ALTER TABLE ONLY public.hr_leave_requests REPLICA IDENTITY FULL;


