    CONSTRAINT hr_ot_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.hr_ot_requests REPLICA IDENTITY FULL;


--
-- Name: hr_pay_schedules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_pay_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    name text NOT NULL,
    frequency text NOT NULL,
    weekday integer DEFAULT 1 NOT NULL,
    first_day integer DEFAULT 15 NOT NULL,
    second_day integer,
    payment_day integer,
    holiday_rule text DEFAULT 'none'::text NOT NULL,
    deduction_policy text DEFAULT 'last'::text NOT NULL,
    cutoff_time time without time zone DEFAULT '18:00:00'::time without time zone NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_pay_schedules_check CHECK (((second_day IS NULL) OR (second_day > first_day))),
    CONSTRAINT hr_pay_schedules_deduction_policy_check CHECK ((deduction_policy = ANY (ARRAY['last'::text, 'proportional'::text]))),
    CONSTRAINT hr_pay_schedules_first_day_check CHECK (((first_day >= 1) AND (first_day <= 27))),
    CONSTRAINT hr_pay_schedules_frequency_check CHECK ((frequency = ANY (ARRAY['daily'::text, 'weekly'::text, 'semimonthly'::text, 'monthly'::text, 'custom'::text]))),
    CONSTRAINT hr_pay_schedules_holiday_rule_check CHECK ((holiday_rule = ANY (ARRAY['none'::text, 'previous'::text, 'next'::text]))),
    CONSTRAINT hr_pay_schedules_name_check CHECK ((length(TRIM(BOTH FROM name)) > 0)),
    CONSTRAINT hr_pay_schedules_payment_day_check CHECK (((payment_day >= 1) AND (payment_day <= 31))),
    CONSTRAINT hr_pay_schedules_second_day_check CHECK (((second_day >= 16) AND (second_day <= 31))),
    CONSTRAINT hr_pay_schedules_weekday_check CHECK (((weekday >= 1) AND (weekday <= 7)))
);


--
-- Name: hr_payroll_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_payroll_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payroll_run_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    employee_code text NOT NULL,
    employee_name text NOT NULL,
    department_position text,
    base_salary numeric(12,2) DEFAULT 0 NOT NULL,
    position_allowance numeric(12,2) DEFAULT 0 NOT NULL,
    personal_tax numeric(12,2) DEFAULT 0 NOT NULL,
    social_security numeric(12,2) DEFAULT 0 NOT NULL,
    student_loan numeric(12,2) DEFAULT 0 NOT NULL,
    company_loan numeric(12,2) DEFAULT 0 NOT NULL,
    leave_deduction numeric(12,2) DEFAULT 0 NOT NULL,
    other_income numeric(12,2) DEFAULT 0 NOT NULL,
    other_deduction numeric(12,2) DEFAULT 0 NOT NULL,
    company_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    savings numeric(12,2) DEFAULT 0 NOT NULL,
    savings_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    company_loan_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    company_loan_opening_installments integer DEFAULT 0 NOT NULL,
    income_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    personal_tax_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    student_loan_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    employee_nickname text,
    social_security_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    ewf numeric(12,2) DEFAULT 0 NOT NULL,
    ewf_opening_balance numeric(12,2) DEFAULT 0 NOT NULL,
    total_deduction numeric(12,2) GENERATED ALWAYS AS ((((((((personal_tax + social_security) + ewf) + savings) + student_loan) + company_loan) + leave_deduction) + other_deduction)) STORED,
    ot_normal_hours numeric(8,2) DEFAULT 0 NOT NULL,
    ot_holiday_hours numeric(8,2) DEFAULT 0 NOT NULL,
    overtime_pay numeric(12,2) DEFAULT 0 NOT NULL,
    gross_income numeric(12,2) GENERATED ALWAYS AS ((((base_salary + position_allowance) + overtime_pay) + other_income)) STORED,
    net_pay numeric(12,2) GENERATED ALWAYS AS (((((base_salary + position_allowance) + overtime_pay) + other_income) - (((((((personal_tax + social_security) + ewf) + savings) + student_loan) + company_loan) + leave_deduction) + other_deduction))) STORED,
    pay_type text DEFAULT 'permanent'::text NOT NULL,
    daily_rate numeric(12,2) DEFAULT 0 NOT NULL,
    full_days numeric(6,2) DEFAULT 0 NOT NULL,
    half_days numeric(6,2) DEFAULT 0 NOT NULL,
    paid_holiday_days numeric(6,2) DEFAULT 0 NOT NULL,
    unpaid_leave_days numeric(6,2) DEFAULT 0 NOT NULL,
    payable_days numeric(6,2) DEFAULT 0 NOT NULL,
    unresolved_attendance_days integer DEFAULT 0 NOT NULL,
    daily_wage_details jsonb DEFAULT '[]'::jsonb NOT NULL,
    social_security_enabled boolean,
    monthly_rate numeric(12,2),
    monthly_payable_days numeric(6,2),
    monthly_wage_details jsonb,
    earning_dates date[],
    deduction_allocations jsonb,
    CONSTRAINT hr_payroll_items_company_loan_opening_balance_check CHECK ((company_loan_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_company_loan_opening_installments_check CHECK ((company_loan_opening_installments >= 0)),
    CONSTRAINT hr_payroll_items_daily_rate_check CHECK ((daily_rate >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_ewf_check CHECK ((ewf >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_ewf_opening_balance_check CHECK ((ewf_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_full_days_check CHECK ((full_days >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_half_days_check CHECK ((half_days >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_income_opening_balance_check CHECK ((income_opening_balance >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_ot_holiday_hours_check CHECK ((ot_holiday_hours >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_ot_normal_hours_check CHECK ((ot_normal_hours >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_overtime_pay_check CHECK ((overtime_pay >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_paid_holiday_days_check CHECK ((paid_holiday_days >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_pay_type_check CHECK ((pay_type = ANY (ARRAY['permanent'::text, 'daily'::text]))),
    CONSTRAINT hr_payroll_items_payable_days_check CHECK ((payable_days >= (0)::numeric)),
