-- Name: hr_payroll_monthly_allocations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_payroll_monthly_allocations (
    payroll_item_id uuid NOT NULL,
    payroll_run_id uuid NOT NULL,
    company_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    earning_month date NOT NULL,
    amounts jsonb NOT NULL
);


--
-- Name: hr_payroll_effective_monthly_allocations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hr_payroll_effective_monthly_allocations WITH (security_invoker='true') AS
 SELECT a.payroll_item_id,
    a.payroll_run_id,
    a.company_id,
    a.employee_id,
    a.earning_month,
    a.amounts,
    (((a.payroll_item_id)::text || ':'::text) || (a.earning_month)::text) AS allocation_key
   FROM public.hr_payroll_monthly_allocations a
UNION ALL
 SELECT a.source_item_id AS payroll_item_id,
    i.payroll_run_id,
    a.company_id,
    a.employee_id,
    ((m.key || '-01'::text))::date AS earning_month,
    m.value AS amounts,
    ((('adjustment:'::text || (a.id)::text) || ':'::text) || m.key) AS allocation_key
   FROM ((public.hr_payroll_adjustments a
     JOIN public.hr_payroll_items i ON ((i.id = a.source_item_id)))
     CROSS JOIN LATERAL jsonb_each(a.deduction_allocations) m(key, value))
  WHERE (a.status = 'approved'::text);


