--
-- Name: v_cost_safe_inv_po; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cost_safe_inv_po WITH (security_barrier='true') AS
 SELECT id,
    po_no,
    pr_id,
    status,
    ordered_by,
    ordered_at,
    note,
    created_at,
    updated_at,
    supplier_id,
    supplier_name,
    intl_shipping_method,
    intl_shipping_weight,
    intl_shipping_cbm,
    intl_shipping_cost,
    intl_shipping_currency,
    intl_exchange_rate,
    intl_shipping_cost_thb,
        CASE
            WHEN public.erp_can_view_cost() THEN total_amount
            ELSE NULL::numeric
        END AS total_amount,
        CASE
            WHEN public.erp_can_view_cost() THEN grand_total
            ELSE NULL::numeric
        END AS grand_total,
    created_by,
    expected_arrival_date,
    tracking_number,
    shipment_entries,
    receiving_note
   FROM public.inv_po
  WHERE ((auth.role() = 'authenticated'::text) AND ((auth.role() = 'authenticated'::text) OR (EXISTS ( SELECT 1
           FROM public.us_users
          WHERE ((us_users.id = auth.uid()) AND (us_users.role = ANY (ARRAY['superadmin'::text, 'admin'::text, 'account'::text, 'manager'::text])))))) AND true);


--
-- Name: v_cost_safe_inv_po_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cost_safe_inv_po_items WITH (security_barrier='true') AS
 SELECT id,
    po_id,
    product_id,
    qty,
        CASE
            WHEN public.erp_can_view_cost() THEN unit_price
            ELSE NULL::numeric
        END AS unit_price,
    note,
    created_at,
        CASE
            WHEN public.erp_can_view_cost() THEN subtotal
            ELSE NULL::numeric
        END AS subtotal,
    unit,
    qty_received_total,
    resolution_type,
    resolution_qty,
    resolution_note,
    resolved_at,
    resolved_by
   FROM public.inv_po_items
  WHERE ((auth.role() = 'authenticated'::text) AND ((auth.role() = 'authenticated'::text) OR (EXISTS ( SELECT 1
           FROM public.us_users
          WHERE ((us_users.id = auth.uid()) AND (us_users.role = ANY (ARRAY['superadmin'::text, 'admin'::text, 'account'::text, 'manager'::text])))))) AND true);


--
-- Name: v_cost_safe_inv_pr_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cost_safe_inv_pr_items WITH (security_barrier='true') AS
 SELECT id,
    pr_id,
    product_id,
    qty,
    note,
    created_at,
        CASE
            WHEN public.erp_can_view_cost() THEN last_purchase_price
            ELSE NULL::numeric
        END AS last_purchase_price,
        CASE
            WHEN public.erp_can_view_cost() THEN estimated_price
            ELSE NULL::numeric
        END AS estimated_price,
    unit
   FROM public.inv_pr_items
  WHERE ((auth.role() = 'authenticated'::text) AND ((auth.role() = 'authenticated'::text) OR (EXISTS ( SELECT 1
           FROM public.us_users
          WHERE ((us_users.id = auth.uid()) AND (us_users.role = ANY (ARRAY['superadmin'::text, 'admin'::text, 'account'::text, 'manager'::text])))))) AND true);


--
-- Name: v_cost_safe_pr_products; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cost_safe_pr_products WITH (security_barrier='true') AS
 SELECT id,
    product_code,
    product_name,
    product_category,
    product_type,
    rubber_code,
    storage_location,
    is_active,
    created_at,
    updated_at,
    legacy_id,
    seller_name,
    product_name_cn,
    order_point,
        CASE
            WHEN public.erp_can_view_cost() THEN unit_cost
            ELSE NULL::numeric
        END AS unit_cost,
    safety_stock,
        CASE
            WHEN public.erp_can_view_cost() THEN landed_cost
            ELSE NULL::numeric
        END AS landed_cost,
    unit_name,
    unit_multiplier,
    order_point_days,
    is_hold,
    hold_reason,
    hold_at,
    hold_by,
    seller_name_cn,
    seller_purchase_channel,
    seller_type
   FROM public.pr_products
  WHERE ((auth.role() = 'authenticated'::text) AND ((EXISTS ( SELECT 1
           FROM public.us_users
          WHERE ((us_users.id = auth.uid()) AND (us_users.role = ANY (ARRAY['superadmin'::text, 'admin-tr'::text, 'admin-pump'::text]))))) OR ((auth.role() = 'authenticated'::text) AND (is_active = true))) AND true);


--
-- Name: v_product_last_price; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_product_last_price WITH (security_barrier='true') AS
 SELECT DISTINCT ON (poi.product_id) poi.product_id,
    poi.unit_price AS last_price,
    po.ordered_at AS last_ordered_at
   FROM (public.inv_po_items poi
     JOIN public.inv_po po ON ((po.id = poi.po_id)))
  WHERE ((po.status = ANY (ARRAY['ordered'::text, 'partial'::text, 'received'::text])) AND (poi.unit_price IS NOT NULL) AND public.erp_can_view_cost())
  ORDER BY poi.product_id, po.ordered_at DESC;


--
-- Name: vw_inventory_adjustment_reconcile; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_inventory_adjustment_reconcile AS
 SELECT ia.id AS adjustment_id,
    ia.adjust_no,
    ia.status,
    ia.adjustment_type,
    ia.created_at,
    ia.approved_at,
    iai.id AS adjustment_item_id,
    iai.product_id,
    p.product_code,
    p.product_name,
    iai.qty_delta,
    iai.new_safety_stock,
    iai.before_on_hand,
    iai.after_on_hand,
    iai.before_safety_stock,
    iai.after_safety_stock,
    iai.before_total_qty,
    iai.after_total_qty,
    sb.on_hand AS balance_on_hand,
    sb.safety_stock AS balance_safety_stock,
    (COALESCE(sb.on_hand, (0)::numeric) + COALESCE(sb.safety_stock, (0)::numeric)) AS balance_total_qty,
    COALESCE(ms.total_cost_impact, (0)::numeric) AS movement_total_cost_impact,
    COALESCE(ls.lot_qty_remaining, (0)::numeric) AS lot_qty_remaining,
    COALESCE(ls.lot_total_value, (0)::numeric) AS lot_total_value,
        CASE
            WHEN (ia.status = 'approved'::text) THEN (abs(((COALESCE(sb.on_hand, (0)::numeric) + COALESCE(sb.safety_stock, (0)::numeric)) - COALESCE(iai.after_total_qty, (COALESCE(iai.after_on_hand, (0)::numeric) + COALESCE(iai.after_safety_stock, (0)::numeric))))) < 0.0001)
            ELSE (abs(((COALESCE(iai.before_total_qty, (0)::numeric) + COALESCE(iai.qty_delta, (0)::numeric)) - COALESCE(iai.after_total_qty, (COALESCE(iai.after_on_hand, (0)::numeric) + COALESCE(iai.after_safety_stock, (0)::numeric))))) < 0.0001)
        END AS qty_consistent
   FROM (((((public.inv_adjustment_items iai
     JOIN public.inv_adjustments ia ON ((ia.id = iai.adjustment_id)))
     JOIN public.pr_products p ON ((p.id = iai.product_id)))
     LEFT JOIN public.inv_stock_balances sb ON ((sb.product_id = iai.product_id)))
     LEFT JOIN ( SELECT inv_stock_movements.ref_id,
            inv_stock_movements.product_id,
            sum(COALESCE(inv_stock_movements.total_cost, (0)::numeric)) AS total_cost_impact
           FROM public.inv_stock_movements
          WHERE (inv_stock_movements.ref_type = 'inv_adjustments'::text)
          GROUP BY inv_stock_movements.ref_id, inv_stock_movements.product_id) ms ON (((ms.ref_id = ia.id) AND (ms.product_id = iai.product_id))))
     LEFT JOIN ( SELECT inv_stock_lots.product_id,
            sum(COALESCE(inv_stock_lots.qty_remaining, (0)::numeric)) AS lot_qty_remaining,
            sum((COALESCE(inv_stock_lots.qty_remaining, (0)::numeric) * COALESCE(inv_stock_lots.unit_cost, (0)::numeric))) AS lot_total_value
           FROM public.inv_stock_lots
          GROUP BY inv_stock_lots.product_id) ls ON ((ls.product_id = iai.product_id)));


