    status_before_cancel text,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    CONSTRAINT wms_orders_fulfillment_mode_check CHECK (((fulfillment_mode IS NULL) OR (fulfillment_mode = ANY (ARRAY['warehouse_pick'::text, 'system_complete'::text, 'sub_warehouse_skip'::text])))),
    CONSTRAINT wms_orders_stock_action_check CHECK (((stock_action IS NULL) OR (stock_action = ANY (ARRAY['not_picked'::text, 'recalled'::text, 'waste'::text]))))
);


--
-- Name: COLUMN wms_orders.stock_action; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wms_orders.stock_action IS 'Cancellation stock result: not_picked=no stock impact, recalled=physical/ledger return, waste=not returned.';


--
-- Name: COLUMN wms_orders.fulfillment_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wms_orders.fulfillment_mode IS 'warehouse_pick=Picker คลังหลัก, system_complete=ตัดคลังหลักอัตโนมัติ, sub_warehouse_skip=ข้าม Picker และตัดสต๊อคหลักอัตโนมัติ';


--
-- Name: COLUMN wms_orders.source_order_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wms_orders.source_order_id IS 'บิล (or_orders) ที่รายการ WMS นี้ผูก';


--
-- Name: COLUMN wms_orders.plan_line_released; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wms_orders.plan_line_released IS 'true เมื่อบิลถูกย้ายออกจากใบงานแต่แถวค้างเพื่อคืนสต๊อก/แจ้งเตือน';


--
-- Name: COLUMN wms_orders.status_before_cancel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wms_orders.status_before_cancel IS 'WMS status immediately before cancellation; preserves whether stock was untouched, reserved or deducted.';


