--
-- Name: or_orders Production can update limited confirm statuses; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Production can update limited confirm statuses" ON public.or_orders FOR UPDATE TO authenticated USING (((EXISTS ( SELECT 1
   FROM public.us_users
  WHERE ((us_users.id = auth.uid()) AND (us_users.role = 'production'::text)))) AND (((channel_code = 'PUMP'::text) AND (status = ANY (ARRAY['ตรวจสอบแล้ว'::text, 'ไม่ต้องออกแบบ'::text, 'รอออกแบบ'::text, 'ออกแบบแล้ว'::text, 'รอคอนเฟิร์ม'::text, 'คอนเฟิร์มแล้ว'::text, 'เสร็จสิ้น'::text]))) OR ((COALESCE(channel_code, ''::text) IS DISTINCT FROM 'PUMP'::text) AND (COALESCE(requires_confirm_design, false) = true) AND (status = ANY (ARRAY['ตรวจสอบแล้ว'::text, 'ไม่ต้องออกแบบ'::text, 'รอออกแบบ'::text, 'ออกแบบแล้ว'::text, 'รอคอนเฟิร์ม'::text, 'คอนเฟิร์มแล้ว'::text, 'เสร็จสิ้น'::text])))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM public.us_users
  WHERE ((us_users.id = auth.uid()) AND (us_users.role = 'production'::text)))) AND (((channel_code = 'PUMP'::text) AND (status = ANY (ARRAY['ตรวจสอบแล้ว'::text, 'ไม่ต้องออกแบบ'::text, 'รอออกแบบ'::text, 'ออกแบบแล้ว'::text, 'รอคอนเฟิร์ม'::text, 'คอนเฟิร์มแล้ว'::text, 'เสร็จสิ้น'::text]))) OR ((COALESCE(channel_code, ''::text) IS DISTINCT FROM 'PUMP'::text) AND (COALESCE(requires_confirm_design, false) = true) AND (status = ANY (ARRAY['ตรวจสอบแล้ว'::text, 'ไม่ต้องออกแบบ'::text, 'รอออกแบบ'::text, 'ออกแบบแล้ว'::text, 'รอคอนเฟิร์ม'::text, 'คอนเฟิร์มแล้ว'::text, 'เสร็จสิ้น'::text]))))));


